-- CANDIDATE release file generated by Worker AF (H8) from the tested Stage 2 combined candidate.
-- NOT committed, NOT installed anywhere. Source pieces and hashes: h8/RELEASE_FORM_RESULT.json.
-- Probe/prototype identifiers renamed to production names per h8/tools/rename_map.json.
-- Policy X: no economic-key derivation, freshness or post-Draft behaviour change beyond the tested winners.
-- Repeatable CloudTMS function authority: banking_pay_stage2_workbench_draft_v1
-- Workbench/Draft corrections: A10 on-view Draft warning, A14 global readers, A15 dedupe keys, A16 narrow scope,
-- A17 section 1 head->dirty-ledger trigger function, A18 R25 publish_core, A20 Magnit expense heads (seed/track only;
-- the occurrence-page reader change lives in the reader-pair file), A21 manual-amount re-confirm, A23 Draft unblock,
-- A24 Source drift refusal (v2 helper), A26 Draft blockers, A27 Draft performance, A28 zero-pay/slicing,
-- A29 claim-scan call overhead, A30 H6 fixes (repayment reallocation, Client-filter certify, unfinished Drafts hidden).

\set ON_ERROR_STOP on

begin;

-- [NEW] private.pay_batch_source_head_drift_v1(p_pay_batch_id uuid)  winner piece A24
CREATE OR REPLACE FUNCTION private.pay_batch_source_head_drift_v1(p_pay_batch_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  /*
   * A24 (Worker AD, 26 Sep 2026); v2 (Worker AQ, 26 Sep 2026).  Stricter refusal only: never changes an amount, a
   * Draft, a reservation, settlement, pay state or any summary.  Policy X: the Draft side is read ONLY from frozen
   * batch artefacts (pay_batches.source_scope_change_generation frozen at V8 scope freeze and the freezing
   * operation's scope_frozen_at_utc; pay_batches.created_at_utc for a Draft without a frozen generation).  Live
   * Source currentness is comparison-only: which head is COMMITTED_CURRENT for each of the Draft's own root families,
   * the commit-time generation of the scope-change transaction that made it current while that row exists, and the
   * head's own immutable publication stamp.  No economic key, amount or identity is derived; no fallback identity.
   *
   * Frozen head identity: Draft items carry no head id.  The head that was current when the Draft froze is
   * exactly the head whose publication finalised at a generation <= the frozen generation (heads are
   * append-only revisions; every publication allocates a later global generation at commit).  So "current head
   * differs from the head at freeze" <=> "current head's publication generation > frozen generation".
   *
   * Proof ladder per family (fail closed when order cannot be proved):
   *   scope-change tx row present (unchanged from v1):
   *     TX_GENERATION        tx FINALIZED, Draft has frozen generation: drift iff gen > frozen.
   *     TX_COMMIT_TIME       tx FINALIZED, no frozen generation: drift iff finalized_at > Draft created_at.
   *     TX_NOT_FINALIZED     tx row present but not FINALIZED: drift (unprovable).
   *   tx row absent (pay_workbench_scope_reconcile_ensure_v1 deletes FINALIZED/NOOP rows finalised more than
   *   7 days before it runs, so an absent row proves the head's commit time C < now() - 7 days):
   *     CANDIDATE_GENERATION  head Candidate's scope counter <= frozen generation: no drift (v1).
   *     TX_RETENTION          Draft froze at or after now() - 7 days, so after C: no drift (v1).
   *     HEAD_COMMITTED_AFTER_FREEZE  head.committed_at_utc (stamped inside the publishing transaction, so <= C and
   *                           never rewritten: weekly_source_immutable_fact_guard) is later than the Draft's frozen
   *                           time: drift (proved; the tx-present rules would also have refused it).
   *     HEAD_BEFORE_FREEZE    the Draft froze at least PUBLICATION_WINDOW (10 minutes) after committed_at_utc: no
   *                           drift.  committed_at_utc is taken when the publication starts, before its commit; the
   *                           window must exceed the longest possible publication transaction.  Every application
   *                           publication route is one PostgREST RPC transaction, capped by the mandatory 120-second
   *                           connection-level statement_timeout, so 10 minutes is 5x that cap.
   *     UNPROVABLE_PUBLICATION_WINDOW  the Draft froze less than 10 minutes after committed_at_utc (the head could
   *                           still have been uncommitted): drift (fail closed).
   *     UNPROVABLE_AFTER_TX_RETENTION  no frozen time: drift (fail closed, as v1).
   * Coupling: the '7 days' below must stay <= the retention interval in pay_workbench_scope_reconcile_ensure_v1, and
   * the 10-minute publication window must stay above the longest Source publication transaction.
   */
  WITH batch AS (
    SELECT b.id, b.created_at_utc, b.source_scope_change_generation AS frozen_generation,
           CASE
             WHEN b.source_scope_change_generation IS NULL THEN b.created_at_utc
             ELSE (SELECT min(op.scope_frozen_at_utc)
                     FROM public.banking_pay_operations AS op
                    WHERE op.pay_batch_id = b.id
                      AND op.frozen_scope_change_generation = b.source_scope_change_generation)
           END AS frozen_at_utc
      FROM public.pay_batches AS b
     WHERE b.id = p_pay_batch_id
  ), draft_family AS (
    SELECT DISTINCT pg_catalog.btrim(t.booking_id) AS family_booking_id
      FROM batch
      JOIN public.pay_batch_candidates AS c ON c.pay_batch_id = batch.id
      JOIN public.pay_batch_items AS i ON i.pay_batch_candidate_id = c.id
      JOIN public.timesheets AS t ON t.timesheet_id = i.timesheet_id
     WHERE COALESCE(i.is_voided, false) IS NOT TRUE
       AND NULLIF(pg_catalog.btrim(COALESCE(t.booking_id, '')), '') IS NOT NULL
  ), judged AS (
    SELECT h.root_family_booking_id, h.root_timesheet_id, h.candidate_id, h.id AS head_id, h.head_revision,
           pg_catalog.encode(h.entitlement_digest, 'hex') AS entitlement_digest,
           h.committed_at_utc AS head_committed_at_utc,
           tx.tx_token IS NOT NULL AS tx_present, tx.state AS tx_state, tx.allocated_generation, tx.finalized_at_utc,
           counter.scope_change_generation AS candidate_generation,
           batch.frozen_generation, batch.frozen_at_utc, batch.created_at_utc AS draft_created_at_utc,
           CASE
             WHEN tx.tx_token IS NOT NULL AND tx.state IS DISTINCT FROM 'FINALIZED' THEN 'TX_NOT_FINALIZED'
             WHEN tx.tx_token IS NOT NULL AND batch.frozen_generation IS NOT NULL THEN
               CASE WHEN tx.allocated_generation IS NULL OR tx.allocated_generation > batch.frozen_generation
                    THEN 'TX_GENERATION' END
             WHEN tx.tx_token IS NOT NULL THEN
               CASE WHEN tx.finalized_at_utc IS NULL OR tx.finalized_at_utc > batch.created_at_utc
                    THEN 'TX_COMMIT_TIME' END
             WHEN batch.frozen_generation IS NOT NULL
              AND counter.scope_change_generation IS NOT NULL
              AND counter.scope_change_generation <= batch.frozen_generation THEN NULL
             WHEN batch.frozen_at_utc IS NOT NULL
              AND batch.frozen_at_utc >= pg_catalog.now() - pg_catalog.make_interval(days => 7) THEN NULL
             WHEN batch.frozen_at_utc IS NULL OR h.committed_at_utc IS NULL THEN 'UNPROVABLE_AFTER_TX_RETENTION'
             WHEN h.committed_at_utc > batch.frozen_at_utc THEN 'HEAD_COMMITTED_AFTER_FREEZE'
             WHEN batch.frozen_at_utc >= h.committed_at_utc + pg_catalog.make_interval(mins => 10) THEN NULL
             ELSE 'UNPROVABLE_PUBLICATION_WINDOW'
           END AS drift_basis
      FROM batch
      JOIN draft_family AS f ON true
      JOIN public.weekly_source_entitlement_heads AS h
        ON pg_catalog.btrim(h.root_family_booking_id) = f.family_booking_id
       AND h.state = 'COMMITTED_CURRENT'
      LEFT JOIN public.banking_pay_scope_change_transactions AS tx ON tx.tx_token = h.scope_change_tx_token
      LEFT JOIN public.app_change_counters AS counter
        ON counter.entity_key = 'pay_candidate:' || h.candidate_id::text
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
           'key_type', 'SOURCE_ENTITLEMENT_HEAD',
           'key_value', j.root_family_booking_id,
           'timesheet_id', j.root_timesheet_id,
           'candidate_id', j.candidate_id,
           'reason', 'SOURCE_ENTITLEMENT_HEAD_CHANGED',
           'basis', j.drift_basis,
           'expected', pg_catalog.jsonb_build_object(
             'draft_frozen_generation', j.frozen_generation,
             'draft_frozen_at_utc', j.frozen_at_utc,
             'draft_created_at_utc', j.draft_created_at_utc),
           'actual', pg_catalog.jsonb_build_object(
             'head_id', j.head_id, 'head_revision', j.head_revision,
             'entitlement_digest', j.entitlement_digest,
             'publication_tx_present', j.tx_present,
             'publication_tx_state', j.tx_state,
             'publication_generation', j.allocated_generation,
             'publication_finalized_at_utc', j.finalized_at_utc)
             || CASE WHEN j.tx_present THEN '{}'::jsonb
                     ELSE pg_catalog.jsonb_build_object('head_committed_at_utc', j.head_committed_at_utc) END)
         ORDER BY j.root_family_booking_id), '[]'::jsonb)
    FROM judged AS j
   WHERE j.drift_basis IS NOT NULL;
$function$;

-- [NEW] private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id uuid)  winner piece A30
CREATE OR REPLACE FUNCTION private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  -- A30 (PRE-EXISTING fix, H6 M3). True while the batch belongs to a V8 certified Draft operation
  -- (banking_pay_draft_certified_operation_start_v8 records workbench_settled_certificate_reference_v8 in input_json)
  -- that has not reached a terminal status. pay_batch_shell_ensure_from_operation creates the DRAFT shell and stamps
  -- the operation's candidate scope rows with its id in the same statement, so the link exists from the shell's birth.
  -- Terminal non-COMPLETE operations are owned by the broker's existing failure cleanup (finishFailedWithCleanup);
  -- historical and non-V8 batches never match.
  SELECT p_pay_batch_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    JOIN public.banking_pay_operations AS operation_row
      ON operation_row.id = scope_row.operation_id
    WHERE scope_row.pay_batch_id = p_pay_batch_id
      AND operation_row.operation_type = 'DRAFT_CREATE'
      AND operation_row.status <> ALL (ARRAY['COMPLETE','FAILED','CANCELLED','CANCELED','REVIEW_REQUIRED']::text[])
      AND operation_row.input_json ? 'workbench_settled_certificate_reference_v8'
  );
$function$;

-- [NEW] private.weekly_source_entitlement_head_ledger_mark_v1()  winner piece A17_S1
CREATE OR REPLACE FUNCTION private.weekly_source_entitlement_head_ledger_mark_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_anchor_bundle uuid;
  v_anchor_revision bigint;
  v_scope uuid[];
  v_token_text text;
  v_token uuid;
  v_result jsonb;
BEGIN
  -- Only a change of currentness is a ledger event: INSERT directly as COMMITTED_CURRENT, or an UPDATE whose
  -- state moves into or out of COMMITTED_CURRENT. STAGED inserts/updates and non-state updates return at once.
  IF TG_OP='INSERT' THEN
    IF NEW.state IS DISTINCT FROM 'COMMITTED_CURRENT' THEN RETURN NULL; END IF;
  ELSIF OLD.state IS NOT DISTINCT FROM NEW.state
     OR (OLD.state IS DISTINCT FROM 'COMMITTED_CURRENT' AND NEW.state IS DISTINCT FROM 'COMMITTED_CURRENT') THEN
    RETURN NULL;
  END IF;

  -- The publication this change belongs to.
  IF NEW.state='COMMITTED_CURRENT' THEN
    v_anchor_bundle:=NEW.decision_bundle_id; v_anchor_revision:=NEW.bundle_revision;
  ELSIF NEW.superseded_by_head_id IS NOT NULL THEN
    SELECT successor.decision_bundle_id,successor.bundle_revision
      INTO v_anchor_bundle,v_anchor_revision
      FROM public.weekly_source_entitlement_heads AS successor
     WHERE successor.id=NEW.superseded_by_head_id;
  END IF;

  SELECT COALESCE(pg_catalog.array_agg(DISTINCT root_id ORDER BY root_id),ARRAY[]::uuid[])
    INTO v_scope
    FROM (
      SELECT NEW.root_timesheet_id AS root_id
      UNION
      SELECT sibling.root_timesheet_id
        FROM public.weekly_source_entitlement_heads AS sibling
       WHERE v_anchor_bundle IS NOT NULL
         AND sibling.decision_bundle_id=v_anchor_bundle
         AND sibling.bundle_revision=v_anchor_revision
         AND sibling.candidate_id=NEW.candidate_id
         AND sibling.state IN ('STAGED','COMMITTED_CURRENT')
    ) AS scope_root;

  -- Exactly once per transaction scope: already marked under this transaction's token -> no write at all.
  v_token_text:=NULLIF(pg_catalog.btrim(COALESCE(
    pg_catalog.current_setting('cloudtms.banking_pay_scope_tx_token',true),'')),'');
  IF v_token_text IS NOT NULL
     AND v_token_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_token:=v_token_text::uuid;
    IF EXISTS (
         SELECT 1
           FROM public.banking_pay_workbench_jobs AS job_row
          WHERE job_row.candidate_id=NEW.candidate_id
            AND job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
            AND job_row.status IN ('QUEUED','RUNNING')
            AND job_row.scope_change_tx_token=v_token
            AND NOT EXISTS (
              SELECT scope_id::text FROM pg_catalog.unnest(v_scope) AS wanted(scope_id)
              EXCEPT
              SELECT covered.value
                FROM pg_catalog.jsonb_array_elements_text(
                       CASE WHEN pg_catalog.jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids')='array'
                            THEN job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END) AS covered(value)))
       AND NOT EXISTS (
         SELECT 1
           FROM pg_catalog.unnest(v_scope) AS wanted(scope_id)
           LEFT JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
             ON scope_state.timesheet_id=wanted.scope_id
          WHERE scope_state.timesheet_id IS NULL
             OR scope_state.candidate_id IS DISTINCT FROM NEW.candidate_id
             OR scope_state.economic_state IS DISTINCT FROM 'DIRTY'
             OR scope_state.last_scope_change_tx_token IS DISTINCT FROM v_token) THEN
      RETURN NULL;
    END IF;
  END IF;

  v_result:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>pg_catalog.array_fill(NEW.candidate_id,ARRAY[pg_catalog.cardinality(v_scope)]),
    p_timesheet_ids=>v_scope,
    p_reason=>'WEEKLY_SOURCE_ENTITLEMENT_HEAD_CURRENTNESS_CHANGED',
    p_scope_change_tx_token=>NULL::uuid,   -- the invalidator takes the transaction's one token
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_entitlement_head_change',pg_catalog.jsonb_build_object(
        'head_id',NEW.id,'head_revision',NEW.head_revision,
        'state_before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.state END,
        'state_after',NEW.state,
        'decision_bundle_id',NEW.decision_bundle_id,'bundle_revision',NEW.bundle_revision,
        'superseded_by_head_id',NEW.superseded_by_head_id,
        'superseded_by_withdrawal_id',NEW.superseded_by_withdrawal_id)));

  IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
     OR (v_result->>'candidate_count')::integer IS DISTINCT FROM 1
     OR COALESCE((v_result->>'job_inserted_count')::integer,0)
        +COALESCE((v_result->>'job_coalesced_count')::integer,0)<1 THEN
    RAISE EXCEPTION 'WEEKLY_SOURCE_HEAD_LEDGER_MARK_FAILED'
      USING ERRCODE='55000',
            DETAIL=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_HEAD_LEDGER_MARK_FAILED','head_id',NEW.id,'invalidation',v_result)::text;
  END IF;
  RETURN NULL;
END;
$function$;

-- [NEW] public._pay_batch_draft_stale_hint_on_view_v1(p_pay_batch_id uuid, p_page_timesheet_count integer, p_budget_ms integer)  winner piece A24
CREATE OR REPLACE FUNCTION public._pay_batch_draft_stale_hint_on_view_v1(p_pay_batch_id uuid, p_page_timesheet_count integer DEFAULT 200, p_budget_ms integer DEFAULT 1500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
/*
 * G-A3 (25 Sep 2026 user ruling): the "changed since this Draft was created"
 * warning is computed when the Draft is opened, not when a Source/Timesheet
 * write happens.  This is a DISPLAY HINT ONLY
 * (policy_x_authority_scope = FROZEN_DRAFT_INVALIDATION_HINT_ONLY).
 *
 * Policy X: the Draft side is read only from frozen batch artifacts
 * (_pay_batch_item_economic_components over this Draft's own item ids).  Live
 * truth is comparison-only, through the same helpers and the same formula as
 * the RESERVATION_CHANGED section of _pay_batch_validate_freshness_base_v1.
 * Nothing is recalculated, no frozen amount is written, no freshness status or
 * freshness hash is written.  The mandatory execution freshness checks are
 * unchanged and remain the only safeguard.
 *
 * Bounded by the Draft's own frozen items: pages of the Draft's own delta-item
 * Timesheets (p_page_timesheet_count per page, keyset by timesheet id), early
 * exit on the first stale page, and a wall-clock budget.  No family-history,
 * Candidate-history or population enumeration is performed here.
 *
 * The result is written through banking_pay_batch_signal_touch into the same
 * last_change_scope_json fields the list already reads (stale_hint,
 * stale_reason, policy_x_authority_scope), only on the fresh -> stale
 * transition, so repeated opens do not bump signal versions.
 */
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_status text;
  v_created_at_utc timestamptz;
  v_page_size integer := LEAST(500, GREATEST(1, COALESCE(p_page_timesheet_count, 200)));
  v_budget_ms integer := LEAST(10000, GREATEST(50, COALESCE(p_budget_ms, 1500)));
  v_cursor uuid := NULL::uuid;
  v_page_ts uuid[] := ARRAY[]::uuid[];
  v_page_items uuid[] := ARRAY[]::uuid[];
  v_page_ts_count integer := 0;
  v_pages integer := 0;
  v_items_checked integer := 0;
  v_timesheets_checked integer := 0;
  v_page_diff_count integer := 0;
  v_diff_count integer := 0;
  v_page_stale_ts uuid[] := ARRAY[]::uuid[];
  v_page_stale_candidates uuid[] := ARRAY[]::uuid[];
  v_stale_ts uuid[] := ARRAY[]::uuid[];
  v_stale_candidates uuid[] := ARRAY[]::uuid[];
  v_method_candidates uuid[] := ARRAY[]::uuid[];
  v_complete boolean := false;
  v_budget_exhausted boolean := false;
  v_stale boolean := false;
  v_reason text := NULL::text;
  v_existing_scope jsonb := NULL::jsonb;
  v_already_hinted boolean := false;
  v_touched boolean := false;
  v_touch_result jsonb := '{}'::jsonb;
  v_source_head_drift jsonb := '[]'::jsonb;  -- A24
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'checked', false, 'code', 'PAY_BATCH_ID_REQUIRED');
  END IF;

  SELECT upper(btrim(coalesce(pb.status, ''))), pb.created_at_utc
  INTO v_status, v_created_at_utc
  FROM public.pay_batches AS pb
  WHERE pb.id = p_pay_batch_id;

  IF v_status IS DISTINCT FROM 'DRAFT' THEN
    RETURN jsonb_build_object('ok', true, 'checked', false, 'code', 'NOT_DRAFT', 'batch_status', v_status);
  END IF;

  -- The hint is sticky (as before: once shown it is never cleared by a later
  -- write).  A Draft already carrying it needs no further work on open.
  SELECT signal_row.last_change_scope_json
  INTO v_existing_scope
  FROM public.banking_pay_batch_change_signals AS signal_row
  WHERE signal_row.pay_batch_id = p_pay_batch_id;

  IF lower(btrim(coalesce(v_existing_scope->>'stale_hint', 'false'))) IN ('true','t','1','yes','y','on') THEN
    RETURN jsonb_build_object(
      'ok', true, 'checked', false, 'code', 'ALREADY_HINTED', 'stale', true,
      'stale_reason', v_existing_scope->>'stale_reason',
      'elapsed_ms', round((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 1),
      'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
    );
  END IF;

  ---------------------------------------------------------------------------
  -- 1. Timesheet / TSFIN source change: frozen item components vs live truth.
  ---------------------------------------------------------------------------
  LOOP
    SELECT coalesce(array_agg(page_ts.timesheet_id ORDER BY page_ts.timesheet_id), ARRAY[]::uuid[])
    INTO v_page_ts
    FROM (
      SELECT DISTINCT own_item.timesheet_id
      FROM public.pay_batch_candidates AS own_candidate
      JOIN public.pay_batch_items AS own_item
        ON own_item.pay_batch_candidate_id = own_candidate.id
      WHERE own_candidate.pay_batch_id = p_pay_batch_id
        AND coalesce(own_item.is_voided, false) = false
        AND own_item.timesheet_id IS NOT NULL
        AND upper(nullif(btrim(coalesce(own_item.item_type, '')), '')) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
        AND (v_cursor IS NULL OR own_item.timesheet_id > v_cursor)
      ORDER BY own_item.timesheet_id
      LIMIT v_page_size
    ) AS page_ts;

    v_page_ts_count := coalesce(array_length(v_page_ts, 1), 0);
    IF v_page_ts_count = 0 THEN
      v_complete := true;
      EXIT;
    END IF;
    v_pages := v_pages + 1;
    v_cursor := v_page_ts[v_page_ts_count];

    -- The page's own items.  A Timesheet carrying a correction-chain residual
    -- item is left to the mandatory freshness wrapper (which reconstructs the
    -- residual); the hint never guesses about it.
    SELECT coalesce(array_agg(own_item.id ORDER BY own_item.id), ARRAY[]::uuid[])
    INTO v_page_items
    FROM public.pay_batch_candidates AS own_candidate
    JOIN public.pay_batch_items AS own_item
      ON own_item.pay_batch_candidate_id = own_candidate.id
    WHERE own_candidate.pay_batch_id = p_pay_batch_id
      AND own_item.timesheet_id = ANY(v_page_ts)
      AND coalesce(own_item.is_voided, false) = false
      AND upper(nullif(btrim(coalesce(own_item.item_type, '')), '')) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS own_correction_exclusion
        WHERE own_correction_exclusion.pay_batch_item_id = own_item.id
          AND own_correction_exclusion.status = 'APPLIED'
          AND own_correction_exclusion.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS chain_item
        WHERE chain_item.pay_batch_candidate_id IN (
                SELECT chain_candidate.id FROM public.pay_batch_candidates AS chain_candidate
                WHERE chain_candidate.pay_batch_id = p_pay_batch_id)
          AND chain_item.timesheet_id = own_item.timesheet_id
          AND coalesce(chain_item.is_voided, false) = false
          AND (
            nullif(coalesce(chain_item.frozen_source_basis_json #>> '{correction_chain_residual,root_timesheet_id}',
                            chain_item.frozen_component_snapshot_json #>> '{correction_chain_residual,root_timesheet_id}', ''), '') IS NOT NULL
            OR coalesce(chain_item.frozen_source_basis_json->>'source_family_key',
                        chain_item.frozen_component_snapshot_json->>'source_family_key', '') ~ '^correction-chain:'
          )
      );

    IF coalesce(array_length(v_page_items, 1), 0) > 0 THEN
      v_items_checked := v_items_checked + array_length(v_page_items, 1);
      v_timesheets_checked := v_timesheets_checked + v_page_ts_count;

      -- Same comparison as _pay_batch_validate_freshness_base_v1
      -- RESERVATION_CHANGED, restricted to this page of the Draft's own items.
      WITH
      this_components_raw AS (
        SELECT
          pbec.pay_batch_item_id,
          pbec.timesheet_id,
          own_candidate.candidate_id,
          upper(nullif(btrim(coalesce(pbec.key_type, '')), '')) AS key_type,
          nullif(btrim(coalesce(pbec.key_value, '')), '') AS key_value,
          pbec.source_amount_ex_vat AS source_amount_ex_vat_raw,
          nullif(btrim(coalesce(pbec.key_resolution_failure_reason, '')), '') AS key_resolution_failure_reason
        FROM public._pay_batch_item_economic_components(
          p_pay_batch_id => p_pay_batch_id,
          p_pay_batch_item_ids => v_page_items
        ) AS pbec
        JOIN public.pay_batch_items AS own_item
          ON own_item.id = pbec.pay_batch_item_id
        JOIN public.pay_batch_candidates AS own_candidate
          ON own_candidate.id = own_item.pay_batch_candidate_id
        WHERE upper(nullif(btrim(coalesce(pbec.item_type, '')), '')) IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
      ),
      this_component_resolution_failures AS (
        SELECT tcr.timesheet_id, tcr.candidate_id
        FROM this_components_raw AS tcr
        WHERE tcr.key_resolution_failure_reason IS NOT NULL
           OR tcr.key_type IS NULL
           OR tcr.key_value IS NULL
           OR tcr.key_type NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
           OR (tcr.key_type = 'TS_DAY' AND tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
           OR tcr.source_amount_ex_vat_raw IS NULL
      ),
      this_components AS (
        SELECT
          tcr.timesheet_id,
          tcr.key_type,
          tcr.key_value,
          (array_agg(tcr.candidate_id ORDER BY tcr.candidate_id))[1] AS candidate_id,
          round(sum(round(coalesce(tcr.source_amount_ex_vat_raw, 0), 2)), 2)::numeric(12,2) AS current_source_ex_vat
        FROM this_components_raw AS tcr
        WHERE tcr.timesheet_id IS NOT NULL
          AND tcr.key_type IS NOT NULL
          AND tcr.key_value IS NOT NULL
          AND tcr.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
          AND NOT (tcr.key_type = 'TS_DAY' AND tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
          AND tcr.key_resolution_failure_reason IS NULL
          AND tcr.source_amount_ex_vat_raw IS NOT NULL
        GROUP BY tcr.timesheet_id, tcr.key_type, tcr.key_value
      ),
      current_truth_baseline AS (
        SELECT
          ctec.timesheet_id,
          upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) AS key_type,
          nullif(btrim(coalesce(ctec.key_value, '')), '') AS key_value,
          round(sum(coalesce(ctec.truth_ex_vat, 0)), 2)::numeric(12,2) AS truth_ex_vat,
          round(sum(coalesce(ctec.baseline_ex_vat, 0)), 2)::numeric(12,2) AS baseline_ex_vat
        FROM public._pay_current_timesheet_entitlement_components(v_page_ts) AS ctec
        WHERE ctec.timesheet_id IS NOT NULL
          AND nullif(btrim(coalesce(ctec.key_type, '')), '') IS NOT NULL
          AND nullif(btrim(coalesce(ctec.key_value, '')), '') IS NOT NULL
        GROUP BY
          ctec.timesheet_id,
          upper(nullif(btrim(coalesce(ctec.key_type, '')), '')),
          nullif(btrim(coalesce(ctec.key_value, '')), '')
      ),
      all_reserved AS (
        SELECT
          rc.timesheet_id,
          upper(nullif(btrim(coalesce(rc.key_type, '')), '')) AS key_type,
          nullif(btrim(coalesce(rc.key_value, '')), '') AS key_value,
          round(sum(coalesce(rc.amount_ex_vat, 0)), 2)::numeric(12,2) AS all_reserved_ex_vat
        FROM public._pay_reserved_components(v_page_ts) AS rc
        WHERE rc.timesheet_id IS NOT NULL
          AND nullif(btrim(coalesce(rc.key_type, '')), '') IS NOT NULL
          AND nullif(btrim(coalesce(rc.key_value, '')), '') IS NOT NULL
        GROUP BY
          rc.timesheet_id,
          upper(nullif(btrim(coalesce(rc.key_type, '')), '')),
          nullif(btrim(coalesce(rc.key_value, '')), '')
      ),
      reservation_mismatches AS (
        SELECT tc.timesheet_id, tc.candidate_id
        FROM this_components AS tc
        LEFT JOIN current_truth_baseline AS ctb
          ON ctb.timesheet_id = tc.timesheet_id
         AND ctb.key_type = tc.key_type
         AND ctb.key_value = tc.key_value
        LEFT JOIN all_reserved AS ar
          ON ar.timesheet_id = tc.timesheet_id
         AND ar.key_type = tc.key_type
         AND ar.key_value = tc.key_value
        WHERE abs(
                round(
                  coalesce(ctb.truth_ex_vat, 0)
                  - coalesce(ctb.baseline_ex_vat, 0)
                  - (coalesce(ar.all_reserved_ex_vat, 0) - coalesce(tc.current_source_ex_vat, 0)),
                  2
                )
                - round(coalesce(tc.current_source_ex_vat, 0), 2)
              ) > 0.01
      ),
      page_diffs AS (
        SELECT timesheet_id, candidate_id FROM this_component_resolution_failures
        UNION ALL
        SELECT timesheet_id, candidate_id FROM reservation_mismatches
      )
      SELECT
        count(*)::integer,
        coalesce(array_agg(DISTINCT page_diffs.timesheet_id) FILTER (WHERE page_diffs.timesheet_id IS NOT NULL), ARRAY[]::uuid[]),
        coalesce(array_agg(DISTINCT page_diffs.candidate_id) FILTER (WHERE page_diffs.candidate_id IS NOT NULL), ARRAY[]::uuid[])
      INTO v_page_diff_count, v_page_stale_ts, v_page_stale_candidates
      FROM page_diffs;

      IF v_page_diff_count > 0 THEN
        v_stale := true;
        v_diff_count := v_diff_count + v_page_diff_count;
        v_stale_ts := v_page_stale_ts;
        v_stale_candidates := v_page_stale_candidates;
        v_reason := 'TIMESHEET_MATERIAL_LIVE_SOURCE_CHANGED';
        EXIT;
      END IF;
    END IF;

    IF v_page_ts_count < v_page_size THEN
      v_complete := true;
      EXIT;
    END IF;

    IF (EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000) > v_budget_ms THEN
      v_budget_exhausted := true;
      EXIT;
    END IF;
  END LOOP;

  ---------------------------------------------------------------------------
  -- 2. Candidate PAYE <-> UMBRELLA route change: the Draft's own Candidates'
  --    current method vs the pay channel frozen on their own non-mismatch items.
  ---------------------------------------------------------------------------
  IF v_stale IS NOT TRUE THEN
    SELECT coalesce(array_agg(DISTINCT own_candidate.candidate_id ORDER BY own_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_method_candidates
    FROM public.pay_batch_candidates AS own_candidate
    JOIN public.candidates AS candidate_row
      ON candidate_row.id = own_candidate.candidate_id
    WHERE own_candidate.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(candidate_row.pay_method, ''))) IN ('PAYE','UMBRELLA')
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_items AS own_item
        WHERE own_item.pay_batch_candidate_id = own_candidate.id
          AND coalesce(own_item.is_voided, false) = false
          AND coalesce(own_item.is_mismatch, false) = false
          AND upper(btrim(coalesce(own_item.pay_channel, ''))) IN ('PAYE','UMBRELLA')
          AND upper(btrim(coalesce(own_item.pay_channel, ''))) <> upper(btrim(candidate_row.pay_method))
      );
    IF coalesce(array_length(v_method_candidates, 1), 0) > 0 THEN
      v_stale := true;
      v_stale_candidates := v_method_candidates;
      v_reason := 'CANDIDATE_PAY_METHOD_CHANGED';
    END IF;
  END IF;

  ---------------------------------------------------------------------------
  -- 2b. A24: Source entitlement head made current after this Draft froze.
  --     Comparison-only helper over the Draft's own root families.
  ---------------------------------------------------------------------------
  IF v_stale IS NOT TRUE THEN
    v_source_head_drift := private.pay_batch_source_head_drift_v1(p_pay_batch_id);
    IF jsonb_array_length(v_source_head_drift) > 0 THEN
      v_stale := true;
      v_reason := 'SOURCE_ENTITLEMENT_HEAD_CHANGED';
      SELECT coalesce(array_agg(DISTINCT (drift_row.value->>'timesheet_id')::uuid), ARRAY[]::uuid[]),
             coalesce(array_agg(DISTINCT (drift_row.value->>'candidate_id')::uuid), ARRAY[]::uuid[])
      INTO v_stale_ts, v_stale_candidates
      FROM jsonb_array_elements(v_source_head_drift) AS drift_row(value);
      v_diff_count := v_diff_count + jsonb_array_length(v_source_head_drift);
    END IF;
  END IF;

  ---------------------------------------------------------------------------
  -- 3. Surface it through the fields the list already reads, once.
  ---------------------------------------------------------------------------
  IF v_stale THEN
    SELECT signal_row.last_change_scope_json
    INTO v_existing_scope
    FROM public.banking_pay_batch_change_signals AS signal_row
    WHERE signal_row.pay_batch_id = p_pay_batch_id;

    v_already_hinted := lower(btrim(coalesce(v_existing_scope->>'stale_hint', 'false'))) IN ('true','t','1','yes','y','on');

    IF v_already_hinted IS NOT TRUE THEN
      v_touch_result := public.banking_pay_batch_signal_touch(
        p_pay_batch_id => p_pay_batch_id,
        p_change_reason => v_reason,
        p_change_source => '_pay_batch_draft_stale_hint_on_view_v1',
        p_change_scope_json => jsonb_build_object(
          'stale_hint', true,
          'stale_reason', v_reason,
          'candidate_ids', to_jsonb(v_stale_candidates[1:50]),
          'timesheet_ids', to_jsonb(v_stale_ts[1:50]),
          'detection', 'ON_VIEW_FROZEN_ITEM_CHECK',
          'draft_created_at_utc', v_created_at_utc,
          'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
        ),
        p_touch_payment_status => false,
        p_touch_correction_progress => false,
        p_touch_alerts => true,
        p_touch_overview => true
      );
      v_touched := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'checked', true,
    'stale', v_stale,
    'stale_reason', v_reason,
    'complete', (v_complete OR v_stale),
    'budget_exhausted', v_budget_exhausted,
    'pages', v_pages,
    'timesheets_checked', v_timesheets_checked,
    'items_checked', v_items_checked,
    'diff_count', v_diff_count,
    'already_hinted', v_already_hinted,
    'signal_touched', v_touched,
    'elapsed_ms', round((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 1),
    'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
  );
END;
$function$
;

-- [REPLACES] private.pay_sync_overpayments_from_workbench_workspace_v1(p_build_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_nonce uuid, p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb, p_client_filter_single uuid, p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[])  winner piece A28
CREATE OR REPLACE FUNCTION private.pay_sync_overpayments_from_workbench_workspace_v1(p_build_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_nonce uuid, p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid, p_pay_channel_scope text, p_candidate_ids uuid[], p_mismatch_choices jsonb DEFAULT '{}'::jsonb, p_client_filter_single uuid DEFAULT NULL::uuid, p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_bounded_build private.banking_pay_workbench_economic_builds%rowtype;
  v_bounded_job public.banking_pay_workbench_jobs%rowtype;
  v_bounded_attempt private.banking_pay_workbench_stage_attempts%rowtype;
  v_bounded_registry private.banking_pay_workbench_candidate_scope_registry%rowtype;
  v_bounded_scope_ids uuid[] := array[]::uuid[];
  v_bounded_scope_count integer := 0;
  v_bounded_fact_count bigint := 0;
  v_bounded_pre_sync_digest text;
  v_bounded_post_sync_digest text;
  v_bounded_canonical_digest text;
  v_bounded_economic_component_digest text;
  v_bounded_presentation_allocation_digest text;
  v_bounded_canonical_count integer := 0;
  v_bounded_canonical_stage_timestamp timestamptz;
  v_bounded_canonical_result jsonb := '{}'::jsonb;
  v_public_result_json jsonb := '{}'::jsonb;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_case_update_count int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;
  v_preview_decisions_json jsonb := '{}'::jsonb;
  v_preview_context_json jsonb := '{}'::jsonb;
  v_preview_baseline_json jsonb := '{}'::jsonb;
  v_preview_collect_result_json jsonb := '{}'::jsonb;
  v_preview_canonical_result_json jsonb := '{}'::jsonb;
  v_preview_candidate_row_json jsonb := '{}'::jsonb;
  v_preview_scope_context_json jsonb := '{}'::jsonb;
  v_preview_scope_candidate_ids_json jsonb := '[]'::jsonb;
  v_preview_candidate_loop_id uuid := NULL::uuid;
  v_preview_candidate_count integer := 0;
  v_requested_candidate_count integer := 0;
  v_missing_candidate_count integer := 0;
  v_missing_candidate_ids_json jsonb := '[]'::jsonb;
  v_authoritative_timesheet_scope_requested boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_explicit_empty_timesheet_scope boolean := false;
  v_preview_scope_strategy text := 'CANDIDATE_FULL_LIVE';
  v_sync_authority_token text := NULL::text;
  v_current_sync_authority_token text := NULL::text;
  v_workbench_session_id_text text := NULL::text;
  v_source_build_run_id_text text := NULL::text;
  v_session_version_text text := NULL::text;
  v_workbench_session_id uuid := NULL::uuid;
  v_source_build_run_id uuid := NULL::uuid;
  v_workbench_session_version bigint := NULL::bigint;
  v_authoritative_candidate_id uuid := NULL::uuid;
  v_existing_active_reserved_amount numeric(12,2) := 0;
  v_effective_case_amount_ex numeric(12,2);
  v_active_reservation_protection_applied boolean := false;
  v_correction_rewrite_result jsonb := '{}'::jsonb;
  v_resolution_pending_member_ids uuid[] := array[]::uuid[];
  v_resolution_pending_root_ids uuid[] := array[]::uuid[];

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_component_case_outstanding_amount numeric(12,2) := 0;
  v_component_open_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_target_amount_is_authoritative_outstanding boolean := false;
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
  v_authoritative_negative_component_count integer := 0;
  v_authoritative_negative_component_digest text := NULL::text;
  v_expected_negative_component_digest text := NULL::text;
  v_authoritative_settled_baseline_digest text := NULL::text;
  v_expected_settled_baseline_digest text := NULL::text;
  v_authoritative_session_valid boolean := false;
  v_observed_effect_count integer := 0;
  v_observed_effect_digest text := md5('');
  v_effect_mismatch_detail jsonb := '{}'::jsonb;
  v_presentation_mismatch_detail jsonb := '{}'::jsonb;
  v_rate_authority_failure_code text := NULL::text;
  v_rate_authority_failure_detail jsonb := '[]'::jsonb;
  v_exception_detail text := NULL::text;
  v_exception_context text := NULL::text;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
  v_captured_effects jsonb := '[]'::jsonb;
  v_execution_profile_version integer := CASE
    WHEN COALESCE(current_setting('cloudtms.pay_workbench_execution_profile_version', true), '') ~ '^[12]$'
      THEN current_setting('cloudtms.pay_workbench_execution_profile_version', true)::integer
    ELSE 1
  END;
  v_reconciliation_optimization_version integer := 0;
  v_reconcile_started_at timestamptz := clock_timestamp();
  v_freshness_set_ms integer := 0;
  v_workspace_cache_ms integer := 0;
  v_authoritative_components_ms integer := 0;
  v_preflight_setup_ms integer := 0;
  v_correction_residuals_ms integer := 0;
  v_authority_validation_ms integer := 0;
  v_component_assembly_ms integer := 0;
  v_preview_workspace_ms integer := 0;
  v_preview_collect_ms integer := 0;
  v_preview_canonical_ms integer := 0;
  v_preview_summary_ms integer := 0;
  v_case_workspace_ms integer := 0;
  v_finance_apply_ms integer := 0;
  v_post_freshness_ms integer := 0;
  v_canonical_render_ms integer := 0;
  v_canonical_stage_ms integer := 0;
  v_phase_started_at timestamptz := clock_timestamp();
  -- A28 reconciliation slicing
  v_slice jsonb := NULL::jsonb;
  v_slice_active boolean := false;
  v_slice_final boolean := false;
  v_slice_plan jsonb := NULL::jsonb;
  v_slice_ordinal_base bigint := 0;
  v_slice_max_ordinal bigint := 0;
  v_slice_kept integer := 0;
  v_slice_dropped_candidate_level integer := 0;
  v_slice_dropped_other_slice integer := 0;
  v_slice_recovery_headroom numeric := 0;
  v_slice_ordinary_headroom numeric := 0;
  v_slice_total_scope_count integer := 0;
  v_slice_line_total integer := 0;
begin
  SELECT * INTO v_bounded_registry
  FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE current_build_id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_build
  FROM private.banking_pay_workbench_economic_builds
  WHERE id=p_build_id FOR UPDATE;
  SELECT * INTO v_bounded_job
  FROM public.banking_pay_workbench_jobs
  WHERE id=p_job_id FOR UPDATE;
  SELECT * INTO v_bounded_attempt
  FROM private.banking_pay_workbench_stage_attempts
  WHERE id=p_attempt_id FOR UPDATE;

  IF v_bounded_build.id IS NULL OR v_bounded_job.id IS NULL OR v_bounded_attempt.id IS NULL
     OR v_bounded_registry.candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
     OR v_bounded_registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
     OR v_bounded_registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq
     OR v_bounded_job.economic_build_id IS DISTINCT FROM p_build_id
     OR v_bounded_job.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_job.status IS DISTINCT FROM 'RUNNING'
     OR v_bounded_attempt.job_id IS DISTINCT FROM p_job_id
     OR v_bounded_attempt.build_id IS DISTINCT FROM p_build_id
     OR v_bounded_attempt.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_attempt.attempt_nonce IS DISTINCT FROM p_attempt_nonce
     OR v_bounded_attempt.attempt_status IS DISTINCT FROM 'STARTED'
     OR clock_timestamp()>=v_bounded_attempt.lease_expires_at_utc
     OR v_bounded_build.status IS DISTINCT FROM 'RECONCILING'
     OR v_bounded_build.private_stage IS DISTINCT FROM 'RECONCILE_EXECUTE'
     OR v_bounded_build.dependency_closure_sealed_at_utc IS NULL
     OR NOT v_bounded_build.dependency_edge_stream_complete
     OR NOT v_bounded_build.edge_tag_stream_complete
     OR v_bounded_build.tagged_edge_count<>v_bounded_build.dependency_edge_count
     OR v_bounded_build.row_seal_count<>v_bounded_build.scope_count THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  IF COALESCE(NULLIF(v_bounded_build.attestation_json->>'execution_profile_version','')::integer,1)
       IS DISTINCT FROM v_execution_profile_version
     OR COALESCE(v_bounded_attempt.execution_profile_version,1)
       IS DISTINCT FROM v_execution_profile_version THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_MISMATCH' USING ERRCODE='23514';
  END IF;
  BEGIN
    v_reconciliation_optimization_version:=COALESCE(
      NULLIF(v_bounded_build.attestation_json->>'reconciliation_optimization_version','')::integer,0
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_INVALID' USING ERRCODE='23514';
  END;
  IF v_reconciliation_optimization_version NOT IN (0,1)
     OR (v_execution_profile_version=1 AND v_reconciliation_optimization_version<>0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_MISMATCH' USING ERRCODE='23514';
  END IF;
  PERFORM pg_catalog.set_config(
    'cloudtms.pay_workbench_reconciliation_optimization_version',
    v_reconciliation_optimization_version::text,
    true
  );
  IF v_reconciliation_optimization_version=1 THEN
    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp._bpay_wb_correction_residual_cache_v2(
      candidate_id uuid NOT NULL,session_key text NOT NULL,exclude_key text NOT NULL,result_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,session_key,exclude_key)
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp._bpay_wb_correction_residual_cache_v2;
  END IF;

  IF EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
    WHERE build_id=p_build_id AND closure_status<>'SEALED' LIMIT 1
  ) OR EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id
      AND NOT scope_row.required_fact_families <@ scope_row.completed_fact_families
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACTS_INCOMPLETE' USING ERRCODE='23514';
  END IF;

  SELECT array_agg(timesheet_id ORDER BY stable_ordinal),count(*)::integer
  INTO v_bounded_scope_ids,v_bounded_scope_count
  FROM private.banking_pay_workbench_economic_build_scope
  WHERE build_id=p_build_id AND closure_status='SEALED';
  v_bounded_scope_ids:=COALESCE(v_bounded_scope_ids,array[]::uuid[]);
  v_slice_total_scope_count:=v_bounded_scope_count;

  -- A28: a sliced build reconciles only the whole dependency units of its current slice. The slice is chosen by
  -- the source-build owner and recorded on the locked build; it is re-derived here from the sealed scope.
  v_slice_plan := v_bounded_build.attestation_json->'reconcile_slicing';
  v_slice := v_slice_plan->'current';
  IF jsonb_typeof(v_slice_plan)='object' THEN
    IF jsonb_typeof(v_slice)<>'object' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_REQUIRED' USING ERRCODE='23514';
    END IF;
    v_slice_active := true;
    v_slice_final := COALESCE((v_slice->>'final')::boolean,false);
    SELECT array_agg(scope_row.timesheet_id ORDER BY scope_row.stable_ordinal),count(*)::integer
    INTO v_bounded_scope_ids,v_bounded_scope_count
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id AND scope_row.closure_status='SEALED'
      AND scope_row.dependency_unit_key IN (
        SELECT unit_scope.dependency_unit_key
        FROM private.banking_pay_workbench_economic_build_scope unit_scope
        WHERE unit_scope.build_id=p_build_id AND unit_scope.closure_status='SEALED'
        GROUP BY unit_scope.dependency_unit_key
        HAVING min(unit_scope.stable_ordinal)>(v_slice->>'after_unit_ordinal')::bigint
           AND min(unit_scope.stable_ordinal)<=(v_slice->>'through_unit_ordinal')::bigint);
    v_bounded_scope_ids:=COALESCE(v_bounded_scope_ids,array[]::uuid[]);
    IF v_bounded_scope_count<1 OR v_bounded_scope_count>100
       OR v_bounded_scope_count IS DISTINCT FROM (v_slice->>'timesheet_count')::integer THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_INVALID' USING ERRCODE='23514';
    END IF;
  END IF;

  -- Session-replacement correction decisions are registered before the
  -- target candidate has authoritative build evidence.  The legacy source
  -- builder consumed those registrations immediately before materialising
  -- correction residuals; the bounded workspace must preserve that same
  -- ordering.  Capture and execute each recompute from raw authority.  The
  -- capture subtransaction rolls this state back with its finance DML, while
  -- execute persists the identical carried decision before effect and
  -- canonical-output attestation.
  PERFORM public._pay_workbench_case_resolution_carry_process_candidate_v1(
    v_bounded_build.session_id,
    v_bounded_build.candidate_id,
    v_bounded_build.source_build_run_id,
    clock_timestamp()
  );

  CREATE TEMP TABLE pg_temp.tmp_sync_entitlement_components_v2(
    timesheet_id uuid NOT NULL,
    key_type text NOT NULL,
    key_value text NOT NULL,
    truth_ex_vat numeric,
    baseline_ex_vat numeric,
    truth_inc_vat numeric,
    baseline_inc_vat numeric,
    PRIMARY KEY(timesheet_id,key_type,key_value)
  ) ON COMMIT DROP;
  CREATE TEMP TABLE pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
    timesheet_id uuid PRIMARY KEY,
    active_settled_component_count integer NOT NULL,
    active_settled_signature text NOT NULL
  ) ON COMMIT DROP;

  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp.tmp_sync_entitlement_components_v2(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,truth_inc_vat,baseline_inc_vat)
    SELECT component.timesheet_id,UPPER(BTRIM(component.key_type)),BTRIM(component.key_value),
      component.truth_ex_vat,component.baseline_ex_vat,component.truth_inc_vat,component.baseline_inc_vat
    FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) component
    WHERE NULLIF(BTRIM(COALESCE(component.key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(component.key_value,'')),'') IS NOT NULL
      AND (NOT v_slice_active OR component.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;

    INSERT INTO pg_temp.tmp_sync_settled_basis_by_timesheet_v2(
      timesheet_id,active_settled_component_count,active_settled_signature)
    SELECT scope_row.timesheet_id,
      COUNT(fact.natural_key)::integer,
      md5(COALESCE((jsonb_agg(jsonb_build_object(
        'key_type',fact.economic_key_type,
        'key_value',fact.economic_key_value,
        'amount_ex_vat',ROUND(COALESCE(fact.amount_ex_vat,0),2),
        'amount_inc_vat',ROUND(COALESCE(fact.amount_inc_vat,0),2)
      ) ORDER BY fact.economic_key_type,fact.economic_key_value)
        FILTER (WHERE fact.natural_key IS NOT NULL))::text,'[]'))
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.banking_pay_workbench_economic_build_facts fact
      ON fact.build_id=scope_row.build_id
     AND fact.timesheet_id=scope_row.timesheet_id
     AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
    GROUP BY scope_row.timesheet_id;
  END IF;
  v_workspace_cache_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer;

  IF to_regclass('pg_temp._bpay_wb_pre_sync_freshness_v1') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FRESHNESS_CONTEXT_CONFLICT'
      USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_pre_sync_freshness_v1(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL,
    settled_authority_digest text NOT NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) current_fingerprint ON current_fingerprint.timesheet_id=scope_row.timesheet_id
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  ELSE
    INSERT INTO pg_temp._bpay_wb_pre_sync_freshness_v1(
      timesheet_id,input_fingerprint,revision_json,settled_authority_digest)
    SELECT scope_row.timesheet_id,current_fingerprint.input_fingerprint,
      current_fingerprint.revision_json,
      md5(jsonb_build_object(
        'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
        'last_settled_signature',pay_state.last_settled_signature,
        'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
        'last_settled_at_utc',pay_state.last_settled_at_utc
      )::text)
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) current_fingerprint ON true
    LEFT JOIN public.timesheet_pay_state pay_state ON pay_state.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  END IF;
  v_freshness_set_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer-v_workspace_cache_ms;
  v_phase_started_at := clock_timestamp();

  IF EXISTS(
    SELECT 1
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
      ON pre_sync.timesheet_id=scope_row.timesheet_id
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
      AND pre_sync.input_fingerprint IS DISTINCT FROM scope_row.captured_input_fingerprint
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  SELECT count(*)::bigint,
         md5(COALESCE(string_agg(fact_family||':'||natural_key||':'||financial_digest,''
           ORDER BY fact_family,natural_key),''))
  INTO v_bounded_fact_count,v_bounded_pre_sync_digest
  FROM private.banking_pay_workbench_economic_build_facts
  WHERE build_id=p_build_id AND fact_family NOT IN ('DEPENDENCY_EDGE','EXPECTED_FINANCE_EFFECT');

  -- A28 (PRE-EXISTING SB02 fix, item 1): a Candidate with NOTHING to pay. The sealed build's only facts are
  -- zero-amount UNIT_PROJECTION dependency evidence (it owns no economic occurrence): no priced, settled,
  -- reserved, finance-case, component, protection or allocation fact at all. There is nothing to price, reconcile
  -- or present, so it reconciles to ZERO staged lines exactly like the existing empty-scope route, instead of
  -- failing checks that assume something to present. The freshness fence above has already run. Any other fact
  -- keeps the full reconciliation.
  IF NOT v_slice_active AND v_bounded_scope_count>0 AND NOT EXISTS(
       SELECT 1 FROM private.banking_pay_workbench_economic_build_facts ntp_fact
       WHERE ntp_fact.build_id=p_build_id
         AND ntp_fact.fact_family NOT IN ('DEPENDENCY_EDGE','EXPECTED_FINANCE_EFFECT')
         AND NOT (ntp_fact.fact_family='LIVE_ENTITLEMENT_INPUT' AND ntp_fact.source_relation='UNIT_PROJECTION'
           AND COALESCE(ntp_fact.amount_ex_vat,0)=0 AND COALESCE(ntp_fact.amount_inc_vat,0)=0
           AND COALESCE(ntp_fact.truth_ex_vat,0)=0 AND COALESCE(ntp_fact.truth_inc_vat,0)=0
           AND COALESCE(ntp_fact.baseline_ex_vat,0)=0 AND COALESCE(ntp_fact.baseline_inc_vat,0)=0
           AND COALESCE(ntp_fact.reserved_source_amount,0)=0
           AND ntp_fact.finance_case_id IS NULL AND ntp_fact.finance_component_id IS NULL
           AND ntp_fact.reservation_id IS NULL)
       LIMIT 1) THEN
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true);
    IF v_effect_capture_mode THEN
      RETURN jsonb_build_object('ok',true,'public_result_json',jsonb_build_object(
        'ok',true,'effect_plan_capture',true,'captured_effects','[]'::jsonb,'nothing_to_price',true,
        '_internal_reconcile_timing',jsonb_build_object('nothing_to_price',true,
          'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
        'internal_result_json',jsonb_build_object('captured_effect_count',0,'nothing_to_price',true));
    END IF;
    IF COALESCE((v_bounded_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE
       OR COALESCE((v_bounded_build.attestation_json->>'effect_plan_count')::integer,-1)<>0
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_facts effect_row
         WHERE effect_row.build_id=p_build_id AND effect_row.fact_family='EXPECTED_FINANCE_EFFECT' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_MISMATCH' USING ERRCODE='23514';
    END IF;
    DELETE FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    SELECT md5(jsonb_build_object(
      'candidate_id',v_bounded_build.candidate_id,'case_count',count(*),
      'case_digest',md5(COALESCE(string_agg(md5(to_jsonb(case_row)::text),'' ORDER BY case_row.id),''))
    )::text)
    INTO v_bounded_post_sync_digest
    FROM public.pay_advances case_row WHERE case_row.candidate_id=v_bounded_build.candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds
    SET status='RECONCILED',private_stage='SOURCE_PUBLISH',fact_count=v_bounded_fact_count,
        pre_sync_digest=v_bounded_pre_sync_digest,post_sync_digest=v_bounded_post_sync_digest,
        canonical_count=0,canonical_digest=md5(''),
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'version',1,'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
          'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_count',v_bounded_scope_count,
          'fact_count',v_bounded_fact_count,'canonical_count',0,
          'effect_plan_sealed',true,'effect_plan_count',0,
          'effect_plan_digest',v_bounded_build.attestation_json->>'effect_plan_digest',
          'observed_finance_effect_count',0,'observed_finance_effect_digest',md5(''),
          'economic_component_digest',md5(''),'presentation_allocation_digest',md5(''),
          'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
          'canonical_digest',md5(''),'nothing_to_price_reconciliation_version',1),
        reconciled_at_utc=clock_timestamp(),publication_cursor_json=jsonb_build_object(
          'cursor_kind','SOURCE_PUBLISH','cursor_version',1,'build_id',p_build_id,
          'candidate_id',v_bounded_build.candidate_id,'canonical_count',0,'canonical_digest',md5('')),
        updated_at_utc=clock_timestamp()
    WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    RETURN jsonb_build_object(
      'ok',true,'public_result_json',jsonb_build_object('ok',true,'nothing_to_price',true,
        'pay_channel_scope',upper(NULLIF(btrim(p_pay_channel_scope),'')),
        'cases_inserted',0,'cases_touched',0,'cases_amended',0,'cases_reopened',0,'cases_cleared',0),
      'internal_result_json',jsonb_build_object('build_id',p_build_id,'attempt_id',p_attempt_id,
        'scope_timesheet_count',v_bounded_scope_count,'fact_count',v_bounded_fact_count,
        'canonical_stage_count',0,'nothing_to_price',true),
      'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_timesheet_count',v_bounded_scope_count,
      'canonical_stage_count',0,'nothing_to_price',true);
  END IF;

  IF to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
  END IF;
  CREATE TEMP TABLE pg_temp._bpay_wb_expected_effects(
    build_token uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    relation_name text NOT NULL,
    operation text NOT NULL,
    source_id uuid NOT NULL,
    actual_source_id uuid NULL,
    finance_case_id uuid NULL,
    finance_component_id uuid NULL,
    economic_key_type text NULL,
    economic_key_value text NULL,
    proposed boolean NOT NULL DEFAULT false,
    expected_before_digest text NULL,
    expected_after_digest text NULL,
    observed boolean NOT NULL DEFAULT false,
    UNIQUE NULLS NOT DISTINCT(
      build_token,relation_name,operation,source_id,candidate_id,timesheet_id,
      expected_before_digest,expected_after_digest
    )
  ) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_effect_identity_map_v1(
    relation_name text NOT NULL,
    logical_source_id uuid NOT NULL,
    actual_source_id uuid NOT NULL,
    PRIMARY KEY(relation_name,logical_source_id),
    UNIQUE(relation_name,actual_source_id)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_effect_identity_map_v1;

  IF NOT v_effect_capture_mode THEN
    INSERT INTO pg_temp._bpay_wb_expected_effects(build_token,candidate_id,timesheet_id,
      relation_name,operation,source_id,finance_case_id,finance_component_id,
      economic_key_type,economic_key_value,expected_before_digest,expected_after_digest,proposed,observed)
    SELECT v_bounded_build.build_token,fact.candidate_id,fact.timesheet_id,fact.source_relation,
      fact.source_payload_json->>'operation',fact.source_id,fact.finance_case_id,
      fact.finance_component_id,fact.economic_key_type,fact.economic_key_value,
      NULLIF(fact.source_payload_json->>'expected_before_digest',''),
      NULLIF(fact.source_payload_json->>'expected_after_digest',''),false,false
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id AND fact.fact_family='EXPECTED_FINANCE_EFFECT';
    IF COALESCE((v_bounded_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE
       OR NULLIF(v_bounded_build.attestation_json->>'effect_plan_digest','') IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_REQUIRED' USING ERRCODE='23514';
    END IF;
  END IF;

  p_candidate_ids:=ARRAY[v_bounded_build.candidate_id];
  p_force_include_timesheet_ids:=v_bounded_scope_ids;
  p_exclude_timesheet_ids:=ARRAY(
    SELECT excluded_id FROM unnest(COALESCE(p_exclude_timesheet_ids,array[]::uuid[])) excluded_id
    WHERE excluded_id=ANY(v_bounded_scope_ids) ORDER BY excluded_id
  );
  PERFORM set_config('cloudtms.pay_workbench_overpayment_sync_token',v_bounded_build.build_token::text,true);
  -- A28: the final slice renders the Candidate-level balance lines. Its recovery headroom must be the whole
  -- Candidate's, so the additive headroom of the earlier slices is handed to the two preview owners, bound to
  -- this build token (they ignore it otherwise). Transaction-local; cleared before every return.
  PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1',CASE WHEN v_slice_active THEN jsonb_build_object(
    'build_token',v_bounded_build.build_token::text,'candidate_id',v_bounded_build.candidate_id::text,
    'final',v_slice_final,'slice_index',v_slice->'index',
    'prior_recovery_headroom_ex',COALESCE((v_slice_plan->>'prior_recovery_headroom_ex')::numeric,0),
    'prior_ordinary_positive_headroom_ex',COALESCE((v_slice_plan->>'prior_ordinary_positive_headroom_ex')::numeric,0)
  )::text ELSE '' END,true);
  p_mismatch_choices:=(CASE WHEN jsonb_typeof(COALESCE(p_mismatch_choices,'{}'::jsonb))='object'
    THEN COALESCE(p_mismatch_choices,'{}'::jsonb) ELSE '{}'::jsonb END)
    - 'overpayment_sync_negative_component_digest'
    - 'overpayment_sync_settled_baseline_digest'
    ||jsonb_build_object(
      'overpayment_sync_authoritative_timesheet_scope',true,
      'overpayment_sync_authority_token',v_bounded_build.build_token::text,
      'workbench_session_id',v_bounded_build.session_id::text,
      'source_build_run_id',v_bounded_build.source_build_run_id::text,
      'source_change_seq',v_bounded_build.source_change_seq,
      'session_version',v_bounded_build.session_version,
      'overpayment_sync_scope_digest',v_bounded_build.scope_digest,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    );

  v_preflight_setup_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  declare
    v_correction_candidate uuid;
    v_residuals jsonb;
    v_candidate_pending_member_ids uuid[] := array[]::uuid[];
    v_candidate_pending_root_ids uuid[] := array[]::uuid[];
  begin
    foreach v_correction_candidate in array coalesce(p_candidate_ids,array[]::uuid[]) loop
      v_residuals:=public._ctms_candidate_correction_residuals_v1(
        NULL::uuid,
        v_correction_candidate,
        NULL::uuid,
        'PAY_SYNC_OVERPAYMENTS'
      );

      v_candidate_pending_member_ids := ARRAY(
        select distinct member_id.value::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        cross join lateral jsonb_array_elements_text(
          coalesce(residual.value->'member_timesheet_ids', '[]'::jsonb)
        ) member_id(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and member_id.value
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by member_id.value::uuid
      );

      v_candidate_pending_root_ids := ARRAY(
        select distinct (residual.value->>'root_timesheet_id')::uuid
        from jsonb_array_elements(v_residuals) residual(value)
        where coalesce((residual.value->>'draftable')::boolean, false) is not true
          and coalesce(residual.value->>'block_code', '')
                = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
          and coalesce((residual.value->>'unresolved_count')::integer, 0) > 0
          and coalesce((residual.value->>'reservation_overrun_count')::integer, 0) = 0
          and coalesce((residual.value->>'component_count')::integer, 0) > 0
          and coalesce(residual.value->>'root_timesheet_id', '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        order by (residual.value->>'root_timesheet_id')::uuid
      );

      v_resolution_pending_member_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_member_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_member_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      v_resolution_pending_root_ids := ARRAY(
        select distinct pending_id
        from unnest(
          coalesce(v_resolution_pending_root_ids, array[]::uuid[])
          || coalesce(v_candidate_pending_root_ids, array[]::uuid[])
        ) pending_id
        order by pending_id
      );

      if exists(
        select 1
        from jsonb_array_elements(v_residuals) r
        where coalesce((r->>'draftable')::boolean,false) is not true
          and not (
            coalesce(r->>'block_code','')
              = 'CORRECTION_CHAIN_PAY_METHOD_RESOLUTION_REQUIRED'
            and coalesce((r->>'unresolved_count')::integer,0) > 0
            and coalesce((r->>'reservation_overrun_count')::integer,0) = 0
            and coalesce((r->>'component_count')::integer,0) > 0
          )
          and not (
            coalesce(r->>'block_code','') = 'CORRECTION_CHAIN_RESERVATION_OVERRUN'
            and coalesce((r->>'reservation_overrun_count')::integer,0) > 0
            and exists (
              select 1
              from private.banking_pay_workbench_economic_build_facts active_batch_item
              where active_batch_item.build_id=p_build_id
                and active_batch_item.fact_family='PROTECTION_EVIDENCE'
                and active_batch_item.source_relation='pay_batch_items'
                and active_batch_item.candidate_id=v_correction_candidate
                and active_batch_item.source_payload_json->>'protection_kind'
                  ='ACTIVE_CORRECTION_CHAIN_BATCH_ITEM'
                and coalesce(
                  active_batch_item.source_payload_json #>> '{frozen_component_snapshot_json,correction_root_id}',
                  active_batch_item.source_payload_json #>> '{frozen_resolution_payload_json,correction_root_id}',
                  '')=coalesce(r->>'root_timesheet_id','')
            )
          )
          and (
            coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
            or exists (
              select 1
              from jsonb_array_elements_text(
                coalesce(r->'member_timesheet_ids','[]'::jsonb)
              ) member_id(value)
              where member_id.value::uuid
                    = any(coalesce(p_force_include_timesheet_ids,array[]::uuid[]))
            )
          )
      ) then
        raise exception 'CORRECTION_RESIDUAL_NOT_READY_FOR_OVERPAYMENT_SYNC' using errcode='P0001',detail=v_residuals::text;
      end if;
    end loop;
  end;
  v_correction_residuals_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  v_requested_candidate_count := COALESCE(array_length(p_candidate_ids, 1), 0);

  v_authoritative_timesheet_scope_requested := LOWER(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authoritative_timesheet_scope',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_sync_authority_token := NULLIF(BTRIM(COALESCE(
    p_mismatch_choices->>'overpayment_sync_authority_token',
    ''
  )), '');
  v_current_sync_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  IF COALESCE(v_authoritative_timesheet_scope_requested, false)
     AND (
       p_force_include_timesheet_ids IS NULL
       OR v_sync_authority_token IS NULL
       OR v_current_sync_authority_token IS NULL
       OR v_sync_authority_token IS DISTINCT FROM v_current_sync_authority_token
     ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_AUTHORITY_INVALID',
              'message', 'Authoritative Timesheet scope is internal Workbench authority and requires the matching transaction-local source-build token.',
              'force_include_argument_supplied', p_force_include_timesheet_ids IS NOT NULL,
              'authority_token_supplied', v_sync_authority_token IS NOT NULL,
              'transaction_authority_present', v_current_sync_authority_token IS NOT NULL
            )::text;
  END IF;

  v_authoritative_timesheet_scope := COALESCE(v_authoritative_timesheet_scope_requested, false)
    AND p_force_include_timesheet_ids IS NOT NULL
    AND v_sync_authority_token IS NOT NULL
    AND v_sync_authority_token = v_current_sync_authority_token;

  v_explicit_empty_timesheet_scope := COALESCE(v_authoritative_timesheet_scope, false)
    AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) = 0;

  v_preview_scope_strategy := CASE
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
     AND COALESCE(array_length(p_force_include_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
    WHEN COALESCE(v_authoritative_timesheet_scope, false)
      THEN 'AUTHORITATIVE_EMPTY'
    ELSE 'CANDIDATE_FULL_LIVE'
  END;

  v_preview_decisions_json := (
      CASE
        WHEN jsonb_typeof(COALESCE(p_mismatch_choices, '{}'::jsonb)) = 'object'
          THEN COALESCE(p_mismatch_choices, '{}'::jsonb)
        ELSE '{}'::jsonb
      END
      - 'refresh_scope_kind'
      - 'targeted_timesheet_ids'
      - 'targeted_timesheet_ids_requested'
      - 'linked_timesheet_ids'
      - 'linked_timesheet_ids_requested'
      - 'source_build_allow_full_fallback'
      - 'overpayment_sync_authority_token'
      - 'overpayment_sync_authoritative_timesheet_scope'
      - 'authoritative_timesheet_scope'
      - 'exact_timesheet_scope'
      - 'workbench_session_id'
      - 'source_build_run_id'
      - 'source_change_seq'
      - 'session_version'
      - 'overpayment_sync_scope_digest'
      - 'overpayment_sync_negative_component_digest'
      - 'overpayment_sync_settled_baseline_digest'
      - 'policy_x_authority_scope'
    )
    || jsonb_build_object(
      'overpayment_sync_mode', true,
      'emit_raw_overpayment_components', true,
      'preview_context_mode', CASE WHEN v_requested_candidate_count = 1 THEN 'FULL_COMPAT' ELSE 'PAGE' END,
      'scope_limit', LEAST(GREATEST(COALESCE(v_requested_candidate_count, 1), 1), 100),
      'pay_channel_scope', v_scope,
      'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
      'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
      'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb),
      'overpayment_sync_preview_scope_strategy', v_preview_scope_strategy
    )
    || CASE
      WHEN v_preview_scope_strategy = 'TARGETED_TIMESHEETS' THEN
        jsonb_build_object(
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'source_build_allow_full_fallback', false,
          'overpayment_sync_explicit_empty_scope', false
        )
      ELSE
        jsonb_build_object(
          'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
          'targeted_timesheet_ids', '[]'::jsonb,
          'targeted_timesheet_ids_requested', '[]'::jsonb,
          'linked_timesheet_ids', '[]'::jsonb,
          'linked_timesheet_ids_requested', '[]'::jsonb,
          'overpayment_sync_explicit_empty_scope', COALESCE(v_explicit_empty_timesheet_scope, false)
        )
    END
    || CASE
      WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
        jsonb_build_object(
          'workbench_source_build_mode', true,
          'source_build_mode', true,
          'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'overpayment_sync_authority_token', v_sync_authority_token
        )
      ELSE '{}'::jsonb
    END;


  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_ID_INVALID',
              'message', 'candidate_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS included_timesheet(timesheet_id)
    WHERE included_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_FORCE_INCLUDE_TIMESHEET_ID_INVALID',
              'message', 'force_include_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])) AS excluded_timesheet(timesheet_id)
    WHERE excluded_timesheet.timesheet_id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_EXCLUDE_TIMESHEET_ID_INVALID',
              'message', 'exclude_timesheet_ids must not contain null values.'
            )::text;
  END IF;

  IF v_requested_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_TOO_LARGE',
              'candidate_count', v_requested_candidate_count,
              'limit', 100,
              'message', 'Supply at most 100 explicit candidate IDs per bounded reconciliation call.'
            )::text;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    IF v_requested_candidate_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SINGLE_CANDIDATE_REQUIRED',
                'candidate_count', v_requested_candidate_count
              )::text;
    END IF;

    v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), '');
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), '');
    v_session_version_text := NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), '');

    IF v_workbench_session_id_text IS NULL
       OR v_workbench_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_session_version_text IS NULL
       OR v_session_version_text !~ '^[0-9]{1,18}$'
       OR NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), '') IS NULL
       OR UPPER(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH' THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_METADATA_INVALID',
                'workbench_session_id', v_workbench_session_id_text,
                'source_build_run_id', v_source_build_run_id_text,
                'session_version', v_session_version_text,
                'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
              )::text;
    END IF;

    v_workbench_session_id := v_workbench_session_id_text::uuid;
    v_source_build_run_id := v_source_build_run_id_text::uuid;
    v_workbench_session_version := v_session_version_text::bigint;

    v_authoritative_candidate_id := p_candidate_ids[1];

    -- Supabase preloads plpgsql_check with fatal nested-statement inspection.
    -- Keep this predicate in its bounded owner-only SQL helper so the deeply
    -- nested PL/pgSQL frame does not corrupt pldbgapi2's parent stack.
    v_authoritative_session_valid :=
      public._pay_workbench_authoritative_scope_valid_v1(
      v_workbench_session_id,
      v_authoritative_candidate_id,
      v_workbench_session_version,
      p_actor_user_id,
      p_pay_date,
      p_week_ending_cutoff,
      v_scope
    );

    IF COALESCE(v_authoritative_session_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_SESSION_INVALID',
                'workbench_session_id', v_workbench_session_id::text,
                'source_build_run_id', v_source_build_run_id::text,
                'session_version', v_workbench_session_version,
                'candidate_id', v_authoritative_candidate_id::text,
                'pay_channel_scope', v_scope
              )::text;
    END IF;

    IF EXISTS (
      WITH candidate_authority_seed_timesheets AS (
        SELECT authoritative_tsfin.timesheet_id
        FROM public.timesheets_financials AS authoritative_tsfin
        WHERE authoritative_tsfin.candidate_id = v_authoritative_candidate_id
          AND authoritative_tsfin.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_case.linked_timesheet_id
        FROM public.pay_advances AS authoritative_case
        WHERE authoritative_case.candidate_id = v_authoritative_candidate_id
          AND authoritative_case.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_component.linked_timesheet_id
        FROM public.pay_finance_case_components AS authoritative_component
        WHERE authoritative_component.candidate_id = v_authoritative_candidate_id
          AND authoritative_component.linked_timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_override.timesheet_id
        FROM public.timesheet_payment_overrides AS authoritative_override
        WHERE authoritative_override.candidate_id = v_authoritative_candidate_id
          AND authoritative_override.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_adjustment.timesheet_id
        FROM public.ts_pay_adjustments AS authoritative_adjustment
        WHERE authoritative_adjustment.candidate_id = v_authoritative_candidate_id
          AND authoritative_adjustment.timesheet_id IS NOT NULL

        UNION

        SELECT authoritative_snooze.timesheet_id
        FROM public.pay_item_snoozes AS authoritative_snooze
        WHERE authoritative_snooze.candidate_id = v_authoritative_candidate_id
          AND authoritative_snooze.timesheet_id IS NOT NULL
          AND authoritative_snooze.cleared_at_utc IS NULL
          AND authoritative_snooze.cancelled_at_utc IS NULL

        UNION

        SELECT authoritative_batch_item.timesheet_id
        FROM public.pay_batch_candidates AS authoritative_batch_candidate
        JOIN public.pay_batch_items AS authoritative_batch_item
          ON authoritative_batch_item.pay_batch_candidate_id = authoritative_batch_candidate.id
        WHERE authoritative_batch_candidate.candidate_id = v_authoritative_candidate_id
          AND authoritative_batch_item.timesheet_id IS NOT NULL
          AND COALESCE(authoritative_batch_item.is_voided, false) IS NOT TRUE

        UNION

        SELECT authoritative_correction.timesheet_id
        FROM public.pay_payment_correction_items AS authoritative_correction
        WHERE authoritative_correction.candidate_id = v_authoritative_candidate_id
          AND authoritative_correction.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(authoritative_correction.status, ''))) = 'APPLIED'
      ), candidate_authority_seed_array AS (
        SELECT COALESCE(
          ARRAY_AGG(
            DISTINCT candidate_authority_seed_timesheets.timesheet_id
            ORDER BY candidate_authority_seed_timesheets.timesheet_id
          ),
          ARRAY[]::uuid[]
        ) AS timesheet_ids
        FROM candidate_authority_seed_timesheets
      ), candidate_authority_timesheets AS (
        SELECT candidate_authority_seed_timesheets.timesheet_id
        FROM candidate_authority_seed_timesheets

        UNION

        SELECT authority_rotation.canonical_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.canonical_timesheet_id IS NOT NULL

        UNION

        SELECT authority_rotation.family_timesheet_id
        FROM candidate_authority_seed_array
        JOIN public._pay_timesheet_rotation_scope(
          candidate_authority_seed_array.timesheet_ids
        ) AS authority_rotation
          ON true
        WHERE authority_rotation.family_timesheet_id IS NOT NULL
      )
      SELECT 1
      FROM unnest(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[])) AS authoritative_timesheet(timesheet_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM candidate_authority_timesheets AS candidate_authority
        WHERE candidate_authority.timesheet_id = authoritative_timesheet.timesheet_id
      )
    ) THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_SCOPE_CANDIDATE_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb)
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_explicit_empty_timesheet_scope, false) THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
      jsonb_build_object(
        'pay_channel_scope', v_scope,
        'authoritative_timesheet_scope', true,
        'explicit_empty_timesheet_scope', true,
        'preview_scope_strategy', v_preview_scope_strategy,
        'candidate_count', v_requested_candidate_count,
        'cases_inserted', 0,
        'cases_touched', 0,
        'cases_amended', 0,
        'cases_reopened', 0,
        'cases_cleared', 0
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'pay_channel_scope', v_scope,
      'authoritative_timesheet_scope', true,
      'explicit_empty_timesheet_scope', true,
      'preview_scope_strategy', v_preview_scope_strategy,
      'scope_timesheet_ids', '[]'::jsonb,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', 0,
      'preview_candidate_coverage_complete', true,
      'negative_preview_timesheets_count', 0,
      'negative_preview_timesheets', '[]'::jsonb,
      'underpayment_case_count', 0,
      'underpayment_cases', '[]'::jsonb,
      'timesheet_finance_case_candidates_count', 0,
      'timesheet_finance_case_candidates', '[]'::jsonb,
      'cases_inserted', 0,
      'cases_touched', 0,
      'cases_amended', 0,
      'cases_reopened', 0,
      'cases_cleared', 0
    );
  END IF;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_preview_candidates (
    candidate_id uuid not null primary key,
    candidate_json jsonb not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_negative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_authoritative_components (
    timesheet_id uuid not null,
    key_type text not null,
    key_value text not null,
    truth_ex_vat numeric(12,2) not null,
    baseline_ex_vat numeric(12,2) not null,
    reserved_ex_vat numeric(12,2) not null,
    outstanding_ex_vat numeric(12,2) not null,
    baseline_signature text null,
    primary key (timesheet_id, key_type, key_value)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_raw_negative_timesheet_rows (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    case_components_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;
  truncate table pg_temp.tmp_sync_preview_candidates;
  truncate table pg_temp.tmp_sync_authoritative_negative_components;
  truncate table pg_temp.tmp_sync_authoritative_components;
  truncate table pg_temp.tmp_sync_raw_negative_timesheet_rows;

  v_authority_validation_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF COALESCE(v_authoritative_timesheet_scope, false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_finance_case_authority;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_finance_case_authority ON COMMIT DROP AS
    SELECT fact.build_id,fact.candidate_id,fact.finance_case_id,
      COUNT(*)::integer AS evidence_count,
      COUNT(DISTINCT UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),'')))::integer
        AS distinct_case_type_count,
      MIN(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),''))) AS case_type
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=p_build_id
      AND fact.fact_family='FINANCE_CASE_IDENTITY'
      AND fact.finance_case_id IS NOT NULL
    GROUP BY fact.build_id,fact.candidate_id,fact.finance_case_id;

    CREATE UNIQUE INDEX tmp_sync_sealed_finance_case_authority_idx
      ON pg_temp.tmp_sync_sealed_finance_case_authority(
        build_id,candidate_id,finance_case_id);

    INSERT INTO pg_temp.tmp_sync_authoritative_components (
      timesheet_id,
      key_type,
      key_value,
      truth_ex_vat,
      baseline_ex_vat,
      reserved_ex_vat,
      outstanding_ex_vat,
      baseline_signature
    )
    WITH live_entitlement_components AS (
      SELECT
        entitlement_component.timesheet_id,
        UPPER(BTRIM(entitlement_component.key_type)) AS key_type,
        BTRIM(entitlement_component.key_value) AS key_value,
        ROUND(COALESCE(entitlement_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(entitlement_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat
      FROM (
        SELECT legacy_component.*
        FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
          p_build_id,NULL::text
        ) AS legacy_component
        WHERE v_execution_profile_version = 1
        UNION ALL
        SELECT cached_component.*
        FROM pg_temp.tmp_sync_entitlement_components_v2 AS cached_component
        WHERE v_execution_profile_version = 2
      ) AS entitlement_component
      WHERE NULLIF(BTRIM(COALESCE(entitlement_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(entitlement_component.key_value, '')), '') IS NOT NULL
        AND (NOT v_slice_active OR entitlement_component.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
    ), active_entitlement_reservations AS (
      SELECT
        reserved_component.timesheet_id,
        UPPER(BTRIM(reserved_component.key_type)) AS key_type,
        BTRIM(reserved_component.key_value) AS key_value,
        ROUND(COALESCE(reserved_component.amount_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat
      FROM (
        SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
          fact.economic_key_value AS key_value,
          SUM(CASE
            WHEN case_authority.evidence_count=1
              AND case_authority.distinct_case_type_count=1
              AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0)
          END) AS amount_ex_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.fact_family='RESERVATION_COMPONENT'
          AND (NOT v_slice_active OR fact.timesheet_id=ANY(v_bounded_scope_ids)
            OR (fact.timesheet_id IS NULL AND v_slice_final)) /* A28 */
        GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value
      ) AS reserved_component
      WHERE NULLIF(BTRIM(COALESCE(reserved_component.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(reserved_component.key_value, '')), '') IS NOT NULL
    ), live_economic_keys AS (
      SELECT
        live_component.timesheet_id,
        live_component.key_type,
        live_component.key_value
      FROM live_entitlement_components AS live_component

      UNION

      SELECT
        reserved_component.timesheet_id,
        reserved_component.key_type,
        reserved_component.key_value
      FROM active_entitlement_reservations AS reserved_component
    ), raw_outstanding_components AS (
      SELECT
        live_key.timesheet_id,
        live_key.key_type,
        live_key.key_value,
        ROUND(COALESCE(live_component.truth_ex_vat, 0), 2)::numeric(12,2) AS truth_ex_vat,
        ROUND(COALESCE(live_component.baseline_ex_vat, 0), 2)::numeric(12,2) AS baseline_ex_vat,
        ROUND(COALESCE(reserved_component.reserved_ex_vat, 0), 2)::numeric(12,2) AS reserved_ex_vat,
        ROUND(
          COALESCE(live_component.truth_ex_vat, 0)
          - COALESCE(live_component.baseline_ex_vat, 0)
          - COALESCE(reserved_component.reserved_ex_vat, 0),
          2
        )::numeric(12,2) AS outstanding_ex_vat
      FROM live_economic_keys AS live_key
      LEFT JOIN live_entitlement_components AS live_component
        ON live_component.timesheet_id = live_key.timesheet_id
       AND live_component.key_type = live_key.key_type
       AND live_component.key_value = live_key.key_value
      LEFT JOIN active_entitlement_reservations AS reserved_component
        ON reserved_component.timesheet_id = live_key.timesheet_id
       AND reserved_component.key_type = live_key.key_type
       AND reserved_component.key_value = live_key.key_value
    )
    SELECT
      raw_component.timesheet_id,
      raw_component.key_type,
      raw_component.key_value,
      raw_component.truth_ex_vat,
      raw_component.baseline_ex_vat,
      raw_component.reserved_ex_vat,
      raw_component.outstanding_ex_vat,
      COALESCE(active_settled_basis.active_settled_signature,md5('[]')) AS baseline_signature
    FROM raw_outstanding_components AS raw_component
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS active_settled_component_count,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_component.key_type,
            'key_value', active_settled_component.key_value,
            'amount_ex_vat', ROUND(COALESCE(active_settled_component.amount_ex_vat, 0), 2),
            'amount_inc_vat', ROUND(COALESCE(active_settled_component.amount_inc_vat, 0), 2)
          ) ORDER BY active_settled_component.key_type, active_settled_component.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=raw_component.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_component
      HAVING v_execution_profile_version = 1

      UNION ALL

      SELECT cached_basis.active_settled_component_count,cached_basis.active_settled_signature
      FROM pg_temp.tmp_sync_settled_basis_by_timesheet_v2 cached_basis
      WHERE v_execution_profile_version = 2
        AND cached_basis.timesheet_id=raw_component.timesheet_id
    ) AS active_settled_basis ON true
    ;

    INSERT INTO pg_temp.tmp_sync_authoritative_negative_components(
      timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    )
    SELECT timesheet_id,key_type,key_value,truth_ex_vat,baseline_ex_vat,
      reserved_ex_vat,outstanding_ex_vat,baseline_signature
    FROM pg_temp.tmp_sync_authoritative_components
    WHERE outstanding_ex_vat < 0;

    PERFORM public._ctms_rewrite_sync_authoritative_correction_negative_components_v1(
      nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid,
      v_authoritative_candidate_id,
      coalesce(p_force_include_timesheet_ids, array[]::uuid[])
    );

    SELECT
      COUNT(*)::integer,
      md5(COALESCE(jsonb_agg(
        jsonb_build_object(
          'timesheet_id', negative_component.timesheet_id::text,
          'key_type', negative_component.key_type,
          'key_value', negative_component.key_value,
          'truth_ex_vat', ROUND(negative_component.truth_ex_vat, 2)::numeric(12,2),
          'baseline_ex_vat', ROUND(negative_component.baseline_ex_vat, 2)::numeric(12,2),
          'reserved_ex_vat', ROUND(negative_component.reserved_ex_vat, 2)::numeric(12,2),
          'outstanding_ex_vat', ROUND(negative_component.outstanding_ex_vat, 2)::numeric(12,2)
        ) ORDER BY negative_component.timesheet_id, negative_component.key_type, negative_component.key_value
      )::text, '[]'))
    INTO
      v_authoritative_negative_component_count,
      v_authoritative_negative_component_digest
    FROM pg_temp.tmp_sync_authoritative_negative_components AS negative_component;

    SELECT md5(COALESCE(jsonb_agg(
      jsonb_build_object(
        'timesheet_id', settled_component.timesheet_id::text,
        'key_type', settled_component.key_type,
        'key_value', settled_component.key_value,
        'amount_ex_vat', ROUND(COALESCE(settled_component.amount_ex_vat, 0), 2),
        'amount_inc_vat', ROUND(COALESCE(settled_component.amount_inc_vat, 0), 2)
      ) ORDER BY settled_component.timesheet_id, settled_component.key_type, settled_component.key_value
    )::text, '[]'))
    INTO v_authoritative_settled_baseline_digest
    FROM (
      SELECT fact.timesheet_id,fact.economic_key_type AS key_type,
        fact.economic_key_value AS key_value,fact.amount_ex_vat,fact.amount_inc_vat
      FROM private.banking_pay_workbench_economic_build_facts fact
      WHERE fact.build_id=p_build_id
        AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
    ) AS settled_component;

    -- These two attestations are private build authority.  They are derived
    -- only after immutable fact materialisation; caller/job values were
    -- stripped above and can never assert them.
    v_expected_negative_component_digest := v_authoritative_negative_component_digest;
    v_expected_settled_baseline_digest := v_authoritative_settled_baseline_digest;
    p_mismatch_choices:=p_mismatch_choices||jsonb_build_object(
      'overpayment_sync_negative_component_digest',v_expected_negative_component_digest,
      'overpayment_sync_settled_baseline_digest',v_expected_settled_baseline_digest);

    IF v_authoritative_negative_component_digest IS DISTINCT FROM v_expected_negative_component_digest
       OR v_authoritative_settled_baseline_digest IS DISTINCT FROM v_expected_settled_baseline_digest THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_COMPONENT_DIGEST_MISMATCH',
                'candidate_id', v_authoritative_candidate_id::text,
                'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                'expected_negative_component_digest', v_expected_negative_component_digest,
                'actual_negative_component_digest', v_authoritative_negative_component_digest,
                'expected_settled_baseline_digest', v_expected_settled_baseline_digest,
                'actual_settled_baseline_digest', v_authoritative_settled_baseline_digest,
                'message', 'The Workbench negative-component or settled-baseline authority changed before finance-case synchronisation.'
              )::text;
    END IF;
  END IF;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_raw;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection_failures;
    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_rate_projection;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_raw
    ON COMMIT DROP AS
    SELECT row_number() OVER(ORDER BY helper_row.timesheet_id NULLS FIRST,
        helper_row.economic_key_type NULLS FIRST,helper_row.economic_key_value NULLS FIRST,
        helper_row.physical_bucket_key NULLS FIRST,helper_row.failure_code NULLS FIRST,
        helper_row.evidence_json::text)::bigint AS materialization_ordinal,
      helper_row.*
    FROM private.pay_workbench_sealed_rate_component_projection_v1(
      p_build_id,v_bounded_build.candidate_id,
      CASE WHEN p_force_include_timesheet_ids IS NULL THEN NULL::uuid[]
        ELSE p_force_include_timesheet_ids END
    ) helper_row;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection_failures(
      failure_rank integer NOT NULL,failure_code text NOT NULL,timesheet_id uuid,
      economic_key_type text,economic_key_value text,physical_bucket_key text,
      detail_json jsonb NOT NULL
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 10,COALESCE(NULLIF(BTRIM(raw.failure_code),''),
        'RATE_AUTHORITY_FAILED_ROW_CODE_MISSING'),raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'projection_status',raw.projection_status,'failure_code',raw.failure_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))='FAILED';

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 20,'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_family_key',raw.source_family_key,'component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,'bucket_code',raw.bucket_code)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (raw.timesheet_id IS NULL OR NULLIF(BTRIM(raw.economic_key_type),'') IS NULL
        OR NULLIF(BTRIM(raw.economic_key_value),'') IS NULL
        OR NULLIF(BTRIM(raw.source_family_key),'') IS NULL
        OR NULLIF(BTRIM(raw.component_kind),'') IS NULL
        OR NULLIF(BTRIM(raw.component_member_identity),'') IS NULL
        OR NULLIF(BTRIM(raw.bucket_code),'') IS NULL
        OR NULLIF(BTRIM(raw.physical_bucket_key),'') IS NULL);

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 21,'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'source_pay_method',raw.source_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.source_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.source_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 22,'RATE_AUTHORITY_TARGET_PAY_METHOD_MISSING',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,raw.physical_bucket_key,
      jsonb_build_object('materialization_ordinal',raw.materialization_ordinal,
        'target_pay_method',raw.target_pay_method)
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
      AND (NULLIF(BTRIM(raw.target_pay_method),'') IS NULL
        OR UPPER(BTRIM(raw.target_pay_method)) NOT IN ('PAYE','UMBRELLA'));

    WITH key_methods AS MATERIALIZED (
      SELECT DISTINCT raw.timesheet_id,
        UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        UPPER(BTRIM(raw.source_pay_method)) AS source_pay_method
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
    ), timesheet_methods AS MATERIALIZED (
      SELECT key_method.timesheet_id,
        COUNT(DISTINCT key_method.source_pay_method)::integer
          AS distinct_supported_method_count,
        COUNT(*)::integer AS economic_key_count,
        jsonb_agg(jsonb_build_object(
          'economic_key_type',key_method.economic_key_type,
          'economic_key_value',key_method.economic_key_value,
          'source_pay_method',key_method.source_pay_method)
          ORDER BY key_method.economic_key_type,key_method.economic_key_value,
            key_method.source_pay_method) AS complete_key_method_set
      FROM key_methods key_method
      GROUP BY key_method.timesheet_id
    )
    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 23,'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT',method.timesheet_id,
      NULL::text,NULL::text,NULL::text,
      jsonb_build_object(
        'distinct_supported_method_count',method.distinct_supported_method_count,
        'economic_key_count',method.economic_key_count,
        'complete_economic_key_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(method.complete_key_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',method.economic_key_count>25,
        'economic_key_method_sample',pg_catalog.jsonb_path_query_array(
          method.complete_key_method_set,'$[0 to 24]'))
    FROM timesheet_methods method
    WHERE method.distinct_supported_method_count<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 30,'RATE_AUTHORITY_DUPLICATE_PHYSICAL_BUCKET',duplicate.timesheet_id,
      duplicate.economic_key_type,duplicate.economic_key_value,
      duplicate.physical_bucket_key,
      jsonb_build_object('duplicate_count',duplicate.duplicate_count)
    FROM (
      SELECT raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key,count(*)::integer AS duplicate_count
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,''))<>'FAILED'
        AND raw.timesheet_id IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_type),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.economic_key_value),'') IS NOT NULL
        AND NULLIF(BTRIM(raw.physical_bucket_key),'') IS NOT NULL
      GROUP BY raw.timesheet_id,raw.economic_key_type,raw.economic_key_value,
        raw.physical_bucket_key HAVING count(*)>1
    ) duplicate;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 40,'RATE_AUTHORITY_TARGET_AUTHORITY_CONFLICT',NULL::uuid,NULL::text,
      NULL::text,NULL::text,jsonb_build_object(
        'target_method_count',count(DISTINCT raw.target_pay_method),
        'target_digest_count',count(DISTINCT raw.target_authority_digest),
        'conversion_digest_count',count(DISTINCT raw.conversion_context_digest))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
    HAVING count(DISTINCT raw.target_pay_method)<>1
       OR count(DISTINCT raw.target_authority_digest)<>1
       OR count(DISTINCT raw.conversion_context_digest)<>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 45,'RATE_AUTHORITY_MULTIPLE_RATES_UNSUPPORTED',raw.timesheet_id,
      raw.economic_key_type,raw.economic_key_value,MIN(raw.physical_bucket_key),
      jsonb_build_object('component_kind',raw.component_kind,
        'component_member_identity',raw.component_member_identity,
        'bucket_code',raw.bucket_code,
        'source_rate_count',count(DISTINCT ROUND(raw.source_rate,6)),
        'source_charge_rate_count',count(DISTINCT ROUND(raw.source_charge_rate,6)))
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
      AND raw.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
    GROUP BY raw.timesheet_id,raw.component_kind,raw.component_member_identity,
      raw.economic_key_type,raw.economic_key_value,raw.bucket_code
    HAVING count(DISTINCT ROUND(raw.source_rate,6))>1
       OR count(DISTINCT ROUND(raw.source_charge_rate,6))>1;

    INSERT INTO pg_temp.tmp_sync_sealed_rate_projection_failures
    SELECT 50,'PAY_SYNC_OVERPAYMENTS_RATE_ECONOMIC_FENCE_MISMATCH',
      COALESCE(expected.timesheet_id,actual.timesheet_id),
      COALESCE(expected.key_type,actual.economic_key_type),
      COALESCE(expected.key_value,actual.economic_key_value),NULL::text,
      jsonb_build_object('expected_truth_ex_vat',expected.truth_ex_vat,
        'actual_truth_ex_vat',actual.truth_ex_vat,
        'expected_baseline_ex_vat',expected.baseline_ex_vat,
        'actual_baseline_ex_vat',actual.baseline_ex_vat,
        'expected_reserved_ex_vat',expected.reserved_ex_vat,
        'actual_reserved_ex_vat',actual.reserved_ex_vat,
        'expected_outstanding_ex_vat',expected.outstanding_ex_vat,
        'actual_outstanding_ex_vat',actual.outstanding_ex_vat)
    FROM pg_temp.tmp_sync_authoritative_components expected
    FULL OUTER JOIN (
      SELECT raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)) AS economic_key_type,
        BTRIM(raw.economic_key_value) AS economic_key_value,
        ROUND(SUM(raw.truth_ex_vat),2) AS truth_ex_vat,
        ROUND(SUM(raw.baseline_ex_vat),2) AS baseline_ex_vat,
        ROUND(SUM(raw.reserved_ex_vat),2) AS reserved_ex_vat,
        ROUND(SUM(raw.outstanding_ex_vat),2) AS outstanding_ex_vat
      FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
      WHERE UPPER(COALESCE(raw.projection_status,'')) IN ('READY','FIXED')
        AND raw.failure_code IS NULL
      GROUP BY raw.timesheet_id,UPPER(BTRIM(raw.economic_key_type)),
        BTRIM(raw.economic_key_value)
    ) actual ON actual.timesheet_id=expected.timesheet_id
      AND actual.economic_key_type=expected.key_type
      AND actual.economic_key_value=expected.key_value
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
      OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
      OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
      OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
      OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat;

    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='[]'::jsonb;

    SELECT failure.failure_code
    INTO v_rate_authority_failure_code
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure
    ORDER BY failure.failure_rank,failure.timesheet_id NULLS FIRST,
      failure.economic_key_type NULLS FIRST,failure.economic_key_value NULLS FIRST,
      failure.physical_bucket_key NULLS FIRST,failure.failure_code
    LIMIT 1;

    SELECT COALESCE(jsonb_agg(jsonb_build_object('failure_rank',failure.failure_rank,
        'failure_code',failure.failure_code,'timesheet_id',failure.timesheet_id,
        'economic_key_type',failure.economic_key_type,
        'economic_key_value',failure.economic_key_value,
        'physical_bucket_key',failure.physical_bucket_key,
        'detail',failure.detail_json) ORDER BY failure.failure_rank,
        failure.timesheet_id NULLS FIRST,failure.economic_key_type NULLS FIRST,
        failure.economic_key_value NULLS FIRST,failure.physical_bucket_key NULLS FIRST,
        failure.failure_code),'[]'::jsonb)
    INTO v_rate_authority_failure_detail
    FROM pg_temp.tmp_sync_sealed_rate_projection_failures failure;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'failures',v_rate_authority_failure_detail)::text;
    END IF;

    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_rate_projection ON COMMIT DROP AS
    SELECT raw.build_id,raw.candidate_id,raw.timesheet_id,raw.financial_row_id,
      raw.source_family_key,raw.economic_key_type,raw.economic_key_value,
      raw.component_kind,raw.component_member_identity,raw.segment_id,raw.segment_key,
      raw.segment_stable_key,raw.bucket_code,raw.bucket_sort_ordinal,
      raw.physical_bucket_key,raw.physical_bucket_digest,raw.source_units,
      raw.source_rate,raw.source_charge_rate,raw.truth_ex_vat,raw.baseline_ex_vat,
      raw.reserved_ex_vat,raw.outstanding_ex_vat,raw.source_charge_ex_vat,
      raw.source_pay_method,raw.target_pay_method,raw.umbrella_id,
      raw.umbrella_enabled,raw.umbrella_vat_chargeable,raw.erni_pct,raw.vat_rate_pct,
      raw.financial_revision_digest,raw.target_authority_digest,
      raw.conversion_context_digest,raw.sealed_evidence_digest,
      raw.projection_status,raw.failure_code,raw.evidence_json
    FROM pg_temp.tmp_sync_sealed_rate_projection_raw raw
    WHERE UPPER(raw.projection_status) IN ('READY','FIXED') AND raw.failure_code IS NULL;

    ALTER TABLE pg_temp.tmp_sync_sealed_rate_projection
      ALTER COLUMN timesheet_id SET NOT NULL,
      ALTER COLUMN economic_key_type SET NOT NULL,
      ALTER COLUMN economic_key_value SET NOT NULL,
      ALTER COLUMN source_family_key SET NOT NULL,
      ALTER COLUMN component_kind SET NOT NULL,
      ALTER COLUMN component_member_identity SET NOT NULL,
      ALTER COLUMN bucket_code SET NOT NULL,
      ALTER COLUMN physical_bucket_key SET NOT NULL,
      ALTER COLUMN physical_bucket_digest SET NOT NULL,
      ALTER COLUMN source_pay_method SET NOT NULL,
      ALTER COLUMN target_pay_method SET NOT NULL,
      ALTER COLUMN projection_status SET NOT NULL,
      ALTER COLUMN evidence_json SET NOT NULL,
      ADD CHECK (projection_status IN ('READY','FIXED')),
      ADD PRIMARY KEY(timesheet_id,economic_key_type,economic_key_value,physical_bucket_key);
    CREATE INDEX tmp_sync_sealed_rate_projection_lookup_idx
      ON pg_temp.tmp_sync_sealed_rate_projection(
        timesheet_id,source_family_key,economic_key_type,economic_key_value,bucket_code);

    /* The legacy pre-Draft renderer is allowed to omit an economic component
       whose live truth is zero.  Preserve every renderer-owned component as-is,
       but retain an exact physical-bucket map so a frozen baseline-only
       component can be supplied from the already validated sealed projection
       when (and only when) the renderer has no owner for that bucket. */
    DROP TABLE IF EXISTS pg_temp.tmp_sync_raw_preview_physical_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_raw_preview_physical_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      component_ordinality bigint NOT NULL,
      physical_bucket_key text NULL,
      component_json jsonb NOT NULL
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_missing_preview_components;
    CREATE TEMP TABLE pg_temp.tmp_sync_sealed_missing_preview_components (
      candidate_id uuid NOT NULL,
      timesheet_id uuid NOT NULL,
      economic_key_type text NOT NULL,
      economic_key_value text NOT NULL,
      bucket_sort_ordinal integer NOT NULL,
      physical_bucket_key text NOT NULL,
      component_json jsonb NOT NULL,
      PRIMARY KEY(candidate_id,timesheet_id,physical_bucket_key)
    ) ON COMMIT DROP;
  END IF;

  v_component_assembly_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_authoritative_components_ms := COALESCE(v_preflight_setup_ms,0)
    + COALESCE(v_correction_residuals_ms,0)
    + COALESCE(v_authority_validation_ms,0)
    + COALESCE(v_component_assembly_ms,0);
  v_phase_started_at := clock_timestamp();
  IF v_requested_candidate_count > 0 THEN
    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT requested_candidate.candidate_id
      FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
      WHERE requested_candidate.candidate_id IS NOT NULL
      ORDER BY requested_candidate.candidate_id
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'candidate_ids', COALESCE(to_jsonb(p_candidate_ids), '[]'::jsonb),
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      )
      || CASE
        WHEN COALESCE(v_authoritative_timesheet_scope, false) THEN
          jsonb_build_object(
            'workbench_source_build_mode', true,
            'source_build_mode', true,
            'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            -- v_workbench_session_id has already passed the exact session,
            -- candidate, version, actor, pay-date and scope authority checks
            -- above.  The existing preview overlay deliberately requires this
            -- explicit session authority before consuming saved rate choices.
            'workbench_resolution_session_id',v_workbench_session_id::text
          )
        ELSE '{}'::jsonb
      END;

      IF COALESCE(v_authoritative_timesheet_scope, false) THEN
        v_phase_started_at := clock_timestamp();
        v_preview_collect_result_json := public.pay_preview_candidate_collect_scope(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
        v_preview_collect_ms := v_preview_collect_ms
          + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

        -- pay_preview_candidate_collect_scope intentionally discovers current
        -- pre-Draft reservation state.  A sealed build must not continue using
        -- those later live rows, so replace the complete reservation workspace
        -- with the RESERVATION_COMPONENT facts captured by this build before
        -- any baseline or component construction consumes it.
        DROP TABLE IF EXISTS pg_temp.tmp_sync_sealed_reservation_items;
        CREATE TEMP TABLE pg_temp.tmp_sync_sealed_reservation_items ON COMMIT DROP AS
        SELECT fact.fact_family||':'||fact.natural_key AS authority_fact_identity,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_item_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_item_id')::uuid END AS pay_batch_item_id,
          CASE WHEN COALESCE(fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json#>>'{pay_batch_item,pay_batch_id}')::uuid
            WHEN COALESCE(fact.source_payload_json->>'pay_batch_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (fact.source_payload_json->>'pay_batch_id')::uuid END AS pay_batch_id,
          fact.timesheet_id,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_key,
          NULLIF(BTRIM(COALESCE(
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_id}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_id}',
            CASE WHEN NULLIF(BTRIM(COALESCE(
                fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref')),'') LIKE 'seg:%'
              THEN split_part(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
                fact.source_payload_json->>'source_ref'),':',2) END,
            fact.source_payload_json#>>'{pay_batch_item,segment_key}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,segment_key}',
            fact.source_payload_json#>>'{frozen_source_basis_json,segment_key}')),'')
            AS segment_id_norm,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{pay_batch_item,source_ref}',
            fact.source_payload_json->>'source_ref')),'') AS source_ref,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{pay_batch_item,item_type}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'OVERPAYMENT_RECOVERY' END,
            CASE UPPER(BTRIM(fact.economic_key_type))
              WHEN 'TS_DAY' THEN 'SEGMENT_DELTA' WHEN 'TS_TOTAL' THEN 'SEGMENT_DELTA'
              WHEN 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
              WHEN 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
              WHEN 'ADDITIONAL_CODE' THEN 'ADJUSTMENT_DELTA'
              ELSE 'ADJUSTMENT_DELTA' END) AS item_type,
          UPPER(BTRIM(fact.economic_key_type)) AS component_key_type,
          BTRIM(fact.economic_key_value) AS component_key_value,
          COALESCE(NULLIF(BTRIM(fact.source_payload_json#>>'{economic_key,key_resolution_source}'),''),
            CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN 'FINANCE_CASE_IDENTITY' END,
            'SEALED_RESERVATION_COMPONENT') AS key_resolution_source,
          NULLIF(BTRIM(COALESCE(fact.source_payload_json#>>'{economic_key,key_resolution_failure_reason}',
            fact.source_payload_json->>'resolution_failure')),'') AS key_resolution_failure_reason,
          ROUND(CASE WHEN case_authority.evidence_count=1
                AND case_authority.distinct_case_type_count=1
                AND case_authority.case_type='OVERPAYMENT'
              THEN -ABS(COALESCE(fact.reserved_source_amount,0))
            ELSE COALESCE(fact.reserved_source_amount,0) END,2) AS amount_ex_vat,
          CASE WHEN jsonb_typeof(fact.source_payload_json->'breakdowns')='array'
            THEN fact.source_payload_json->'breakdowns' ELSE '[]'::jsonb END AS breakdowns
        FROM private.banking_pay_workbench_economic_build_facts fact
        LEFT JOIN pg_temp.tmp_sync_sealed_finance_case_authority case_authority
          ON case_authority.build_id=fact.build_id
         AND case_authority.candidate_id=fact.candidate_id
         AND case_authority.finance_case_id=fact.finance_case_id
        WHERE fact.build_id=p_build_id AND fact.candidate_id=v_preview_candidate_loop_id
          AND fact.fact_family='RESERVATION_COMPONENT'
          AND fact.timesheet_id IS NOT NULL
          AND (NOT v_slice_active OR fact.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_type,'')),'') IS NOT NULL
          AND NULLIF(BTRIM(COALESCE(fact.economic_key_value,'')),'') IS NOT NULL;

        CREATE UNIQUE INDEX tmp_sync_sealed_reservation_items_authority_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(authority_fact_identity);
        CREATE INDEX tmp_sync_sealed_reservation_items_key_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(
            timesheet_id,component_key_type,component_key_value);
        CREATE INDEX tmp_sync_sealed_reservation_items_source_ref_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,source_ref);
        CREATE INDEX tmp_sync_sealed_reservation_items_type_idx
          ON pg_temp.tmp_sync_sealed_reservation_items(timesheet_id,item_type);

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_batch_items_replacement
          (LIKE pg_temp.reserved_batch_items INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_batch_items_replacement(
          pay_batch_item_id,pay_batch_id,timesheet_id,segment_key,segment_id_norm,
          source_ref,item_type,component_key_type,component_key_value,
          key_resolution_source,key_resolution_failure_reason,amount_ex_vat)
        SELECT sealed.pay_batch_item_id,sealed.pay_batch_id,sealed.timesheet_id,
          sealed.segment_key,sealed.segment_id_norm,sealed.source_ref,sealed.item_type,
          sealed.component_key_type,sealed.component_key_value,
          sealed.key_resolution_source,sealed.key_resolution_failure_reason,
          sealed.amount_ex_vat
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement
          (LIKE pg_temp.reserved_by_source_ref INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_by_source_ref_replacement
        SELECT sealed.timesheet_id,sealed.source_ref,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.source_ref IS NOT NULL
        GROUP BY sealed.timesheet_id,sealed.source_ref;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
          (LIKE pg_temp.reserved_total_by_timesheet INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_total_by_timesheet_replacement
        SELECT sealed.timesheet_id,ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        GROUP BY sealed.timesheet_id;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement
          (LIKE pg_temp.reserved_segment_key_map INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_key_map_replacement
        SELECT sealed.timesheet_id,sealed.segment_id_norm,
          sealed.component_key_type,sealed.component_key_value
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$');

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement
          (LIKE pg_temp.reserved_segment_sums INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_segment_sums_replacement
        SELECT sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='SEGMENT_DELTA'
          AND sealed.component_key_type IN ('TS_DAY','TS_TOTAL')
          AND sealed.component_key_value IS NOT NULL
          AND (sealed.component_key_type<>'TS_DAY'
            OR sealed.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        GROUP BY sealed.timesheet_id,sealed.component_key_type,sealed.component_key_value;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
          (LIKE pg_temp.reserved_preview_segment_ords INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_preview_segment_ords_replacement
        SELECT sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END,
          ROUND(SUM(sealed.amount_ex_vat),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        WHERE sealed.item_type='ADJUSTMENT_DELTA'
          AND BTRIM(COALESCE(sealed.source_ref,'')) LIKE 'preview_seg:%'
        GROUP BY sealed.timesheet_id,
          CASE WHEN split_part(COALESCE(sealed.source_ref,''),':',3) ~ '^\d+$'
            THEN split_part(sealed.source_ref,':',3)::integer END;

        CREATE TEMP TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement
          (LIKE pg_temp.reserved_additional_by_code INCLUDING ALL) ON COMMIT DROP;
        INSERT INTO pg_temp.tmp_sync_reserved_additional_by_code_replacement
        SELECT sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
            breakdown.value->>'bucket_code',
            CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
              THEN sealed.component_key_value END)),'')) AS code,
          ROUND(SUM(CASE
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_amount_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value#>>'{meta_json,source_pay_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value#>>'{meta_json,source_pay_ex_vat}')::numeric)
            WHEN COALESCE(breakdown.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              THEN ABS((breakdown.value->>'amount_ex_vat')::numeric)
            ELSE ABS(sealed.amount_ex_vat) END),2)
        FROM pg_temp.tmp_sync_sealed_reservation_items sealed
        LEFT JOIN LATERAL jsonb_array_elements(CASE
          WHEN jsonb_typeof(sealed.breakdowns)='array' AND jsonb_array_length(sealed.breakdowns)>0
            THEN sealed.breakdowns
          WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN jsonb_build_array(jsonb_build_object(
              'bucket_code',sealed.component_key_value,
              'amount_ex_vat',sealed.amount_ex_vat,
              'line_kind','ADDITIONAL_UNIT'))
          ELSE '[]'::jsonb END) breakdown(value) ON true
        WHERE (breakdown.value->>'line_kind'='ADDITIONAL_UNIT'
            OR sealed.component_key_type='ADDITIONAL_CODE')
          AND NULLIF(BTRIM(COALESCE(breakdown.value->>'bucket_code',
            sealed.component_key_value)),'') IS NOT NULL
        GROUP BY sealed.timesheet_id,UPPER(NULLIF(BTRIM(COALESCE(
          breakdown.value->>'bucket_code',
          CASE WHEN sealed.component_key_type='ADDITIONAL_CODE'
            THEN sealed.component_key_value END)),''));

        DROP TABLE pg_temp.reserved_batch_items,pg_temp.reserved_by_source_ref,
          pg_temp.reserved_total_by_timesheet,pg_temp.reserved_segment_key_map,
          pg_temp.reserved_segment_sums,pg_temp.reserved_preview_segment_ords,
          pg_temp.reserved_additional_by_code;
        ALTER TABLE pg_temp.tmp_sync_reserved_batch_items_replacement RENAME TO reserved_batch_items;
        ALTER TABLE pg_temp.tmp_sync_reserved_by_source_ref_replacement RENAME TO reserved_by_source_ref;
        ALTER TABLE pg_temp.tmp_sync_reserved_total_by_timesheet_replacement RENAME TO reserved_total_by_timesheet;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_key_map_replacement RENAME TO reserved_segment_key_map;
        ALTER TABLE pg_temp.tmp_sync_reserved_segment_sums_replacement RENAME TO reserved_segment_sums;
        ALTER TABLE pg_temp.tmp_sync_reserved_preview_segment_ords_replacement RENAME TO reserved_preview_segment_ords;
        ALTER TABLE pg_temp.tmp_sync_reserved_additional_by_code_replacement RENAME TO reserved_additional_by_code;

        IF to_regclass('pg_temp.ts_baseline') IS NULL
           OR to_regclass('pg_temp.pay_preview_candidate_context') IS NULL THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_INPUT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          LEFT JOIN pg_temp.ts_baseline baseline
            ON baseline.candidate_id=v_preview_candidate_loop_id
           AND baseline.timesheet_id=sealed.timesheet_id
          WHERE baseline.timesheet_id IS NULL
        ) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE'
            USING ERRCODE='23514';
        END IF;

        UPDATE pg_temp.pay_preview_candidate_context context_row
        SET erni_pct=authority.erni_pct,vat_rate_pct=authority.vat_rate_pct
        FROM (
          SELECT MIN(sealed.erni_pct) AS erni_pct,MIN(sealed.vat_rate_pct) AS vat_rate_pct
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        ) authority
        WHERE context_row.candidate_id=v_preview_candidate_loop_id;

        WITH segment_bucket_rows AS (
          SELECT sealed.*,
            CASE WHEN COALESCE(sealed.evidence_json#>>'{source_ordinal}','') ~ '^\d+$'
              THEN (sealed.evidence_json#>>'{source_ordinal}')::bigint ELSE 0 END
              AS source_ordinal,
            CASE WHEN jsonb_typeof(sealed.evidence_json#>'{source_payload,segment}')='object'
              THEN sealed.evidence_json#>'{source_payload,segment}' ELSE '{}'::jsonb END
              AS source_segment,
            COALESCE(sealed.segment_stable_key,sealed.segment_id,sealed.segment_key,
              CASE WHEN sealed.component_kind='WORKED_TIME_RESIDUAL'
                THEN 'worked-time-residual:'||sealed.economic_key_type||':'
                  ||sealed.economic_key_value END) AS builder_segment_identity
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.component_kind IN ('WORKED_TIME','WORKED_TIME_RESIDUAL')
        ), segment_grouped AS (
          SELECT segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value,
            COALESCE(MIN(segment.segment_id),segment.builder_segment_identity) AS segment_id,
            COALESCE(MIN(segment.segment_key),segment.builder_segment_identity) AS segment_key,
            MIN(segment.source_ordinal) AS source_ordinal,
            (array_agg(segment.source_segment ORDER BY segment.source_ordinal,
              segment.builder_segment_identity,segment.segment_id))[1]
              ||jsonb_build_object(
                'segment_id',COALESCE(MIN(segment.segment_id),segment.builder_segment_identity),
                'segment_key',COALESCE(MIN(segment.segment_key),segment.builder_segment_identity),
                'segment_stable_key',segment.builder_segment_identity,
                'date',MIN(COALESCE(segment.source_segment->>'date',
                  segment.source_segment->>'work_date',CASE
                    WHEN segment.economic_key_type='TS_DAY' THEN segment.economic_key_value END)),
                'hours_day',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='DAY'),0),6),
                'hours_night',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='NIGHT'),0),6),
                'hours_sat',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SAT'),0),6),
                'hours_sun',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='SUN'),0),6),
                'hours_bh',ROUND(COALESCE(SUM(segment.source_units)
                  FILTER(WHERE segment.bucket_code='BH'),0),6),
                'pay_amount',ROUND(SUM(segment.truth_ex_vat),2),
                'charge_amount',ROUND(SUM(COALESCE(segment.source_charge_ex_vat,0)),2))
              AS segment_json
          FROM segment_bucket_rows segment
          GROUP BY segment.timesheet_id,segment.builder_segment_identity,
            segment.economic_key_type,segment.economic_key_value
        ), segments_by_timesheet AS (
          SELECT grouped.timesheet_id,jsonb_agg(grouped.segment_json ORDER BY
            grouped.source_ordinal,grouped.builder_segment_identity,grouped.segment_id)
              AS segments_json
          FROM segment_grouped grouped GROUP BY grouped.timesheet_id
        ), additional_by_timesheet AS (
          SELECT additional.timesheet_id,
            COALESCE(jsonb_object_agg(
              additional.evidence_json#>>'{source_payload,raw_additional_code}',
              additional.evidence_json#>'{source_payload,source_value}' ORDER BY
              octet_length(additional.evidence_json#>>'{source_payload,raw_additional_code}'),
              encode(convert_to(additional.evidence_json#>>'{source_payload,raw_additional_code}',
                'UTF8'),'hex')),'{}'::jsonb) AS additional_json,
            ROUND(SUM(additional.truth_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(SUM(COALESCE(additional.source_charge_ex_vat,0)),2)
              AS additional_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection additional
          WHERE additional.component_kind='ADDITIONAL_UNIT'
            AND COALESCE(additional.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
            AND NULLIF(additional.evidence_json#>>'{source_payload,raw_additional_code}','')
              IS NOT NULL
          GROUP BY additional.timesheet_id
        ), adjustments_by_timesheet AS (
          SELECT adjustment.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',adjustment.evidence_json#>>'{source_payload,adjustment_id}',
              'delta_pay_ex_vat',ROUND(adjustment.truth_ex_vat,2))
            ORDER BY adjustment.evidence_json#>>'{source_payload,adjustment_id}') AS adjustments_json
          FROM pg_temp.tmp_sync_sealed_rate_projection adjustment
          WHERE adjustment.component_kind='ADJUSTMENT'
            AND COALESCE(adjustment.evidence_json->>'source_key','') NOT LIKE 'SEALED_SYNTHETIC:%'
          GROUP BY adjustment.timesheet_id
        ), economic_projection_totals AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.truth_ex_vat),2) AS truth_ex_vat,
            ROUND(SUM(sealed.baseline_ex_vat),2) AS baseline_ex_vat,
            ROUND(SUM(sealed.reserved_ex_vat),2) AS reserved_ex_vat,
            MIN(CASE WHEN COALESCE(sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{economic_authority,baseline_inc_vat}')::numeric END)
              AS baseline_inc_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_keys AS (
          SELECT total.*
          FROM economic_projection_totals total
          WHERE ABS(total.truth_ex_vat)<=0.005 AND ABS(total.baseline_ex_vat)>0.005
        ), baseline_only_physical_evidence AS (
          SELECT sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value,
            ROUND(SUM(sealed.source_charge_ex_vat),2) AS source_charge_ex_vat,
            (array_agg(sealed.evidence_json#>'{source_payload,source_value}' ORDER BY
              sealed.physical_bucket_key))[1] AS source_value
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          JOIN baseline_only_keys baseline
            USING(timesheet_id,economic_key_type,economic_key_value)
          GROUP BY sealed.timesheet_id,sealed.economic_key_type,sealed.economic_key_value
        ), baseline_only_active_artifacts AS (
          SELECT baseline.timesheet_id,
            jsonb_agg(jsonb_build_object(
              'key_type',baseline.economic_key_type,
              'key_value',baseline.economic_key_value,
              'amount_ex_vat',baseline.baseline_ex_vat,
              'amount_inc_vat',COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat),
              'baseline_source','SEALED_BUILD_FACTS') ORDER BY
              baseline.economic_key_type,baseline.economic_key_value) AS components_json,
            COUNT(*)::integer AS component_count,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS amount_ex_vat,
            ROUND(SUM(COALESCE(baseline.baseline_inc_vat,baseline.baseline_ex_vat)),2)
              AS amount_inc_vat
          FROM baseline_only_keys baseline GROUP BY baseline.timesheet_id
        ), baseline_only_expenses AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS expenses_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS expenses_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),2) AS travel_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='TRAVEL'),0),2) AS travel_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),2) AS accommodation_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),2) AS other_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='OTHER'),0),2) AS other_charge_ex_vat,
            ROUND(SUM(baseline.baseline_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),2) AS mileage_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat) FILTER(
              WHERE baseline.economic_key_value='MILEAGE'),0),2) AS mileage_charge_ex_vat
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='EXPENSE_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_additional AS (
          SELECT baseline.timesheet_id,
            ROUND(SUM(baseline.baseline_ex_vat),2) AS additional_pay_ex_vat,
            ROUND(-COALESCE(SUM(sealed.source_charge_ex_vat),0),2) AS additional_charge_ex_vat,
            COALESCE(jsonb_object_agg(baseline.economic_key_value,
              COALESCE(sealed.source_value,
                jsonb_build_object('source_pay_ex_vat',baseline.baseline_ex_vat))
              ORDER BY octet_length(baseline.economic_key_value),
                encode(convert_to(baseline.economic_key_value,'UTF8'),'hex')),'{}'::jsonb)
              AS additional_units_json
          FROM baseline_only_keys baseline
          LEFT JOIN baseline_only_physical_evidence sealed
            USING(timesheet_id,economic_key_type,economic_key_value)
          WHERE baseline.economic_key_type='ADDITIONAL_CODE'
          GROUP BY baseline.timesheet_id
        ), baseline_only_adjustments AS (
          SELECT baseline.timesheet_id,jsonb_agg(jsonb_build_object(
              'id',baseline.economic_key_value,
              'pay_amount_ex_vat',baseline.baseline_ex_vat,
              'source_pay_ex_vat',baseline.baseline_ex_vat)
            ORDER BY baseline.economic_key_value) AS adjustments_json
          FROM baseline_only_keys baseline
          WHERE baseline.economic_key_type='ADJUSTMENT_CODE'
          GROUP BY baseline.timesheet_id
        ), timesheet_authority AS (
          SELECT sealed.timesheet_id,
            (jsonb_agg(DISTINCT sealed.source_pay_method ORDER BY sealed.source_pay_method)->>0)
              AS source_pay_method,
            MIN(sealed.target_pay_method) AS target_pay_method,
            MIN(sealed.umbrella_id::text)::uuid AS umbrella_id,
            bool_and(sealed.umbrella_enabled) AS umbrella_enabled,
            bool_and(sealed.umbrella_vat_chargeable) AS umbrella_vat_chargeable,
            ROUND(COALESCE(SUM(sealed.source_units)
              FILTER(WHERE sealed.component_kind='WORKED_TIME'),0),6) AS total_hours,
            ROUND(SUM(sealed.truth_ex_vat),2) AS total_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE ABS(sealed.truth_ex_vat)>0.005),0),2) AS total_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='DAY'),0),6)
              AS hours_day,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='NIGHT'),0),6)
              AS hours_night,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SAT'),0),6)
              AS hours_sat,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='SUN'),0),6)
              AS hours_sun,
            ROUND(COALESCE(SUM(sealed.source_units) FILTER(WHERE sealed.bucket_code='BH'),0),6)
              AS hours_bh,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='DAY') AS pay_day,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS pay_night,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SAT') AS pay_sat,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='SUN') AS pay_sun,
            MIN(sealed.source_rate) FILTER(WHERE sealed.bucket_code='BH') AS pay_bh,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='DAY') AS charge_day,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='NIGHT') AS charge_night,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SAT') AS charge_sat,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='SUN') AS charge_sun,
            MIN(sealed.source_charge_rate) FILTER(WHERE sealed.bucket_code='BH') AS charge_bh,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'),0),2) AS expenses_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE'
                AND ABS(sealed.truth_ex_vat)>0.005),0),2) AS expenses_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='TRAVEL'),0),2)
              AS travel_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='ACCOMMODATION'),0),2)
              AS accommodation_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='OTHER'),0),2)
              AS other_charge_ex_vat,
            ROUND(COALESCE(SUM(sealed.truth_ex_vat) FILTER(WHERE sealed.component_kind='EXPENSE'
              AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_pay_ex_vat,
            ROUND(COALESCE(SUM(sealed.source_charge_ex_vat)
              FILTER(WHERE sealed.component_kind='EXPENSE' AND ABS(sealed.truth_ex_vat)>0.005
                AND sealed.evidence_json#>>'{source_payload,expense_code}'='MILEAGE'),0),2)
              AS mileage_charge_ex_vat
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed GROUP BY sealed.timesheet_id
        )
        UPDATE pg_temp.ts_baseline baseline
        SET ts_pay_method=authority.source_pay_method,
          cand_pay_method=authority.target_pay_method,
          cand_umbrella_id=authority.umbrella_id,
          umb_enabled=authority.umbrella_enabled,
          umb_vat_chargeable=authority.umbrella_vat_chargeable,
          base_json=jsonb_build_object(
            'baseline_source','SEALED_BUILD_FACTS',
            'active_settled_artifact_components',COALESCE(active.components_json,'[]'::jsonb),
            'active_settled_amount_ex_vat',COALESCE(active.amount_ex_vat,0),
            'active_settled_amount_inc_vat',COALESCE(active.amount_inc_vat,0),
            'segments','[]'::jsonb,
            'additional_pay_ex_vat',COALESCE(baseline_additional.additional_pay_ex_vat,0),
            'additional_charge_ex_vat',COALESCE(baseline_additional.additional_charge_ex_vat,0),
            'additional_units_json',COALESCE(baseline_additional.additional_units_json,'{}'::jsonb),
            'expenses',jsonb_build_object(
              'expenses_pay_ex_vat',COALESCE(baseline_expenses.expenses_pay_ex_vat,0),
              'expenses_charge_ex_vat',COALESCE(baseline_expenses.expenses_charge_ex_vat,0),
              'travel_pay_ex_vat',COALESCE(baseline_expenses.travel_pay_ex_vat,0),
              'travel_charge_ex_vat',COALESCE(baseline_expenses.travel_charge_ex_vat,0),
              'accommodation_pay_ex_vat',COALESCE(baseline_expenses.accommodation_pay_ex_vat,0),
              'accommodation_charge_ex_vat',COALESCE(baseline_expenses.accommodation_charge_ex_vat,0),
              'other_pay_ex_vat',COALESCE(baseline_expenses.other_pay_ex_vat,0),
              'other_charge_ex_vat',COALESCE(baseline_expenses.other_charge_ex_vat,0),
              'mileage_pay_ex_vat',COALESCE(baseline_expenses.mileage_pay_ex_vat,0),
              'mileage_charge_ex_vat',COALESCE(baseline_expenses.mileage_charge_ex_vat,0)),
            'adjustments',COALESCE(baseline_adjustments.adjustments_json,'[]'::jsonb)),
          active_settled_artifact_components_json=COALESCE(active.components_json,'[]'::jsonb),
          active_settled_artifact_component_count=COALESCE(active.component_count,0),
          active_settled_artifact_amount_ex_vat=COALESCE(active.amount_ex_vat,0),
          active_settled_artifact_amount_inc_vat=COALESCE(active.amount_inc_vat,0),
          has_active_settled_artifact_baseline=COALESCE(active.component_count,0)>0,
          bas_hours_day=0,bas_hours_night=0,bas_hours_sat=0,bas_hours_sun=0,bas_hours_bh=0,
          bas_pay_day=NULL,bas_pay_night=NULL,bas_pay_sat=NULL,bas_pay_sun=NULL,bas_pay_bh=NULL,
          bas_charge_day=NULL,bas_charge_night=NULL,bas_charge_sat=NULL,
          bas_charge_sun=NULL,bas_charge_bh=NULL,
          current_segments_json=COALESCE(segments.segments_json,'[]'::jsonb),
          current_adjustments_json=COALESCE(adjustments.adjustments_json,'[]'::jsonb),
          total_hours=authority.total_hours,total_pay_ex_vat=authority.total_pay_ex_vat,
          total_charge_ex_vat=authority.total_charge_ex_vat,
          hours_day=authority.hours_day,hours_night=authority.hours_night,
          hours_sat=authority.hours_sat,hours_sun=authority.hours_sun,hours_bh=authority.hours_bh,
          pay_day=authority.pay_day,pay_night=authority.pay_night,pay_sat=authority.pay_sat,
          pay_sun=authority.pay_sun,pay_bh=authority.pay_bh,
          charge_day=authority.charge_day,charge_night=authority.charge_night,
          charge_sat=authority.charge_sat,charge_sun=authority.charge_sun,
          charge_bh=authority.charge_bh,
          cur_hours_day=authority.hours_day,cur_hours_night=authority.hours_night,
          cur_hours_sat=authority.hours_sat,cur_hours_sun=authority.hours_sun,
          cur_hours_bh=authority.hours_bh,
          cur_pay_day=authority.pay_day,cur_pay_night=authority.pay_night,
          cur_pay_sat=authority.pay_sat,cur_pay_sun=authority.pay_sun,cur_pay_bh=authority.pay_bh,
          cur_charge_day=authority.charge_day,cur_charge_night=authority.charge_night,
          cur_charge_sat=authority.charge_sat,cur_charge_sun=authority.charge_sun,
          cur_charge_bh=authority.charge_bh,
          current_additional_units_json=COALESCE(additional.additional_json,'{}'::jsonb),
          current_additional_pay_ex_vat=COALESCE(additional.additional_pay_ex_vat,0),
          current_additional_charge_ex_vat=COALESCE(additional.additional_charge_ex_vat,0),
          current_expenses_pay_ex_vat=authority.expenses_pay_ex_vat,
          current_expenses_charge_ex_vat=authority.expenses_charge_ex_vat,
          current_travel_pay_ex_vat=authority.travel_pay_ex_vat,
          current_travel_charge_ex_vat=authority.travel_charge_ex_vat,
          current_accommodation_pay_ex_vat=authority.accommodation_pay_ex_vat,
          current_accommodation_charge_ex_vat=authority.accommodation_charge_ex_vat,
          current_other_pay_ex_vat=authority.other_pay_ex_vat,
          current_other_charge_ex_vat=authority.other_charge_ex_vat,
          current_mileage_pay_ex_vat=authority.mileage_pay_ex_vat,
          current_mileage_charge_ex_vat=authority.mileage_charge_ex_vat
        FROM timesheet_authority authority
        LEFT JOIN segments_by_timesheet segments USING(timesheet_id)
        LEFT JOIN additional_by_timesheet additional USING(timesheet_id)
        LEFT JOIN adjustments_by_timesheet adjustments USING(timesheet_id)
        LEFT JOIN baseline_only_active_artifacts active USING(timesheet_id)
        LEFT JOIN baseline_only_expenses baseline_expenses USING(timesheet_id)
        LEFT JOIN baseline_only_additional baseline_additional USING(timesheet_id)
        LEFT JOIN baseline_only_adjustments baseline_adjustments USING(timesheet_id)
        WHERE baseline.candidate_id=v_preview_candidate_loop_id
          AND baseline.timesheet_id=authority.timesheet_id;

        IF v_execution_profile_version=2 THEN
          v_phase_started_at := clock_timestamp();
          v_preview_canonical_result_json := public.pay_preview_candidate_build_canonical_lines(
            p_context_json => v_preview_context_json,
            p_candidate_id => v_preview_candidate_loop_id
          );
          v_preview_canonical_ms := v_preview_canonical_ms
            + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
        END IF;
      END IF;

      v_phase_started_at := clock_timestamp();
      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );
      v_preview_summary_ms := v_preview_summary_ms
        + FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

      IF jsonb_typeof(COALESCE(v_preview_baseline_json, '{}'::jsonb)) <> 'object' THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_BASELINE_INVALID',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND COALESCE(v_authoritative_negative_component_count, 0) > 0
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NULL THEN
        PERFORM public.pay_preview_candidate_build_case_component_rows(
          p_context_json => v_preview_context_json,
          p_candidate_id => v_preview_candidate_loop_id
        );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope,false) THEN
        DELETE FROM pg_temp.tmp_sync_raw_preview_physical_components
        WHERE candidate_id=v_preview_candidate_loop_id;
        DELETE FROM pg_temp.tmp_sync_sealed_missing_preview_components
        WHERE candidate_id=v_preview_candidate_loop_id;

        IF to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
          INSERT INTO pg_temp.tmp_sync_raw_preview_physical_components(
            candidate_id,timesheet_id,component_ordinality,physical_bucket_key,
            component_json
          )
          SELECT raw_case.candidate_id,raw_case.timesheet_id,
            raw_component.ordinality::bigint,
            concat_ws('|','RATE_BUCKET_V1',raw_case.timesheet_id::text,
              NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
              UPPER(NULLIF(BTRIM(raw_component.value->>'component_key_type'),'')),
              NULLIF(BTRIM(raw_component.value->>'component_key_value'),''),
              CASE
                WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT'
                  THEN 'worked-time-residual:'
                    ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                    ||BTRIM(raw_component.value->>'component_key_value')
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))
                    IN ('TS_DAY','TS_TOTAL')
                  THEN COALESCE(
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                    NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                  THEN 'additional:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                  THEN 'expense:'
                    ||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                  THEN 'adjustment:'
                    ||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
              END,
              UPPER(BTRIM(COALESCE(
                CASE WHEN UPPER(BTRIM(COALESCE(
                    raw_component.value#>>'{source_basis_json,component_fallback}','')))
                      ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                  WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                  WHEN 'EXPENSE_CODE' THEN 'FIXED'
                  WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                END)))) AS physical_bucket_key,
            raw_component.value
          FROM pg_temp.timesheet_case_rollup raw_case
          CROSS JOIN LATERAL jsonb_array_elements(CASE
            WHEN jsonb_typeof(raw_case.case_components_json)='array'
              THEN raw_case.case_components_json ELSE '[]'::jsonb END)
            WITH ORDINALITY raw_component(value,ordinality)
          WHERE raw_case.candidate_id=v_preview_candidate_loop_id;
        END IF;

        IF EXISTS(
          SELECT 1
          FROM pg_temp.tmp_sync_sealed_rate_projection sealed
          WHERE sealed.candidate_id=v_preview_candidate_loop_id
            AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
            AND sealed.evidence_json#>>'{source_payload,source_kind}'
              IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
            AND jsonb_typeof(CASE
              WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
                THEN sealed.evidence_json#>'{source_payload,segment}'
              ELSE sealed.evidence_json#>'{source_payload,source_value}' END)<>'object'
        ) THEN
          RAISE EXCEPTION 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE',
              'candidate_id',v_preview_candidate_loop_id::text,
              'message','A sealed builder component has no complete frozen source basis.'
            )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_sealed_missing_preview_components(
          candidate_id,timesheet_id,economic_key_type,economic_key_value,
          bucket_sort_ordinal,physical_bucket_key,component_json
        )
        SELECT sealed.candidate_id,sealed.timesheet_id,sealed.economic_key_type,
          sealed.economic_key_value,sealed.bucket_sort_ordinal,sealed.physical_bucket_key,
          jsonb_strip_nulls(jsonb_build_object(
            'source_family_key',sealed.source_family_key,
            'component_key_type',sealed.economic_key_type,
            'component_key_value',sealed.economic_key_value,
            'component_kind',sealed.component_kind,
            'component_member_identity',sealed.component_member_identity,
            'classification',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
              THEN 'REIMBURSEMENT_GROSS_FIXED' ELSE 'TAXABLE_CHANNEL_SENSITIVE' END,
            'source_pay_method',sealed.source_pay_method,
            'current_target_pay_method',sealed.target_pay_method,
            'source_basis_json',
              bridge.source_basis_json
              ||jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id',sealed.timesheet_id::text,
                'source_family_key',sealed.source_family_key,
                'component_key_type',sealed.economic_key_type,
                'component_key_value',sealed.economic_key_value,
                'segment_id',sealed.segment_id,
                'segment_key',COALESCE(sealed.segment_key,sealed.segment_id),
                'segment_stable_key',sealed.segment_stable_key,
                'work_date',COALESCE(
                  bridge.source_basis_json->>'work_date',
                  bridge.source_basis_json->>'date'),
                'ref_num',bridge.source_basis_json->>'ref_num',
                'additional_code',CASE WHEN sealed.economic_key_type='ADDITIONAL_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'expense_code',CASE WHEN sealed.economic_key_type='EXPENSE_CODE'
                  THEN UPPER(sealed.economic_key_value) END,
                'adjustment_id',CASE WHEN sealed.economic_key_type='ADJUSTMENT_CODE'
                  THEN sealed.economic_key_value END,
                'bucket_code',sealed.bucket_code,
                'source_pay_method',sealed.source_pay_method)),
            'source_units',sealed.source_units,
            'source_rate',sealed.source_rate,
            'source_charge_rate',sealed.source_charge_rate,
            'source_pay_ex_vat',sealed.outstanding_ex_vat,
            'source_charge_ex_vat',sealed.source_charge_ex_vat,
            'component_amount_ex_vat',sealed.outstanding_ex_vat,
            'authoritative_truth_ex_vat',sealed.truth_ex_vat,
            'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
            'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
            'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
            'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
            'physical_bucket_key',sealed.physical_bucket_key,
            'physical_bucket_digest',sealed.physical_bucket_digest,
            'sealed_evidence_digest',sealed.sealed_evidence_digest,
            'financial_revision_digest',sealed.financial_revision_digest,
            'target_authority_digest',sealed.target_authority_digest,
            'conversion_context_digest',sealed.conversion_context_digest
          )) AS component_json
        FROM pg_temp.tmp_sync_sealed_rate_projection sealed
        CROSS JOIN LATERAL (
          SELECT CASE
            WHEN sealed.evidence_json#>>'{source_payload,source_kind}'='SEGMENT'
              THEN sealed.evidence_json#>'{source_payload,segment}'
            ELSE sealed.evidence_json#>'{source_payload,source_value}'
          END AS source_basis_json
        ) bridge
        WHERE sealed.candidate_id=v_preview_candidate_loop_id
          AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
          AND sealed.evidence_json#>>'{source_payload,source_kind}'
            IN ('SEGMENT','SEALED_BASELINE_COMPONENT','WORKED_TIME_RESIDUAL')
          AND jsonb_typeof(bridge.source_basis_json)='object'
          AND NOT EXISTS(
            SELECT 1
            FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
            WHERE raw_component.candidate_id=sealed.candidate_id
              AND raw_component.timesheet_id=sealed.timesheet_id
              AND raw_component.physical_bucket_key=sealed.physical_bucket_key
          );
      END IF;

      IF COALESCE(v_authoritative_timesheet_scope, false)
         AND to_regclass('pg_temp.timesheet_case_rollup') IS NOT NULL THEN
        IF EXISTS (
          WITH correction_residuals AS (
            SELECT residual.value AS residual_json
            FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
              v_workbench_session_id_text::uuid,
              v_preview_candidate_loop_id,
              NULL::uuid,
              'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA'
            )) AS residual(value)
            WHERE COALESCE((residual.value->>'draftable')::boolean, false)
          ), correction_member_roots AS (
            SELECT DISTINCT
              member_id.value::uuid AS member_timesheet_id,
              (residual.residual_json->>'root_timesheet_id')::uuid AS root_timesheet_id
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements_text(
              COALESCE(residual.residual_json->'member_timesheet_ids', '[]'::jsonb)
            ) AS member_id(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND member_id.value
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          ), correction_component_totals AS (
            SELECT
              (residual.residual_json->>'root_timesheet_id')::uuid AS timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              1::integer AS preview_component_count,
              ROUND(
                (component.value->>'truth_ex_vat')::numeric,
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM correction_residuals AS residual
            CROSS JOIN LATERAL jsonb_array_elements(
              COALESCE(residual.residual_json->'components', '[]'::jsonb)
            ) AS component(value)
            WHERE COALESCE(residual.residual_json->>'root_timesheet_id', '')
                    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND COALESCE(component.value->>'truth_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND ROUND(
                    COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0),
                    2
                  ) < 0
          ), raw_preview_component_totals AS (
            SELECT
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(raw_component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS preview_component_count,
              ROUND(
                SUM((raw_component.value->>'component_amount_ex_vat')::numeric),
                2
              )::numeric(12,2) AS preview_truth_ex_vat
            FROM pg_temp.timesheet_case_rollup AS raw_case
            CROSS JOIN LATERAL jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(raw_case.case_components_json) = 'array'
                  THEN COALESCE(raw_case.case_components_json, '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS raw_component(value)
            WHERE raw_case.candidate_id = v_preview_candidate_loop_id
              AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
              AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
              AND NOT EXISTS (
                SELECT 1
                FROM correction_member_roots AS correction_member
                WHERE correction_member.member_timesheet_id = raw_case.timesheet_id
              )
              AND COALESCE(raw_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_case.timesheet_id,
              UPPER(BTRIM(COALESCE(raw_component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(raw_component.value->>'component_key_value', ''))
          ), preview_component_totals AS (
            SELECT * FROM correction_component_totals
            UNION ALL
            SELECT * FROM raw_preview_component_totals
          ), sealed_baseline_only_keys AS (
            SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
              sealed.economic_key_value AS key_value
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            GROUP BY sealed.timesheet_id,sealed.economic_key_type,
              sealed.economic_key_value
            HAVING COUNT(*)=COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{source_payload,source_kind}'=
                  'SEALED_BASELINE_COMPONENT')
              AND COUNT(*) FILTER(WHERE
                sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true')>0
              AND ROUND(SUM(sealed.truth_ex_vat),2)=0
              AND ROUND(SUM(sealed.outstanding_ex_vat),2)<0
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN preview_component_totals AS preview_total
            ON preview_total.timesheet_id = authoritative_component.timesheet_id
           AND preview_total.key_type = authoritative_component.key_type
           AND preview_total.key_value = authoritative_component.key_value
          LEFT JOIN sealed_baseline_only_keys sealed_baseline
            ON sealed_baseline.timesheet_id=authoritative_component.timesheet_id
           AND sealed_baseline.key_type=authoritative_component.key_type
           AND sealed_baseline.key_value=authoritative_component.key_value
          WHERE (
                  (
                    preview_total.preview_component_count IS NULL
                    AND ABS(ROUND(authoritative_component.truth_ex_vat, 2)) > 0.01
                  )
                  OR (
                    preview_total.preview_component_count IS NOT NULL
                    AND ABS(ROUND(
                      preview_total.preview_truth_ex_vat
                      - authoritative_component.truth_ex_vat,
                      2
                    )) > 0.01
                  )
                )
            AND sealed_baseline.timesheet_id IS NULL
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'authoritative_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_component.timesheet_id::text,
                        'key_type', bounded_component.key_type,
                        'key_value', bounded_component.key_value,
                        'truth_ex_vat', bounded_component.truth_ex_vat,
                        'outstanding_ex_vat', bounded_component.outstanding_ex_vat
                      ) ORDER BY bounded_component.timesheet_id, bounded_component.key_type, bounded_component.key_value), '[]'::jsonb)
                      FROM (
                        SELECT *
                        FROM pg_temp.tmp_sync_authoritative_negative_components
                        ORDER BY timesheet_id, key_type, key_value
                        LIMIT 10
                      ) AS bounded_component
                    ),
                    'correction_component_sample', (
                      SELECT COALESCE(jsonb_agg(jsonb_build_object(
                        'timesheet_id', bounded_correction.root_timesheet_id,
                        'key_type', bounded_correction.key_type,
                        'key_value', bounded_correction.key_value,
                        'truth_ex_vat', bounded_correction.truth_ex_vat,
                        'outstanding_ex_vat', bounded_correction.outstanding_ex_vat
                      ) ORDER BY bounded_correction.root_timesheet_id, bounded_correction.key_type, bounded_correction.key_value), '[]'::jsonb)
                      FROM (
                        SELECT
                          residual.value->>'root_timesheet_id' AS root_timesheet_id,
                          UPPER(BTRIM(component.value->>'component_key_type')) AS key_type,
                          BTRIM(component.value->>'component_key_value') AS key_value,
                          component.value->>'truth_ex_vat' AS truth_ex_vat,
                          component.value->>'target_outstanding_ex_vat' AS outstanding_ex_vat
                        FROM jsonb_array_elements(public._ctms_candidate_correction_residuals_v1(
                          v_workbench_session_id_text::uuid,
                          v_preview_candidate_loop_id,
                          NULL::uuid,
                          'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_METADATA_DIAGNOSTIC'
                        )) AS residual(value)
                        CROSS JOIN LATERAL jsonb_array_elements(
                          COALESCE(residual.value->'components', '[]'::jsonb)
                        ) AS component(value)
                        WHERE COALESCE((residual.value->>'draftable')::boolean, false)
                          AND ROUND(COALESCE(NULLIF(component.value->>'target_outstanding_ex_vat', '')::numeric, 0), 2) < 0
                        ORDER BY residual.value->>'root_timesheet_id',
                                 UPPER(BTRIM(component.value->>'component_key_type')),
                                 BTRIM(component.value->>'component_key_value')
                        LIMIT 10
                      ) AS bounded_correction
                    ),
                    'message', 'Canonical negative component keys were not represented by preview metadata whose current component totals match authoritative live truth.'
                  )::text;
        END IF;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows (
          candidate_id,
          timesheet_id,
          client_id,
          candidate_pay_method,
          case_is_blocked,
          case_components_json
        )
        SELECT
          raw_case.candidate_id,
          raw_case.timesheet_id,
          raw_case.client_id,
          (SELECT MIN(sealed.target_pay_method)
            FROM pg_temp.tmp_sync_sealed_rate_projection sealed
            WHERE sealed.timesheet_id=raw_case.timesheet_id),
          COALESCE(raw_case.is_blocked, false),
          COALESCE((
            SELECT jsonb_agg(
              raw_component.value
              || jsonb_build_object(
                'component_amount_ex_vat',sealed.outstanding_ex_vat,
                'authoritative_truth_ex_vat',sealed.truth_ex_vat,
                'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
                'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
                'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
                'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
                'physical_bucket_key',sealed.physical_bucket_key,
                'physical_bucket_digest',sealed.physical_bucket_digest,
                'sealed_evidence_digest',sealed.sealed_evidence_digest
              )
              ORDER BY sealed.economic_key_type,sealed.economic_key_value,
                sealed.bucket_sort_ordinal,sealed.physical_bucket_key
            )
            FROM jsonb_array_elements(CASE
              WHEN jsonb_typeof(raw_case.case_components_json)='array'
                THEN raw_case.case_components_json ELSE '[]'::jsonb END)
              WITH ORDINALITY raw_component(value,ordinality)
            JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
              ON sealed.timesheet_id=raw_case.timesheet_id
             AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
             AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
             AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
               raw_case.timesheet_id::text,
               NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
               UPPER(BTRIM(raw_component.value->>'component_key_type')),
               BTRIM(raw_component.value->>'component_key_value'),
               CASE
                 WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT'
                   THEN 'worked-time-residual:'
                     ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
                     ||BTRIM(raw_component.value->>'component_key_value')
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
                   THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
                     NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
                   THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
                   THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
                 WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
                   THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
               END,
               UPPER(BTRIM(COALESCE(
                 CASE WHEN UPPER(BTRIM(COALESCE(
                     raw_component.value#>>'{source_basis_json,component_fallback}','')))
                       ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
                 NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
                 CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
                   WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
                   WHEN 'EXPENSE_CODE' THEN 'FIXED'
                   WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
                 END))))
            JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
              ON negative_component.timesheet_id=sealed.timesheet_id
             AND negative_component.key_type=sealed.economic_key_type
             AND negative_component.key_value=sealed.economic_key_value
          ),'[]'::jsonb)
        FROM pg_temp.timesheet_case_rollup AS raw_case
        WHERE raw_case.candidate_id = v_preview_candidate_loop_id
          AND raw_case.timesheet_id = ANY(COALESCE(p_force_include_timesheet_ids, ARRAY[]::uuid[]))
          AND NOT (raw_case.timesheet_id = ANY(COALESCE(p_exclude_timesheet_ids, ARRAY[]::uuid[])))
          AND NOT (
            raw_case.timesheet_id
              = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
          )
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
            WHERE authoritative_component.timesheet_id = raw_case.timesheet_id
          )
        ON CONFLICT (candidate_id, timesheet_id) DO UPDATE
        SET
          client_id = EXCLUDED.client_id,
          candidate_pay_method = EXCLUDED.candidate_pay_method,
          case_is_blocked = EXCLUDED.case_is_blocked,
          case_components_json = EXCLUDED.case_components_json;

        WITH missing_components AS (
          SELECT missing.candidate_id,missing.timesheet_id,
            jsonb_agg(missing.component_json ORDER BY missing.economic_key_type,
              missing.economic_key_value,missing.bucket_sort_ordinal,
              missing.physical_bucket_key) AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=missing.timesheet_id
           AND negative_component.key_type=missing.economic_key_type
           AND negative_component.key_value=missing.economic_key_value
          WHERE missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY missing.candidate_id,missing.timesheet_id
        )
        UPDATE pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
        SET case_components_json=raw_row.case_components_json||missing.components_json
        FROM missing_components missing
        WHERE raw_row.candidate_id=missing.candidate_id
          AND raw_row.timesheet_id=missing.timesheet_id;

        INSERT INTO pg_temp.tmp_sync_raw_negative_timesheet_rows(
          candidate_id,timesheet_id,client_id,candidate_pay_method,
          case_is_blocked,case_components_json
        )
        SELECT missing.candidate_id,missing.timesheet_id,baseline.client_id,
          (SELECT MIN(sealed.target_pay_method)
           FROM pg_temp.tmp_sync_sealed_rate_projection sealed
           WHERE sealed.timesheet_id=missing.timesheet_id),
          false,missing.components_json
        FROM (
          SELECT sealed_missing.candidate_id,sealed_missing.timesheet_id,
            jsonb_agg(sealed_missing.component_json ORDER BY
              sealed_missing.economic_key_type,sealed_missing.economic_key_value,
              sealed_missing.bucket_sort_ordinal,sealed_missing.physical_bucket_key)
              AS components_json
          FROM pg_temp.tmp_sync_sealed_missing_preview_components sealed_missing
          JOIN pg_temp.tmp_sync_authoritative_negative_components negative_component
            ON negative_component.timesheet_id=sealed_missing.timesheet_id
           AND negative_component.key_type=sealed_missing.economic_key_type
           AND negative_component.key_value=sealed_missing.economic_key_value
          WHERE sealed_missing.candidate_id=v_preview_candidate_loop_id
          GROUP BY sealed_missing.candidate_id,sealed_missing.timesheet_id
        ) missing
        JOIN pg_temp.ts_baseline baseline
          ON baseline.candidate_id=missing.candidate_id
         AND baseline.timesheet_id=missing.timesheet_id
        WHERE NOT EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows existing_row
          WHERE existing_row.candidate_id=missing.candidate_id
            AND existing_row.timesheet_id=missing.timesheet_id
        );

        IF EXISTS(
          SELECT 1 FROM pg_temp.tmp_sync_authoritative_negative_components negative_component
          WHERE NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_root_ids,ARRAY[]::uuid[])))
            AND NOT (negative_component.timesheet_id
              =ANY(COALESCE(v_resolution_pending_member_ids,ARRAY[]::uuid[])))
            AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_raw_negative_timesheet_rows raw_row
              WHERE raw_row.candidate_id=v_preview_candidate_loop_id
                AND raw_row.timesheet_id=negative_component.timesheet_id)
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'
            USING ERRCODE='P0001',DETAIL=jsonb_build_object(
              'code','PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING',
              'candidate_id',v_preview_candidate_loop_id::text)::text;
        END IF;

        IF EXISTS (
          WITH allocated_component_totals AS (
            SELECT
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))) AS key_type,
              BTRIM(COALESCE(component.value->>'component_key_value', '')) AS key_value,
              COUNT(*)::integer AS allocated_component_count,
              ROUND(SUM((component.value->>'component_amount_ex_vat')::numeric), 2)::numeric(12,2) AS allocated_outstanding_ex_vat
            FROM pg_temp.tmp_sync_raw_negative_timesheet_rows AS raw_timesheet
            CROSS JOIN LATERAL jsonb_array_elements(raw_timesheet.case_components_json) AS component(value)
            WHERE raw_timesheet.candidate_id = v_preview_candidate_loop_id
              AND COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            GROUP BY
              raw_timesheet.timesheet_id,
              UPPER(BTRIM(COALESCE(component.value->>'component_key_type', ''))),
              BTRIM(COALESCE(component.value->>'component_key_value', ''))
          )
          SELECT 1
          FROM pg_temp.tmp_sync_authoritative_negative_components AS authoritative_component
          LEFT JOIN allocated_component_totals AS allocated_total
            ON allocated_total.timesheet_id = authoritative_component.timesheet_id
           AND allocated_total.key_type = authoritative_component.key_type
           AND allocated_total.key_value = authoritative_component.key_value
          WHERE (
                  allocated_total.allocated_component_count IS NULL
                  OR (
                  ABS(ROUND(
                    COALESCE(allocated_total.allocated_outstanding_ex_vat, 0)
                    - authoritative_component.outstanding_ex_vat,
                    2
                  )) > 0.01
                )
                )
            AND NOT (
              authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_root_ids, ARRAY[]::uuid[]))
              OR authoritative_component.timesheet_id
                = ANY(COALESCE(v_resolution_pending_member_ids, ARRAY[]::uuid[]))
            )
        ) THEN
          RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_SYNC_OVERPAYMENTS_AUTHORITATIVE_NEGATIVE_COMPONENT_METADATA_MISMATCH',
                    'candidate_id', v_preview_candidate_loop_id::text,
                    'negative_component_count', COALESCE(v_authoritative_negative_component_count, 0),
                    'negative_component_digest', v_authoritative_negative_component_digest,
                    'message', 'Canonical negative components were not represented exactly by the validated pre-draft component allocations.'
                  )::text;
        END IF;
      END IF;

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope,
                  'baseline_candidate_id', NULLIF(BTRIM(COALESCE(
                    v_preview_candidate_row_json->>'candidate_id',
                    v_preview_baseline_json->>'candidate_id',
                    ''
                  )), '')
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) IS DISTINCT FROM v_scope THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_PAY_CHANNEL_MISMATCH',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'requested_pay_channel_scope', v_scope,
                  'current_pay_method', NULLIF(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', '')), '')
                )::text;
      END IF;

      v_preview_candidate_row_json := v_preview_candidate_row_json
        || jsonb_build_object(
          'candidate_id', v_preview_candidate_loop_id::text,
          'itemisation', CASE
            WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
            WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
              THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        );

      INSERT INTO pg_temp.tmp_sync_preview_candidates (
        candidate_id,
        candidate_json
      )
      VALUES (
        v_preview_candidate_loop_id,
        v_preview_candidate_row_json
      )
      ON CONFLICT (candidate_id) DO UPDATE
      SET candidate_json = EXCLUDED.candidate_json;
    END LOOP;
  ELSE
    v_preview_scope_context_json := public.pay_preview_build_context(
      p_pay_date => p_pay_date,
      p_week_ending_cutoff => p_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => p_client_filter_single,
      p_preview_decisions_json => v_preview_decisions_json
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', 100
        )
    );

    v_preview_scope_candidate_ids_json := CASE
      WHEN jsonb_typeof(v_preview_scope_context_json->'candidate_ids') = 'array'
        THEN COALESCE(v_preview_scope_context_json->'candidate_ids', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    IF LOWER(BTRIM(COALESCE(v_preview_scope_context_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_CANDIDATE_SCOPE_REQUIRES_EXPLICIT_IDS',
                'message', 'The bounded candidate page is incomplete. Supply explicit candidate_ids rather than accepting a partial all-candidate reconciliation.',
                'pay_channel_scope', v_scope,
                'page_count', COALESCE(v_preview_scope_context_json->>'page_count', '0'),
                'limit', COALESCE(v_preview_scope_context_json->>'limit', '100'),
                'next_cursor_json', COALESCE(v_preview_scope_context_json->'next_cursor_json', 'null'::jsonb)
              )::text;
    END IF;

    FOR v_preview_candidate_loop_id IN
      SELECT DISTINCT scoped_candidate.value::uuid
      FROM jsonb_array_elements_text(COALESCE(v_preview_scope_candidate_ids_json, '[]'::jsonb)) AS scoped_candidate(value)
      WHERE scoped_candidate.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY scoped_candidate.value::uuid
    LOOP
      v_preview_context_json := public.pay_preview_build_context(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_candidate_id => v_preview_candidate_loop_id,
        p_client_id => p_client_filter_single,
        p_preview_decisions_json => v_preview_decisions_json
      )
      || jsonb_build_object(
        'overpayment_sync_mode', true,
        'emit_raw_overpayment_components', true,
        'pay_channel_scope', v_scope,
        'force_include_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
        'exclude_timesheet_ids', COALESCE(to_jsonb(p_exclude_timesheet_ids), '[]'::jsonb)
      );

      v_preview_baseline_json := public.pay_preview_candidate_build_summary_fragment(
        p_context_json => v_preview_context_json,
        p_candidate_id => v_preview_candidate_loop_id
      );

      v_preview_candidate_row_json := CASE
        WHEN jsonb_typeof(v_preview_baseline_json->'candidate_row') = 'object'
          THEN COALESCE(v_preview_baseline_json->'candidate_row', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      IF NULLIF(BTRIM(COALESCE(
           v_preview_candidate_row_json->>'candidate_id',
           v_preview_baseline_json->>'candidate_id',
           ''
         )), '') IS DISTINCT FROM v_preview_candidate_loop_id::text THEN
        RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
                  'candidate_id', v_preview_candidate_loop_id::text,
                  'pay_channel_scope', v_scope
                )::text;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_preview_candidate_row_json->>'current_pay_method', ''))) = v_scope THEN
        v_preview_candidate_row_json := v_preview_candidate_row_json
          || jsonb_build_object(
            'candidate_id', v_preview_candidate_loop_id::text,
            'itemisation', CASE
              WHEN jsonb_typeof(v_preview_candidate_row_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_candidate_row_json->'itemisation', '[]'::jsonb)
              WHEN jsonb_typeof(v_preview_baseline_json->'itemisation') = 'array'
                THEN COALESCE(v_preview_baseline_json->'itemisation', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          );

        INSERT INTO pg_temp.tmp_sync_preview_candidates (
          candidate_id,
          candidate_json
        )
        VALUES (
          v_preview_candidate_loop_id,
          v_preview_candidate_row_json
        )
        ON CONFLICT (candidate_id) DO UPDATE
        SET candidate_json = EXCLUDED.candidate_json;
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_preview_candidate_count
  FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate;

  WITH requested_candidates AS (
    SELECT DISTINCT requested_candidate.candidate_id
    FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS requested_candidate(candidate_id)
    WHERE requested_candidate.candidate_id IS NOT NULL
  ), missing_candidates AS (
    SELECT requested_candidates.candidate_id
    FROM requested_candidates
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_sync_preview_candidates AS preview_candidate
      WHERE preview_candidate.candidate_id = requested_candidates.candidate_id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(missing_candidates.candidate_id::text ORDER BY missing_candidates.candidate_id), '[]'::jsonb)
  INTO v_missing_candidate_count,
       v_missing_candidate_ids_json
  FROM missing_candidates;

  IF COALESCE(v_missing_candidate_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_SYNC_OVERPAYMENTS_PREVIEW_CANDIDATE_COVERAGE_INCOMPLETE',
              'pay_channel_scope', v_scope,
              'requested_candidate_count', v_requested_candidate_count,
              'preview_candidate_count', v_preview_candidate_count,
              'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb)
            )::text;
  END IF;

  v_preview_workspace_ms := COALESCE(v_preview_collect_ms, 0)
    + COALESCE(v_preview_canonical_ms, 0)
    + COALESCE(v_preview_summary_ms, 0);
  v_phase_started_at := clock_timestamp();

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with candidate_rows as (
    select
      preview_candidate.candidate_id,
      upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      case
        when jsonb_typeof(preview_candidate.candidate_json->'itemisation') = 'array'
          then coalesce(preview_candidate.candidate_json->'itemisation', '[]'::jsonb)
        else '[]'::jsonb
      end as itemisation_json
    from pg_temp.tmp_sync_preview_candidates as preview_candidate
    where upper(btrim(coalesce(preview_candidate.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or preview_candidate.candidate_id = any(p_candidate_ids)
      )
  ),
  itemisation_timesheet_rows as (
    select cr.candidate_id,cr.candidate_pay_method,itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id','')),'')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat','')::numeric,0),2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked','false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components','[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json,'[]'::jsonb)) itm(value)
    where coalesce(itm.value->>'line_type','')='TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'') is not null
      and (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null)
      and not (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id','')),'')::uuid=any(p_exclude_timesheet_ids))
  ),
  authoritative_timesheet_rows AS (
    SELECT v_authoritative_candidate_id AS candidate_id,
      (SELECT MIN(sealed.target_pay_method)
       FROM pg_temp.tmp_sync_sealed_rate_projection sealed) AS candidate_pay_method,
      jsonb_build_object('line_type','TIMESHEET_PAYMENT','timesheet_id',scope_row.timesheet_id::text,
        'client_id',CASE WHEN metadata.client_id IS NULL THEN NULL ELSE metadata.client_id::text END,
        'amount_ex_vat',ROUND(COALESCE(economic_total.truth_ex_vat,0),2),
        'case_is_blocked',COALESCE(metadata.case_is_blocked,false),
        'case_components',COALESCE(physical_components.case_components_json,'[]'::jsonb)
          ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb),
        'source_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text) AS item_json,
      scope_row.timesheet_id,metadata.client_id,
      ROUND(COALESCE(economic_total.truth_ex_vat,0),2)::numeric(12,2) AS corrected_amount_ex,
      COALESCE(metadata.case_is_blocked,false) AS case_is_blocked,
      COALESCE(physical_components.case_components_json,'[]'::jsonb)
        ||COALESCE(missing_physical_components.case_components_json,'[]'::jsonb)
        AS case_components_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL (
      SELECT COALESCE(preview_row.client_id,current_financial.client_id) AS client_id,
        COALESCE(preview_row.case_is_blocked,false) AS case_is_blocked
      FROM (SELECT 1) seed
      LEFT JOIN LATERAL (
        SELECT item.client_id,item.case_is_blocked
        FROM itemisation_timesheet_rows item WHERE item.timesheet_id=scope_row.timesheet_id LIMIT 1
      ) preview_row ON true
      LEFT JOIN LATERAL (
        SELECT financial.client_id FROM public.timesheets_financials financial
        WHERE financial.timesheet_id=scope_row.timesheet_id AND financial.is_current
          AND financial.candidate_id=v_authoritative_candidate_id
        ORDER BY financial.computed_at_utc DESC NULLS LAST,financial.id DESC LIMIT 1
      ) current_financial ON true
    ) metadata ON true
    LEFT JOIN LATERAL (
      SELECT ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
      FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=scope_row.timesheet_id
    ) economic_total ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(
        raw_component.value||jsonb_build_object(
          'component_amount_ex_vat',sealed.outstanding_ex_vat,
          'authoritative_truth_ex_vat',sealed.truth_ex_vat,
          'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
          'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
          'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
          'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
          'physical_bucket_key',sealed.physical_bucket_key,
           'physical_bucket_digest',sealed.physical_bucket_digest,
           'sealed_evidence_digest',sealed.sealed_evidence_digest,
           'financial_revision_digest',sealed.financial_revision_digest,
           'target_authority_digest',sealed.target_authority_digest,
           'conversion_context_digest',sealed.conversion_context_digest,
           'source_pay_method',sealed.source_pay_method,
           'current_target_pay_method',sealed.target_pay_method,
           'source_basis_json',(CASE
             WHEN jsonb_typeof(raw_component.value->'source_basis_json')='object'
               THEN raw_component.value->'source_basis_json'
             ELSE '{}'::jsonb END)||jsonb_build_object(
               'source_pay_method',sealed.source_pay_method))
        ORDER BY raw_component.ordinality),'[]'::jsonb) AS case_components_json
      FROM pg_temp.timesheet_case_rollup raw_case
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(raw_case.case_components_json)='array'
          THEN raw_case.case_components_json ELSE '[]'::jsonb END)
        WITH ORDINALITY raw_component(value,ordinality)
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_case.timesheet_id
       AND sealed.economic_key_type=UPPER(BTRIM(raw_component.value->>'component_key_type'))
       AND sealed.economic_key_value=BTRIM(raw_component.value->>'component_key_value')
       AND sealed.physical_bucket_key=concat_ws('|','RATE_BUCKET_V1',
         raw_case.timesheet_id::text,
         NULLIF(BTRIM(raw_component.value->>'source_family_key'),''),
         UPPER(BTRIM(raw_component.value->>'component_key_type')),
         BTRIM(raw_component.value->>'component_key_value'),
         CASE
           WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT'
             THEN 'worked-time-residual:'
               ||UPPER(BTRIM(raw_component.value->>'component_key_type'))||':'
               ||BTRIM(raw_component.value->>'component_key_value')
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
             THEN COALESCE(NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_stable_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_id}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,segment_key}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,work_date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,date}'),''),
               NULLIF(BTRIM(raw_component.value#>>'{source_basis_json,ref_num}'),''))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADDITIONAL_CODE'
             THEN 'additional:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,additional_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='EXPENSE_CODE'
             THEN 'expense:'||UPPER(BTRIM(raw_component.value#>>'{source_basis_json,expense_code}'))
           WHEN UPPER(BTRIM(raw_component.value->>'component_key_type'))='ADJUSTMENT_CODE'
             THEN 'adjustment:'||BTRIM(raw_component.value#>>'{source_basis_json,adjustment_id}')
         END,
         UPPER(BTRIM(COALESCE(
           CASE WHEN UPPER(BTRIM(COALESCE(
               raw_component.value#>>'{source_basis_json,component_fallback}','')))
                 ='WORKED_TIME_AMOUNT' THEN 'FIXED' END,
           NULLIF(raw_component.value#>>'{source_basis_json,bucket_code}',''),
           CASE UPPER(BTRIM(raw_component.value->>'component_key_type'))
             WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
             WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))))
      WHERE raw_case.candidate_id=v_authoritative_candidate_id
        AND raw_case.timesheet_id=scope_row.timesheet_id
    ) physical_components ON true
    LEFT JOIN LATERAL (
      SELECT COALESCE(jsonb_agg(missing.component_json ORDER BY
        missing.economic_key_type,missing.economic_key_value,
        missing.bucket_sort_ordinal,missing.physical_bucket_key),'[]'::jsonb)
        AS case_components_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=v_authoritative_candidate_id
        AND missing.timesheet_id=scope_row.timesheet_id
    ) missing_physical_components ON true
    WHERE scope_row.build_id=p_build_id
      AND (coalesce(array_length(p_force_include_timesheet_ids,1),0)=0
        OR scope_row.timesheet_id=ANY(p_force_include_timesheet_ids)
        OR p_force_include_timesheet_ids IS NULL)
      AND NOT (coalesce(array_length(p_exclude_timesheet_ids,1),0)>0
        AND scope_row.timesheet_id=ANY(p_exclude_timesheet_ids))
  ),
  timesheet_item_rows AS (
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM authoritative_timesheet_rows item
    WHERE COALESCE(v_authoritative_timesheet_scope,false)
    UNION ALL
    SELECT item.candidate_id,item.candidate_pay_method,item.item_json,item.timesheet_id,item.client_id,
      item.corrected_amount_ex,item.case_is_blocked,item.case_components_json
    FROM itemisation_timesheet_rows item
    WHERE NOT COALESCE(v_authoritative_timesheet_scope,false)
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM (
        SELECT fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          fact.amount_ex_vat,fact.amount_inc_vat
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=p_build_id AND fact.timesheet_id=distinct_timesheet_rows.timesheet_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      ) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      UPPER(NULLIF(BTRIM(COALESCE(comp.value->>'component_key_type', '')), '')) AS component_key_type,
      NULLIF(BTRIM(COALESCE(comp.value->>'component_key_value', '')), '') AS component_key_value,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  finance_component_movements_raw as (
    /* Authoritative builds have already folded settled baseline and active
       reservations into each signed component.  Keep the movement relation
       fact-owned so no mutable finance table can change the result. */
    select v_authoritative_candidate_id as candidate_id,fact.timesheet_id,
      upper(btrim(coalesce(fact.economic_key_type,''))) as component_key_type,
      nullif(btrim(coalesce(fact.economic_key_value,'')),'') as component_key_value,
      case
        when fact.fact_family='FROZEN_SETTLED_COMPONENT' then upper(btrim(coalesce(
          fact.source_payload_json #>> '{pay_batch_item,item_type}',
          fact.source_payload_json->>'item_type','')))
        when fact.fact_family='RESERVATION_COMPONENT' then case upper(coalesce((
          select case_fact.source_payload_json->>'case_type'
          from private.banking_pay_workbench_economic_build_facts case_fact
          where case_fact.build_id=fact.build_id
            and case_fact.fact_family='FINANCE_CASE_IDENTITY'
            and case_fact.finance_case_id=fact.finance_case_id
          limit 1),'OVERPAYMENT'))
          when 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT' else 'OVERPAYMENT_RECOVERY' end
        else NULL end as item_type,
      round(abs(coalesce(fact.amount_ex_vat,fact.reserved_source_amount,0)),2)::numeric(12,2) as movement_amount_ex,
      (fact.fact_family='FROZEN_SETTLED_COMPONENT') as is_settled_movement,
      (fact.fact_family='RESERVATION_COMPONENT') as is_active_reservation
    from private.banking_pay_workbench_economic_build_facts fact
    where fact.build_id=p_build_id
      and fact.fact_family in ('FROZEN_SETTLED_COMPONENT','RESERVATION_COMPONENT')
      and fact.timesheet_id is not null
      and (not v_slice_active or fact.timesheet_id=any(v_bounded_scope_ids)) /* A28 */
  ),
  finance_component_movements as (
    select
      fcmr.candidate_id,
      fcmr.timesheet_id,
      fcmr.component_key_type,
      fcmr.component_key_value,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'OVERPAYMENT_RECOVERY' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_overpayment_recovery_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_settled_movement), 0), 2)::numeric(12,2) as settled_underpayment_payment_ex,
      round(coalesce(sum(fcmr.movement_amount_ex) filter (where fcmr.item_type = 'UNDERPAYMENT_PAYMENT' and fcmr.is_active_reservation), 0), 2)::numeric(12,2) as reserved_underpayment_payment_ex,
      true as has_finance_movement
    from finance_component_movements_raw fcmr
    where fcmr.component_key_type is not null
      and fcmr.component_key_value is not null
    group by fcmr.candidate_id, fcmr.timesheet_id, fcmr.component_key_type, fcmr.component_key_value
  ),
  timesheet_exploded_with_signed_balance as (
    select
      tec.*,
      coalesce(fcm.settled_overpayment_recovery_ex, 0) as settled_overpayment_recovery_ex,
      coalesce(fcm.reserved_overpayment_recovery_ex, 0) as reserved_overpayment_recovery_ex,
      coalesce(fcm.settled_underpayment_payment_ex, 0) as settled_underpayment_payment_ex,
      coalesce(fcm.reserved_underpayment_payment_ex, 0) as reserved_underpayment_payment_ex,
      coalesce(fcm.has_finance_movement, false) as has_finance_movement,
      case
        /* The authoritative pre-draft component amount is already the canonical
           live-truth minus settled-baseline minus active-reservation balance.
           Reapplying finance movements here would double count them. */
        when upper(btrim(coalesce(
               tec.component_json->>'overpayment_component_authority',
               ''
             ))) = 'PRE_DRAFT_LIVE_TRUTH'
          then round(coalesce(tec.component_amount_ex, 0), 2)::numeric(12,2)
        else round(
          coalesce(tec.component_amount_ex, 0)
          + coalesce(fcm.settled_overpayment_recovery_ex, 0)
          + coalesce(fcm.reserved_overpayment_recovery_ex, 0)
          - coalesce(fcm.settled_underpayment_payment_ex, 0)
          - coalesce(fcm.reserved_underpayment_payment_ex, 0),
          2
        )::numeric(12,2)
      end as signed_component_amount_ex
    from timesheet_exploded_components tec
    left join finance_component_movements fcm
      on fcm.candidate_id = tec.candidate_id
     and fcm.timesheet_id = tec.timesheet_id
     and fcm.component_key_type = tec.component_key_type
     and fcm.component_key_value = tec.component_key_value
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      bool_or(coalesce(tec.has_finance_movement, false)) as has_finance_movement,
      round(coalesce(sum(case when tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null then abs(tec.signed_component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null then tec.signed_component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex < 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', tec.component_key_type,
            'component_key_value', tec.component_key_value,
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN tec.component_key_type = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''),
            'current_target_pay_method', nullif(btrim(coalesce(tec.component_json->>'current_target_pay_method', '')), ''),
            'source_basis_json', (CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', tec.component_key_type,
                'component_key_value', tec.component_key_value,
                'component_amount_ex_vat', abs(tec.signed_component_amount_ex)
              ))
            END)||jsonb_build_object('source_pay_method',
              nullif(btrim(coalesce(tec.component_json->>'source_pay_method','')),'')),
            'source_amount', abs(tec.signed_component_amount_ex),
            'overpayment_component_authority', NULLIF(UPPER(BTRIM(COALESCE(
              tec.component_json->>'overpayment_component_authority',
              ''
            ))), ''),
            'remaining_source_amount', CASE
              WHEN upper(btrim(coalesce(
                     tec.component_json->>'overpayment_component_authority',
                     ''
                   ))) = 'PRE_DRAFT_LIVE_TRUTH'
                THEN abs(tec.signed_component_amount_ex)
              ELSE NULL
            END,
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.signed_component_amount_ex > 0 and tec.component_key_type is not null and tec.component_key_value is not null),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_with_signed_balance tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
            or coalesce(tcr.has_finance_movement, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
           or coalesce(tcr.has_finance_movement, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  IF COALESCE(v_authoritative_timesheet_scope,false) THEN
    v_rate_authority_failure_code:=NULL::text;
    v_rate_authority_failure_detail:='{}'::jsonb;
    WITH component_methods AS MATERIALIZED (
      SELECT candidate.candidate_id,candidate.timesheet_id,
        UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),''))
          AS source_pay_method,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),''))
          AS economic_key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'')
          AS economic_key_value,
        component.ordinality::integer AS component_ordinality
      FROM pg_temp.tmp_sync_timesheet_case_candidates candidate
      CROSS JOIN LATERAL jsonb_array_elements(CASE
        WHEN jsonb_typeof(candidate.components_sync_json)='array'
          THEN candidate.components_sync_json ELSE '[]'::jsonb END)
        WITH ORDINALITY component(value,ordinality)
    ), method_summary AS MATERIALIZED (
      SELECT method.candidate_id,method.timesheet_id,COUNT(*)::integer AS component_count,
        COUNT(*) FILTER(WHERE method.source_pay_method IS NULL
          OR method.source_pay_method NOT IN ('PAYE','UMBRELLA'))::integer
          AS invalid_method_count,
        COUNT(DISTINCT method.source_pay_method) FILTER(
          WHERE method.source_pay_method IN ('PAYE','UMBRELLA'))::integer
          AS distinct_supported_method_count,
        jsonb_agg(jsonb_build_object(
          'component_ordinality',method.component_ordinality,
          'economic_key_type',method.economic_key_type,
          'economic_key_value',method.economic_key_value,
          'source_pay_method',method.source_pay_method)
          ORDER BY method.component_ordinality) AS complete_component_method_set
      FROM component_methods method
      GROUP BY method.candidate_id,method.timesheet_id
    )
    SELECT CASE WHEN summary.invalid_method_count>0
        THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        ELSE 'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT' END,
      jsonb_build_object(
        'candidate_id',summary.candidate_id,
        'timesheet_id',summary.timesheet_id,
        'component_count',summary.component_count,
        'invalid_method_count',summary.invalid_method_count,
        'distinct_supported_method_count',summary.distinct_supported_method_count,
        'complete_component_method_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(summary.complete_component_method_set::text,'UTF8'),
          'sha256'),'hex'),
        'sample_truncated',summary.component_count>25,
        'component_method_sample',pg_catalog.jsonb_path_query_array(
          summary.complete_component_method_set,'$[0 to 24]'))
    INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
    FROM method_summary summary
    WHERE summary.invalid_method_count>0
       OR summary.distinct_supported_method_count<>1
    ORDER BY summary.timesheet_id
    LIMIT 1;

    IF v_rate_authority_failure_code IS NOT NULL THEN
      RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
        DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
          'detail',v_rate_authority_failure_detail)::text;
    END IF;
  END IF;

  v_correction_rewrite_result :=
    public._ctms_rewrite_sync_correction_cases_v1(
    case
      when nullif(btrim(coalesce(p_mismatch_choices->>'workbench_session_id', '')), '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then nullif(btrim(p_mismatch_choices->>'workbench_session_id'), '')::uuid
      else null::uuid
    end,
    coalesce(p_candidate_ids, array[]::uuid[]),
    coalesce(p_force_include_timesheet_ids, array[]::uuid[])
  );

  select coalesce(array_agg(distinct value::uuid order by value::uuid),array[]::uuid[])
  into v_resolution_pending_member_ids
  from jsonb_array_elements_text(
    coalesce(
      v_correction_rewrite_result
        ->'resolution_pending_member_timesheet_ids',
      '[]'::jsonb
    )
  ) pending_member(value);

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  v_case_workspace_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    v_selected_event_type := NULL;
    v_selected_reason := NULL;
    v_selected_note := NULL;
    v_case_update_count := 0;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array'
            THEN v_target_case_row.components_sync_json
          ELSE '[]'::jsonb
        END
      ) AS authoritative_component(value)
      WHERE UPPER(BTRIM(COALESCE(
        authoritative_component.value->>'overpayment_component_authority',
        ''
      ))) = 'PRE_DRAFT_LIVE_TRUTH'
    )
    INTO v_target_amount_is_authoritative_outstanding;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(component_element.value->>'source_pay_method'),''))
            AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_safety_events
        where sync_safety_events.build_id=p_build_id
          and sync_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      ) as old_has_manual_or_restructure_event,
      exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts automatic_clear_event
        where automatic_clear_event.build_id=p_build_id
          and automatic_clear_event.fact_family='PROTECTION_EVIDENCE'
          and automatic_clear_event.finance_case_id = pa.id
          and (
            (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CASE_CLEARED'
              and lower(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'rail_settlement'
            )
            or (
              upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'event_type', ''))) = 'CLEARED'
              and upper(btrim(coalesce(automatic_clear_event.source_payload_json->>'reason', ''))) = 'PREVIEW_FINANCE_SYNC'
            )
          )
      ) as old_has_automatic_reconcilable_clear,
      round(coalesce((
        select sum(abs(coalesce(settled_fact.amount_ex_vat,0)))
        from private.banking_pay_workbench_economic_build_facts settled_fact
        where settled_fact.build_id=p_build_id
          and settled_fact.fact_family='FROZEN_SETTLED_COMPONENT'
          and settled_fact.finance_case_id=pa.id
          and (
            (
              v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'OVERPAYMENT_RECOVERY'
            )
            or (
              v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
              and upper(btrim(coalesce(settled_fact.source_payload_json #>> '{pay_batch_item,item_type}',
                settled_fact.source_payload_json->>'item_type',''))) = 'UNDERPAYMENT_PAYMENT'
            )
          )
      ), 0), 2)::numeric(12,2) as old_active_recovered_amount
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type = v_target_case_row.desired_case_type
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    v_existing_recovered_amount := greatest(
      coalesce(v_existing_case_row.old_active_recovered_amount, 0),
      0
    );

    v_existing_active_reserved_amount := 0::numeric(12,2);

    IF v_existing_case_row.finance_case_id IS NOT NULL THEN
      SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
        reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
      INTO v_existing_active_reserved_amount
      FROM private.banking_pay_workbench_economic_build_facts reservation_fact
      WHERE reservation_fact.build_id=p_build_id
        AND reservation_fact.fact_family='RESERVATION_COMPONENT'
        AND reservation_fact.finance_case_id=v_existing_case_row.finance_case_id;
    END IF;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or (
           v_existing_case_row.old_cleared_at_utc is not null
           and not (
             upper(coalesce(v_existing_case_row.old_status::text, '')) = 'PAID_OFF'
             and coalesce(v_existing_case_row.old_has_automatic_reconcilable_clear, false)
             and coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false) is not true
             and (
               (
                 coalesce(v_target_amount_is_authoritative_outstanding, false)
                 and round(coalesce(v_target_case_amount_ex, 0), 2) > 0
               )
               or (
                 coalesce(v_target_amount_is_authoritative_outstanding, false) is not true
                 and round(
                   coalesce(v_target_case_amount_ex, 0)
                   - coalesce(v_existing_recovered_amount, 0),
                   2
                 ) > 0
               )
             )
           )
         )
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event,
          'has_automatic_reconcilable_clear', v_existing_case_row.old_has_automatic_reconcilable_clear,
          'existing_recovered_amount', v_existing_recovered_amount
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'component_sync_skipped', true,
          'component_authority_preserved', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature,
          'target_pay_channel_scope', v_scope,
          'workbench_session_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'workbench_session_id', '')), ''),
          'source_build_run_id', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'source_build_run_id', '')), ''),
          'session_version', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'session_version', '')), ''),
          'overpayment_sync_scope_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_scope_digest', '')), ''),
          'overpayment_sync_negative_component_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_negative_component_digest', '')), ''),
          'overpayment_sync_settled_baseline_digest', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'overpayment_sync_settled_baseline_digest', '')), ''),
          'policy_x_authority_scope', NULLIF(BTRIM(COALESCE(p_mismatch_choices->>'policy_x_authority_scope', '')), '')
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped case and component synchronisation because the existing case is written-off, cleared, closed, paused, manually resolved, or restructured.'
      );

      /* A protected case must not be inserted into tmp_sync_case_links with an
         empty component payload.  Every row in tmp_sync_case_links is processed
         later by pay_finance_components_sync_from_preview; an empty payload is
         authoritative removal input and can close open components.  The case
         clear pass already excludes protected cases by lifecycle state/event,
         so omitting the link preserves the complete protected case/component
         authority without allowing automatic sync to rewrite it. */
      continue;
    end if;

    IF v_existing_case_row.finance_case_id IS NOT NULL
       AND v_existing_case_row.old_case_type IS DISTINCT FROM v_target_case_row.desired_case_type
       AND COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_ACTIVE_RESERVATION_DIRECTION_CONFLICT',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'existing_case_type', v_existing_case_row.old_case_type::text,
                'target_case_type', v_target_case_row.desired_case_type::text,
                'active_reserved_amount', COALESCE(v_existing_active_reserved_amount, 0),
                'message', 'The finance-case direction cannot change while a frozen recovery or payment reservation remains active. Settle or cancel the active batch before reconciling the opposite direction.'
              )::text;
    END IF;

    IF COALESCE(v_target_amount_is_authoritative_outstanding, false) THEN
      /* PRE_DRAFT_LIVE_TRUTH supplies the canonical amount that remains after
         settled baseline movements and active reservations.  Keep historic
         consumption in the case lifetime total, but do not subtract it from
         the authoritative remaining amount a second time. */
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < COALESCE(v_existing_active_reserved_amount, 0);
      v_new_outstanding_amount := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        COALESCE(v_existing_active_reserved_amount, 0),
        0
      )::numeric(12,2);
      v_effective_case_amount_ex := ROUND(
        COALESCE(v_existing_recovered_amount, 0) + v_new_outstanding_amount,
        2
      )::numeric(12,2);
    ELSE
      v_active_reservation_protection_applied := COALESCE(v_existing_active_reserved_amount, 0) > 0
        AND COALESCE(v_target_case_amount_ex, 0) < ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2);
      v_effective_case_amount_ex := GREATEST(
        COALESCE(v_target_case_amount_ex, 0),
        ROUND(COALESCE(v_existing_recovered_amount, 0) + COALESCE(v_existing_active_reserved_amount, 0), 2)
      )::numeric(12,2);
      v_new_outstanding_amount := greatest(v_effective_case_amount_ex - v_existing_recovered_amount, COALESCE(v_existing_active_reserved_amount, 0), 0)::numeric(12,2);
    END IF;

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_effective_case_amount_ex,
        v_new_outstanding_amount,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_effective_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id
        and row(
          pa.client_id,
          pa.case_type,
          pa.advance_kind,
          pa.reason,
          pa.linked_shift_date,
          pa.baseline_signature,
          pa.source_original_paid_amount,
          pa.source_corrected_paid_amount,
          pa.original_amount,
          pa.outstanding_amount,
          pa.status,
          pa.cleared_at_utc,
          pa.cleared_by_user_id,
          pa.taxability,
          pa.routing_kind
        ) is distinct from row(
          v_target_case_row.client_id,
          v_target_case_row.desired_case_type,
          v_target_case_row.desired_advance_kind,
          v_target_case_row.desired_reason,
          v_target_case_row.linked_shift_date,
          v_target_case_row.baseline_signature,
          v_target_case_row.source_original_paid_amount,
          v_target_case_row.source_corrected_paid_amount,
          v_effective_case_amount_ex,
          v_new_outstanding_amount,
          case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
          case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
            else pa.taxability
          end,
          case
            when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
            else pa.routing_kind
          end
        );

      get diagnostics v_case_update_count = row_count;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if v_case_update_count > 0
         and upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF'
         and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      elsif v_case_update_count > 0 then
        v_cases_amended := v_cases_amended + 1;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_effective_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      COALESCE(v_effective_case_amount_ex, v_target_case_amount_ex),
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    if v_selected_event_type is not null then
    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
    end if;

    IF COALESCE(v_active_reservation_protection_applied, false)
       AND NOT EXISTS (
         SELECT 1
         FROM public.pay_finance_case_events AS protection_event
         WHERE protection_event.finance_case_id = v_selected_finance_case_id
           AND protection_event.event_type = 'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION'
           AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
           AND protection_event.before_json IS NOT DISTINCT FROM v_case_before_json
           AND protection_event.after_json = jsonb_build_object(
             'target_case_amount_ex', v_target_case_amount_ex,
             'effective_case_amount_ex', v_effective_case_amount_ex,
             'active_reserved_recovery_amount', v_existing_active_reserved_amount,
             'existing_recovered_amount', v_existing_recovered_amount,
             'outstanding_amount', v_new_outstanding_amount
           )
       ) THEN
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_selected_finance_case_id,
        'SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
        now(),
        p_actor_user_id,
        null,
        null,
        v_case_before_json,
        jsonb_build_object(
          'target_case_amount_ex', v_target_case_amount_ex,
          'effective_case_amount_ex', v_effective_case_amount_ex,
          'active_reserved_recovery_amount', v_existing_active_reserved_amount,
          'existing_recovered_amount', v_existing_recovered_amount,
          'outstanding_amount', v_new_outstanding_amount
        ),
        'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
        'Deferred overpayment/underpayment case shrink because an active recovery reservation exists.'
      );
    END IF;
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not (
        coalesce(array_length(v_resolution_pending_member_ids, 1), 0) > 0
        and pa.linked_timesheet_id
              = any(v_resolution_pending_member_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from private.banking_pay_workbench_economic_build_facts sync_clear_safety_events
        where sync_clear_safety_events.build_id=p_build_id
          and sync_clear_safety_events.fact_family='PROTECTION_EVIDENCE'
          and sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'event_type', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'MANUAL_WRITE_OFF',
              'CASE_MANUAL_ECONOMIC_OVERRIDE',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
            or upper(btrim(coalesce(sync_clear_safety_events.source_payload_json->>'reason', ''))) in (
              'MANUAL_ECONOMIC_OVERRIDE',
              'WRITE_OFF',
              'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
            )
          )
      )
  loop
    SELECT ROUND(COALESCE(SUM(ABS(COALESCE(
      reservation_fact.reserved_source_amount,reservation_fact.amount_ex_vat,0))),0),2)::numeric(12,2)
    INTO v_existing_active_reserved_amount
    FROM private.banking_pay_workbench_economic_build_facts reservation_fact
    WHERE reservation_fact.build_id=p_build_id
      AND reservation_fact.fact_family='RESERVATION_COMPONENT'
      AND reservation_fact.finance_case_id=v_open_case_candidate.finance_case_id;

    IF COALESCE(v_existing_active_reserved_amount, 0) > 0 THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protection_event
        WHERE protection_event.finance_case_id = v_open_case_candidate.finance_case_id
          AND protection_event.event_type = 'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION'
          AND protection_event.reason = 'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION'
          AND protection_event.before_json = jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          )
          AND protection_event.after_json = jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          )
      ) THEN
        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_open_case_candidate.finance_case_id,
          'SYNC_CLEAR_DEFERRED_ACTIVE_RESERVATION',
          now(),
          p_actor_user_id,
          null,
          null,
          jsonb_build_object(
            'case_type', v_open_case_candidate.old_case_type::text,
            'status', 'ACTIVE',
            'original_amount', v_open_case_candidate.old_original_amount,
            'outstanding_amount', v_open_case_candidate.old_outstanding_amount
          ),
          jsonb_build_object(
            'clear_deferred', true,
            'active_reserved_recovery_amount', v_existing_active_reserved_amount
          ),
          'PREVIEW_FINANCE_SYNC_ACTIVE_RESERVATION_PROTECTION',
          'Deferred finance case clear because an active recovery reservation exists.'
        );
      END IF;

      CONTINUE;
    END IF;

    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_existing_case_row.finance_case_id::text,
                'candidate_id', v_existing_case_row.candidate_id::text,
                'timesheet_id', v_existing_case_row.timesheet_id::text,
                'operation', 'CLEAR',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    IF jsonb_typeof(COALESCE(v_components_sync_result, '{}'::jsonb)) <> 'object'
       OR LOWER(BTRIM(COALESCE(v_components_sync_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_SYNC_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'operation', 'RECONCILE',
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    SELECT
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
    INTO
      v_component_case_outstanding_amount,
      v_component_open_remaining_total
    FROM public.pay_advances AS pa
    LEFT JOIN public.pay_finance_case_components AS pfc
      ON pfc.finance_case_id = pa.id
    WHERE pa.id = v_target_case_row.finance_case_id
    GROUP BY pa.outstanding_amount;

    v_component_case_mismatch_amount := round(
      coalesce(v_component_case_outstanding_amount, 0) - coalesce(v_component_open_remaining_total, 0),
      2
    )::numeric(12,2);

    IF abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
      RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SYNC_OVERPAYMENTS_COMPONENT_CASE_RECONCILIATION_FAILED',
                'finance_case_id', v_target_case_row.finance_case_id::text,
                'candidate_id', v_target_case_row.candidate_id::text,
                'timesheet_id', v_target_case_row.timesheet_id::text,
                'desired_case_type', v_target_case_row.desired_case_type::text,
                'case_outstanding_amount', coalesce(v_component_case_outstanding_amount, 0),
                'open_component_remaining_total', coalesce(v_component_open_remaining_total, 0),
                'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
                'component_sync_result', COALESCE(v_components_sync_result, '{}'::jsonb)
              )::text;
    END IF;

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'requested_candidate_count', v_requested_candidate_count,
      'preview_candidate_count', v_preview_candidate_count,
      'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
      'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
      'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
      'preview_scope_strategy', v_preview_scope_strategy,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  v_public_result_json := jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'requested_candidate_count', v_requested_candidate_count,
    'preview_candidate_count', v_preview_candidate_count,
    'preview_candidate_coverage_complete', COALESCE(v_missing_candidate_count, 0) = 0,
    'missing_candidate_ids', COALESCE(v_missing_candidate_ids_json, '[]'::jsonb),
    'authoritative_timesheet_scope', COALESCE(v_authoritative_timesheet_scope, false),
    'explicit_empty_timesheet_scope', COALESCE(v_explicit_empty_timesheet_scope, false),
    'preview_scope_strategy', v_preview_scope_strategy,
    'scope_timesheet_ids', COALESCE(to_jsonb(p_force_include_timesheet_ids), '[]'::jsonb),
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'correction_resolution_pending_chain_count',
      coalesce(
        nullif(
          v_correction_rewrite_result
            ->>'resolution_pending_chain_count',
          ''
        )::integer,
        0
      ),
    'correction_resolution_pending_member_timesheet_ids',
      to_jsonb(v_resolution_pending_member_ids),
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );

  v_finance_apply_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF v_effect_capture_mode THEN
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true); /* A28 */
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',candidate_id,'timesheet_id',timesheet_id,'relation_name',relation_name,
      'operation',operation,'source_id',source_id,'finance_case_id',finance_case_id,
      'finance_component_id',finance_component_id,'economic_key_type',economic_key_type,
      'economic_key_value',economic_key_value,'expected_before_digest',expected_before_digest,
      'expected_after_digest',expected_after_digest)
      ORDER BY relation_name,operation,source_id),'[]'::jsonb)
    INTO v_captured_effects FROM pg_temp._bpay_wb_expected_effects;
    IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CAPTURE_INCOMPLETE' USING ERRCODE='23514';
    END IF;
    RETURN jsonb_build_object('ok',true,'public_result_json',jsonb_build_object(
      'ok',true,'effect_plan_capture',true,'captured_effects',v_captured_effects,
      '_internal_reconcile_timing',jsonb_build_object(
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'workspace_cache_ms',v_workspace_cache_ms,
        'freshness_set_ms',v_freshness_set_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      'internal_result_json',jsonb_build_object(
        'captured_effect_count',jsonb_array_length(v_captured_effects),
        'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'freshness_set_ms',v_freshness_set_ms,
        'workspace_cache_ms',v_workspace_cache_ms,
        'authoritative_components_ms',v_authoritative_components_ms,
        'preflight_setup_ms',v_preflight_setup_ms,
        'correction_residuals_ms',v_correction_residuals_ms,
        'authority_validation_ms',v_authority_validation_ms,
        'component_assembly_ms',v_component_assembly_ms,
        'preview_workspace_ms',v_preview_workspace_ms,
        'preview_collect_ms',v_preview_collect_ms,
        'preview_canonical_ms',v_preview_canonical_ms,
        'preview_summary_ms',v_preview_summary_ms,
        'case_workspace_ms',v_case_workspace_ms,
        'finance_apply_ms',v_finance_apply_ms,
        'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer));
  END IF;

  IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects WHERE proposed IS NOT TRUE OR observed IS NOT TRUE)
     OR EXISTS(SELECT 1 FROM pg_temp._bpay_wb_expected_effects
       WHERE build_token IS DISTINCT FROM v_bounded_build.build_token
          OR candidate_id IS DISTINCT FROM v_bounded_build.candidate_id
          OR relation_name NOT IN ('pay_advances','pay_finance_case_components','pay_finance_case_events')) THEN
    SELECT jsonb_build_object(
      'total_effects',count(*),
      'not_proposed',count(*) FILTER (WHERE proposed IS NOT TRUE),
      'not_observed',count(*) FILTER (WHERE observed IS NOT TRUE),
      'wrong_build_token',count(*) FILTER (
        WHERE build_token IS DISTINCT FROM v_bounded_build.build_token),
      'wrong_candidate',count(*) FILTER (
        WHERE candidate_id IS DISTINCT FROM v_bounded_build.candidate_id),
      'invalid_relation',count(*) FILTER (
        WHERE relation_name NOT IN (
          'pay_advances','pay_finance_case_components','pay_finance_case_events')),
      'pay_advances_not_observed',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed IS NOT TRUE),
      'components_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_components' AND observed IS NOT TRUE),
      'events_not_observed',count(*) FILTER (
        WHERE relation_name='pay_finance_case_events' AND observed IS NOT TRUE)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  IF (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared)>0
     AND (SELECT count(*) FROM pg_temp._bpay_wb_expected_effects
          WHERE relation_name='pay_advances' AND observed)
       < (v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared) THEN
    SELECT jsonb_build_object(
      'case_transitions',v_cases_inserted+v_cases_amended+v_cases_reopened+v_cases_cleared,
      'observed_case_effects',count(*) FILTER (
        WHERE relation_name='pay_advances' AND observed)
    )
    INTO v_effect_mismatch_detail
    FROM pg_temp._bpay_wb_expected_effects;

    RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
      v_effect_mismatch_detail::text
      USING ERRCODE='23514', DETAIL=v_effect_mismatch_detail::text;
  END IF;
  SELECT count(*)::integer,md5(COALESCE(string_agg(
    relation_name||':'||operation||':'||source_id::text||':'||
    COALESCE(expected_before_digest,'')||':'||COALESCE(expected_after_digest,''),''
    ORDER BY relation_name,operation,source_id),''))
  INTO v_observed_effect_count,v_observed_effect_digest
  FROM pg_temp._bpay_wb_expected_effects;

  -- Final freshness fence: preview helpers retained for presentation metadata
  -- cannot publish if any build-bound economic input changed during this RPC.
  -- Finance-case DML legitimately refreshes derived timesheet-pay summary cache
  -- fields.  The initial full-row fingerprint above remains exact; after DML,
  -- compare every non-pay-state revision plus the four settled-authority fields
  -- so cache-only refreshes cannot make the transaction stale while Policy X
  -- settlement authority and every other captured input remain fail-closed.
  CREATE TEMP TABLE pg_temp._bpay_wb_post_sync_freshness_v2(
    timesheet_id uuid PRIMARY KEY,
    input_fingerprint text NULL,
    revision_json jsonb NULL
  ) ON COMMIT DROP;
  IF v_execution_profile_version = 2 THEN
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT fingerprint.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,v_bounded_scope_ids
    ) fingerprint;
  ELSE
    INSERT INTO pg_temp._bpay_wb_post_sync_freshness_v2(timesheet_id,input_fingerprint,revision_json)
    SELECT scope_row.timesheet_id,fingerprint.input_fingerprint,fingerprint.revision_json
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    LEFT JOIN LATERAL private.pay_workbench_timesheet_input_fingerprint_v1(
      p_build_id,v_bounded_build.candidate_id,ARRAY[scope_row.timesheet_id]
    ) fingerprint ON true
    WHERE scope_row.build_id=p_build_id
      AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */;
  END IF;
  IF EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_candidate_scope_registry registry
      WHERE registry.candidate_id=v_bounded_build.candidate_id
        AND (registry.current_build_id IS DISTINCT FROM p_build_id
          OR registry.dirty_generation IS DISTINCT FROM v_bounded_build.captured_candidate_generation
          OR registry.current_source_change_seq IS DISTINCT FROM v_bounded_build.source_change_seq)
    ) OR EXISTS(
      SELECT 1
      FROM private.banking_pay_workbench_economic_build_scope scope_row
      LEFT JOIN pg_temp._bpay_wb_pre_sync_freshness_v1 pre_sync
        ON pre_sync.timesheet_id=scope_row.timesheet_id
      LEFT JOIN pg_temp._bpay_wb_post_sync_freshness_v2 current_fingerprint
        ON current_fingerprint.timesheet_id=scope_row.timesheet_id
      LEFT JOIN public.timesheet_pay_state pay_state
        ON pay_state.timesheet_id=scope_row.timesheet_id
      WHERE scope_row.build_id=p_build_id
        AND (NOT v_slice_active OR scope_row.timesheet_id=ANY(v_bounded_scope_ids)) /* A28 */
        AND (
          pre_sync.timesheet_id IS NULL
          OR current_fingerprint.input_fingerprint IS NULL
          OR (current_fingerprint.revision_json-'pay_state_digest')
               IS DISTINCT FROM (pre_sync.revision_json-'pay_state_digest')
          OR md5(jsonb_build_object(
               'last_settled_snapshot_json',pay_state.last_settled_snapshot_json,
               'last_settled_signature',pay_state.last_settled_signature,
               'last_settled_pay_batch_id',pay_state.last_settled_pay_batch_id,
               'last_settled_at_utc',pay_state.last_settled_at_utc
             )::text) IS DISTINCT FROM pre_sync.settled_authority_digest
        )
      LIMIT 1
    ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;
  v_post_freshness_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();
  /* The preview canonicaliser is retained only as a presentation renderer.
     Replace its complete timesheet economic input with the sealed build
     workspace before it runs, then attest the protected output fields. */
  IF to_regclass('pg_temp.timesheet_case_rollup_effective') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.ts_baseline') IS NULL
     OR to_regclass('pg_temp.cand_payee') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACT_WORKSPACE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The legacy renderer may omit a revoked or otherwise zero-current-truth
  -- economic target from its case rollup.  Preserve the complete private
  -- presentation graph by creating a neutral metadata-only row for every
  -- fact-derived economic target.  UNIT_PROJECTION also contains physical
  -- dependency evidence which deliberately owns no economic occurrence; that
  -- evidence remains sealed/attested but must not invent a presentation row.
  -- The sealed build facts below remain the sole source of every economic
  -- value.
  IF (SELECT count(*) FROM pg_temp.cand_payee payee
      WHERE payee.candidate_id=v_bounded_build.candidate_id)<>1
     OR EXISTS(
       WITH economic_target AS (
         SELECT DISTINCT component.timesheet_id
         FROM pg_temp.tmp_sync_authoritative_components component
       )
       SELECT 1
       FROM economic_target target
       LEFT JOIN pg_temp.ts_baseline baseline
         ON baseline.candidate_id=v_bounded_build.candidate_id
        AND baseline.timesheet_id=target.timesheet_id
       GROUP BY target.timesheet_id
       HAVING count(baseline.timesheet_id)<>1
     ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_METADATA_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  INSERT INTO pg_temp.timesheet_case_rollup_effective(
    candidate_id,timesheet_id,client_id,ts_week_ending_date,ts_client_name,ts_pay_method,
    cand_pay_method,cand_tms_ref,cand_display_name,cand_umbrella_id,umb_enabled,
    umb_vat_chargeable,candidate_has_bank_details,candidate_bank_hash,
    umbrella_has_bank_details,umbrella_bank_hash,resolution_family,case_needs_resolution,
    case_resolution_satisfied_now,resolution_action_label,linked_resolution_scope_json,
    case_total_amount_ex,safe_amount_ex,unresolved_taxable_amount_ex,open_taxable_count,
    open_reimbursement_count,unresolved_taxable_count,stale_count,is_mixed_case,is_blocked,
    segments_total_ex,delta_additional_pay_ex_vat,delta_expenses_pay_ex_vat,
    delta_travel_pay_ex_vat,delta_accommodation_pay_ex_vat,delta_other_pay_ex_vat,
    delta_mileage_pay_ex_vat,segment_deltas_json,adjustment_deltas_json,
    additional_unit_deltas_json,reservation_overrun_detected,payment_amount_ex_vat,
    payment_amount_inc_vat,payment_amount,case_resolution_summary_json,case_components_json
  )
  SELECT v_bounded_build.candidate_id,target.timesheet_id,baseline.client_id,
    baseline.ts_week_ending_date,baseline.ts_client_name,baseline.ts_pay_method,
    baseline.cand_pay_method,baseline.cand_tms_ref,baseline.cand_display_name,
    baseline.cand_umbrella_id,baseline.umb_enabled,baseline.umb_vat_chargeable,
    (baseline.cand_bank_hash IS NOT NULL AND BTRIM(baseline.cand_bank_hash)<>''),
    baseline.cand_bank_hash,
    (baseline.umb_bank_hash IS NOT NULL AND BTRIM(baseline.umb_bank_hash)<>''),
    baseline.umb_bank_hash,'BUCKETED',false,true,'Suggested Rate',
    jsonb_build_object(
      'resolve_all_linked_timesheets_default',true,
      'linked_scope_type','SELF_ONLY','linked_timesheet_count',1,
      'linked_timesheet_ids',jsonb_build_array(target.timesheet_id::text),
      'seed_timesheet_id',target.timesheet_id::text),
    0::numeric,0::numeric,0::numeric,0,0,0,0,false,false,
    0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,0::numeric,
    '[]'::jsonb,'[]'::jsonb,'[]'::jsonb,false,
    0::numeric,0::numeric,0::numeric,
    jsonb_build_object(
      'case_needs_resolution',false,'case_resolution_satisfied_now',true,
      'safe_amount_ex_vat',0,'blocked_case_amount_ex_vat',0,
      'unresolved_taxable_amount_ex_vat',0,
      'economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text),
    '[]'::jsonb
  FROM (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ) target
  JOIN pg_temp.ts_baseline baseline
    ON baseline.candidate_id=v_bounded_build.candidate_id
   AND baseline.timesheet_id=target.timesheet_id
  WHERE NOT EXISTS(
    SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
    WHERE preview_row.candidate_id=v_bounded_build.candidate_id
      AND preview_row.timesheet_id=target.timesheet_id
  );
  IF EXISTS(
    SELECT 1
    FROM pg_temp.tmp_sync_authoritative_components component
    WHERE component.timesheet_id IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM pg_temp.timesheet_case_rollup_effective preview_row
        WHERE preview_row.candidate_id=v_bounded_build.candidate_id
          AND preview_row.timesheet_id=component.timesheet_id)
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_SCOPE_INCOMPLETE' USING ERRCODE='23514';
  END IF;
  DELETE FROM pg_temp.timesheet_case_rollup_effective preview_row
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=COALESCE((
    SELECT jsonb_agg(component.component_json ORDER BY component.source_rank,
      component.component_ordinality,component.physical_bucket_key)
    FROM (
      SELECT 0::integer AS source_rank,raw_component.component_ordinality,
        raw_component.physical_bucket_key,
        raw_component.component_json||jsonb_strip_nulls(jsonb_build_object(
          'component_amount_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_pay_ex_vat',COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>
                '{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),
          'source_charge_ex_vat',sealed.source_charge_ex_vat
        )) AS component_json
      FROM pg_temp.tmp_sync_raw_preview_physical_components raw_component
      JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
        ON sealed.timesheet_id=raw_component.timesheet_id
       AND sealed.physical_bucket_key=raw_component.physical_bucket_key
       AND sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      WHERE raw_component.candidate_id=preview_row.candidate_id
        AND raw_component.timesheet_id=preview_row.timesheet_id
      UNION ALL
      SELECT 1::integer,missing.bucket_sort_ordinal::bigint,
        missing.physical_bucket_key,missing.component_json
      FROM pg_temp.tmp_sync_sealed_missing_preview_components missing
      WHERE missing.candidate_id=preview_row.candidate_id
        AND missing.timesheet_id=preview_row.timesheet_id
    ) component
  ),'[]'::jsonb)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  DROP TABLE IF EXISTS pg_temp.tmp_sync_builder_physical_components;
  CREATE TEMP TABLE pg_temp.tmp_sync_builder_physical_components ON COMMIT DROP AS
  SELECT preview_row.candidate_id,preview_row.timesheet_id,
    component.ordinality::integer AS component_ordinality,component.value AS component_json,
    UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS economic_key_type,
    NULLIF(BTRIM(component.value->>'component_key_value'),'') AS economic_key_value,
    concat_ws('|','RATE_BUCKET_V1',preview_row.timesheet_id::text,
      NULLIF(BTRIM(component.value->>'source_family_key'),''),
      UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
      NULLIF(BTRIM(component.value->>'component_key_value'),''),
      CASE
        WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'worked-time-residual:'||UPPER(BTRIM(component.value->>'component_key_type'))
            ||':'||BTRIM(component.value->>'component_key_value')
        WHEN UPPER(BTRIM(component.value->>'component_key_type')) IN ('TS_DAY','TS_TOTAL')
          THEN COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_stable_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,work_date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,date}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADDITIONAL_CODE'
          THEN 'additional:'||UPPER(BTRIM(component.value#>>'{source_basis_json,additional_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='EXPENSE_CODE'
          THEN 'expense:'||UPPER(BTRIM(component.value#>>'{source_basis_json,expense_code}'))
        WHEN UPPER(BTRIM(component.value->>'component_key_type'))='ADJUSTMENT_CODE'
          THEN 'adjustment:'||BTRIM(component.value#>>'{source_basis_json,adjustment_id}')
      END,
      UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))))
      AS physical_bucket_key,
    md5(jsonb_build_object(
      'builder_comparison_version',1,'timesheet_id',preview_row.timesheet_id::text,
      'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
      'component_key_type',UPPER(BTRIM(component.value->>'component_key_type')),
      'component_key_value',BTRIM(component.value->>'component_key_value'),
      'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
      'segment_key',COALESCE(
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
        NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
      'segment_stable_key',NULLIF(BTRIM(
        component.value#>>'{source_basis_json,segment_stable_key}'),''),
      'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
        component.value#>>'{source_basis_json,date}')),''),
      'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
      'additional_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,additional_code}')),''),
      'expense_code',NULLIF(UPPER(BTRIM(
        component.value#>>'{source_basis_json,expense_code}')),''),
      'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
      'bucket_code',UPPER(BTRIM(COALESCE(
        CASE WHEN UPPER(BTRIM(COALESCE(
            component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
        CASE UPPER(BTRIM(component.value->>'component_key_type'))
          WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED'
          WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
        END))),
      'source_units',CASE WHEN COALESCE(component.value->>'source_units','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_units')::numeric,6) END,
      'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_rate')::numeric,6) END,
      'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
      'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
      'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
      'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
      'target_pay_method',UPPER(NULLIF(BTRIM(
        component.value->>'current_target_pay_method'),'')))::text) AS builder_comparison_digest
  FROM pg_temp.timesheet_case_rollup_effective preview_row
  CROSS JOIN LATERAL jsonb_array_elements(CASE
    WHEN jsonb_typeof(preview_row.case_components_json)='array'
      THEN preview_row.case_components_json ELSE '[]'::jsonb END)
    WITH ORDINALITY component(value,ordinality)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id;

  SELECT failure.failure_code,failure.detail_json
  INTO v_rate_authority_failure_code,v_rate_authority_failure_detail
  FROM (
    SELECT 10 AS failure_rank,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_MISSING'::text
        AS failure_code,jsonb_build_object('timesheet_id',sealed.timesheet_id,
          'physical_bucket_key',sealed.physical_bucket_key) AS detail_json
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    LEFT JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
      AND builder.timesheet_id IS NULL
    UNION ALL
    SELECT 20,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_COMPONENT_EXTRA',jsonb_build_object(
      'timesheet_id',builder.timesheet_id,'physical_bucket_key',builder.physical_bucket_key)
    FROM pg_temp.tmp_sync_builder_physical_components builder
    LEFT JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
    WHERE sealed.timesheet_id IS NULL
    UNION ALL
    SELECT 30,'PAY_SYNC_OVERPAYMENTS_RATE_BUILDER_DIGEST_MISMATCH',jsonb_build_object(
      'timesheet_id',sealed.timesheet_id,'physical_bucket_key',sealed.physical_bucket_key,
      'economic_key_type',sealed.economic_key_type,
      'economic_key_value',sealed.economic_key_value,
      'digest_mismatch',builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'amount_mismatch',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
        ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
          CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
          sealed.outstanding_ex_vat),2),
      'expected_digest',sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}',
      'actual_digest',builder.builder_comparison_digest,
      'expected_amount_ex_vat',ROUND(COALESCE(
        CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
            ~ '^-?\d+(\.\d+)?$'
          THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
        sealed.outstanding_ex_vat),2),
      'actual_amount_ex_vat',CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2) END)
    FROM pg_temp.tmp_sync_sealed_rate_projection sealed
    JOIN pg_temp.tmp_sync_builder_physical_components builder
      ON builder.timesheet_id=sealed.timesheet_id
     AND builder.physical_bucket_key=sealed.physical_bucket_key
    WHERE builder.builder_comparison_digest IS DISTINCT FROM
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
       OR CASE WHEN COALESCE(builder.component_json->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((builder.component_json->>'component_amount_ex_vat')::numeric,2)
          ELSE NULL::numeric END IS DISTINCT FROM ROUND(COALESCE(
            CASE WHEN COALESCE(sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}','')
                ~ '^-?\d+(\.\d+)?$'
              THEN (sealed.evidence_json#>>'{physical_bucket,builder_component_amount_ex_vat}')::numeric END,
            sealed.outstanding_ex_vat),2)
  ) failure
  ORDER BY failure.failure_rank,
    failure.detail_json->>'timesheet_id',failure.detail_json->>'physical_bucket_key'
  LIMIT 1;

  IF v_rate_authority_failure_code IS NOT NULL THEN
    RAISE EXCEPTION '%',v_rate_authority_failure_code USING ERRCODE='P0001',
      DETAIL=jsonb_build_object('code',v_rate_authority_failure_code,
        'detail',v_rate_authority_failure_detail)::text;
  END IF;

  WITH overlaid AS (
    SELECT builder.candidate_id,builder.timesheet_id,builder.component_ordinality,
      builder.component_json||jsonb_build_object(
        'component_amount_ex_vat',sealed.outstanding_ex_vat,
        'authoritative_truth_ex_vat',sealed.truth_ex_vat,
        'authoritative_baseline_ex_vat',sealed.baseline_ex_vat,
        'authoritative_reserved_ex_vat',sealed.reserved_ex_vat,
        'authoritative_outstanding_ex_vat',sealed.outstanding_ex_vat,
        'overpayment_component_authority','PRE_DRAFT_LIVE_TRUTH',
        'physical_bucket_key',sealed.physical_bucket_key,
        'physical_bucket_digest',sealed.physical_bucket_digest,
        'sealed_evidence_digest',sealed.sealed_evidence_digest,
        'financial_revision_digest',sealed.financial_revision_digest,
        'target_authority_digest',sealed.target_authority_digest,
        'conversion_context_digest',sealed.conversion_context_digest,
        'source_pay_method',sealed.source_pay_method,
        'current_target_pay_method',sealed.target_pay_method,
        'source_basis_json',(CASE
          WHEN jsonb_typeof(builder.component_json->'source_basis_json')='object'
            THEN builder.component_json->'source_basis_json'
          ELSE '{}'::jsonb END)||jsonb_build_object(
            'source_pay_method',sealed.source_pay_method))
        AS component_json
    FROM pg_temp.tmp_sync_builder_physical_components builder
    JOIN pg_temp.tmp_sync_sealed_rate_projection sealed
      ON sealed.timesheet_id=builder.timesheet_id
     AND sealed.physical_bucket_key=builder.physical_bucket_key
  ), grouped AS (
    SELECT overlaid.candidate_id,overlaid.timesheet_id,
      jsonb_agg(overlaid.component_json ORDER BY overlaid.component_ordinality) AS components_json
    FROM overlaid GROUP BY overlaid.candidate_id,overlaid.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET case_components_json=grouped.components_json
  FROM grouped
  WHERE preview_row.candidate_id=grouped.candidate_id
    AND preview_row.timesheet_id=grouped.timesheet_id;

  WITH fact_totals AS (
    SELECT component.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2)::numeric(12,2) AS truth_ex_vat,
      ROUND(COALESCE(SUM(entitlement.truth_inc_vat),0),2)::numeric(12,2) AS truth_inc_vat
    FROM pg_temp.tmp_sync_authoritative_components component
    LEFT JOIN (
      SELECT legacy_component.*
      FROM private.pay_current_timesheet_entitlement_components_from_build_v1(p_build_id,NULL::text) legacy_component
      WHERE v_execution_profile_version = 1
      UNION ALL
      SELECT cached_component.*
      FROM pg_temp.tmp_sync_entitlement_components_v2 cached_component
      WHERE v_execution_profile_version = 2
    ) entitlement
      ON entitlement.timesheet_id=component.timesheet_id
     AND entitlement.key_type=component.key_type AND entitlement.key_value=component.key_value
    GROUP BY component.timesheet_id
  )
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=COALESCE(fact_totals.truth_ex_vat,0),
      payment_amount_inc_vat=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      payment_amount=COALESCE(fact_totals.truth_inc_vat,fact_totals.truth_ex_vat,0),
      case_total_amount_ex=COALESCE(fact_totals.truth_ex_vat,0),
      safe_amount_ex=CASE WHEN preview_row.is_blocked THEN 0 ELSE COALESCE(fact_totals.truth_ex_vat,0) END,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  FROM fact_totals
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND preview_row.timesheet_id=fact_totals.timesheet_id;
  UPDATE pg_temp.timesheet_case_rollup_effective preview_row
  SET payment_amount_ex_vat=0,payment_amount_inc_vat=0,payment_amount=0,
      case_total_amount_ex=0,safe_amount_ex=0,case_components_json='[]'::jsonb,
      case_resolution_summary_json=COALESCE(preview_row.case_resolution_summary_json,'{}'::jsonb)
        ||jsonb_build_object('economic_authority','SEALED_ECONOMIC_BUILD_FACTS','build_id',p_build_id::text)
  WHERE preview_row.candidate_id=v_bounded_build.candidate_id
    AND EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
      WHERE scope_row.build_id=p_build_id AND scope_row.timesheet_id=preview_row.timesheet_id)
    AND NOT EXISTS(SELECT 1 FROM pg_temp.tmp_sync_authoritative_components component
      WHERE component.timesheet_id=preview_row.timesheet_id);

  -- Economic completeness is private build authority.  It is deliberately
  -- attested before presentation rendering so a zero-net, hidden, blocked or
  -- snoozed line is not required to invent a public row merely to prove that
  -- its physical components were preserved.
  SELECT md5(COALESCE(string_agg(
    sealed.timesheet_id::text||':'||sealed.economic_key_type||':'||
    sealed.economic_key_value||':'||sealed.physical_bucket_key||':'||
    sealed.sealed_evidence_digest,'' ORDER BY sealed.timesheet_id,
    sealed.economic_key_type,sealed.economic_key_value,sealed.bucket_sort_ordinal,
    sealed.physical_bucket_key),''))
  INTO v_bounded_economic_component_digest
  FROM pg_temp.tmp_sync_sealed_rate_projection sealed;

  v_bounded_canonical_result:=public.pay_preview_candidate_build_canonical_lines(
    v_preview_context_json,v_bounded_build.candidate_id);
  IF to_regclass('pg_temp.canonical_preview_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_CANONICAL_LINES_MISSING' USING ERRCODE='23514';
  END IF;
  IF to_regclass('pg_temp.canonical_timesheet_presentation_state') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_STATE_MISSING' USING ERRCODE='23514';
  END IF;
  -- The renderer's protected state must cover the sealed scope exactly.  Its
  -- ready + blocked + indefinitely-hidden allocation must also reconstruct the
  -- complete private economic truth.  Case-resolution presentation is an
  -- overlay and is intentionally not added to that economic total.
  WITH economic_target AS (
    SELECT DISTINCT component.timesheet_id
    FROM pg_temp.tmp_sync_authoritative_components component
  ), fact_truth AS (
    SELECT target.timesheet_id,
      ROUND(COALESCE(SUM(component.truth_ex_vat),0),2) AS truth_ex_vat
    FROM economic_target target
    LEFT JOIN pg_temp.tmp_sync_authoritative_components component
      ON component.timesheet_id=target.timesheet_id
    GROUP BY target.timesheet_id
  ), state_row AS (
    SELECT state.timesheet_id,COUNT(*) AS state_count,
      MIN(state.amount_ex_vat) AS amount_ex_vat,
      MIN(state.ready_section_amount_ex_vat) AS ready_amount,
      MIN(state.blocked_section_amount_ex_vat) AS blocked_amount,
      MIN(state.hidden_indefinite_segment_amount_ex_vat) AS hidden_segment_amount,
      MIN(state.hidden_expense_amount_ex_vat) AS hidden_expense_amount,
      BOOL_OR(COALESCE(state.resolved_segment_rows_replace_source_total,false))
        AS resolved_segment_rows_replace_source_total,
      MIN(component_allocation.component_count) AS component_count,
      MIN(component_allocation.invalid_amount_count) AS invalid_component_amount_count,
      MIN(component_allocation.presentation_amount_ex_vat)
        AS component_presentation_amount_ex_vat
    FROM pg_temp.canonical_timesheet_presentation_state state
    LEFT JOIN LATERAL (
      SELECT COUNT(*)::integer AS component_count,
        COUNT(*) FILTER (WHERE
          COALESCE(component.value->>'ready_preview_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$'
          AND COALESCE(component.value->>'preview_component_amount_ex_vat','')
            !~ '^-?\d+(\.\d+)?$')::integer AS invalid_amount_count,
        ROUND(COALESCE(SUM(CASE
          WHEN COALESCE(component.value->>'ready_preview_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'ready_preview_amount_ex_vat')::numeric
          WHEN COALESCE(component.value->>'preview_component_amount_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN (component.value->>'preview_component_amount_ex_vat')::numeric
          ELSE 0::numeric
        END),0),2) AS presentation_amount_ex_vat
      FROM jsonb_array_elements(CASE
        WHEN jsonb_typeof(state.case_components_json)='array'
          THEN state.case_components_json ELSE '[]'::jsonb END) component(value)
    ) component_allocation ON true
    WHERE state.candidate_id=v_bounded_build.candidate_id
    GROUP BY state.timesheet_id
  ), rollup_row AS (
    SELECT rollup.timesheet_id,COUNT(*) AS rollup_count
    FROM pg_temp.timesheet_case_rollup_effective rollup
    WHERE rollup.candidate_id=v_bounded_build.candidate_id
    GROUP BY rollup.timesheet_id
  ), canonical_line_row AS (
    SELECT line.timesheet_id,COUNT(*) AS line_count
    FROM pg_temp.canonical_timesheet_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY line.timesheet_id
  ), presentation_seed_row AS (
    SELECT seed.timesheet_id,COUNT(*) AS seed_count
    FROM pg_temp.canonical_timesheet_presentation_seed seed
    WHERE seed.candidate_id=v_bounded_build.candidate_id
    GROUP BY seed.timesheet_id
  ), mismatch AS (
    SELECT
      fact.timesheet_id IS NULL AS missing_fact_target,
      state.timesheet_id IS NULL AS missing_state,
      COALESCE(state.state_count,0)<>1 AS state_multiplicity_mismatch,
      ABS(COALESCE(state.amount_ex_vat,0)-COALESCE(fact.truth_ex_vat,0))>0.01
        AS truth_amount_mismatch,
      (
        COALESCE(state.resolved_segment_rows_replace_source_total,false)
        AND (COALESCE(state.component_count,0)=0
          OR COALESCE(state.invalid_component_amount_count,0)>0)
      ) AS resolved_basis_bridge_invalid,
      ABS(COALESCE(CASE
        -- A resolved-rate presentation is intentionally target-valued while
        -- amount_ex_vat remains the sealed source economic truth.  The
        -- renderer's existing replacement marker selects the independently
        -- materialised component presentation total for this sum only.
        WHEN COALESCE(state.resolved_segment_rows_replace_source_total,false)
          THEN state.component_presentation_amount_ex_vat
        ELSE state.amount_ex_vat
      END,0)-(
        COALESCE(state.ready_amount,0)+COALESCE(state.blocked_amount,0)
        +COALESCE(state.hidden_segment_amount,0)+COALESCE(state.hidden_expense_amount,0)))>0.01
        AS allocation_sum_mismatch,
      COALESCE(rollup.rollup_count,0)>0 AS rollup_present,
      COALESCE(canonical_line.line_count,0)>0 AS canonical_line_present,
      COALESCE(presentation_seed.seed_count,0)>0 AS presentation_seed_present
    FROM fact_truth fact
    FULL OUTER JOIN state_row state USING(timesheet_id)
    LEFT JOIN rollup_row rollup USING(timesheet_id)
    LEFT JOIN canonical_line_row canonical_line USING(timesheet_id)
    LEFT JOIN presentation_seed_row presentation_seed USING(timesheet_id)
  )
  SELECT jsonb_build_object(
    'mismatch_count',count(*) FILTER (
      WHERE missing_fact_target OR missing_state OR state_multiplicity_mismatch
         OR truth_amount_mismatch OR resolved_basis_bridge_invalid
         OR allocation_sum_mismatch),
    'missing_fact_target_count',count(*) FILTER (WHERE missing_fact_target),
    'missing_state_count',count(*) FILTER (WHERE missing_state),
    'state_multiplicity_mismatch_count',count(*) FILTER (WHERE state_multiplicity_mismatch),
    'truth_amount_mismatch_count',count(*) FILTER (WHERE truth_amount_mismatch),
    'resolved_basis_bridge_invalid_count',count(*) FILTER (
      WHERE resolved_basis_bridge_invalid),
    'allocation_sum_mismatch_count',count(*) FILTER (WHERE allocation_sum_mismatch),
    'missing_state_with_rollup_count',count(*) FILTER (WHERE missing_state AND rollup_present),
    'missing_state_with_canonical_line_count',count(*) FILTER (
      WHERE missing_state AND canonical_line_present),
    'missing_state_with_presentation_seed_count',count(*) FILTER (
      WHERE missing_state AND presentation_seed_present)
  )
  INTO v_presentation_mismatch_detail
  FROM mismatch;

  IF COALESCE((v_presentation_mismatch_detail->>'mismatch_count')::integer,0)>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_ALLOCATION_AUTHORITY_MISMATCH %',
      v_presentation_mismatch_detail::text
      USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1 FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
      AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
      AND (
        COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR NOT EXISTS(
          SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=p_build_id
            AND scope_row.timesheet_id=COALESCE(line.line_json->>'real_business_timesheet_id',
              line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid)
        OR UPPER(BTRIM(COALESCE(line.pay_channel::text,''))) IS DISTINCT FROM v_scope
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_FACT_AUTHORITY_MISMATCH' USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    SELECT 1
    FROM pg_temp.canonical_preview_lines line
    WHERE line.candidate_id=v_bounded_build.candidate_id
    GROUP BY COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
      NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
      NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
      md5(line.line_json::text))
    HAVING count(*)>1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_LINE_IDENTITY_CONFLICT %', (
      WITH keyed_lines AS (
        SELECT
          COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
            NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
            NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
            md5(line.line_json::text)) AS line_identity,
          CASE
            WHEN NULLIF(BTRIM(line.line_json->>'presentation_line_id'),'') IS NOT NULL THEN 'PRESENTATION_LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'preview_row_id'),'') IS NOT NULL THEN 'PREVIEW_ROW_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'line_id'),'') IS NOT NULL THEN 'LINE_ID'
            WHEN NULLIF(BTRIM(line.line_json->>'case_key'),'') IS NOT NULL THEN 'CASE_KEY'
            ELSE 'ROW_DIGEST'
          END AS identity_source,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_role'),''),'~')) AS presentation_role,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_section'),''),'~')) AS presentation_section,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'line_type'),''),'~')) AS line_type,
          UPPER(COALESCE(NULLIF(BTRIM(line.line_json->>'component_key_type'),''),'~')) AS component_key_type,
          UPPER(COALESCE(NULLIF(BTRIM(COALESCE(
            line.line_json->>'bucket_code',
            line.line_json#>>'{source_basis_json,bucket_code}'
          )),''),'~')) AS bucket_code
        FROM pg_temp.canonical_preview_lines line
        WHERE line.candidate_id=v_bounded_build.candidate_id
      ), duplicate_identities AS (
        SELECT keyed.line_identity,count(*)::integer AS row_count
        FROM keyed_lines keyed
        GROUP BY keyed.line_identity
        HAVING count(*)>1
      ), duplicate_rows AS (
        SELECT keyed.*
        FROM keyed_lines keyed
        JOIN duplicate_identities duplicate_identity
          ON duplicate_identity.line_identity=keyed.line_identity
      ), shape_counts AS (
        SELECT concat_ws('|',duplicate_row.identity_source,duplicate_row.presentation_role,
                 duplicate_row.presentation_section,duplicate_row.line_type,
                 duplicate_row.component_key_type,duplicate_row.bucket_code) AS shape,
               count(*)::integer AS row_count
        FROM duplicate_rows duplicate_row
        GROUP BY duplicate_row.identity_source,duplicate_row.presentation_role,
          duplicate_row.presentation_section,duplicate_row.line_type,
          duplicate_row.component_key_type,duplicate_row.bucket_code
      )
      SELECT jsonb_build_object(
        'duplicate_identity_count',(SELECT count(*)::integer FROM duplicate_identities),
        'duplicate_row_count',(SELECT count(*)::integer FROM duplicate_rows),
        'maximum_identity_multiplicity',COALESCE((SELECT max(row_count) FROM duplicate_identities),0),
        'line_shape_counts',COALESCE((SELECT jsonb_object_agg(shape,row_count ORDER BY shape)
          FROM shape_counts),'{}'::jsonb)
      )
    )::text USING ERRCODE='23514';
  END IF;
  IF EXISTS(
    WITH expected AS (
      SELECT (allocation.value->>'timesheet_id')::uuid AS timesheet_id,
        allocation.value->>'line_identity' AS line_identity,
        allocation.value->>'parent_line_identity' AS parent_line_identity,
        allocation.value->>'presentation_section' AS presentation_section,
        allocation.value->>'pay_channel' AS pay_channel,
        ROUND((allocation.value->>'amount_ex_vat')::numeric,2) AS amount_ex_vat,
        (allocation.value->>'draftable')::boolean AS draftable,
        (allocation.value->>'excluded_from_allocation')::boolean AS excluded_from_allocation,
        ROUND((allocation.value->>'section_non_segment_amount_ex_vat')::numeric,2)
          AS section_non_segment_amount_ex_vat,
        allocation.value->'section_segment_rows' AS section_segment_rows,
        (allocation.value->>'resolved_segment_rows_replace_source_total')::boolean
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid
          AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),'')) AS line_identity,
        NULLIF(BTRIM(line.line_json->>'presentation_parent_line_id'),'') AS parent_line_identity,
        UPPER(NULLIF(BTRIM(line.line_json->>'presentation_section'),'')) AS presentation_section,
        UPPER(BTRIM(COALESCE(line.pay_channel::text,line.line_json->>'pay_channel',''))) AS pay_channel,
        ROUND(COALESCE(line.amount_ex_vat,0),2) AS amount_ex_vat,
        COALESCE((line.line_json->>'is_ready_for_draft')::boolean,false) AS draftable,
        COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)
          AS excluded_from_allocation,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
        ) AS semantic_non_selectable_parent,
        (
          UPPER(COALESCE(line.line_json->>'presentation_role',''))='PARENT'
          AND UPPER(COALESCE(line.line_json->>'presentation_reason',''))=
            'NEGATIVE_ORDINARY_PRESENTATION_ONLY'
          AND UPPER(COALESCE(line.line_json->>'presentation_section',''))='BLOCKED_FOR_PAY'
          AND COALESCE((line.line_json->>'selection_allowed')::boolean,false)=false
          AND COALESCE((line.line_json->>'is_excluded_from_allocation')::boolean,false)=true
          AND ROUND(COALESCE(line.amount_ex_vat,0),2)<0
        ) AS semantic_negative_parent,
        ROUND(COALESCE((line.line_json->>'section_non_segment_amount_ex_vat')::numeric,0),2)
          AS section_non_segment_amount_ex_vat,
        CASE WHEN jsonb_typeof(line.line_json->'section_segment_rows')='array'
          THEN line.line_json->'section_segment_rows' ELSE '[]'::jsonb END AS section_segment_rows,
        COALESCE((line.line_json->>'resolved_segment_rows_replace_source_total')::boolean,false)
          AS resolved_segment_rows_replace_source_total
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        -- Semantic V3 publishes exact keyed allocation components beside the
        -- aggregate presentation parent.  The protected presentation fence
        -- continues to compare the parent only; economic component equality
        -- is independently enforced by the canonical fact-component fence
        -- immediately below.
        AND UPPER(COALESCE(line.line_json->>'presentation_role','PARENT'))
          <> 'ALLOCATION_COMPONENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT 1
    FROM expected
    FULL OUTER JOIN actual USING(timesheet_id,line_identity)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.parent_line_identity IS DISTINCT FROM expected.parent_line_identity
       OR (
         actual.presentation_section IS DISTINCT FROM expected.presentation_section
         AND NOT (
           actual.semantic_negative_parent
           AND actual.presentation_section='BLOCKED_FOR_PAY'
           AND expected.presentation_section='READY_TO_PAY'
         )
       )
       OR actual.pay_channel IS DISTINCT FROM expected.pay_channel
       OR ABS(actual.amount_ex_vat-expected.amount_ex_vat)>0.01
       OR (
         actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM false
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.draftable IS DISTINCT FROM expected.draftable
       )
       OR (
         NOT actual.semantic_non_selectable_parent
         AND actual.excluded_from_allocation IS DISTINCT FROM expected.excluded_from_allocation
       )
       OR ABS(actual.section_non_segment_amount_ex_vat-
         expected.section_non_segment_amount_ex_vat)>0.01
       OR actual.section_segment_rows IS DISTINCT FROM expected.section_segment_rows
       OR actual.resolved_segment_rows_replace_source_total IS DISTINCT FROM
         expected.resolved_segment_rows_replace_source_total
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PRESENTATION_ALLOCATION_MISMATCH'
      USING ERRCODE='23514';
  END IF;
  SELECT md5(COALESCE(string_agg(allocation.value::text,'' ORDER BY
    allocation.value->>'timesheet_id',allocation.value->>'line_identity'),''))
  INTO v_bounded_presentation_allocation_digest
  FROM pg_temp.canonical_timesheet_presentation_state state
  CROSS JOIN LATERAL jsonb_array_elements(
    private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
  WHERE state.candidate_id=v_bounded_build.candidate_id;
  IF EXISTS(
    WITH expected AS (
      SELECT sealed.timesheet_id,sealed.economic_key_type AS key_type,
        sealed.economic_key_value AS key_value,sealed.physical_bucket_key,
        sealed.evidence_json#>>'{physical_bucket,builder_comparison_digest}'
          AS builder_comparison_digest,
        sealed.outstanding_ex_vat AS component_amount_ex_vat,
        sealed.truth_ex_vat,sealed.baseline_ex_vat,sealed.reserved_ex_vat,
        sealed.outstanding_ex_vat,sealed.physical_bucket_digest,
        sealed.sealed_evidence_digest,sealed.financial_revision_digest,
        sealed.target_authority_digest,sealed.conversion_context_digest
      FROM pg_temp.tmp_sync_sealed_rate_projection sealed
      WHERE sealed.evidence_json#>>'{physical_bucket,builder_component_expected}'='true'
    ), actual_lines AS (
      SELECT COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid AS timesheet_id,
        COALESCE(NULLIF(BTRIM(line.line_json->>'presentation_line_id'),''),
          NULLIF(BTRIM(line.line_json->>'preview_row_id'),''),
          NULLIF(BTRIM(line.line_json->>'line_id'),''),NULLIF(BTRIM(line.line_json->>'case_key'),''),
          md5(line.line_json::text)) AS line_identity,
        CASE WHEN jsonb_typeof(line.line_json->'case_components')='array'
          THEN line.line_json->'case_components' ELSE '[]'::jsonb END AS components_json
      FROM pg_temp.canonical_preview_lines line
      WHERE line.candidate_id=v_bounded_build.candidate_id
        AND UPPER(COALESCE(line.line_json->>'line_type',''))='TIMESHEET_PAYMENT'
        AND COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), expected_presentation_timesheets AS (
      SELECT DISTINCT (allocation.value->>'timesheet_id')::uuid AS timesheet_id
      FROM pg_temp.canonical_timesheet_presentation_state state
      CROSS JOIN LATERAL jsonb_array_elements(
        private.pay_workbench_presentation_allocation_expected_v1(to_jsonb(state))) allocation(value)
      WHERE state.candidate_id=v_bounded_build.candidate_id
    ), actual_occurrence AS (
      SELECT actual_line.timesheet_id,actual_line.line_identity,
        UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')) AS key_type,
        NULLIF(BTRIM(component.value->>'component_key_value'),'') AS key_value,
        NULLIF(BTRIM(component.value->>'physical_bucket_key'),'') AS physical_bucket_key,
        md5(jsonb_build_object(
          'builder_comparison_version',1,
          'timesheet_id',actual_line.timesheet_id::text,
          'source_family_key',NULLIF(BTRIM(component.value->>'source_family_key'),''),
          'component_key_type',UPPER(NULLIF(BTRIM(component.value->>'component_key_type'),'')),
          'component_key_value',NULLIF(BTRIM(component.value->>'component_key_value'),''),
          'segment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),''),
          'segment_key',COALESCE(
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_key}'),''),
            NULLIF(BTRIM(component.value#>>'{source_basis_json,segment_id}'),'')),
          'segment_stable_key',NULLIF(BTRIM(
            component.value#>>'{source_basis_json,segment_stable_key}'),''),
          'work_date',NULLIF(BTRIM(COALESCE(component.value#>>'{source_basis_json,work_date}',
            component.value#>>'{source_basis_json,date}')),''),
          'ref_num',NULLIF(BTRIM(component.value#>>'{source_basis_json,ref_num}'),''),
          'additional_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,additional_code}')),''),
          'expense_code',NULLIF(UPPER(BTRIM(
            component.value#>>'{source_basis_json,expense_code}')),''),
          'adjustment_id',NULLIF(BTRIM(component.value#>>'{source_basis_json,adjustment_id}'),''),
          'bucket_code',UPPER(BTRIM(COALESCE(
            CASE WHEN UPPER(BTRIM(COALESCE(
                component.value#>>'{source_basis_json,component_fallback}','')))='WORKED_TIME_AMOUNT'
              THEN 'FIXED' END,
            NULLIF(component.value#>>'{source_basis_json,bucket_code}',''),
            CASE UPPER(BTRIM(component.value->>'component_key_type'))
              WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
              WHEN 'EXPENSE_CODE' THEN 'FIXED'
              WHEN 'ADJUSTMENT_CODE' THEN 'FIXED'
            END))),
          'source_units',CASE WHEN COALESCE(component.value->>'source_units','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_units')::numeric,6) END,
          'source_rate',CASE WHEN COALESCE(component.value->>'source_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_rate')::numeric,6) END,
          'source_charge_rate',CASE WHEN COALESCE(component.value->>'source_charge_rate','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_rate')::numeric,6) END,
          'source_pay_ex_vat',CASE WHEN COALESCE(component.value->>'source_pay_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_pay_ex_vat')::numeric,2) END,
          'source_charge_ex_vat',CASE WHEN COALESCE(component.value->>'source_charge_ex_vat','')
              ~ '^-?\d+(\.\d+)?$'
            THEN ROUND((component.value->>'source_charge_ex_vat')::numeric,2) END,
          'source_pay_method',UPPER(NULLIF(BTRIM(component.value->>'source_pay_method'),'')),
          'target_pay_method',UPPER(NULLIF(BTRIM(
            component.value->>'current_target_pay_method'),'')))::text)
          AS builder_comparison_digest,
        CASE WHEN COALESCE(component.value->>'component_amount_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'component_amount_ex_vat')::numeric,2) END
          AS component_amount_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_truth_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_truth_ex_vat')::numeric,2) END
          AS truth_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_baseline_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_baseline_ex_vat')::numeric,2) END
          AS baseline_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_reserved_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_reserved_ex_vat')::numeric,2) END
          AS reserved_ex_vat,
        CASE WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((component.value->>'authoritative_outstanding_ex_vat')::numeric,2) END
          AS outstanding_ex_vat,
        NULLIF(BTRIM(component.value->>'physical_bucket_digest'),'') AS physical_bucket_digest,
        NULLIF(BTRIM(component.value->>'sealed_evidence_digest'),'') AS sealed_evidence_digest,
        NULLIF(BTRIM(component.value->>'financial_revision_digest'),'') AS financial_revision_digest,
        NULLIF(BTRIM(component.value->>'target_authority_digest'),'') AS target_authority_digest,
        NULLIF(BTRIM(component.value->>'conversion_context_digest'),'') AS conversion_context_digest
      FROM actual_lines actual_line
      CROSS JOIN LATERAL jsonb_array_elements(actual_line.components_json) component(value)
    ), conflicting_actual AS (
      SELECT timesheet_id,line_identity,physical_bucket_key
      FROM actual_occurrence
      GROUP BY timesheet_id,line_identity,physical_bucket_key
      HAVING physical_bucket_key IS NULL
        OR bool_or(key_type IS NULL OR key_value IS NULL OR
          builder_comparison_digest IS NULL OR physical_bucket_digest IS NULL OR
          sealed_evidence_digest IS NULL)
        OR count(*)>1
        OR count(DISTINCT jsonb_build_object('key_type',key_type,'key_value',key_value,
          'builder_comparison_digest',builder_comparison_digest,
          'component_amount_ex_vat',component_amount_ex_vat,'truth_ex_vat',truth_ex_vat,
          'baseline_ex_vat',baseline_ex_vat,'reserved_ex_vat',reserved_ex_vat,
          'outstanding_ex_vat',outstanding_ex_vat,
          'physical_bucket_digest',physical_bucket_digest,
          'sealed_evidence_digest',sealed_evidence_digest,
          'financial_revision_digest',financial_revision_digest,
          'target_authority_digest',target_authority_digest,
          'conversion_context_digest',conversion_context_digest))>1
    ), actual AS (
      -- Presentation splitting may repeat one identical physical component on
      -- several stable lines.  Collapse only after per-line duplicate and
      -- conflict checks have succeeded; never collapse DAY and NIGHT together.
      SELECT DISTINCT timesheet_id,key_type,key_value,physical_bucket_key,
        builder_comparison_digest,component_amount_ex_vat,truth_ex_vat,
        baseline_ex_vat,reserved_ex_vat,outstanding_ex_vat,
        physical_bucket_digest,sealed_evidence_digest,financial_revision_digest,
        target_authority_digest,conversion_context_digest
      FROM actual_occurrence
    ), expected_rendered AS (
      SELECT expected.* FROM expected
      JOIN expected_presentation_timesheets USING(timesheet_id)
    )
    SELECT 1 FROM conflicting_actual
    UNION ALL
    SELECT 1 FROM expected_rendered expected
      FULL OUTER JOIN actual USING(timesheet_id,key_type,key_value,physical_bucket_key)
    WHERE expected.timesheet_id IS NULL OR actual.timesheet_id IS NULL
       OR actual.builder_comparison_digest IS DISTINCT FROM expected.builder_comparison_digest
       OR actual.component_amount_ex_vat IS DISTINCT FROM expected.component_amount_ex_vat
       OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
       OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
       OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
       OR actual.outstanding_ex_vat IS DISTINCT FROM expected.outstanding_ex_vat
       OR actual.physical_bucket_digest IS DISTINCT FROM expected.physical_bucket_digest
       OR actual.sealed_evidence_digest IS DISTINCT FROM expected.sealed_evidence_digest
       OR actual.financial_revision_digest IS DISTINCT FROM expected.financial_revision_digest
       OR actual.target_authority_digest IS DISTINCT FROM expected.target_authority_digest
       OR actual.conversion_context_digest IS DISTINCT FROM expected.conversion_context_digest
  ) THEN
    RAISE EXCEPTION 'PAY_SYNC_OVERPAYMENTS_RATE_PHYSICAL_FENCE_MISMATCH' USING ERRCODE='P0001';
  END IF;

  v_canonical_render_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;
  v_phase_started_at := clock_timestamp();

  IF v_slice_active THEN
    -- A28: earlier slices' staged lines are kept (private, unpublished). A first slice never has any.
    SELECT COALESCE(max(source_ordinal),0),count(*)::integer INTO v_slice_ordinal_base,v_slice_line_total
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    IF COALESCE((v_slice_plan->>'slices_completed')::integer,0)=0 AND v_slice_line_total>0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_STAGE_NOT_EMPTY' USING ERRCODE='23514';
    END IF;
    IF v_slice_line_total IS DISTINCT FROM COALESCE((v_slice_plan->>'staged_line_count')::integer,0) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_STAGE_MISMATCH' USING ERRCODE='23514';
    END IF;
    SELECT count(*) FILTER (WHERE owner.is_candidate_level AND NOT v_slice_final)::integer,
           count(*) FILTER (WHERE NOT owner.is_candidate_level AND owner.line_timesheet_id IS NOT NULL
             AND NOT (owner.line_timesheet_id=ANY(v_bounded_scope_ids))
             AND EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope other_scope
               WHERE other_scope.build_id=p_build_id AND other_scope.timesheet_id=owner.line_timesheet_id))::integer
    INTO v_slice_dropped_candidate_level,v_slice_dropped_other_slice
    FROM pg_temp.canonical_preview_lines line
    CROSS JOIN LATERAL (SELECT
      (COALESCE(line.line_json->>'preview_row_id','') LIKE 'finance:%'
        OR UPPER(COALESCE(line.line_json->>'line_type',''))='MANUAL_ADJUSTMENT_CARRY_FORWARD') AS is_candidate_level,
      CASE WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN COALESCE(line.line_json->>'real_business_timesheet_id',
          line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid END AS line_timesheet_id
    ) owner
    WHERE line.candidate_id=v_bounded_build.candidate_id;
  ELSE
  DELETE FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
  END IF;
  v_bounded_canonical_stage_timestamp:=clock_timestamp();
  INSERT INTO private.banking_pay_workbench_canonical_stage_lines(
    build_id,source_ordinal,session_id,candidate_id,session_version,source_change_seq,
    source_build_run_id,timesheet_id,line_key,parent_line_key,split_suffix,section,
    source_row_json,economic_key_json,contract_json,pay_channel_scope,
    refresh_scope_kind,row_digest,stage_status,verified_at_utc,created_at_utc
  )
  SELECT p_build_id,
    v_slice_ordinal_base+row_number() OVER(ORDER BY public.pay_workbench_preview_section_from_line_json(line.line_json),
      COALESCE(line.line_json->>'preview_row_id',line.line_json->>'line_id',
        line.line_json->>'case_key',md5(line.line_json::text)))::bigint,
    v_bounded_build.session_id,v_bounded_build.candidate_id,v_bounded_build.session_version,
    v_bounded_build.source_change_seq,v_bounded_build.source_build_run_id,
    CASE WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
      line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(line.line_json->>'real_business_timesheet_id',
        line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid ELSE NULL END,
    COALESCE(NULLIF(btrim(line.line_json->>'preview_row_id'),''),
      NULLIF(btrim(line.line_json->>'line_id'),''),NULLIF(btrim(line.line_json->>'case_key'),''),
      md5(line.line_json::text)),
    NULLIF(btrim(line.line_json->>'parent_line_key'),''),
    NULLIF(btrim(line.line_json->>'split_suffix'),''),
    public.pay_workbench_preview_section_from_line_json(line.line_json),line.line_json,
    CASE WHEN jsonb_typeof(line.line_json->'economic_key')='object'
      THEN line.line_json->'economic_key' ELSE '{}'::jsonb END,
    CASE WHEN jsonb_typeof(line.line_json->'contract_json')='object'
      THEN line.line_json->'contract_json'
      WHEN jsonb_typeof(line.line_json->'contract')='object' THEN line.line_json->'contract'
      ELSE '{}'::jsonb END,
    v_scope,'BOUNDED_ECONOMIC_BUILD',md5(line.line_json::text),'VERIFIED',
    v_bounded_canonical_stage_timestamp,v_bounded_canonical_stage_timestamp
  FROM pg_temp.canonical_preview_lines line
  WHERE line.candidate_id=v_bounded_build.candidate_id
    -- A28: a slice stages only what it owns. Timesheet lines belong to the slice of their Timesheet; the
    -- Candidate-level balance lines (finance cases, carry-forwards) and any line outside the build scope belong
    -- to the final slice, which sees the whole Candidate's headroom.
    AND (NOT v_slice_active OR (
      CASE WHEN COALESCE(line.line_json->>'preview_row_id','') LIKE 'finance:%'
             OR UPPER(COALESCE(line.line_json->>'line_type',''))='MANUAL_ADJUSTMENT_CARRY_FORWARD' THEN v_slice_final
        WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
            line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_slice_final
        WHEN COALESCE(line.line_json->>'real_business_timesheet_id',
            line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid
            =ANY(v_bounded_scope_ids) THEN true
        WHEN EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope other_scope
            WHERE other_scope.build_id=p_build_id
              AND other_scope.timesheet_id=COALESCE(line.line_json->>'real_business_timesheet_id',
                line.line_json#>>'{economic_key,timesheet_id}',line.line_json->>'timesheet_id')::uuid) THEN false
        ELSE v_slice_final END));
  GET DIAGNOSTICS v_slice_kept = ROW_COUNT;

  IF v_slice_active AND v_slice_final THEN
    -- A28: restore exactly the unsliced staging order over every staged line (two collision-free passes).
    SELECT COALESCE(max(source_ordinal),0) INTO v_slice_max_ordinal
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    WITH ordered AS (
      SELECT stage_line.source_ordinal AS old_ordinal,
        row_number() OVER(ORDER BY public.pay_workbench_preview_section_from_line_json(stage_line.source_row_json),
          COALESCE(stage_line.source_row_json->>'preview_row_id',stage_line.source_row_json->>'line_id',
            stage_line.source_row_json->>'case_key',md5(stage_line.source_row_json::text)),
          stage_line.line_key,stage_line.timesheet_id NULLS FIRST)::bigint AS new_ordinal
      FROM private.banking_pay_workbench_canonical_stage_lines stage_line
      WHERE stage_line.build_id=p_build_id
    )
    UPDATE private.banking_pay_workbench_canonical_stage_lines stage_line
    SET source_ordinal=v_slice_max_ordinal+ordered.new_ordinal
    FROM ordered
    WHERE stage_line.build_id=p_build_id AND stage_line.source_ordinal=ordered.old_ordinal;
    UPDATE private.banking_pay_workbench_canonical_stage_lines
    SET source_ordinal=source_ordinal-v_slice_max_ordinal
    WHERE build_id=p_build_id;
  END IF;

  IF v_slice_active AND NOT v_slice_final THEN
    -- A28: close a non-final slice. Its lines stay privately staged; nothing is published; the build returns
    -- to READY_FOR_RECONCILIATION for the next slice's own bounded capture and execute. The slice's additive
    -- recovery headroom is carried to the final slice.
    IF to_regclass('pg_temp.candidate_authoritative_recovery_headroom') IS NOT NULL THEN
      EXECUTE 'SELECT COALESCE(sum(authoritative_recovery_headroom_ex),0) FROM pg_temp.candidate_authoritative_recovery_headroom WHERE candidate_id=$1'
        INTO v_slice_recovery_headroom USING v_bounded_build.candidate_id;
    END IF;
    IF to_regclass('pg_temp.timesheet_allocation_component_lines') IS NOT NULL THEN
      EXECUTE 'SELECT COALESCE(round(sum(amount_ex_vat),2),0) FROM pg_temp.timesheet_allocation_component_lines WHERE candidate_id=$1 AND amount_ex_vat>0'
        INTO v_slice_ordinary_headroom USING v_bounded_build.candidate_id;
    END IF;
    SELECT count(*)::integer INTO v_slice_line_total
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;
    UPDATE private.banking_pay_workbench_economic_builds
    SET status='READY_FOR_RECONCILIATION',
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'effect_plan_sealed',false,
          'reconcile_slicing',(v_slice_plan-'current')||jsonb_build_object(
            'next_after_unit_ordinal',(v_slice->>'through_unit_ordinal')::bigint,
            'slices_completed',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
            'reconciled_timesheet_count',COALESCE((v_slice_plan->>'reconciled_timesheet_count')::integer,0)+v_bounded_scope_count,
            'prior_recovery_headroom_ex',ROUND(COALESCE((v_slice_plan->>'prior_recovery_headroom_ex')::numeric,0)+COALESCE(v_slice_recovery_headroom,0),2),
            'prior_ordinary_positive_headroom_ex',ROUND(COALESCE((v_slice_plan->>'prior_ordinary_positive_headroom_ex')::numeric,0)+COALESCE(v_slice_ordinary_headroom,0),2),
            'observed_finance_effect_count',COALESCE((v_slice_plan->>'observed_finance_effect_count')::integer,0)+v_observed_effect_count,
            'staged_line_count',v_slice_line_total,
            'last_slice',jsonb_build_object('index',v_slice->'index','timesheet_count',v_bounded_scope_count,
              'unit_count',v_slice->'unit_count','staged_lines',v_slice_kept,
              'held_for_final_slice',v_slice_dropped_candidate_level,'owned_by_other_slice',v_slice_dropped_other_slice,
              'recovery_headroom_ex',COALESCE(v_slice_recovery_headroom,0),
              'ordinary_positive_headroom_ex',COALESCE(v_slice_ordinary_headroom,0),
              'observed_finance_effect_count',v_observed_effect_count,
              'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer,
              'case_workspace_ms',v_case_workspace_ms,'finance_apply_ms',v_finance_apply_ms,
              'canonical_render_ms',v_canonical_render_ms))),
        updated_at_utc=clock_timestamp()
    WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true);
    RETURN jsonb_build_object(
      'ok',true,'public_result_json',v_public_result_json,
      'internal_result_json',jsonb_build_object('build_id',p_build_id,'attempt_id',p_attempt_id,
        'slice_index',v_slice->'index','slice_final',false,'scope_timesheet_count',v_bounded_scope_count,
        'staged_lines',v_slice_kept,'total_reconcile_ms',
        FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer),
      'build_id',p_build_id,'attempt_id',p_attempt_id,'slice_index',v_slice->'index','slice_final',false,
      'scope_timesheet_count',v_bounded_scope_count);
  END IF;

  SELECT count(*)::integer,
         md5(COALESCE(string_agg(row_digest,'' ORDER BY source_ordinal),''))
  INTO v_bounded_canonical_count,v_bounded_canonical_digest
  FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=p_build_id;

  SELECT md5(jsonb_build_object(
    'candidate_id',v_bounded_build.candidate_id,'case_count',count(*),
    'case_digest',md5(COALESCE(string_agg(md5(to_jsonb(case_row)::text),'' ORDER BY case_row.id),''))
  )::text)
  INTO v_bounded_post_sync_digest
  FROM public.pay_advances case_row WHERE case_row.candidate_id=v_bounded_build.candidate_id;

  v_canonical_stage_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_phase_started_at))*1000)::integer;

  UPDATE private.banking_pay_workbench_economic_builds
  SET status='RECONCILED',private_stage='SOURCE_PUBLISH',fact_count=v_bounded_fact_count,
      pre_sync_digest=v_bounded_pre_sync_digest,post_sync_digest=v_bounded_post_sync_digest,
      canonical_count=v_bounded_canonical_count,canonical_digest=v_bounded_canonical_digest,
      attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
        'version',1,'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH',
        'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_count',v_slice_total_scope_count,
        'fact_count',v_bounded_fact_count,'canonical_count',v_bounded_canonical_count,
        'effect_plan_sealed',true,
        'effect_plan_count',COALESCE((v_bounded_build.attestation_json->>'effect_plan_count')::integer,0),
        'effect_plan_digest',v_bounded_build.attestation_json->>'effect_plan_digest',
        'effect_plan_created_at_utc',v_bounded_build.attestation_json->'effect_plan_created_at_utc',
        'observed_finance_effect_count',v_observed_effect_count,
        'observed_finance_effect_digest',v_observed_effect_digest,
        'economic_component_digest',v_bounded_economic_component_digest,
        'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
        'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
        'canonical_digest',v_bounded_canonical_digest,
        'reconcile_slicing',CASE WHEN v_slice_active THEN (v_slice_plan-'current')||jsonb_build_object(
          'slices_completed',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
          'reconciled_timesheet_count',COALESCE((v_slice_plan->>'reconciled_timesheet_count')::integer,0)+v_bounded_scope_count,
          'observed_finance_effect_count',COALESCE((v_slice_plan->>'observed_finance_effect_count')::integer,0)+v_observed_effect_count,
          'staged_line_count',v_bounded_canonical_count,'completed_at_utc',clock_timestamp(),
          'last_slice',jsonb_build_object('index',v_slice->'index','timesheet_count',v_bounded_scope_count,
            'unit_count',v_slice->'unit_count','staged_lines',v_slice_kept,'final',true,
            'observed_finance_effect_count',v_observed_effect_count,
            'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer))
          ELSE NULL::jsonb END,
        'reconcile_execute_timing_json',jsonb_build_object(
          'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
          'workspace_cache_ms',v_workspace_cache_ms,
          'freshness_set_ms',v_freshness_set_ms,
          'authoritative_components_ms',v_authoritative_components_ms,
          'preflight_setup_ms',v_preflight_setup_ms,
          'correction_residuals_ms',v_correction_residuals_ms,
          'authority_validation_ms',v_authority_validation_ms,
          'component_assembly_ms',v_component_assembly_ms,
          'preview_workspace_ms',v_preview_workspace_ms,
          'preview_collect_ms',v_preview_collect_ms,
          'preview_canonical_ms',v_preview_canonical_ms,
          'preview_summary_ms',v_preview_summary_ms,
          'case_workspace_ms',v_case_workspace_ms,
          'finance_apply_ms',v_finance_apply_ms,
          'post_freshness_ms',v_post_freshness_ms,
          'canonical_render_ms',v_canonical_render_ms,
          'canonical_stage_ms',v_canonical_stage_ms,
          'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer)),
      reconciled_at_utc=clock_timestamp(),publication_cursor_json=jsonb_build_object(
        'cursor_kind','SOURCE_PUBLISH','cursor_version',1,'build_id',p_build_id,
        'candidate_id',v_bounded_build.candidate_id,'canonical_count',v_bounded_canonical_count,
        'canonical_digest',v_bounded_canonical_digest),updated_at_utc=clock_timestamp()
  WHERE id=p_build_id AND status='RECONCILING' AND private_stage='RECONCILE_EXECUTE';
  IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
  PERFORM set_config('cloudtms.pay_workbench_reconcile_slice_v1','',true); /* A28 */

  RETURN jsonb_build_object(
    'ok',true,'public_result_json',v_public_result_json,
    'internal_result_json',jsonb_build_object(
      'build_id',p_build_id,'attempt_id',p_attempt_id,'scope_timesheet_count',v_bounded_scope_count,
      'fact_count',v_bounded_fact_count,'canonical_stage_count',v_bounded_canonical_count,
      'economic_component_digest',v_bounded_economic_component_digest,
      'presentation_allocation_digest',v_bounded_presentation_allocation_digest,
      'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
      'canonical_digest',v_bounded_canonical_digest,
      'execution_profile_version',v_execution_profile_version,
      'reconciliation_optimization_version',v_reconciliation_optimization_version,
      'freshness_set_ms',v_freshness_set_ms,
      'workspace_cache_ms',v_workspace_cache_ms,
      'authoritative_components_ms',v_authoritative_components_ms,
      'preflight_setup_ms',v_preflight_setup_ms,
      'correction_residuals_ms',v_correction_residuals_ms,
      'authority_validation_ms',v_authority_validation_ms,
      'component_assembly_ms',v_component_assembly_ms,
      'preview_workspace_ms',v_preview_workspace_ms,
      'preview_collect_ms',v_preview_collect_ms,
      'preview_canonical_ms',v_preview_canonical_ms,
      'preview_summary_ms',v_preview_summary_ms,
      'case_workspace_ms',v_case_workspace_ms,
      'finance_apply_ms',v_finance_apply_ms,
      'post_freshness_ms',v_post_freshness_ms,
      'canonical_render_ms',v_canonical_render_ms,
      'canonical_stage_ms',v_canonical_stage_ms,
      'total_reconcile_ms',FLOOR(EXTRACT(EPOCH FROM (clock_timestamp()-v_reconcile_started_at))*1000)::integer),
    'build_id',p_build_id,'attempt_id',p_attempt_id,
    'scope_timesheet_count',v_slice_total_scope_count,
    'slice_final',CASE WHEN v_slice_active THEN true ELSE NULL END,
    'canonical_stage_count',v_bounded_canonical_count,
    'pre_sync_digest',v_bounded_pre_sync_digest,'post_sync_digest',v_bounded_post_sync_digest,
    'canonical_digest',v_bounded_canonical_digest
  );
exception
  when others then
    GET STACKED DIAGNOSTICS
      v_exception_detail = PG_EXCEPTION_DETAIL,
      v_exception_context = PG_EXCEPTION_CONTEXT;
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM,
        'exception_detail', NULLIF(v_exception_detail, ''),
        'exception_context', NULLIF(v_exception_context, '')
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    IF SQLSTATE = '23514'
       AND SQLERRM = 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',
        jsonb_build_object(
          'source',COALESCE(
            substring(v_exception_context FROM 'PL/pgSQL function [^\n]+'),
            'UNKNOWN_EFFECT_ATTESTATION_SOURCE'),
          'has_detail',NULLIF(v_exception_detail,'') IS NOT NULL
        )::text
        USING ERRCODE='23514';
    END IF;
    RAISE;
end;
$function$
;

-- [REPLACES] private.pay_workbench_candidate_bounded_scope_v1(p_build_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_limit integer, p_targeted_timesheet_ids uuid[], p_force_include_timesheet_ids uuid[], p_exclude_timesheet_ids uuid[], p_client_filter_single uuid)  winner piece A16
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_bounded_scope_v1(p_build_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 500, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_force_include_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_exclude_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_client_filter_single uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_cursor jsonb := COALESCE(p_cursor_json,'{}'::jsonb);
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit,500),1),500);
  v_cursor_kind text := COALESCE(NULLIF(v_cursor->>'cursor_kind',''),'PREPARE_SCOPE');
  v_family_ordinal integer := COALESCE((v_cursor->>'seed_family_ordinal')::integer,1);
  v_family text := COALESCE(NULLIF(v_cursor->>'seed_family',''),'ACTIVE_STATE');
  v_last_key text := v_cursor->>'last_source_key';
  v_selected_count integer := 0;
  v_inserted_count integer := 0;
  v_merged_count integer := 0;
  v_accumulated_count bigint := COALESCE((v_cursor->>'accumulated_row_count')::bigint,0);
  v_processed_count bigint := COALESCE((v_cursor->>'processed_source_rows')::bigint,0);
  v_rolling_digest text := COALESCE(NULLIF(v_cursor->>'rolling_digest',''),md5('BPAY_SEED_SCOPE_V1'));
  v_row_digest text;
  v_has_more boolean := true;
  v_initial_sealed boolean := false;
  v_next_cursor jsonb;
  v_row record;
  v_scope_exists boolean;
  v_last_timesheet_id uuid;
  v_next_family text;
  -- S-08 narrow preparation scope (user rulings 25 Sep 2026).  The mode and the
  -- pay window are decided once on the first PREPARE_SCOPE page and frozen in the
  -- cursor, exactly like captured_* generation fences.
  v_scope_mode text;
  v_narrow boolean := false;
  v_is_fresh_cursor boolean := false;
  v_months_back integer;
  v_weeks_ahead integer;
  v_today_uk date;
  v_eligibility_from date;
  v_eligibility_to date;
  v_week_ending_cutoff date;
  v_scope_extra jsonb := '{}'::jsonb;
  v_nrow record;
  v_narrow_reason text;
  v_narrow_scanned integer := 0;
  v_narrow_evaluations integer := 0;
  v_narrow_added integer := 0;
  v_narrow_family_more boolean := false;
  v_narrow_scan_key text;
BEGIN
  IF jsonb_typeof(v_cursor)<>'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id=p_candidate_id FOR UPDATE;
  SELECT * INTO v_build
  FROM private.banking_pay_workbench_economic_builds AS build_row
  WHERE build_row.id=p_build_id FOR UPDATE;

  IF v_registry.candidate_id IS NULL OR v_build.id IS NULL
     OR v_build.candidate_id<>p_candidate_id
     OR v_registry.current_build_id IS DISTINCT FROM p_build_id
     OR v_registry.dirty_generation<>v_build.captured_candidate_generation
     OR v_registry.current_source_change_seq<>v_build.source_change_seq
     OR v_build.status<>'COLLECTING' OR v_build.private_stage<>'PREPARE_SCOPE' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT'
      USING ERRCODE='40001',DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_BUILD_NOT_CURRENT','build_id',p_build_id,'candidate_id',p_candidate_id
      )::text;
  END IF;

  IF COALESCE(v_cursor->>'build_id',p_build_id::text)<>p_build_id::text
     OR COALESCE(v_cursor->>'candidate_id',p_candidate_id::text)<>p_candidate_id::text
     OR COALESCE((v_cursor->>'captured_candidate_generation')::bigint,v_build.captured_candidate_generation)
        <>v_build.captured_candidate_generation
     OR COALESCE((v_cursor->>'captured_source_change_seq')::bigint,v_build.source_change_seq)
        <>v_build.source_change_seq THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  IF v_cursor_kind='SEED_SCOPE_SEAL' THEN
    v_last_timesheet_id := NULLIF(v_cursor->>'last_timesheet_id','')::uuid;
    FOR v_row IN
      SELECT scope_row.timesheet_id,scope_row.candidate_id,scope_row.seed_reasons,
             scope_row.captured_dirty_generation
      FROM private.banking_pay_workbench_economic_build_scope AS scope_row
      WHERE scope_row.build_id=p_build_id
        AND (v_last_timesheet_id IS NULL OR scope_row.timesheet_id>v_last_timesheet_id)
      ORDER BY scope_row.timesheet_id
      LIMIT v_limit
      FOR UPDATE
    LOOP
      v_selected_count:=v_selected_count+1;
      v_last_timesheet_id:=v_row.timesheet_id;
      v_row_digest:=md5(jsonb_build_object(
        'candidate_id',v_row.candidate_id,'timesheet_id',v_row.timesheet_id,
        'seed_reasons',(SELECT jsonb_agg(reason ORDER BY reason)
          FROM unnest(v_row.seed_reasons) AS reason),
        'captured_dirty_generation',v_row.captured_dirty_generation
      )::text);
      v_rolling_digest:=md5(v_rolling_digest||v_row_digest);
      v_accumulated_count:=v_accumulated_count+1;
    END LOOP;

    IF v_selected_count<v_limit THEN
      UPDATE private.banking_pay_workbench_economic_builds
      SET seed_scope_count=v_accumulated_count::integer,
          seed_scope_digest=v_rolling_digest,
          seed_scope_sealed_at_utc=clock_timestamp(),
          scope_count=v_accumulated_count::integer,
          dependency_node_count=v_accumulated_count::integer,
          private_stage='DEPENDENCY_CLOSURE',
          scope_cursor_json=jsonb_build_object(
            'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'terminal',true,
            'build_id',p_build_id,'candidate_id',p_candidate_id,
            'processed_row_count',v_accumulated_count,'rolling_digest',v_rolling_digest
          ),
          closure_cursor_json=jsonb_build_object(
            'cursor_kind','DEPENDENCY_CLOSURE','cursor_version',1,
            'build_id',p_build_id,'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq,
            'frontier_timesheet_id',NULL,'dependency_family','CORRECTION_FORWARD',
            'dependency_family_ordinal',1,'last_edge_key',NULL,
            'processed_edge_count',0,'processed_emission_count',0,'page_number',1
          ),
          updated_at_utc=clock_timestamp()
      WHERE id=p_build_id AND private_stage='PREPARE_SCOPE';
      v_initial_sealed:=true;
      v_has_more:=true;
      v_next_cursor:=(SELECT closure_cursor_json
        FROM private.banking_pay_workbench_economic_builds WHERE id=p_build_id);
    ELSE
      v_next_cursor:=jsonb_build_object(
        'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
        'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,
        'page_number',COALESCE((v_cursor->>'page_number')::integer,1)+1,
        'last_timesheet_id',v_last_timesheet_id,'processed_row_count',v_accumulated_count,
        'accumulated_row_count',v_accumulated_count,'rolling_digest',v_rolling_digest,
        'previous_page_digest',md5(v_cursor::text||v_rolling_digest)
      );
      UPDATE private.banking_pay_workbench_economic_builds
      SET scope_cursor_json=v_next_cursor,updated_at_utc=clock_timestamp()
      WHERE id=p_build_id;
    END IF;

    RETURN jsonb_build_object(
      'ok',true,'build_id',p_build_id,'candidate_id',p_candidate_id,
      'cursor_kind',v_next_cursor->>'cursor_kind','cursor_version',1,
      'seed_family','COMPLETE','processed_source_count',v_selected_count,
      'new_scope_row_count',0,'merged_scope_row_count',0,
      'initial_scope_count',v_accumulated_count,'initial_scope_digest',v_rolling_digest,
      'initial_scope_sealed',v_initial_sealed,'has_more',v_has_more,
      'next_cursor_json',v_next_cursor
    );
  END IF;

  IF v_cursor_kind NOT IN ('PREPARE_SCOPE','SCOPE_SELECT') OR v_family_ordinal NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  -- S-08: LEGACY_FULL is kept only for (a) the one-time bootstrap classification
  -- read, which must see the whole legacy history once, and (b) a build whose
  -- in-flight cursor was issued before this definition was installed.  Every
  -- other build uses NARROW_S08_V1.
  v_is_fresh_cursor := v_family_ordinal=1 AND v_last_key IS NULL
    AND COALESCE((v_cursor->>'processed_source_rows')::bigint,0)=0;
  v_scope_mode := NULLIF(v_cursor->>'scope_mode','');
  IF v_scope_mode IS NULL THEN
    IF NOT v_is_fresh_cursor THEN
      v_scope_mode := 'LEGACY_FULL';
    ELSIF v_registry.initialisation_status IN ('DISCOVERING','CLASSIFYING')
       AND v_registry.bootstrap_id IS NOT NULL
       AND COALESCE((v_build.attestation_json->>'bootstrap_active_reconciliation')::boolean,false) IS NOT TRUE THEN
      v_scope_mode := 'LEGACY_FULL';
    ELSE
      v_scope_mode := 'NARROW_S08_V1';
    END IF;
  ELSIF v_scope_mode NOT IN ('LEGACY_FULL','NARROW_S08_V1') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;
  v_narrow := v_scope_mode='NARROW_S08_V1';

  IF v_narrow THEN
    SELECT session_row.week_ending_cutoff INTO v_week_ending_cutoff
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id=v_build.session_id;
    IF v_cursor ? 'eligibility_from_date' THEN
      v_eligibility_from := NULLIF(v_cursor->>'eligibility_from_date','')::date;
      v_eligibility_to := NULLIF(v_cursor->>'eligibility_to_date','')::date;
      IF v_eligibility_from IS NULL OR v_eligibility_to IS NULL
         OR NULLIF(v_cursor->>'week_ending_cutoff','')::date IS DISTINCT FROM v_week_ending_cutoff THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
      END IF;
    ELSIF v_is_fresh_cursor THEN
      -- Same window arithmetic as public.pay_preview_build_context.
      SELECT settings_row.pay_eligibility_months_back,settings_row.pay_eligibility_weeks_ahead
      INTO v_months_back,v_weeks_ahead
      FROM public.settings_defaults AS settings_row
      ORDER BY settings_row.id ASC LIMIT 1;
      v_months_back := GREATEST(0,LEAST(COALESCE(v_months_back,6),120));
      v_weeks_ahead := GREATEST(0,LEAST(COALESCE(v_weeks_ahead,2),52));
      v_today_uk := (now() AT TIME ZONE 'Europe/London')::date;
      v_eligibility_from := (v_today_uk-(v_months_back::text||' months')::interval)::date;
      v_eligibility_to := LEAST((v_today_uk+(v_weeks_ahead::text||' weeks')::interval)::date,
        v_week_ending_cutoff);
    ELSE
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    v_scope_extra := jsonb_build_object(
      'narrow_scope_contract','S08_NARROW_SCOPE_V1',
      'eligibility_from_date',v_eligibility_from,
      'eligibility_to_date',v_eligibility_to,
      'week_ending_cutoff',v_week_ending_cutoff);
  END IF;
  v_scope_extra := v_scope_extra||jsonb_build_object('scope_mode',v_scope_mode);

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_seed_page_v1(
    source_key text PRIMARY KEY,timesheet_id uuid NOT NULL,reason text NOT NULL
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_seed_page_v1;

  INSERT INTO pg_temp._bpay_wb_seed_page_v1(source_key,timesheet_id,reason)
  WITH emissions AS (
    SELECT scope_state.timesheet_id::text AS source_key,scope_state.timesheet_id,'ACTIVE_STATE'::text AS reason
    FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
    WHERE v_family_ordinal=1 AND NOT v_narrow AND scope_state.candidate_id=p_candidate_id
      AND scope_state.economic_state IN ('DIRTY','LIVE')
    UNION ALL
    SELECT source_line.timesheet_id::text||':'||source_line.id::text,source_line.timesheet_id,'CURRENT_SOURCE_OWNER'
    FROM public.banking_pay_workbench_candidate_source_lines AS source_line
    WHERE v_family_ordinal=2 AND NOT v_narrow AND source_line.candidate_id=p_candidate_id
      AND source_line.status='CURRENT' AND source_line.timesheet_id IS NOT NULL
    UNION ALL
    SELECT advance_row.linked_timesheet_id::text||':'||advance_row.id::text,
           advance_row.linked_timesheet_id,'OPEN_ADVANCE'
    FROM public.pay_advances AS advance_row
    WHERE v_family_ordinal=3 AND NOT v_narrow AND advance_row.candidate_id=p_candidate_id
      AND advance_row.status='ACTIVE' AND advance_row.linked_timesheet_id IS NOT NULL
      AND advance_row.cleared_at_utc IS NULL AND advance_row.written_off_at_utc IS NULL
    UNION ALL
    SELECT component_row.linked_timesheet_id::text||':'||component_row.id::text,
           component_row.linked_timesheet_id,'OPEN_FINANCE_COMPONENT'
    FROM public.pay_finance_case_components AS component_row
    WHERE v_family_ordinal=4 AND NOT v_narrow AND component_row.candidate_id=p_candidate_id
      AND component_row.linked_timesheet_id IS NOT NULL AND component_row.closed_at_utc IS NULL
    UNION ALL
    SELECT reservation_row.id::text||':'||COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id)::text,
           COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id),'ACTIVE_RESERVATION'
    FROM public.pay_advance_reservations AS reservation_row
    LEFT JOIN public.pay_finance_case_components AS component_row
      ON component_row.id=reservation_row.finance_component_id
    LEFT JOIN public.pay_batch_items AS item_row ON item_row.id=reservation_row.pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=COALESCE(reservation_row.pay_batch_candidate_id,item_row.pay_batch_candidate_id)
    WHERE v_family_ordinal=5 AND NOT v_narrow AND reservation_row.released_at_utc IS NULL
      AND COALESCE(component_row.candidate_id,batch_candidate.candidate_id)=p_candidate_id
      AND COALESCE(component_row.linked_timesheet_id,item_row.timesheet_id) IS NOT NULL
    UNION ALL
    SELECT override_row.timesheet_id::text||':'||override_row.id::text,
           override_row.timesheet_id,'ACTIVE_OVERRIDE'
    FROM public.timesheet_payment_overrides AS override_row
    WHERE v_family_ordinal=6 AND override_row.candidate_id=p_candidate_id
      AND override_row.timesheet_id IS NOT NULL AND override_row.cleared_at_utc IS NULL
      AND override_row.consumed_at_utc IS NULL AND override_row.consumed_by_pay_batch_id IS NULL
      AND (NOT v_narrow OR EXISTS(SELECT 1 FROM public.timesheets AS f6_ts WHERE f6_ts.timesheet_id=override_row.timesheet_id
          AND ((f6_ts.authorised_at_server IS NOT NULL AND f6_ts.revoked_at IS NULL AND f6_ts.archived_at_utc IS NULL
            AND COALESCE(CASE WHEN UPPER(COALESCE(f6_ts.sheet_scope::text,''))='DAILY' AND f6_ts.worked_start_iso IS NOT NULL THEN (f6_ts.worked_start_iso AT TIME ZONE 'Europe/London')::date ELSE NULL::date END,f6_ts.week_ending_date::date) BETWEEN v_eligibility_from AND v_eligibility_to)
          OR EXISTS(SELECT 1 FROM public.timesheet_payment_overrides AS f6_ts_adv
            WHERE f6_ts_adv.timesheet_id=f6_ts.timesheet_id AND f6_ts_adv.cleared_at_utc IS NULL
              AND f6_ts_adv.consumed_at_utc IS NULL AND f6_ts_adv.consumed_by_pay_batch_id IS NULL
              AND UPPER(COALESCE(f6_ts_adv.override_type,''))='ADVANCE_THIS_PAYMENT'))))
    UNION ALL
    SELECT adjustment_row.timesheet_id::text||':'||adjustment_row.id::text,
           adjustment_row.timesheet_id,'UNPAID_ADJUSTMENT'
    FROM public.ts_pay_adjustments AS adjustment_row
    WHERE v_family_ordinal=7 AND adjustment_row.candidate_id=p_candidate_id
      AND adjustment_row.timesheet_id IS NOT NULL AND adjustment_row.paid_at_utc IS NULL
      AND (NOT v_narrow OR EXISTS(SELECT 1 FROM public.timesheets AS f7_ts WHERE f7_ts.timesheet_id=adjustment_row.timesheet_id
          AND f7_ts.authorised_at_server IS NOT NULL AND f7_ts.revoked_at IS NULL AND f7_ts.archived_at_utc IS NULL))
    UNION ALL
    SELECT snooze_row.timesheet_id::text||':'||snooze_row.id::text,
           snooze_row.timesheet_id,'ACTIVE_SNOOZE'
    FROM public.pay_item_snoozes AS snooze_row
    WHERE v_family_ordinal=8 AND snooze_row.candidate_id=p_candidate_id
      AND snooze_row.timesheet_id IS NOT NULL AND snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
      AND (NOT v_narrow OR EXISTS(SELECT 1 FROM public.timesheets AS f8_ts WHERE f8_ts.timesheet_id=snooze_row.timesheet_id
          AND ((f8_ts.authorised_at_server IS NOT NULL AND f8_ts.revoked_at IS NULL AND f8_ts.archived_at_utc IS NULL
            AND COALESCE(CASE WHEN UPPER(COALESCE(f8_ts.sheet_scope::text,''))='DAILY' AND f8_ts.worked_start_iso IS NOT NULL THEN (f8_ts.worked_start_iso AT TIME ZONE 'Europe/London')::date ELSE NULL::date END,f8_ts.week_ending_date::date) BETWEEN v_eligibility_from AND v_eligibility_to)
          OR EXISTS(SELECT 1 FROM public.timesheet_payment_overrides AS f8_ts_adv
            WHERE f8_ts_adv.timesheet_id=f8_ts.timesheet_id AND f8_ts_adv.cleared_at_utc IS NULL
              AND f8_ts_adv.consumed_at_utc IS NULL AND f8_ts_adv.consumed_by_pay_batch_id IS NULL
              AND UPPER(COALESCE(f8_ts_adv.override_type,''))='ADVANCE_THIS_PAYMENT'))))
    UNION ALL
    SELECT target_id::text,target_id,'TARGETED_ID'
    FROM unnest(COALESCE(p_targeted_timesheet_ids,ARRAY[]::uuid[])) AS target_id
    WHERE v_family_ordinal=9 AND target_id IS NOT NULL
    UNION ALL
    SELECT force_id::text,force_id,'FORCED_ID'
    FROM unnest(COALESCE(p_force_include_timesheet_ids,ARRAY[]::uuid[])) AS force_id
    WHERE v_family_ordinal=10 AND force_id IS NOT NULL
  ), valid_emissions AS (
    SELECT DISTINCT ON (emission.source_key) emission.source_key,emission.timesheet_id,emission.reason
    FROM emissions AS emission
    JOIN public.timesheets AS timesheet_row ON timesheet_row.timesheet_id=emission.timesheet_id
    JOIN LATERAL (
      SELECT financial_row.candidate_id,financial_row.client_id
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id=emission.timesheet_id AND financial_row.is_current
      ORDER BY financial_row.id DESC LIMIT 1
    ) AS ownership_financial ON ownership_financial.candidate_id=p_candidate_id
    WHERE (p_client_filter_single IS NULL OR ownership_financial.client_id=p_client_filter_single)
      AND NOT emission.timesheet_id=ANY(COALESCE(p_exclude_timesheet_ids,ARRAY[]::uuid[]))
      AND (v_last_key IS NULL OR emission.source_key>v_last_key)
    ORDER BY emission.source_key,emission.timesheet_id
  )
  SELECT source_key,timesheet_id,reason FROM valid_emissions
  ORDER BY source_key LIMIT v_limit;

  -- S-08 family 1.  A Timesheet enters the preparation scope only when it is
  --   TOUCHED          recorded in the Workbench dirty ledger since the last build
  --                    (authorised, unauthorised or changed; bootstrap relabels excluded),
  --   PAY_NOW          authorised and inside the frozen pay window, or ADVANCE_THIS_PAYMENT,
  --   OWED_AUTHORISED  older than the pay window, still authorised, and money is genuinely
  --                    still owed (open underpayment case, or the existing outstanding owner
  --                    public._pay_outstanding_components > 0; the summary cache is not used
  --                    because authorisation does not refresh it).
  -- Untouched unauthorised, settled or merely finance-linked Timesheets stay out; their open
  -- advances, recoveries and adjustments are presented as Candidate balances (see D5).
  IF v_narrow AND v_family_ordinal=1 THEN
    v_narrow_scan_key:=v_last_key;
    FOR v_nrow IN
      SELECT scope_state.timesheet_id,scope_state.economic_state,scope_state.last_dirty_reason,
        (narrow_ts.authorised_at_server IS NOT NULL AND narrow_ts.revoked_at IS NULL AND narrow_ts.archived_at_utc IS NULL) AS is_authorised,
        COALESCE(CASE WHEN UPPER(COALESCE(narrow_ts.sheet_scope::text,''))='DAILY' AND narrow_ts.worked_start_iso IS NOT NULL THEN (narrow_ts.worked_start_iso AT TIME ZONE 'Europe/London')::date ELSE NULL::date END,narrow_ts.week_ending_date::date) AS effective_date,
        EXISTS(SELECT 1 FROM public.timesheet_payment_overrides AS narrow_advance
          WHERE narrow_advance.timesheet_id=scope_state.timesheet_id AND narrow_advance.cleared_at_utc IS NULL
            AND narrow_advance.consumed_at_utc IS NULL AND narrow_advance.consumed_by_pay_batch_id IS NULL
            AND UPPER(COALESCE(narrow_advance.override_type,''))='ADVANCE_THIS_PAYMENT') AS advance_now
      FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
      JOIN public.timesheets AS narrow_ts ON narrow_ts.timesheet_id=scope_state.timesheet_id
      JOIN LATERAL (
        SELECT financial_row.candidate_id,financial_row.client_id
        FROM public.timesheets_financials AS financial_row
        WHERE financial_row.timesheet_id=scope_state.timesheet_id AND financial_row.is_current
        ORDER BY financial_row.id DESC LIMIT 1
      ) AS narrow_owner ON narrow_owner.candidate_id=p_candidate_id
      WHERE scope_state.candidate_id=p_candidate_id
        AND scope_state.economic_state IN ('DIRTY','LIVE')
        AND (p_client_filter_single IS NULL OR narrow_owner.client_id=p_client_filter_single)
        AND NOT scope_state.timesheet_id=ANY(COALESCE(p_exclude_timesheet_ids,ARRAY[]::uuid[]))
        AND (v_last_key IS NULL OR scope_state.timesheet_id::text>v_last_key)
      ORDER BY scope_state.timesheet_id::text
    LOOP
      v_narrow_scanned:=v_narrow_scanned+1;
      v_narrow_scan_key:=v_nrow.timesheet_id::text;
      v_narrow_reason:=CASE
        WHEN v_nrow.economic_state='DIRTY'
         AND COALESCE(v_nrow.last_dirty_reason,'') NOT IN (
           'LEGACY_BOOTSTRAP_DISCOVERY','LEGACY_ACTIVE_UNIT_CLASSIFIED') THEN 'TOUCHED'
        WHEN (v_nrow.is_authorised AND v_nrow.effective_date BETWEEN v_eligibility_from AND v_eligibility_to)
          OR v_nrow.advance_now THEN 'PAY_NOW'
      END;
      IF v_narrow_reason IS NULL AND v_nrow.is_authorised AND v_nrow.effective_date<v_eligibility_from THEN
        v_narrow_evaluations:=v_narrow_evaluations+1;
        IF EXISTS(SELECT 1 FROM public.pay_advances AS owed_case
             WHERE owed_case.candidate_id=p_candidate_id
               AND owed_case.linked_timesheet_id=v_nrow.timesheet_id
               AND owed_case.case_type='UNDERPAYMENT'::public.pay_finance_case_type_enum
               AND owed_case.status='ACTIVE'::public.pay_advance_status_enum
               AND owed_case.cleared_at_utc IS NULL AND owed_case.written_off_at_utc IS NULL
               AND COALESCE(owed_case.outstanding_amount,0)>0)
           OR (SELECT ROUND(COALESCE(SUM(live_owed.outstanding_ex_vat),0),2)
               FROM public._pay_outstanding_components(ARRAY[v_nrow.timesheet_id]) AS live_owed)>0 THEN
          v_narrow_reason:='OWED_AUTHORISED';
        END IF;
      END IF;
      IF v_narrow_reason IS NOT NULL THEN
        INSERT INTO pg_temp._bpay_wb_seed_page_v1(source_key,timesheet_id,reason)
        VALUES (v_nrow.timesheet_id::text,v_nrow.timesheet_id,v_narrow_reason)
        ON CONFLICT (source_key) DO NOTHING;
        v_narrow_added:=v_narrow_added+1;
      END IF;
      EXIT WHEN v_narrow_added>=v_limit;
      IF v_narrow_evaluations>=100 OR v_narrow_scanned>=5000 THEN
        v_narrow_family_more:=true;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  FOR v_row IN SELECT * FROM pg_temp._bpay_wb_seed_page_v1 ORDER BY source_key
  LOOP
    v_selected_count:=v_selected_count+1;
    v_processed_count:=v_processed_count+1;
    v_last_key:=v_row.source_key;
    SELECT EXISTS(
      SELECT 1 FROM private.banking_pay_workbench_economic_build_scope AS scope_row
      WHERE scope_row.build_id=p_build_id AND scope_row.timesheet_id=v_row.timesheet_id
    ) INTO v_scope_exists;
    INSERT INTO private.banking_pay_workbench_economic_build_scope AS scope_row(
      build_id,timesheet_id,candidate_id,seed_reasons,dependency_reasons,
      captured_dirty_generation,required_fact_families
    ) VALUES (
      p_build_id,v_row.timesheet_id,p_candidate_id,ARRAY[v_row.reason],ARRAY[]::text[],
      v_build.captured_candidate_generation,
      ARRAY['FROZEN_SETTLED_COMPONENT','LIVE_ENTITLEMENT_INPUT','ENTITLEMENT_COMPONENT',
        'PAY_STATE_FALLBACK','PAYEE_BASELINE_INPUT','CANONICAL_INPUT']::text[]
    )
    ON CONFLICT(build_id,timesheet_id) DO UPDATE
    SET seed_reasons=(SELECT array_agg(DISTINCT reason ORDER BY reason)
      FROM unnest(scope_row.seed_reasons||EXCLUDED.seed_reasons) AS reason),
        updated_at_utc=clock_timestamp()
    WHERE scope_row.candidate_id=EXCLUDED.candidate_id
      AND scope_row.captured_dirty_generation=EXCLUDED.captured_dirty_generation;
    IF v_scope_exists THEN v_merged_count:=v_merged_count+1;
    ELSE v_inserted_count:=v_inserted_count+1; END IF;
  END LOOP;

  IF v_narrow_family_more THEN
    -- page budget reached before this family finished: resume after the last row examined
    v_last_key:=GREATEST(COALESCE(v_last_key,''),COALESCE(v_narrow_scan_key,''));
  ELSIF v_selected_count<v_limit THEN
    v_family_ordinal:=v_family_ordinal+1;
    v_last_key:=NULL;
  END IF;

  IF v_family_ordinal>10 THEN
    v_next_cursor:=jsonb_build_object(
      'cursor_kind','SEED_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
      'candidate_id',p_candidate_id,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'page_number',1,'last_timesheet_id',NULL,'processed_row_count',0,
      'accumulated_row_count',0,'rolling_digest',md5('BPAY_SEED_SCOPE_V1'),
      'previous_page_digest',NULL
    );
  ELSE
    v_next_family:=(ARRAY['ACTIVE_STATE','CURRENT_SOURCE_OWNER','OPEN_ADVANCE',
      'OPEN_FINANCE_COMPONENT','ACTIVE_RESERVATION','ACTIVE_OVERRIDE','UNPAID_ADJUSTMENT',
      'ACTIVE_SNOOZE','TARGETED_ID','FORCED_ID'])[v_family_ordinal];
    v_next_cursor:=jsonb_build_object(
      'cursor_kind','SCOPE_SELECT','cursor_version',1,'build_id',p_build_id,
      'candidate_id',p_candidate_id,'seed_family',v_next_family,
      'seed_family_ordinal',v_family_ordinal,'last_source_key',v_last_key,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'processed_source_rows',v_processed_count
    )||v_scope_extra;
  END IF;

  UPDATE private.banking_pay_workbench_economic_builds
  SET scope_cursor_json=v_next_cursor,scope_count=scope_count+v_inserted_count,
      updated_at_utc=clock_timestamp()
  WHERE id=p_build_id AND private_stage='PREPARE_SCOPE';

  RETURN jsonb_build_object(
    'ok',true,'build_id',p_build_id,'candidate_id',p_candidate_id,
    'cursor_kind',v_next_cursor->>'cursor_kind','cursor_version',1,
    'seed_family',COALESCE(v_next_cursor->>'seed_family','COMPLETE'),
    'processed_source_count',v_selected_count,'new_scope_row_count',v_inserted_count,
    'merged_scope_row_count',v_merged_count,'initial_scope_count',NULL,
    'initial_scope_digest',NULL,'initial_scope_sealed',false,'has_more',true,
    'next_cursor_json',v_next_cursor
  );
END;
$function$;

-- [REPLACES] private.pay_workbench_candidate_source_build_chunk_legacy_v1(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb, p_payload_json jsonb, p_limit integer)  winner piece A28
CREATE OR REPLACE FUNCTION private.pay_workbench_candidate_source_build_chunk_legacy_v1(p_session_id uuid, p_candidate_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_payload_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cursor jsonb:=COALESCE(p_cursor_json,'{}'::jsonb);
  v_payload jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_payload_json,'{}'::jsonb))='object'
    THEN COALESCE(p_payload_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_build_id uuid:=NULLIF(v_payload->>'economic_build_id','')::uuid;
  v_attempt_id uuid:=NULLIF(v_payload->>'attempt_id','')::uuid;
  v_attempt_nonce uuid:=NULLIF(v_payload->>'attempt_nonce','')::uuid;
  v_stage text:=upper(COALESCE(NULLIF(v_payload->>'private_stage',''),NULLIF(v_cursor->>'cursor_kind','')));
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),1),500);
  -- Fact collection is intentionally capped independently of callers.  The
  -- complete candidate remains unbounded through durable continuation pages.
  v_fact_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),1),25);
  v_result jsonb;
  v_next jsonb;
  v_unit_key text:=NULLIF(v_cursor->>'dependency_unit_key','');
  v_fact_family text:=NULLIF(v_cursor->>'fact_family','');
  v_last_source_key text:=NULLIF(v_cursor->>'last_source_key','');
  v_page_number integer:=GREATEST(COALESCE((v_cursor->>'page_number')::integer,1),1);
  v_page_count integer:=0;
  v_page_digest text;
  v_cumulative_fact_count integer:=GREATEST(COALESCE((v_cursor->>'cumulative_fact_count')::integer,0),0);
  v_next_cumulative_fact_count integer:=0;
  v_cumulative_digest text:=COALESCE(NULLIF(v_cursor->>'cumulative_digest',''),md5('BPAY_FACT_STREAM_V2'));
  v_raw_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'raw_physical_source_count')::bigint,0),0);
  v_resolved_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'resolved_physical_source_count')::bigint,0),0);
  v_failed_physical_source_count bigint:=GREATEST(COALESCE((v_cursor->>'failed_physical_source_count')::bigint,0),0);
  v_page_physical_source_count bigint:=0;
  v_page_resolved_source_count bigint:=0;
  v_page_failed_source_count bigint:=0;
  v_next_raw_physical_source_count bigint:=0;
  v_next_resolved_physical_source_count bigint:=0;
  v_next_failed_physical_source_count bigint:=0;
  v_raw_physical_amount_ex_vat numeric:=COALESCE((v_cursor->>'raw_physical_amount_ex_vat')::numeric,0);
  v_resolved_physical_amount_ex_vat numeric:=COALESCE((v_cursor->>'resolved_physical_amount_ex_vat')::numeric,0);
  v_page_physical_amount_ex_vat numeric:=0;
  v_page_resolved_amount_ex_vat numeric:=0;
  v_next_raw_physical_amount_ex_vat numeric:=0;
  v_next_resolved_physical_amount_ex_vat numeric:=0;
  v_expected_source_count integer;
  v_raw_source_has_more boolean:=false;
  v_has_more boolean:=false;
  v_is_final boolean:=false;
  v_last_page_key text;
  v_last_raw_physical_source_key text:=NULLIF(v_cursor->>'last_raw_physical_source_key','');
  v_next_last_raw_physical_source_key text;
  v_cursor_start_hash text;
  v_cursor_end_hash text;
  v_existing_page private.banking_pay_workbench_economic_build_fact_pages%ROWTYPE;
  v_previous_page private.banking_pay_workbench_economic_build_fact_pages%ROWTYPE;
  v_fact_page_timestamp timestamptz;
  v_replay_cursor jsonb;
  v_unit_ids uuid[]:=ARRAY[]::uuid[];
  v_family_ordinal integer;
  v_unit_families text[]:=ARRAY[
    'LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK',
    'ENTITLEMENT_COMPONENT','PAYEE_BASELINE_INPUT','CANONICAL_INPUT'
  ];
  v_global_families text[]:=ARRAY[
    'FINANCE_ITEM_AUTHORITY','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY',
    'PROTECTION_EVIDENCE','ALLOCATION_INPUT'
  ];
  v_scope_inserted integer:=0;
  v_derived_fact_count integer:=0;
  v_derived_settled_count integer:=0;
  v_derived_fallback_count integer:=0;
  v_live_page_ids uuid[]:=ARRAY[]::uuid[];
  v_input_phase text:=upper(COALESCE(NULLIF(v_cursor->>'input_phase',''),'PROJECTION'));
  v_input_projection_id uuid:=NULLIF(v_cursor->>'input_projection_id','')::uuid;
  v_next_projection_id uuid;
  v_projection_has_more boolean:=false;
  v_projection_phase_transition boolean:=false;
  v_projection_family_transition boolean:=false;
  v_occurrence_bundle jsonb:='{}'::jsonb;
  v_resolution_failure text;
  v_vector jsonb;
  v_envelope_version integer;
  v_envelope jsonb;
  v_envelope_evidence jsonb;
  v_vector_item record;
  v_scale_blocked boolean:=false;
  v_scale_block_reason text;
  v_sync_result jsonb;
  v_capture_timing_json jsonb:='{}'::jsonb;
  v_effect_plan jsonb:='[]'::jsonb;
  v_effect_plan_digest text:=md5('');
  v_effect_plan_count integer:=0;
  v_publish_now boolean:=false;
  v_published_count integer:=0;
  v_published_digest text;
  v_source_publication_id uuid:=NULL::uuid;
  v_existing_publication_count integer:=0;
  v_existing_publication_digest text:=NULL::text;
  v_candidate_pay_method text;
  v_actor_user_id uuid;
  v_expected_count integer;
  v_cleanup_kind text;
  v_cleanup_count integer:=0;
  v_bootstrap_stream text;
  v_bootstrap_next_stream text;
  v_bootstrap_last_key text;
  v_bootstrap_page_count integer:=0;
  v_bootstrap_registered integer:=0;
  v_bootstrap_has_more boolean:=false;
  v_bootstrap_has_dirty boolean:=false;
  v_bootstrap_classification_phase text;
  v_bootstrap_unit_key text;
  v_bootstrap_last_unit_key text;
  v_bootstrap_last_ordinal bigint:=0;
  v_bootstrap_unit_relevant boolean:=false;
  v_bootstrap_page_relevant boolean:=false;
  v_bootstrap_raw_current_count bigint:=0;
  v_bootstrap_resolved_current_count bigint:=0;
  v_bootstrap_raw_baseline_count bigint:=0;
  v_bootstrap_resolved_baseline_count bigint:=0;
  v_bootstrap_page_raw_current_count bigint:=0;
  v_bootstrap_page_resolved_current_count bigint:=0;
  v_bootstrap_page_raw_baseline_count bigint:=0;
  v_bootstrap_page_resolved_baseline_count bigint:=0;
  v_bootstrap_evidence_complete boolean:=false;
  v_bootstrap_reset_count integer:=0;
  v_bootstrap_id uuid;
  v_reservation_order_contract constant text:='RESERVATION_COMPONENT_SOURCE_KEY_C_V1';
  v_is_fresh_reservation_cursor boolean:=false;
  v_correction_scope_issue_request_id uuid;
  v_correction_scope_issue_code text;
  -- A28 reconciliation slicing
  v_slice_possible boolean:=true;
  v_slice_bound integer;
  v_slice_unit record;
  v_slice_rows integer:=0;
  v_slice_count integer:=0;
  v_slice_unit_count integer:=0;
  v_slice_max_unit integer:=0;
  v_slice_plan jsonb;
  v_slice_current jsonb;
  v_slice_after bigint;
  v_slice_through bigint;
  v_slice_final boolean;
BEGIN
  IF v_build_id IS NULL OR v_attempt_id IS NULL OR v_attempt_nonce IS NULL
     OR jsonb_typeof(v_cursor)<>'object' OR p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(p_candidate_id),24062027));
  SELECT * INTO v_registry FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE candidate_id=p_candidate_id FOR UPDATE;
  SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds
  WHERE id=v_build_id FOR UPDATE;
  SELECT * INTO v_session FROM public.banking_pay_workbench_sessions
  WHERE id=p_session_id;
  -- Candidate source work never mutates the shared session row here. Holding
  -- it FOR UPDATE made every candidate in one Workbench session execute
  -- serially and caused concurrent RPC-1 claims to time out. The immutable
  -- build freezes session_version, and terminal completion/publication owns
  -- the exclusive session lock plus the final generation/version fences.
  IF v_registry.current_build_id IS DISTINCT FROM v_build_id
     OR v_build.candidate_id IS DISTINCT FROM p_candidate_id
     OR v_build.session_id IS DISTINCT FROM p_session_id
     OR v_build.session_version IS DISTINCT FROM v_session.version
     OR v_registry.dirty_generation IS DISTINCT FROM v_build.captured_candidate_generation
     OR v_registry.current_source_change_seq IS DISTINCT FROM v_build.source_change_seq
     OR v_build.private_stage IS DISTINCT FROM v_stage THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT' USING ERRCODE='40001';
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM private.banking_pay_workbench_stage_attempts attempt
    WHERE attempt.id=v_attempt_id AND attempt.build_id=v_build_id
      AND attempt.attempt_nonce=v_attempt_nonce AND attempt.private_stage=v_stage
      AND attempt.attempt_status='STARTED' AND clock_timestamp()<attempt.lease_expires_at_utc
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001';
  END IF;

  IF v_stage='PREPARE_SCOPE' THEN
    v_result:=private.pay_workbench_candidate_bounded_scope_v1(
      v_build_id,p_candidate_id,v_cursor,LEAST(v_limit,500),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'targeted_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'force_include_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(COALESCE(v_payload->'exclude_timesheet_ids','[]'::jsonb)) value
        WHERE value ~* '^[0-9a-f-]{36}$' ORDER BY value::uuid),
      NULLIF(v_payload->>'client_filter_single','')::uuid
    );
    RETURN v_result||jsonb_build_object(
      'private_stage',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','continuation_enqueued',false,
      'next_action',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)
    );
  END IF;

  IF v_stage='DEPENDENCY_CLOSURE' THEN
    v_result:=private.pay_workbench_timesheet_dependency_closure_v2(v_build_id,v_cursor,LEAST(v_limit,25));
    RETURN v_result||jsonb_build_object(
      'private_stage',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','continuation_enqueued',false,
      'next_action',(SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)
    );
  END IF;

  IF v_stage='WORKSPACE_FACT' THEN
    -- Version 1.2.9: validate but never reconstruct a fact cursor.  The exact
    -- committed page-end JSON is the next invocation's page-start authority.
    v_cursor:=private.pay_workbench_fact_cursor_preserve_v2(v_cursor);
    IF NULLIF(v_cursor->>'build_id','')::uuid IS DISTINCT FROM v_build_id
       OR NULLIF(v_cursor->>'candidate_id','')::uuid IS DISTINCT FROM p_candidate_id
       OR COALESCE((v_cursor->>'captured_candidate_generation')::bigint,-1)
          IS DISTINCT FROM v_build.captured_candidate_generation
       OR COALESCE((v_cursor->>'captured_source_change_seq')::bigint,-1)
          IS DISTINCT FROM v_build.source_change_seq
       OR NULLIF(v_cursor->>'dependency_unit_key','') IS NULL
       OR NULLIF(v_cursor->>'fact_family','') IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    IF v_fact_family='RESERVATION_COMPONENT' THEN
      v_is_fresh_reservation_cursor:=
        v_page_number=1
        AND v_last_source_key IS NULL
        AND v_cursor->>'previous_page_digest' IS NULL
        AND v_cumulative_fact_count=0
        AND v_cumulative_digest=md5('BPAY_FACT_STREAM_V2')
        AND v_raw_physical_source_count=0
        AND v_resolved_physical_source_count=0
        AND v_failed_physical_source_count=0
        AND v_raw_physical_amount_ex_vat=0
        AND v_resolved_physical_amount_ex_vat=0
        AND v_last_raw_physical_source_key IS NULL
        AND COALESCE((v_cursor->>'terminal')::boolean,false)=false
        AND COALESCE((v_cursor->>'source_exhausted')::boolean,false)=false
        AND v_cursor->>'raw_terminal_source_key' IS NULL
        AND v_cursor->>'raw_page_evidence_digest' IS NULL
        AND NOT EXISTS(
          SELECT 1
          FROM private.banking_pay_workbench_economic_build_fact_pages page
          WHERE page.build_id=v_build_id
            AND page.dependency_unit_key=v_unit_key
            AND page.fact_family=v_fact_family
          LIMIT 1);
      IF NOT (v_cursor ? 'reservation_source_key_order_contract') THEN
        IF NOT v_is_fresh_reservation_cursor THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_RESERVATION_ORDER_CONTRACT_OBSOLETE'
            USING ERRCODE='40001';
        END IF;
        v_cursor:=v_cursor || jsonb_build_object(
          'reservation_source_key_order_contract',v_reservation_order_contract);
      ELSIF v_cursor->>'reservation_source_key_order_contract'
          <>v_reservation_order_contract THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_RESERVATION_ORDER_CONTRACT_OBSOLETE'
          USING ERRCODE='40001';
      END IF;
    END IF;
    IF v_build.dependency_closure_sealed_at_utc IS NULL OR EXISTS(
      SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=v_build_id AND closure_status<>'SEALED' LIMIT 1
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_FACTS_INCOMPLETE' USING ERRCODE='23514';
    END IF;

    -- A build that crossed an older bootstrap reset implementation can reach
    -- a fresh page-one cursor while its earlier bootstrap fact ledger is still
    -- attached.  Do not weaken the page-chain invariant or repair rows out of
    -- band.  Complete this exact material attempt by returning to the same
    -- bounded page -> fact -> scope reset owner used by current bootstrap
    -- classification.  The ordinary RPC-2 completion path then delivers the
    -- reset continuation atomically.
    IF v_page_number=1
       AND v_cumulative_fact_count=0
       AND v_cursor->>'previous_page_digest' IS NULL
       AND v_registry.initialisation_status='CLASSIFYING'
       AND v_registry.bootstrap_id IS NOT NULL
       AND EXISTS(
         SELECT 1
         FROM private.banking_pay_workbench_economic_build_fact_pages page
         WHERE page.build_id=v_build_id
           AND page.dependency_unit_key=v_unit_key
           AND page.fact_family=v_fact_family
         LIMIT 1
       ) THEN
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_registry.bootstrap_id,'bootstrap_stream','RESET_FACT_PAGES',
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,
        'recovery_reason','STALE_BOOTSTRAP_FACT_AUTHORITY');
      UPDATE private.banking_pay_workbench_economic_builds
      SET private_stage='BOOTSTRAP_DISCOVERY',updated_at_utc=clock_timestamp()
      WHERE id=v_build_id;
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream='RESET_FACT_PAGES',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','RESETTING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','classification_phase','RESET_FACT_PAGES',
        'recovery_reason','STALE_BOOTSTRAP_FACT_AUTHORITY');
    END IF;

    IF v_unit_key IS NULL THEN
      IF NOT EXISTS(SELECT 1
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key='GLOBAL'
          AND page.fact_family='FINANCE_ITEM_AUTHORITY'
          AND page.status='COMPLETED' AND page.is_family_final LIMIT 1) THEN
        v_unit_key:='GLOBAL';
        v_fact_family:='FINANCE_ITEM_AUTHORITY';
      ELSE
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id
          AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN v_unit_key:='GLOBAL'; END IF;
      END IF;
    END IF;
    IF v_fact_family IS NULL THEN
      v_fact_family:=CASE WHEN v_unit_key='GLOBAL' THEN v_global_families[1] ELSE v_unit_families[1] END;
    END IF;
    IF v_unit_key='GLOBAL' THEN
      v_family_ordinal:=array_position(v_global_families,v_fact_family);
    ELSE
      v_family_ordinal:=array_position(v_unit_families,v_fact_family);
      SELECT array_agg(timesheet_id ORDER BY stable_ordinal) INTO v_unit_ids
      FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key;
    END IF;
    IF v_family_ordinal IS NULL THEN RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023'; END IF;
    IF (v_unit_key='GLOBAL' AND v_input_phase IS DISTINCT FROM 'PHYSICAL_SOURCE')
       OR (v_unit_key<>'GLOBAL' AND v_fact_family='LIVE_ENTITLEMENT_INPUT'
         AND v_input_phase NOT IN ('PROJECTION','COMPONENTS'))
       OR (v_unit_key<>'GLOBAL' AND v_fact_family<>'LIVE_ENTITLEMENT_INPUT'
         AND v_input_phase IS DISTINCT FROM 'COMPONENTS') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    IF v_fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
       OR (v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='COMPONENTS') THEN
      IF v_input_phase<>'COMPONENTS' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
      END IF;
      IF v_input_projection_id IS NULL THEN
        SELECT projection.timesheet_id INTO v_input_projection_id
        FROM private.banking_pay_workbench_economic_build_facts projection
        WHERE projection.build_id=v_build_id
          AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND projection.dependency_unit_key=v_unit_key
          AND projection.source_relation='UNIT_PROJECTION'
        ORDER BY projection.timesheet_id,projection.natural_key LIMIT 1;
      END IF;
      IF v_input_projection_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_UNIT_PROJECTION_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    END IF;
    CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_fact_page_v1(
      source_key text PRIMARY KEY,natural_key text NOT NULL,timesheet_id uuid NULL,
      subject_timesheet_ids uuid[] NOT NULL,source_relation text NOT NULL,source_id uuid NULL,
      economic_key_type text NULL,economic_key_value text NULL,
      amount_ex_vat numeric NULL,amount_inc_vat numeric NULL,
      truth_ex_vat numeric NULL,truth_inc_vat numeric NULL,
      baseline_ex_vat numeric NULL,baseline_inc_vat numeric NULL,
      reserved_source_amount numeric NULL,finance_case_id uuid NULL,
      finance_component_id uuid NULL,reservation_id uuid NULL,
      source_payload_json jsonb NOT NULL,financial_digest text NOT NULL
    ) ON COMMIT DROP;
    TRUNCATE pg_temp._bpay_wb_fact_page_v1;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
      v_occurrence_bundle:=private.pay_workbench_finance_item_authority_page_bundle_v1(
        v_build_id,
        CASE WHEN COALESCE(v_last_source_key,'') ~
          '^05:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN split_part(v_last_source_key,':',2)::uuid END,
        CASE WHEN COALESCE(v_last_source_key,'') ~
          '^05:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN split_part(v_last_source_key,':',3)::uuid END,
        v_fact_limit);
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT authority.source_key,md5('FINANCE_ITEM_AUTHORITY:'||authority.source_key),
        authority.resolved_timesheet_id,
        CASE WHEN authority.resolved_timesheet_id IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[authority.resolved_timesheet_id] END,
        'pay_batch_items',authority.pay_batch_item_id,
        authority.economic_key_type,authority.economic_key_value,
        authority.source_amount_ex_vat,authority.source_amount_inc_vat,
        NULL,NULL,NULL,NULL,NULL,
        authority.resolved_finance_case_id,authority.finance_component_id,NULL,
        authority.source_payload_json||jsonb_build_object(
          'authoritative_in_scope',authority.is_authoritative,
          'resolution_failure',authority.resolution_failure),
        authority.financial_digest
      FROM jsonb_to_recordset(COALESCE(v_occurrence_bundle->'rows','[]'::jsonb)) authority(
        source_key text,pay_batch_candidate_id uuid,pay_batch_item_id uuid,
        resolved_timesheet_id uuid,resolved_candidate_id uuid,resolved_finance_case_id uuid,
        finance_component_id uuid,economic_key_type text,economic_key_value text,
        source_amount_ex_vat numeric,source_amount_inc_vat numeric,is_authoritative boolean,
        source_payload_json jsonb,financial_digest text,resolution_failure text);
    ELSIF v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='PROJECTION' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT projection.source_key,md5('UNIT_PROJECTION:'||projection.source_key),
        COALESCE(projection.projected_timesheet_id,projection.family_timesheet_id),
        ARRAY[projection.family_timesheet_id],
        'UNIT_PROJECTION',projection.family_timesheet_id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
        NULL,NULL,NULL,NULL,
        jsonb_build_object('role','UNIT_PROJECTION','scope_family_key',projection.scope_family_key,
          'family_timesheet_id',projection.family_timesheet_id,
          'canonical_timesheet_id',projection.canonical_timesheet_id,
          'projected_timesheet_id',projection.projected_timesheet_id,
          'projection_resolution_status',projection.projection_resolution_status,
          'stable_ordinal',projection.stable_ordinal,
          'resolution_failure',CASE WHEN projection.projected_timesheet_id IS NULL
            THEN 'UNIT_PROJECTION_MISSING_CURRENT' END),
        md5(jsonb_build_object('family_timesheet_id',projection.family_timesheet_id,
          'scope_family_key',projection.scope_family_key,
          'canonical_timesheet_id',projection.canonical_timesheet_id,
          'projected_timesheet_id',projection.projected_timesheet_id,
          'stable_ordinal',projection.stable_ordinal)::text)
      FROM (
        WITH scope_page AS MATERIALIZED (
          SELECT scope_row.timesheet_id,scope_row.stable_ordinal
          FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=v_build_id
            AND scope_row.dependency_unit_key=v_unit_key
            AND (v_last_source_key IS NULL OR
              '00:'||LPAD(scope_row.stable_ordinal::text,20,'0')||':'||scope_row.timesheet_id::text>v_last_source_key)
          ORDER BY scope_row.stable_ordinal,scope_row.timesheet_id
          LIMIT v_fact_limit+1
        )
        SELECT scope_page.stable_ordinal,scope_page.timesheet_id AS family_timesheet_id,
          COALESCE(NULLIF(BTRIM(member.booking_id),''),scope_page.timesheet_id::text) AS scope_family_key,
          COALESCE(canonical.timesheet_id,fallback_member.timesheet_id) AS canonical_timesheet_id,
          COALESCE(canonical.timesheet_id,fallback_member.timesheet_id) AS projected_timesheet_id,
          CASE WHEN canonical.timesheet_id IS NOT NULL THEN 'CURRENT_FAMILY_MEMBER'
            WHEN fallback_member.timesheet_id IS NOT NULL THEN 'SEALED_FAMILY_FALLBACK_NO_CURRENT'
            ELSE 'UNRESOLVED' END AS projection_resolution_status,
          '00:'||LPAD(scope_page.stable_ordinal::text,20,'0')||':'||scope_page.timesheet_id::text AS source_key
        FROM scope_page
        JOIN public.timesheets member ON member.timesheet_id=scope_page.timesheet_id
        LEFT JOIN LATERAL (
          SELECT current_member.timesheet_id
          FROM public.timesheets current_member
          JOIN private.banking_pay_workbench_economic_build_scope current_scope
            ON current_scope.build_id=v_build_id
           AND current_scope.dependency_unit_key=v_unit_key
           AND current_scope.timesheet_id=current_member.timesheet_id
          -- Preserve the established rotation authority exactly: canonical
          -- identity is the highest-ranked is_current family member. Revocation
          -- and archival remain captured facts; they do not erase identity.
          WHERE current_member.is_current IS TRUE
            AND (CASE WHEN NULLIF(BTRIM(member.booking_id),'') IS NULL
                  THEN current_member.timesheet_id=member.timesheet_id
                  ELSE current_member.booking_id=member.booking_id END)
          ORDER BY current_member.version DESC NULLS LAST,
            current_member.updated_at DESC NULLS LAST,current_member.created_at DESC NULLS LAST,
            current_member.timesheet_id
          LIMIT 1
        ) canonical ON true
        LEFT JOIN LATERAL (
          -- Some bounded legacy families legitimately have no row still marked
          -- current. Keep one page-independent owner from the sealed unit rather
          -- than losing the physical family or projecting each page differently.
          SELECT fallback_row.timesheet_id
          FROM private.banking_pay_workbench_economic_build_scope fallback_scope
          JOIN public.timesheets fallback_row
            ON fallback_row.timesheet_id=fallback_scope.timesheet_id
          WHERE canonical.timesheet_id IS NULL
            AND fallback_scope.build_id=v_build_id
            AND fallback_scope.dependency_unit_key=v_unit_key
            AND (CASE WHEN NULLIF(BTRIM(member.booking_id),'') IS NULL
                  THEN fallback_row.timesheet_id=member.timesheet_id
                  ELSE fallback_row.booking_id=member.booking_id END)
          ORDER BY fallback_scope.stable_ordinal,fallback_row.timesheet_id
          LIMIT 1
        ) fallback_member ON true
        ORDER BY scope_page.stable_ordinal,scope_page.timesheet_id
      ) projection;
    ELSIF v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK') THEN
      v_occurrence_bundle:=private.pay_workbench_unit_economic_occurrence_bundle_v1(
        v_build_id,v_unit_key,v_fact_family,v_input_projection_id,
        v_last_source_key,v_fact_limit);
      IF jsonb_typeof(v_occurrence_bundle)<>'object'
         OR COALESCE((v_occurrence_bundle->>'bundle_version')::integer,0)<>1
         OR jsonb_typeof(v_occurrence_bundle->'rows')<>'array' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_EVIDENCE_INVALID'
          USING ERRCODE='23514';
      END IF;
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT occurrence.source_key,occurrence.natural_key,occurrence.timesheet_id,
        occurrence.subject_timesheet_ids,occurrence.source_relation,occurrence.source_id,
        occurrence.economic_key_type,occurrence.economic_key_value,
        occurrence.amount_ex_vat,occurrence.amount_inc_vat,
        occurrence.truth_ex_vat,occurrence.truth_inc_vat,
        occurrence.baseline_ex_vat,occurrence.baseline_inc_vat,
        NULL,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'finance_case_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'finance_case_id')::uuid END,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'finance_component_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'finance_component_id')::uuid END,
        CASE WHEN COALESCE(occurrence.source_payload_json->>'reservation_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (occurrence.source_payload_json->>'reservation_id')::uuid END,
        occurrence.source_payload_json,occurrence.financial_digest
      FROM jsonb_to_recordset(v_occurrence_bundle->'rows') occurrence(
        source_key text,natural_key text,timesheet_id uuid,subject_timesheet_ids uuid[],
        source_relation text,source_id uuid,economic_key_type text,economic_key_value text,
        amount_ex_vat numeric,amount_inc_vat numeric,truth_ex_vat numeric,truth_inc_vat numeric,
        baseline_ex_vat numeric,baseline_inc_vat numeric,source_payload_json jsonb,
        financial_digest text,resolution_failure text
      );
    ELSIF v_fact_family IN ('ENTITLEMENT_COMPONENT','PAYEE_BASELINE_INPUT','CANONICAL_INPUT') THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT source.source_key,md5(v_fact_family||':'||source.source_key),source.timesheet_id,
        ARRAY[source.timesheet_id],'economic_build_facts',source.source_id,
        source.key_type,source.key_value,
        CASE WHEN v_fact_family='CANONICAL_INPUT' THEN source.truth_ex_vat END,
        CASE WHEN v_fact_family='CANONICAL_INPUT' THEN source.truth_inc_vat END,
        source.truth_ex_vat,source.truth_inc_vat,source.baseline_ex_vat,source.baseline_inc_vat,
        NULL,NULL,NULL,NULL,
        jsonb_build_object('fact_role',v_fact_family,'source_fact_family',source.source_family,
          'source_natural_key',source.source_natural_key),
        md5(jsonb_build_object('timesheet_id',source.timesheet_id,'source_family',source.source_family,
          'source_natural_key',source.source_natural_key,'key_type',source.key_type,
          'key_value',source.key_value,'truth_ex_vat',source.truth_ex_vat,
          'truth_inc_vat',source.truth_inc_vat,'baseline_ex_vat',source.baseline_ex_vat,
          'baseline_inc_vat',source.baseline_inc_vat)::text)
      FROM (
        SELECT 'T:'||fact.natural_key AS source_key,fact.timesheet_id,fact.source_id,
          fact.economic_key_type AS key_type,fact.economic_key_value AS key_value,
          COALESCE(fact.truth_ex_vat,0) AS truth_ex_vat,
          COALESCE(fact.truth_inc_vat,fact.truth_ex_vat,0) AS truth_inc_vat,
          0::numeric AS baseline_ex_vat,0::numeric AS baseline_inc_vat,
          fact.fact_family AS source_family,fact.natural_key AS source_natural_key
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id AND fact.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND fact.dependency_unit_key=v_unit_key AND fact.source_relation<>'UNIT_PROJECTION'
          AND fact.economic_key_type IS NOT NULL
          AND COALESCE(fact.source_payload_json->>'evidence_only','false')<>'true'
        UNION ALL
        SELECT 'B:'||fact.fact_family||':'||fact.natural_key,fact.timesheet_id,fact.source_id,
          fact.economic_key_type,fact.economic_key_value,0::numeric,0::numeric,
          COALESCE(fact.amount_ex_vat,0),COALESCE(fact.amount_inc_vat,fact.amount_ex_vat,0),
          fact.fact_family,fact.natural_key
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id
          AND fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND fact.dependency_unit_key=v_unit_key AND fact.economic_key_type IS NOT NULL
          AND COALESCE(fact.source_payload_json->>'evidence_only','false')<>'true'
          AND (fact.fact_family<>'PAY_STATE_FALLBACK' OR NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_facts active
            WHERE active.build_id=v_build_id AND active.fact_family='FROZEN_SETTLED_COMPONENT'
              AND active.dependency_unit_key=v_unit_key AND active.timesheet_id=fact.timesheet_id))
      ) source
      WHERE v_last_source_key IS NULL OR source.source_key>v_last_source_key
      ORDER BY source.source_key LIMIT v_fact_limit+1;
    ELSIF v_fact_family='RESERVATION_COMPONENT' THEN
      -- One server-owned projection resolves every financially open correction
      -- request for this candidate. Durable request-candidate membership is the
      -- primary frozen authority; work items, when present, must agree exactly.
      -- Only requests with no durable membership may use the already-valid
      -- legacy envelope/helper path. BLOCKED remains financially open.
      SELECT correction_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM public.pay_payment_correction_requests AS correction_request
      WHERE correction_request.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
        )
        AND correction_request.correction_kind IN (
          'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
        )
        AND NULLIF(BTRIM(COALESCE(
              correction_request.plan_json->>'candidate_scope_contract_version',''
            )), '') IS NOT NULL
        AND correction_request.plan_json->>'candidate_scope_contract_version' NOT IN ('1','2')
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS request_candidate
          WHERE request_candidate.pay_batch_id=correction_request.pay_batch_id
            AND request_candidate.candidate_id=p_candidate_id
        )
      ORDER BY correction_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      v_correction_scope_issue_request_id:=NULL::uuid;
      v_correction_scope_issue_code:=NULL::text;

      SELECT correction_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM public.pay_payment_correction_requests AS correction_request
      JOIN public.pay_payment_correction_request_candidates AS request_member
        ON request_member.correction_request_id=correction_request.id
      JOIN public.pay_batch_candidates AS request_candidate
        ON request_candidate.id=request_member.pay_batch_candidate_id
       AND request_candidate.pay_batch_id=correction_request.pay_batch_id
       AND request_candidate.candidate_id=p_candidate_id
      WHERE correction_request.status IN (
          'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
        )
        AND correction_request.correction_kind IN (
          'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
        )
        AND (
          request_member.pay_batch_item_ids IS NULL
          OR cardinality(request_member.pay_batch_item_ids)<>request_member.active_item_count
          OR EXISTS (
            SELECT 1
            FROM unnest(request_member.pay_batch_item_ids) AS frozen_item(pay_batch_item_id)
            LEFT JOIN public.pay_batch_items AS item_row
              ON item_row.id=frozen_item.pay_batch_item_id
             AND item_row.pay_batch_candidate_id=request_member.pay_batch_candidate_id
            WHERE item_row.id IS NULL
          )
          OR (
            EXISTS (
              SELECT 1
              FROM public.pay_payment_correction_work_items AS any_work
              WHERE any_work.correction_request_id=correction_request.id
            )
            AND NOT EXISTS (
              SELECT 1
              FROM public.pay_payment_correction_work_items AS matching_work
              WHERE matching_work.correction_request_id=correction_request.id
                AND matching_work.pay_batch_candidate_id=request_member.pay_batch_candidate_id
            )
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_work_items AS work_item
            WHERE work_item.correction_request_id=correction_request.id
              AND work_item.pay_batch_candidate_id=request_member.pay_batch_candidate_id
              AND (
                work_item.pay_batch_id IS DISTINCT FROM correction_request.pay_batch_id
                OR work_item.candidate_id IS DISTINCT FROM p_candidate_id
                OR work_item.selection_hash IS DISTINCT FROM request_member.candidate_scope_hash
                OR work_item.selection_json->>'expected_item_count'
                     IS DISTINCT FROM request_member.active_item_count::text
                OR work_item.selection_json->'expected_pay_batch_item_ids'
                     IS DISTINCT FROM to_jsonb(request_member.pay_batch_item_ids)
              )
          )
        )
      ORDER BY correction_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      v_correction_scope_issue_request_id:=NULL::uuid;
      v_correction_scope_issue_code:=NULL::text;

      -- A no-membership request may use only a helper-compatible envelope or
      -- the helper's existing narrow whole-Draft compatibility contract.
      SELECT fallback_request.id,
             'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISSING'
      INTO v_correction_scope_issue_request_id, v_correction_scope_issue_code
      FROM (
        SELECT correction_request.*,
          CASE
            WHEN jsonb_typeof(correction_request.plan_json->'selected_pay_batch_item_ids')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json->'selected_pay_batch_item_ids',
                  'expected_pay_batch_item_ids',correction_request.plan_json->'selected_pay_batch_item_ids')
            WHEN jsonb_typeof(correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',correction_request.plan_json#>'{selection,selected_pay_batch_item_ids}')
            WHEN jsonb_typeof(correction_request.plan_json#>'{selection,pay_batch_item_ids}')='array'
              THEN COALESCE(correction_request.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',correction_request.plan_json#>'{selection,pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',correction_request.plan_json#>'{selection,pay_batch_item_ids}')
            ELSE COALESCE(correction_request.selection_json,'{}'::jsonb)
          END AS resolved_selection_json
        FROM public.pay_payment_correction_requests AS correction_request
        WHERE correction_request.status IN (
            'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
          )
          AND correction_request.correction_kind IN (
            'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
          )
          AND NOT EXISTS (
            SELECT 1 FROM public.pay_payment_correction_request_candidates AS any_member
            WHERE any_member.correction_request_id=correction_request.id
          )
          AND EXISTS (
            SELECT 1 FROM public.pay_batch_candidates AS request_candidate
            WHERE request_candidate.pay_batch_id=correction_request.pay_batch_id
              AND request_candidate.candidate_id=p_candidate_id
          )
      ) AS fallback_request
      WHERE NOT (
        upper(NULLIF(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'scope_type','')),''))
          IN ('BATCH','CANDIDATES','TRANSFER','UMBRELLA_PAYMENT_GROUP')
        OR (
          upper(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'requested_action','')))='DRAFT_CANCEL'
          AND upper(BTRIM(COALESCE(fallback_request.resolved_selection_json->>'mode','')))='ALL_MATCHING'
          AND COALESCE(fallback_request.resolved_selection_json->>'source_context','')='pay_batch_cancel'
          AND COALESCE(fallback_request.resolved_selection_json->'filter_json','{}'::jsonb)='{}'::jsonb
          AND COALESCE(fallback_request.resolved_selection_json->'exclusions','[]'::jsonb)='[]'::jsonb
        )
      )
      ORDER BY fallback_request.id::text
      LIMIT 1;

      IF v_correction_scope_issue_request_id IS NOT NULL THEN
        RAISE EXCEPTION '%', v_correction_scope_issue_code
          USING ERRCODE='P0001', DETAIL=jsonb_build_object(
            'code',v_correction_scope_issue_code,
            'correction_request_id',v_correction_scope_issue_request_id,
            'candidate_id',p_candidate_id
          )::text;
      END IF;

      DROP TABLE IF EXISTS pg_temp._bpay_wb_open_correction_scope_v1;
      CREATE TEMP TABLE _bpay_wb_open_correction_scope_v1 ON COMMIT DROP AS
      WITH open_requests AS MATERIALIZED (
        SELECT correction_request.*
        FROM public.pay_payment_correction_requests AS correction_request
        WHERE correction_request.status IN (
            'REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'
          )
          AND correction_request.correction_kind IN (
            'PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'
          )
      ), membership_scope AS MATERIALIZED (
        SELECT request_row.id AS correction_request_id,
               frozen_item.pay_batch_item_id
        FROM open_requests AS request_row
        JOIN public.pay_payment_correction_request_candidates AS request_member
          ON request_member.correction_request_id=request_row.id
        JOIN public.pay_batch_candidates AS request_candidate
          ON request_candidate.id=request_member.pay_batch_candidate_id
         AND request_candidate.pay_batch_id=request_row.pay_batch_id
         AND request_candidate.candidate_id=p_candidate_id
        CROSS JOIN LATERAL unnest(request_member.pay_batch_item_ids)
          AS frozen_item(pay_batch_item_id)
      ), fallback_requests AS MATERIALIZED (
        SELECT request_row.*,
          CASE
            WHEN jsonb_typeof(request_row.plan_json->'selected_pay_batch_item_ids')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json->'selected_pay_batch_item_ids',
                  'expected_pay_batch_item_ids',request_row.plan_json->'selected_pay_batch_item_ids')
            WHEN jsonb_typeof(request_row.plan_json#>'{selection,selected_pay_batch_item_ids}')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json#>'{selection,selected_pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',request_row.plan_json#>'{selection,selected_pay_batch_item_ids}')
            WHEN jsonb_typeof(request_row.plan_json#>'{selection,pay_batch_item_ids}')='array'
              THEN COALESCE(request_row.selection_json,'{}'::jsonb)
                ||jsonb_build_object(
                  'pay_batch_item_ids',request_row.plan_json#>'{selection,pay_batch_item_ids}',
                  'expected_pay_batch_item_ids',request_row.plan_json#>'{selection,pay_batch_item_ids}')
            ELSE COALESCE(request_row.selection_json,'{}'::jsonb)
          END AS resolved_selection_json
        FROM open_requests AS request_row
        WHERE NOT EXISTS (
          SELECT 1 FROM public.pay_payment_correction_request_candidates AS any_member
          WHERE any_member.correction_request_id=request_row.id
        )
      ), fallback_scope AS MATERIALIZED (
        SELECT fallback_request.id AS correction_request_id,
               selected_item.pay_batch_item_id
        FROM fallback_requests AS fallback_request
        JOIN LATERAL public._pay_payment_correction_selected_items(
          fallback_request.pay_batch_id,
          fallback_request.resolved_selection_json,
          false
        ) AS selected_item ON selected_item.pay_batch_id=fallback_request.pay_batch_id
        WHERE selected_item.candidate_id=p_candidate_id
      )
      SELECT DISTINCT resolved_scope.correction_request_id,
             resolved_scope.pay_batch_item_id
      FROM (
        SELECT * FROM membership_scope
        UNION ALL
        SELECT * FROM fallback_scope
      ) AS resolved_scope;

      CREATE INDEX ON pg_temp._bpay_wb_open_correction_scope_v1(pay_batch_item_id);
      CREATE INDEX ON pg_temp._bpay_wb_open_correction_scope_v1(correction_request_id,pay_batch_item_id);

      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT reservation.id::text,md5('RESERVATION:'||reservation.id::text),
        authority.resolved_timesheet_id,authority.owner_ids,'pay_advance_reservations',reservation.id,
        authority.resolved_component_key_type,authority.resolved_component_key_value,
        NULL,NULL,NULL,NULL,NULL,NULL,COALESCE(reservation.reserved_source_amount,reservation.reserved_amount),
        authority.resolved_finance_case_id,authority.resolved_finance_component_id,
        reservation.id,to_jsonb(reservation)||jsonb_build_object('resolution_failure',CASE
          WHEN authority.resolution_failure IS NOT NULL THEN authority.resolution_failure
          WHEN cardinality(authority.component_key_pairs)<>1 THEN 'RESERVATION_ECONOMIC_KEY_CONFLICT'
          WHEN authority.resolved_component_key_type NOT IN
            ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
            OR NULLIF(BTRIM(authority.resolved_component_key_value),'') IS NULL
            THEN 'RESERVATION_ECONOMIC_KEY_INVALID'
          WHEN authority.resolved_component_key_type='TS_DAY' AND NOT (
            authority.resolved_component_key_value ~ '^\d{4}-\d{2}-\d{2}$'
            AND pg_input_is_valid(authority.resolved_component_key_value,'date')
            AND CASE WHEN pg_input_is_valid(authority.resolved_component_key_value,'date')
              THEN (authority.resolved_component_key_value::date)::text=
                authority.resolved_component_key_value ELSE false END)
            THEN 'RESERVATION_TS_DAY_INVALID'
          END,'authority_evidence',authority.evidence_json),
        md5(to_jsonb(reservation)::text)
      FROM public.pay_advance_reservations reservation
      LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=reservation.finance_component_id
      LEFT JOIN public.pay_advances finance_case
        ON finance_case.id=COALESCE(reservation.finance_case_id,component.finance_case_id)
      LEFT JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=reservation.pay_batch_candidate_id
      LEFT JOIN public.pay_batch_candidates item_batch_candidate ON item_batch_candidate.id=item.pay_batch_candidate_id
      CROSS JOIN LATERAL (
        SELECT resolved.owner_ids,resolved.candidate_ids,resolved.finance_case_ids,
          resolved.resolved_timesheet_id,resolved.resolved_finance_case_id,
          resolved.resolved_finance_component_id,resolved.resolved_component_key_type,
          resolved.resolved_component_key_value,resolved.resolution_failure,
          resolved.evidence_json,resolved.component_key_pairs
        FROM private.pay_workbench_financial_source_authority_v3(
          p_candidate_id,
          ARRAY(SELECT DISTINCT owner_id FROM (VALUES
            (item.timesheet_id),(component.linked_timesheet_id),(finance_case.linked_timesheet_id)
          ) owner(owner_id) WHERE owner_id IS NOT NULL ORDER BY owner_id),
          ARRAY(SELECT DISTINCT candidate_id FROM (VALUES
            (batch_candidate.candidate_id),(item_batch_candidate.candidate_id),
            (component.candidate_id),(finance_case.candidate_id)
          ) owner_candidate(candidate_id) WHERE candidate_id IS NOT NULL ORDER BY candidate_id),
          ARRAY(SELECT DISTINCT finance_case_id FROM (VALUES
            (reservation.finance_case_id),(item.finance_case_id),(component.finance_case_id)
          ) owner_case(finance_case_id) WHERE finance_case_id IS NOT NULL ORDER BY finance_case_id),
          ARRAY(SELECT DISTINCT finance_component_id FROM (VALUES
            (reservation.finance_component_id),(item.finance_component_id),(component.id)
          ) owner_component(finance_component_id)
            WHERE finance_component_id IS NOT NULL ORDER BY finance_component_id),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION_FROZEN_COLUMNS',
              'key_type',reservation.frozen_component_key_type,
              'key_value',reservation.frozen_component_key_value),
            jsonb_build_object('source','PAY_BATCH_ITEM_FROZEN_COLUMNS',
              'key_type',item.frozen_component_key_type,
              'key_value',item.frozen_component_key_value),
            jsonb_build_object('source','FINANCE_COMPONENT',
              'key_type',component.component_key_type,
              'key_value',component.component_key_value)),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION',
              'document',COALESCE(reservation.frozen_source_basis_json,'{}'::jsonb)),
            jsonb_build_object('source','PAY_BATCH_ITEM',
              'document',COALESCE(item.frozen_source_basis_json,'{}'::jsonb))),
          jsonb_build_array(
            jsonb_build_object('source','RESERVATION',
              'document',COALESCE(reservation.frozen_component_snapshot_json,'{}'::jsonb)),
            jsonb_build_object('source','PAY_BATCH_ITEM',
              'document',COALESCE(item.frozen_component_snapshot_json,'{}'::jsonb))),
          'RESERVATION'
        ) resolved
      ) authority
      WHERE (p_candidate_id=ANY(authority.candidate_ids)
          OR authority.owner_ids && ARRAY(
            SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope
            WHERE build_id=v_build_id))
        AND upper(btrim(COALESCE(reservation.status,''))) IN ('RESERVED','COMMITTED')
        AND reservation.released_at_utc IS NULL
        AND (item.id IS NULL OR COALESCE(item.is_voided,false) IS NOT TRUE)
        AND (authority.resolution_failure IS NOT NULL OR authority.owner_ids && ARRAY(
          SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope WHERE build_id=v_build_id))
        AND (v_last_source_key IS NULL OR reservation.id::text COLLATE "C"
          >v_last_source_key COLLATE "C")
      ORDER BY reservation.id::text COLLATE "C" LIMIT v_fact_limit+1;

      -- The normal pre-Draft preview treats active, non-settled pay-batch items as
      -- reservations even where no pay_advance_reservations row exists.  Seal
      -- that same authority here so reconciliation never has to rediscover it
      -- from later live state.  Existing directly-linked advance reservations
      -- remain the preferred owner and exclude the corresponding item below.
      WITH active_item_candidates AS MATERIALIZED (
        SELECT DISTINCT
          item.id AS pay_batch_item_id,
          batch_candidate.pay_batch_id,
          item.pay_batch_candidate_id,
          item.timesheet_id AS source_timesheet_id,
          item.item_type,
          item.segment_key,
          item.source_ref,
          UPPER(BTRIM(item.pay_channel)) AS pay_channel,
          item.reservation_id,
          item.finance_case_id,
          item.finance_component_id,
          item.frozen_component_key_type,
          item.frozen_component_key_value,
          COALESCE(item.frozen_source_basis_json,'{}'::jsonb) AS frozen_source_basis_json,
          COALESCE(item.frozen_component_snapshot_json,'{}'::jsonb)
            AS frozen_component_snapshot_json,
          COALESCE(item.frozen_resolution_payload_json,'{}'::jsonb)
            AS frozen_resolution_payload_json,
          COALESCE(item.frozen_resolution_result_json,'{}'::jsonb)
            AS frozen_resolution_result_json,
          ROUND(public._pay_batch_item_source_reservation_amount_ex_vat(item.id),2)
            AS reserved_source_amount,
          batch_row.status AS batch_status,
          batch_candidate.settlement_status AS candidate_settlement_status,
          batch_candidate.settled_at_utc AS candidate_settled_at_utc,
          transfer.status AS transfer_status,
          transfer.completed_at_utc AS transfer_completed_at_utc
        FROM public.pay_batch_items item
        JOIN public.pay_batch_candidates batch_candidate
          ON batch_candidate.id=item.pay_batch_candidate_id
        JOIN public.pay_batches batch_row ON batch_row.id=batch_candidate.pay_batch_id
        LEFT JOIN public.pay_bank_transfers transfer ON transfer.id=item.pay_bank_transfer_id
        WHERE batch_candidate.candidate_id=p_candidate_id
          AND item.timesheet_id IS NOT NULL
          AND UPPER(BTRIM(COALESCE(item.pay_channel,''))) IN ('PAYE','UMBRELLA')
          AND item.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
          AND public._pay_batch_item_source_reservation_amount_ex_vat(item.id) IS NOT NULL
          AND COALESCE(item.is_voided,false) IS NOT TRUE
          AND EXISTS (
            SELECT 1
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id
              AND scope_row.candidate_id=p_candidate_id
              AND (scope_row.timesheet_id=item.timesheet_id
                OR scope_row.root_timesheet_id=item.timesheet_id)
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_items applied_correction
            WHERE applied_correction.pay_batch_item_id=item.id
              AND applied_correction.status='APPLIED'
              AND applied_correction.correction_item_kind IN (
                'PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          AND NOT (
            UPPER(BTRIM(COALESCE(batch_candidate.settlement_status,'')))='SETTLED'
            OR batch_candidate.settled_at_utc IS NOT NULL
            OR UPPER(BTRIM(COALESCE(transfer.status,'')))='COMPLETED'
            OR transfer.completed_at_utc IS NOT NULL
          )
          AND (
            public._pay_batch_status_is_active_reservation(batch_row.status)
            OR EXISTS (
              SELECT 1
              FROM pg_temp._bpay_wb_open_correction_scope_v1 AS correction_scope
              WHERE correction_scope.pay_batch_item_id=item.id
            )
            OR EXISTS (
              SELECT 1
              FROM public.pay_bank_transfer_events terminal_event
              WHERE terminal_event.pay_batch_id=batch_candidate.pay_batch_id
                AND terminal_event.pay_bank_transfer_id=item.pay_bank_transfer_id
                AND terminal_event.mapping_status='MATCHED'
                AND terminal_event.normalised_state IN ('FAILED','DECLINED','REJECTED','CANCELLED')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items applied_failure_correction
                  WHERE applied_failure_correction.pay_batch_item_id=item.id
                    AND applied_failure_correction.status='APPLIED'
                    AND applied_failure_correction.correction_item_kind IN (
                      'NO_MONEY_UNWIND','PRE_BANK_CANCEL','SETTLED_REVERSAL')
                )
            )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_advance_reservations advance
            WHERE (advance.pay_batch_item_id=item.id OR advance.id=item.reservation_id)
              AND UPPER(BTRIM(COALESCE(advance.status,''))) IN ('RESERVED','COMMITTED')
              AND advance.released_at_utc IS NULL
          )
      ), active_item_id_array AS MATERIALIZED (
        SELECT CASE WHEN COUNT(*)=0
          THEN ARRAY['00000000-0000-0000-0000-000000000000'::uuid]
          ELSE ARRAY_AGG(candidate.pay_batch_item_id ORDER BY candidate.pay_batch_item_id) END
          AS pay_batch_item_ids
        FROM active_item_candidates candidate
      ), active_item_components AS MATERIALIZED (
        SELECT component.pay_batch_item_id,
          UPPER(NULLIF(BTRIM(component.key_type),'')) AS key_type,
          NULLIF(BTRIM(component.key_value),'') AS key_value,
          NULLIF(BTRIM(component.key_resolution_source),'') AS key_resolution_source,
          NULLIF(BTRIM(component.key_resolution_failure_reason),'')
            AS key_resolution_failure_reason
        FROM active_item_id_array item_ids
        JOIN LATERAL public._pay_batch_item_economic_components(
          NULL::uuid,item_ids.pay_batch_item_ids) component ON true
      ), active_item_component_summary AS MATERIALIZED (
        SELECT candidate.pay_batch_item_id,
          COUNT(DISTINCT (component.key_type,component.key_value)) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL)::integer
            AS economic_key_count,
          MIN(component.key_type) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL) AS key_type,
          MIN(component.key_value) FILTER(
            WHERE component.key_type IS NOT NULL AND component.key_value IS NOT NULL) AS key_value,
          MIN(component.key_resolution_source) AS key_resolution_source,
          MIN(component.key_resolution_failure_reason) AS key_resolution_failure_reason
        FROM active_item_candidates candidate
        LEFT JOIN active_item_components component
          ON component.pay_batch_item_id=candidate.pay_batch_item_id
        GROUP BY candidate.pay_batch_item_id
      ), active_item_rotation AS MATERIALIZED (
        SELECT DISTINCT ON (rotation.requested_timesheet_id)
          rotation.requested_timesheet_id,
          COALESCE(rotation.canonical_timesheet_id,rotation.requested_timesheet_id)
            AS canonical_timesheet_id
        FROM public._pay_timesheet_rotation_scope(ARRAY(
          SELECT DISTINCT candidate.source_timesheet_id
          FROM active_item_candidates candidate
          ORDER BY candidate.source_timesheet_id)) rotation
        ORDER BY rotation.requested_timesheet_id,rotation.family_is_current DESC NULLS LAST,
          rotation.family_version DESC NULLS LAST,rotation.family_timesheet_id
      ), active_item_enriched AS MATERIALIZED (
        SELECT candidate.*,
          CASE WHEN candidate.reservation_id IS NULL THEN 1
            ELSE COUNT(*) OVER(PARTITION BY candidate.reservation_id) END::integer
            AS logical_owner_count,
          COALESCE(rotation.canonical_timesheet_id,candidate.source_timesheet_id)
            AS sealed_timesheet_id,
          component.economic_key_count,component.key_type,component.key_value,
          component.key_resolution_source,component.key_resolution_failure_reason,
          COALESCE((SELECT jsonb_agg(to_jsonb(breakdown) ORDER BY breakdown.id)
            FROM public.pay_batch_item_breakdowns breakdown
            WHERE breakdown.pay_batch_item_id=candidate.pay_batch_item_id),'[]'::jsonb)
            AS breakdowns,
          COALESCE((SELECT jsonb_agg(correction_scope.correction_request_id::text
                                    ORDER BY correction_scope.correction_request_id::text)
            FROM pg_temp._bpay_wb_open_correction_scope_v1 AS correction_scope
            WHERE correction_scope.pay_batch_item_id=candidate.pay_batch_item_id),
            '[]'::jsonb) AS open_correction_request_ids
        FROM active_item_candidates candidate
        LEFT JOIN active_item_component_summary component
          ON component.pay_batch_item_id=candidate.pay_batch_item_id
        LEFT JOIN active_item_rotation rotation
          ON rotation.requested_timesheet_id=candidate.source_timesheet_id
      ), active_item_payloads AS MATERIALIZED (
        SELECT enriched.*,
          CASE
            WHEN enriched.logical_owner_count<>1
              THEN 'RESERVATION_DUPLICATE_LOGICAL_OWNER'
            WHEN COALESCE(enriched.economic_key_count,0)=0
              THEN 'RESERVATION_ECONOMIC_KEY_MISSING'
            WHEN enriched.economic_key_count<>1
              THEN 'RESERVATION_ECONOMIC_KEY_CONFLICT'
            WHEN enriched.key_resolution_failure_reason IS NOT NULL
              THEN enriched.key_resolution_failure_reason
            WHEN enriched.key_type NOT IN (
              'TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE',
              'EXPENSE_CODE','MANUAL_CARRY_FORWARD')
              OR enriched.key_value IS NULL
              THEN 'RESERVATION_ECONOMIC_KEY_INVALID'
            WHEN enriched.key_type='TS_DAY' AND NOT (
              enriched.key_value ~ '^\d{4}-\d{2}-\d{2}$'
              AND pg_input_is_valid(enriched.key_value,'date')
              AND CASE WHEN pg_input_is_valid(enriched.key_value,'date')
                THEN enriched.key_value::date::text=enriched.key_value ELSE false END)
              THEN 'RESERVATION_TS_DAY_INVALID'
          END AS resolution_failure
        FROM active_item_enriched enriched
      ), active_item_documents AS MATERIALIZED (
        SELECT item.*,
          jsonb_build_object(
            'reservation_authority_version',2,
            'authority_source','ACTIVE_PAY_BATCH_ITEM',
            'pay_batch_item',jsonb_build_object(
              'id',item.pay_batch_item_id::text,
              'pay_batch_id',item.pay_batch_id::text,
              'pay_batch_candidate_id',item.pay_batch_candidate_id::text,
              'timesheet_id',item.source_timesheet_id::text,
              'projected_timesheet_id',item.sealed_timesheet_id::text,
              'item_type',item.item_type,
              'segment_key',item.segment_key,
              'source_ref',item.source_ref,
              'pay_channel',item.pay_channel,
              'reservation_id',item.reservation_id::text,
              'finance_case_id',item.finance_case_id::text,
              'finance_component_id',item.finance_component_id::text,
              'frozen_component_key_type',item.frozen_component_key_type,
              'frozen_component_key_value',item.frozen_component_key_value,
              'frozen_source_basis_json',item.frozen_source_basis_json,
              'frozen_component_snapshot_json',item.frozen_component_snapshot_json,
              'frozen_resolution_payload_json',item.frozen_resolution_payload_json,
              'frozen_resolution_result_json',item.frozen_resolution_result_json),
            'economic_key',jsonb_build_object(
              'key_type',item.key_type,'key_value',item.key_value,
              'key_resolution_source',item.key_resolution_source,
              'key_resolution_failure_reason',item.key_resolution_failure_reason),
            'active_state',jsonb_build_object(
              'batch_status',item.batch_status,
              'candidate_settlement_status',item.candidate_settlement_status,
              'candidate_settled_at_utc',item.candidate_settled_at_utc,
              'transfer_status',item.transfer_status,
              'transfer_completed_at_utc',item.transfer_completed_at_utc,
              'open_correction_request_ids',item.open_correction_request_ids),
            'breakdowns',item.breakdowns,
            'source_reservation_amount_ex_vat',item.reserved_source_amount,
            'resolution_failure',item.resolution_failure) AS source_payload_json
        FROM active_item_payloads item
      )
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT '~ITEM:'||item.pay_batch_item_id::text,
        md5('ACTIVE_ITEM_RESERVATION:'||item.pay_batch_item_id::text),
        item.sealed_timesheet_id,
        ARRAY(SELECT DISTINCT owner_id FROM unnest(ARRAY[
          item.source_timesheet_id,item.sealed_timesheet_id]) owner(owner_id)
          WHERE owner_id IS NOT NULL ORDER BY owner_id),
        'pay_batch_items_active_reservation',item.pay_batch_item_id,
        item.key_type,item.key_value,
        NULL,NULL,NULL,NULL,NULL,NULL,item.reserved_source_amount,
        item.finance_case_id,item.finance_component_id,
        COALESCE(item.reservation_id,item.pay_batch_item_id),
        item.source_payload_json,md5(item.source_payload_json::text)
      FROM active_item_documents item
      WHERE v_last_source_key IS NULL
        OR ('~ITEM:'||item.pay_batch_item_id::text) COLLATE "C"
          >v_last_source_key COLLATE "C"
      ORDER BY ('~ITEM:'||item.pay_batch_item_id::text) COLLATE "C"
      LIMIT v_fact_limit+1
      ON CONFLICT(source_key) DO NOTHING;
    ELSIF v_fact_family='FINANCE_CASE_IDENTITY' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT finance_case.id::text,md5('CASE:'||finance_case.id::text),finance_case.linked_timesheet_id,
        CASE WHEN finance_case.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[finance_case.linked_timesheet_id] END,
        'pay_advances',finance_case.id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,finance_case.id,NULL,NULL,
        to_jsonb(finance_case),md5(to_jsonb(finance_case)::text)
      FROM public.pay_advances finance_case WHERE finance_case.candidate_id=p_candidate_id
        AND ((finance_case.cleared_at_utc IS NULL AND finance_case.written_off_at_utc IS NULL)
          OR finance_case.linked_timesheet_id IN (
            SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope
            WHERE build_id=v_build_id
          ))
        AND (v_last_source_key IS NULL OR finance_case.id::text>v_last_source_key)
      ORDER BY finance_case.id LIMIT v_fact_limit+1;
    ELSIF v_fact_family='FINANCE_COMPONENT_IDENTITY' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT component.id::text,md5('COMPONENT:'||component.id::text),component.linked_timesheet_id,
        CASE WHEN component.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[component.linked_timesheet_id] END,
        'pay_finance_case_components',component.id,
        CASE WHEN component.component_key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
          THEN component.component_key_type ELSE NULL END,
        CASE WHEN component.component_key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
          THEN component.component_key_value ELSE NULL END,
        component.source_amount,NULL,NULL,NULL,NULL,NULL,component.remaining_source_amount,
        component.finance_case_id,component.id,NULL,to_jsonb(component),md5(to_jsonb(component)::text)
      FROM public.pay_finance_case_components component WHERE component.candidate_id=p_candidate_id
        AND component.closed_at_utc IS NULL AND (v_last_source_key IS NULL OR component.id::text>v_last_source_key)
      ORDER BY component.id LIMIT v_fact_limit+1;
    ELSIF v_fact_family='PROTECTION_EVIDENCE' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT 'EVENT:'||event.id::text,md5('EVENT:'||event.id::text),component.linked_timesheet_id,
        CASE WHEN component.linked_timesheet_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[component.linked_timesheet_id] END,
        'pay_finance_case_events',event.id,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
        event.finance_case_id,event.finance_component_id,event.reservation_id,to_jsonb(event),md5(to_jsonb(event)::text)
      FROM public.pay_finance_case_events event
      JOIN private.banking_pay_workbench_economic_build_facts case_fact
        ON case_fact.build_id=v_build_id AND case_fact.fact_family='FINANCE_CASE_IDENTITY'
       AND case_fact.finance_case_id=event.finance_case_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=event.finance_component_id
      WHERE case_fact.candidate_id=p_candidate_id
        AND (
          upper(btrim(COALESCE(event.event_type,''))) LIKE '%WRITE%OFF%'
          OR upper(btrim(COALESCE(event.event_type,''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR upper(btrim(COALESCE(event.reason,''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR (
            upper(btrim(COALESCE(event.event_type,'')))='CASE_CLEARED'
            AND lower(btrim(COALESCE(event.reason,'')))='rail_settlement'
          )
          OR (
            upper(btrim(COALESCE(event.event_type,'')))='CLEARED'
            AND upper(btrim(COALESCE(event.reason,'')))='PREVIEW_FINANCE_SYNC'
          )
        )
        AND event.id=(
          SELECT event_latest.id
          FROM public.pay_finance_case_events event_latest
          WHERE event_latest.finance_case_id=event.finance_case_id
            AND (
              upper(btrim(COALESCE(event_latest.event_type,''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(COALESCE(event_latest.event_type,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR upper(btrim(COALESCE(event_latest.reason,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR (upper(btrim(COALESCE(event_latest.event_type,'')))='CASE_CLEARED'
                AND lower(btrim(COALESCE(event_latest.reason,'')))='rail_settlement')
              OR (upper(btrim(COALESCE(event_latest.event_type,'')))='CLEARED'
                AND upper(btrim(COALESCE(event_latest.reason,'')))='PREVIEW_FINANCE_SYNC')
            )
            AND (CASE WHEN (
              upper(btrim(COALESCE(event_latest.event_type,''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(COALESCE(event_latest.event_type,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR upper(btrim(COALESCE(event_latest.reason,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'))
              THEN 'MANUAL' ELSE 'AUTOMATIC_CLEAR' END)
              =(CASE WHEN (
                upper(btrim(COALESCE(event.event_type,''))) LIKE '%WRITE%OFF%'
                OR upper(btrim(COALESCE(event.event_type,''))) IN (
                  'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF','CASE_MANUAL_ECONOMIC_OVERRIDE',
                  'COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
                OR upper(btrim(COALESCE(event.reason,''))) IN (
                  'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE'))
                THEN 'MANUAL' ELSE 'AUTOMATIC_CLEAR' END)
          ORDER BY event_latest.event_at_utc DESC NULLS LAST,event_latest.id DESC
          LIMIT 1
        )
        AND (v_last_source_key IS NULL OR 'EVENT:'||event.id::text>v_last_source_key)
      ORDER BY event.id LIMIT v_fact_limit+1;
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT 'BATCH_ITEM:'||item.id::text,md5('BATCH_ITEM_PROTECTION:'||item.id::text),
        item.timesheet_id,CASE WHEN item.timesheet_id IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[item.timesheet_id] END,'pay_batch_items',item.id,
        NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,item.finance_case_id,
        item.finance_component_id,item.reservation_id,
        to_jsonb(item)||jsonb_build_object('protection_kind','ACTIVE_CORRECTION_CHAIN_BATCH_ITEM'),
        md5(to_jsonb(item)::text)
      FROM public.pay_batch_items item
      JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=item.pay_batch_candidate_id
      JOIN public.pay_batches batch_row ON batch_row.id=batch_candidate.pay_batch_id
      WHERE batch_candidate.candidate_id=p_candidate_id
        AND COALESCE(item.is_voided,false) IS NOT TRUE
        AND batch_row.cancelled_at_utc IS NULL
        AND upper(btrim(COALESCE(batch_row.status,''))) IN (
          'DRAFT','DRAFT_CREATED','READY','WAITING_BANK_CONFIRM','PARTIAL','FAILED',
          'BLOCKED_FUNDS','SCHEDULED','EXECUTING','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT')
        AND COALESCE(item.frozen_component_snapshot_json->>'correction_root_id',
          item.frozen_resolution_payload_json->>'correction_root_id','') IN (
            SELECT scope_row.root_timesheet_id::text
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id AND scope_row.root_timesheet_id IS NOT NULL)
        AND (v_last_source_key IS NULL OR 'BATCH_ITEM:'||item.id::text>v_last_source_key)
      ORDER BY item.id LIMIT v_fact_limit+1
      ON CONFLICT(source_key) DO NOTHING;
    ELSIF v_fact_family='ALLOCATION_INPUT' THEN
      INSERT INTO pg_temp._bpay_wb_fact_page_v1
      SELECT fact.fact_family||':'||fact.natural_key,md5('ALLOCATION:'||fact.fact_family||':'||fact.natural_key),
        fact.timesheet_id,fact.subject_timesheet_ids,'economic_build_facts',fact.source_id,
        fact.economic_key_type,fact.economic_key_value,
        COALESCE(fact.amount_ex_vat,fact.truth_ex_vat),COALESCE(fact.amount_inc_vat,fact.truth_inc_vat),
        fact.truth_ex_vat,fact.truth_inc_vat,fact.baseline_ex_vat,fact.baseline_inc_vat,
        fact.reserved_source_amount,fact.finance_case_id,fact.finance_component_id,fact.reservation_id,
        jsonb_build_object('source_fact_family',fact.fact_family,'source_natural_key',fact.natural_key),fact.financial_digest
      FROM private.banking_pay_workbench_economic_build_facts fact
      WHERE fact.build_id=v_build_id AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT')
        AND fact.economic_key_type IS NOT NULL
        AND (v_last_source_key IS NULL OR fact.fact_family||':'||fact.natural_key>v_last_source_key)
      ORDER BY fact.fact_family,fact.natural_key LIMIT v_fact_limit+1;
    ELSE
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    SELECT NULLIF(BTRIM(page.source_payload_json->>'resolution_failure'),'')
    INTO v_resolution_failure
    FROM pg_temp._bpay_wb_fact_page_v1 page
    WHERE NULLIF(BTRIM(page.source_payload_json->>'resolution_failure'),'') IS NOT NULL
    ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN page.source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN page.source_key END
    LIMIT 1;
    IF v_resolution_failure IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ECONOMIC_KEY_RESOLUTION_INCOMPLETE'
        USING ERRCODE='23514',DETAIL=v_resolution_failure;
    END IF;
    IF v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
      v_raw_source_has_more:=COALESCE(
        (v_occurrence_bundle->>'raw_source_has_more')::boolean,false);
      v_has_more:=v_raw_source_has_more;
    ELSIF v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
       AND v_input_phase<>'PROJECTION' THEN
      v_raw_source_has_more:=COALESCE(
        (v_occurrence_bundle->>'raw_source_has_more')::boolean,false);
      v_has_more:=v_raw_source_has_more;
    ELSE
      v_raw_source_has_more:=false;
      SELECT count(*)>v_fact_limit INTO v_has_more FROM pg_temp._bpay_wb_fact_page_v1;
    END IF;
    SELECT count(*)::integer,
      md5(CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN v_reservation_order_contract||':' ELSE '' END
        ||COALESCE(string_agg(source_key||':'||financial_digest,'' ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END),'')),
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN max(source_key COLLATE "C") ELSE max(source_key) END
    INTO v_page_count,v_page_digest,v_last_page_key
    FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN source_key END LIMIT v_fact_limit) page_rows;

    IF NOT v_has_more AND v_fact_family='LIVE_ENTITLEMENT_INPUT' AND v_input_phase='PROJECTION' THEN
      SELECT projection_ids.projected_timesheet_id INTO v_next_projection_id
      FROM (
        SELECT fact.timesheet_id AS projected_timesheet_id
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id AND fact.fact_family='LIVE_ENTITLEMENT_INPUT'
          AND fact.dependency_unit_key=v_unit_key AND fact.source_relation='UNIT_PROJECTION'
        UNION ALL
        SELECT page.timesheet_id
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END LIMIT v_fact_limit) page
        WHERE page.source_relation='UNIT_PROJECTION'
      ) projection_ids
      ORDER BY projection_ids.projected_timesheet_id
      LIMIT 1;
      IF v_next_projection_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_UNIT_PROJECTION_INCOMPLETE' USING ERRCODE='23514';
      END IF;
      v_projection_phase_transition:=true;
      v_has_more:=true;
    ELSIF NOT v_has_more
      AND v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK') THEN
      SELECT projection.timesheet_id INTO v_next_projection_id
      FROM private.banking_pay_workbench_economic_build_facts projection
      WHERE projection.build_id=v_build_id
        AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
        AND projection.dependency_unit_key=v_unit_key
        AND projection.source_relation='UNIT_PROJECTION'
        AND projection.timesheet_id>v_input_projection_id
      ORDER BY projection.timesheet_id
      LIMIT 1;
      IF v_next_projection_id IS NOT NULL THEN
        v_projection_family_transition:=true;
        v_has_more:=true;
      END IF;
    END IF;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' OR (
         v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
         AND v_input_phase<>'PROJECTION') THEN
      v_has_more:=private.pay_workbench_physical_source_continuation_v1(
        v_raw_source_has_more,
        COALESCE((v_occurrence_bundle->>'raw_source_exhausted')::boolean,false),
        v_projection_family_transition);
    END IF;

    IF v_fact_family='FINANCE_ITEM_AUTHORITY' OR (
         v_fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
         AND v_input_phase<>'PROJECTION') THEN
      v_page_physical_source_count:=COALESCE((v_occurrence_bundle->>'raw_page_count')::bigint,0);
      v_page_resolved_source_count:=COALESCE((v_occurrence_bundle->>'resolved_page_count')::bigint,0);
      v_page_failed_source_count:=COALESCE((v_occurrence_bundle->>'failed_page_count')::bigint,0);
      v_page_physical_amount_ex_vat:=COALESCE((v_occurrence_bundle->>'raw_amount_ex_vat')::numeric,0);
      v_page_resolved_amount_ex_vat:=COALESCE((v_occurrence_bundle->>'resolved_amount_ex_vat')::numeric,0);
      IF (v_page_physical_source_count>0
           AND NULLIF(v_occurrence_bundle->>'last_raw_source_key','') IS NULL)
         OR NULLIF(v_occurrence_bundle->>'evidence_digest','') IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_EVIDENCE_INVALID'
          USING ERRCODE='23514';
      END IF;
    ELSE
      SELECT count(*)::bigint,
        count(*) FILTER(WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NULL)::bigint,
        count(*) FILTER(WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NOT NULL)::bigint,
        ROUND(COALESCE(sum(COALESCE(page.truth_ex_vat,page.amount_ex_vat,
          page.reserved_source_amount,0)),0),2),
        ROUND(COALESCE(sum(COALESCE(page.truth_ex_vat,page.amount_ex_vat,
          page.reserved_source_amount,0)) FILTER(
            WHERE NULLIF(page.source_payload_json->>'resolution_failure','') IS NULL),0),2)
      INTO v_page_physical_source_count,v_page_resolved_source_count,
        v_page_failed_source_count,v_page_physical_amount_ex_vat,
        v_page_resolved_amount_ex_vat
      FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
        CASE WHEN v_fact_family='RESERVATION_COMPONENT'
          THEN source_key END COLLATE "C",
        CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
          THEN source_key END LIMIT v_fact_limit) page
      WHERE v_fact_family='RESERVATION_COMPONENT'
        AND page.source_relation<>'UNIT_PROJECTION';
      IF v_fact_family='RESERVATION_COMPONENT' THEN
        SELECT jsonb_build_object(
          'evidence_digest',md5(v_reservation_order_contract||':'||COALESCE(string_agg(page.source_key||':'||COALESCE(
            NULLIF(page.source_payload_json->>'raw_physical_digest',''),page.financial_digest),''
            ORDER BY page.source_key COLLATE "C"),'')),
          'last_raw_source_key',max(page.source_key COLLATE "C"))
        INTO v_occurrence_bundle
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1
          ORDER BY source_key COLLATE "C" LIMIT v_fact_limit) page;
      END IF;
    END IF;
    v_next_raw_physical_source_count:=v_raw_physical_source_count+
      COALESCE(v_page_physical_source_count,0);
    v_next_resolved_physical_source_count:=v_resolved_physical_source_count+
      COALESCE(v_page_resolved_source_count,0);
    v_next_failed_physical_source_count:=v_failed_physical_source_count+
      COALESCE(v_page_failed_source_count,0);
    v_next_raw_physical_amount_ex_vat:=ROUND(v_raw_physical_amount_ex_vat+
      COALESCE(v_page_physical_amount_ex_vat,0),2);
    v_next_resolved_physical_amount_ex_vat:=ROUND(v_resolved_physical_amount_ex_vat+
      COALESCE(v_page_resolved_amount_ex_vat,0),2);
    v_next_last_raw_physical_source_key:=COALESCE(
      NULLIF(v_occurrence_bundle->>'last_raw_source_key',''),
      CASE WHEN v_page_physical_source_count>0 THEN v_last_page_key END,
      v_last_raw_physical_source_key);
    v_cursor_start_hash:=md5(v_cursor::text);
    v_next_cumulative_fact_count:=v_cumulative_fact_count+v_page_count;
    v_cumulative_digest:=md5(v_cumulative_digest||v_page_digest);
    v_is_final:=NOT v_has_more;
    v_next:=jsonb_build_object('cursor_kind','WORKSPACE_FACT','cursor_version',2,
      'build_id',v_build_id,'candidate_id',p_candidate_id,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'dependency_unit_key',v_unit_key,'fact_family',v_fact_family,
      'page_number',v_page_number+1,'last_source_key',CASE
        WHEN v_projection_phase_transition OR v_projection_family_transition THEN NULL
        WHEN v_has_more THEN v_last_page_key ELSE NULL END,
      'previous_page_digest',v_page_digest,'cumulative_fact_count',v_next_cumulative_fact_count,
      'cumulative_digest',v_cumulative_digest,
      'terminal',v_is_final,
      'raw_physical_source_count',v_next_raw_physical_source_count,
      'resolved_physical_source_count',v_next_resolved_physical_source_count,
      'failed_physical_source_count',v_next_failed_physical_source_count,
      'raw_physical_amount_ex_vat',v_next_raw_physical_amount_ex_vat,
      'resolved_physical_amount_ex_vat',v_next_resolved_physical_amount_ex_vat,
      'last_raw_physical_source_key',v_next_last_raw_physical_source_key,
      'source_exhausted',v_is_final,
      'raw_terminal_source_key',CASE WHEN v_is_final AND v_page_physical_source_count>0
        THEN v_next_last_raw_physical_source_key
        WHEN v_is_final AND v_next_raw_physical_source_count>0
        THEN v_next_last_raw_physical_source_key END,
      'raw_page_evidence_digest',v_occurrence_bundle->>'evidence_digest',
      'input_phase',CASE WHEN v_projection_phase_transition THEN 'COMPONENTS'
        ELSE v_input_phase END,
      'input_projection_id',CASE WHEN v_projection_phase_transition OR v_projection_family_transition
        THEN v_next_projection_id ELSE v_input_projection_id END);
    IF v_fact_family='RESERVATION_COMPONENT' THEN
      v_next:=v_next || jsonb_build_object(
        'reservation_source_key_order_contract',v_reservation_order_contract);
    END IF;
    v_cursor_end_hash:=md5(v_next::text);
    v_expected_source_count:=CASE
      WHEN v_is_final AND v_fact_family IN ('FINANCE_ITEM_AUTHORITY','LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT',
        'PAY_STATE_FALLBACK','RESERVATION_COMPONENT')
        THEN v_next_raw_physical_source_count::integer
      ELSE NULL END;

    IF v_page_number=1 THEN
      IF v_cumulative_fact_count<>0 OR v_cursor->>'previous_page_digest' IS NOT NULL
         OR v_cursor->>'cumulative_digest' IS DISTINCT FROM md5('BPAY_FACT_STREAM_V2')
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_fact_pages
           WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
             AND fact_family=v_fact_family LIMIT 1) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    ELSE
      SELECT * INTO v_previous_page
      FROM private.banking_pay_workbench_economic_build_fact_pages
      WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
        AND fact_family=v_fact_family AND page_number=v_page_number-1;
      IF v_previous_page.id IS NULL OR v_previous_page.status<>'COMPLETED'
         OR v_previous_page.is_family_final
         OR v_previous_page.cursor_end_hash<>v_cursor_start_hash
         OR v_previous_page.cursor_end_json IS DISTINCT FROM v_cursor
         OR v_previous_page.cumulative_fact_count<>v_cumulative_fact_count
         OR v_previous_page.cumulative_digest<>COALESCE(v_cursor->>'cumulative_digest','')
         OR v_previous_page.page_digest<>COALESCE(v_cursor->>'previous_page_digest','') THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
      END IF;
    END IF;

    SELECT * INTO v_existing_page FROM private.banking_pay_workbench_economic_build_fact_pages
    WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key
      AND fact_family=v_fact_family AND page_number=v_page_number;
    IF FOUND THEN
      IF v_existing_page.attempt_id IS DISTINCT FROM v_attempt_id
         OR v_existing_page.status<>'COMPLETED'
         OR v_existing_page.cursor_start_json IS DISTINCT FROM v_cursor
         OR v_existing_page.cursor_start_hash<>v_cursor_start_hash
         OR v_existing_page.cursor_end_json IS DISTINCT FROM v_next
         OR v_existing_page.cursor_end_hash<>v_cursor_end_hash
         OR v_existing_page.expected_source_count IS DISTINCT FROM v_expected_source_count
         OR v_existing_page.actual_fact_count<>v_page_count
         OR v_existing_page.cumulative_fact_count<>v_next_cumulative_fact_count
         OR v_existing_page.page_digest<>v_page_digest
         OR v_existing_page.cumulative_digest<>v_cumulative_digest
         OR v_existing_page.is_family_final IS DISTINCT FROM v_is_final THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_REPLAY_CONFLICT' USING ERRCODE='23514';
      END IF;
      SELECT fact_cursor_json INTO v_replay_cursor
      FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage',v_build.private_stage,'stage_status','PAGE_REPLAYED',
        'has_more',true,'continuation_enqueued',false,
        'next_cursor_json',COALESCE(v_replay_cursor,v_next),'next_action',v_build.private_stage,
        'page_fact_count',v_page_count,'cumulative_fact_count',v_next_cumulative_fact_count,
        'page_digest',v_page_digest,'cumulative_digest',v_cumulative_digest);
    END IF;

    IF EXISTS(
      SELECT 1 FROM pg_temp._bpay_wb_fact_page_v1 page_row
      JOIN private.banking_pay_workbench_economic_build_facts existing
        ON existing.build_id=v_build_id AND existing.fact_family=v_fact_family
       AND existing.natural_key=page_row.natural_key
      WHERE existing.financial_digest<>page_row.financial_digest LIMIT 1
    ) THEN RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_REPLAY_CONFLICT' USING ERRCODE='23514'; END IF;

    IF v_fact_family IS NOT NULL THEN
      INSERT INTO private.banking_pay_workbench_economic_build_facts(
      build_id,fact_family,natural_key,candidate_id,timesheet_id,subject_timesheet_ids,
      dependency_unit_key,source_relation,source_id,economic_key_type,economic_key_value,
      amount_ex_vat,amount_inc_vat,truth_ex_vat,truth_inc_vat,baseline_ex_vat,baseline_inc_vat,
      reserved_source_amount,finance_case_id,finance_component_id,reservation_id,
      source_payload_json,financial_digest
    )
    SELECT v_build_id,v_fact_family,page.natural_key,p_candidate_id,page.timesheet_id,
      page.subject_timesheet_ids,v_unit_key,page.source_relation,page.source_id,
      page.economic_key_type,page.economic_key_value,page.amount_ex_vat,page.amount_inc_vat,
      page.truth_ex_vat,page.truth_inc_vat,page.baseline_ex_vat,page.baseline_inc_vat,
      page.reserved_source_amount,page.finance_case_id,page.finance_component_id,page.reservation_id,
      page.source_payload_json,page.financial_digest
    FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
      CASE WHEN v_fact_family='RESERVATION_COMPONENT'
        THEN source_key END COLLATE "C",
      CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
        THEN source_key END LIMIT v_fact_limit) page;
      GET DIAGNOSTICS v_scope_inserted=ROW_COUNT;
      IF v_scope_inserted<>v_page_count THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_COUNT_MISMATCH' USING ERRCODE='23514';
      END IF;
    ELSE
      v_scope_inserted:=0;
    END IF;

    -- Physical occurrences are already typed and immutable. Derived families
    -- page those stored occurrences; no page-local live helper is invoked.
    v_derived_fact_count:=0;
    v_derived_settled_count:=0;
    v_derived_fallback_count:=0;

    -- The table's physical column order evaluates completed_at_utc before
    -- created_at_utc.  Supplying one database-owned timestamp prevents two
    -- independent clock_timestamp() defaults from intermittently violating
    -- completed_at_utc >= created_at_utc under fast concurrent lanes.
    v_fact_page_timestamp:=clock_timestamp();
    INSERT INTO private.banking_pay_workbench_economic_build_fact_pages(
      build_id,attempt_id,dependency_unit_key,fact_family,page_number,
      cursor_start_json,cursor_start_hash,cursor_end_json,cursor_end_hash,
      expected_source_count,actual_fact_count,cumulative_fact_count,page_digest,cumulative_digest,is_family_final,
      completed_at_utc,created_at_utc
    ) VALUES(v_build_id,v_attempt_id,v_unit_key,v_fact_family,v_page_number,
      v_cursor,v_cursor_start_hash,v_next,v_cursor_end_hash,v_expected_source_count,v_page_count,
      v_next_cumulative_fact_count,v_page_digest,v_cumulative_digest,v_is_final,
      v_fact_page_timestamp,v_fact_page_timestamp);

    IF v_unit_key<>'GLOBAL' THEN
      UPDATE private.banking_pay_workbench_economic_build_scope scope_row
      SET fact_row_count=scope_row.fact_row_count+page_count.page_count,
          fact_digest=md5(COALESCE(scope_row.fact_digest,md5('BPAY_SCOPE_FACT_V1'))||v_page_digest),
          updated_at_utc=clock_timestamp()
      FROM (
        SELECT page.timesheet_id,count(*)::integer page_count
        FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
          CASE WHEN v_fact_family='RESERVATION_COMPONENT'
            THEN source_key END COLLATE "C",
          CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
            THEN source_key END LIMIT v_fact_limit) page
        WHERE page.timesheet_id IS NOT NULL GROUP BY page.timesheet_id
      ) page_count
      WHERE scope_row.build_id=v_build_id AND scope_row.timesheet_id=page_count.timesheet_id;
    END IF;

    UPDATE private.banking_pay_workbench_economic_builds build_row
    SET fact_count=build_row.fact_count+v_scope_inserted+v_derived_fact_count+v_derived_settled_count+v_derived_fallback_count,
        complexity_vector_json=COALESCE(build_row.complexity_vector_json,'{}'::jsonb)
          ||jsonb_build_object(
            'settled_source_row_count',COALESCE((build_row.complexity_vector_json->>'settled_source_row_count')::bigint,0)+page_stats.settled_count,
            'settled_component_count',COALESCE((build_row.complexity_vector_json->>'settled_component_count')::bigint,0)+page_stats.settled_count,
            'entitlement_component_count',COALESCE((build_row.complexity_vector_json->>'entitlement_component_count')::bigint,0)+page_stats.entitlement_count,
            'reservation_component_count',COALESCE((build_row.complexity_vector_json->>'reservation_component_count')::bigint,0)+page_stats.reservation_count,
            'finance_case_count',COALESCE((build_row.complexity_vector_json->>'finance_case_count')::bigint,0)+page_stats.case_count,
            'finance_component_count',COALESCE((build_row.complexity_vector_json->>'finance_component_count')::bigint,0)+page_stats.component_count,
            'protection_evidence_count',COALESCE((build_row.complexity_vector_json->>'protection_evidence_count')::bigint,0)+page_stats.protection_count,
            'expected_case_insert_count',COALESCE((build_row.complexity_vector_json->>'expected_case_insert_count')::bigint,0)+page_stats.negative_count,
            'expected_component_insert_count',COALESCE((build_row.complexity_vector_json->>'expected_component_insert_count')::bigint,0)+page_stats.negative_count,
            'canonical_source_row_count',COALESCE((build_row.complexity_vector_json->>'canonical_source_row_count')::bigint,0)+page_stats.canonical_count,
            'staging_bytes',COALESCE((build_row.complexity_vector_json->>'staging_bytes')::bigint,0)+page_stats.staging_bytes),
        updated_at_utc=clock_timestamp()
    FROM (SELECT
      count(*) FILTER(WHERE v_fact_family='FROZEN_SETTLED_COMPONENT')::bigint settled_count,
      count(*) FILTER(WHERE v_fact_family='ENTITLEMENT_COMPONENT')::bigint entitlement_count,
      count(*) FILTER(WHERE v_fact_family='RESERVATION_COMPONENT')::bigint reservation_count,
      count(*) FILTER(WHERE v_fact_family='FINANCE_CASE_IDENTITY')::bigint case_count,
      count(*) FILTER(WHERE v_fact_family='FINANCE_COMPONENT_IDENTITY')::bigint component_count,
      count(*) FILTER(WHERE v_fact_family='PROTECTION_EVIDENCE')::bigint protection_count,
      count(*) FILTER(WHERE v_fact_family='ENTITLEMENT_COMPONENT' AND truth_ex_vat<baseline_ex_vat)::bigint negative_count,
      count(*) FILTER(WHERE v_fact_family='CANONICAL_INPUT')::bigint canonical_count,
      COALESCE(sum(pg_column_size(source_payload_json)) FILTER(WHERE v_fact_family='CANONICAL_INPUT'),0)::bigint staging_bytes
      FROM (SELECT * FROM pg_temp._bpay_wb_fact_page_v1 ORDER BY
        CASE WHEN v_fact_family='RESERVATION_COMPONENT'
          THEN source_key END COLLATE "C",
        CASE WHEN v_fact_family<>'RESERVATION_COMPONENT'
          THEN source_key END LIMIT v_fact_limit) accepted) page_stats
    WHERE build_row.id=v_build_id;

    IF v_is_final THEN
      IF v_unit_key<>'GLOBAL' THEN
        UPDATE private.banking_pay_workbench_economic_build_scope
        SET completed_fact_families=(SELECT array_agg(DISTINCT family ORDER BY family)
          FROM unnest(completed_fact_families||ARRAY[v_fact_family]) family),updated_at_utc=clock_timestamp()
        WHERE build_id=v_build_id AND dependency_unit_key=v_unit_key;
      END IF;
      IF v_unit_key='GLOBAL' AND v_fact_family='FINANCE_ITEM_AUTHORITY' THEN
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN
          v_unit_key:='GLOBAL';
          v_fact_family:=v_global_families[2];
        ELSE
          v_fact_family:=v_unit_families[1];
        END IF;
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_fact_family,
          CASE WHEN v_unit_key<>'GLOBAL' THEN 'PROJECTION'
            ELSE 'PHYSICAL_SOURCE' END,NULL);
      ELSIF v_unit_key<>'GLOBAL' AND v_family_ordinal<cardinality(v_unit_families) THEN
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_unit_families[v_family_ordinal+1],
          CASE WHEN v_unit_families[v_family_ordinal+1]='LIVE_ENTITLEMENT_INPUT'
            THEN 'PROJECTION' ELSE 'COMPONENTS' END,NULL);
      ELSIF v_unit_key<>'GLOBAL' THEN
        SELECT dependency_unit_key INTO v_unit_key
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id AND NOT required_fact_families <@ completed_fact_families
        ORDER BY stable_ordinal LIMIT 1;
        IF v_unit_key IS NULL THEN v_unit_key:='GLOBAL';v_fact_family:=v_global_families[2];
        ELSE v_fact_family:=v_unit_families[1]; END IF;
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,v_unit_key,v_fact_family,
          CASE WHEN v_unit_key<>'GLOBAL' THEN 'PROJECTION'
            ELSE 'PHYSICAL_SOURCE' END,NULL);
      ELSIF v_family_ordinal<cardinality(v_global_families) THEN
        v_next:=private.pay_workbench_fact_cursor_transition_v3(
          v_next,'GLOBAL',v_global_families[v_family_ordinal+1],
          'PHYSICAL_SOURCE',NULL);
      ELSE
        IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
          WHERE build_id=v_build_id AND NOT required_fact_families<@completed_fact_families LIMIT 1) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_FACT_PAGE_CHAIN_INCOMPLETE' USING ERRCODE='23514';
        END IF;
        IF EXISTS(
          WITH required_stream AS (
            SELECT DISTINCT scope_row.dependency_unit_key,required.family AS fact_family
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            CROSS JOIN LATERAL unnest(ARRAY['LIVE_ENTITLEMENT_INPUT',
              'FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK']) required(family)
            WHERE scope_row.build_id=v_build_id
            UNION ALL SELECT 'GLOBAL'::text,'FINANCE_ITEM_AUTHORITY'::text
            UNION ALL SELECT 'GLOBAL'::text,'RESERVATION_COMPONENT'::text
          ), terminal_stream AS (
            SELECT page.dependency_unit_key,page.fact_family,count(*) AS terminal_count,
              min(page.expected_source_count) AS expected_source_count,
              min((page.cursor_end_json->>'raw_physical_source_count')::bigint) AS raw_count,
              min((page.cursor_end_json->>'resolved_physical_source_count')::bigint) AS resolved_count,
              min((page.cursor_end_json->>'failed_physical_source_count')::bigint) AS failed_count,
              min((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric) AS raw_amount,
              min((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric) AS resolved_amount,
              min(NULLIF(page.cursor_end_json->>'raw_terminal_source_key','')) AS terminal_source_key,
              bool_and(COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false)) AS exhausted
            FROM private.banking_pay_workbench_economic_build_fact_pages page
            WHERE page.build_id=v_build_id AND page.status='COMPLETED' AND page.is_family_final
            GROUP BY page.dependency_unit_key,page.fact_family
          )
          SELECT 1 FROM required_stream required
          LEFT JOIN terminal_stream terminal USING(dependency_unit_key,fact_family)
          WHERE terminal.terminal_count IS DISTINCT FROM 1
             OR terminal.expected_source_count IS DISTINCT FROM terminal.raw_count::integer
             OR terminal.raw_count IS DISTINCT FROM terminal.resolved_count
             OR terminal.failed_count IS DISTINCT FROM 0
             OR ROUND(terminal.raw_amount,2) IS DISTINCT FROM ROUND(terminal.resolved_amount,2)
             OR (terminal.raw_count>0 AND terminal.terminal_source_key IS NULL)
             OR terminal.exhausted IS DISTINCT FROM true
          LIMIT 1
        ) THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_SEAL_INCOMPLETE' USING ERRCODE='23514';
        END IF;
        IF v_registry.initialisation_status IN ('DISCOVERING','CLASSIFYING')
           AND v_registry.bootstrap_id IS NOT NULL
           AND COALESCE((v_build.attestation_json->>'bootstrap_active_reconciliation')::boolean,false)
             IS NOT TRUE THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_registry.bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',NULL,
            'dependency_unit_key',NULL,'last_stable_ordinal',0,
            'unit_financially_relevant',false,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
          UPDATE private.banking_pay_workbench_economic_builds
          SET status='COLLECTING',private_stage='BOOTSTRAP_DISCOVERY',
            fact_cursor_json=jsonb_build_object('cursor_kind','WORKSPACE_FACT','cursor_version',2,
              'terminal',true,'build_id',v_build_id),
            updated_at_utc=clock_timestamp()
          WHERE id=v_build_id;
          UPDATE private.banking_pay_workbench_candidate_scope_registry
          SET initialisation_status='CLASSIFYING',bootstrap_stream='CLASSIFY_UNITS',
            bootstrap_cursor_json=v_next,updated_at_utc=clock_timestamp()
          WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
            'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
            'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
            'next_action','BOOTSTRAP_DISCOVERY');
        END IF;
        SELECT COALESCE(complexity_vector_json,'{}'::jsonb)||jsonb_build_object(
          'relevant_timesheet_count',scope_count,'dependency_node_count',dependency_node_count,
          'dependency_edge_count',dependency_edge_count,
          'expected_case_update_count',COALESCE((complexity_vector_json->>'finance_case_count')::bigint,0),
          'expected_case_clear_count',0,
          'expected_component_update_count',COALESCE((complexity_vector_json->>'finance_component_count')::bigint,0),
          'expected_component_close_count',0)
        INTO v_vector FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
        SELECT banking_pay_workbench_reconciliation_envelope_version,
               banking_pay_workbench_reconciliation_envelope_json,
               banking_pay_workbench_reconciliation_envelope_evidence_json
        INTO v_envelope_version,v_envelope,v_envelope_evidence
        FROM public.settings_defaults WHERE id=1;
        IF v_envelope_version IS NULL OR jsonb_typeof(v_envelope)<>'object' OR v_envelope='{}'::jsonb
           OR jsonb_typeof(v_envelope_evidence)<>'object' OR v_envelope_evidence='{}'::jsonb THEN
          v_scale_blocked:=true;
          v_scale_block_reason:='ENVELOPE_OR_EVIDENCE_MISSING_OR_MALFORMED';
          -- A malformed or absent configuration is itself immutable scale-block
          -- evidence.  Preserve a truthful non-empty snapshot so the durable
          -- BLOCKED row satisfies its lifecycle constraint without inventing a
          -- financial limit or allowing reconciliation to continue.
          v_envelope_version:=COALESCE(v_envelope_version,1);
          v_envelope:=jsonb_build_object(
            '_authority_state','ENVELOPE_OR_EVIDENCE_MISSING_OR_MALFORMED'
          );
          v_envelope_evidence:=jsonb_build_object(
            'evidence_status','UNVALIDATED_CONFIGURATION'
          );
        ELSE
          FOR v_vector_item IN SELECT key,value FROM jsonb_each_text(v_vector) LOOP
            IF COALESCE(v_envelope->>v_vector_item.key,'') !~ '^[0-9]+$' THEN
              v_scale_blocked:=true;
              v_scale_block_reason:='VECTOR_OUTSIDE_MEASURED_ENVELOPE';
              v_slice_possible:=false;
              EXIT;
            ELSIF v_vector_item.value::numeric>(v_envelope->>v_vector_item.key)::numeric THEN
              v_scale_blocked:=true;
              v_scale_block_reason:='VECTOR_OUTSIDE_MEASURED_ENVELOPE';
              -- A28: only the two per-Timesheet dimensions can be divided. Any other dimension above the
              -- measured envelope (cases, components, bytes, ...) remains a fail-closed block.
              IF v_vector_item.key NOT IN ('relevant_timesheet_count','dependency_node_count') THEN
                v_slice_possible:=false;
              END IF;
            END IF;
          END LOOP;
          -- A28 (PRE-EXISTING SB02 change, user ruling): a Candidate above the per-Timesheet envelope is not
          -- blocked. Its final reconciliation runs in bounded slices of whole dependency units inside this same
          -- build; every slice is within the UNCHANGED measured envelope and the 100-Timesheet preview bound, so
          -- each transaction's work stays bounded. Publication still happens once, after the last slice.
          IF v_scale_blocked AND v_slice_possible THEN
            v_slice_bound:=LEAST(100,(v_envelope->>'relevant_timesheet_count')::integer,
              (v_envelope->>'dependency_node_count')::integer);
            SELECT COALESCE(max(unit_row.unit_size),0)::integer,count(*)::integer
            INTO v_slice_max_unit,v_slice_unit_count
            FROM (SELECT count(*) AS unit_size FROM private.banking_pay_workbench_economic_build_scope unit_scope
              WHERE unit_scope.build_id=v_build_id AND unit_scope.closure_status='SEALED'
              GROUP BY unit_scope.dependency_unit_key) unit_row;
            IF v_slice_bound IS NULL OR v_slice_bound<1 OR v_slice_max_unit>v_slice_bound OR v_slice_unit_count<1 THEN
              v_scale_block_reason:='DEPENDENCY_UNIT_OUTSIDE_MEASURED_ENVELOPE';
            ELSE
              FOR v_slice_unit IN
                SELECT count(*)::integer AS unit_size
                FROM private.banking_pay_workbench_economic_build_scope unit_scope
                WHERE unit_scope.build_id=v_build_id AND unit_scope.closure_status='SEALED'
                GROUP BY unit_scope.dependency_unit_key
                ORDER BY min(unit_scope.stable_ordinal)
              LOOP
                IF v_slice_rows=0 OR v_slice_rows+v_slice_unit.unit_size>v_slice_bound THEN
                  v_slice_count:=v_slice_count+1;
                  v_slice_rows:=0;
                END IF;
                v_slice_rows:=v_slice_rows+v_slice_unit.unit_size;
              END LOOP;
              v_scale_blocked:=false;
              v_slice_plan:=jsonb_build_object(
                'contract','BANKING_PAY_RECONCILE_SLICING_V1','reason','VECTOR_OUTSIDE_MEASURED_ENVELOPE',
                'envelope_version',v_envelope_version,'slice_bound',v_slice_bound,'slice_count',v_slice_count,
                'unit_count',v_slice_unit_count,'max_unit_timesheet_count',v_slice_max_unit,
                'relevant_timesheet_count',(v_vector->>'relevant_timesheet_count')::bigint,
                'dependency_node_count',(v_vector->>'dependency_node_count')::bigint,
                'next_after_unit_ordinal',0,'slices_completed',0,'reconciled_timesheet_count',0,
                'prior_recovery_headroom_ex',0,'prior_ordinary_positive_headroom_ex',0,
                'observed_finance_effect_count',0,'publication','ONCE_AFTER_FINAL_SLICE',
                'planned_at_utc',clock_timestamp());
            END IF;
          END IF;
        END IF;
        IF v_scale_blocked THEN
          UPDATE private.banking_pay_workbench_economic_builds SET
            status='BLOCKED_UNVALIDATED_RECONCILIATION_SCALE',complexity_vector_json=v_vector,
            envelope_version=v_envelope_version,envelope_snapshot_json=COALESCE(v_envelope,'{}'::jsonb),
            envelope_evidence_json=COALESCE(v_envelope_evidence,'{}'::jsonb),
            attestation_json=attestation_json||jsonb_build_object(
              'reconciliation_scale_block',jsonb_build_object(
                'reason',COALESCE(v_scale_block_reason,'UNVALIDATED_RECONCILIATION_SCALE'),
                'envelope_version',v_envelope_version
              )
            ),
            fact_cursor_json=v_next||jsonb_build_object('terminal',true),updated_at_utc=clock_timestamp()
          WHERE id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','WORKSPACE_FACT',
            'stage_status','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE','has_more',false,
            'continuation_enqueued',false,'next_action','SCALE_EVIDENCE_REQUIRED','complexity_vector',v_vector);
        END IF;
        v_next:=jsonb_build_object('cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
          'build_id',v_build_id,'candidate_id',p_candidate_id,
          'captured_candidate_generation',v_build.captured_candidate_generation,
          'captured_source_change_seq',v_build.source_change_seq);
        UPDATE private.banking_pay_workbench_economic_builds SET status='READY_FOR_RECONCILIATION',
          private_stage='RECONCILE_EXECUTE',fact_cursor_json=jsonb_build_object(
            'cursor_kind','WORKSPACE_FACT','cursor_version',2,'terminal',true,'build_id',v_build_id),
          complexity_vector_json=v_vector,envelope_version=v_envelope_version,
          envelope_snapshot_json=v_envelope,envelope_evidence_json=v_envelope_evidence,
          attestation_json=COALESCE(attestation_json,'{}'::jsonb)||CASE WHEN v_slice_plan IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('reconcile_slicing',v_slice_plan) END,
          ready_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      END IF;
    END IF;
    IF (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id)='WORKSPACE_FACT' THEN
      UPDATE private.banking_pay_workbench_economic_builds SET fact_cursor_json=v_next,
        updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    END IF;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage',
      (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'stage_status','PREPARING','has_more',true,'continuation_enqueued',false,
      'next_cursor_json',v_next,'next_action',
      (SELECT private_stage FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
      'page_fact_count',v_page_count,'page_digest',v_page_digest);
  END IF;

  IF v_stage='RECONCILE_EXECUTE' THEN
    UPDATE private.banking_pay_workbench_economic_builds SET status='RECONCILING',updated_at_utc=clock_timestamp()
    WHERE id=v_build_id AND status='READY_FOR_RECONCILIATION' AND private_stage='RECONCILE_EXECUTE';
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE' USING ERRCODE='40001'; END IF;
    -- A28: a sliced build chooses its next slice (whole dependency units after the last reconciled unit, up to
    -- the plan's bound) before the slice's effect-plan capture. The execute call of the same slice reuses it.
    v_slice_plan:=v_build.attestation_json->'reconcile_slicing';
    IF jsonb_typeof(v_slice_plan)='object'
       AND COALESCE((v_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE THEN
      v_slice_bound:=(v_slice_plan->>'slice_bound')::integer;
      v_slice_after:=COALESCE((v_slice_plan->>'next_after_unit_ordinal')::bigint,0);
      v_slice_through:=NULL;
      v_slice_rows:=0;
      v_slice_unit_count:=0;
      FOR v_slice_unit IN
        SELECT min(unit_scope.stable_ordinal) AS unit_ordinal,count(*)::integer AS unit_size
        FROM private.banking_pay_workbench_economic_build_scope unit_scope
        WHERE unit_scope.build_id=v_build_id AND unit_scope.closure_status='SEALED'
        GROUP BY unit_scope.dependency_unit_key
        HAVING min(unit_scope.stable_ordinal)>v_slice_after
        ORDER BY min(unit_scope.stable_ordinal)
      LOOP
        EXIT WHEN v_slice_rows>0 AND v_slice_rows+v_slice_unit.unit_size>v_slice_bound;
        v_slice_rows:=v_slice_rows+v_slice_unit.unit_size;
        v_slice_unit_count:=v_slice_unit_count+1;
        v_slice_through:=v_slice_unit.unit_ordinal;
      END LOOP;
      IF v_slice_rows<1 OR v_slice_rows>v_slice_bound OR v_slice_bound>100 THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SLICE_INVALID' USING ERRCODE='23514',
          DETAIL=jsonb_build_object('build_id',v_build_id,'after',v_slice_after,'rows',v_slice_rows,'bound',v_slice_bound)::text;
      END IF;
      v_slice_final:=NOT EXISTS(
        SELECT 1 FROM private.banking_pay_workbench_economic_build_scope later_scope
        WHERE later_scope.build_id=v_build_id AND later_scope.closure_status='SEALED'
          AND later_scope.stable_ordinal>v_slice_through
          AND NOT EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope earlier_unit
            WHERE earlier_unit.build_id=v_build_id AND earlier_unit.closure_status='SEALED'
              AND earlier_unit.dependency_unit_key=later_scope.dependency_unit_key
              AND earlier_unit.stable_ordinal<=v_slice_through));
      v_slice_current:=jsonb_build_object('index',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
        'after_unit_ordinal',v_slice_after,'through_unit_ordinal',v_slice_through,
        'timesheet_count',v_slice_rows,'unit_count',v_slice_unit_count,'final',v_slice_final,
        'chosen_at_utc',clock_timestamp());
      UPDATE private.banking_pay_workbench_economic_builds
      SET attestation_json=jsonb_set(attestation_json,'{reconcile_slicing,current}',v_slice_current,true),
          updated_at_utc=clock_timestamp()
      WHERE id=v_build_id AND status='RECONCILING';
      SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
    END IF;
    SELECT upper(NULLIF(btrim(to_jsonb(candidate_row)->>'pay_method'),'')) INTO v_candidate_pay_method
    FROM public.candidates candidate_row WHERE candidate_row.id=p_candidate_id;
    v_actor_user_id:=COALESCE(NULLIF(v_payload->>'actor_user_id','')::uuid,v_session.actor_user_id);
    IF COALESCE((v_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS NOT TRUE THEN
      BEGIN
        PERFORM set_config('cloudtms.pay_workbench_effect_capture_mode','capture',true);
        v_sync_result:=public.pay_sync_overpayments_from_preview(
          v_session.pay_date,v_session.week_ending_cutoff,v_actor_user_id,v_candidate_pay_method,
          ARRAY[p_candidate_id],COALESCE(v_payload->'mismatch_choices','{}'::jsonb),
          NULLIF(v_payload->>'client_filter_single','')::uuid,NULL,NULL
        );
        v_effect_plan:=COALESCE(v_sync_result->'captured_effects','[]'::jsonb);
        v_capture_timing_json:=CASE
          WHEN jsonb_typeof(v_sync_result->'_internal_reconcile_timing')='object'
            THEN v_sync_result->'_internal_reconcile_timing'
          ELSE '{}'::jsonb
        END;
        IF jsonb_typeof(v_effect_plan)<>'array' THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CAPTURE_INVALID' USING ERRCODE='23514';
        END IF;
        RAISE EXCEPTION 'PAY_WORKBENCH_EFFECT_PLAN_CAPTURE_ROLLBACK' USING ERRCODE='PZ001';
      EXCEPTION WHEN SQLSTATE 'PZ001' THEN
        NULL;
      END;
      -- Generated row identities and audit timestamps are not economic authority.
      -- INSERT effects are normalised, deterministically ordered, and assigned a
      -- build-owned plan identity before the durable plan is sealed.
      WITH ordered AS (
        SELECT raw_effect.value AS raw_effect,raw_effect.ordinality,
          row_number() OVER(ORDER BY raw_effect.value::text,raw_effect.ordinality) AS plan_ordinal
        FROM jsonb_array_elements(COALESCE(v_effect_plan,'[]'::jsonb))
          WITH ORDINALITY raw_effect(value,ordinality)
      ), identified AS (
        SELECT ordered.*,
          CASE WHEN ordered.raw_effect->>'operation'='INSERT'
            THEN (md5(v_build_id::text||':EXPECTED_FINANCE_EFFECT:'||ordered.plan_ordinal::text))::uuid
            ELSE NULLIF(ordered.raw_effect->>'source_id','')::uuid END AS logical_source_id
        FROM ordered
      ), normalised AS (
        SELECT identified.plan_ordinal,
          identified.raw_effect||jsonb_build_object(
            'source_id',identified.logical_source_id,
            'finance_case_id',CASE
              WHEN identified.raw_effect->>'operation'='INSERT'
               AND identified.raw_effect->>'relation_name'='pay_advances'
                THEN identified.logical_source_id
              WHEN NULLIF(identified.raw_effect->>'finance_case_id','') IS NULL THEN NULL
              ELSE COALESCE((SELECT parent.logical_source_id FROM identified parent
                WHERE parent.raw_effect->>'operation'='INSERT'
                  AND parent.raw_effect->>'relation_name'='pay_advances'
                  AND NULLIF(parent.raw_effect->>'source_id','')::uuid=
                    NULLIF(identified.raw_effect->>'finance_case_id','')::uuid),
                NULLIF(identified.raw_effect->>'finance_case_id','')::uuid) END,
            'finance_component_id',CASE
              WHEN identified.raw_effect->>'operation'='INSERT'
               AND identified.raw_effect->>'relation_name'='pay_finance_case_components'
                THEN identified.logical_source_id
              WHEN NULLIF(identified.raw_effect->>'finance_component_id','') IS NULL THEN NULL
              ELSE COALESCE((SELECT parent.logical_source_id FROM identified parent
                WHERE parent.raw_effect->>'operation'='INSERT'
                  AND parent.raw_effect->>'relation_name'='pay_finance_case_components'
                  AND NULLIF(parent.raw_effect->>'source_id','')::uuid=
                    NULLIF(identified.raw_effect->>'finance_component_id','')::uuid),
                NULLIF(identified.raw_effect->>'finance_component_id','')::uuid) END
          ) AS effect
        FROM identified
      )
      SELECT COALESCE(jsonb_agg(normalised.effect ORDER BY normalised.plan_ordinal),'[]'::jsonb)
      INTO v_effect_plan FROM normalised;
      v_effect_plan_count:=jsonb_array_length(COALESCE(v_effect_plan,'[]'::jsonb));
      v_effect_plan_digest:=md5(COALESCE(v_effect_plan::text,'[]'));
      DELETE FROM private.banking_pay_workbench_economic_build_facts
      WHERE build_id=v_build_id AND fact_family='EXPECTED_FINANCE_EFFECT';
      INSERT INTO private.banking_pay_workbench_economic_build_facts(build_id,fact_family,natural_key,
        candidate_id,timesheet_id,subject_timesheet_ids,dependency_unit_key,source_relation,source_id,
        finance_case_id,finance_component_id,economic_key_type,economic_key_value,
        source_payload_json,financial_digest,source_ordinal)
      SELECT v_build_id,'EXPECTED_FINANCE_EFFECT',md5('EXPECTED_FINANCE_EFFECT:'||effect.ordinality::text||':'||effect.value::text),
        (effect.value->>'candidate_id')::uuid,NULLIF(effect.value->>'timesheet_id','')::uuid,
        CASE WHEN NULLIF(effect.value->>'timesheet_id','') IS NULL THEN ARRAY[]::uuid[]
          ELSE ARRAY[(effect.value->>'timesheet_id')::uuid] END,'GLOBAL',effect.value->>'relation_name',
        (effect.value->>'source_id')::uuid,
        NULLIF(effect.value->>'finance_case_id','')::uuid,
        NULLIF(effect.value->>'finance_component_id','')::uuid,
        NULLIF(effect.value->>'economic_key_type',''),
        NULLIF(effect.value->>'economic_key_value',''),jsonb_build_object(
          'operation',effect.value->>'operation',
          'expected_before_digest',effect.value->>'expected_before_digest',
          'expected_after_digest',effect.value->>'expected_after_digest'),md5(effect.value::text),effect.ordinality
      FROM jsonb_array_elements(COALESCE(v_effect_plan,'[]'::jsonb)) WITH ORDINALITY effect(value,ordinality);
      UPDATE private.banking_pay_workbench_economic_builds SET status='READY_FOR_RECONCILIATION',
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'effect_plan_sealed',true,'effect_plan_count',v_effect_plan_count,
          'effect_plan_digest',v_effect_plan_digest,'effect_plan_created_at_utc',clock_timestamp(),
          'reconcile_capture_timing_json',v_capture_timing_json),
        updated_at_utc=clock_timestamp() WHERE id=v_build_id AND status='RECONCILING';
      v_next:=jsonb_build_object('cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
        'build_id',v_build_id,'candidate_id',p_candidate_id,'reconcile_phase','EXECUTE',
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,'effect_plan_digest',v_effect_plan_digest);
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','RECONCILE_EXECUTE',
        'stage_status','EFFECT_PLAN_READY','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',v_next,'next_action','RECONCILE_EXECUTE',
        'effect_plan_count',v_effect_plan_count,'effect_plan_digest',v_effect_plan_digest);
    END IF;
    SELECT count(*)::integer,md5(COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id',fact.candidate_id,'timesheet_id',fact.timesheet_id,
      'relation_name',fact.source_relation,'operation',fact.source_payload_json->>'operation',
      'source_id',fact.source_id,'finance_case_id',fact.finance_case_id,
      'finance_component_id',fact.finance_component_id,
      'economic_key_type',fact.economic_key_type,'economic_key_value',fact.economic_key_value,
      'expected_before_digest',NULLIF(fact.source_payload_json->>'expected_before_digest',''),
      'expected_after_digest',NULLIF(fact.source_payload_json->>'expected_after_digest','')
      ) ORDER BY fact.source_ordinal),'[]'::jsonb)::text)
    INTO v_effect_plan_count,v_effect_plan_digest
    FROM private.banking_pay_workbench_economic_build_facts fact
    WHERE fact.build_id=v_build_id AND fact.fact_family='EXPECTED_FINANCE_EFFECT';
    IF v_effect_plan_count IS DISTINCT FROM
         COALESCE((v_build.attestation_json->>'effect_plan_count')::integer,0)
       OR v_effect_plan_digest IS DISTINCT FROM v_build.attestation_json->>'effect_plan_digest'
       OR NULLIF(v_cursor->>'effect_plan_digest','') IS DISTINCT FROM
          v_build.attestation_json->>'effect_plan_digest' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_PLAN_MISMATCH'
        USING ERRCODE='23514';
    END IF;
    v_sync_result:=public.pay_sync_overpayments_from_preview(
      v_session.pay_date,v_session.week_ending_cutoff,v_actor_user_id,v_candidate_pay_method,
      ARRAY[p_candidate_id],COALESCE(v_payload->'mismatch_choices','{}'::jsonb),
      NULLIF(v_payload->>'client_filter_single','')::uuid,NULL,NULL
    );
    -- A28: a non-final slice returns the build to READY_FOR_RECONCILIATION with its lines staged privately.
    -- Nothing is published; the next slice continues in a new bounded RPC.
    IF jsonb_typeof(v_build.attestation_json->'reconcile_slicing')='object' AND EXISTS(
         SELECT 1 FROM private.banking_pay_workbench_economic_builds sliced_build
         WHERE sliced_build.id=v_build_id AND sliced_build.status='READY_FOR_RECONCILIATION'
           AND sliced_build.private_stage='RECONCILE_EXECUTE') THEN
      SELECT attestation_json->'reconcile_slicing' INTO v_slice_plan
      FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
      v_next:=jsonb_build_object('cursor_kind','RECONCILE_EXECUTE','cursor_version',1,
        'build_id',v_build_id,'candidate_id',p_candidate_id,'reconcile_phase','SLICE_CAPTURE',
        'slice_index',COALESCE((v_slice_plan->>'slices_completed')::integer,0)+1,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','RECONCILE_EXECUTE',
        'stage_status','SLICE_RECONCILED','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',v_next,'next_action','RECONCILE_EXECUTE',
        'slices_completed',v_slice_plan->'slices_completed','slice_count',v_slice_plan->'slice_count',
        'last_slice',v_slice_plan->'last_slice');
    END IF;
    SELECT canonical_count<=25 INTO v_publish_now FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id;
    IF NOT v_publish_now THEN
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','SOURCE_PUBLISH',
        'stage_status','RECONCILED','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',(SELECT publication_cursor_json FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id),
        'next_action','SOURCE_PUBLISH','sync_result',v_sync_result);
    END IF;
    v_stage:='SOURCE_PUBLISH';
  END IF;

  IF v_stage='SOURCE_PUBLISH' THEN
    SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds WHERE id=v_build_id FOR UPDATE;
    IF v_build.status NOT IN ('RECONCILED','PUBLISHING') OR v_build.private_stage<>'SOURCE_PUBLISH'
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_canonical_stage_lines
         WHERE build_id=v_build_id AND stage_status<>'VERIFIED' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_NOT_READY' USING ERRCODE='23514';
    END IF;
    UPDATE private.banking_pay_workbench_economic_builds SET status='PUBLISHING',updated_at_utc=clock_timestamp()
    WHERE id=v_build_id;
    v_source_publication_id:=CASE WHEN COALESCE((
      SELECT setting.banking_pay_source_publication_identity_write_v1_enabled
      FROM public.settings_defaults AS setting WHERE setting.id=1
    ),false) THEN private.pay_workbench_source_publication_identity_v1(
      p_session_id,p_candidate_id,v_build.session_version,
      v_build.source_change_seq,v_build.source_build_run_id
    ) ELSE NULL::uuid END;
    PERFORM 1 FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
    ORDER BY source_ordinal FOR UPDATE;

    SELECT count(*)::integer,
           md5(COALESCE(string_agg(md5(source_row_json::text),'' ORDER BY source_ordinal),''))
    INTO v_existing_publication_count,v_existing_publication_digest
    FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id
      AND session_version=v_build.session_version
      AND source_change_seq=v_build.source_change_seq
      AND source_build_run_id=v_build.source_build_run_id
      AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id
      AND status IN ('DIRTY','CURRENT','SUPERSEDED');

    IF v_existing_publication_count>0 THEN
      IF v_existing_publication_count IS DISTINCT FROM v_build.canonical_count
         OR v_existing_publication_digest IS DISTINCT FROM v_build.canonical_digest THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_REPLAY_CONFLICT'
          USING ERRCODE='23514',DETAIL=jsonb_build_object(
            'code','PAY_WORKBENCH_CANONICAL_PUBLICATION_REPLAY_CONFLICT',
            'build_id',v_build_id,'source_publication_id',v_source_publication_id,
            'expected_count',v_build.canonical_count,'actual_count',v_existing_publication_count,
            'expected_digest',v_build.canonical_digest,'actual_digest',v_existing_publication_digest
          )::text;
      END IF;
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='SUPERSEDED',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
        AND source_publication_id IS DISTINCT FROM v_source_publication_id;
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='CURRENT',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id
        AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id
        AND source_build_run_id=v_build.source_build_run_id
        AND status<>'CURRENT';
      v_published_count:=v_existing_publication_count;
    ELSE
      UPDATE public.banking_pay_workbench_candidate_source_lines
      SET status='SUPERSEDED',updated_at_utc=clock_timestamp()
      WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT';
      INSERT INTO public.banking_pay_workbench_candidate_source_lines(
      session_id,candidate_id,session_version,source_change_seq,source_build_run_id,source_publication_id,
      source_ordinal,line_key,parent_line_key,split_suffix,timesheet_id,section,
      source_row_json,economic_key_json,contract_json,pay_channel_scope,refresh_scope_kind,status
    ) SELECT session_id,candidate_id,session_version,source_change_seq,source_build_run_id,
      v_source_publication_id,
      source_ordinal,line_key,parent_line_key,split_suffix,timesheet_id,section,
      source_row_json,economic_key_json,contract_json,pay_channel_scope,refresh_scope_kind,'CURRENT'
    FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=v_build_id
    ORDER BY source_ordinal;
      GET DIAGNOSTICS v_published_count=ROW_COUNT;
    END IF;
    SELECT md5(COALESCE(string_agg(md5(source_row_json::text),'' ORDER BY source_ordinal),''))
    INTO v_published_digest FROM public.banking_pay_workbench_candidate_source_lines
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id AND status='CURRENT'
      AND source_build_run_id=v_build.source_build_run_id
      AND source_publication_id IS NOT DISTINCT FROM v_source_publication_id;
    IF v_published_count<>v_build.canonical_count OR v_published_digest IS DISTINCT FROM v_build.canonical_digest THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_PUBLICATION_DIGEST_MISMATCH' USING ERRCODE='23514';
    END IF;
    UPDATE public.banking_pay_workbench_session_candidate_state SET status='READY',
      source_change_seq=v_build.source_change_seq,session_version=v_build.session_version,
      pending_job_id=NULL,last_error_json='{}'::jsonb,last_recomputed_at_utc=clock_timestamp(),
      updated_at_utc=clock_timestamp()
    WHERE session_id=p_session_id AND candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_timesheet_scope_state state_row
    SET economic_state=CASE WHEN EXISTS(
        SELECT 1
        FROM (
          SELECT fact.economic_key_type,fact.economic_key_value,
            ROUND(SUM(COALESCE(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
            ROUND(SUM(COALESCE(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat,
            ROUND(SUM(COALESCE(fact.reserved_source_amount,0)),2) AS reserved_source_amount,
            -- S-08 D4: only an OPEN finance case keeps a Timesheet LIVE.  A cleared or
            -- written-off case (e.g. a repaid advance) must not keep it unsettled for ever.
            bool_or(fact.finance_case_id IS NOT NULL AND EXISTS(
              SELECT 1 FROM public.pay_advances open_case
              WHERE open_case.id=fact.finance_case_id
                AND open_case.cleared_at_utc IS NULL AND open_case.written_off_at_utc IS NULL)) AS has_finance_case
          FROM private.banking_pay_workbench_economic_build_facts fact
          WHERE fact.build_id=v_build_id
            AND state_row.timesheet_id=ANY(fact.subject_timesheet_ids)
            AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY')
          GROUP BY fact.economic_key_type,fact.economic_key_value
        ) authority
        WHERE authority.truth_ex_vat IS DISTINCT FROM authority.baseline_ex_vat
          OR authority.reserved_source_amount<>0 OR authority.has_finance_case
      ) THEN 'LIVE' ELSE 'CLOSED' END,
      evaluated_generation=state_row.dirty_generation,
      current_input_fingerprint=scope_row.captured_input_fingerprint,
      evaluated_input_fingerprint=scope_row.captured_input_fingerprint,
      current_build_id=NULL,last_evaluated_at_utc=clock_timestamp(),
      closed_at_utc=CASE WHEN EXISTS(
        SELECT 1
        FROM (
          SELECT fact.economic_key_type,fact.economic_key_value,
            ROUND(SUM(COALESCE(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
            ROUND(SUM(COALESCE(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat,
            ROUND(SUM(COALESCE(fact.reserved_source_amount,0)),2) AS reserved_source_amount,
            -- S-08 D4: only an OPEN finance case keeps a Timesheet LIVE.  A cleared or
            -- written-off case (e.g. a repaid advance) must not keep it unsettled for ever.
            bool_or(fact.finance_case_id IS NOT NULL AND EXISTS(
              SELECT 1 FROM public.pay_advances open_case
              WHERE open_case.id=fact.finance_case_id
                AND open_case.cleared_at_utc IS NULL AND open_case.written_off_at_utc IS NULL)) AS has_finance_case
          FROM private.banking_pay_workbench_economic_build_facts fact
          WHERE fact.build_id=v_build_id
            AND state_row.timesheet_id=ANY(fact.subject_timesheet_ids)
            AND fact.fact_family IN ('ENTITLEMENT_COMPONENT','RESERVATION_COMPONENT','FINANCE_CASE_IDENTITY','FINANCE_COMPONENT_IDENTITY')
          GROUP BY fact.economic_key_type,fact.economic_key_value
        ) authority
        WHERE authority.truth_ex_vat IS DISTINCT FROM authority.baseline_ex_vat
          OR authority.reserved_source_amount<>0 OR authority.has_finance_case
      ) THEN NULL ELSE clock_timestamp() END,updated_at_utc=clock_timestamp()
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=v_build_id AND state_row.timesheet_id=scope_row.timesheet_id;
    UPDATE private.banking_pay_workbench_candidate_scope_registry SET initialisation_status='READY',
      evaluated_generation=dirty_generation,current_build_id=NULL,last_evaluated_at_utc=clock_timestamp(),
      initialised_at_utc=COALESCE(initialised_at_utc,clock_timestamp()),failure_json='{}'::jsonb,
      updated_at_utc=clock_timestamp() WHERE candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds SET status='COMPLETE',private_stage='COMPLETE',
      publication_cursor_json=jsonb_build_object('cursor_kind','SOURCE_PUBLISH','cursor_version',1,
        'terminal',true,'published_count',v_published_count,'published_digest',v_published_digest),
      completed_at_utc=clock_timestamp(),cleanup_not_before_utc=clock_timestamp()+interval '7 days',
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','COMPLETE',
      'stage_status','COMPLETE','has_more',false,'continuation_enqueued',false,
      'next_action','COMPLETE','published_count',v_published_count,'published_digest',v_published_digest);
  END IF;

  IF v_stage='BUILD_CLEANUP' THEN
    v_cleanup_kind:=COALESCE(NULLIF(v_cursor->>'cleanup_kind',''),'CANONICAL_STAGE');
    IF v_build.status<>'CLEANING' OR v_build.cleanup_not_before_utc IS NULL
       OR clock_timestamp()<v_build.cleanup_not_before_utc
       OR v_registry.current_build_id IS NOT DISTINCT FROM v_build_id
       OR EXISTS(SELECT 1 FROM public.banking_pay_workbench_jobs cleanup_job
         WHERE cleanup_job.economic_build_id=v_build_id
           AND cleanup_job.id<>(SELECT job_id FROM private.banking_pay_workbench_stage_attempts WHERE id=v_attempt_id)
           AND cleanup_job.status IN ('QUEUED','RUNNING') LIMIT 1)
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts cleanup_attempt
         WHERE cleanup_attempt.build_id=v_build_id AND cleanup_attempt.id<>v_attempt_id
           AND cleanup_attempt.attempt_status='STARTED' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CLEANUP_BUILD_PROTECTED' USING ERRCODE='55006';
    END IF;
    IF v_cleanup_kind='CANONICAL_STAGE' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_canonical_stage_lines
        WHERE build_id=v_build_id ORDER BY source_ordinal LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_canonical_stage_lines row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='FACT_PAGES'; END IF;
    ELSIF v_cleanup_kind='FACT_PAGES' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_fact_pages
        WHERE build_id=v_build_id ORDER BY id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_fact_pages row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='FACTS'; END IF;
    ELSIF v_cleanup_kind='FACTS' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_facts
        WHERE build_id=v_build_id ORDER BY fact_family,natural_key LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_facts row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='SCOPE'; END IF;
    ELSIF v_cleanup_kind='SCOPE' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=v_build_id ORDER BY timesheet_id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_economic_build_scope row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='ATTEMPTS'; END IF;
    ELSIF v_cleanup_kind='ATTEMPTS' THEN
      WITH doomed AS (SELECT ctid FROM private.banking_pay_workbench_stage_attempts
        WHERE build_id=v_build_id AND id<>v_attempt_id ORDER BY id LIMIT LEAST(v_limit,500))
      DELETE FROM private.banking_pay_workbench_stage_attempts row USING doomed WHERE row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_cleanup_count=ROW_COUNT;
      IF v_cleanup_count<LEAST(v_limit,500) THEN v_cleanup_kind:='HEADER_FINALISE'; END IF;
    ELSIF v_cleanup_kind='HEADER_FINALISE' THEN
      IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_canonical_stage_lines WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_fact_pages WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_facts WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope WHERE build_id=v_build_id LIMIT 1)
         OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts
           WHERE build_id=v_build_id AND id<>v_attempt_id LIMIT 1) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CLEANUP_CHILDREN_REMAIN' USING ERRCODE='23514';
      END IF;
      v_cleanup_kind:='COMPLETE';
      v_cleanup_count:=0;
    ELSIF v_cleanup_kind<>'COMPLETE' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;
    v_next:=jsonb_build_object('cursor_kind','BUILD_CLEANUP','cursor_version',1,
      'build_id',v_build_id,'candidate_id',p_candidate_id,'cleanup_kind',v_cleanup_kind,
      'deleted_count',v_cleanup_count,'terminal',v_cleanup_kind='COMPLETE');
    UPDATE private.banking_pay_workbench_economic_builds SET cleanup_cursor_json=v_next,
      status=CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE status END,
      private_stage=CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE private_stage END,
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','BUILD_CLEANUP',
      'stage_status',CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE 'CLEANING' END,
      'has_more',v_cleanup_kind<>'COMPLETE','continuation_enqueued',false,
      'next_cursor_json',v_next,'next_action',CASE WHEN v_cleanup_kind='COMPLETE' THEN 'COMPLETE' ELSE 'BUILD_CLEANUP' END,
      'deleted_count',v_cleanup_count);
  END IF;

  IF v_stage='BOOTSTRAP_DISCOVERY' THEN
    v_bootstrap_id:=NULLIF(v_cursor->>'bootstrap_id','')::uuid;
    v_bootstrap_stream:=upper(COALESCE(NULLIF(v_cursor->>'bootstrap_stream',''),v_registry.bootstrap_stream));
    v_bootstrap_last_key:=NULLIF(v_cursor->>'last_source_key','');
    IF v_bootstrap_id IS NULL OR v_bootstrap_id IS DISTINCT FROM v_registry.bootstrap_id
       OR v_registry.initialisation_status NOT IN ('DISCOVERING','CLASSIFYING') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_bootstrap_page_v1(
      source_key text PRIMARY KEY,
      timesheet_id uuid NULL
    ) ON COMMIT DROP;
    TRUNCATE pg_temp._bpay_wb_bootstrap_page_v1;

    IF v_bootstrap_stream='TIMESHEETS_TSFIN' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'TIMESHEET:'||timesheet_row.timesheet_id::text row_key,timesheet_row.timesheet_id
        FROM public.timesheets timesheet_row
        JOIN public.contracts contract_row ON contract_row.id=timesheet_row.contract_id
        WHERE contract_row.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'TSFIN:'||financial.id::text row_key,financial.timesheet_id
        FROM public.timesheets_financials financial
        WHERE financial.candidate_id=p_candidate_id AND financial.is_current
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='BATCH_ARTIFACTS';
    ELSIF v_bootstrap_stream='BATCH_ARTIFACTS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'ITEM:'||item.id::text row_key,item.timesheet_id
        FROM public.pay_batch_items item
        JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=item.pay_batch_candidate_id
        WHERE batch_candidate.candidate_id=p_candidate_id AND item.timesheet_id IS NOT NULL
        UNION ALL
        SELECT 'SNAPSHOT:'||snapshot.id::text,snapshot.timesheet_id
        FROM public.pay_batch_timesheet_snapshots snapshot
        WHERE snapshot.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='CORRECTIONS';
    ELSIF v_bootstrap_stream='CORRECTIONS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'CORRECTION:'||correction.id::text,correction.timesheet_id
      FROM public.pay_payment_correction_items correction
      WHERE correction.candidate_id=p_candidate_id AND correction.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'CORRECTION:'||correction.id::text>v_bootstrap_last_key)
      ORDER BY correction.id LIMIT 251;
      v_bootstrap_next_stream:='FINANCE';
    ELSIF v_bootstrap_stream='FINANCE' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'ADVANCE:'||finance_case.id::text row_key,finance_case.linked_timesheet_id timesheet_id
        FROM public.pay_advances finance_case WHERE finance_case.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'COMPONENT:'||component.id::text,component.linked_timesheet_id
        FROM public.pay_finance_case_components component WHERE component.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'EVENT:'||event.id::text,component.linked_timesheet_id
        FROM public.pay_finance_case_events event
        JOIN public.pay_advances finance_case ON finance_case.id=event.finance_case_id
        LEFT JOIN public.pay_finance_case_components component ON component.id=event.finance_component_id
        WHERE finance_case.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='RESERVATIONS';
    ELSIF v_bootstrap_stream='RESERVATIONS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'RESERVATION:'||reservation.id::text,COALESCE(item.timesheet_id,component.linked_timesheet_id)
      FROM public.pay_advance_reservations reservation
      LEFT JOIN public.pay_batch_candidates batch_candidate ON batch_candidate.id=reservation.pay_batch_candidate_id
      LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
      LEFT JOIN public.pay_finance_case_components component ON component.id=reservation.finance_component_id
      WHERE COALESCE(batch_candidate.candidate_id,component.candidate_id)=p_candidate_id
        AND (v_bootstrap_last_key IS NULL OR 'RESERVATION:'||reservation.id::text>v_bootstrap_last_key)
      ORDER BY reservation.id LIMIT 251;
      v_bootstrap_next_stream:='OVERRIDES_ADJUSTMENTS';
    ELSIF v_bootstrap_stream='OVERRIDES_ADJUSTMENTS' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT row_key,timesheet_id FROM (
        SELECT 'OVERRIDE:'||override_row.id::text row_key,override_row.timesheet_id
        FROM public.timesheet_payment_overrides override_row WHERE override_row.candidate_id=p_candidate_id
        UNION ALL
        SELECT 'ADJUSTMENT:'||adjustment.id::text,adjustment.timesheet_id
        FROM public.ts_pay_adjustments adjustment WHERE adjustment.candidate_id=p_candidate_id
      ) rows WHERE v_bootstrap_last_key IS NULL OR row_key>v_bootstrap_last_key
      ORDER BY row_key LIMIT 251;
      v_bootstrap_next_stream:='SNOOZES';
    ELSIF v_bootstrap_stream='SNOOZES' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'SNOOZE:'||snooze.id::text,snooze.timesheet_id
      FROM public.pay_item_snoozes snooze
      WHERE snooze.candidate_id=p_candidate_id AND snooze.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'SNOOZE:'||snooze.id::text>v_bootstrap_last_key)
      ORDER BY snooze.id LIMIT 251;
      v_bootstrap_next_stream:='CURRENT_SOURCE';
    ELSIF v_bootstrap_stream='CURRENT_SOURCE' THEN
      INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1
      SELECT 'SOURCE:'||source_row.id::text,source_row.timesheet_id
      FROM public.banking_pay_workbench_candidate_source_lines source_row
      WHERE source_row.candidate_id=p_candidate_id AND source_row.status IN ('CURRENT','DIRTY')
        AND source_row.timesheet_id IS NOT NULL
        AND (v_bootstrap_last_key IS NULL OR 'SOURCE:'||source_row.id::text>v_bootstrap_last_key)
      ORDER BY source_row.id LIMIT 251;
      v_bootstrap_next_stream:='SCOPE_CLOSURE';
    ELSIF v_bootstrap_stream='CLASSIFY_UNITS' THEN
      v_bootstrap_classification_phase:=upper(COALESCE(NULLIF(v_cursor->>'classification_phase',''),'EVIDENCE'));
      v_bootstrap_unit_key:=NULLIF(v_cursor->>'dependency_unit_key','');
      v_bootstrap_last_unit_key:=NULLIF(v_cursor->>'last_dependency_unit_key','');
      v_bootstrap_last_ordinal:=GREATEST(COALESCE((v_cursor->>'last_stable_ordinal')::bigint,0),0);
      v_bootstrap_unit_relevant:=COALESCE((v_cursor->>'unit_financially_relevant')::boolean,false);
      v_bootstrap_raw_current_count:=GREATEST(COALESCE((v_cursor->>'raw_current_occurrence_count')::bigint,0),0);
      v_bootstrap_resolved_current_count:=GREATEST(COALESCE((v_cursor->>'resolved_current_occurrence_count')::bigint,0),0);
      v_bootstrap_raw_baseline_count:=GREATEST(COALESCE((v_cursor->>'raw_baseline_occurrence_count')::bigint,0),0);
      v_bootstrap_resolved_baseline_count:=GREATEST(COALESCE((v_cursor->>'resolved_baseline_occurrence_count')::bigint,0),0);

      IF v_bootstrap_classification_phase='EVIDENCE' THEN
        IF v_bootstrap_unit_key IS NULL THEN
          SELECT scope_row.dependency_unit_key INTO v_bootstrap_unit_key
          FROM private.banking_pay_workbench_economic_build_scope scope_row
          WHERE scope_row.build_id=v_build_id AND scope_row.closure_status='SEALED'
            AND (v_bootstrap_last_unit_key IS NULL
              OR scope_row.dependency_unit_key>v_bootstrap_last_unit_key)
          ORDER BY scope_row.dependency_unit_key LIMIT 1;
        END IF;
        IF v_bootstrap_unit_key IS NULL THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','RESET_FACT_PAGES',
            'last_source_key',NULL,'build_id',v_build_id,'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
          UPDATE private.banking_pay_workbench_candidate_scope_registry
          SET bootstrap_stream='RESET_FACT_PAGES',bootstrap_cursor_json=v_next,
              updated_at_utc=clock_timestamp()
          WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
          -- The sealed seed cursor remains immutable. Bootstrap continuation is
          -- owned by the registry's dedicated bootstrap_cursor_json.
          UPDATE private.banking_pay_workbench_economic_builds
          SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
          RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
            'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
            'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
            'next_action','BOOTSTRAP_DISCOVERY','classification_phase','RESET_FACT_PAGES');
        END IF;

        INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1(source_key,timesheet_id)
        SELECT lpad(scope_row.stable_ordinal::text,20,'0'),scope_row.timesheet_id
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id
          AND scope_row.dependency_unit_key=v_bootstrap_unit_key
          AND scope_row.stable_ordinal>v_bootstrap_last_ordinal
        ORDER BY scope_row.stable_ordinal LIMIT 26;
        SELECT count(*)>25 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
        SELECT count(*)::integer,COALESCE(max(source_key)::bigint,v_bootstrap_last_ordinal)
        INTO v_bootstrap_page_count,v_bootstrap_last_ordinal
        FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page;
        SELECT EXISTS(
          SELECT 1
          FROM (SELECT timesheet_id FROM pg_temp._bpay_wb_bootstrap_page_v1
            ORDER BY source_key LIMIT 25) page
          WHERE EXISTS(SELECT 1 FROM public.timesheets_financials financial
              WHERE financial.timesheet_id=page.timesheet_id
                AND financial.candidate_id=p_candidate_id AND financial.is_current
                AND financial.paid_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines source_row
              WHERE source_row.candidate_id=p_candidate_id
                AND source_row.timesheet_id=page.timesheet_id
                AND source_row.status IN ('CURRENT','DIRTY'))
            OR EXISTS(SELECT 1 FROM public.pay_advances finance_case
              WHERE finance_case.candidate_id=p_candidate_id
                AND finance_case.linked_timesheet_id=page.timesheet_id
                AND finance_case.cleared_at_utc IS NULL
                AND finance_case.written_off_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_finance_case_components component
              WHERE component.candidate_id=p_candidate_id
                AND component.linked_timesheet_id=page.timesheet_id
                AND component.closed_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.timesheet_payment_overrides override_row
              WHERE override_row.candidate_id=p_candidate_id
                AND override_row.timesheet_id=page.timesheet_id
                AND override_row.cleared_at_utc IS NULL
                AND override_row.consumed_at_utc IS NULL
                AND override_row.consumed_by_pay_batch_id IS NULL)
            OR EXISTS(SELECT 1 FROM public.ts_pay_adjustments adjustment
              WHERE adjustment.candidate_id=p_candidate_id
                AND adjustment.timesheet_id=page.timesheet_id
                AND adjustment.paid_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_item_snoozes snooze
              WHERE snooze.candidate_id=p_candidate_id
                AND snooze.timesheet_id=page.timesheet_id
                AND snooze.cleared_at_utc IS NULL)
            OR EXISTS(SELECT 1 FROM public.pay_advance_reservations reservation
              LEFT JOIN public.pay_batch_items item ON item.id=reservation.pay_batch_item_id
              LEFT JOIN public.pay_finance_case_components component
                ON component.id=reservation.finance_component_id
              WHERE COALESCE(item.timesheet_id,component.linked_timesheet_id)=page.timesheet_id
                AND reservation.status NOT IN ('RELEASED','SETTLED'))
            OR EXISTS(
              SELECT 1
              FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
                v_build_id,v_bootstrap_unit_key) component
              WHERE component.timesheet_id=page.timesheet_id
                AND (ROUND(COALESCE(component.truth_ex_vat,0),2)
                      IS DISTINCT FROM ROUND(COALESCE(component.baseline_ex_vat,0),2)
                  OR ROUND(COALESCE(component.truth_inc_vat,0),2)
                      IS DISTINCT FROM ROUND(COALESCE(component.baseline_inc_vat,0),2))
            )
            OR (
              NOT EXISTS(
                SELECT 1
                FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
                  v_build_id,v_bootstrap_unit_key) component
                WHERE component.timesheet_id=page.timesheet_id
              )
              AND (
                EXISTS(SELECT 1
                  FROM private.banking_pay_workbench_economic_build_facts fact
                  WHERE fact.build_id=v_build_id AND fact.timesheet_id=page.timesheet_id
                    AND fact.fact_family IN ('LIVE_ENTITLEMENT_INPUT',
                      'FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
                    AND fact.source_relation<>'UNIT_PROJECTION')
                OR EXISTS(SELECT 1 FROM public.timesheets_financials financial
                  WHERE financial.timesheet_id=page.timesheet_id
                    AND financial.candidate_id=p_candidate_id AND financial.is_current
                    AND ABS(COALESCE(financial.total_pay_ex_vat,0))>0.005)
                OR EXISTS(SELECT 1 FROM public.timesheet_pay_state state
                  WHERE state.timesheet_id=page.timesheet_id
                    AND COALESCE(state.last_settled_snapshot_json,'{}'::jsonb)<>'{}'::jsonb)
              )
            )
          LIMIT 1
        ) INTO v_bootstrap_page_relevant;
        SELECT
          COALESCE(SUM((page.cursor_end_json->>'raw_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family='LIVE_ENTITLEMENT_INPUT'),0),
          COALESCE(SUM((page.cursor_end_json->>'resolved_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family='LIVE_ENTITLEMENT_INPUT'),0),
          COALESCE(SUM((page.cursor_end_json->>'raw_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')),0),
          COALESCE(SUM((page.cursor_end_json->>'resolved_physical_source_count')::bigint)
            FILTER(WHERE page.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')),0),
          COUNT(*)=3
            AND BOOL_AND(page.expected_source_count IS NOT NULL
              AND page.expected_source_count=(page.cursor_end_json->>'raw_physical_source_count')::integer
              AND (page.cursor_end_json->>'raw_physical_source_count')::bigint=
                (page.cursor_end_json->>'resolved_physical_source_count')::bigint
              AND (page.cursor_end_json->>'failed_physical_source_count')::bigint=0
              AND ROUND((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric,2)=
                ROUND((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric,2)
              AND COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false))
        INTO v_bootstrap_raw_current_count,v_bootstrap_resolved_current_count,
          v_bootstrap_raw_baseline_count,v_bootstrap_resolved_baseline_count,
          v_bootstrap_evidence_complete
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key=v_bootstrap_unit_key
          AND page.fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND page.status='COMPLETED' AND page.is_family_final;
        v_bootstrap_unit_relevant:=v_bootstrap_unit_relevant OR v_bootstrap_page_relevant;
        v_bootstrap_evidence_complete:=COALESCE(v_bootstrap_evidence_complete,false)
          AND v_bootstrap_raw_current_count=v_bootstrap_resolved_current_count
          AND v_bootstrap_raw_baseline_count=v_bootstrap_resolved_baseline_count;
        IF v_bootstrap_has_more THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',v_bootstrap_last_ordinal,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        ELSE
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','APPLY','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',0,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        END IF;
      ELSIF v_bootstrap_classification_phase='APPLY' THEN
        IF v_bootstrap_unit_key IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
        END IF;
        SELECT COUNT(*)=3 AND BOOL_AND(
            page.expected_source_count IS NOT NULL
            AND page.expected_source_count=(page.cursor_end_json->>'raw_physical_source_count')::integer
            AND (page.cursor_end_json->>'raw_physical_source_count')::bigint=
              (page.cursor_end_json->>'resolved_physical_source_count')::bigint
            AND (page.cursor_end_json->>'failed_physical_source_count')::bigint=0
            AND ROUND((page.cursor_end_json->>'raw_physical_amount_ex_vat')::numeric,2)=
              ROUND((page.cursor_end_json->>'resolved_physical_amount_ex_vat')::numeric,2)
            AND COALESCE((page.cursor_end_json->>'source_exhausted')::boolean,false))
        INTO v_bootstrap_evidence_complete
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id AND page.dependency_unit_key=v_bootstrap_unit_key
          AND page.fact_family IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
          AND page.status='COMPLETED' AND page.is_family_final;
        v_bootstrap_evidence_complete:=COALESCE(v_bootstrap_evidence_complete,false)
          AND COALESCE((v_cursor->>'evidence_complete')::boolean,false)
          AND v_bootstrap_raw_current_count=v_bootstrap_resolved_current_count
          AND v_bootstrap_raw_baseline_count=v_bootstrap_resolved_baseline_count
          AND NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=v_build_id
              AND scope_row.dependency_unit_key=v_bootstrap_unit_key
              AND (scope_row.closure_status<>'SEALED'
                OR NOT scope_row.required_fact_families <@ scope_row.completed_fact_families))
          AND NOT EXISTS(
            SELECT 1 FROM private.banking_pay_workbench_economic_build_facts fact
            WHERE fact.build_id=v_build_id AND fact.dependency_unit_key=v_bootstrap_unit_key
              AND NULLIF(BTRIM(fact.source_payload_json->>'resolution_failure'),'') IS NOT NULL);
        IF NOT v_bootstrap_evidence_complete THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CLOSED_AUTHORITY_UNPROVED'
            USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_bootstrap_page_v1(source_key,timesheet_id)
        SELECT lpad(scope_row.stable_ordinal::text,20,'0'),scope_row.timesheet_id
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id
          AND scope_row.dependency_unit_key=v_bootstrap_unit_key
          AND scope_row.stable_ordinal>v_bootstrap_last_ordinal
        ORDER BY scope_row.stable_ordinal LIMIT 26;
        SELECT count(*)>25 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
        SELECT count(*)::integer,COALESCE(max(source_key)::bigint,v_bootstrap_last_ordinal)
        INTO v_bootstrap_page_count,v_bootstrap_last_ordinal
        FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page;
        UPDATE private.banking_pay_workbench_timesheet_scope_state state_row SET
          economic_state=CASE WHEN v_bootstrap_unit_relevant THEN 'DIRTY' ELSE 'CLOSED' END,
          evaluated_generation=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.evaluated_generation ELSE state_row.dirty_generation END,
          current_input_fingerprint=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.current_input_fingerprint ELSE scope_row.captured_input_fingerprint END,
          evaluated_input_fingerprint=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.evaluated_input_fingerprint ELSE scope_row.captured_input_fingerprint END,
          last_dirty_reason=CASE WHEN v_bootstrap_unit_relevant
            THEN 'LEGACY_ACTIVE_UNIT_CLASSIFIED' ELSE 'LEGACY_CLOSED_UNIT_CLASSIFIED' END,
          last_evaluated_at_utc=CASE WHEN v_bootstrap_unit_relevant
            THEN state_row.last_evaluated_at_utc ELSE clock_timestamp() END,
          closed_at_utc=CASE WHEN v_bootstrap_unit_relevant THEN NULL ELSE clock_timestamp() END,
          current_build_id=CASE WHEN v_bootstrap_unit_relevant THEN v_build_id ELSE NULL END,
          updated_at_utc=clock_timestamp()
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        JOIN (SELECT timesheet_id FROM pg_temp._bpay_wb_bootstrap_page_v1
          ORDER BY source_key LIMIT 25) page ON page.timesheet_id=scope_row.timesheet_id
        WHERE scope_row.build_id=v_build_id
          AND state_row.timesheet_id=scope_row.timesheet_id
          AND state_row.dirty_generation<=v_build.captured_candidate_generation;
        IF v_bootstrap_has_more THEN
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','APPLY','last_dependency_unit_key',v_bootstrap_last_unit_key,
            'dependency_unit_key',v_bootstrap_unit_key,'last_stable_ordinal',v_bootstrap_last_ordinal,
            'unit_financially_relevant',v_bootstrap_unit_relevant,
            'raw_current_occurrence_count',v_bootstrap_raw_current_count,
            'resolved_current_occurrence_count',v_bootstrap_resolved_current_count,
            'raw_baseline_occurrence_count',v_bootstrap_raw_baseline_count,
            'resolved_baseline_occurrence_count',v_bootstrap_resolved_baseline_count,
            'evidence_complete',v_bootstrap_evidence_complete,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        ELSE
          v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
            'bootstrap_id',v_bootstrap_id,'bootstrap_stream','CLASSIFY_UNITS',
            'classification_phase','EVIDENCE','last_dependency_unit_key',v_bootstrap_unit_key,
            'dependency_unit_key',NULL,'last_stable_ordinal',0,
            'unit_financially_relevant',false,'build_id',v_build_id,
            'candidate_id',p_candidate_id,
            'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq);
        END IF;
      ELSE
        RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
      END IF;
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET initialisation_status='CLASSIFYING',bootstrap_stream='CLASSIFY_UNITS',
          bootstrap_cursor_json=v_next,
          bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      -- Do not replace the terminal seed-scope cursor during classification.
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','classification_phase',
        v_next->>'classification_phase','page_source_count',v_bootstrap_page_count);
    ELSIF v_bootstrap_stream='RESET_FACT_PAGES' THEN
      WITH doomed AS (
        SELECT page.ctid
        FROM private.banking_pay_workbench_economic_build_fact_pages page
        WHERE page.build_id=v_build_id
        ORDER BY page.dependency_unit_key,page.fact_family,page.page_number
        LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_fact_pages page
        USING doomed WHERE page.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',
        CASE WHEN v_bootstrap_reset_count<250 THEN 'RESET_FACTS' ELSE 'RESET_FACT_PAGES' END,
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream=v_next->>'bootstrap_stream',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
    ELSIF v_bootstrap_stream='RESET_FACTS' THEN
      WITH doomed AS (
        SELECT fact.ctid
        FROM private.banking_pay_workbench_economic_build_facts fact
        WHERE fact.build_id=v_build_id
        ORDER BY fact.fact_family,fact.natural_key LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_facts fact
        USING doomed WHERE fact.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',
        CASE WHEN v_bootstrap_reset_count<250 THEN 'RESET_SCOPE' ELSE 'RESET_FACTS' END,
        'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET bootstrap_stream=v_next->>'bootstrap_stream',bootstrap_cursor_json=v_next,
          updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      -- Reset progress belongs to bootstrap_cursor_json until the atomic
      -- seed-seal reset below clears both the digest and sealed timestamp.
      UPDATE private.banking_pay_workbench_economic_builds
      SET updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
        'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
        'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
    ELSIF v_bootstrap_stream='RESET_SCOPE' THEN
      WITH doomed AS (
        SELECT scope_row.ctid
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=v_build_id ORDER BY scope_row.stable_ordinal LIMIT 250
      ) DELETE FROM private.banking_pay_workbench_economic_build_scope scope_row
        USING doomed WHERE scope_row.ctid=doomed.ctid;
      GET DIAGNOSTICS v_bootstrap_reset_count=ROW_COUNT;
      IF v_bootstrap_reset_count>=250 THEN
        v_next:=v_cursor;
        UPDATE private.banking_pay_workbench_candidate_scope_registry
        SET bootstrap_cursor_json=v_next,updated_at_utc=clock_timestamp()
        WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
        RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
          'private_stage','BOOTSTRAP_DISCOVERY','stage_status','CLASSIFYING',
          'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
          'next_action','BOOTSTRAP_DISCOVERY','deleted_count',v_bootstrap_reset_count);
      END IF;
      SELECT EXISTS(
        SELECT 1 FROM private.banking_pay_workbench_timesheet_scope_state
        WHERE candidate_id=p_candidate_id AND economic_state='DIRTY' LIMIT 1
      ) INTO v_bootstrap_has_dirty;
      IF NOT v_bootstrap_has_dirty
         AND v_registry.dirty_generation=v_build.captured_candidate_generation
         AND v_registry.current_source_change_seq=v_build.source_change_seq THEN
        UPDATE private.banking_pay_workbench_candidate_scope_registry SET
          initialisation_status='READY',evaluated_generation=dirty_generation,current_build_id=NULL,
          last_evaluated_at_utc=clock_timestamp(),initialised_at_utc=clock_timestamp(),
          bootstrap_stream='COMPLETE',bootstrap_cursor_json=jsonb_build_object(
            'cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,'terminal',true,
            'bootstrap_id',v_bootstrap_id),failure_json='{}'::jsonb,updated_at_utc=clock_timestamp()
        WHERE candidate_id=p_candidate_id;
        UPDATE private.banking_pay_workbench_economic_builds SET
          status='COMPLETE',private_stage='COMPLETE',scope_count=0,dependency_node_count=0,
          dependency_edge_count=0,tagged_edge_count=0,unit_count=0,row_seal_count=0,
          last_stable_ordinal=0,scope_digest=md5(''),dependency_digest=md5(''),
          pre_sync_digest=md5(''),post_sync_digest=md5(''),canonical_digest=md5(''),
          attestation_json=jsonb_build_object('bootstrap_id',v_bootstrap_id,
            'no_active_scope',true,'classification_dependency_closed',true),
          reconciled_at_utc=clock_timestamp(),completed_at_utc=clock_timestamp(),
          cleanup_not_before_utc=clock_timestamp()+interval '7 days',
          updated_at_utc=clock_timestamp() WHERE id=v_build_id;
        RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','COMPLETE',
          'stage_status','COMPLETE','has_more',false,'continuation_enqueued',false,
          'next_action','COMPLETE','classification_dependency_closed',true);
      END IF;
      v_next:=jsonb_build_object('cursor_kind','SCOPE_SELECT','cursor_version',1,
        'seed_family','ACTIVE_STATE','last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',p_candidate_id,'captured_candidate_generation',v_registry.dirty_generation,
        'captured_source_change_seq',v_registry.current_source_change_seq,'processed_source_rows',0);
      UPDATE private.banking_pay_workbench_economic_builds SET
        captured_candidate_generation=v_registry.dirty_generation,
        source_change_seq=v_registry.current_source_change_seq,status='COLLECTING',
        private_stage='PREPARE_SCOPE',scope_cursor_json=v_next,closure_cursor_json='{}'::jsonb,
        fact_cursor_json='{}'::jsonb,seed_scope_count=0,scope_count=0,
        dependency_node_count=0,dependency_edge_count=0,tagged_edge_count=0,
        unit_count=0,row_seal_count=0,last_stable_ordinal=0,fact_count=0,
        seed_scope_digest=NULL,dependency_edge_stream_digest=NULL,
        dependency_edge_stream_complete=false,dependency_edge_stream_terminal_key_json='{}'::jsonb,
        edge_tag_digest=NULL,edge_tag_stream_complete=false,
        edge_tag_stream_terminal_key_json='{}'::jsonb,unit_digest=NULL,
        sealed_fingerprint_digest=NULL,scope_digest=NULL,dependency_digest=NULL,
        seed_scope_sealed_at_utc=NULL,dependency_closure_sealed_at_utc=NULL,
        attestation_json=COALESCE(attestation_json,'{}'::jsonb)||jsonb_build_object(
          'bootstrap_active_reconciliation',true,
          'bootstrap_active_reconciliation_started_at_utc',statement_timestamp()),
        updated_at_utc=clock_timestamp() WHERE id=v_build_id;
      UPDATE private.banking_pay_workbench_candidate_scope_registry SET
        initialisation_status='CLASSIFYING',bootstrap_stream='ACTIVE_RECONCILIATION',
        bootstrap_cursor_json=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY',
          'cursor_version',1,'terminal',true,'bootstrap_id',v_bootstrap_id),
        updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,
        'private_stage','PREPARE_SCOPE','stage_status','PREPARING','has_more',true,
        'continuation_enqueued',false,'next_cursor_json',v_next,'next_action','PREPARE_SCOPE');
    ELSE
      RAISE EXCEPTION 'PAY_WORKBENCH_BOOTSTRAP_CURSOR_INVALID' USING ERRCODE='22023';
    END IF;

    SELECT count(*)>250 INTO v_bootstrap_has_more FROM pg_temp._bpay_wb_bootstrap_page_v1;
    SELECT count(*)::integer,max(source_key) INTO v_bootstrap_page_count,v_bootstrap_last_key
    FROM (SELECT source_key FROM pg_temp._bpay_wb_bootstrap_page_v1 ORDER BY source_key LIMIT 250) page;

    WITH discovered AS (
      SELECT DISTINCT page.timesheet_id
      FROM (SELECT * FROM pg_temp._bpay_wb_bootstrap_page_v1
        ORDER BY source_key LIMIT 250) page
      JOIN public.timesheets timesheet_row ON timesheet_row.timesheet_id=page.timesheet_id
      WHERE page.timesheet_id IS NOT NULL
    ), inserted AS (
      INSERT INTO private.banking_pay_workbench_timesheet_scope_state(
        timesheet_id,candidate_id,economic_state,dirty_generation,last_dirty_reason,
        current_build_id,registered_at_utc,last_dirtied_at_utc,updated_at_utc
      ) SELECT timesheet_id,p_candidate_id,'DIRTY',v_build.captured_candidate_generation,
        'LEGACY_BOOTSTRAP_DISCOVERY',v_build_id,clock_timestamp(),clock_timestamp(),clock_timestamp()
      FROM discovered
      ON CONFLICT(timesheet_id) DO UPDATE SET
        candidate_id=EXCLUDED.candidate_id,economic_state='DIRTY',
        dirty_generation=GREATEST(private.banking_pay_workbench_timesheet_scope_state.dirty_generation,
          EXCLUDED.dirty_generation),
        last_dirty_reason='LEGACY_BOOTSTRAP_DISCOVERY',current_build_id=v_build_id,
        last_dirtied_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp()
      RETURNING (xmax=0) newly_inserted
    ) SELECT count(*) FILTER(WHERE newly_inserted)::integer
      INTO v_bootstrap_registered FROM inserted;

    IF v_bootstrap_has_more THEN
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',v_bootstrap_stream,
        'last_source_key',v_bootstrap_last_key,'build_id',v_build_id,
        'candidate_id',p_candidate_id,'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
    ELSIF v_bootstrap_next_stream='SCOPE_CLOSURE' THEN
      v_next:=jsonb_build_object('cursor_kind','SCOPE_SELECT','cursor_version',1,
        'seed_family','ACTIVE_STATE','last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq,'processed_source_rows',0);
      UPDATE private.banking_pay_workbench_economic_builds SET
        private_stage='PREPARE_SCOPE',scope_cursor_json=v_next,updated_at_utc=clock_timestamp()
      WHERE id=v_build_id AND private_stage='BOOTSTRAP_DISCOVERY';
      UPDATE private.banking_pay_workbench_candidate_scope_registry SET
        initialisation_status='CLASSIFYING',bootstrap_stream='DEPENDENCY_CLOSURE',
        bootstrap_cursor_json=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY',
          'cursor_version',1,'terminal',true,'bootstrap_id',v_bootstrap_id,
          'next_stage','PREPARE_SCOPE'),
        bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
        bootstrap_timesheets_registered=bootstrap_timesheets_registered+v_bootstrap_registered,
        updated_at_utc=clock_timestamp()
      WHERE candidate_id=p_candidate_id AND current_build_id=v_build_id;
      RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','PREPARE_SCOPE',
        'stage_status','CLASSIFYING','has_more',true,'continuation_enqueued',false,
        'next_cursor_json',v_next,'next_action','PREPARE_SCOPE',
        'page_source_count',v_bootstrap_page_count,
        'timesheets_registered',v_bootstrap_registered);
    ELSE
      v_next:=jsonb_build_object('cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream',v_bootstrap_next_stream,
        'last_source_key',NULL,'build_id',v_build_id,'candidate_id',p_candidate_id,
        'captured_candidate_generation',v_build.captured_candidate_generation,
        'captured_source_change_seq',v_build.source_change_seq);
    END IF;

    UPDATE private.banking_pay_workbench_candidate_scope_registry SET
      initialisation_status='DISCOVERING',
      bootstrap_stream=COALESCE(v_next->>'bootstrap_stream',bootstrap_stream),
      bootstrap_cursor_json=v_next,
      bootstrap_rows_seen=bootstrap_rows_seen+v_bootstrap_page_count,
      bootstrap_timesheets_registered=bootstrap_timesheets_registered+v_bootstrap_registered,
      updated_at_utc=clock_timestamp()
    WHERE candidate_id=p_candidate_id;
    UPDATE private.banking_pay_workbench_economic_builds SET scope_cursor_json=v_next,
      updated_at_utc=clock_timestamp() WHERE id=v_build_id;
    RETURN jsonb_build_object('ok',true,'build_id',v_build_id,'private_stage','BOOTSTRAP_DISCOVERY',
      'stage_status','DISCOVERING',
      'has_more',true,'continuation_enqueued',false,'next_cursor_json',v_next,
      'next_action','BOOTSTRAP_DISCOVERY','page_source_count',v_bootstrap_page_count,
      'timesheets_registered',v_bootstrap_registered);
  END IF;
  RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
END;
$function$
;

-- [REPLACES] private.pay_workbench_modal_blocked_presentation_v2(p_row jsonb, p_task jsonb)  winner piece A26
CREATE OR REPLACE FUNCTION private.pay_workbench_modal_blocked_presentation_v2(p_row jsonb, p_task jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
 n jsonb;summary jsonb;headroom jsonb;component jsonb;components jsonb;ss jsonb;
 line_type text;codes text[];state text;until_date text;reason text;message_id text;condition_text text;
 amount numeric;nominal numeric;outstanding numeric;original numeric;component_outstanding numeric;
 outstanding_total numeric:=0;component_count integer:=0;recoverable numeric;row_amount numeric;section_amount numeric;
 has_amount boolean;code text;
BEGIN
 IF jsonb_typeof(p_row) IS DISTINCT FROM 'object' OR jsonb_typeof(p_task) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF private.pay_workbench_modal_hidden_v2(p_row) THEN RETURN NULL;END IF;
 n:=CASE WHEN jsonb_typeof(p_row->'row_json')='object' THEN p_row->'row_json'
   WHEN jsonb_typeof(p_row->'rowJson')='object' THEN p_row->'rowJson' ELSE '{}'::jsonb END;
 summary:=CASE WHEN jsonb_typeof(p_row->'case_resolution_summary')='object' THEN p_row->'case_resolution_summary'
   WHEN jsonb_typeof(n->'case_resolution_summary')='object' THEN n->'case_resolution_summary' ELSE '{}'::jsonb END;
 headroom:=CASE WHEN jsonb_typeof(p_row->'selection_recovery_headroom_v1')='object' THEN p_row->'selection_recovery_headroom_v1'
   WHEN jsonb_typeof(n->'selection_recovery_headroom_v1')='object' THEN n->'selection_recovery_headroom_v1' ELSE '{}'::jsonb END;
 line_type:=UPPER(BTRIM(COALESCE(NULLIF(p_row->>'line_type',''),NULLIF(p_row->>'lineType',''),
   NULLIF(n->>'line_type',''),n->>'lineType','')));
 SELECT COALESCE(array_agg(DISTINCT upper(btrim(value))) FILTER(WHERE NULLIF(btrim(value),'') IS NOT NULL),ARRAY[]::text[])
 INTO codes FROM (
  SELECT unnest(private.pay_workbench_modal_bank_blockers_v2(p_row)||private.pay_workbench_modal_bank_blockers_v2(n)
    ||private.pay_workbench_modal_bank_blockers_v2(summary)) AS value
  UNION ALL SELECT unnest(ARRAY[p_row->>'presentation_reason',p_row->>'presentationReason',n->>'presentation_reason',n->>'presentationReason'])
 ) reasons;
 row_amount:=private.pay_workbench_modal_first_display_number_v2(private.pay_workbench_modal_display_fields_v2(p_row,ARRAY[
  'amount_display','amountDisplay','amount_ex_vat','amountExVat','preview_amount_ex_vat','previewAmountExVat',
  'ready_preview_amount_ex_vat','readyPreviewAmountExVat','component_amount_ex_vat','componentAmountExVat']));
 section_amount:=COALESCE(private.pay_workbench_modal_first_display_number_v2(
  private.pay_workbench_modal_display_fields_v2(p_row,ARRAY['section_amount_display','sectionAmountDisplay',
    'section_amount_ex_vat','sectionAmountExVat','section_non_segment_amount_ex_vat','sectionNonSegmentAmountExVat'])),row_amount);
 has_amount:=section_amount IS NOT NULL;
 nominal:=private.pay_workbench_modal_first_display_number_v2(ARRAY[p_row->'nominal_due_amount_ex_vat',p_row->'nominalDueAmountExVat',
  n->'nominal_due_amount_ex_vat',n->'nominalDueAmountExVat',summary->'nominal_due_amount_ex_vat',summary->'nominalDueAmountExVat'],true);
 IF has_amount THEN amount:=private.pay_workbench_modal_line_display_amount_v2(p_row);END IF;
 IF line_type='OVERPAYMENT_RECOVERY' THEN
  -- Same outstanding components, precedence and two-decimal display as
  -- getOverpaymentRecoveryPresentation. No allocation/write is performed.
  SELECT COALESCE(jsonb_agg(item.value ORDER BY src.ord,item.ord),'[]'::jsonb) INTO components
  FROM unnest(ARRAY[p_row->'case_components',p_row->'caseComponents',n->'case_components',n->'caseComponents'])
   WITH ORDINALITY src(value,ord)
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(src.value)='array' THEN src.value ELSE '[]'::jsonb END)
   WITH ORDINALITY item(value,ord) WHERE jsonb_typeof(item.value)='object';
  FOR component IN SELECT value FROM jsonb_array_elements(components) LOOP
   original:=ABS(ROUND(private.pay_workbench_modal_first_display_number_v2(ARRAY[
    component->'resolved_target_amount_ex_vat',component->'resolvedTargetAmountExVat',component->'target_pay_ex_vat',
    component->'targetPayExVat',component->'source_amount',component->'sourceAmount',component->'source_pay_ex_vat',
    component->'sourcePayExVat',component->'remaining_source_amount',component->'remainingSourceAmount'],true),2));
   component_outstanding:=ABS(ROUND(private.pay_workbench_modal_first_display_number_v2(ARRAY[
    component->'target_outstanding_ex_vat',component->'targetOutstandingExVat',component->'remaining_source_amount',
    component->'remainingSourceAmount',to_jsonb(original)],true),2));
   IF original IS NOT NULL OR component_outstanding IS NOT NULL THEN
    component_count:=component_count+1;outstanding_total:=outstanding_total+COALESCE(component_outstanding,0);
   END IF;
  END LOOP;
  recoverable:=ABS(ROUND(COALESCE(private.pay_workbench_modal_first_display_number_v2(ARRAY[
   p_row->'recoverable_this_pay_run_ex_vat',p_row->'recoverableThisPayRunExVat',n->'recoverable_this_pay_run_ex_vat',
   n->'recoverableThisPayRunExVat',headroom->'recoverable_amount_ex_vat',headroom->'recoverableAmountExVat',
   to_jsonb(row_amount),to_jsonb(section_amount),'0'::jsonb],true),0),2));
  outstanding:=CASE WHEN component_count>0 THEN outstanding_total ELSE ABS(ROUND(COALESCE(
   private.pay_workbench_modal_first_display_number_v2(ARRAY[p_row->'nominal_due_amount_ex_vat',p_row->'nominalDueAmountExVat',
    n->'nominal_due_amount_ex_vat',n->'nominalDueAmountExVat',p_row->'case_outstanding_amount',p_row->'caseOutstandingAmount',
    n->'case_outstanding_amount',n->'caseOutstandingAmount',p_row->'outstanding_amount',p_row->'outstandingAmount',
    n->'outstanding_amount',n->'outstandingAmount',summary->'nominal_due_amount_ex_vat',summary->'nominalDueAmountExVat',
    to_jsonb(recoverable)],true),0),2)) END;
  IF outstanding>0 AND recoverable=0 AND 'NO_PAY_HEADROOM'=ANY(codes) THEN amount:=outstanding;END IF;
 END IF;
 ss:=CASE WHEN jsonb_typeof(p_row->'snooze_state')='object' THEN p_row->'snooze_state' ELSE '{}'::jsonb END;
 state:=UPPER(BTRIM(COALESCE(NULLIF(ss->>'state',''),CASE WHEN jsonb_typeof(p_row->'snooze_state')='string'
   THEN NULLIF(p_row->>'snooze_state','') END,p_row->>'blocked_snooze_state','')));
 until_date:=BTRIM(COALESCE(NULLIF(ss->>'snooze_until_date',''),p_row->>'snooze_until_date',''));
 IF state NOT IN ('','NONE','NOT_SNOOZED','CLEARED') AND until_date<>'' THEN
  IF until_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(until_date::date,'YYYY-MM-DD')<>until_date THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  reason:='Snoozed until '||to_char(until_date::date,'DD/MM/YYYY')||'.';condition_text:=reason;
 ELSIF p_task->>'task_family'='SOURCE_PROGRESS' THEN
  IF p_task->>'state' IS DISTINCT FROM 'BLOCKED' OR p_task->>'title' IS NULL
   OR p_task->>'title' NOT IN ('Refresh failed','Payment preview needs refreshing.',
     'Too many Timesheets to prepare in one pass') THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  -- A26 (AC-F1): the over-envelope Candidate is shown as a Blocked row with its reason, never silently removed.
  reason:=p_task->>'title';condition_text:=CASE WHEN p_task->>'title'='Too many Timesheets to prepare in one pass'
   THEN 'Banking Pay cannot yet prepare this many Timesheets for one Candidate at once. None of this Candidate''s payments are shown or can be included in a Draft until it is prepared.'
   ELSE 'Payment preview needs refreshing.' END;amount:=NULL;
 ELSIF p_task->>'task_family'='BANK_ACCOUNT' THEN
  IF p_task->>'state' IS DISTINCT FROM 'BLOCKED' THEN
   RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';END IF;
  message_id:=p_task->>'title_message_id';reason:=private.pay_workbench_modal_task_title_v2(message_id);
  IF reason IS NULL THEN
   code:=p_task->>'code';
   IF code IN ('BANK_TARGET_CHANGED','BANK_RESULT_CHANGED') THEN
    message_id:='MSG-096';reason:='The bank details changed or could not be confirmed. Refresh Banking Pay and try again.';
   ELSE message_id:='MSG-090';reason:='Payment issue not identified';END IF;
  END IF;
  condition_text:=reason;
 ELSIF 'NO_PAY_HEADROOM'=ANY(codes) THEN
  message_id:='MSG-031';reason:='Insufficient funds to deduct';
  condition_text:='There is not enough pay available in this run to make this deduction.';
 ELSIF line_type='DO_NOT_PAY' THEN
  reason:='This line is currently marked do not pay.';condition_text:=reason;
 ELSIF line_type='BLOCKED_TIMESHEET' THEN
  message_id:='MSG-093';
  reason:='This Timesheet payment cannot be included because CloudTMS could not confirm its current status. Open the Timesheet or refresh Banking Pay.';
  condition_text:=reason;
 ELSE message_id:='MSG-090';reason:='Payment issue not identified';END IF;
 IF message_id='MSG-090' THEN
  condition_text:='CloudTMS could not identify why this payment is blocked. It will not be included. Refresh Banking Pay; if it remains blocked, contact support.';
 END IF;
 RETURN jsonb_build_object('reason_message_id',message_id,'reason',reason,'clear_condition',condition_text,
  'clear_condition_message_id',CASE message_id WHEN 'MSG-031' THEN 'MSG-032' WHEN 'MSG-090' THEN 'MSG-091' ELSE message_id END,
  'affected_display_amount',CASE WHEN amount IS NOT NULL THEN (ROUND(amount,2)::numeric(20,2))::text END,
  'nominal_due_amount',CASE WHEN nominal IS NOT NULL THEN (ROUND(nominal,2)::numeric(20,2))::text END,
  'diagnostic_codes',to_jsonb(codes));
END;
$function$
;

-- [REPLACES] private.pay_workbench_modal_source_issue_members_v2(p_session banking_pay_workbench_sessions, p_channel text, p_progress jsonb, p_can_refresh boolean)  winner piece A26
CREATE OR REPLACE FUNCTION private.pay_workbench_modal_source_issue_members_v2(p_session banking_pay_workbench_sessions, p_channel text, p_progress jsonb, p_can_refresh boolean)
 RETURNS TABLE(task_key text, candidate_id uuid, source_kind text, preview_row_id uuid, source_payload jsonb, task_json jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF p_channel IS NULL OR p_channel NOT IN ('ALL','PAYE','UMBRELLA') OR jsonb_typeof(p_progress) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- Most open sessions have no stale/pending source. The same current-source
  -- owner proves that this entire result is empty before any three-section
  -- payment/detail expansion. STABLE uses one snapshot; no fact is inferred
  -- from a loaded page or from the browser.
  IF NOT EXISTS (
    SELECT 1 FROM private.pay_workbench_modal_source_progress_facts_v2(p_session.id,p_session.version) f
    WHERE f.source_state<>'CURRENT'
  ) THEN RETURN; END IF;
  RETURN QUERY
  WITH facts AS MATERIALIZED (
    SELECT f.*,COALESCE(cs.effective_candidate_fragment_json,'{}'::jsonb) AS fragment,
      jsonb_build_object('candidate_id',f.candidate_id,'candidate_name',COALESCE(NULLIF(BTRIM(c.display_name),''),c.tms_ref,c.id::text),
        'candidate_reference',COALESCE(c.tms_ref,''),'pay_channel',c.pay_method) AS candidate_meta,
      -- A26 (AC-F1): the scale-block reason recorded on the failed scope by pay_workbench_complete_job.
      (scope_error.error_json->>'code')='BLOCKED_UNVALIDATED_RECONCILIATION_SCALE' AS scale_blocked
    FROM private.pay_workbench_modal_source_progress_facts_v2(p_session.id,p_session.version) f
    JOIN public.candidates c ON c.id=f.candidate_id
    LEFT JOIN public.banking_pay_workbench_session_scope scope_error ON scope_error.id=f.scope_id
    LEFT JOIN public.banking_pay_workbench_session_candidate_state cs
      ON cs.session_id=p_session.id AND cs.candidate_id=f.candidate_id AND cs.session_version=p_session.version
    WHERE f.source_state<>'CURRENT'
      AND NOT private.pay_workbench_modal_hidden_v2(cs.effective_candidate_fragment_json)
  ), rows AS MATERIALIZED (
    SELECT r.candidate_id,r.id,private.pay_workbench_modal_row_payload_v2(r) AS payload
    FROM (VALUES ('canonical_preview_lines'),('cases_resolutions'),('blocked_for_pay')) section(name)
    CROSS JOIN LATERAL private.pay_workbench_modal_eligible_rows_v2(p_session.id,p_session.version,section.name) r
    JOIN facts f ON f.candidate_id=r.candidate_id
    WHERE NOT private.pay_workbench_modal_hidden_v2(r.row_json)
      AND private.pay_workbench_modal_row_matches_scope_v2(r.row_json||jsonb_build_object('candidate_id',r.candidate_id),
        p_session.filters_json,p_channel,section.name)
  ), visible AS MATERIALIZED (
    SELECT f.* FROM facts f WHERE EXISTS(SELECT 1 FROM rows r WHERE r.candidate_id=f.candidate_id)
      OR (NOT EXISTS(SELECT 1 FROM public.banking_pay_workbench_preview_rows r WHERE r.session_id=p_session.id
          AND r.session_version=p_session.version AND r.candidate_id=f.candidate_id)
        AND private.pay_workbench_modal_row_matches_scope_v2(f.candidate_meta||f.fragment||jsonb_build_object('candidate_id',f.candidate_id),
          p_session.filters_json,p_channel,'blocked_for_pay'))
  ), jobs AS MATERIALIZED (
    SELECT j.* FROM private.pay_workbench_modal_stage_job_facts_v2(p_session) j
  ), choices AS MATERIALIZED (
    SELECT DISTINCT ON(f.candidate_id) f.*,j.job_facts
    FROM visible f LEFT JOIN jobs j ON j.candidate_id=f.candidate_id
      OR (j.candidate_id IS NULL AND (
        (j.job_type='WORKBENCH_SESSION_SCOPE_SEED' AND NOT f.seeded)
        OR j.job_type IN ('WORKBENCH_SESSION_CLONE_REBASE','WORKBENCH_CANDIDATE_LINE_WORK_PROCESS','WORKBENCH_PREVIEW_ROWS_MATERIALISE')))
    ORDER BY f.candidate_id,CASE WHEN j.job_facts->'can_progress'='true'::jsonb THEN 0
      WHEN j.job_facts->'is_failed'='true'::jsonb THEN 1 ELSE 2 END,
      CASE WHEN j.candidate_id IS NOT NULL THEN 0 ELSE 1 END,j.job_facts->>'job_generation',j.job_facts->>'job_id'
  ), states AS MATERIALIZED (
    SELECT f.*,
      CASE WHEN NOT f.recovery_required AND f.job_facts->'can_progress'='true'::jsonb
          -- SOURCE_BUILD_PENDING keeps its exact existing owner/successor.
          AND (f.scope_status<>'SOURCE_BUILD_PENDING' OR f.job_facts->>'job_id'=COALESCE(f.successor_job_id,f.pending_job_id)::text)
        THEN 'UPDATING'
        WHEN p_can_refresh IS TRUE AND p_progress->>'next_recommended_action' IN ('REFRESH_OR_RETRY','RETRY_OR_REFRESH','OPEN_NEW_SESSION')
        THEN 'ACTION_REQUIRED' ELSE 'BLOCKED' END AS issue_state
    FROM choices f
  ), tasks AS MATERIALIZED (
    SELECT f.*,
      encode(extensions.digest(convert_to(jsonb_build_array('SOURCE_PROGRESS',p_session.id,p_session.version,
        p_session.progress_counter_version,f.issue_state,
        CASE WHEN f.issue_state='ACTION_REQUIRED' THEN 'REFRESH_WORKBENCH'
          WHEN f.issue_state='UPDATING' THEN f.job_facts->>'job_id' ELSE f.candidate_id::text END)::text,'UTF8'),'sha256'),'hex') AS issue_key,
      jsonb_build_object('task_family','SOURCE_PROGRESS','state',f.issue_state,
        'code',CASE WHEN f.issue_state='UPDATING' THEN 'SOURCE_PROGRESS_PENDING'
          WHEN f.recovery_required THEN COALESCE(f.owner_failure_reason,'SOURCE_REFRESH_REQUIRED')
          WHEN f.scale_blocked IS TRUE THEN 'CANDIDATE_TOO_LARGE_TO_PREPARE'
          WHEN f.source_failed OR f.job_facts->'is_failed'='true'::jsonb THEN 'SOURCE_REFRESH_FAILED'
          ELSE COALESCE(f.job_facts->>'blocked_code','SOURCE_REFRESH_REQUIRED') END,
        'title',CASE WHEN f.issue_state='UPDATING' THEN 'Refreshing…'
          WHEN f.scale_blocked IS TRUE THEN 'Too many Timesheets to prepare in one pass'
          WHEN f.source_failed OR f.job_facts->'is_failed'='true'::jsonb THEN 'Refresh failed' ELSE 'Payment preview needs refreshing.' END,
        'action',CASE WHEN f.issue_state='ACTION_REQUIRED' THEN 'banking:pay:refreshAll' END,
        'job',f.job_facts,'affected_payment_count_complete',false) AS issue
    FROM states f
  )
  SELECT f.issue_key,f.candidate_id,'SOURCE_PROGRESS'::text,NULL::uuid,
    f.candidate_meta||jsonb_build_object('source_progress',jsonb_build_object('scope_id',f.scope_id,'scope_status',f.scope_status,
      'source_state',f.source_state,'publication_current',f.publication_current,'source_failed',f.source_failed,
      'recovery_required',f.recovery_required,'recovery_scheduled',f.recovery_scheduled,'owner_failure_reason',f.owner_failure_reason)),
    f.issue||jsonb_build_object('context_only',false)
  FROM tasks f
  UNION ALL
  SELECT f.issue_key,f.candidate_id,'PREVIEW_ROW'::text,r.id,r.payload,
    f.issue||jsonb_build_object('context_only',true)
  FROM tasks f JOIN rows r ON r.candidate_id=f.candidate_id;
END;
$function$
;

-- [REPLACES] private.pay_workbench_recovery_selection_overlay_apply_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb)  winner piece A30
CREATE OR REPLACE FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_force_v3 boolean := false;
  v_reason text := 'SELECTION_CHANGED';
  v_unknown_option_count integer := 0;
  v_is_v3 boolean := false;
  v_recovery_row_count integer := 0;
  v_ready_recovery_count integer := 0;
  v_case_recovery_count integer := 0;
  v_blocked_recovery_count integer := 0;
  v_forced_deselected_count integer := 0;
  v_updated_count integer := 0;
  v_selected_positive_amount numeric := 0;
  v_ready_recovery_amount numeric := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_overlay_digest text := NULL::text;
  v_duplicate_recovery_identity_count integer := 0;
  v_session_ready boolean := false;
  v_draft_blocker_codes jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SCOPE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_unknown_option_count
  FROM pg_catalog.jsonb_object_keys(p_options_json) AS supplied_option(option_key)
  WHERE supplied_option.option_key NOT IN ('force_v3', 'reason', 'pay_channel_scope');

  IF v_unknown_option_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_UNKNOWN'
      USING ERRCODE = '22023';
  END IF;

  -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  IF COALESCE(p_options_json->>'pay_channel_scope','ALL') NOT IN ('ALL','PAYE','UMBRELLA') THEN
    RAISE EXCEPTION 'BANKING_PAY_V2_INVALID_INPUT' USING ERRCODE='22023';
  END IF;
  -- END BANKING_PAY_MODAL_WRITE_CHANNEL_VALIDATION_V2
  v_force_v3 := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_options_json->>'force_v3', 'false')))
    IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := pg_catalog.upper(pg_catalog.btrim(COALESCE(NULLIF(p_options_json->>'reason', ''), 'SELECTION_CHANGED')));

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001';
  END IF;

  v_is_v3 := v_force_v3 OR (
    v_scope.certified_preview_publication_attestation_json->>'attestation_version'
      = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND v_scope.certified_preview_publication_attestation_json->>'contract_version' = '3'
    AND v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
      = 'READY_TO_PAY_SEMANTIC_V2'
  );

  IF v_is_v3 IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_V3_SEMANTIC_SOURCE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'updated_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_recovery_selection_overlay;
  CREATE TEMPORARY TABLE pg_temp._bpay_recovery_selection_overlay ON COMMIT DROP AS
  WITH selected_positive_by_channel AS (
    SELECT
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'candidate_pay_method',
        positive_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        CASE
          WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
          ELSE 0::numeric
        END
      ), 0), 2) AS selected_positive_headroom_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS positive_row
    WHERE positive_row.session_id = p_session_id
      AND positive_row.session_version = v_session.version
      AND positive_row.candidate_id = p_candidate_id
      AND positive_row.status = 'READY'
      AND positive_row.selected IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'line_type', ''))) = 'TIMESHEET_PAYMENT'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'presentation_role', ''))) = 'ALLOCATION_COMPONENT'
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'draftable', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND (positive_row.row_json->>'amount_ex_vat')::numeric > 0
    GROUP BY pg_catalog.upper(pg_catalog.btrim(COALESCE(
      positive_row.row_json->>'pay_channel',
      positive_row.row_json->>'candidate_pay_method',
      positive_row.row_json->>'current_pay_method',
      ''
    )))
  ), recovery_base AS (
    SELECT
      recovery_row.id,
      recovery_row.row_ordinal,
      recovery_row.section AS physical_section,
      recovery_row.row_key,
      recovery_row.selected AS current_selected,
      recovery_row.selection_state AS current_selection_state,
      COALESCE(recovery_row.row_json, '{}'::jsonb) AS base_row_json,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'selection_user_override',
        ''
      ))) = 'UNSELECTED' AS explicitly_user_unselected,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'pay_channel',
        recovery_row.row_json->>'candidate_pay_method',
        recovery_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(recovery_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'source_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS nominal_due_amount_ex_vat,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_components') = 'array'
          THEN recovery_row.row_json->'case_components'
        ELSE '[]'::jsonb
      END AS canonical_case_components,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary'
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary_json') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary_json'
        ELSE '{}'::jsonb
      END AS case_resolution_summary_json,
      (
        pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,case_needs_resolution}',
          recovery_row.row_json#>>'{case_resolution_summary_json,case_needs_resolution}',
          recovery_row.row_json->>'case_needs_resolution_now',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,taxable_channel_restructure,can_apply}',
          recovery_row.row_json#>>'{case_resolution_summary_json,taxable_channel_restructure,can_apply}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,resolution_family}',
          recovery_row.row_json#>>'{case_resolution_summary_json,resolution_family}',
          recovery_row.row_json->>'resolution_family',
          ''
        ))) = 'TAXABLE_CHANNEL_RESTRUCTURE'
      ) AS actionable_restructure,
      COALESCE(
        recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
        (
          SELECT COALESCE(pg_catalog.jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
          FROM pg_catalog.jsonb_array_elements_text(
            CASE
              WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                THEN recovery_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS reason(value, ordinality)
          WHERE pg_catalog.upper(pg_catalog.btrim(reason.value)) <> 'NO_PAY_HEADROOM'
        ),
        '[]'::jsonb
      ) AS base_blocked_reason_codes,
      COALESCE(
        NULLIF(recovery_row.row_json#>>'{selection_recovery_headroom_v1,base_presentation_reason}', ''),
        CASE
          WHEN pg_catalog.upper(COALESCE(recovery_row.row_json->>'presentation_reason', '')) = 'NO_PAY_HEADROOM'
            THEN 'READY_TO_PAY'
          ELSE NULLIF(recovery_row.row_json->>'presentation_reason', '')
        END,
        'READY_TO_PAY'
      ) AS base_presentation_reason,
      (
        recovery_row.row_json->>'finance_case_id'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'line_type', ''))) IN (
          'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
        )
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'post_draft_overlay_applied', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'case_needs_resolution_now', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json#>>'{snooze_state,state}', 'NONE'))) = 'NONE'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(
              recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
              CASE
                WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                  THEN recovery_row.row_json->'blocked_reason_codes'
                ELSE '[]'::jsonb
              END
            )
          ) AS blocker(value)
          WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_PAY_HEADROOM'
        )
      ) AS static_recovery_eligible
    FROM public.banking_pay_workbench_preview_rows AS recovery_row
    WHERE recovery_row.session_id = p_session_id
      AND recovery_row.session_version = v_session.version
      AND recovery_row.candidate_id = p_candidate_id
      AND recovery_row.status = 'READY'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'line_type',
        recovery_row.row_json->>'case_type',
        ''
      ))) IN (
        'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
      )
  ), ranked_recovery AS (
    SELECT
      recovery_base.*,
      COALESCE(selected_headroom.selected_positive_headroom_ex_vat, 0)::numeric AS selected_positive_headroom_ex_vat,
      COALESCE(pg_catalog.sum(
        CASE
          WHEN recovery_base.static_recovery_eligible
           AND recovery_base.actionable_restructure IS NOT TRUE
           -- A30 (PRE-EXISTING fix, H6 M1; APPROVED rule, roadmap "Product behaviour that remains fixed"): a repayment
           -- the Office explicitly excluded consumes no headroom, so it releases that headroom to later included
           -- repayments (GBP100 headroom, first GBP80 excluded, second GBP80 included -> the second receives GBP80,
           -- not GBP20). Included-only and no-exclusion allocations, and the cap at ordinary pay headroom, are unchanged.
           AND recovery_base.explicitly_user_unselected IS NOT TRUE
            THEN recovery_base.nominal_due_amount_ex_vat
          ELSE 0::numeric
        END
      ) OVER (
        PARTITION BY recovery_base.pay_channel
        ORDER BY recovery_base.row_ordinal, recovery_base.id
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_nominal_due_amount_ex_vat
    FROM recovery_base
    LEFT JOIN selected_positive_by_channel AS selected_headroom
      ON selected_headroom.pay_channel = recovery_base.pay_channel
  ), allocated_recovery AS (
    SELECT
      ranked_recovery.*,
      CASE
        WHEN ranked_recovery.static_recovery_eligible
         AND ranked_recovery.actionable_restructure IS NOT TRUE
         AND ranked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
          THEN pg_catalog.round(LEAST(
            ranked_recovery.nominal_due_amount_ex_vat,
            GREATEST(
              ranked_recovery.selected_positive_headroom_ex_vat
                - ranked_recovery.prior_nominal_due_amount_ex_vat,
              0
            )
          ), 2)
        ELSE 0::numeric
      END AS recoverable_amount_ex_vat
    FROM ranked_recovery
  ), recovery_component_base AS (
    SELECT
      allocated_recovery.id AS recovery_row_id,
      component.ordinality::integer AS component_ordinality,
      component.value AS component_json,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN true
        ELSE NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_type',
                component.value#>>'{component_key,key_type}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_value',
                component.value#>>'{component_key,key_value}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', '')), '') IS NOT NULL
      END AS identity_complete,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'FINANCE:' || pg_catalog.lower(component.value->>'finance_component_id')
        ELSE 'STRUCT:' || pg_catalog.concat_ws(E'\x1f',
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', ''))),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            component.value->>'component_key_type', component.value#>>'{component_key,key_type}', ''
          ))),
          pg_catalog.btrim(COALESCE(
            component.value->>'component_key_value', component.value#>>'{component_key,key_value}', ''
          )),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', ''))),
          pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')),
          pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', ''))
        )
      END AS component_identity,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(component.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'target_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'authoritative_outstanding_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'source_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'component_amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS component_capacity_ex_vat,
      allocated_recovery.recoverable_amount_ex_vat
    FROM allocated_recovery
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
      allocated_recovery.canonical_case_components
    ) WITH ORDINALITY AS component(value, ordinality)
  ), recovery_component_ranked AS (
    SELECT
      recovery_component_base.*,
      pg_catalog.count(*) OVER (
        PARTITION BY recovery_component_base.recovery_row_id,
          recovery_component_base.component_identity
      )::integer AS component_identity_count,
      COALESCE(pg_catalog.sum(recovery_component_base.component_capacity_ex_vat) OVER (
        PARTITION BY recovery_component_base.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_type',
            recovery_component_base.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_value',
            recovery_component_base.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_base.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_base.component_json->>'component_fingerprint', ''),
          recovery_component_base.component_ordinality
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_component_capacity_ex_vat
    FROM recovery_component_base
  ), recovery_component_allocated AS (
    SELECT
      recovery_component_ranked.*,
      pg_catalog.round(LEAST(
        recovery_component_ranked.component_capacity_ex_vat,
        GREATEST(
          recovery_component_ranked.recoverable_amount_ex_vat
            - recovery_component_ranked.prior_component_capacity_ex_vat,
          0
        )
      ), 2) AS base_component_recoverable_ex_vat,
      pg_catalog.row_number() OVER (
        PARTITION BY recovery_component_ranked.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_type',
            recovery_component_ranked.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_value',
            recovery_component_ranked.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_ranked.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_ranked.component_json->>'component_fingerprint', ''),
          recovery_component_ranked.component_ordinality
      )::integer AS allocation_order
    FROM recovery_component_ranked
  ), recovery_component_residual AS (
    SELECT
      recovery_component_allocated.*,
      pg_catalog.round(
        recovery_component_allocated.recoverable_amount_ex_vat
          - pg_catalog.sum(recovery_component_allocated.base_component_recoverable_ex_vat)
              OVER (PARTITION BY recovery_component_allocated.recovery_row_id),
        2
      ) AS penny_residual_ex_vat,
      pg_catalog.max(recovery_component_allocated.allocation_order) FILTER (
        WHERE recovery_component_allocated.component_capacity_ex_vat
              - recovery_component_allocated.base_component_recoverable_ex_vat > 0
      ) OVER (PARTITION BY recovery_component_allocated.recovery_row_id)
        AS residual_target_order
    FROM recovery_component_allocated
  ), recovery_component_final AS (
    SELECT
      recovery_component_residual.*,
      pg_catalog.round(
        recovery_component_residual.base_component_recoverable_ex_vat
          + CASE
              WHEN recovery_component_residual.penny_residual_ex_vat <> 0
               AND recovery_component_residual.allocation_order
                    = recovery_component_residual.residual_target_order
               AND recovery_component_residual.component_capacity_ex_vat
                     - recovery_component_residual.base_component_recoverable_ex_vat
                    >= recovery_component_residual.penny_residual_ex_vat
                THEN recovery_component_residual.penny_residual_ex_vat
              ELSE 0::numeric
            END,
        2
      ) AS component_recoverable_ex_vat
    FROM recovery_component_residual
  ), recovery_component_rollup AS (
    SELECT
      recovery_component_final.recovery_row_id,
      pg_catalog.jsonb_agg(
        recovery_component_final.component_json
        || pg_catalog.jsonb_build_object(
          'preview_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'allocated_source_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'ready_preview_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'preview_component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'recoverable_this_pay_run_ex_vat', recovery_component_final.component_recoverable_ex_vat
        )
        ORDER BY recovery_component_final.component_ordinality
      ) AS allocated_case_components,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.identity_complete IS NOT TRUE
      )::integer AS incomplete_identity_count,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.component_identity_count > 1
      )::integer AS duplicate_identity_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_capacity_ex_vat
      ), 0), 2) AS component_capacity_ex_vat,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_recoverable_ex_vat
      ), 0), 2) AS component_recoverable_ex_vat
    FROM recovery_component_final
    GROUP BY recovery_component_final.recovery_row_id
  )
  SELECT
    allocated_recovery.*,
    COALESCE(recovery_component_rollup.allocated_case_components, '[]'::jsonb)
      AS allocated_case_components,
    COALESCE(recovery_component_rollup.incomplete_identity_count, 0)::integer
      AS incomplete_component_identity_count,
    COALESCE(recovery_component_rollup.duplicate_identity_count, 0)::integer
      AS duplicate_component_identity_count,
    COALESCE(recovery_component_rollup.component_capacity_ex_vat, 0)::numeric
      AS component_capacity_ex_vat,
    COALESCE(recovery_component_rollup.component_recoverable_ex_vat, 0)::numeric
      AS component_recoverable_ex_vat,
    CASE
      WHEN allocated_recovery.actionable_restructure
        THEN 'cases_resolutions'
      WHEN allocated_recovery.static_recovery_eligible
       AND allocated_recovery.recoverable_amount_ex_vat > 0
        THEN 'canonical_preview_lines'
      ELSE 'blocked_for_pay'
    END AS effective_section,
    pg_catalog.md5(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'candidate_id', p_candidate_id::text,
      'pay_channel', allocated_recovery.pay_channel,
      'row_key', allocated_recovery.row_key,
      'selected_positive_headroom_ex_vat', allocated_recovery.selected_positive_headroom_ex_vat,
      'nominal_due_amount_ex_vat', allocated_recovery.nominal_due_amount_ex_vat,
      'recoverable_amount_ex_vat', allocated_recovery.recoverable_amount_ex_vat,
      'effective_section', CASE
        WHEN allocated_recovery.actionable_restructure
          THEN 'cases_resolutions'
        WHEN allocated_recovery.static_recovery_eligible
         AND allocated_recovery.recoverable_amount_ex_vat > 0
          THEN 'canonical_preview_lines'
        ELSE 'blocked_for_pay'
      END
    )::text) AS row_overlay_digest
  FROM allocated_recovery
  LEFT JOIN recovery_component_rollup
    ON recovery_component_rollup.recovery_row_id = allocated_recovery.id;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.incomplete_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_INCOMPLETE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.duplicate_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_DUPLICATE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.nominal_due_amount_ex_vat > 0
      AND pg_catalog.jsonb_array_length(overlay_row.allocated_case_components) = 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.recoverable_amount_ex_vat > overlay_row.component_capacity_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_CAPACITY_INSUFFICIENT'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.component_recoverable_ex_vat
      IS DISTINCT FROM overlay_row.recoverable_amount_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_PENNY_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_duplicate_recovery_identity_count
  FROM (
    SELECT
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key) AS recovery_identity,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', ''))) AS recovery_family
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    GROUP BY
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key),
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', '')))
    HAVING pg_catalog.count(*) > 1
  ) AS duplicate_identity;

  IF v_duplicate_recovery_identity_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_DUPLICATE_IDENTITY'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'canonical_preview_lines')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'cases_resolutions')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'blocked_for_pay')::integer,
         (
           SELECT pg_catalog.round(COALESCE(pg_catalog.sum(channel_headroom.selected_positive_headroom_ex_vat), 0), 2)
           FROM (
             SELECT overlay_channel.pay_channel,
                    pg_catalog.max(overlay_channel.selected_positive_headroom_ex_vat) AS selected_positive_headroom_ex_vat
             FROM pg_temp._bpay_recovery_selection_overlay AS overlay_channel
             GROUP BY overlay_channel.pay_channel
           ) AS channel_headroom
         ),
         pg_catalog.round(COALESCE(pg_catalog.sum(overlay_row.recoverable_amount_ex_vat), 0), 2),
         pg_catalog.md5(COALESCE(pg_catalog.string_agg(
           overlay_row.row_key || E'\x1f' || overlay_row.row_overlay_digest,
           E'\x1e' ORDER BY overlay_row.row_ordinal, overlay_row.id
         ), ''))
  INTO v_recovery_row_count,
       v_ready_recovery_count,
       v_case_recovery_count,
       v_blocked_recovery_count,
       v_selected_positive_amount,
       v_ready_recovery_amount,
       v_overlay_digest
  FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row;

  WITH updated_rows AS (
    UPDATE public.banking_pay_workbench_preview_rows AS recovery_row
    SET selected = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN overlay_row.explicitly_user_unselected IS NOT TRUE
          ELSE false
        END,
        selection_state = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN CASE
              WHEN overlay_row.explicitly_user_unselected IS TRUE THEN 'UNSELECTED'
              ELSE 'SELECTED'
            END
          ELSE 'NOT_SELECTABLE'
        END,
        row_json = pg_catalog.jsonb_strip_nulls(
          overlay_row.base_row_json
          || pg_catalog.jsonb_build_object(
            'case_components', overlay_row.allocated_case_components,
            'amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'amount_display', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_display', -overlay_row.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', overlay_row.recoverable_amount_ex_vat,
            'semantic_ordinary_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'retained_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'semantic_recovery_headroom_capped',
              overlay_row.recoverable_amount_ex_vat < overlay_row.nominal_due_amount_ex_vat,
            'effective_section', overlay_row.effective_section,
            'physical_section', overlay_row.physical_section,
            'readiness_state', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'RESOLUTION_REQUIRED'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_section', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'CASES_RESOLUTIONS'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_reason', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_presentation_reason
              WHEN overlay_row.effective_section = 'cases_resolutions'
                THEN 'CASE_NEEDS_RESOLUTION'
              WHEN overlay_row.static_recovery_eligible THEN 'NO_PAY_HEADROOM'
              ELSE overlay_row.base_presentation_reason
            END,
            'draftable', overlay_row.effective_section = 'canonical_preview_lines',
            'is_ready_for_draft', overlay_row.effective_section = 'canonical_preview_lines',
            'selection_allowed', overlay_row.effective_section = 'canonical_preview_lines',
            'is_excluded_from_allocation', overlay_row.effective_section <> 'canonical_preview_lines',
            'selected', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.explicitly_user_unselected IS NOT TRUE
              ELSE false
            END,
            'selection_state', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS NOT TRUE
                THEN 'SELECTED'
              WHEN overlay_row.effective_section = 'canonical_preview_lines' THEN 'UNSELECTED'
              ELSE 'NOT_SELECTABLE'
            END,
            'selection_origin', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS TRUE
                THEN 'USER_EXPLICIT_DESELECT'
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              ELSE COALESCE(overlay_row.base_row_json->>'selection_origin', 'SERVER_HEADROOM_BLOCKED')
            END,
            'blocked_reason_codes', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_blocked_reason_codes
              WHEN overlay_row.static_recovery_eligible
                THEN overlay_row.base_blocked_reason_codes || pg_catalog.jsonb_build_array('NO_PAY_HEADROOM')
              ELSE overlay_row.base_blocked_reason_codes
            END,
            'case_is_blocked', overlay_row.effective_section <> 'canonical_preview_lines',
            'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'component_allocation_contract_version', 1,
              'candidate_id', p_candidate_id::text,
              'pay_channel', overlay_row.pay_channel,
              'physical_section', overlay_row.physical_section,
              'prior_physical_section', overlay_row.physical_section,
              'effective_section', overlay_row.effective_section,
              'selected_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
              'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
              'recoverable_amount_ex_vat', overlay_row.recoverable_amount_ex_vat,
              'base_blocked_reason_codes', overlay_row.base_blocked_reason_codes,
              'base_presentation_reason', overlay_row.base_presentation_reason,
              'static_recovery_eligible', overlay_row.static_recovery_eligible,
              'actionable_restructure', overlay_row.actionable_restructure,
              'component_capacity_ex_vat', overlay_row.component_capacity_ex_vat,
              'component_recoverable_ex_vat', overlay_row.component_recoverable_ex_vat,
              'overlay_digest', overlay_row.row_overlay_digest,
              'reason', v_reason,
              'updated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            'case_resolution_summary', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END,
            'case_resolution_summary_json', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END
          )
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'row_json') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'row_json', (overlay_row.base_row_json->'row_json')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'case', (overlay_row.base_row_json->'case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'raw_case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'raw_case', (overlay_row.base_row_json->'raw_case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE recovery_row.id = overlay_row.id
      -- BEGIN BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
      AND (COALESCE(p_options_json->>'pay_channel_scope','ALL')='ALL'
        OR overlay_row.pay_channel=p_options_json->>'pay_channel_scope')
      -- END BANKING_PAY_MODAL_WRITE_CHANNEL_FILTER_V2
    RETURNING recovery_row.id,
              overlay_row.effective_section,
              overlay_row.current_selected,
              recovery_row.selected
  )
  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (
           WHERE updated_rows.current_selected IS TRUE
             AND updated_rows.selected IS FALSE
         )::integer
  INTO v_updated_count, v_forced_deselected_count
  FROM updated_rows;

  SELECT COALESCE(
           pg_catalog.jsonb_agg(selected_row.id::text ORDER BY selected_row.row_ordinal, selected_row.id),
           '[]'::jsonb
         ),
         pg_catalog.count(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = v_session.version
    AND selected_row.status = 'READY'
    AND selected_row.selected IS TRUE
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_session_ready := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_session.progress_json->>'ready',
    v_session.progress_json->>'session_ready',
    v_session.progress_json->>'ready_flag',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COALESCE(
           pg_catalog.jsonb_agg(pg_catalog.to_jsonb(blocker.value) ORDER BY blocker.ordinality),
           '[]'::jsonb
         )
  INTO v_draft_blocker_codes
  FROM pg_catalog.jsonb_array_elements_text(
    CASE
      WHEN pg_catalog.jsonb_typeof(v_session.progress_json->'draft_blocker_codes') = 'array'
        THEN v_session.progress_json->'draft_blocker_codes'
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS blocker(value, ordinality)
  WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_SELECTED_ROWS';

  IF v_session_ready AND COALESCE(v_selected_row_count, 0) = 0 THEN
    v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
      || pg_catalog.jsonb_build_array('NO_SELECTED_ROWS');
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN COALESCE(session_update.server_selected_preview_row_ids_provided, false)
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_update.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
            'contract_version', 1,
            'candidate_id', p_candidate_id::text,
            'selected_positive_headroom_ex_vat', v_selected_positive_amount,
            'ready_recovery_count', v_ready_recovery_count,
            'case_recovery_count', v_case_recovery_count,
            'blocked_recovery_count', v_blocked_recovery_count,
            'recoverable_amount_ex_vat', v_ready_recovery_amount,
            'overlay_digest', v_overlay_digest,
            'reason', v_reason,
            'updated_at_utc', v_now::text
          ),
          'selected_row_count', COALESCE(v_selected_row_count, 0),
          'selected_eligible_ready_row_count', COALESCE(v_selected_row_count, 0),
          'selected_rows_available', COALESCE(v_selected_row_count, 0) > 0,
          'ready_for_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'can_create_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb)
        ),
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET certified_preview_publication_attestation_json = CASE
        WHEN v_scope.certified_preview_publication_attestation_json->>'attestation_version'
             = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          THEN COALESCE(scope_update.certified_preview_publication_attestation_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
                'contract_version', 1,
                'selected_positive_headroom_ex_vat', v_selected_positive_amount,
                'ready_recovery_count', v_ready_recovery_count,
                'case_recovery_count', v_case_recovery_count,
                'blocked_recovery_count', v_blocked_recovery_count,
                'recoverable_amount_ex_vat', v_ready_recovery_amount,
                'overlay_digest', v_overlay_digest,
                'reason', v_reason,
                'updated_at_utc', v_now::text
              )
            )
        ELSE scope_update.certified_preview_publication_attestation_json
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = v_scope.id;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SELECTION_DEPENDENT_RECOVERY_HEADROOM_APPLIED',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'recovery_row_count', v_recovery_row_count,
    'ready_recovery_count', v_ready_recovery_count,
    'case_recovery_count', v_case_recovery_count,
    'blocked_recovery_count', v_blocked_recovery_count,
    'forced_deselected_count', v_forced_deselected_count,
    'updated_count', v_updated_count,
    'selected_positive_headroom_ex_vat', v_selected_positive_amount,
    'recoverable_amount_ex_vat', v_ready_recovery_amount,
    'overlay_digest', v_overlay_digest,
    'physical_sections_changed', false,
    'source_rows_changed', false,
    'post_draft_artifacts_touched', false,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$
;

-- [REPLACES] private.pay_workbench_settled_certificate_constituent_seed_v8(p_certificate_uuid uuid, p_constituent_ordinal integer)  winner piece A27
CREATE OR REPLACE FUNCTION private.pay_workbench_settled_certificate_constituent_seed_v8(p_certificate_uuid uuid, p_constituent_ordinal integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_member private.banking_pay_workbench_settled_certificate_source_members_v8%ROWTYPE;
  v_header private.banking_pay_workbench_settled_certificates_v8%ROWTYPE;
  v_preview public.banking_pay_workbench_preview_rows%ROWTYPE;
  v_source public.banking_pay_workbench_candidate_source_lines%ROWTYPE;
  v_publication private.banking_pay_workbench_settled_certificate_publications_v8%ROWTYPE;
  v_contract jsonb;
  v_json jsonb;
  v_source_identity_unsigned jsonb;
  v_source_identity_digest text;
  v_prior_treatment text;
  v_prior_paid text;
  v_prior_digest text;
  v_supersession_digest text;
  v_item_digest text;
  v_overlay jsonb;
  v_overlay_digest text;
  v_recovery_contract text;
  v_recovery_nominal text;
  v_recovery_amount text;
  v_recovery_headroom text;
  v_recovery_allocated text;
  v_recovery_result text;
  v_allocation_kind text;
  v_allocation_result text;
  v_allocation_digest text;
  v_reservation_amount text;
  v_reservation_ids jsonb := '[]'::jsonb;
  v_reservation_digest text;
  v_superseded_source_ids jsonb := '[]'::jsonb;
  v_economic_build_id uuid;
  v_entitlement_count integer := 0;
  v_entitlement_truth numeric;
  v_entitlement_baseline numeric;
  v_reservation_count integer := 0;
  v_reservation_missing_id_count integer := 0;
  v_client_id uuid;
  v_timesheet_id uuid;
  v_line_type text;
  v_key_type text;
  v_key_value text;
  v_pay_channel text;
  v_payment_method text;
  v_amount numeric;
BEGIN
  IF p_certificate_uuid IS NULL OR p_constituent_ordinal IS NULL
     OR p_constituent_ordinal < 0 OR p_constituent_ordinal > 49999 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_CONSTITUENT_CURSOR_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO STRICT v_header
  FROM private.banking_pay_workbench_settled_certificates_v8 header
  WHERE header.certificate_uuid = p_certificate_uuid;
  SELECT * INTO STRICT v_member
  FROM private.banking_pay_workbench_settled_certificate_source_members_v8 member
  WHERE member.certificate_uuid = p_certificate_uuid
    AND member.constituent_ordinal = p_constituent_ordinal;
  SELECT * INTO STRICT v_preview
  FROM public.banking_pay_workbench_preview_rows preview
  WHERE preview.id = v_member.preview_row_id;

  IF v_preview.session_id IS DISTINCT FROM v_header.workbench_session_id
     OR v_preview.session_version IS DISTINCT FROM v_header.session_version
     OR private.pay_workbench_settled_certificate_source_row_digest_v8(v_preview.id)
          IS DISTINCT FROM v_member.source_row_digest_sha256 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SOURCE_ROW_CHANGED' USING ERRCODE = '55000';
  END IF;
  v_contract := private.pay_workbench_settled_certificate_preview_contract_v8(v_preview.id);
  IF v_contract->'eligible' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SOURCE_ROW_NOT_DRAFT_ELIGIBLE'
      USING ERRCODE = '55000', DETAIL = v_contract::text;
  END IF;
  v_json := v_preview.row_json;

  IF COALESCE(v_json->>'source_line_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SOURCE_LINE_IDENTITY_MISSING' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO STRICT v_source
  FROM public.banking_pay_workbench_candidate_source_lines source_line
  WHERE source_line.id = (v_json->>'source_line_id')::uuid;
  IF v_source.session_id IS DISTINCT FROM v_header.workbench_session_id
     OR v_source.session_version IS DISTINCT FROM v_header.session_version
     OR v_source.candidate_id IS DISTINCT FROM v_preview.candidate_id
     OR v_source.source_change_seq::text IS DISTINCT FROM COALESCE(v_json->>'source_change_seq', '')
     OR v_source.source_build_run_id::text IS DISTINCT FROM COALESCE(v_json->>'source_build_run_id', '')
     OR v_source.source_publication_id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SOURCE_LINE_IDENTITY_MISMATCH' USING ERRCODE = '55000';
  END IF;
  SELECT * INTO STRICT v_publication
  FROM private.banking_pay_workbench_settled_certificate_publications_v8 publication
  WHERE publication.certificate_uuid = p_certificate_uuid
    AND publication.candidate_id = v_preview.candidate_id;
  IF v_publication.source_change_seq IS DISTINCT FROM v_source.source_change_seq
     OR v_publication.source_build_run_id IS DISTINCT FROM v_source.source_build_run_id
     OR v_publication.source_publication_id IS DISTINCT FROM v_source.source_publication_id THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PUBLICATION_SOURCE_MISMATCH' USING ERRCODE = '55000';
  END IF;
  SELECT CASE
    WHEN COALESCE(scope.certified_preview_publication_attestation_json->>'economic_build_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (scope.certified_preview_publication_attestation_json->>'economic_build_id')::uuid
    ELSE NULL END
  INTO STRICT v_economic_build_id
  FROM public.banking_pay_workbench_session_scope scope
  WHERE scope.session_id=v_header.workbench_session_id
    AND scope.candidate_id=v_preview.candidate_id
    AND scope.certified_preview_publication_session_version=v_header.session_version
    AND scope.certified_preview_publication_source_change_seq=v_source.source_change_seq
    AND scope.certified_preview_publication_source_build_run_id=v_source.source_build_run_id
    AND scope.certified_preview_publication_source_publication_id=v_source.source_publication_id;
  IF v_economic_build_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM private.banking_pay_workbench_economic_builds build_row
    WHERE build_row.id=v_economic_build_id
      AND build_row.candidate_id=v_preview.candidate_id
      AND build_row.session_id=v_header.workbench_session_id
      AND build_row.session_version=v_header.session_version
      AND build_row.source_change_seq=v_source.source_change_seq
      AND build_row.source_build_run_id=v_source.source_build_run_id
      AND build_row.status='COMPLETE'
      AND build_row.completed_at_utc IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_ECONOMIC_BUILD_IDENTITY_MISSING' USING ERRCODE='55000';
  END IF;

  v_line_type := UPPER(v_contract->>'line_type');
  v_key_type := UPPER(v_contract->>'key_type');
  v_key_value := v_contract->>'key_value';
  v_pay_channel := UPPER(v_contract->>'pay_channel');
  v_timesheet_id := (v_contract->>'timesheet_id')::uuid;
  v_amount := ROUND((v_contract->>'amount_ex_vat')::numeric, 2);
  IF COALESCE(v_json->>'client_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_client_id := (v_json->>'client_id')::uuid;
  ELSIF NULLIF(BTRIM(COALESCE(v_json->>'client_id', '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_CLIENT_IDENTITY_INVALID' USING ERRCODE = '22023';
  END IF;
  v_payment_method := UPPER(NULLIF(BTRIM(COALESCE(
    v_json->>'current_target_pay_method', v_json->>'source_pay_method', v_json->>'pay_channel', ''
  )), ''));
  IF v_payment_method IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PAYMENT_METHOD_MISSING' USING ERRCODE = '22023';
  END IF;

  v_source_identity_unsigned := pg_catalog.jsonb_build_object(
    'source_kind', 'CERTIFIED_CANDIDATE_SOURCE_LINE',
    'source_line_id', v_source.id::text,
    'source_row_key', v_source.line_key,
    'source_publication_id', v_source.source_publication_id,
    'source_change_seq', v_source.source_change_seq,
    'source_build_run_id', v_source.source_build_run_id
  );
  v_source_identity_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(v_source_identity_unsigned)
  );

  -- Prior settlement is not reconstructed and never defaults from an absent
  -- preview key.  The installed component owner groups the sealed build facts
  -- by the exact Timesheet/economic key and supplies the active settled
  -- baseline already used by Workbench reconciliation.  A genuinely absent
  -- grouped row is explicit zero evidence from the complete sealed build.
  -- A27 (AC-P1): the same grouped row as
  --   private.pay_current_timesheet_entitlement_components_from_build_v1(v_economic_build_id,NULL)
  --   filtered by (timesheet_id IS NOT DISTINCT FROM v_timesheet_id, UPPER(key_type)=v_key_type, key_value=v_key_value),
  -- read directly: the three filters are on the GROUP BY keys, so they are applied before the aggregate (index
  -- bpay_wb_economic_build_facts_timesheet_idx) instead of aggregating every entitlement fact of the build for every
  -- constituent, and the sealed-build condition is read once instead of once per fact. Same source rows, same sums,
  -- same group count. The owner function itself is unchanged.
  SELECT COUNT(*)::integer,MAX(component.truth_ex_vat),MAX(component.baseline_ex_vat)
  INTO v_entitlement_count,v_entitlement_truth,v_entitlement_baseline
  FROM (
    SELECT fact.timesheet_id,
      fact.economic_key_type AS key_type,
      fact.economic_key_value AS key_value,
      round(sum(coalesce(fact.truth_ex_vat,0)),2) AS truth_ex_vat,
      round(sum(coalesce(fact.baseline_ex_vat,0)),2) AS baseline_ex_vat
    FROM private.banking_pay_workbench_economic_build_facts AS fact
    WHERE fact.build_id=v_economic_build_id
      AND fact.timesheet_id=v_timesheet_id
      AND fact.fact_family='ENTITLEMENT_COMPONENT'
      AND fact.timesheet_id IS NOT NULL
      AND fact.economic_key_type IS NOT NULL
      AND fact.economic_key_value IS NOT NULL
      AND UPPER(fact.economic_key_type)=v_key_type
      AND fact.economic_key_value=v_key_value
      -- the owner's JOIN to the build row: id is the primary key, so the join keeps each fact once when that one
      -- build row is sealed and drops it otherwise; checked once here instead of once per fact.
      AND EXISTS (
        SELECT 1
        FROM private.banking_pay_workbench_economic_builds AS build
        WHERE build.id=v_economic_build_id
          AND build.dependency_closure_sealed_at_utc IS NOT NULL
          AND build.dependency_edge_stream_complete
          AND build.edge_tag_stream_complete
      )
    GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value
  ) component;
  IF v_entitlement_count > 1 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PRIOR_PAYMENT_COMPONENT_CARDINALITY_INVALID'
      USING ERRCODE='55000';
  END IF;
  IF v_entitlement_count=1 THEN
    IF v_entitlement_truth IS NULL OR v_entitlement_baseline IS NULL THEN
      RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PRIOR_PAYMENT_COMPONENT_INCOMPLETE'
        USING ERRCODE='55000';
    END IF;
    v_prior_treatment := 'ACTIVE_SETTLED_COMPONENT_BASELINE_APPLIED';
    v_prior_paid := private.pay_workbench_settled_certificate_money_v8(
      pg_catalog.to_jsonb(ROUND(v_entitlement_baseline,2))
    );
  ELSE
    v_prior_treatment := 'NO_SETTLED_COMPONENT_BASELINE_IN_SEALED_BUILD';
    v_prior_paid := '0.00';
  END IF;
  v_prior_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(pg_catalog.jsonb_build_object(
      'treatment', v_prior_treatment,
      'prior_paid_amount_ex_vat', v_prior_paid,
      'economic_build_id',v_economic_build_id,
      'authoritative_truth_ex_vat',CASE WHEN v_entitlement_count=1 THEN
        private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(ROUND(v_entitlement_truth,2))) END,
      'authoritative_baseline_ex_vat',CASE WHEN v_entitlement_count=1 THEN v_prior_paid END,
      'source_row_digest_sha256', v_member.source_row_digest_sha256
    ))
  );

  -- Supersession is the exact stable line or certified cancellation replay
  -- lineage inside this session. Candidate-only history is deliberately not
  -- admitted because it could bind an unrelated economic source.
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(old_source.id::text)
           ORDER BY old_source.source_change_seq,old_source.source_ordinal,old_source.id),'[]'::jsonb)
  INTO v_superseded_source_ids
  FROM public.banking_pay_workbench_candidate_source_lines old_source
  WHERE old_source.session_id=v_source.session_id
    AND old_source.candidate_id=v_source.candidate_id
    AND old_source.id<>v_source.id
    AND UPPER(BTRIM(old_source.status))='SUPERSEDED'
    AND (
      old_source.line_key=v_source.line_key
      OR (
        old_source.economic_key_json=v_source.economic_key_json
        AND old_source.source_build_run_id::text IN (
          NULLIF(v_source.source_row_json->>'original_source_build_run_id',''),
          NULLIF(v_source.source_row_json->>'replayed_from_source_build_run_id','')
        )
      )
    );
  v_supersession_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(pg_catalog.jsonb_build_object(
      'treatment',CASE WHEN pg_catalog.jsonb_array_length(v_superseded_source_ids)=0
        THEN 'CURRENT_CERTIFIED_SOURCE_ONLY'
        ELSE 'CURRENT_CERTIFIED_SOURCE_REPLACES_PROVED_LINEAGE' END,
      'ordered_superseded_source_ids',v_superseded_source_ids,
      'source_publication_id', v_source.source_publication_id
    ))
  );
  v_item_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(pg_catalog.jsonb_build_object(
      'source_identity_digest_sha256', v_source_identity_digest,
      'semantic_kind', v_line_type,
      'canonical_amount_ex_vat', private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(v_amount)),
      'economic_key', pg_catalog.jsonb_build_object(
        'timesheet_id', v_timesheet_id, 'key_type', v_key_type, 'key_value', v_key_value
      )
    ))
  );

  v_overlay := CASE WHEN pg_catalog.jsonb_typeof(v_json->'selection_recovery_headroom_v1') = 'object'
    THEN v_json->'selection_recovery_headroom_v1' ELSE NULL END;
  IF v_line_type IN ('OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','LOAN_REPAYMENT') THEN
    v_recovery_contract := COALESCE(v_overlay->>'contract_version', v_json->>'recovery_residual_contract_version');
    v_recovery_nominal := private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(
      ROUND(COALESCE(NULLIF(v_overlay->>'nominal_due_amount_ex_vat', '')::numeric,
        NULLIF(v_json->>'nominal_due_amount_ex_vat', '')::numeric), 2)
    ));
    v_recovery_amount := private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(
      ROUND(COALESCE(NULLIF(v_overlay->>'recoverable_amount_ex_vat', '')::numeric,
        NULLIF(v_json->>'recoverable_this_pay_run_ex_vat', '')::numeric, ABS(v_amount)), 2)
    ));
    v_recovery_headroom := private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(
      ROUND(COALESCE(NULLIF(v_overlay->>'selected_positive_headroom_ex_vat', '')::numeric,
        NULLIF(v_json->>'retained_positive_headroom_ex_vat', '')::numeric,
        NULLIF(v_json->>'semantic_ordinary_positive_headroom_ex_vat', '')::numeric,
        ABS(v_amount)), 2)
    ));
    v_recovery_allocated := v_recovery_amount;
    v_recovery_result := 'RECOVERY_HEADROOM_ALLOCATED';
    v_allocation_kind := 'WORKBENCH_RECOVERY_HEADROOM_V1';
    v_allocation_result := 'ALLOCATED_WITHIN_CERTIFIED_HEADROOM';
    v_allocation_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
      private.pay_workbench_settled_certificate_stable_stringify_v8(COALESCE(v_overlay, pg_catalog.jsonb_build_object(
        'nominal_due_amount_ex_vat', v_recovery_nominal,
        'recoverable_amount_ex_vat', v_recovery_amount,
        'selected_positive_headroom_ex_vat', v_recovery_headroom
      )))
    );
    v_overlay_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
      private.pay_workbench_settled_certificate_stable_stringify_v8(COALESCE(v_overlay, '{}'::jsonb))
    );
  ELSE
    v_recovery_result := 'NOT_APPLICABLE';
    v_allocation_kind := 'NOT_APPLICABLE';
    v_allocation_result := 'NOT_APPLICABLE';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_json->>'finance_component_id','')),'') IS NOT NULL
     AND COALESCE(v_json->>'finance_component_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_FINANCE_COMPONENT_IDENTITY_INVALID' USING ERRCODE='22023';
  END IF;
  SELECT COUNT(*)::integer,
         COUNT(*) FILTER(WHERE fact.reservation_id IS NULL)::integer,
         CASE WHEN COUNT(*)=0 THEN NULL ELSE private.pay_workbench_settled_certificate_money_v8(
           pg_catalog.to_jsonb(ROUND(SUM(fact.reserved_source_amount),2))) END,
         COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(fact.reservation_id::text)
           ORDER BY fact.natural_key,fact.reservation_id)
           FILTER(WHERE fact.reservation_id IS NOT NULL),'[]'::jsonb)
  INTO v_reservation_count,v_reservation_missing_id_count,v_reservation_amount,v_reservation_ids
  FROM private.banking_pay_workbench_economic_build_facts fact
  WHERE fact.build_id=v_economic_build_id
    AND fact.fact_family='RESERVATION_COMPONENT'
    AND fact.candidate_id=v_preview.candidate_id
    AND fact.timesheet_id IS NOT DISTINCT FROM v_timesheet_id
    AND UPPER(fact.economic_key_type)=v_key_type
    AND fact.economic_key_value=v_key_value
    AND (NULLIF(v_json->>'finance_component_id','') IS NULL
      OR fact.finance_component_id=(v_json->>'finance_component_id')::uuid);
  IF v_reservation_missing_id_count<>0
     OR (v_reservation_count<>pg_catalog.jsonb_array_length(v_reservation_ids)) THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SOURCE_RESERVATION_IDENTITY_INCOMPLETE'
      USING ERRCODE='55000';
  END IF;
  v_reservation_digest := CASE WHEN v_reservation_amount IS NULL THEN NULL ELSE
    private.pay_workbench_settled_certificate_sha256_text_v8(
      private.pay_workbench_settled_certificate_stable_stringify_v8(pg_catalog.jsonb_build_object(
        'source_reservation_amount_ex_vat', v_reservation_amount,
        'ordered_active_source_reservation_ids', v_reservation_ids
      ))
    ) END;

  RETURN pg_catalog.jsonb_build_object(
    'preview_row_id', v_preview.id,
    'presentation_preview_row_id', COALESCE(NULLIF(BTRIM(v_json->>'preview_row_id'), ''), v_preview.id::text),
    'row_key', v_preview.row_key,
    'line_id', NULLIF(BTRIM(v_json->>'line_id'), ''),
    'source_kind', 'CERTIFIED_CANDIDATE_SOURCE_LINE',
    'source_line_id', v_source.id::text,
    'source_row_key', v_source.line_key,
    'source_publication_id', v_source.source_publication_id,
    'source_change_seq', v_source.source_change_seq,
    'source_build_run_id', v_source.source_build_run_id,
    'source_identity_digest_sha256', v_source_identity_digest,
    'candidate_publication_ordinal', v_publication.scope_ordinal,
    'candidate_id', v_preview.candidate_id,
    'client_id', v_client_id,
    'timesheet_id', v_timesheet_id,
    'resolved_pay_channel', v_pay_channel,
    'resolved_payment_method', v_payment_method,
    'amount_sign', CASE WHEN v_amount < 0 THEN 'NEGATIVE' WHEN v_amount > 0 THEN 'POSITIVE' ELSE 'ZERO' END,
    'semantic_kind', v_line_type,
    'economic_key_type', v_key_type,
    'economic_key_value', v_key_value,
    'canonical_amount_ex_vat', private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(v_amount)),
    'source_reservation_amount_ex_vat', v_reservation_amount,
    'source_reservation_ids', v_reservation_ids,
    'prior_payment_treatment', v_prior_treatment,
    'prior_paid_amount_ex_vat', v_prior_paid,
    'prior_payment_evidence_digest_sha256', v_prior_digest,
    'supersession_treatment', CASE WHEN pg_catalog.jsonb_array_length(v_superseded_source_ids)=0
      THEN 'CURRENT_CERTIFIED_SOURCE_ONLY'
      ELSE 'CURRENT_CERTIFIED_SOURCE_REPLACES_PROVED_LINEAGE' END,
    'supersession_evidence_digest_sha256', v_supersession_digest,
    'superseded_source_ids',v_superseded_source_ids,
    'recovery_contract_version', v_recovery_contract,
    'recovery_nominal_due_amount_ex_vat', v_recovery_nominal,
    'recovery_recoverable_this_pay_run_ex_vat', v_recovery_amount,
    'recovery_headroom_amount_ex_vat', v_recovery_headroom,
    'recovery_allocated_amount_ex_vat', v_recovery_allocated,
    'recovery_result_kind', v_recovery_result,
    'recovery_overlay_digest_sha256', v_overlay_digest,
    'expected_allocation_basis_kind', v_allocation_kind,
    'expected_allocated_recovery_amount_ex_vat', v_recovery_allocated,
    'expected_allocation_result', v_allocation_result,
    'expected_allocation_source_digest_sha256', v_allocation_digest,
    'expected_item_semantic_kind', v_line_type,
    'expected_item_source_identity_digest_sha256', v_source_identity_digest,
    'expected_item_amount_ex_vat', private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(v_amount)),
    'expected_item_source_digest_sha256', v_item_digest,
    'expected_reservation_applicability', CASE WHEN v_reservation_amount IS NULL THEN 'NOT_APPLICABLE' ELSE 'APPLICABLE' END,
    'expected_reservation_amount_ex_vat', v_reservation_amount,
    'expected_reservation_source_digest_sha256', v_reservation_digest,
    'case_components', CASE WHEN pg_catalog.jsonb_typeof(v_json->'case_components') = 'array'
      THEN v_json->'case_components' ELSE '[]'::jsonb END,
    'source_row_digest_sha256', v_member.source_row_digest_sha256
  );
END;
$function$;

-- [REPLACES] private.pay_workbench_settled_certificate_preview_contract_v8(p_preview_row_id uuid)  winner piece A30
CREATE OR REPLACE FUNCTION private.pay_workbench_settled_certificate_preview_contract_v8(p_preview_row_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_row public.banking_pay_workbench_preview_rows%ROWTYPE;
  v_json jsonb;
  v_overlay jsonb;
  v_preview_contract jsonb;
  v_candidate_id uuid;
  v_timesheet_id uuid;
  v_finance_case_id uuid;
  v_finance_component_id uuid;
  v_pay_channel text;
  v_line_type text;
  v_key_type text;
  v_key_value text;
  v_amount numeric;
  v_selected_headroom numeric;
  v_recoverable numeric;
  v_nominal numeric;
  v_physical_section text;
  v_effective_section text;
  v_overlay_valid boolean := false;
  v_synthetic_total boolean := false;
  v_certified_finance boolean := false;
  v_eligible boolean := false;
BEGIN
  SELECT * INTO v_row
  FROM public.banking_pay_workbench_preview_rows
  WHERE id = p_preview_row_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('eligible', false, 'reason', 'PREVIEW_ROW_NOT_FOUND');
  END IF;

  v_json := v_row.row_json;
  v_overlay := CASE WHEN pg_catalog.jsonb_typeof(v_json->'selection_recovery_headroom_v1') = 'object'
    THEN v_json->'selection_recovery_headroom_v1' ELSE '{}'::jsonb END;
  v_preview_contract := CASE WHEN pg_catalog.jsonb_typeof(v_json->'preview_contract') = 'object'
    THEN v_json->'preview_contract' ELSE '{}'::jsonb END;
  v_candidate_id := v_row.candidate_id;
  v_timesheet_id := COALESCE(
    v_row.timesheet_id,
    CASE WHEN COALESCE(v_json#>>'{economic_key,timesheet_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_json#>>'{economic_key,timesheet_id}')::uuid END,
    CASE WHEN COALESCE(v_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_json->>'timesheet_id')::uuid END
  );
  v_finance_case_id := CASE
    WHEN COALESCE(v_json->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_json->>'finance_case_id')::uuid
    ELSE NULL
  END;
  v_finance_component_id := CASE
    WHEN COALESCE(v_json->>'finance_component_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN (v_json->>'finance_component_id')::uuid
    ELSE NULL
  END;
  v_pay_channel := UPPER(NULLIF(BTRIM(COALESCE(
    v_json->>'pay_channel', v_json->>'current_pay_method', v_json->>'candidate_pay_method', ''
  )), ''));
  v_line_type := UPPER(NULLIF(BTRIM(COALESCE(v_json->>'line_type', v_json->>'item_type', '')), ''));
  v_key_type := UPPER(NULLIF(BTRIM(COALESCE(
    v_row.key_type, v_json#>>'{economic_key,key_type}', v_json->>'key_type', v_json->>'component_key_type', ''
  )), ''));
  v_key_value := NULLIF(BTRIM(COALESCE(
    v_row.key_value, v_json#>>'{economic_key,key_value}', v_json->>'key_value', v_json->>'component_key_value', ''
  )), '');
  IF COALESCE(v_json->>'amount_ex_vat', v_json->>'preview_amount_ex_vat', v_json->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_amount := ROUND(COALESCE(v_json->>'amount_ex_vat', v_json->>'preview_amount_ex_vat', v_json->>'amount_display')::numeric, 2);
  END IF;

  v_physical_section := CASE LOWER(BTRIM(COALESCE(v_overlay->>'physical_section', '')))
    WHEN 'canonical_preview_lines' THEN 'canonical_preview_lines'
    WHEN 'ready_to_pay' THEN 'canonical_preview_lines'
    WHEN 'ready' THEN 'canonical_preview_lines'
    WHEN 'blocked_for_pay' THEN 'blocked_for_pay'
    WHEN 'blocked_for_pay_now' THEN 'blocked_for_pay'
    WHEN 'blocked_now' THEN 'blocked_for_pay'
    WHEN 'blocked_preview_lines' THEN 'blocked_for_pay'
    ELSE LOWER(BTRIM(COALESCE(v_overlay->>'physical_section', ''))) END;
  v_effective_section := CASE LOWER(BTRIM(COALESCE(v_overlay->>'effective_section', '')))
    WHEN 'canonical_preview_lines' THEN 'canonical_preview_lines'
    WHEN 'ready_to_pay' THEN 'canonical_preview_lines'
    WHEN 'ready' THEN 'canonical_preview_lines'
    WHEN 'blocked_for_pay' THEN 'blocked_for_pay'
    WHEN 'blocked_for_pay_now' THEN 'blocked_for_pay'
    WHEN 'blocked_now' THEN 'blocked_for_pay'
    WHEN 'blocked_preview_lines' THEN 'blocked_for_pay'
    ELSE LOWER(BTRIM(COALESCE(v_overlay->>'effective_section', ''))) END;

  IF COALESCE(v_overlay->>'selected_positive_headroom_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
     AND COALESCE(v_overlay->>'recoverable_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
     AND COALESCE(v_overlay->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_selected_headroom := ROUND((v_overlay->>'selected_positive_headroom_ex_vat')::numeric, 2);
    v_recoverable := ROUND((v_overlay->>'recoverable_amount_ex_vat')::numeric, 2);
    v_nominal := ROUND((v_overlay->>'nominal_due_amount_ex_vat')::numeric, 2);
  END IF;
  v_overlay_valid := COALESCE(v_overlay->>'contract_version', '') = '1'
    AND COALESCE(v_overlay->>'candidate_id', '') = v_candidate_id::text
    AND v_pay_channel IN ('PAYE','UMBRELLA')
    AND UPPER(COALESCE(v_overlay->>'pay_channel', '')) = v_pay_channel
    AND v_line_type IN ('OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','LOAN_REPAYMENT')
    AND v_physical_section = 'blocked_for_pay'
    AND v_effective_section = 'canonical_preview_lines'
    AND v_selected_headroom > 0
    AND v_recoverable > 0
    AND v_recoverable <= v_selected_headroom
    AND v_nominal >= v_recoverable
    AND v_amount < 0
    AND ABS(v_amount) = v_recoverable
    AND v_overlay->'static_recovery_eligible' = 'true'::jsonb
    AND COALESCE(v_overlay->>'overlay_digest', '') ~* '^[0-9a-f]{32}$'
    AND UPPER(COALESCE(v_overlay->>'policy_x_authority_scope', '')) = 'PRE_DRAFT_LIVE_TRUTH';

  IF v_key_type = 'TS_TOTAL'
     AND UPPER(COALESCE(v_key_value, '')) = 'TOTAL'
     AND LOWER(CONCAT_WS('|',
       v_row.id::text, v_row.row_key, v_json->>'preview_row_id', v_json->>'row_key',
       v_json->>'line_key', v_json->>'source_ref', v_json#>>'{source_basis_json,row_key}',
       v_json#>>'{source_basis_json,line_key}', v_json#>>'{source_basis_json,source_ref}'
     )) LIKE '%:non_segment:total%'
     AND (
       v_json->'resolved_segment_rows_replace_source_total' = 'true'::jsonb
       OR v_json#>'{source_basis_json,resolved_segment_rows_replace_source_total}' = 'true'::jsonb
       OR EXISTS (
         SELECT 1
         FROM public.banking_pay_workbench_preview_rows sibling
         WHERE sibling.session_id = v_row.session_id
           AND sibling.id <> v_row.id
           AND sibling.timesheet_id IS NOT DISTINCT FROM v_timesheet_id
           AND UPPER(COALESCE(sibling.key_type, sibling.row_json#>>'{economic_key,key_type}', '')) = 'TS_DAY'
           AND (sibling.selected OR UPPER(sibling.selection_state) = 'SELECTED' OR UPPER(sibling.status) = 'READY')
       )
     ) THEN
    v_synthetic_total := true;
  END IF;

  v_effective_section := CASE
    WHEN v_overlay_valid THEN 'canonical_preview_lines'
    WHEN LOWER(v_row.section) IN ('canonical_preview_lines','ready_to_pay','ready') THEN 'canonical_preview_lines'
    WHEN LOWER(v_row.section) IN ('blocked_for_pay','blocked_for_pay_now','blocked_now','blocked_preview_lines') THEN 'blocked_for_pay'
    WHEN LOWER(v_row.section) IN ('cases_resolutions','cases_and_resolutions','case_resolution','case_resolutions') THEN 'cases_resolutions'
    ELSE LOWER(v_row.section) END;

  -- Finance rows do not have a Timesheet identity.  Admit only the six
  -- canonical visible aliases emitted by the current Workbench producer and
  -- bind the producer-owned case/component/source identities byte-for-byte.
  -- Hidden/frozen item vocabulary (LOAN_REPAYMENT and MANUAL_CREDIT_PAYOUT)
  -- remains invalid as a visible selected row.  No amount, tax, VAT, channel,
  -- headroom or later Draft policy is calculated here.
  v_certified_finance := v_timesheet_id IS NULL
    AND v_line_type IN (
      'OVERPAYMENT_RECOVERY',
      'MANUAL_DEBT_RECOVERY',
      'PAYMENT_ADVANCE_REPAYMENT',
      'LOAN_PAYOUT',
      'UNDERPAYMENT_PAYMENT',
      'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
    )
    AND v_finance_case_id IS NOT NULL
    AND v_finance_component_id IS NOT NULL
    AND v_key_type IN ('CASE_TOTAL','FINANCE_COMPONENT')
    AND v_key_value IS NOT NULL
    AND (
      (
        COALESCE(v_json->>'source_function', '') = 'pay_workbench_candidate_source_build_chunk'
        AND UPPER(COALESCE(v_json->>'dependency_family_kind', '')) = 'FINANCE_CASE'
        AND COALESCE(v_json->>'dependency_family_key', '') = 'finance:' || v_finance_case_id::text
      )
      -- A30 (PRE-EXISTING fix, H6 M2b): the markers above are written only by the retired 21072026 source-build
      -- chunk; no installed producer writes them, so no finance row (repayment, credit, loan) could ever certify.
      -- The CURRENT producer, the certified Source-to-preview publisher, marks its rows
      -- published_from_certified_source = true and carries the same finance-case family as case_key. The exact
      -- source line / publication / economic build binding is still enforced for every row by
      -- pay_workbench_settled_certificate_constituent_seed_v8. Every other condition here is unchanged.
      OR (
        v_json->'published_from_certified_source' = 'true'::jsonb
        AND COALESCE(v_json->>'case_key', '') = 'finance:' || v_finance_case_id::text
        AND COALESCE(v_json->>'source_line_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
    )
    AND COALESCE(v_json->>'source_ref', '') = 'advance:' || v_finance_case_id::text
    AND UPPER(COALESCE(v_json->>'policy_x_authority_scope', '')) = 'PRE_DRAFT_LIVE_TRUTH'
    AND pg_catalog.jsonb_typeof(v_json->'case_components') = 'array'
    AND pg_catalog.jsonb_array_length(v_json->'case_components') > 0
    AND (
      SELECT pg_catalog.count(*) = 1
      FROM pg_catalog.jsonb_array_elements(v_json->'case_components') AS component(value)
      WHERE component.value->>'finance_component_id' = v_finance_component_id::text
        AND UPPER(COALESCE(component.value->>'component_key_type', '')) = v_key_type
        AND COALESCE(component.value->>'component_key_value', '') = v_key_value
    );

  v_eligible := v_effective_section = 'canonical_preview_lines'
    AND UPPER(v_row.status) = 'READY'
    AND v_row.selected
    AND UPPER(v_row.selection_state) = 'SELECTED'
    AND v_json->'draftable' = 'true'::jsonb
    AND v_json->'is_ready_for_draft' = 'true'::jsonb
    AND v_json->'is_excluded_from_allocation' = 'false'::jsonb
    AND v_preview_contract->'ok' = 'true'::jsonb
    AND (v_overlay_valid OR v_preview_contract->'selection_allowed' = 'true'::jsonb)
    AND (NOT (v_json ? 'selection_allowed') OR v_json->'selection_allowed' = 'true'::jsonb)
    AND v_candidate_id IS NOT NULL
    AND (
      (
        v_timesheet_id IS NOT NULL
        AND v_key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
      )
      OR v_certified_finance
    )
    AND v_key_value IS NOT NULL
    AND v_pay_channel IN ('PAYE','UMBRELLA')
    AND v_line_type IS NOT NULL
    AND v_amount IS NOT NULL
    AND NOT v_synthetic_total;

  RETURN pg_catalog.jsonb_build_object(
    'eligible', v_eligible,
    'effective_section', v_effective_section,
    'overlay_valid', v_overlay_valid,
    'synthetic_resolved_total', v_synthetic_total,
    'candidate_id', v_candidate_id,
    'timesheet_id', v_timesheet_id,
    'finance_case_id', v_finance_case_id,
    'finance_component_id', v_finance_component_id,
    'certified_finance', v_certified_finance,
    'pay_channel', v_pay_channel,
    'line_type', v_line_type,
    'key_type', v_key_type,
    'key_value', v_key_value,
    'amount_ex_vat', v_amount,
    'recovery_overlay', CASE WHEN v_overlay_valid THEN v_overlay ELSE NULL END
  );
END;
$function$
;

-- [REPLACES] private.weekly_source_entitlement_publish_core_v1(p_request jsonb, p_publication_mode text, p_lock_result jsonb, p_pending_bundle_id uuid, p_worker_id text, p_worker_run_id uuid, p_census jsonb, p_proof jsonb)  winner piece A18
CREATE OR REPLACE FUNCTION private.weekly_source_entitlement_publish_core_v1(p_request jsonb, p_publication_mode text, p_lock_result jsonb, p_pending_bundle_id uuid, p_worker_id text, p_worker_run_id uuid, p_census jsonb, p_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_mode text;
  v_canonical jsonb;
  v_digest bytea;
  v_now timestamptz;
  v_err_message text;
  v_err_detail text;
  v_err_state text;
  v_bundle record;
  v_pending record;
  v_receipt record;
  v_decision_bundle_id uuid;
  v_bundle_revision bigint;
  v_candidate_id uuid;
  v_decision_id uuid;
  v_member_root_ids uuid[];
  v_member_family_booking_ids text[];
  v_member_root_versions integer[];
  v_head_ids uuid[];
  v_expected_head_ids uuid[]:=array[]::uuid[];
  v_current_head_ids uuid[]:=array[]::uuid[];
  v_prior_head_ids uuid[]:=array[]::uuid[];
  v_head_revisions bigint[]:=array[]::bigint[];
  v_n integer;
  v_i integer;
  v_control jsonb;
  v_family jsonb;
  v_member_timesheet_ids uuid[]:=array[]::uuid[];
  v_entitlement jsonb;
  v_choice jsonb;
  v_component jsonb;
  v_component_sha bytea;
  v_component_ids uuid[];
  v_before_ids uuid[];
  v_after_1 uuid[]:=array[]::uuid[];
  v_after_2 uuid[]:=array[]::uuid[];
  v_before_1 uuid[]:=array[]::uuid[];
  v_before_2 uuid[]:=array[]::uuid[];
  v_moved uuid[]:=array[]::uuid[];
  -- WP-06c review F1: the CONTENT hash the SOURCE authority holds for every
  -- component of member 1's before-position, keyed by component_id.  It is what
  -- a MOVED component must still equal on the destination side.
  v_source_component_hashes jsonb:='{}'::jsonb;
  v_moved_found integer;
  v_inventory_pairs jsonb;
  v_component_hashes jsonb;
  v_head_revision bigint;
  v_token uuid;
  v_invalidation jsonb;
  v_rows integer;
  v_live_generations integer;
  v_family_live_generations integer;
  v_family_members uuid[];
  v_any_generations integer;
  v_any_heads integer;
  v_target_auth jsonb;
  v_target_authorise_result jsonb;
  v_review jsonb;
  v_source_generation_digest bytea;
  v_contract_choice_digest bytea;
  v_before_inventory jsonb;
  v_before_inventory_digest bytea;
  v_acceptance_digest bytea;
  v_before_source text[]:=array[]::text[];
  v_effective jsonb;
  v_blank jsonb;
  v_observation_frame uuid;
  v_token_recheck uuid;
  v_declared_scope uuid[];
  v_normalised jsonb;
  v_offending jsonb;
  v_result_heads jsonb:='[]'::jsonb;
  v_lineage_rows integer:=0;
begin
  -- Service-only, exactly as public.weekly_source_timesheet_lineage_ensure_atomic_v1.
  if coalesce(
       pg_catalog.current_setting('request.jwt.claim.role',true),
       nullif(pg_catalog.current_setting('request.jwt.claims',true),'')::jsonb->>'role',
       ''
     )<>'service_role' then
    raise exception 'WEEKLY_SOURCE_SERVICE_ROLE_REQUIRED' using errcode='42501';
  end if;

  -- Shape validation and the one canonical digest.  Nothing has been written,
  -- so a malformed request is returned rather than raised.
  begin
    v_mode:=pg_catalog.upper(pg_catalog.btrim(coalesce(p_publication_mode,'')));
    if v_mode not in ('IMMEDIATE','DEFERRED') then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_publication_mode','reason','EXPECTED_IMMEDIATE_OR_DEFERRED')::text;
    end if;
    -- proof/32 section 9 and H2-038: both Worker fields are required when the
    -- mode is DEFERRED and null when it is IMMEDIATE.
    if (v_mode='DEFERRED')<>(p_worker_id is not null and p_worker_run_id is not null)
       or (v_mode='IMMEDIATE' and (p_worker_id is not null or p_worker_run_id is not null)) then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_worker_id','reason','WORKER_FIELDS_MUST_MATCH_MODE')::text;
    end if;
    if pg_catalog.jsonb_typeof(coalesce(p_census,'{}'::jsonb))<>'object'
       or pg_catalog.jsonb_typeof(coalesce(p_proof,'{}'::jsonb))<>'object' then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID'
        using errcode='22023',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID',
                'field','p_census','reason','EXPECTED_OBJECT')::text;
    end if;
    v_canonical:=private.weekly_source_publication_request_canonical_v1(
      p_request,v_mode,p_pending_bundle_id);
    v_digest:=private.weekly_source_publication_request_digest_v1(v_canonical);
  -- Review finding F10: catching only `invalid_parameter_value` let a malformed
  -- request RAISE instead of returning - an impossible calendar date (22008),
  -- an integer outside the range (22003) and a non-uuid in the control scope
  -- (22P02) all escaped.  Nothing has been written at this point, so every one
  -- of them is a returned refusal, and WP-08b no longer counts a caller's typo
  -- as a technical failure on its way to MANUAL_REVIEW.
  exception when invalid_parameter_value
              or datetime_field_overflow
              or invalid_datetime_format
              or numeric_value_out_of_range
              or invalid_text_representation then
    get stacked diagnostics v_err_message=message_text, v_err_detail=pg_exception_detail,
                            v_err_state=returned_sqlstate;
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code',case when v_err_state='22023' then v_err_message
                  else 'WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID' end,
      'retryable',false,
      'detail',case when coalesce(v_err_detail,'') ~ '^\{' then v_err_detail::jsonb
                    else pg_catalog.jsonb_build_object(
                           'reason','REQUEST_VALUE_COULD_NOT_BE_PARSED',
                           'sqlstate',v_err_state,'message',v_err_message) end);
  end;

  v_now:=pg_catalog.clock_timestamp();
  v_control:=coalesce(p_request->'control','{}'::jsonb);
  v_decision_bundle_id:=(v_canonical->>'decision_bundle_id')::uuid;
  v_bundle_revision:=(v_canonical->>'bundle_revision')::bigint;
  v_candidate_id:=(v_canonical->>'candidate_id')::uuid;
  v_decision_id:=(v_canonical->>'decision_id')::uuid;

  select pg_catalog.array_agg(root_element.value::uuid order by root_element.ordinality)
    into v_member_root_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_ids')
         with ordinality as root_element(value,ordinality);
  select pg_catalog.array_agg(booking_element.value order by booking_element.ordinality)
    into v_member_family_booking_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_family_booking_ids')
         with ordinality as booking_element(value,ordinality);
  select pg_catalog.array_agg(version_element.value::integer order by version_element.ordinality)
    into v_member_root_versions
    from pg_catalog.jsonb_array_elements_text(v_canonical->'member_root_versions')
         with ordinality as version_element(value,ordinality);
  select pg_catalog.array_agg(head_element.value::uuid order by head_element.ordinality)
    into v_head_ids
    from pg_catalog.jsonb_array_elements_text(v_canonical->'head_ids')
         with ordinality as head_element(value,ordinality);
  v_n:=pg_catalog.cardinality(v_member_root_ids);

  -- H2-032: no duplicate root and no duplicate head id.  The receipt relation
  -- repeats both rules; refusing here keeps the failure a refusal rather than a
  -- rolled-back transaction.
  if not private.weekly_source_uuid_array_is_distinct_v1(v_member_root_ids)
     or not private.weekly_source_uuid_array_is_distinct_v1(v_head_ids) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DUPLICATE_ROOT_OR_HEAD_ID'));
  end if;
  if v_n=2 and pg_catalog.btrim(v_member_family_booking_ids[1])
              =pg_catalog.btrim(v_member_family_booking_ids[2]) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','MEMBERS_SHARE_ONE_FAMILY'));
  end if;

  -- ---- 1. exact receipt replay, before any mutation (proof/32 section 8.1) --
  -- The digest is only an index lookup: every immutable receipt field is
  -- compared before a replay may be returned (H2-032).
  select * into v_receipt
    from private.weekly_source_entitlement_publication_receipts as receipt_row
   where receipt_row.request_digest=v_digest;
  if found then
    if v_receipt.decision_bundle_id<>v_decision_bundle_id
       or v_receipt.bundle_revision<>v_bundle_revision
       or v_receipt.candidate_id<>v_candidate_id
       or v_receipt.member_root_ids is distinct from v_member_root_ids
       or v_receipt.member_family_booking_ids is distinct from v_member_family_booking_ids
       or v_receipt.member_root_versions is distinct from v_member_root_versions
       or v_receipt.head_ids is distinct from v_head_ids
       or v_receipt.decision_id<>v_decision_id
       or v_receipt.publication_mode<>v_mode
       or v_receipt.pending_bundle_id is distinct from p_pending_bundle_id then
      -- Round-5 ruling A1 control 5: "conflicting replay and a tampered row are
      -- PERMANENT integrity failures and go DIRECTLY to manual review; they are
      -- not retried ten times".  The same digest over different immutable
      -- receipt fields means two different economic decisions share one money
      -- identity, which no amount of retrying can resolve.  `retryable:false`
      -- alone only stops the immediate retry; the disposition below is what
      -- tells the deferred release owner to route the bundle to MANUAL_REVIEW
      -- at once instead of counting it as one of its ten technical failures.
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REPLAY_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','A_COMMITTED_RECEIPT_CARRIES_THIS_DIGEST_WITH_DIFFERENT_IMMUTABLE_FIELDS',
          'receipt_id',v_receipt.id,
          'request_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
    return pg_catalog.jsonb_build_object(
      'ok',true,'published',true,'replayed',true,
      'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id));
  end if;

  -- ---- 2. the immutable accepted decision bundle -------------------------
  select * into v_bundle
    from public.weekly_source_entitlement_decision_bundles as bundle_row
   where bundle_row.decision_bundle_id=v_decision_bundle_id
     and bundle_row.bundle_revision=v_bundle_revision
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_FOUND',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;
  if v_bundle.candidate_id<>v_candidate_id
     or v_bundle.decision_id<>v_decision_id
     or v_bundle.proposed_head_ids is distinct from v_head_ids
     or (v_bundle.bundle_kind='SINGLE_ROOT')<>(v_n=1)
     or (v_bundle.bundle_kind='CROSS_CONTRACT_A_B')<>(v_n=2) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_DISAGREES_WITH_REQUEST',
        'bundle_kind',v_bundle.bundle_kind,'member_count',v_n));
  end if;
  if v_bundle.state not in ('PROPOSED','COMMITTED') then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','DECISION_BUNDLE_NOT_LIVE',
        'state',v_bundle.state));
  end if;
  -- Review finding F7.  The replay check above runs BEFORE the bundle lock and
  -- matches on the digest, so a SECOND, DIFFERENT request under an already
  -- COMMITTED bundle revision used to pass every pre-write check and be stopped
  -- only by the head primary key, as a raised 23505 that WP-08b would count as
  -- a technical failure.  A committed revision has had its one publication:
  -- anything that is not that exact request is refused here, with a code.
  if v_bundle.state='COMMITTED'
     and not exists (
       select 1
         from private.weekly_source_entitlement_publication_receipts as receipt_row
        where receipt_row.decision_bundle_id=v_decision_bundle_id
          and receipt_row.bundle_revision=v_bundle_revision
          and receipt_row.request_digest=v_digest) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_BUNDLE_REVISION_ALREADY_PUBLISHED','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','THIS_BUNDLE_REVISION_HAS_ALREADY_PUBLISHED_A_DIFFERENT_REQUEST',
        'decision_bundle_id',v_decision_bundle_id,'bundle_revision',v_bundle_revision));
  end if;

  -- ---- 2a0. DEFERRED mode is not trusted on the census (review U5) ---------
  -- The core's contract is "the caller ran the census", but a frozen root must
  -- never publish (24 section 4.4; proof/32 section 7, last bullet), and the
  -- reviewer executed a DEFERRED release that published with
  -- p_census = {"result":"FROZEN"} and a p_pending_bundle_id naming no row at
  -- all.  So the one step where the answer decides whether money moves is
  -- checked here as well as by the caller.
  if v_mode='DEFERRED' then
    if coalesce(p_census->>'result','')<>'RELEASABLE' then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_CENSUS_NOT_RELEASABLE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','A_DEFERRED_RELEASE_MAY_ONLY_PUBLISH_ON_A_RELEASABLE_CENSUS',
          'census_result',coalesce(p_census->'result','null'::jsonb)));
    end if;
    select * into v_pending
      from public.weekly_source_pending_entitlement_bundles as pending_row
     where pending_row.id=p_pending_bundle_id
       and pending_row.decision_bundle_id=v_decision_bundle_id
       and pending_row.bundle_revision=v_bundle_revision
       and pending_row.candidate_id=v_candidate_id
     for update;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','NO_PENDING_BUNDLE_ROW_FOR_THIS_DECISION_BUNDLE_AND_REVISION',
          'pending_bundle_id',p_pending_bundle_id,
          'decision_bundle_id',v_decision_bundle_id,
          'bundle_revision',v_bundle_revision));
    end if;
    -- Decision D10.  The migration cannot bind the pending bundle's stored
    -- request to its stored digest, because such a trigger would have to call
    -- the canonical encoder, which lives in a repeatable, and migrations are
    -- applied first: a rebuild from empty would fail.  The safety therefore
    -- belongs here, where the decision to move money is actually made.  Under
    -- the lock already held, the stored request and the stored digest are
    -- verified TOGETHER, and against the request being released.
    --
    -- Round-5 ruling A1 control 3 is exactly this: "release must lock the row,
    -- recalculate the digest from the stored canonical request and refuse
    -- BEFORE EFFECTS on any mismatch".  The row is locked `for update` above,
    -- the digest is recomputed by this coordinator from the stored request, and
    -- both refusals below happen before the first write.  Control 5 adds that a
    -- tampered row is a PERMANENT integrity failure that goes DIRECTLY to
    -- manual review, so each one carries the disposition the deferred release
    -- owner must honour instead of counting a technical failure.
    if private.weekly_source_publication_request_digest_v1(
         private.weekly_source_publication_request_canonical_v1(
           v_pending.request_json,'DEFERRED',p_pending_bundle_id))
       is distinct from v_pending.request_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_STORED_REQUEST_DOES_NOT_MATCH_ITS_STORED_DIGEST',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'recomputed_digest',pg_catalog.encode(
            private.weekly_source_publication_request_digest_v1(
              private.weekly_source_publication_request_canonical_v1(
                v_pending.request_json,'DEFERRED',p_pending_bundle_id)),'hex')));
    end if;
    if v_pending.request_digest is distinct from v_digest then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PENDING_BUNDLE_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'integrity_failure',true,'disposition','MANUAL_REVIEW',
          'reason','THE_REQUEST_BEING_RELEASED_IS_NOT_THE_ONE_THAT_WAS_SAVED',
          'pending_bundle_id',p_pending_bundle_id,
          'stored_digest',pg_catalog.encode(v_pending.request_digest,'hex'),
          'release_digest',pg_catalog.encode(v_digest,'hex')));
    end if;
  end if;

  -- ---- 2b. the accepted decision BINDS what is published (review U1) -------
  -- 24 section 4.5 step 2 and file 26 Gate 5 step 4 require the coordinator to
  -- revalidate "the current source revision, Contract choices, Candidate,
  -- Client, week, approval digest and the immutable identity of every moved
  -- component".  Quoting the right bundle id, decision id and head ids is not
  -- enough: the request must equal the accepted decision in every identity the
  -- bundle row carries, or a caller could publish a different root, Contract,
  -- week and amount of money under the Office decision's identity and actor.
  v_choice:=(
    select choice_element.value
      from pg_catalog.jsonb_array_elements(
             v_canonical->'financial_request'->'contract_choices') as choice_element(value)
     where (choice_element.value->>'root_ordinal')::integer=1);
  if v_member_root_ids[1] is distinct from v_bundle.source_root_timesheet_id
     or v_member_family_booking_ids[1] is distinct from v_bundle.source_root_family_booking_id
     or (v_choice->>'contract_id')::uuid is distinct from v_bundle.source_contract_id then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','SOURCE_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
        'accepted_root',v_bundle.source_root_timesheet_id,'requested_root',v_member_root_ids[1],
        'accepted_family',v_bundle.source_root_family_booking_id,
        'requested_family',v_member_family_booking_ids[1],
        'accepted_contract',v_bundle.source_contract_id,
        'requested_contract',v_choice->'contract_id'));
  end if;
  v_choice:=null;
  if v_n=2 then
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=2);
    if v_member_root_ids[2] is distinct from v_bundle.target_root_timesheet_id
       or v_member_family_booking_ids[2] is distinct from v_bundle.target_root_family_booking_id
       or (v_choice->>'contract_id')::uuid is distinct from v_bundle.target_contract_id then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','TARGET_ROOT_DISAGREES_WITH_ACCEPTED_DECISION',
          'accepted_root',v_bundle.target_root_timesheet_id,'requested_root',v_member_root_ids[2],
          'accepted_family',v_bundle.target_root_family_booking_id,
          'requested_family',v_member_family_booking_ids[2],
          'accepted_contract',v_bundle.target_contract_id,
          'requested_contract',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  elsif v_bundle.target_root_timesheet_id is not null
     or v_bundle.target_root_family_booking_id is not null
     or v_bundle.target_contract_id is not null then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','SINGLE_ROOT_BUNDLE_CARRIES_A_TARGET_ROOT'));
  end if;

  -- The week is the accepted decision's, and it is also each root Timesheet's
  -- own week and Contract.  One ordinary root per Candidate, Contract and week
  -- (contract section 5) only means anything if the week is checked.
  for v_i in 1..v_n loop
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);
    if (v_choice->>'week_ending_date')::date is distinct from v_bundle.week_ending_date
       or not exists (
         select 1
           from public.timesheets as root_row
          where root_row.timesheet_id=v_member_root_ids[v_i]
            and root_row.week_ending_date=v_bundle.week_ending_date
            and root_row.contract_id=(v_choice->>'contract_id')::uuid) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','WEEK_OR_CONTRACT_DISAGREES_WITH_ACCEPTED_DECISION',
          'root_ordinal',v_i,'accepted_week',v_bundle.week_ending_date,
          'requested_week',v_choice->'week_ending_date',
          'requested_contract',v_choice->'contract_id'));
    end if;
    -- The Candidate must actually OWN the root.  The reviewer published a head,
    -- a receipt and an invalidation under a second Candidate for a root it did
    -- not own: the installed invalidator's ownership rule fires only when a
    -- current TSFIN row exists, so the coordinator checks the Contract itself
    -- rather than leaving it to I-1 or to Banking Pay.
    if not exists (
      select 1
        from public.contracts as contract_row
       where contract_row.id=(v_choice->>'contract_id')::uuid
         and contract_row.candidate_id=v_candidate_id) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','CANDIDATE_DOES_NOT_OWN_THE_ROOT',
          'root_ordinal',v_i,'candidate_id',v_candidate_id,
          'contract_id',v_choice->'contract_id'));
    end if;
    v_choice:=null;
  end loop;

  -- The three approval digests the bundle row carries, recomputed here with the
  -- one canonical encoder.  These are mode-independent by construction, so the
  -- same values bind an immediate publication and a deferred release.
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');
  v_contract_choice_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'contract_choices');
  v_before_inventory:=private.weekly_source_publication_before_inventory_v1(v_control,v_n);
  v_before_inventory_digest:=private.weekly_source_publication_request_digest_v1(v_before_inventory);
  -- The acceptance digest: the canonical request in IMMEDIATE mode with no
  -- pending bundle.  publication_mode and pending_bundle_id are digest fields
  -- (proof/32 section 9), so the digest the RECEIPT carries changes with the
  -- mode and cannot be the one stored on the accepted decision.  The bundle
  -- row's request_digest is therefore always taken in IMMEDIATE/null, which is
  -- what the proposal composer can compute at proposal time, before any pending
  -- bundle exists.  Written into interfaces\PUBLICATION_REQUEST_SHAPE.md.
  v_acceptance_digest:=private.weekly_source_publication_request_digest_v1(
    private.weekly_source_publication_request_canonical_v1(p_request,'IMMEDIATE',null::uuid));
  if v_bundle.source_revision_digest is distinct from v_source_generation_digest
     or v_bundle.contract_choice_digest is distinct from v_contract_choice_digest
     or v_bundle.before_inventory_digest is distinct from v_before_inventory_digest
     or v_bundle.request_digest is distinct from v_acceptance_digest then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','APPROVAL_DIGESTS_DISAGREE_WITH_ACCEPTED_DECISION',
        'source_revision_digest_matches',
          v_bundle.source_revision_digest is not distinct from v_source_generation_digest,
        'contract_choice_digest_matches',
          v_bundle.contract_choice_digest is not distinct from v_contract_choice_digest,
        'before_inventory_digest_matches',
          v_bundle.before_inventory_digest is not distinct from v_before_inventory_digest,
        'request_digest_matches',
          v_bundle.request_digest is not distinct from v_acceptance_digest));
  end if;

  -- ---- 2a. the current source revision (24 section 4.5 step 2; R7) --------
  -- "revalidate the current source revision".  A head built from a superseded
  -- or merely prepared final revision must never become current.
  if not exists (
    select 1
      from public.weekly_source_final_revisions as revision_row
     where revision_row.id=(v_canonical->'financial_request'->'source_revision'->>'final_revision_id')::uuid
       and revision_row.source_cycle_id=(v_canonical->'financial_request'->'source_revision'->>'source_cycle_id')::uuid
       and revision_row.revision_number=(v_canonical->'financial_request'->'source_revision'->>'revision_number')::integer
       and revision_row.state='CURRENT'
       and pg_catalog.encode(revision_row.manifest_hash,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'manifest_hash')
       and pg_catalog.encode(revision_row.policy_fingerprint,'hex')
           =(v_canonical->'financial_request'->'source_revision'->>'policy_fingerprint')
  ) then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_SOURCE_REVISION_STALE','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'source_revision',v_canonical->'financial_request'->'source_revision'));
  end if;

  -- ---- 3. member identity against the I-1 lock result ---------------------
  -- proof/32 section 4.0 integrity gate; proof/34 section 6: after first
  -- authorisation an unexpected rotation is an INTEGRITY FAILURE, never a stale
  -- rebuild.  This coordinator never rebuilds anything.
  if p_lock_result is null
     or pg_catalog.jsonb_typeof(p_lock_result)<>'object'
     or coalesce((p_lock_result->>'ok')::boolean,false) is not true
     or coalesce(p_lock_result->>'gate','')<>'GRANTED' then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object('reason','LOCK_RESULT_NOT_GRANTED'));
  end if;

  for v_i in 1..v_n loop
    select family_element.value into v_family
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    if v_family is null
       or coalesce((v_family->>'requested_is_canonical')::boolean,false) is not true
       or coalesce((v_family->>'family_is_current')::boolean,false) is not true
       or (v_family->>'canonical_timesheet_id')::uuid is distinct from v_member_root_ids[v_i]
       or (v_family->>'canonical_version')::integer is distinct from v_member_root_versions[v_i]
       or pg_catalog.btrim(coalesce(v_family->>'family_booking_id',''))
          is distinct from pg_catalog.btrim(v_member_family_booking_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'requested_timesheet_id',v_member_root_ids[v_i],
          'lock_result_family',v_family));
    end if;
    select v_member_timesheet_ids||coalesce(
             pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_member_timesheet_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce(v_family->'member_timesheet_ids','[]'::jsonb)) as member_element(value);

    -- WP-01a review U1: `root_family_booking_id` is free text on the head row and
    -- nothing in the schema ties it to the root's real booking_id, so the
    -- coordinator validates it itself.  The raw value must equal
    -- public.timesheets.booking_id of the canonical root BYTE FOR BYTE: the
    -- trimmed form is the lock and index key (proof/32 section 6 step 2), not an
    -- identity, and a differently cased or unrelated string would take a
    -- different advisory lock from the one protecting the uniqueness index.
    if not exists (
      select 1
        from public.timesheets as root_row
       where root_row.timesheet_id=v_member_root_ids[v_i]
         and root_row.booking_id=v_member_family_booking_ids[v_i]
         and root_row.version=v_member_root_versions[v_i]
         and root_row.is_current) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','FAMILY_BOOKING_ID_DOES_NOT_MATCH_THE_ROOT',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'declared_version',v_member_root_versions[v_i]));
    end if;
    v_family:=null;
  end loop;

  -- ---- 4. compare-and-swap on each member's expected current head ---------
  -- jsonb_array_elements_text turns a JSON null into a SQL NULL, which is
  -- exactly "the caller believes this root has no committed head yet".
  select pg_catalog.array_agg(expected_element.value::uuid
                              order by expected_element.ordinality)
    into v_expected_head_ids
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'expected_current_head_ids','[]'::jsonb))
         with ordinality as expected_element(value,ordinality);
  if coalesce(pg_catalog.cardinality(v_expected_head_ids),0)<>v_n then
    return pg_catalog.jsonb_build_object(
      'ok',false,'published',false,'replayed',false,
      'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
      'detail',pg_catalog.jsonb_build_object(
        'reason','EXPECTED_CURRENT_HEAD_IDS_NOT_ALIGNED'));
  end if;

  for v_i in 1..v_n loop
    -- One committed current head per root across both authority kinds
    -- (24 section 4.3), read under lock (H2-024).
    --
    -- WP-01a review U1: "at most one committed current head" is a partial unique
    -- index on the TRIMMED family string only, so it is not a schema guarantee
    -- for a physical root.  The coordinator therefore counts the rows itself,
    -- refuses more than one as an integrity failure rather than choosing one,
    -- and asserts that the head it found belongs to the canonical root I-1
    -- resolved.  It never falls back to stale TSFIN (27 section 5.1).
    select pg_catalog.count(*)::integer into v_rows
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       and head_row.state='COMMITTED_CURRENT';
    if v_rows>1 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','MORE_THAN_ONE_COMMITTED_CURRENT_HEAD',
          'root_ordinal',v_i,'committed_current_heads',v_rows));
    end if;
    v_current_head_ids:=v_current_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
         and head_row.state='COMMITTED_CURRENT'
         for update);
    if v_current_head_ids[v_i] is not null
       and not exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.id=v_current_head_ids[v_i]
            and head_row.root_timesheet_id=v_member_root_ids[v_i]) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_BELONGS_TO_ANOTHER_PHYSICAL_ROOT',
          'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
    end if;
    -- The MIRROR of the guard above, and the same defect class as WP-06 review
    -- finding F2: the family key found no head, but the PHYSICAL root carries
    -- one.  Since schema change S8 removed unique(root_timesheet_id) from the
    -- family relation, nothing keyed on the physical id is unique any more, so
    -- the two identities really can disagree.  Falling through here would take a
    -- TSFIN — or an unproved — before-position for a root that demonstrably HAS
    -- a committed head, understating the effective entitlement, which is exactly
    -- how a residual turns into an overpayment.  It costs one indexed lookup
    -- (weekly_source_entitlement_heads_committed_root_uq), so it is checked
    -- rather than assumed, and it is checked HERE so it covers the I-7 branch
    -- and the no-I-7 branch alike.
    if v_current_head_ids[v_i] is null
       and exists (
         select 1
           from public.weekly_source_entitlement_heads as head_row
          where head_row.root_timesheet_id=v_member_root_ids[v_i]
            and head_row.state='COMMITTED_CURRENT') then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','COMMITTED_HEAD_EXISTS_FOR_THE_PHYSICAL_ROOT_BUT_NOT_THE_DECLARED_FAMILY',
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'declared_family_booking_id',v_member_family_booking_ids[v_i],
          'physical_root_head_id',(
            select head_row.id
              from public.weekly_source_entitlement_heads as head_row
             where head_row.root_timesheet_id=v_member_root_ids[v_i]
               and head_row.state='COMMITTED_CURRENT')));
    end if;
    if v_current_head_ids[v_i] is distinct from v_expected_head_ids[v_i] then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_HEAD_CAS_CONFLICT','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,
          'expected_current_head_id',v_expected_head_ids[v_i],
          'actual_current_head_id',v_current_head_ids[v_i]));
    end if;
    select coalesce(pg_catalog.max(head_row.head_revision),0)+1
      into v_head_revision
      from public.weekly_source_entitlement_heads as head_row
     where pg_catalog.btrim(head_row.root_family_booking_id)
           =pg_catalog.btrim(v_member_family_booking_ids[v_i]);
    v_head_revisions:=v_head_revisions||v_head_revision;
    v_prior_head_ids:=v_prior_head_ids||(
      select head_row.id
        from public.weekly_source_entitlement_heads as head_row
       where pg_catalog.btrim(head_row.root_family_booking_id)
             =pg_catalog.btrim(v_member_family_booking_ids[v_i])
       order by head_row.head_revision desc
       limit 1);
  end loop;

  -- ---- 5. the complete post-decision head proofs (H2-024) -----------------
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    select coalesce(pg_catalog.array_agg(
             (component_element.value->>'component_id')::uuid
             order by (component_element.value->>'component_ordinal')::integer),
             array[]::uuid[])
      into v_component_ids
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    select coalesce(pg_catalog.array_agg(before_element.value::uuid),array[]::uuid[])
      into v_before_ids
      from pg_catalog.jsonb_array_elements_text(
             coalesce((select position_element.value->'component_ids'
                         from pg_catalog.jsonb_array_elements(
                                coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
                        where (position_element.value->>'root_ordinal')::integer=v_i),
                      'null'::jsonb)) as before_element(value);
    if (select position_element.value
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_control->'before_positions','[]'::jsonb)) as position_element(value)
         where (position_element.value->>'root_ordinal')::integer=v_i) is null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','BEFORE_POSITION_MISSING','root_ordinal',v_i));
    end if;

    -- A head may never contain an adjustment, whatever key it arrives under
    -- (24 section 5; WB-007, WB-013; review U3 case H6c).  component_kind,
    -- economic_key_type and origin are free text on the relation, so the
    -- coordinator allowlists the kind and refuses the adjustment vocabulary
    -- outright rather than trusting the absence of an `adjustment_id` key.
    v_offending:=(
      select component_element.value
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_kind') not in
               ('WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')
          or component_element.value->>'component_kind' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'economic_key_type' ~* 'ADJUST|ADVANCE'
          or component_element.value->>'origin' ~* 'ADJUST|ADVANCE'
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_COMPONENT_KIND_FORBIDDEN','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'component',v_offending,
          'permitted_kinds',pg_catalog.jsonb_build_array(
            'WORKED_TIME','ADDITIONAL_UNIT','SOURCE_FIXED_EXPENSE')));
    end if;
    v_offending:=null;

    -- H2-024: "each before-position is read from the single committed effective
    -- authority under lock".  Three cases, and only the third is ever accepted
    -- without a server-side read (review U3).
    if v_current_head_ids[v_i] is not null then
      -- (1) A committed head exists: the declared position must equal its
      -- component set EXACTLY, and every RETAINED component must be
      -- byte-identical - the committed row stores component_sha256, so
      -- re-pricing a component that is merely "kept by id" is detectable and
      -- is refused (review U3 cases H10 and H4c).
      if exists (
        select 1
          from (select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select component_row.component_id
                  from public.weekly_source_entitlement_head_components as component_row
                 where component_row.head_id=v_current_head_ids[v_i]) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'current_head_id',v_current_head_ids[v_i]));
      end if;
      -- `component_sha256` is a CONTENT identity and deliberately excludes
      -- `component_ordinal`: the ordinal is the component's position inside a
      -- head, and a component that is retained while another moves out from in
      -- front of it legitimately changes position.  Position is still covered,
      -- by `inventory_digest` (the ordered ordinal/id pairs) and by
      -- `entitlement_digest` (the content hashes in ordinal order).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'committed_sha256',pg_catalog.encode(committed_row.component_sha256,'hex'),
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join public.weekly_source_entitlement_head_components as committed_row
            on committed_row.head_id=v_current_head_ids[v_i]
           and committed_row.component_id=(component_element.value->>'component_id')::uuid
         where committed_row.component_sha256
               is distinct from private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value))
         limit 1);
      if v_offending is not null then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i,'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1: member 1 is the SOURCE of a cross-Contract move, so
      -- its committed head is the authority for what every MOVED component
      -- actually held.  The content hashes are taken here, under the same lock
      -- and from the same rows the retained check just used, and are compared
      -- against the destination side after the set proofs.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 committed_row.component_id::text,
                 pg_catalog.encode(committed_row.component_sha256,'hex')),'{}'::jsonb)
          into v_source_component_hashes
          from public.weekly_source_entitlement_head_components as committed_row
         where committed_row.head_id=v_current_head_ids[v_i];
      end if;
      v_before_source:=v_before_source||'HEAD'::text;

    elsif pg_catalog.to_regprocedure(
            'private.weekly_source_effective_inventory_v1(uuid)') is not null then
      -- (2) No head yet, but interface I-7 exists (decision D9, built by WP-06):
      -- the before-position is derived SERVER-SIDE from the single committed
      -- effective authority - the ordinary financial snapshot - under the same
      -- locks, and the declared position must equal it.
      v_effective:=private.weekly_source_effective_inventory_v1(v_member_root_ids[v_i]);
      if coalesce(pg_catalog.jsonb_typeof(v_effective),'')<>'object' then
        raise exception 'WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID'
          using errcode='55000',
                detail=pg_catalog.jsonb_build_object(
                  'code','WEEKLY_SOURCE_PUBLICATION_EFFECTIVE_INVENTORY_INVALID',
                  'root_ordinal',v_i,'result',v_effective)::text;
      end if;
      -- I-7 answers `ok:false` with an EMPTY components array when it cannot
      -- resolve the root.  Reading that as "the root holds nothing" would turn
      -- an integrity failure into a silent certified-zero publication, so the
      -- refusal is honoured before the sets are compared at all.
      if coalesce((v_effective->>'ok')::boolean,false) is not true then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REFUSED_THE_ROOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'effective_inventory',v_effective));
      end if;
      -- I-7 is reached ONLY when the family key above found no committed head,
      -- so the only authority it can legitimately report here is the ordinary
      -- financial snapshot.  If it reports a HEAD, the two keyings disagree
      -- about the same root — the shape of WP-06 review finding F2, in whichever
      -- direction the disagreement runs — and the coordinator must not pick a
      -- winner between them.  It refuses, cheaply, on a field it already holds.
      if v_effective->>'authority' is distinct from 'TSFIN' then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_ROOT_INTEGRITY_FAILURE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','INTERFACE_I7_REPORTS_AN_AUTHORITY_THE_FAMILY_KEY_DOES_NOT',
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'declared_family_booking_id',v_member_family_booking_ids[v_i],
            'i7_authority',v_effective->'authority','i7_head_id',v_effective->'head_id'));
      end if;
      if exists (
        select 1
          from (select (effective_element.value->>'component_id')::uuid as component_id
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
                except
                select pg_catalog.unnest(v_before_ids)) as missing_from_declared
        union all
        select 1
          from (select pg_catalog.unnest(v_before_ids)
                except
                select (effective_element.value->>'component_id')::uuid
                  from pg_catalog.jsonb_array_elements(
                         coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)) as extra_in_declared
      ) then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_MISMATCH','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'reason','DECLARED_POSITION_DIFFERS_FROM_THE_EFFECTIVE_INVENTORY'));
      end if;
      -- I-7 also carries each component's content hash, so a component RETAINED
      -- from a head-less root gets the same byte-identity guarantee as one
      -- retained from a committed head (review finding U3(a), extended).
      v_offending:=(
        select pg_catalog.jsonb_build_object(
                 'component_id',component_element.value->'component_id',
                 'effective_sha256',effective_element.value->'component_sha256',
                 'requested_sha256',pg_catalog.encode(
                   private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(
                       component_element.value)),'hex'))
          from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
          join pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value)
            on effective_element.value->>'component_id'=component_element.value->>'component_id'
         where effective_element.value->>'component_sha256'
               is distinct from pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex')
         limit 1);
      if v_offending is not null then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_RETAINED_COMPONENT_CHANGED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'authority',v_effective->'authority',
            'component',v_offending));
      end if;
      v_offending:=null;
      -- WP-06c review F1, the head-less source: I-7 carries each component's
      -- own content hash, computed through this file's canonicaliser, content
      -- projection and encoder, so it is directly comparable with a committed
      -- head row's `component_sha256` and with the destination side.
      if v_i=1 then
        select coalesce(pg_catalog.jsonb_object_agg(
                 effective_element.value->>'component_id',
                 effective_element.value->'component_sha256'),'{}'::jsonb)
          into v_source_component_hashes
          from pg_catalog.jsonb_array_elements(
                 coalesce(v_effective->'components','[]'::jsonb)) as effective_element(value);
      end if;
      v_before_source:=v_before_source||'I7'::text;

    else
      -- (3) No head and no I-7.  The declared position cannot be proved, so it
      -- is never recorded as if it were.  An A-to-B bundle is REFUSED rather
      -- than published on an unverified before-position, because that is where
      -- "minus only the moved components" and "keeps every existing component"
      -- would otherwise rest on the caller's word (review U3 case G1-a).
      if v_n=2 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_BEFORE_POSITION_UNPROVABLE','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
            'reason','NO_COMMITTED_HEAD_AND_INTERFACE_I7_IS_NOT_INSTALLED',
            'required_owner','private.weekly_source_effective_inventory_v1(uuid)'));
      end if;
      v_before_source:=v_before_source||'DECLARED_UNPROVED'::text;
    end if;

    if v_i=1 then
      v_after_1:=v_component_ids; v_before_1:=v_before_ids;
    else
      v_after_2:=v_component_ids; v_before_2:=v_before_ids;
    end if;
    v_entitlement:=null;
  end loop;

  select coalesce(pg_catalog.array_agg(moved_element.value::uuid),array[]::uuid[])
    into v_moved
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_control->'moved_component_ids','[]'::jsonb)) as moved_element(value);

  if v_n=1 then
    if pg_catalog.cardinality(v_moved)>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('reason','MOVED_SET_ON_SINGLE_ROOT_BUNDLE'));
    end if;
  else
    -- "an already-authorised B keeps EVERY existing component" (24 section 4.5
    -- step 3).  This is tested FIRST so that a B which loses one gets the exact
    -- code the interface documents.  Placed after the combined set proof it was
    -- unreachable, because `B-after = B-before union moved` already implies
    -- `B-before is a subset of B-after` (review finding F12).
    if pg_catalog.cardinality(
         private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))>0 then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_COMPONENT_DROPPED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'dropped',pg_catalog.to_jsonb(
            private.weekly_source_uuid_set_difference_v1(v_before_2,v_after_2))));
    end if;
    -- 24 section 4.5 step 3 and H2-024, proved in the same transaction.
    if pg_catalog.cardinality(v_moved)=0
       or not private.weekly_source_uuid_array_is_distinct_v1(v_moved)
       or private.weekly_source_uuid_set_equals_v1(
            v_before_1,private.weekly_source_uuid_set_union_v1(v_after_1,v_moved)) is not true
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_after_1,v_moved))>0
       or pg_catalog.cardinality(private.weekly_source_uuid_set_intersect_v1(v_before_2,v_moved))>0
       or private.weekly_source_uuid_set_equals_v1(
            v_after_2,private.weekly_source_uuid_set_union_v1(v_before_2,v_moved)) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'a_before',pg_catalog.to_jsonb(v_before_1),'a_after',pg_catalog.to_jsonb(v_after_1),
          'b_before',pg_catalog.to_jsonb(v_before_2),'b_after',pg_catalog.to_jsonb(v_after_2),
          'moved',pg_catalog.to_jsonb(v_moved)));
    end if;

    -- Round-5 ruling, Part E, "Partial Contract-to-Contract move":
    --
    --   "Not in scope for this release.  The supported operation is the
    --    whole-entitlement move.  A requested partial move must take the named
    --    fail-closed path and explain that partial movement is unsupported; it
    --    must not approximate the move."
    --
    -- THE DEFINITION IS THE WHOLE OF THE RULE.  A move is WHOLE when the source
    -- member retains nothing after it, and PARTIAL otherwise.  Three statements
    -- of that are available here and they are the SAME statement, because the
    -- set proofs immediately above have already established
    -- `A_after = A_before \ moved`:
    --
    --   (i)   A-after is empty                     -> cardinality(v_after_1)=0
    --   (ii)  every component of A-before moved    -> moved = A_before
    --   (iii) member 1 is certified zero           -> the declared flag, which
    --         the coordinator re-checks against `component_count` below and
    --         which the head relation's own CHECK enforces
    --
    -- (i) is the one tested, because it is read from what the request actually
    -- carries rather than from a flag the caller sets.  (ii) is asserted
    -- alongside it: if the two ever disagreed, the set proofs above would have
    -- been wrong, so the disagreement is itself refused rather than resolved.
    --
    -- This is a SCOPE gate, so it is tested before the content proof below: a
    -- partial move is refused for being partial, in plain English, not for a
    -- hash mismatch it may not even have.  It is a returned refusal before the
    -- first write, exactly like every other check in this section.
    if pg_catalog.cardinality(v_after_1)>0
       or private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1) is not true then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_PARTIAL_MOVE_UNSUPPORTED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','ONLY_A_WHOLE_ENTITLEMENT_MOVE_IS_SUPPORTED_IN_THIS_RELEASE',
          'message','This bundle moves only part of the entitlement from one Contract '
                  ||'to the other and leaves the rest behind. Moving part of an '
                  ||'entitlement is not supported in this release: a Contract-to-Contract '
                  ||'amendment must move the whole entitlement, so that the old Contract '
                  ||'is left holding nothing. Nothing has been published. Either move '
                  ||'every component of the old Contract''s entitlement, or leave the '
                  ||'entitlement where it is.',
          'definition','A move is WHOLE when the source root retains nothing after it.',
          'a_before',pg_catalog.to_jsonb(v_before_1),
          'a_after',pg_catalog.to_jsonb(v_after_1),
          'a_after_component_count',pg_catalog.cardinality(v_after_1),
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_is_the_whole_source_position',
            private.weekly_source_uuid_set_equals_v1(v_moved,v_before_1)));
    end if;

    -- WP-06c review finding F1 (HIGH).  Everything above proves the move by
    -- IDENTITY.  A moved component's CONTENT was never compared with anything:
    -- it is absent from A-after and from B-before, so neither retained-component
    -- check above joins it, and a request composed outside the builder could
    -- re-price a shift on its way from A to B and be published with a receipt
    -- (executed: 85.50 -> 850.50 and 4.25 -> 40 hours).  The coordinator is the
    -- last gate before an entitlement is published, so it verifies rather than
    -- trusts: every moved component must still equal, byte for byte, what the
    -- SOURCE authority actually held - A's committed head row's
    -- `component_sha256` where A has a head, else interface I-7's own content
    -- hash for the same component.  `24 section 4.5` step 3 is "B-after is B's
    -- previously effective complete entitlement plus only those component(s)" -
    -- THOSE components, not components with those identities.
    --
    -- The comparison uses the same content projection as the retained checks, so
    -- `component_ordinal`, `movement_id` and `movement_group_id` - the three
    -- things a move legitimately changes - are excluded, and nothing else is.
    -- A moved component the source authority does not carry at all has a null
    -- hash here and is refused by the same test (`is distinct from`).
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=2);
    select pg_catalog.count(*)::integer into v_moved_found
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
     where (component_element.value->>'component_id')::uuid=any(v_moved);
    if v_moved_found<>pg_catalog.cardinality(v_moved) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVE_SET_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'reason','THE_DESTINATION_DOES_NOT_CARRY_EACH_MOVED_COMPONENT_EXACTLY_ONCE',
          'moved',pg_catalog.to_jsonb(v_moved),
          'moved_components_in_b_after',v_moved_found));
    end if;
    v_offending:=(
      select pg_catalog.jsonb_build_object(
               'component_id',component_element.value->'component_id',
               'source_authority',v_before_source[1],
               'source_sha256',pg_catalog.to_jsonb(
                 v_source_component_hashes->>(component_element.value->>'component_id')),
               'requested_sha256',pg_catalog.encode(
                 private.weekly_source_publication_request_digest_v1(
                   private.weekly_source_publication_component_content_v1(
                     component_element.value)),'hex'))
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where (component_element.value->>'component_id')::uuid=any(v_moved)
         and (v_source_component_hashes->>(component_element.value->>'component_id'))
             is distinct from pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                 private.weekly_source_publication_component_content_v1(
                   component_element.value)),'hex')
       limit 1);
    if v_offending is not null then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVED_COMPONENT_CHANGED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',2,'component',v_offending));
    end if;
    v_offending:=null;
    v_entitlement:=null;
  end if;

  -- Movement identity: every moved component carries movement_id in its
  -- destination head and no retained component carries one.
  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
       where ((component_element.value->>'component_id')::uuid=any(v_moved)
              and v_i=2
              and component_element.value->'movement_id'='null'::jsonb)
          or (not ((component_element.value->>'component_id')::uuid=any(v_moved) and v_i=2)
              and component_element.value->'movement_id'<>'null'::jsonb)
    ) then
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_MOVEMENT_IDENTITY_INVALID','retryable',false,
        'detail',pg_catalog.jsonb_build_object('root_ordinal',v_i));
    end if;
    v_entitlement:=null;
  end loop;

  -- ---- 6. the target root's authorisation state ---------------------------
  v_target_auth:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'target_root_authorisation','null'::jsonb))='object'
                      then v_control->'target_root_authorisation' end;
  v_review:=case when pg_catalog.jsonb_typeof(coalesce(v_control->'whole_root_office_review','null'::jsonb))='object'
                 then v_control->'whole_root_office_review' end;

  for v_i in 1..v_n loop
    -- Decision D8: the authorisation record is per ROOT and lives in
    -- public.weekly_source_root_authorisations, keyed on the physical
    -- root_timesheet_id, with at most one live generation per root.  It is no
    -- longer the per-source-row lineage binding.
    select pg_catalog.count(*)::integer into v_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
       and authorisation_row.withdrawn_at_utc is null;

    -- WP-07 review finding F2, answered from THIS side of the seam.  The
    -- authorisation record is keyed on the PHYSICAL root_timesheet_id, and since
    -- schema change S8 removed the physical uniqueness a single family can hold
    -- several of them.  A test that counts only the canonical root's own
    -- generations lets a ROTATED family whose NON-CANONICAL member is already
    -- authorised be authorised a second time; the root is then payable and
    -- carries two live generations, which every withdrawal path treats as an
    -- impossible state, so it can never be withdrawn again.
    --
    -- The "is it already authorised?" test is therefore over the whole FAMILY:
    -- every member Timesheet the lock result carries for this root, and the
    -- family booking id the authorisation row itself records.  The coordinator
    -- does not rely on interface I-6 having been widened to match — that is
    -- precisely the assumption this finding punished.
    select coalesce(pg_catalog.array_agg(member_element.value::uuid),array[]::uuid[])
      into v_family_members
      from pg_catalog.jsonb_array_elements(p_lock_result->'families') as family_element(value)
     cross join pg_catalog.jsonb_array_elements_text(
                  coalesce(family_element.value->'member_timesheet_ids','[]'::jsonb))
                as member_element(value)
     where family_element.value->>'requested_timesheet_id'=v_member_root_ids[v_i]::text;
    select pg_catalog.count(*)::integer into v_family_live_generations
      from public.weekly_source_root_authorisations as authorisation_row
     where authorisation_row.withdrawn_at_utc is null
       and (authorisation_row.root_timesheet_id=v_member_root_ids[v_i]
            or authorisation_row.root_timesheet_id=any(v_family_members)
            or pg_catalog.btrim(authorisation_row.family_booking_id)
               =pg_catalog.btrim(v_member_family_booking_ids[v_i]));

    if v_i=2 and v_target_auth is not null then
      -- 24 section 4.5 step 4: only a genuinely new, never-authorised B root is
      -- created and authorised here, and it is never authorised silently.
      if v_family_live_generations>0 then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ALREADY_AUTHORISED','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'live_generations',v_family_live_generations,
            'live_generations_on_this_physical_root',v_live_generations,
            'root_timesheet_id',v_member_root_ids[v_i],
            'family_booking_id',v_member_family_booking_ids[v_i],
            'family_member_timesheet_ids',pg_catalog.to_jsonb(v_family_members)));
      end if;
      if (v_target_auth->>'timesheet_id')::uuid is distinct from v_member_root_ids[2] then
        return pg_catalog.jsonb_build_object(
          'ok',false,'published',false,'replayed',false,
          'code','WEEKLY_SOURCE_PUBLICATION_REQUEST_INVALID','retryable',false,
          'detail',pg_catalog.jsonb_build_object(
            'reason','TARGET_AUTHORISATION_TIMESHEET_MISMATCH'));
      end if;

      -- Review U2.  "Unknown to Weekly Source" is NOT the same as "blank": a B
      -- Timesheet that already existed, was never touched by Weekly Source and
      -- carries its own unrelated shifts satisfied the old test and was
      -- authorised silently, which 24 section 4.5 step 4, file 26 Gate 5 step 6,
      -- 27 section 8 step 6 and H2-024 all forbid.  B is now treated as
      -- genuinely new only when it is provably blank as well as unknown.
      v_blank:=private.weekly_source_publication_target_root_blank_v1(
        v_member_root_ids[2],v_member_family_booking_ids[2]);
      if coalesce((v_blank->>'blank')::boolean,false) is not true then
        -- The whole-root Office review is the only way past this, and it is a
        -- real control or it is nothing: a genuine boolean true, an existing
        -- reviewer, a time, bound to the accepted decision, and PERSISTED on
        -- the accepted decision so the act can be shown afterwards.  The three
        -- identity columns now exist on the bundle relation, so the check is
        -- the real one: the ACCEPTED DECISION must carry the review, and the
        -- request must quote exactly what it carries.
        if v_bundle.whole_root_review_required is not true
           or v_bundle.whole_root_reviewed_by_user_id is null
           or v_bundle.whole_root_reviewed_at_utc is null then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','THE_ACCEPTED_DECISION_CARRIES_NO_WHOLE_ROOT_OFFICE_REVIEW',
              'blank_check',v_blank,
              'decision_bundle_id',v_decision_bundle_id,
              'bundle_revision',v_bundle_revision));
        end if;
        -- The request's own review object: a real boolean, a real reviewer, a
        -- real time, and bound to this accepted decision.
        if v_review is null
           or pg_catalog.jsonb_typeof(v_review->'reviewed')<>'boolean'
           or (v_review->'reviewed')::boolean is not true
           or (v_review->>'reviewed_by_user_id') is null
           or (v_review->>'reviewed_at_utc') is null
           or (v_review->>'decision_id')::uuid is distinct from v_decision_id then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','WHOLE_ROOT_OFFICE_REVIEW_MISSING_OR_MALFORMED',
              'blank_check',v_blank,'review',v_review));
        end if;
        -- And it must be the review the ACCEPTED DECISION carries, not one the
        -- caller invented for this request.  The reviewer's existence is the
        -- bundle column's own foreign key, so it is proved by the row, not
        -- re-checked here.
        if (v_review->>'reviewed_by_user_id')::uuid
             is distinct from v_bundle.whole_root_reviewed_by_user_id
           or (v_review->>'reviewed_at_utc')::timestamptz
                is distinct from v_bundle.whole_root_reviewed_at_utc then
          return pg_catalog.jsonb_build_object(
            'ok',false,'published',false,'replayed',false,
            'code','WEEKLY_SOURCE_PUBLICATION_TARGET_ROOT_REVIEW_REQUIRED','retryable',false,
            'detail',pg_catalog.jsonb_build_object(
              'reason','REVIEW_IS_NOT_THE_ONE_ON_THE_ACCEPTED_DECISION',
              'accepted_reviewer',v_bundle.whole_root_reviewed_by_user_id,
              'requested_reviewer',v_review->'reviewed_by_user_id'));
        end if;
      end if;
    elsif v_live_generations=0 then
      -- A head over a root Weekly Source has not authorised would never reach
      -- payroll, so it is refused rather than written (decision D8: the live
      -- authorisation row is the test).
      return pg_catalog.jsonb_build_object(
        'ok',false,'published',false,'replayed',false,
        'code','WEEKLY_SOURCE_PUBLICATION_TARGET_NOT_AUTHORISED','retryable',false,
        'detail',pg_catalog.jsonb_build_object(
          'root_ordinal',v_i,'root_timesheet_id',v_member_root_ids[v_i],
          'family_booking_id',v_member_family_booking_ids[v_i]));
    end if;
  end loop;

  -- =========================================================================
  -- Everything from here writes.  Every failure below RAISES and rolls the
  -- whole transaction back: no head, pointer, invalidation, dirty job, B
  -- authorisation or receipt may survive (R11; 26 Gate 5 pass condition).
  -- =========================================================================

  -- Observe exact writes in this invocation, not differences against global history.
  v_observation_frame:=private.weekly_source_observation_begin_v1();

  -- ---- 7. stage every member head and its complete component inventory ----
  v_source_generation_digest:=private.weekly_source_publication_request_digest_v1(
    v_canonical->'financial_request'->'source_revision');

  for v_i in 1..v_n loop
    v_entitlement:=(
      select entitlement_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'member_entitlements') as entitlement_element(value)
       where (entitlement_element.value->>'root_ordinal')::integer=v_i);
    v_choice:=(
      select choice_element.value
        from pg_catalog.jsonb_array_elements(
               v_canonical->'financial_request'->'contract_choices') as choice_element(value)
       where (choice_element.value->>'root_ordinal')::integer=v_i);

    select coalesce(pg_catalog.jsonb_agg(
             pg_catalog.jsonb_build_object(
               'component_ordinal',component_element.value->'component_ordinal',
               'component_id',component_element.value->'component_id')
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb),
           coalesce(pg_catalog.jsonb_agg(
             pg_catalog.to_jsonb(pg_catalog.encode(
               private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),'hex'))
             order by (component_element.value->>'component_ordinal')::integer),'[]'::jsonb)
      into v_inventory_pairs,v_component_hashes
      from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value);

    insert into public.weekly_source_entitlement_heads(
      id,authority_kind,agency_id,candidate_id,contract_id,week_ending_date,
      root_timesheet_id,root_family_booking_id,root_timesheet_version,head_revision,
      prior_head_id,state,certified_zero,component_count,entitlement_digest,inventory_digest,
      source_generation_digest,decision_bundle_id,bundle_revision,decision_id,
      decided_by_user_id,staged_at_utc,created_at_utc
    ) values (
      v_head_ids[v_i],
      v_entitlement->>'authority_kind',
      v_bundle.agency_id,
      v_candidate_id,
      (v_choice->>'contract_id')::uuid,
      (v_choice->>'week_ending_date')::date,
      v_member_root_ids[v_i],
      v_member_family_booking_ids[v_i],
      v_member_root_versions[v_i],
      v_head_revisions[v_i],
      v_prior_head_ids[v_i],
      'STAGED',
      (v_entitlement->>'certified_zero')::boolean,
      (v_entitlement->>'component_count')::integer,
      -- entitlement_digest: the complete economic content of the head.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object(
          'authority_kind',v_entitlement->'authority_kind',
          'certified_zero',v_entitlement->'certified_zero',
          'component_count',v_entitlement->'component_count',
          'components',v_component_hashes)),
      -- inventory_digest: which components the head contains, identity only.
      private.weekly_source_publication_request_digest_v1(
        pg_catalog.jsonb_build_object('components',v_inventory_pairs)),
      v_source_generation_digest,
      v_decision_bundle_id,v_bundle_revision,v_decision_id,
      v_bundle.decided_by_user_id,v_now,v_now);

    insert into public.weekly_source_entitlement_head_components(
      head_id,component_ordinal,component_id,component_kind,economic_key_type,
      economic_key_value,component_member_identity,segment_id,segment_key,
      segment_stable_key,work_date,reference_number,hours_day,hours_night,hours_sat,
      hours_sun,hours_bh,additional_code_raw,unit_count,unit_pay_rate,unit_charge_rate,
      expense_code,pay_ex_vat,charge_ex_vat,exclude_from_pay,origin,
      decision_bundle_id,bundle_revision,movement_id,movement_group_id,
      component_sha256,created_at_utc)
    select
      v_head_ids[v_i],
      (component_element.value->>'component_ordinal')::integer,
      (component_element.value->>'component_id')::uuid,
      component_element.value->>'component_kind',
      component_element.value->>'economic_key_type',
      component_element.value->>'economic_key_value',
      component_element.value->>'component_member_identity',
      component_element.value->>'segment_id',
      component_element.value->>'segment_key',
      component_element.value->>'segment_stable_key',
      (component_element.value->>'work_date')::date,
      component_element.value->>'reference_number',
      (component_element.value->>'hours_day')::numeric,
      (component_element.value->>'hours_night')::numeric,
      (component_element.value->>'hours_sat')::numeric,
      (component_element.value->>'hours_sun')::numeric,
      (component_element.value->>'hours_bh')::numeric,
      component_element.value->>'additional_code_raw',
      (component_element.value->>'unit_count')::numeric,
      (component_element.value->>'unit_pay_rate')::numeric,
      (component_element.value->>'unit_charge_rate')::numeric,
      component_element.value->>'expense_code',
      (component_element.value->>'pay_ex_vat')::numeric,
      (component_element.value->>'charge_ex_vat')::numeric,
      (component_element.value->>'exclude_from_pay')::boolean,
      component_element.value->>'origin',
      v_decision_bundle_id,v_bundle_revision,
      (component_element.value->>'movement_id')::uuid,
      (component_element.value->>'movement_group_id')::uuid,
      private.weekly_source_publication_request_digest_v1(
                     private.weekly_source_publication_component_content_v1(component_element.value)),
      v_now
    from pg_catalog.jsonb_array_elements(v_entitlement->'components') as component_element(value)
    order by (component_element.value->>'component_ordinal')::integer;

    v_entitlement:=null; v_choice:=null;
  end loop;

  -- ---- 8. interface I-6 for a genuinely new B root ------------------------
  -- After staging and before the single invalidation.  I-6 calls the UNCHANGED
  -- ordinary Authorise owner exactly once and inserts the lineage generation of
  -- proof/34 section 4.  It is late-bound: WP-07 owns it.
  if v_target_auth is not null then
    v_target_authorise_result:=private.weekly_source_first_authorise_core_v1(
      v_member_root_ids[2],
      v_target_auth->>'expected_row_signature',
      (v_target_auth->>'actor_user_id')::uuid,
      p_lock_result);
    if coalesce((v_target_authorise_result->>'ok')::boolean,false) is not true then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_TARGET_AUTHORISATION_FAILED',
                'first_authorise_result',v_target_authorise_result)::text;
    end if;
  end if;

  -- ---- 9. activate every head together ------------------------------------
  -- 24 section 5.1: pass the same transaction token and scalar head/currentness
  -- evidence used by the publication receipt.  The token is taken before
  -- activation so the head, the invalidation and the receipt all carry it.
  v_token:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token is null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_SCOPE_TOKEN_UNAVAILABLE')::text;
  end if;

  for v_i in 1..v_n loop
    if v_current_head_ids[v_i] is not null then
      update public.weekly_source_entitlement_heads
         set state='SUPERSEDED',
             superseded_at_utc=v_now,
             superseded_by_head_id=v_head_ids[v_i]
       where id=v_current_head_ids[v_i];
    end if;
  end loop;
  for v_i in 1..v_n loop
    update public.weekly_source_entitlement_heads
       set state='COMMITTED_CURRENT',
           committed_at_utc=v_now,
           publication_receipt_digest=v_digest,
           scope_change_tx_token=v_token
     where id=v_head_ids[v_i];
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_HEAD_ACTIVATION_FAILED',
                'head_id',v_head_ids[v_i],'rows',v_rows)::text;
    end if;
  end loop;

  -- ---- 10. current_entitlement_head_id on the live ROOT AUTHORISATION ------
  -- Decision D8 (WP-01c): the authorisation record, and therefore this pointer,
  -- is per ROOT in public.weekly_source_root_authorisations, not on the
  -- per-source-row lineage binding.  proof/34 section 4: written by the
  -- head-publication coordinator only, and nothing else on the generation row
  -- is touched.  The relation's own partial unique index gives at most one live
  -- generation per root, so exactly one row must move.
  for v_i in 1..v_n loop
    update public.weekly_source_root_authorisations
       set current_entitlement_head_id=v_head_ids[v_i]
     where root_timesheet_id=v_member_root_ids[v_i]
       and withdrawn_at_utc is null;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then
      raise exception 'WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED'
        using errcode='55000',
              detail=pg_catalog.jsonb_build_object(
                'code','WEEKLY_SOURCE_PUBLICATION_ROOT_AUTHORISATION_POINTER_FAILED',
                'root_ordinal',v_i,
                'root_timesheet_id',v_member_root_ids[v_i],
                'live_authorisation_rows_updated',v_rows)::text;
    end if;
    v_lineage_rows:=v_lineage_rows+v_rows;
  end loop;

  -- ---- 11. ONE bounded Workbench invalidation -----------------------------
  -- proof/32 section 8 step 3 and H2-036: exactly once, after every head and
  -- any B creation/Authorise, with the complete aligned Candidate/root pairs
  -- and the transaction token, success required before the receipt.  The
  -- ordinary Authorise trigger may queue a strict-subset job for the same
  -- Candidate under the same token; that is the accepted option 1 outcome and
  -- Weekly Source neither suppresses it nor folds it.
  v_invalidation:=private.pay_workbench_scope_invalidate_v1(
    p_candidate_ids=>pg_catalog.array_fill(v_candidate_id,array[v_n]),
    p_timesheet_ids=>v_member_root_ids,
    p_reason=>'WEEKLY_SOURCE_ENTITLEMENT_HEAD_PUBLICATION',
    p_scope_change_tx_token=>v_token,
    p_payload_json=>pg_catalog.jsonb_build_object(
      'weekly_source_publication',pg_catalog.jsonb_build_object(
        'decision_bundle_id',v_decision_bundle_id,
        'bundle_revision',v_bundle_revision,
        'publication_mode',v_mode,
        'request_digest',pg_catalog.encode(v_digest,'hex'),
        'head_ids',pg_catalog.to_jsonb(v_head_ids),
        'head_revisions',pg_catalog.to_jsonb(v_head_revisions))));
  -- `<>` on a missing key yields NULL, the IF does not fire, and the receipt is
  -- written anyway.  An invalidation result that does not say it covered
  -- exactly one Candidate must FAIL, so this is `is distinct from` (review
  -- finding, lower severity 1: executed with a wrapper that stripped the key,
  -- and the publication went through).
  if coalesce((v_invalidation->>'ok')::boolean,false) is not true
     or (v_invalidation->>'candidate_count')::integer is distinct from 1
     or (v_invalidation->>'scope_change_tx_token')::uuid is distinct from v_token
     or coalesce((v_invalidation->>'job_inserted_count')::integer,0)
        +coalesce((v_invalidation->>'job_coalesced_count')::integer,0)<1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_FAILED',
              'invalidation',v_invalidation)::text;
  end if;

  -- ---- 11a. the R25 invalidation contract (HANDOVER 2 round 4, ruling 6) ---
  -- Restated R25: EVERY invalidation and dirty job created for this Candidate
  -- in this transaction - the explicit call, the ordinary Authorise route and
  -- every registered DIRTY_TRIGGER:<table>:<op> path - must carry the same
  -- token UUID and the same generation, and every non-complete job's scope,
  -- after the installed rotation normaliser, must be an exact subset of the
  -- declared aligned scope for that Candidate.  A different Candidate, an
  -- outside root or a token disagreement is a CONTRACT FAILURE, not extra
  -- harmless work, and rolls the whole transaction back.  Checked here, after
  -- the one explicit invalidation and BEFORE the receipt.
  --
  -- Ruling 6 point 1: calling the token owner again counts as the same token
  -- only if the returned UUID equals the controlling transaction token.
  v_token_recheck:=public.pay_workbench_scope_change_tx_token_v1();
  if v_token_recheck is distinct from v_token then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','CONTROLLING_TOKEN_CHANGED_INSIDE_THE_TRANSACTION',
              'controlling_token',v_token,'recheck_token',v_token_recheck)::text;
  end if;

  -- The declared complete aligned scope for this Candidate, expanded through
  -- the INSTALLED rotation normaliser (call-only, contract section 2).
  v_normalised:=public._pay_workbench_normalise_timesheet_rotation_scope_payload(
    v_member_root_ids,array[]::uuid[]);
  select coalesce(pg_catalog.array_agg(distinct scope_element.value::uuid),array[]::uuid[])
    into v_declared_scope
    from pg_catalog.jsonb_array_elements_text(
           coalesce(v_normalised->'family_timesheet_ids',
                    coalesce(v_normalised->'canonical_timesheet_ids',
                             pg_catalog.to_jsonb(v_member_root_ids)))) as scope_element(value);
  v_declared_scope:=private.weekly_source_uuid_set_union_v1(v_declared_scope,v_member_root_ids);

  -- At most one new scope-change transaction, and it is the controlling token.
  if exists (
    select 1 from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_scope_change_transactions native
        where native.tx_token=effect.row_id offset 0) as scope_tx_row
     where effect.frame_id=v_observation_frame and effect.kind='TOKEN' and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
       where observed.frame_id=v_observation_frame and observed.kind='TOKEN'
         and observed.row_id=scope_tx_row.tx_token)
       and scope_tx_row.tx_token is distinct from v_token) then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SECOND_SCOPE_CHANGE_TOKEN_WAS_CREATED_IN_THIS_TRANSACTION')::text;
  end if;

  -- Every job this transaction queued: same token, same (absent) generation,
  -- this Candidate, and a scope inside the declared aligned scope.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'job_id',job_row.id,'job_type',job_row.job_type,
             'candidate_id',job_row.candidate_id,
             'scope_change_tx_token',job_row.scope_change_tx_token,
             'scope_change_generation',job_row.scope_change_generation,
             'targeted_timesheet_ids',job_row.payload_json->'targeted_timesheet_ids',
             'reason',job_row.payload_json->'reason')
      from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_workbench_jobs native
        where native.id=effect.row_id offset 0) as job_row
     where effect.frame_id=v_observation_frame and effect.kind='JOB' and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
       where observed.frame_id=v_observation_frame and observed.kind='JOB'
         and observed.row_id=job_row.id)
       and (
         job_row.scope_change_tx_token is distinct from v_token
         -- A18/R25 (PRE-EXISTING fix): a generation is tolerated ONLY on a still-QUEUED dirty-apply job for this
         -- Candidate that an EARLIER committed transaction created and this transaction's enqueue coalesced into.
         -- Its token is already this transaction's, and its generation is one already allocated, so the deferred
         -- finaliser lifts it with GREATEST to THIS transaction's generation at COMMIT and clears the token; the job
         -- then runs after COMMIT over exactly the declared targets (subset and complete-scope checks unchanged).
         -- A RUNNING job, a foreign token, another Candidate/job type or an unallocated generation still fails.
         or (job_row.scope_change_generation is not null
             and not (job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
                      and job_row.status='QUEUED'
                      and job_row.candidate_id=v_candidate_id
                      and job_row.scope_change_tx_token=v_token
                      and job_row.scope_change_generation<=coalesce((
                            select generation_counter.seq
                              from public.app_change_counters as generation_counter
                             where generation_counter.entity_key='pay_candidate_scope_generation'),0)))
         or (job_row.candidate_id is not null and job_row.candidate_id<>v_candidate_id)
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)
            where not (target.value::uuid=any(v_declared_scope)))
         or exists (
           select 1
             from pg_catalog.jsonb_array_elements_text(
                    coalesce(job_row.payload_json->'linked_timesheet_ids','[]'::jsonb)) as linked(value)
            where not (linked.value::uuid=any(v_declared_scope))))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_JOB_QUEUED_IN_THIS_TRANSACTION_BREAKS_THE_R25_CONTRACT',
              'controlling_token',v_token,
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'job',v_offending)::text;
  end if;

  -- Validate every captured scope-state write, including reused rows and
  -- writes carrying an incorrect Candidate or token. No historical snapshot.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
             'timesheet_id',scope_state_row.timesheet_id,
             'candidate_id',scope_state_row.candidate_id,
             'last_scope_change_tx_token',scope_state_row.last_scope_change_tx_token,
             'last_dirty_reason',scope_state_row.last_dirty_reason)
      from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from private.banking_pay_workbench_timesheet_scope_state native
        where native.timesheet_id=effect.row_id offset 0) as scope_state_row
     where effect.frame_id=v_observation_frame and effect.kind='SCOPE'
       and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
         where observed.frame_id=v_observation_frame and observed.kind='SCOPE'
           and observed.row_id=scope_state_row.timesheet_id)
       and (scope_state_row.candidate_id is distinct from v_candidate_id
         or scope_state_row.last_scope_change_tx_token is distinct from v_token
         or not (scope_state_row.timesheet_id=any(v_declared_scope)))
     limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','A_SCOPE_STATE_ROW_OUTSIDE_THE_DECLARED_ALIGNED_SCOPE_WAS_DIRTIED',
              'declared_scope',pg_catalog.to_jsonb(v_declared_scope),
              'scope_state',v_offending)::text;
  end if;

  -- Registry-only writes are part of the same proof, even with no Timesheet
  -- or enqueue. Preserve missing/deleted observations and probe by native PK.
  v_offending:=(
    select pg_catalog.jsonb_build_object(
      'candidate_id',effect.row_id,'deleted',effect.deleted,
      'last_scope_change_tx_token',registry_row.last_scope_change_tx_token,
      'reason',case
        when effect.deleted or registry_row.candidate_id is null then 'REGISTRY_ROW_MISSING_OR_DELETED'
        when registry_row.candidate_id is distinct from v_candidate_id then 'REGISTRY_FOR_A_DIFFERENT_CANDIDATE'
        else 'REGISTRY_CARRIES_A_DIFFERENT_TOKEN' end)
    from pg_temp.ws_observation_rows_v1 as effect
    left join lateral (
      select native.candidate_id,native.last_scope_change_tx_token
      from private.banking_pay_workbench_candidate_scope_registry native
      where native.candidate_id=effect.row_id offset 0
    ) as registry_row on true
    where effect.frame_id=v_observation_frame and effect.kind='REGISTRY'
      and (effect.deleted or registry_row.candidate_id is null
        or registry_row.candidate_id is distinct from v_candidate_id
        or registry_row.last_scope_change_tx_token is distinct from v_token)
    order by effect.row_id limit 1);
  if v_offending is not null then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',detail=pg_catalog.jsonb_build_object(
        'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
        'reason',v_offending->>'reason','registry',v_offending)::text;
  end if;

  -- Exactly one effective complete-scope dirty result per Candidate and token
  -- (ruling 6 point 6).
  if (select pg_catalog.count(*)
        from pg_temp.ws_observation_rows_v1 as effect
      cross join lateral (select native.* from public.banking_pay_workbench_jobs native
        where native.id=effect.row_id offset 0) as job_row
       where effect.frame_id=v_observation_frame and effect.kind='JOB'
         and exists(select 1 from pg_temp.ws_observation_rows_v1 observed
           where observed.frame_id=v_observation_frame and observed.kind='JOB'
             and observed.row_id=job_row.id)
         and job_row.candidate_id=v_candidate_id
         and job_row.scope_change_tx_token=v_token
         and job_row.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
         and job_row.status in ('QUEUED','RUNNING')
         and private.weekly_source_uuid_set_equals_v1(
               (select coalesce(pg_catalog.array_agg(distinct target.value::uuid),array[]::uuid[])
                  from pg_catalog.jsonb_array_elements_text(
                         coalesce(job_row.payload_json->'targeted_timesheet_ids','[]'::jsonb)) as target(value)),
               v_member_root_ids))<>1 then
    raise exception 'WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE'
      using errcode='55000',
            detail=pg_catalog.jsonb_build_object(
              'code','WEEKLY_SOURCE_PUBLICATION_INVALIDATION_CONTRACT_FAILURE',
              'reason','NOT_EXACTLY_ONE_COMPLETE_SCOPE_JOB_FOR_THE_CANDIDATE_UNDER_THIS_TOKEN')::text;
  end if;

  -- No new Workbench effect may appear after the positive proof and before return.
  perform private.weekly_source_observation_seal_v1();
  -- ---- 12. exactly one immutable receipt ----------------------------------
  insert into private.weekly_source_entitlement_publication_receipts(
    decision_bundle_id,pending_bundle_id,bundle_revision,request_digest,publication_mode,
    candidate_id,member_root_ids,member_family_booking_ids,member_root_versions,head_ids,
    scope_change_tx_token,decision_id,decided_by_user_id,released_by_worker_id,
    released_by_worker_run_id,census_json,proof_json,created_at_utc
  ) values (
    v_decision_bundle_id,p_pending_bundle_id,v_bundle_revision,v_digest,v_mode,
    v_candidate_id,v_member_root_ids,v_member_family_booking_ids,v_member_root_versions,
    v_head_ids,v_token,v_decision_id,v_bundle.decided_by_user_id,p_worker_id,
    p_worker_run_id,coalesce(p_census,'{}'::jsonb),coalesce(p_proof,'{}'::jsonb),v_now)
  returning * into v_receipt;

  if v_bundle.state='PROPOSED' then
    update public.weekly_source_entitlement_decision_bundles
       set state='COMMITTED',committed_at_utc=v_now
     where decision_bundle_id=v_decision_bundle_id
       and bundle_revision=v_bundle_revision;
  end if;

  for v_i in 1..v_n loop
    v_result_heads:=v_result_heads||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'root_ordinal',v_i,
        'head_id',v_head_ids[v_i],
        'head_revision',v_head_revisions[v_i],
        'prior_head_id',v_prior_head_ids[v_i],
        'superseded_head_id',v_current_head_ids[v_i],
        'root_timesheet_id',v_member_root_ids[v_i],
        'family_booking_id',v_member_family_booking_ids[v_i],
        'root_timesheet_version',v_member_root_versions[v_i]));
  end loop;

  perform private.weekly_source_observation_end_v1(v_observation_frame);
  return pg_catalog.jsonb_build_object(
    'ok',true,'published',true,'replayed',false,
    'receipt',private.weekly_source_publication_receipt_json_v1(v_receipt.id),
    'heads',v_result_heads,
    'scope_change_tx_token',v_token,
    'invalidation',v_invalidation,
    'root_authorisations_pointed',v_lineage_rows,
    'before_position_source',pg_catalog.to_jsonb(v_before_source),
    'declared_aligned_scope',pg_catalog.to_jsonb(v_declared_scope),
    'member_timesheet_ids',pg_catalog.to_jsonb(v_member_timesheet_ids));
end;
$function$;

-- [REPLACES] private.weekly_source_workbench_inventory_seed_page_v1(p_head_id uuid)  winner piece A20
CREATE OR REPLACE FUNCTION private.weekly_source_workbench_inventory_seed_page_v1(p_head_id uuid)
 RETURNS TABLE(complete boolean, component_count bigint, last_ordinal integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expected integer;
  v_state private.weekly_source_workbench_inventory_v1%rowtype;
  v_count bigint; v_emit bigint; v_bad bigint; v_last integer; v_more boolean;
begin
  select h.component_count into v_expected from public.weekly_source_entitlement_heads h
   where h.id=p_head_id for no key update;
  if not found then raise exception 'WEEKLY_SOURCE_HEAD_NOT_FOUND' using errcode='22023'; end if;
  insert into private.weekly_source_workbench_inventory_v1(head_id) values(p_head_id) on conflict do nothing;
  select i.* into v_state from private.weekly_source_workbench_inventory_v1 i where i.head_id=p_head_id for update;
  if not v_state.complete then
    with raw as materialized (
      select c.component_ordinal,c.component_kind,c.exclude_from_pay,c.pay_ex_vat,c.additional_code_raw,c.expense_code
       from public.weekly_source_entitlement_head_components c
       where c.head_id=p_head_id and c.component_ordinal>v_state.bootstrap_last_ordinal
       order by c.component_ordinal limit 26
    ), page as materialized (select * from raw order by component_ordinal limit 25)
    select count(*),count(*) filter(where component_kind='WORKED_TIME' or round(case when exclude_from_pay then 0::numeric else coalesce(pay_ex_vat,0) end,2)<>0),
      count(*) filter(where component_kind is null or component_kind not in ('WORKED_TIME','ADDITIONAL_UNIT','EXPENSE','SOURCE_FIXED_EXPENSE')
        or (component_kind='ADDITIONAL_UNIT' and nullif(btrim(coalesce(additional_code_raw,'')),'') is null)
        or (component_kind='EXPENSE' and nullif(btrim(coalesce(expense_code,'')),'') is null)),
      coalesce(max(component_ordinal),v_state.bootstrap_last_ordinal),(select count(*)>25 from raw)
     into v_count,v_emit,v_bad,v_last,v_more from page;
    if not v_more and v_state.component_count+v_count<>v_expected then
      raise exception 'WEEKLY_SOURCE_HEAD_INVENTORY_MISMATCH' using errcode='23514';
    end if;
    update private.weekly_source_workbench_inventory_v1 i set
      component_count=i.component_count+v_count,emittable_count=i.emittable_count+v_emit,
      invalid_count=i.invalid_count+v_bad,bootstrap_last_ordinal=v_last,complete=not v_more
      where i.head_id=p_head_id;
  end if;
  return query select i.complete,i.component_count,i.bootstrap_last_ordinal
    from private.weekly_source_workbench_inventory_v1 i where i.head_id=p_head_id;
end;
$function$;

-- [REPLACES] private.weekly_source_workbench_inventory_track_v1()  winner piece A20
CREATE OR REPLACE FUNCTION private.weekly_source_workbench_inventory_track_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_head uuid;
  v_old_emit integer:=0;
  v_new_emit integer:=0;
  v_old_bad integer:=0;
  v_new_bad integer:=0;
begin
  if tg_relid='public.weekly_source_entitlement_heads'::regclass then
    insert into private.weekly_source_workbench_inventory_v1(head_id,complete)
      values(new.id,true);
    return new;
  end if;
  if tg_op='UPDATE' and new.head_id is distinct from old.head_id then
    raise exception 'WEEKLY_SOURCE_COMPONENT_HEAD_CHANGE_REFUSED' using errcode='23514';
  end if;
  v_head:=case when tg_op='DELETE' then old.head_id else new.head_id end;
  -- The original owner already locks its head before component writes. This
  -- metadata row is below that head in the shared lock order; it never seeks
  -- a head/root lock after taking its own lock.
  perform 1 from private.weekly_source_workbench_inventory_v1
    where head_id=v_head and complete for update;
  if not found then
    raise exception 'WEEKLY_SOURCE_WORKBENCH_INVENTORY_NOT_INITIALISED' using errcode='55000';
  end if;
  if tg_op<>'INSERT' then
    v_old_emit:=(old.component_kind='WORKED_TIME' or round(case when old.exclude_from_pay then 0::numeric else coalesce(old.pay_ex_vat,0) end,2)<>0)::integer;
    v_old_bad:=(old.component_kind is null or old.component_kind not in ('WORKED_TIME','ADDITIONAL_UNIT','EXPENSE','SOURCE_FIXED_EXPENSE')
      or (old.component_kind='ADDITIONAL_UNIT' and nullif(btrim(coalesce(old.additional_code_raw,'')),'') is null)
      or (old.component_kind='EXPENSE' and nullif(btrim(coalesce(old.expense_code,'')),'') is null))::integer;
  end if;
  if tg_op<>'DELETE' then
    v_new_emit:=(new.component_kind='WORKED_TIME' or round(case when new.exclude_from_pay then 0::numeric else coalesce(new.pay_ex_vat,0) end,2)<>0)::integer;
    v_new_bad:=(new.component_kind is null or new.component_kind not in ('WORKED_TIME','ADDITIONAL_UNIT','EXPENSE','SOURCE_FIXED_EXPENSE')
      or (new.component_kind='ADDITIONAL_UNIT' and nullif(btrim(coalesce(new.additional_code_raw,'')),'') is null)
      or (new.component_kind='EXPENSE' and nullif(btrim(coalesce(new.expense_code,'')),'') is null))::integer;
  end if;
  update private.weekly_source_workbench_inventory_v1 set
    component_count=component_count+case tg_op when 'INSERT' then 1 when 'DELETE' then -1 else 0 end,
    emittable_count=emittable_count+v_new_emit-v_old_emit,
    invalid_count=invalid_count+v_new_bad-v_old_bad
   where head_id=v_head;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$;

-- [REPLACES] public._pay_workbench_candidate_serial_active_state(p_job_id uuid, p_candidate_id uuid, p_job_type text, p_payload_json jsonb, p_now_utc timestamp with time zone)  winner piece A14
CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_serial_active_state(p_job_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, clock_timestamp());
  v_payload jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_candidate_id uuid := public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json);
  v_serial_key text := public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(p_candidate_id, p_payload_json));
  v_candidate_job boolean := false;
  v_is_chain_continuation boolean := false;
  v_projection_run_id_text text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_active_job_id uuid := NULL::uuid;
  v_active_job_type text := NULL::text;
  v_active_job_status text := NULL::text;
  v_active_job_started_at_utc timestamptz := NULL::timestamptz;
  v_active_job_run_at_utc timestamptz := NULL::timestamptz;
  v_active_chain_id text := NULL::text;
  v_queued_chain_job_id uuid := NULL::uuid;
  v_queued_chain_job_type text := NULL::text;
  v_queued_chain_job_status text := NULL::text;
  v_queued_chain_started_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_run_at_utc timestamptz := NULL::timestamptz;
  v_queued_chain_id text := NULL::text;
  v_projection_blocker_id uuid := NULL::uuid;
  v_projection_blocker_status text := NULL::text;
  v_projection_blocker_started_at_utc timestamptz := NULL::timestamptz;
  v_projection_blocker_updated_at_utc timestamptz := NULL::timestamptz;
  v_blocked boolean := false;
  v_reason text := NULL::text;
BEGIN
  v_candidate_job := public._pay_workbench_candidate_serial_is_candidate_job(p_job_type, v_candidate_id, v_payload);

  IF v_candidate_id IS NULL OR v_candidate_job IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'blocked', false,
      'candidate_serial_blocked', false,
      'reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_serial_wait_reason', 'NO_CANDIDATE_SERIAL_SCOPE',
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'candidate_serial_key', v_serial_key
    );
  END IF;

  v_is_chain_continuation := (
    lower(BTRIM(COALESCE(v_payload->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
    OR lower(BTRIM(COALESCE(v_payload->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      lower(BTRIM(COALESCE(v_payload->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND NULLIF(BTRIM(COALESCE(v_payload->>'fallback_reason', '')), '') IS NOT NULL
    )
    OR (
      NULLIF(BTRIM(COALESCE(v_payload->>'source_job_id', v_payload->>'continuation_source_job_id', v_payload->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
      AND UPPER(BTRIM(COALESCE(v_payload->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
    )
  );

  v_projection_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_payload->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_payload#>>'{cursor_json,cursor,projection_run_id}', '')), '')
  );
  IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_projection_run_id := v_projection_run_id_text::uuid;
  END IF;

  SELECT running_job.id,
         running_job.job_type,
         running_job.status,
         running_job.started_at_utc,
         running_job.run_at_utc,
         COALESCE(NULLIF(BTRIM(COALESCE(running_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(running_job.payload_json->>'source_job_id', '')), ''), running_job.id::text)
  INTO v_active_job_id, v_active_job_type, v_active_job_status, v_active_job_started_at_utc, v_active_job_run_at_utc, v_active_chain_id
  FROM public.banking_pay_workbench_jobs AS running_job
  WHERE running_job.status = 'RUNNING'
    -- A14: status = 'RUNNING' is the original test under the validated status CHECK (exact values),
    -- so the live-status index is used instead of scanning every job ever written.
    AND UPPER(BTRIM(COALESCE(running_job.status, ''))) = 'RUNNING'
    -- A14: implied by the serial-candidate test below (it returns candidate_id when present);
    -- evaluated first so other Candidates' rows never reach the payload/plpgsql tests.
    AND (running_job.candidate_id = v_candidate_id OR running_job.candidate_id IS NULL)
    AND running_job.id IS DISTINCT FROM p_job_id
    AND public._pay_workbench_candidate_serial_candidate_id(running_job.candidate_id, running_job.payload_json) = v_candidate_id
    AND public._pay_workbench_candidate_serial_is_candidate_job(running_job.job_type, running_job.candidate_id, running_job.payload_json)
  ORDER BY running_job.started_at_utc ASC NULLS FIRST, running_job.created_at_utc ASC, running_job.id ASC
  LIMIT 1;

  IF v_active_job_id IS NOT NULL THEN
    v_blocked := true;
    v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_JOB';
  END IF;

  IF v_blocked IS NOT TRUE AND v_is_chain_continuation IS NOT TRUE THEN
    SELECT queued_job.id,
           queued_job.job_type,
           queued_job.status,
           queued_job.started_at_utc,
           queued_job.run_at_utc,
           COALESCE(NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', '')), ''), queued_job.id::text)
    INTO v_queued_chain_job_id, v_queued_chain_job_type, v_queued_chain_job_status, v_queued_chain_started_at_utc, v_queued_chain_run_at_utc, v_queued_chain_id
    FROM public.banking_pay_workbench_jobs AS queued_job
    WHERE queued_job.status = 'QUEUED'
      -- A14: status = 'QUEUED' is the original test under the validated status CHECK (exact values),
      -- so the live-status index is used instead of scanning every job ever written.
      AND UPPER(BTRIM(COALESCE(queued_job.status, ''))) = 'QUEUED'
      -- A14: implied by the serial-candidate test below (it returns candidate_id when present);
      -- evaluated first so other Candidates' rows never reach the payload/plpgsql tests.
      AND (queued_job.candidate_id = v_candidate_id OR queued_job.candidate_id IS NULL)
      AND queued_job.id IS DISTINCT FROM p_job_id
      AND public._pay_workbench_candidate_serial_candidate_id(queued_job.candidate_id, queued_job.payload_json) = v_candidate_id
      AND public._pay_workbench_candidate_serial_is_candidate_job(queued_job.job_type, queued_job.candidate_id, queued_job.payload_json)
      AND (
        lower(BTRIM(COALESCE(queued_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR UPPER(BTRIM(COALESCE(queued_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
        OR lower(BTRIM(COALESCE(queued_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR (
          lower(BTRIM(COALESCE(queued_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
        )
        OR (
          NULLIF(BTRIM(COALESCE(queued_job.payload_json->>'source_job_id', queued_job.payload_json->>'continuation_source_job_id', queued_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
          AND UPPER(BTRIM(COALESCE(queued_job.payload_json->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
        )
      )
    ORDER BY queued_job.run_at_utc ASC, queued_job.priority ASC, queued_job.created_at_utc ASC, queued_job.id ASC
    LIMIT 1;

    IF v_queued_chain_job_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_CONTINUATION';
    END IF;
  END IF;

  IF v_blocked IS NOT TRUE THEN
    SELECT projection_run.id, projection_run.status, projection_run.started_at_utc, projection_run.updated_at_utc
    INTO v_projection_blocker_id, v_projection_blocker_status, v_projection_blocker_started_at_utc, v_projection_blocker_updated_at_utc
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.candidate_id = v_candidate_id
      AND UPPER(BTRIM(COALESCE(projection_run.status, ''))) IN ('RUNNING', 'PROCESSING', 'IN_PROGRESS')
      AND (v_projection_run_id IS NULL OR projection_run.id IS DISTINCT FROM v_projection_run_id)
    ORDER BY projection_run.started_at_utc ASC NULLS FIRST, projection_run.updated_at_utc ASC NULLS FIRST, projection_run.id ASC
    LIMIT 1;

    IF v_projection_blocker_id IS NOT NULL THEN
      v_blocked := true;
      v_reason := 'CANDIDATE_SERIAL_BLOCKED_BY_ACTIVE_PROJECTION_RUN';
    END IF;
  END IF;

  IF v_blocked IS TRUE THEN
    PERFORM public._pay_workbench_candidate_serial_audit(
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      p_job_id,
      v_candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'candidate_serial_key', v_serial_key,
        'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
        'blocked_job_type', v_active_job_type,
        'blocked_job_status', v_active_job_status,
        'blocked_job_started_at_utc', v_active_job_started_at_utc,
        'blocked_job_run_at_utc', v_active_job_run_at_utc,
        'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
        'blocked_chain_job_type', v_queued_chain_job_type,
        'blocked_chain_job_status', v_queued_chain_job_status,
        'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
        'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
        'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
        'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
        'projection_status', v_projection_blocker_status,
        'projection_started_at_utc', v_projection_blocker_started_at_utc,
        'projection_updated_at_utc', v_projection_blocker_updated_at_utc,
        'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED')
      )),
      COALESCE(v_reason, 'CANDIDATE_SERIAL_BLOCKED'),
      NULL::uuid
    );
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'blocked', COALESCE(v_blocked, false),
    'candidate_serial_blocked', COALESCE(v_blocked, false),
    'reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_serial_wait_reason', COALESCE(v_reason, 'CANDIDATE_SERIAL_CLEAR'),
    'candidate_id', v_candidate_id::text,
    'candidate_serial_key', v_serial_key,
    'is_chain_continuation', COALESCE(v_is_chain_continuation, false),
    'blocked_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocking_job_id', CASE WHEN v_active_job_id IS NULL THEN NULL ELSE v_active_job_id::text END,
    'blocked_job_type', v_active_job_type,
    'blocked_job_status', v_active_job_status,
    'blocking_status', COALESCE(v_active_job_status, v_queued_chain_job_status, v_projection_blocker_status),
    'blocked_job_started_at_utc', v_active_job_started_at_utc,
    'blocked_job_run_at_utc', v_active_job_run_at_utc,
    'blocking_started_at_utc', COALESCE(v_active_job_started_at_utc, v_queued_chain_started_at_utc, v_projection_blocker_started_at_utc),
    'blocking_run_at_utc', COALESCE(v_active_job_run_at_utc, v_queued_chain_run_at_utc, v_projection_blocker_updated_at_utc),
    'blocked_chain_job_id', CASE WHEN v_queued_chain_job_id IS NULL THEN NULL ELSE v_queued_chain_job_id::text END,
    'blocked_chain_job_type', v_queued_chain_job_type,
    'blocked_chain_job_status', v_queued_chain_job_status,
    'blocked_chain_started_at_utc', v_queued_chain_started_at_utc,
    'blocked_chain_run_at_utc', v_queued_chain_run_at_utc,
    'active_chain_id', COALESCE(v_active_chain_id, v_queued_chain_id),
    'projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'blocking_projection_run_id', CASE WHEN v_projection_blocker_id IS NULL THEN NULL ELSE v_projection_blocker_id::text END,
    'projection_status', v_projection_blocker_status,
    'projection_started_at_utc', v_projection_blocker_started_at_utc,
    'projection_updated_at_utc', v_projection_blocker_updated_at_utc
  ));
END;
$function$;

-- [REPLACES] public.pay_bank_csv_export_summary_get(p_pay_batch_id uuid, p_scope text, p_actor_user_id uuid)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_bank_csv_export_summary_get(p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
    v_batch_row public.pay_batches%ROWTYPE;
    v_batch_status_upper text := NULL;
    v_execution_commit_state text := 'NOT_SUBMITTED';
    v_execution_commit_ref text := NULL;
    v_execution_committed_at_utc timestamptz := NULL;
    v_pre_execution_export boolean := false;

    v_row_count integer := 0;
    v_total_amount numeric := 0;
    v_current_transfer_hash text := NULL;
    v_current_transfer_hash_basis text := NULL;

    v_pending_row_count integer := 0;
    v_pending_total_amount numeric := 0;
    v_pending_transfer_hash text := NULL;

    v_stable_row_count integer := 0;
    v_stable_total_amount numeric := 0;
    v_stable_transfer_hash text := NULL;

    v_blocked_row_count integer := 0;
    v_all_transfer_count integer := 0;
    v_pay_channels_included jsonb := '[]'::jsonb;
    v_status_counts jsonb := '{}'::jsonb;
    v_provider_counts jsonb := '{}'::jsonb;
    v_rail_env_counts jsonb := '{}'::jsonb;
    v_exportable_status_filter text := NULL;
    v_bank_csv_export_hash text := NULL;
BEGIN
  -- A30 (PRE-EXISTING fix, H6 M3): a batch whose V8 Draft operation is still being prepared (or failing and
  -- retrying) is not a published Draft. Its partial content is not readable until the operation finishes.
  IF private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id) THEN
    RAISE EXCEPTION 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED'
      USING ERRCODE = '55000',
            DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED',
              'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

    IF p_pay_batch_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_ID_REQUIRED',
            'message', 'pay_bank_csv_export_summary_get: pay_batch_id is required'
        )::text;
    END IF;

    IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'INVALID_SCOPE',
            'message', 'pay_bank_csv_export_summary_get: scope must be ALL, PAYE, or UMBRELLA',
            'scope', p_scope
        )::text;
    END IF;

    IF p_actor_user_id IS NOT NULL THEN
        PERFORM 1
        FROM public.tms_users AS actor_user
        WHERE actor_user.id = p_actor_user_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
                'code', 'ACTOR_USER_NOT_FOUND',
                'message', 'pay_bank_csv_export_summary_get: actor user was not found',
                'actor_user_id', p_actor_user_id::text,
                'pay_batch_id', p_pay_batch_id::text
            )::text;
        END IF;
    END IF;

    SELECT pay_batch.*
    INTO v_batch_row
    FROM public.pay_batches AS pay_batch
    WHERE pay_batch.id = p_pay_batch_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'pay_bank_csv_export_summary_get: pay batch was not found',
            'pay_batch_id', p_pay_batch_id::text
        )::text;
    END IF;

    v_batch_status_upper := upper(btrim(coalesce(v_batch_row.status, '')));
    v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));

    IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
        v_execution_commit_state := 'NOT_SUBMITTED';
    END IF;

    v_execution_commit_ref := nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '');
    v_execution_committed_at_utc := v_batch_row.execution_committed_at_utc;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch_row.bank_csv_export_json->>'transfer_hash', '')), '');

    v_pre_execution_export := (
        v_batch_row.cancelled_at_utc IS NULL
        AND v_batch_status_upper NOT IN ('CANCELLED', 'CANCELED')
        AND v_execution_commit_state = 'NOT_SUBMITTED'
        AND v_execution_commit_ref IS NULL
        AND v_execution_committed_at_utc IS NULL
    );

    SELECT
        count(*)::integer,
        round(coalesce(sum(CASE WHEN upper(coalesce(pending_transfer.status, '')) = 'PENDING' THEN pending_transfer.amount ELSE 0 END), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', pending_transfer.id,
                'candidate_id', pending_transfer.candidate_id,
                'umbrella_id', pending_transfer.umbrella_id,
                'pay_channel', pending_transfer.pay_channel,
                'amount', pending_transfer.amount,
                'currency', pending_transfer.currency,
                'payment_reference', pending_transfer.payment_reference,
                'payee_name', pending_transfer.payee_name,
                'sort_code_digits', pending_transfer.sort_code_digits,
                'account_number_digits', pending_transfer.account_number_digits,
                'account_type', pending_transfer.account_type,
                'bank_details_hash_snapshot', pending_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', pending_transfer.payee_entity_kind,
                'payee_entity_id', pending_transfer.payee_entity_id,
                'transfer_group_key', pending_transfer.transfer_group_key
            )
            ORDER BY pending_transfer.id
        )::text, '[]'))
    INTO
        v_pending_row_count,
        v_pending_total_amount,
        v_pending_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key,
            transfer_row.status AS status
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) = 'PENDING'
        ORDER BY transfer_row.id
    ) AS pending_transfer;

    SELECT
        count(*)::integer,
        round(coalesce(sum(stable_transfer.amount), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', stable_transfer.id,
                'candidate_id', stable_transfer.candidate_id,
                'umbrella_id', stable_transfer.umbrella_id,
                'pay_channel', stable_transfer.pay_channel,
                'amount', stable_transfer.amount,
                'currency', stable_transfer.currency,
                'payment_reference', stable_transfer.payment_reference,
                'payee_name', stable_transfer.payee_name,
                'sort_code_digits', stable_transfer.sort_code_digits,
                'account_number_digits', stable_transfer.account_number_digits,
                'account_type', stable_transfer.account_type,
                'bank_details_hash_snapshot', stable_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', stable_transfer.payee_entity_kind,
                'payee_entity_id', stable_transfer.payee_entity_id,
                'transfer_group_key', stable_transfer.transfer_group_key
            )
            ORDER BY stable_transfer.id
        )::text, '[]'))
    INTO
        v_stable_row_count,
        v_stable_total_amount,
        v_stable_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED'
        ORDER BY transfer_row.id
    ) AS stable_transfer;

    IF v_pre_execution_export THEN
        v_row_count := coalesce(v_pending_row_count, 0);
        v_total_amount := coalesce(v_pending_total_amount, 0);
        v_current_transfer_hash := v_pending_transfer_hash;
        v_current_transfer_hash_basis := 'PENDING_TRANSFER_HASH';
        v_exportable_status_filter := 'PENDING';
    ELSE
        v_row_count := coalesce(v_stable_row_count, 0);
        v_total_amount := coalesce(v_stable_total_amount, 0);
        v_current_transfer_hash := v_stable_transfer_hash;
        v_current_transfer_hash_basis := 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH';
        v_exportable_status_filter := 'ALL_NON_BLOCKED';
    END IF;

    SELECT count(*)::integer
    INTO v_all_transfer_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope);

    SELECT count(*)::integer
    INTO v_blocked_row_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
      AND upper(coalesce(transfer_row.status, '')) = 'BLOCKED';

    SELECT coalesce(jsonb_agg(to_jsonb(pay_channel_values.pay_channel) ORDER BY pay_channel_values.pay_channel), '[]'::jsonb)
    INTO v_pay_channels_included
    FROM (
        SELECT DISTINCT upper(coalesce(transfer_row.pay_channel, '')) AS pay_channel
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
    ) AS pay_channel_values
    WHERE pay_channel_values.pay_channel <> '';

    SELECT coalesce(jsonb_object_agg(status_counts.status_key, status_counts.status_count ORDER BY status_counts.status_key), '{}'::jsonb)
    INTO v_status_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.status, '')) AS status_key,
            count(*)::integer AS status_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
        GROUP BY upper(coalesce(transfer_row.status, ''))
    ) AS status_counts
    WHERE status_counts.status_key <> '';

    SELECT coalesce(jsonb_object_agg(provider_counts.provider_key, provider_counts.provider_count ORDER BY provider_counts.provider_key), '{}'::jsonb)
    INTO v_provider_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_provider, '')) AS provider_key,
            count(*)::integer AS provider_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_provider, ''))
    ) AS provider_counts
    WHERE provider_counts.provider_key <> '';

    SELECT coalesce(jsonb_object_agg(env_counts.env_key, env_counts.env_count ORDER BY env_counts.env_key), '{}'::jsonb)
    INTO v_rail_env_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_env, '')) AS env_key,
            count(*)::integer AS env_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_env, ''))
    ) AS env_counts
    WHERE env_counts.env_key <> '';

    RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'pay_channel_scope', v_scope,
        'pre_execution_export', v_pre_execution_export,
        'exportable_status_filter', v_exportable_status_filter,
        'row_count', coalesce(v_row_count, 0),
        'total_amount', coalesce(v_total_amount, 0),
        'transfer_hash', v_current_transfer_hash,
        'current_transfer_hash', v_current_transfer_hash,
        'current_transfer_hash_basis', v_current_transfer_hash_basis,
        'pending_transfer_hash', v_pending_transfer_hash,
        'stable_transfer_hash', v_stable_transfer_hash,
        'provider_snapshot', nullif(btrim(coalesce(v_batch_row.rail_provider_snapshot, '')), ''),
        'rail_env_snapshot', nullif(btrim(coalesce(v_batch_row.rail_env_snapshot, '')), ''),
        'freshness_validation_status', nullif(upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))), ''),
        'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), ''),
        'freshness_scope_hash', nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'bank_csv_export_hash', v_bank_csv_export_hash,
        'csv_export_matches_current_transfers', CASE WHEN v_bank_csv_export_hash IS NULL OR v_current_transfer_hash IS NULL THEN NULL ELSE v_bank_csv_export_hash = v_current_transfer_hash END,
        'pending_row_count', coalesce(v_pending_row_count, 0),
        'pending_total_amount', coalesce(v_pending_total_amount, 0),
        'stable_row_count', coalesce(v_stable_row_count, 0),
        'stable_total_amount', coalesce(v_stable_total_amount, 0),
        'blocked_row_count', coalesce(v_blocked_row_count, 0),
        'all_transfer_count', coalesce(v_all_transfer_count, 0),
        'pay_channels_included', coalesce(v_pay_channels_included, '[]'::jsonb),
        'status_counts', coalesce(v_status_counts, '{}'::jsonb),
        'provider_counts', coalesce(v_provider_counts, '{}'::jsonb),
        'rail_env_counts', coalesce(v_rail_env_counts, '{}'::jsonb),
        'summary_source', 'pay_bank_transfers',
        'policy_x_authority', 'FROZEN_MATERIALISED_TRANSFER_ROWS',
        'generated_at_utc', now()::text
    ));
END;
$function$
;

-- [REPLACES] public.pay_batch_export_csv_rows(p_pay_batch_id uuid, p_actor_user_id uuid)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_batch_export_csv_rows(p_pay_batch_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();

  v_batch record;
  v_batch_kind text := null;
  v_channels text[] := null;

  v_is_cancelled boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_pre_execution_export boolean := false;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_rows jsonb := '[]'::jsonb;
  v_row_count int := 0;
  v_kind_counts jsonb := '{}'::jsonb;
  v_batch_status_raw text := NULL::text;
  v_batch_status_label text := NULL::text;
  v_batch_terminal_with_failed_payments boolean := false;
  v_pending_bank_outcome_count integer := 0;
  v_unknown_bank_outcome_count integer := 0;
  v_terminal_success_payment_count integer := 0;
  v_terminal_failed_payment_count integer := 0;
  v_completed_at_utc timestamptz := NULL::timestamptz;
begin
  -- A30 (PRE-EXISTING fix, H6 M3): a batch whose V8 Draft operation is still being prepared (or failing and
  -- retrying) is not a published Draft. Its partial content is not readable until the operation finishes.
  IF private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id) THEN
    RAISE EXCEPTION 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED'
      USING ERRCODE = '55000',
            DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED',
              'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  if p_pay_batch_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: pay_batch_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.cancelled_at_utc,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.freshness_result_json,
    pb.freshness_operation_id,
    pb.completed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_export_csv_rows: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_is_cancelled := (
    v_batch.cancelled_at_utc is not null
    or upper(btrim(coalesce(v_batch.status, ''))) in ('CANCELLED', 'CANCELED')
  );
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;
  v_freshness_validation_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
  v_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
  v_pre_execution_export := (
    v_is_cancelled = false
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );


  v_completed_at_utc := v_batch.completed_at_utc;
  v_batch_status_raw := v_batch.status;

  WITH transfer_classification AS (
    SELECT
      transfer_row.id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
          OR (
            transfer_row.completed_at_utc IS NOT NULL
            AND UPPER(BTRIM(COALESCE(transfer_row.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            AND UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN 'TERMINAL_SUCCESS'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          THEN 'TERMINAL_FAILED'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED','CHECK_REQUIRED','AMBIGUOUS','TIMEOUT','TIMED_OUT')
          THEN 'UNKNOWN'
        WHEN UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
          OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
          THEN 'PENDING'
        ELSE 'UNKNOWN'
      END AS terminal_class
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  )
  SELECT
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'UNKNOWN')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_SUCCESS')::integer,
    COUNT(*) FILTER (WHERE transfer_classification.terminal_class = 'TERMINAL_FAILED')::integer
  INTO
    v_pending_bank_outcome_count,
    v_unknown_bank_outcome_count,
    v_terminal_success_payment_count,
    v_terminal_failed_payment_count
  FROM transfer_classification;

  v_batch_terminal_with_failed_payments := UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) = 'FAILED';
  v_batch_status_label := public._pay_batch_status_display_label(
    v_batch_status_raw,
    COALESCE(v_pending_bank_outcome_count, 0),
    COALESCE(v_unknown_bank_outcome_count, 0)
  );

  select ch.channels
  into v_channels
  from (
    select
      array_agg(distinct upper(coalesce(pbi.pay_channel,'')) order by upper(coalesce(pbi.pay_channel,'')))
        filter (where upper(coalesce(pbi.pay_channel,'')) in ('PAYE','UMBRELLA')) as channels
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ) ch;

  v_batch_kind := case
    when v_channels is null then null
    when array_position(v_channels,'PAYE') is not null and array_position(v_channels,'UMBRELLA') is not null then 'MIXED'
    when array_position(v_channels,'PAYE') is not null then 'PAYE'
    when array_position(v_channels,'UMBRELLA') is not null then 'UMBRELLA'
    else null
  end;

  if upper(coalesce(v_batch.batch_kind_fixed,'')) = 'LOANS' then
    v_batch_kind := 'LOANS';
  end if;

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id => p_pay_batch_id,
        p_actor_user_id => p_actor_user_id,
        p_allow_large_full_scan => false
      );

      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_batch_export_csv_rows: chunked freshness validation is required before payment-initiation export' else 'pay_batch_export_csv_rows: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  create temp table if not exists _tmp_pay_export_rows (
    sort_surname text not null,
    sort_group int not null,
    sort_work_date date null,
    sort_timesheet_id uuid null,
    sort_line_rank int not null,
    sort_bucket_code text null,
    sort_unit_name text null,
    line_kind text not null,
    row_json jsonb not null
  ) on commit drop;

  truncate table _tmp_pay_export_rows;

  insert into _tmp_pay_export_rows(
    sort_surname,
    sort_group,
    sort_work_date,
    sort_timesheet_id,
    sort_line_rank,
    sort_bucket_code,
    sort_unit_name,
    line_kind,
    row_json
  )
  with
  net_latest as (
    select
      pbc.id as pay_batch_candidate_id,
      (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) as paye_net_amount
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  base as (
    select
      pbc.candidate_id as candidate_id,
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_tms_ref as candidate_tms_ref_snap,
      pbc.candidate_display_name as candidate_display_name_snap,

      c.first_name as cand_first_name,
      c.last_name as cand_last_name,
      c.tms_ref as cand_tms_ref_live,

      pbi.id as pay_batch_item_id,
      pbi.item_type as item_type,
      pbi.timesheet_id as timesheet_id,
      pbi.segment_key as segment_key,
      pbi.source_ref as source_ref,
      pbi.description as item_description,
      pbi.pay_channel as pay_channel,
      pbi.repayment_week_start as repayment_week_start,
      pbi.finance_case_id as finance_case_id,
      pbi.finance_component_id as finance_component_id,
      pbi.paye_treatment as paye_treatment,
      pbi.payout_instruction_snapshot_json as payout_instruction_snapshot_json,
      coalesce(pbi.frozen_component_snapshot_json, '{}'::jsonb) as frozen_component_snapshot_json,
      coalesce(pbi.frozen_source_basis_json, '{}'::jsonb) as frozen_source_basis_json,
      pbi.frozen_resolution_mode as frozen_resolution_mode,
      pbi.frozen_resolution_payload_json as frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json as frozen_resolution_result_json,
      pbi.frozen_source_amount as frozen_source_amount,
      pbi.frozen_target_amount_ex_vat as frozen_target_amount_ex_vat,
      pbi.pay_bank_transfer_id as pay_bank_transfer_id,
      pbt.status as payment_status_raw,
      pbt.rail_state as payment_rail_state,
      pbt.rail_provider as payment_provider,
      pbt.rail_env as payment_rail,
      pbt.rail_tx_id as payment_rail_tx_id,
      pbt.request_id as payment_request_id,
      pbt.completed_at_utc as payment_completed_at_utc,
      pbt.failed_reason as payment_failed_reason,
      coalesce(pbt.rail_meta_json, '{}'::jsonb) as payment_rail_meta_json,
      latest_event.provider_key as payment_event_provider_key,
      latest_event.provider_transaction_id as payment_provider_transaction_id,
      latest_event.provider_request_id as payment_provider_request_id,
      latest_event.provider_event_id as payment_provider_event_id,
      latest_event.provider_event_key as payment_provider_event_key,
      latest_event.provider_reference as payment_provider_reference,
      latest_event.normalised_state as payment_event_normalised_state,
      latest_event.provider_state as payment_event_provider_state,
      latest_event.event_time_utc as payment_event_time_utc,
      latest_event.received_at_utc as payment_event_received_at_utc,
      latest_event.provider_failure_reason_code as payment_provider_failure_reason_code,
      latest_event.provider_failure_reason_group as payment_provider_failure_reason_group,
      latest_event.correction_disposition as payment_action_review_status,

      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.units as units,
      pbib.rate as rate,
      pbib.amount_ex_vat as amount_ex_vat,
      pbib.amount_vat as amount_vat,
      pbib.amount_inc_vat as amount_inc_vat,
      coalesce(pbib.meta_json, '{}'::jsonb) as breakdown_meta_json,

      ecomp.key_type as economic_key_type,
      ecomp.key_value as economic_key_value,
      ecomp.source_amount_ex_vat as economic_source_amount_ex_vat,
      ecomp.target_amount_ex_vat as economic_target_amount_ex_vat,
      ecomp.key_resolution_source as economic_key_resolution_source,
      ecomp.key_resolution_failure_reason as economic_key_resolution_failure_reason,

      ts.week_ending_date as week_ending_date,
      ts.reference_number as reference_number,
      cl.id as client_id,
      cl.name as client_name,

      nl.paye_net_amount as paye_net_amount,

      segd.work_date as seg_work_date,

      vfcr.case_type as finance_case_type,
      vfcr.taxability as finance_taxability,
      vfcr.routing_kind as finance_routing_kind,
      vfcr.management_group as finance_management_group,
      vfcr.lifecycle_status_display as finance_lifecycle_status_display,
      vfcr.status as finance_status,
      vfcr.payout_status as finance_payout_status,
      vfcr.adjustment_comment as finance_adjustment_comment,
      vfcr.notes as finance_notes,
      vfcr.is_candidate_directed_oneoff_payout as is_candidate_directed_oneoff_payout,
      vfcr.appears_on_umbrella_remittance as appears_on_umbrella_remittance,
      vfcr.generates_candidate_payment_advice as generates_candidate_payment_advice,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_created_by_user_id,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_updated_by_user_id,

      tuc.display_name as bank_details_created_by_display_name,
      tuc.email as bank_details_created_by_email,
      tuu.display_name as bank_details_updated_by_display_name,
      tuu.email as bank_details_updated_by_email,

      case
        when coalesce(ecomp.key_type,'') = 'TS_DAY' and coalesce(ecomp.key_value,'') ~ '^\d{4}-\d{2}-\d{2}$' then ecomp.key_value::date
        else null::date
      end as economic_work_date,

      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), ''))::numeric
        else pbib.units
      end as source_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), ''))::numeric
        else pbib.units
      end as target_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), ''))::numeric
        else pbib.rate
      end as source_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), ''))::numeric
        else pbib.rate
      end as target_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), ''))::numeric
        else ecomp.source_amount_ex_vat
      end as source_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), ''))::numeric
        else coalesce(ecomp.target_amount_ex_vat, pbib.amount_ex_vat)
      end as target_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), ''))::numeric
        else null::numeric
      end as source_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), ''))::numeric
        else null::numeric
      end as target_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as source_charge_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as target_charge_ex_vat,
      coalesce(
        nullif(btrim(coalesce(pbib.meta_json->>'resolution_mode','')), ''),
        nullif(btrim(coalesce(pbi.frozen_resolution_mode::text,'')), ''),
        nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'resolution_mode','')), '')
      ) as resolution_mode,
      coalesce(
        nullif(pbib.meta_json->'resolution_payload_json', 'null'::jsonb),
        pbi.frozen_resolution_payload_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_payload_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_payload_json', 'null'::jsonb)
      ) as resolution_payload_json,
      coalesce(
        nullif(pbib.meta_json->'resolution_result_json', 'null'::jsonb),
        pbi.frozen_resolution_result_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_result_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_result_json', 'null'::jsonb)
      ) as resolution_result_json
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
     and pbc.pay_batch_id = p_pay_batch_id
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = pbi.id
    left join public._pay_batch_item_economic_components(p_pay_batch_id, null::uuid[]) ecomp
      on ecomp.pay_batch_item_id = pbi.id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join lateral (
      select
        pbe.provider_key,
        pbe.provider_transaction_id,
        pbe.provider_request_id,
        pbe.provider_event_id,
        pbe.provider_event_key,
        pbe.provider_reference,
        pbe.normalised_state,
        pbe.provider_state,
        pbe.event_time_utc,
        pbe.received_at_utc,
        pbe.provider_failure_reason_code,
        pbe.provider_failure_reason_group,
        pbe.correction_disposition
      from public.pay_bank_transfer_events pbe
      where pbe.pay_batch_id = p_pay_batch_id
        and pbe.pay_bank_transfer_id = pbt.id
      order by coalesce(pbe.event_time_utc, pbe.received_at_utc, pbe.created_at_utc) desc nulls last,
               pbe.id desc
      limit 1
    ) latest_event on true
    left join public.candidates c
      on c.id = pbc.candidate_id
    left join public.timesheets ts
      on ts.timesheet_id = pbi.timesheet_id
     and ts.is_current = true
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cl
      on cl.id = ct.client_id
    left join net_latest nl
      on nl.pay_batch_candidate_id = pbc.id
    left join public.pay_batch_timesheet_snapshots pbts
      on pbts.pay_batch_id = p_pay_batch_id
     and pbts.timesheet_id = pbi.timesheet_id
     and pbts.candidate_id = pbc.candidate_id
     and upper(coalesce(pbts.pay_channel,'')) = upper(coalesce(pbi.pay_channel,''))
    left join lateral (
      select
        nullif(btrim(coalesce(seg->>'date','')),'')::date as work_date
      from jsonb_array_elements(coalesce(pbts.target_snapshot_json->'segments','[]'::jsonb)) seg
      where pbi.item_type = 'SEGMENT_DELTA'
        and seg is not null
        and jsonb_typeof(seg) = 'object'
        and nullif(btrim(coalesce(seg->>'segment_id','')),'') = coalesce(
          nullif(btrim(coalesce(pbi.segment_key,'')), ''),
          case
            when pbi.source_ref is not null and btrim(coalesce(pbi.source_ref,'')) like 'seg:%'
              then nullif(btrim(split_part(pbi.source_ref,':',2)),'')
            else null
          end
        )
        and nullif(btrim(coalesce(seg->>'date','')),'') ~ '^\d{4}-\d{2}-\d{2}$'
      limit 1
    ) segd on true
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    left join public.tms_users tuc
      on tuc.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end
    left join public.tms_users tuu
      on tuu.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end
    where pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ),
  rows0 as (
    select
      coalesce(
        nullif(btrim(coalesce(b.cand_last_name,'')), ''),
        nullif(btrim(regexp_replace(coalesce(b.candidate_display_name_snap,''), '^.*\s', '')), ''),
        nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
        b.candidate_id::text
      ) as sort_surname,

      case
        when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 3
        when b.timesheet_id is null then 2
        else 1
      end as sort_group,

      coalesce(b.economic_work_date, b.seg_work_date, b.week_ending_date, b.repayment_week_start) as sort_work_date,

      b.timesheet_id as sort_timesheet_id,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 900
        when b.item_type = 'LOAN_REPAYMENT' then 910
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 915
        when b.item_type = 'LOAN_PAYOUT' then 920
        when b.item_type = 'UNDERPAYMENT_PAYMENT' then 925
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 930
        else case upper(coalesce(b.line_kind,''))
          when 'TS_BUCKET' then 100
          when 'ADDITIONAL_UNIT' then 200
          when 'MILEAGE' then 300
          when 'EXPENSE' then 400
          when 'ADJUSTMENT' then 500
          when 'CONVERSION_ADJ' then 600
          when 'DEBT_CREATED' then 950
          else 800
        end
      end as sort_line_rank,

      upper(nullif(btrim(coalesce(b.bucket_code,'')),'')) as sort_bucket_code,
      nullif(btrim(coalesce(b.unit_name,'')),'') as sort_unit_name,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
        when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
        when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
        when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
        else upper(coalesce(b.line_kind,''))
      end as line_kind,

      jsonb_strip_nulls(
        jsonb_build_object(
          'candidate_id', b.candidate_id::text,
          'candidate_tms_ref', coalesce(
            nullif(btrim(coalesce(b.candidate_tms_ref_snap,'')), ''),
            nullif(btrim(coalesce(b.cand_tms_ref_live,'')), ''),
            null
          ),
          'candidate_first_name', nullif(btrim(coalesce(b.cand_first_name,'')), ''),
          'candidate_last_name', nullif(btrim(coalesce(b.cand_last_name,'')), ''),
          'candidate_display_name', nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
          'client_id', case when b.client_id is null then null else b.client_id::text end,
          'client_name', b.client_name,
          'timesheet_id', case when b.timesheet_id is null then null else b.timesheet_id::text end,
          'week_ending_date', case when b.week_ending_date is null then null else b.week_ending_date::text end,
          'work_date', case
            when b.economic_work_date is not null then b.economic_work_date::text
            when b.seg_work_date is not null then b.seg_work_date::text
            when b.week_ending_date is not null then b.week_ending_date::text
            when b.repayment_week_start is not null then b.repayment_week_start::text
            else null
          end,
          'reference_number', b.reference_number,
          'pay_channel', upper(coalesce(b.pay_channel,'')),
          'pay_method', upper(coalesce(b.pay_channel,'')),
          'item_type', b.item_type,
          'item_type_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            else null
          end,
          'payment_or_deduction', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','UNDERPAYMENT_PAYMENT') then 'PAYMENT'
            when coalesce(b.amount_ex_vat, 0) < 0 then 'DEDUCTION'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'PAYMENT'
            else 'ZERO'
          end,
          'finance_case_id', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_case_reference', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_component_id', case when b.finance_component_id is null then null else b.finance_component_id::text end,
          'finance_case_type', case when b.finance_case_type is null then null else b.finance_case_type::text end,
          'finance_management_group', b.finance_management_group,
          'lifecycle_status', b.finance_lifecycle_status_display,
          'finance_status', case when b.finance_status is null then null else b.finance_status::text end,
          'finance_payout_status', case when b.finance_payout_status is null then null else b.finance_payout_status::text end,
          'taxability', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'taxability','')), ''),
          'routing_kind', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '')
        )
        || jsonb_build_object(
          'payout_destination', coalesce(
            nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'destination_label','')), ''),
            case
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'UMBRELLA_COMPANY' then 'umbrella company'
              when upper(coalesce(b.pay_channel,'')) = 'PAYE' then 'normal PAYE route'
              when upper(coalesce(b.pay_channel,'')) = 'UMBRELLA' then 'umbrella company'
              else null
            end
          ),
          'sort_code', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''),
          'account_number', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''),
          'destination_group_key', concat_ws(
            '|',
            upper(coalesce(b.pay_channel,'')),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_id','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''), '')
          ),
          'masked_bank_account', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'masked_bank_account_paid_to', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'beneficiary_name', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
          'bank_details_hash', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
          'bank_details_note', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_note','')), ''),
          'bank_details_created_by_user_id', case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end,
          'bank_details_created_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_created_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_created_by_email,'')), ''),
            case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end
          ),
          'bank_details_updated_by_user_id', case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end,
          'bank_details_updated_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_updated_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_updated_by_email,'')), ''),
            case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end
          ),
          'appears_on_umbrella_remittance', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','')), '')) in ('true','t','1','yes','y')), false),
          'generates_candidate_payment_advice', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','')), '')) in ('true','t','1','yes','y')), false),
          'is_candidate_directed_oneoff_payout', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout','')), '')) in ('true','t','1','yes','y')), false),
          'line_kind', case
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'UNDERPAYMENT_PAYMENT'
            else b.line_kind
          end,
          'line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'friendly_line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'UNDERPAYMENT_PAYMENT' then 'Underpayment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when upper(coalesce(b.line_kind,'')) = 'TS_BUCKET' then case upper(coalesce(b.bucket_code,''))
              when 'DAY' then 'Day'
              when 'NIGHT' then 'Night'
              when 'SAT' then 'Sat'
              when 'SUN' then 'Sun'
              when 'BH' then 'BH'
              else coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Hours')
            end
            when upper(coalesce(b.line_kind,'')) = 'ADDITIONAL_UNIT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Additional unit')
            when upper(coalesce(b.line_kind,'')) = 'MILEAGE' then 'Mileage'
            when upper(coalesce(b.line_kind,'')) = 'EXPENSE' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Expense')
            when upper(coalesce(b.line_kind,'')) = 'ADJUSTMENT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Adjustment')
            when upper(coalesce(b.line_kind,'')) = 'CONVERSION_ADJ' then 'Conversion adjustment'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'row_group', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.timesheet_id is null then 'NON_TIMESHEET'
            else 'TIMESHEET'
          end,
          'is_non_timesheet_line', (b.timesheet_id is null),
          'bucket_code', b.bucket_code,
          'unit_name', b.unit_name,
          'units', b.units,
          'rate', b.rate,
          'amount_ex_vat', b.amount_ex_vat,
          'amount_vat', b.amount_vat
        )
        || jsonb_build_object(
          'amount_inc_vat', b.amount_inc_vat,
          'economic_key_type', b.economic_key_type,
          'economic_key_value', b.economic_key_value,
          'key_type', b.economic_key_type,
          'key_value', b.economic_key_value,
          'key_resolution_source', b.economic_key_resolution_source,
          'key_resolution_failure_reason', b.economic_key_resolution_failure_reason,
          'source_units', b.source_units,
          'target_units', b.target_units,
          'source_rate', b.source_rate,
          'target_rate', b.target_rate,
          'source_amount_ex_vat', b.source_amount_ex_vat,
          'target_amount_ex_vat', b.target_amount_ex_vat,
          'target_amount_paid_ex_vat', b.target_amount_ex_vat,
          'source_charge_rate', b.source_charge_rate,
          'target_charge_rate', b.target_charge_rate,
          'source_charge_ex_vat', b.source_charge_ex_vat,
          'target_charge_ex_vat', b.target_charge_ex_vat,
          'resolution_mode', b.resolution_mode,
          'resolution_payload_json', b.resolution_payload_json,
          'resolution_result_json', b.resolution_result_json,
          'source_target_detail', jsonb_strip_nulls(jsonb_build_object(
            'source_units', b.source_units,
            'target_units', b.target_units,
            'source_rate', b.source_rate,
            'target_rate', b.target_rate,
            'source_amount_ex_vat', b.source_amount_ex_vat,
            'target_amount_ex_vat', b.target_amount_ex_vat,
            'source_charge_rate', b.source_charge_rate,
            'target_charge_rate', b.target_charge_rate,
            'source_charge_ex_vat', b.source_charge_ex_vat,
            'target_charge_ex_vat', b.target_charge_ex_vat,
            'economic_key_type', b.economic_key_type,
            'economic_key_value', b.economic_key_value,
            'resolution_mode', b.resolution_mode
          )),
          'signed_amount_ex_vat', b.amount_ex_vat,
          'signed_amount_inc_vat', b.amount_inc_vat,
          'amount_sign', case
            when coalesce(b.amount_ex_vat, 0) < 0 then 'NEGATIVE'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'POSITIVE'
            else 'ZERO'
          end,
          'is_overpayment_recovery', (b.item_type = 'OVERPAYMENT_RECOVERY'),
          'is_loan_repayment', (b.item_type = 'LOAN_REPAYMENT'),
          'is_manual_debt_recovery', (b.item_type = 'MANUAL_DEBT_RECOVERY'),
          'is_underpayment_payment', (b.item_type = 'UNDERPAYMENT_PAYMENT'),
          'deduction_kind', case
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_ADJUSTMENT'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            else null
          end,
          'deduction_amount_ex_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_ex_vat,0)),2)
            else null
          end,
          'deduction_amount_inc_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_inc_vat,0)),2)
            else null
          end,
          'paye_net_amount', case
            when upper(coalesce(b.pay_channel,'')) = 'PAYE' then b.paye_net_amount
            else null
          end,
          'paye_treatment', b.paye_treatment,
          'adjustment_comment', b.finance_adjustment_comment,
          'note', coalesce(b.finance_notes, b.item_description),
          'comment_or_note', coalesce(b.finance_adjustment_comment, b.finance_notes, b.item_description),
          'description', b.item_description,
          'source_ref', b.source_ref,
          'repayment_week_start', case when b.repayment_week_start is null then null else b.repayment_week_start::text end
        )
        || jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN b.pay_bank_transfer_id IS NULL THEN NULL ELSE b.pay_bank_transfer_id::text END,
          'payment_status_raw', b.payment_status_raw,
          'payment_status_label', CASE
            WHEN v_pre_execution_export
             AND UPPER(BTRIM(COALESCE(v_batch_status_raw, ''))) IN ('DRAFT', 'DRAFT_CREATED')
             AND b.pay_bank_transfer_id IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_status_raw, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_rail_state, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_rail_tx_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_request_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_provider_transaction_id, '')), '') IS NULL
             AND NULLIF(BTRIM(COALESCE(b.payment_provider_request_id, '')), '') IS NULL
              THEN 'Not yet submitted'
            ELSE public._pay_bank_transfer_status_display_label(
              b.payment_status_raw,
              b.payment_rail_state,
              CASE
                WHEN (
              UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
              OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
              OR (
                b.payment_completed_at_utc IS NOT NULL
                AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              )
            ) THEN 'FINAL_PAID'
                WHEN (
              UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            ) THEN 'TERMINAL_NO_MONEY'
                ELSE NULL::text
              END
            )
          END,
          'rail_state', b.payment_rail_state,
          'payment_terminal_success', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR (
              b.payment_completed_at_utc IS NOT NULL
              AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            )
          ),
          'payment_terminal_failed', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ),
          'payment_terminal', (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR b.payment_completed_at_utc IS NOT NULL
          ),
          'provider', COALESCE(b.payment_provider, b.payment_event_provider_key),
          'rail', b.payment_rail,
          'rail_tx_id', NULLIF(BTRIM(COALESCE(b.payment_rail_tx_id, '')), ''),
          'provider_transaction_id', NULLIF(BTRIM(COALESCE(b.payment_provider_transaction_id, b.payment_rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', b.payment_rail_meta_json #>> '{provider_transaction_id}', '')), ''),
          'provider_request_id', NULLIF(BTRIM(COALESCE(b.payment_provider_request_id, b.payment_rail_meta_json #>> '{provider_submit_diagnostic,request_id}', b.payment_request_id, '')), ''),
          'payment_completed_at_utc', CASE WHEN b.payment_completed_at_utc IS NULL THEN NULL ELSE b.payment_completed_at_utc::text END,
          'payment_failed_at_utc', CASE WHEN UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT') OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','CANCELLED','CANCELED') THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc)::text ELSE NULL::text END,
          'payment_returned_at_utc', CASE WHEN UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('RETURNED','REVERTED') OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('RETURNED','REVERTED') THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc)::text ELSE NULL::text END,
          'payment_terminal_at_utc', CASE
            WHEN (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
            OR (
              b.payment_completed_at_utc IS NOT NULL
              AND UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
              AND UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            )
          ) THEN COALESCE(b.payment_completed_at_utc, b.payment_event_time_utc, b.payment_event_received_at_utc)::text
            WHEN (
            UPPER(BTRIM(COALESCE(b.payment_status_raw, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(b.payment_rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','VOIDED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          ) THEN COALESCE(b.payment_event_time_utc, b.payment_event_received_at_utc, b.payment_completed_at_utc)::text
            ELSE NULL::text
          END,
          'action_review_status', b.payment_action_review_status,
          'provider_failure_reason_code', b.payment_provider_failure_reason_code,
          'provider_failure_reason_group', b.payment_provider_failure_reason_group
        )
      ) as row_json
    from base b
  )
  select
    r.sort_surname,
    r.sort_group,
    r.sort_work_date,
    r.sort_timesheet_id,
    r.sort_line_rank,
    r.sort_bucket_code,
    r.sort_unit_name,
    r.line_kind,
    r.row_json
  from rows0 r;

  select count(*)::int
  into v_row_count
  from _tmp_pay_export_rows;

  select coalesce(
    jsonb_object_agg(t.lk, t.ct),
    '{}'::jsonb
  )
  into v_kind_counts
  from (
    select
      coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN') as lk,
      count(*)::int as ct
    from _tmp_pay_export_rows per
    group by coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN')
  ) t;

  select coalesce(
    jsonb_agg(
      per.row_json
      order by
        per.sort_surname asc,
        per.sort_group asc,
        per.sort_work_date asc nulls last,
        per.sort_timesheet_id asc nulls last,
        per.sort_line_rank asc,
        per.sort_bucket_code asc nulls last,
        per.sort_unit_name asc nulls last
    ),
    '[]'::jsonb
  )
  into v_rows
  from _tmp_pay_export_rows per;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_EXPORT_CSV_ROWS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'row_count', v_row_count,
        'line_kind_counts', v_kind_counts,
        'is_cancelled', v_is_cancelled,
        'is_stale', v_is_stale,
        'stale_reasons', v_stale_reasons
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'batch', jsonb_build_object(
      'id', v_batch.id::text,
      'status', v_batch.status,
      'batch_status_raw', v_batch_status_raw,
      'batch_status_label', v_batch_status_label,
      'batch_terminal_with_failed_payments', COALESCE(v_batch_terminal_with_failed_payments, false),
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_execution_committed_at_utc IS NULL THEN NULL ELSE v_execution_committed_at_utc::text END,
      'completed_at_utc', CASE WHEN v_completed_at_utc IS NULL THEN NULL ELSE v_completed_at_utc::text END,
      'finalised_at_utc', CASE WHEN v_completed_at_utc IS NULL THEN NULL ELSE v_completed_at_utc::text END,
      'pending_bank_outcome_count', COALESCE(v_pending_bank_outcome_count, 0),
      'unknown_bank_outcome_count', COALESCE(v_unknown_bank_outcome_count, 0),
      'terminal_success_payment_count', COALESCE(v_terminal_success_payment_count, 0),
      'terminal_failed_payment_count', COALESCE(v_terminal_failed_payment_count, 0),
      'pay_date', case when v_batch.pay_date is null then null else v_batch.pay_date::text end,
      'batch_kind', v_batch_kind,
      'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
      'is_cancelled', v_is_cancelled,
      'generated_at_utc', v_now_utc::text
    ),
    'freshness', jsonb_build_object(
      'is_stale', v_is_stale,
      'stale_reasons', v_stale_reasons,
      'diff_sample', v_diff_sample,
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'freshness_operation_id', case when v_batch.freshness_operation_id is null then null else v_batch.freshness_operation_id::text end,
      'source', coalesce(v_fresh->>'source', case when v_pre_execution_export then 'legacy_or_stored_pre_execution' else 'stored_freshness_metadata_non_blocking' end)
    ),
    'summary', jsonb_build_object(
      'row_count', v_row_count,
      'line_kind_counts', v_kind_counts
    ),
    'rows', v_rows
  );
end;
$function$
;

-- [REPLACES] public.pay_batch_freshness_result_get(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid)  winner piece A24
CREATE OR REPLACE FUNCTION public.pay_batch_freshness_result_get(p_operation_id uuid, p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_pay_batch_id uuid := p_pay_batch_id;
  v_actor_is_valid boolean := true;
  v_progress_summary jsonb := '{}'::jsonb;

  v_total_unit_count integer := 0;
  v_fresh_unit_count integer := 0;
  v_stale_unit_count integer := 0;
  v_pending_unit_count integer := 0;
  v_error_unit_count integer := 0;
  v_completed_unit_count integer := 0;
  v_unit_result_hashes jsonb := '[]'::jsonb;

  v_total_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_complete_chunk_count integer := 0;
  v_chunk_result_hashes jsonb := '[]'::jsonb;

  v_validation_complete boolean := false;
  v_is_stale boolean := false;
  v_checked_count integer := 0;
  v_stale_count integer := 0;
  v_failed_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_failed_sample jsonb := '[]'::jsonb;
  v_checked_at_utc timestamptz := NULL::timestamptz;
  v_scope_hash text := NULL::text;
  v_result_hash text := NULL::text;
  v_status text := 'PENDING';
  v_result jsonb := '{}'::jsonb;
  v_hash_basis jsonb := '{}'::jsonb;
  v_source_head_drift jsonb := '[]'::jsonb;  -- A24
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED')::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  v_pay_batch_id := COALESCE(v_pay_batch_id, v_operation.pay_batch_id);

  IF v_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED',
              'operation_id', p_operation_id::text
            )::text;
  END IF;

  IF v_operation.pay_batch_id IS NOT NULL AND v_operation.pay_batch_id <> v_pay_batch_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'operation_pay_batch_id', v_operation.pay_batch_id::text,
              'pay_batch_id', v_pay_batch_id::text
            )::text;
  END IF;

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = v_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND',
              'pay_batch_id', v_pay_batch_id::text
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  v_progress_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'STALE')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'ERROR')::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_unit.status, ''))) NOT IN ('FRESH', 'STALE', 'ERROR'))::integer
  INTO
    v_total_unit_count,
    v_fresh_unit_count,
    v_stale_unit_count,
    v_error_unit_count,
    v_pending_unit_count
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL);

  IF COALESCE(v_total_unit_count, 0) > 0 THEN
    v_completed_unit_count := COALESCE(v_fresh_unit_count, 0) + COALESCE(v_stale_unit_count, 0) + COALESCE(v_error_unit_count, 0);
    v_validation_complete := COALESCE(v_pending_unit_count, 0) = 0;
    v_checked_count := v_completed_unit_count;
    v_stale_count := COALESCE(v_stale_unit_count, 0);
    v_failed_count := COALESCE(v_error_unit_count, 0);

    IF COALESCE(v_pending_unit_count, 0) > 0 THEN
      v_status := 'PENDING';
    ELSIF COALESCE(v_error_unit_count, 0) > 0 THEN
      v_status := 'ERROR';
    ELSIF COALESCE(v_stale_unit_count, 0) > 0 THEN
      v_status := 'STALE';
    ELSE
      v_status := 'PASSED';
    END IF;

    v_is_stale := v_status IN ('STALE', 'ERROR');

    v_scope_hash := COALESCE(
      NULLIF(BTRIM(COALESCE(v_progress_summary->>'scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), ''),
      NULLIF(BTRIM(COALESCE(v_batch.freshness_scope_hash, '')), '')
    );

    IF v_scope_hash IS NULL THEN
      WITH scope_key_rows AS (
        SELECT
          scope_unit.unit_ordinal,
          scope_unit.unit_key
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
      )
      SELECT md5(COALESCE(jsonb_agg(scope_key_rows.unit_key ORDER BY scope_key_rows.unit_ordinal, scope_key_rows.unit_key), '[]'::jsonb)::text)
      INTO v_scope_hash
      FROM scope_key_rows;
    END IF;

    WITH reason_values AS (
      SELECT DISTINCT NULLIF(BTRIM(reason_source.reason_value), '') AS reason_value
      FROM (
        SELECT reason_text.reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
              THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
            ELSE '[]'::jsonb
          END
        ) AS reason_text(reason_value)
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)

        UNION ALL

        SELECT scope_unit.error_json->>'code' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL

        UNION ALL

        SELECT scope_unit.error_json->>'reason' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL
      ) AS reason_source
      WHERE NULLIF(BTRIM(reason_source.reason_value), '') IS NOT NULL
    )
    SELECT COALESCE(jsonb_agg(reason_values.reason_value ORDER BY reason_values.reason_value), '[]'::jsonb)
    INTO v_stale_reasons
    FROM reason_values;

    WITH reason_values AS (
      SELECT NULLIF(BTRIM(reason_source.reason_value), '') AS reason_value
      FROM (
        SELECT reason_text.reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        CROSS JOIN LATERAL jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
              THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
            ELSE '[]'::jsonb
          END
        ) AS reason_text(reason_value)
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)

        UNION ALL

        SELECT scope_unit.error_json->>'code' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL

        UNION ALL

        SELECT scope_unit.error_json->>'reason' AS reason_value
        FROM public.banking_pay_operation_scope_units AS scope_unit
        WHERE scope_unit.operation_id = p_operation_id
          AND scope_unit.phase = 'FRESHNESS'
          AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
          AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
          AND scope_unit.error_json IS NOT NULL
      ) AS reason_source
      WHERE NULLIF(BTRIM(reason_source.reason_value), '') IS NOT NULL
    ),
    reason_counts AS (
      SELECT
        reason_values.reason_value AS reason_key,
        COUNT(*)::integer AS reason_count
      FROM reason_values
      GROUP BY reason_values.reason_value
    )
    SELECT COALESCE(jsonb_object_agg(reason_counts.reason_key, reason_counts.reason_count ORDER BY reason_counts.reason_key), '{}'::jsonb)
    INTO v_stale_reason_counts
    FROM reason_counts;

    WITH key_failure_units AS (
      SELECT DISTINCT scope_unit.id
      FROM public.banking_pay_operation_scope_units AS scope_unit
      LEFT JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,stale_reasons}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,stale_reasons}'
          ELSE '[]'::jsonb
        END
      ) AS reason_text(reason_value) ON true
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        AND (
          UPPER(BTRIM(COALESCE(reason_text.reason_value, ''))) IN ('POST_DRAFT_KEY_RESOLUTION_FAILED', 'KEY_RESOLUTION_FAILED')
          OR UPPER(BTRIM(COALESCE(reason_text.reason_value, ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'code', ''))) IN ('POST_DRAFT_KEY_RESOLUTION_FAILED', 'KEY_RESOLUTION_FAILED')
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'code', ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'reason', ''))) LIKE '%KEY_RESOLUTION%'
          OR UPPER(BTRIM(COALESCE(scope_unit.error_json->>'message', ''))) LIKE '%KEY_RESOLUTION%'
        )
    )
    SELECT COUNT(*)::integer
    INTO v_key_resolution_failure_count
    FROM key_failure_units;

    WITH diff_items AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        diff_item.diff_value
      FROM public.banking_pay_operation_scope_units AS scope_unit
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,diff}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,diff}'
          WHEN jsonb_typeof(scope_unit.unit_payload_json #> '{validation_result,diff_sample}') = 'array'
            THEN scope_unit.unit_payload_json #> '{validation_result,diff_sample}'
          ELSE '[]'::jsonb
        END
      ) AS diff_item(diff_value)
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key, diff_item.diff_value::text
      LIMIT 50
    )
    SELECT COALESCE(jsonb_agg(diff_items.diff_value ORDER BY diff_items.unit_ordinal, diff_items.unit_key, diff_items.diff_value::text), '[]'::jsonb)
    INTO v_diff_sample
    FROM diff_items;

    WITH failed_rows AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        jsonb_build_object(
          'unit_id', scope_unit.id::text,
          'unit_key', scope_unit.unit_key,
          'status', UPPER(BTRIM(COALESCE(scope_unit.status, ''))),
          'error', COALESCE(scope_unit.error_json, '{}'::jsonb)
        ) AS failed_json
      FROM public.banking_pay_operation_scope_units AS scope_unit
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
        AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) = 'ERROR'
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
      LIMIT 20
    )
    SELECT COALESCE(jsonb_agg(failed_rows.failed_json ORDER BY failed_rows.unit_ordinal, failed_rows.unit_key), '[]'::jsonb)
    INTO v_failed_sample
    FROM failed_rows;

    WITH unit_hash_rows AS (
      SELECT
        scope_unit.unit_ordinal,
        scope_unit.unit_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(scope_unit.result_hash, '')), ''),
          md5((jsonb_build_object(
            'unit_key', scope_unit.unit_key,
            'status', UPPER(BTRIM(COALESCE(scope_unit.status, ''))),
            'error_json', COALESCE(scope_unit.error_json, '{}'::jsonb),
            'validation_result', COALESCE(scope_unit.unit_payload_json->'validation_result', '{}'::jsonb)
          ))::text)
        ) AS unit_result_hash
      FROM public.banking_pay_operation_scope_units AS scope_unit
      WHERE scope_unit.operation_id = p_operation_id
        AND scope_unit.phase = 'FRESHNESS'
        AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
        AND (scope_unit.pay_batch_id = v_pay_batch_id OR scope_unit.pay_batch_id IS NULL)
      ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
    )
    SELECT COALESCE(jsonb_agg(unit_hash_rows.unit_result_hash ORDER BY unit_hash_rows.unit_ordinal, unit_hash_rows.unit_key), '[]'::jsonb)
    INTO v_unit_result_hashes
    FROM unit_hash_rows;

    IF COALESCE(v_failed_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'UNIT_ERROR') THEN
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('UNIT_ERROR');
      v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('UNIT_ERROR', COALESCE(v_failed_count, 0));
    END IF;

    IF COALESCE(v_key_resolution_failure_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'KEY_RESOLUTION_FAILED') THEN
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('KEY_RESOLUTION_FAILED');
      v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('KEY_RESOLUTION_FAILED', COALESCE(v_key_resolution_failure_count, 0));
    END IF;

    -- A24: never report PASSED over a Source entitlement head made current after this Draft froze.
    IF v_status = 'PASSED' THEN
      v_source_head_drift := private.pay_batch_source_head_drift_v1(v_pay_batch_id);
      IF jsonb_array_length(v_source_head_drift) > 0 THEN
        v_status := 'STALE';
        v_is_stale := true;
        v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('SOURCE_ENTITLEMENT_HEAD_CHANGED');
        v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('SOURCE_ENTITLEMENT_HEAD_CHANGED', jsonb_array_length(v_source_head_drift));
        v_diff_sample := COALESCE(v_diff_sample, '[]'::jsonb) || v_source_head_drift;
      END IF;
    END IF;
    v_hash_basis := jsonb_build_object(
      'source', 'banking_pay_operation_scope_units',
      'validation_complete', v_validation_complete,
      'is_stale', v_is_stale,
      'status', v_status,
      'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'checked_count', COALESCE(v_checked_count, 0),
      'stale_count', COALESCE(v_stale_count, 0),
      'failed_count', COALESCE(v_failed_count, 0)
    ) || jsonb_build_object(
      'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
      'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
      'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
      'freshness_scope_hash', v_scope_hash,
      'total_units', COALESCE(v_total_unit_count, 0),
      'fresh_units', COALESCE(v_fresh_unit_count, 0),
      'stale_units', COALESCE(v_stale_unit_count, 0),
      'pending_units', COALESCE(v_pending_unit_count, 0),
      'error_units', COALESCE(v_error_unit_count, 0),
      'unit_result_hashes', COALESCE(v_unit_result_hashes, '[]'::jsonb)
    );

    IF v_status <> 'PENDING' THEN
      v_result_hash := md5(v_hash_basis::text);
      v_checked_at_utc := v_now;

      IF v_batch.freshness_operation_id = p_operation_id
         AND NULLIF(BTRIM(COALESCE(v_batch.freshness_result_hash, '')), '') = v_result_hash
         AND v_batch.freshness_checked_at_utc IS NOT NULL THEN
        v_checked_at_utc := v_batch.freshness_checked_at_utc;
      END IF;
    END IF;

    v_result := jsonb_build_object(
      'ok', true,
      'phase', 'FRESHNESS',
      'validation_complete', v_validation_complete,
      'is_stale', v_is_stale,
      'status', v_status,
      'checked_count', COALESCE(v_checked_count, 0),
      'stale_count', COALESCE(v_stale_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
      'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb)
    ) || jsonb_build_object(
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
      'diff', COALESCE(v_diff_sample, '[]'::jsonb),
      'diff_samples', COALESCE(v_diff_sample, '[]'::jsonb),
      'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
      'freshness_checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE to_jsonb(v_checked_at_utc) END,
      'checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE v_checked_at_utc::text END,
      'freshness_result_hash', v_result_hash,
      'result_hash', v_result_hash,
      'freshness_scope_hash', v_scope_hash
    ) || jsonb_build_object(
      'scope_hash', v_scope_hash,
      'total_units', COALESCE(v_total_unit_count, 0),
      'fresh_units', COALESCE(v_fresh_unit_count, 0),
      'stale_units', COALESCE(v_stale_unit_count, 0),
      'pending_units', COALESCE(v_pending_unit_count, 0),
      'error_units', COALESCE(v_error_unit_count, 0),
      'fresh_count', COALESCE(v_fresh_unit_count, 0),
      'pending_count', COALESCE(v_pending_unit_count, 0),
      'error_count', COALESCE(v_error_unit_count, 0)
    ) || jsonb_build_object(
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text,
      'progress_source', 'banking_pay_operation_scope_units'
    );

    UPDATE public.pay_batches AS pay_batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_status,
        freshness_checked_at_utc = CASE WHEN v_status <> 'PENDING' THEN v_checked_at_utc ELSE pay_batch_update.freshness_checked_at_utc END,
        freshness_result_hash = CASE WHEN v_status <> 'PENDING' THEN v_result_hash ELSE pay_batch_update.freshness_result_hash END,
        freshness_scope_hash = COALESCE(v_scope_hash, pay_batch_update.freshness_scope_hash),
        freshness_result_json = v_result
    WHERE pay_batch_update.id = v_pay_batch_id;

    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = jsonb_strip_nulls(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'freshness_summary', v_result,
            'freshness_validation_status', v_status,
            'freshness_status', v_status,
            'freshness_result_hash', v_result_hash,
            'freshness_scope_hash', v_scope_hash,
            'freshness_checked_at_utc', CASE WHEN v_checked_at_utc IS NULL THEN NULL ELSE v_checked_at_utc::text END,
            'freshness_is_stale', v_is_stale
          )
          || jsonb_build_object(
            'freshness_total_units', COALESCE(v_total_unit_count, 0),
            'freshness_pending_units', COALESCE(v_pending_unit_count, 0),
            'freshness_stale_units', COALESCE(v_stale_unit_count, 0),
            'freshness_error_units', COALESCE(v_error_unit_count, 0)
          )
        ),
        result_json = CASE
          WHEN v_status <> 'PENDING' THEN jsonb_set(COALESCE(operation_update.result_json, '{}'::jsonb), '{freshness}', v_result, true)
          ELSE operation_update.result_json
        END,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN v_result;
  END IF;

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'RUNNING')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'FAILED')::integer,
    COUNT(*) FILTER (WHERE chunk_row.status = 'COMPLETE')::integer
  INTO
    v_total_chunk_count,
    v_pending_chunk_count,
    v_running_chunk_count,
    v_failed_chunk_count,
    v_complete_chunk_count
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.operation_id = p_operation_id
    AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
    AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE';

  IF COALESCE(v_total_chunk_count, 0) = 0 THEN
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'reason', 'NO_FRESHNESS_CHUNKS',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text
    );

    RETURN v_result;
  END IF;

  v_validation_complete := COALESCE(v_pending_chunk_count, 0) = 0
    AND COALESCE(v_running_chunk_count, 0) = 0;

  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_progress_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_batch.freshness_scope_hash, '')), '')
  );

  IF v_validation_complete IS NOT TRUE THEN
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'pending_count', COALESCE(v_pending_chunk_count, 0),
      'running_count', COALESCE(v_running_chunk_count, 0),
      'complete_count', COALESCE(v_complete_chunk_count, 0),
      'failed_count', COALESCE(v_failed_chunk_count, 0),
      'checked_count', 0,
      'stale_count', 0,
      'key_resolution_failure_count', 0,
      'diff_sample', '[]'::jsonb,
      'freshness_checked_at_utc', NULL,
      'freshness_result_hash', NULL,
      'freshness_scope_hash', v_scope_hash,
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_pay_batch_id::text
    );

    RETURN v_result;
  END IF;

  WITH chunk_results AS (
    SELECT
      chunk_row.id,
      chunk_row.status,
      COALESCE(chunk_row.result_json, '{}'::jsonb) AS result_json,
      COALESCE(chunk_row.error_json, '{}'::jsonb) AS error_json
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
  ),
  counts AS (
    SELECT
      SUM(COALESCE((chunk_results.result_json->>'checked_count')::integer, 0))::integer AS checked_count,
      SUM(COALESCE((chunk_results.result_json->>'stale_count')::integer, 0))::integer AS stale_count,
      SUM(COALESCE((chunk_results.result_json->>'key_resolution_failure_count')::integer, 0))::integer AS key_resolution_failure_count,
      COUNT(*) FILTER (WHERE chunk_results.status = 'FAILED')::integer AS failed_count,
      BOOL_OR(COALESCE((chunk_results.result_json->>'is_stale')::boolean, false)) AS any_stale,
      BOOL_OR(chunk_results.status = 'FAILED') AS any_failed
    FROM chunk_results
  )
  SELECT
    COALESCE(counts.checked_count, 0),
    COALESCE(counts.stale_count, 0),
    COALESCE(counts.key_resolution_failure_count, 0),
    COALESCE(counts.failed_count, 0),
    COALESCE(counts.any_stale, false) OR COALESCE(counts.any_failed, false) OR COALESCE(counts.key_resolution_failure_count, 0) > 0
  INTO
    v_checked_count,
    v_stale_count,
    v_key_resolution_failure_count,
    v_failed_count,
    v_is_stale
  FROM counts;

  WITH reason_values AS (
    SELECT DISTINCT reason_text.reason_value
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(chunk_row.result_json->'stale_reasons', '[]'::jsonb)) AS reason_text(reason_value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
  )
  SELECT COALESCE(jsonb_agg(reason_values.reason_value ORDER BY reason_values.reason_value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM reason_values;

  WITH reason_pairs AS (
    SELECT
      reason_entry.key AS reason_key,
      SUM(COALESCE(reason_entry.value::text::integer, 0))::integer AS reason_count
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_each(COALESCE(chunk_row.result_json->'stale_reason_counts', '{}'::jsonb)) AS reason_entry(key, value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
    GROUP BY reason_entry.key
  )
  SELECT COALESCE(jsonb_object_agg(reason_pairs.reason_key, reason_pairs.reason_count ORDER BY reason_pairs.reason_key), '{}'::jsonb)
  INTO v_stale_reason_counts
  FROM reason_pairs;

  WITH diff_items AS (
    SELECT
      chunk_row.sequence_no,
      diff_item.diff_value
    FROM public.banking_pay_operation_chunks AS chunk_row
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(chunk_row.result_json->'diff_sample', '[]'::jsonb)) AS diff_item(diff_value)
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.result_json IS NOT NULL
    ORDER BY chunk_row.sequence_no, diff_item.diff_value::text
    LIMIT 50
  )
  SELECT COALESCE(jsonb_agg(diff_items.diff_value ORDER BY diff_items.sequence_no, diff_items.diff_value::text), '[]'::jsonb)
  INTO v_diff_sample
  FROM diff_items;

  WITH chunk_hash_rows AS (
    SELECT
      chunk_row.sequence_no,
      NULLIF(BTRIM(COALESCE(chunk_row.result_json->>'chunk_result_hash', '')), '') AS chunk_result_hash
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND NULLIF(BTRIM(COALESCE(chunk_row.result_json->>'chunk_result_hash', '')), '') IS NOT NULL
    ORDER BY chunk_row.sequence_no
  )
  SELECT COALESCE(jsonb_agg(chunk_hash_rows.chunk_result_hash ORDER BY chunk_hash_rows.sequence_no), '[]'::jsonb)
  INTO v_chunk_result_hashes
  FROM chunk_hash_rows;

  WITH failed_rows AS (
    SELECT
      chunk_row.sequence_no,
      jsonb_build_object(
        'chunk_id', chunk_row.id::text,
        'sequence_no', chunk_row.sequence_no,
        'error', COALESCE(chunk_row.error_json, '{}'::jsonb)
      ) AS failed_json
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND chunk_row.phase IN ('VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE')
      AND chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      AND chunk_row.status = 'FAILED'
    ORDER BY chunk_row.sequence_no
    LIMIT 20
  )
  SELECT COALESCE(jsonb_agg(failed_rows.failed_json ORDER BY failed_rows.sequence_no), '[]'::jsonb)
  INTO v_failed_sample
  FROM failed_rows;

  IF COALESCE(v_failed_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'CHUNK_FAILED') THEN
    v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('CHUNK_FAILED');
    v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('CHUNK_FAILED', COALESCE(v_failed_count, 0));
  END IF;

  IF COALESCE(v_key_resolution_failure_count, 0) > 0 AND NOT (COALESCE(v_stale_reasons, '[]'::jsonb) ? 'KEY_RESOLUTION_FAILED') THEN
    v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('KEY_RESOLUTION_FAILED');
    v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('KEY_RESOLUTION_FAILED', COALESCE(v_key_resolution_failure_count, 0));
  END IF;

  -- A24: never report PASSED over a Source entitlement head made current after this Draft froze.
  IF COALESCE(v_failed_count, 0) = 0 AND v_is_stale IS NOT TRUE THEN
    v_source_head_drift := private.pay_batch_source_head_drift_v1(v_pay_batch_id);
    IF jsonb_array_length(v_source_head_drift) > 0 THEN
      v_is_stale := true;
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('SOURCE_ENTITLEMENT_HEAD_CHANGED');
      v_stale_reason_counts := COALESCE(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('SOURCE_ENTITLEMENT_HEAD_CHANGED', jsonb_array_length(v_source_head_drift));
      v_diff_sample := COALESCE(v_diff_sample, '[]'::jsonb) || v_source_head_drift;
    END IF;
  END IF;

  IF COALESCE(v_failed_count, 0) > 0 THEN
    v_status := 'FAILED';
  ELSIF v_is_stale THEN
    v_status := 'STALE';
  ELSE
    v_status := 'PASSED';
  END IF;

  v_hash_basis := jsonb_build_object(
    'source', 'banking_pay_operation_chunks',
    'validation_complete', true,
    'is_stale', v_is_stale,
    'status', v_status,
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
    'checked_count', COALESCE(v_checked_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'failed_count', COALESCE(v_failed_count, 0)
  ) || jsonb_build_object(
    'key_resolution_failure_count', COALESCE(v_key_resolution_failure_count, 0),
    'diff_sample', COALESCE(v_diff_sample, '[]'::jsonb),
    'failed_sample', COALESCE(v_failed_sample, '[]'::jsonb),
    'freshness_scope_hash', v_scope_hash,
    'chunk_count', COALESCE(v_total_chunk_count, 0),
    'complete_chunk_count', COALESCE(v_complete_chunk_count, 0),
    'chunk_result_hashes', COALESCE(v_chunk_result_hashes, '[]'::jsonb)
  );

  v_result_hash := md5(v_hash_basis::text);
  v_checked_at_utc := v_now;

  IF v_batch.freshness_operation_id = p_operation_id
     AND NULLIF(BTRIM(COALESCE(v_batch.freshness_result_hash, '')), '') = v_result_hash
     AND v_batch.freshness_checked_at_utc IS NOT NULL THEN
    v_checked_at_utc := v_batch.freshness_checked_at_utc;
  END IF;

  v_result := v_hash_basis || jsonb_build_object(
    'ok', true,
    'phase', 'FRESHNESS',
    'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
    'checked_at_utc', v_checked_at_utc::text,
    'freshness_result_hash', v_result_hash,
    'result_hash', v_result_hash,
    'freshness_scope_hash', v_scope_hash,
    'scope_hash', v_scope_hash,
    'operation_id', p_operation_id::text,
    'pay_batch_id', v_pay_batch_id::text,
    'progress_source', 'banking_pay_operation_chunks'
  );

  UPDATE public.pay_batches AS pay_batch_update
  SET freshness_operation_id = p_operation_id,
      freshness_validation_status = v_status,
      freshness_checked_at_utc = v_checked_at_utc,
      freshness_result_hash = v_result_hash,
      freshness_scope_hash = v_scope_hash,
      freshness_result_json = v_result
  WHERE pay_batch_update.id = v_pay_batch_id;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_result,
          'freshness_validation_status', v_status,
          'freshness_status', v_status,
          'freshness_result_hash', v_result_hash,
          'freshness_scope_hash', v_scope_hash,
          'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
          'freshness_is_stale', v_is_stale
        ),
      result_json = jsonb_set(COALESCE(operation_update.result_json, '{}'::jsonb), '{freshness}', v_result, true),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN v_result;
END;
$function$
;

-- [REPLACES] public.pay_batch_get(p_pay_batch_id uuid, p_actor_user_id uuid, p_detail_mode text, p_recommended_page_size integer)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_batch_get(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_detail_mode text DEFAULT 'AUTO'::text, p_recommended_page_size integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch record;
  v_candidates jsonb := '[]'::jsonb;
  v_transfers jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;

  -- ✅ NEW: derived batch kind + channels
  v_batch_kind text := null;
