          'next_retry_description', v_next_retry_description,
          'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
          'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
          'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
          'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
          'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
          'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
          'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb)
        )
        || jsonb_build_object(
          'live_signal_version', COALESCE(v_batch_signal_version, 0),
          'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
          'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
          'alert_version', COALESCE(v_batch_alert_version, 0),
          'overview_version', COALESCE(v_batch_overview_version, 0),
          'last_status_hash', v_batch_last_status_hash,
          'last_alert_hash', v_batch_last_alert_hash,
          'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb),
          'banking_system_snapshot', v_batch.banking_system_snapshot,
          'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,

          -- Neutral (rail-generic) manual confirm aliases (keep legacy keys too)
          'manual_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'manual_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'monzo_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'monzo_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'last_status_checked_at_utc', v_batch.last_status_checked_at_utc,
          'last_funds_check_at_utc', v_batch.last_funds_check_at_utc,
          'last_funds_check_json', v_batch.last_funds_check_json
        ) || jsonb_build_object(
          'funding_account_ref', v_batch.funding_account_ref,
          'blocked_funds_required_gbp', v_blocked_funds_required_gbp,
          'blocked_funds_available_gbp', v_blocked_funds_available_gbp,
          'blocked_funds_required_gbp_display', v_blocked_funds_required_gbp_display,
          'blocked_funds_available_gbp_display', v_blocked_funds_available_gbp_display,
          'blocked_funds_sufficient', v_blocked_funds_sufficient,
          'blocked_funds_provider', v_blocked_funds_provider,
          'blocked_funds_env', v_blocked_funds_env,
          'blocked_funds_account_ref', v_blocked_funds_account_ref,
          'banking_alerts', v_banking_alerts,
          'banking_alert_kind', v_banking_alert_kind,
          'banking_alert_severity', v_banking_alert_severity,
          'banking_alert_label', v_banking_alert_label,
          'banking_alert_reason', v_banking_alert_reason,
          'banking_alert_fingerprint', v_banking_alert_fingerprint,
          'banking_alert_acknowledged_for_user', v_banking_alert_acknowledged_for_user,
          'banking_alert_requires_attention', v_banking_alert_requires_attention
        ))
        || jsonb_build_object(
          'can_retry_blocked_funds', v_can_retry_blocked_funds,
          'no_submission_evidence_flags', v_no_submission_evidence_flags,
          'blocked_funds_payment_issue', v_blocked_funds_payment_issue,
          'payment_issues', v_payment_issues,
          'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
          'payment_execution_review', v_payment_execution_review,
          'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
          'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
          'review_reason_code', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submit_review_reason_code ELSE NULL::text END,
          'provider_submission_status', CASE WHEN v_provider_submit_actual_context AND COALESCE(v_clean_paid_or_settled_success, false) IS NOT TRUE THEN v_provider_submission_status ELSE NULL::text END,
          'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
          'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
          'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
          -- Rail-generic scheduling/execution fields
          'rail_provider_snapshot', v_batch.rail_provider_snapshot,
          'rail_env_snapshot', v_batch.rail_env_snapshot,
          'schedule_kind', v_batch.schedule_kind,
          'scheduled_at_utc', v_batch.scheduled_at_utc,
          'executing_started_at_utc', v_batch.executing_started_at_utc,

          -- Bulk payment reference fields
          'bulk_ref_num', v_batch.bulk_ref_num,
          'bulk_ref_date', case when v_batch.bulk_ref_date is null then null else v_batch.bulk_ref_date::text end,
          'bulk_reference', v_batch.bulk_reference
        )
      ),
      'candidates', v_candidates,
      'transfers', v_transfers,
      'items', v_items
    );
end;
$function$
;

-- [REPLACES] public.pay_batch_get_section_page(p_pay_batch_id uuid, p_section text, p_cursor_json jsonb, p_limit integer, p_actor_user_id uuid, p_filters_json jsonb, p_sort_json jsonb, p_purpose text)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_batch_get_section_page(p_pay_batch_id uuid, p_section text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100, p_actor_user_id uuid DEFAULT NULL::uuid, p_filters_json jsonb DEFAULT '{}'::jsonb, p_sort_json jsonb DEFAULT '{}'::jsonb, p_purpose text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch public.pay_batches%ROWTYPE;
  v_section text := LOWER(REPLACE(NULLIF(BTRIM(COALESCE(p_section, '')), ''), '-', '_'));
  v_purpose text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_purpose, '')), ''), '-', '_'));
  v_limit integer := COALESCE(p_limit, 100);
  v_cursor_id uuid := NULL::uuid;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := NULL::jsonb;
  v_returned_count integer := 0;
  v_raw_count integer := 0;
  v_last_cursor_text text := NULL::text;
  v_known_total_count integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_server_time_utc timestamptz := now();
  v_live_signal_version bigint := 0;
  v_payment_status_version bigint := 0;
  v_correction_progress_version bigint := 0;
  v_alert_version bigint := 0;
  v_overview_version bigint := 0;
  v_last_status_hash text := NULL::text;
  v_last_alert_hash text := NULL::text;
  v_known_live_signal_version bigint := NULL::bigint;
  v_changed_since_version boolean := false;
  v_section_page_signature text := NULL::text;
  v_freshness_summary jsonb := '{}'::jsonb;
  v_candidate_scope_type text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id_text text := NULL::text;
  v_candidate_scope_candidate_id_text text := NULL::text;
  v_candidate_scope_pay_batch_candidate_id uuid := NULL::uuid;
  v_candidate_scope_candidate_id uuid := NULL::uuid;
  v_candidate_scope_actual_pay_batch_id uuid := NULL::uuid;
  v_candidate_scope_actual_candidate_id uuid := NULL::uuid;
  v_candidate_scope_enabled boolean := false;
BEGIN
  -- A30 (PRE-EXISTING fix, H6 M3): a batch whose V8 Draft operation is still being prepared (or failing and
  -- retrying) is not a published Draft. Its partial content is not readable until the operation finishes.
  IF private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id) THEN
    RAISE EXCEPTION 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED'
      USING ERRCODE = '55000',
            DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED',
              'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  PERFORM public.banking_pay_hot_path_budget_apply(
    CASE
      WHEN v_purpose = 'OVERVIEW' OR v_section IN ('overview', 'overview_items') THEN 'OVERVIEW_PAGE'
      ELSE 'EXPLICIT_DIAGNOSTIC'
    END
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF v_section IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_GET_SECTION_PAGE_SECTION_REQUIRED')::text;
  END IF;

  IF v_section = 'overview' THEN
    v_section := 'overview_items';
  END IF;

  IF v_section = 'overview_items' THEN
    v_purpose := 'OVERVIEW';
  END IF;

  IF v_purpose IS NULL THEN
    v_purpose := 'SECTION_PAGE';
  END IF;

  IF v_purpose NOT IN (
    'SECTION_PAGE',
    'OVERVIEW',
    'DETAIL',
    'PAYE_WORKSHEET',
    'CURRENT_PAYMENT_STATUS',
    'PAYMENT_ISSUES',
    'REMITTANCE'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_INVALID_PURPOSE',
              'purpose', v_purpose,
              'allowed_purposes', jsonb_build_array(
                'SECTION_PAGE',
                'OVERVIEW',
                'DETAIL',
                'PAYE_WORKSHEET',
                'CURRENT_PAYMENT_STATUS',
                'PAYMENT_ISSUES',
                'REMITTANCE'
              )
            )::text;
  END IF;

  IF v_purpose = 'OVERVIEW' AND v_section <> 'overview_items' THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_OVERVIEW_SECTION_NOT_ALLOWED',
              'purpose', v_purpose,
              'section', v_section,
              'message', 'Overview purpose may only load overview_items.'
            )::text;
  END IF;

  IF v_section NOT IN (
    'overview_items',
    'candidates',
    'items',
    'item_breakdowns',
    'transfers',
    'current_payment_status',
    'finance_case_groups',
    'remittances',
    'communications',
    'auth_history',
    'events'
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_UNSUPPORTED_SECTION',
              'section', v_section
            )::text;
  END IF;

  v_limit := GREATEST(1, LEAST(v_limit, CASE WHEN v_section = 'overview_items' OR v_purpose = 'OVERVIEW' THEN 100 ELSE 250 END));

  IF p_cursor_json IS NOT NULL
     AND jsonb_typeof(p_cursor_json) = 'object'
     AND NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_cursor_id := COALESCE(p_cursor_json->>'last_id', p_cursor_json->>'last_group_id')::uuid;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  SELECT pay_batch_row.*
  INTO v_batch
  FROM public.pay_batches AS pay_batch_row
  WHERE pay_batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_filters_json IS NOT NULL AND jsonb_typeof(p_filters_json) = 'object' THEN
    BEGIN
      v_known_live_signal_version := NULLIF(BTRIM(COALESCE(
        p_filters_json ->> 'known_live_signal_version',
        p_filters_json ->> 'known_version',
        p_filters_json ->> 'live_signal_version',
        p_filters_json #>> '{live_signal,version}',
        ''
      )), '')::bigint;
    EXCEPTION WHEN OTHERS THEN
      v_known_live_signal_version := NULL::bigint;
    END;

    v_candidate_scope_type := NULLIF(
      UPPER(REGEXP_REPLACE(BTRIM(COALESCE(
        p_filters_json ->> 'scope_type',
        p_filters_json ->> 'scopeType',
        ''
      )), '[[:space:]-]+', '_', 'g')),
      ''
    );
    v_candidate_scope_pay_batch_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'pay_batch_candidate_id',
      p_filters_json ->> 'payBatchCandidateId',
      ''
    )), '');
    v_candidate_scope_candidate_id_text := NULLIF(BTRIM(COALESCE(
      p_filters_json ->> 'candidate_id',
      p_filters_json ->> 'candidateId',
      ''
    )), '');
  END IF;

  IF v_candidate_scope_type = 'PAY_BATCH_CANDIDATE' THEN
    IF v_section <> 'items' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_SECTION_NOT_ALLOWED',
                'section', v_section,
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text IS NULL
       OR v_candidate_scope_candidate_id_text IS NULL THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_REQUIRED',
                'scope_type', v_candidate_scope_type,
                'requires', jsonb_build_array('pay_batch_candidate_id', 'candidate_id')
              )::text;
    END IF;

    IF v_candidate_scope_pay_batch_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_candidate_scope_candidate_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_IDENTITY_INVALID',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_pay_batch_candidate_id := v_candidate_scope_pay_batch_candidate_id_text::uuid;
    v_candidate_scope_candidate_id := v_candidate_scope_candidate_id_text::uuid;

    SELECT
      candidate_scope.pay_batch_id,
      candidate_scope.candidate_id
    INTO
      v_candidate_scope_actual_pay_batch_id,
      v_candidate_scope_actual_candidate_id
    FROM public.pay_batch_candidates AS candidate_scope
    WHERE candidate_scope.id = v_candidate_scope_pay_batch_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_NOT_FOUND',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    IF v_candidate_scope_actual_pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_OUT_OF_BATCH',
                'scope_type', v_candidate_scope_type,
                'pay_batch_id', p_pay_batch_id::text
              )::text;
    END IF;

    IF v_candidate_scope_actual_candidate_id IS DISTINCT FROM v_candidate_scope_candidate_id THEN
      RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_MISMATCH',
                'scope_type', v_candidate_scope_type
              )::text;
    END IF;

    v_candidate_scope_enabled := true;
  ELSIF v_section = 'items'
        AND (v_candidate_scope_pay_batch_candidate_id_text IS NOT NULL OR v_candidate_scope_candidate_id_text IS NOT NULL) THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_SECTION_PAGE_CANDIDATE_SCOPE_TYPE_REQUIRED',
              'required_scope_type', 'PAY_BATCH_CANDIDATE'
            )::text;
  END IF;

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash
  INTO
    v_live_signal_version,
    v_payment_status_version,
    v_correction_progress_version,
    v_alert_version,
    v_overview_version,
    v_last_status_hash,
    v_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_live_signal_version := 0;
    v_payment_status_version := 0;
    v_correction_progress_version := 0;
    v_alert_version := 0;
    v_overview_version := 0;
    v_last_status_hash := NULL::text;
    v_last_alert_hash := NULL::text;
  END IF;

  v_changed_since_version := (
    v_known_live_signal_version IS NOT NULL
    AND COALESCE(v_live_signal_version, 0) > v_known_live_signal_version
  );

  v_freshness_summary := jsonb_strip_nulls(jsonb_build_object(
    'freshness_validation_status', v_batch.freshness_validation_status,
    'freshness_checked_at_utc', CASE WHEN v_batch.freshness_checked_at_utc IS NULL THEN NULL::text ELSE v_batch.freshness_checked_at_utc::text END,
    'freshness_result_hash', v_batch.freshness_result_hash,
    'freshness_scope_hash', v_batch.freshness_scope_hash
  ));

  IF v_section = 'overview_items' THEN
    WITH raw_item_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.pay_bank_transfer_id,
        NULLIF(BTRIM(COALESCE(
          pay_bank_transfer_page.payee_name,
          pay_batch_item_page.payout_instruction_snapshot_json->>'payee_name',
          pay_batch_item_page.payout_instruction_snapshot_json->>'account_holder_name',
          pay_batch_candidate_page.candidate_display_name
        )), '') AS payee_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
          pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
          timesheet_snapshot_page.target_snapshot_json->>'week_ending_date',
          pay_batch_item_page.payout_instruction_snapshot_json->>'week_ending_bucket'
        )), '') AS week_ending_date,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
          pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
          pay_batch_item_page.frozen_resolution_result_json->>'client_name',
          timesheet_snapshot_page.target_snapshot_json->>'client_name'
        )), '') AS client_name,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'role',
          pay_batch_item_page.frozen_source_basis_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json->>'role',
          pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
          pay_batch_item_page.frozen_resolution_payload_json->>'role',
          pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
          timesheet_snapshot_page.target_snapshot_json->>'role',
          timesheet_snapshot_page.target_snapshot_json->>'job_title'
        )), '') AS role,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item_page.frozen_source_basis_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json->>'date',
          pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
          pay_batch_item_page.frozen_resolution_payload_json->>'date',
          CASE
            WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
             AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
            THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
            ELSE NULL::text
          END
        )), '') AS worked_date,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
          THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
          ELSE NULL::text
        END AS additional_code
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.pay_batch_candidate_id = pay_batch_candidate_page.id
      LEFT JOIN public.pay_bank_transfers AS pay_bank_transfer_page
        ON pay_bank_transfer_page.id = pay_batch_item_page.pay_bank_transfer_id
      LEFT JOIN LATERAL (
        SELECT snapshot_page_inner.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_page_inner
        WHERE snapshot_page_inner.pay_batch_id = pay_batch_candidate_page.pay_batch_id
          AND snapshot_page_inner.timesheet_id = pay_batch_item_page.timesheet_id
          AND snapshot_page_inner.candidate_id = pay_batch_candidate_page.candidate_id
          AND (
            snapshot_page_inner.pay_channel IS NOT DISTINCT FROM pay_batch_item_page.pay_channel
            OR snapshot_page_inner.pay_channel IS NULL
            OR pay_batch_item_page.pay_channel IS NULL
          )
        ORDER BY snapshot_page_inner.created_at_utc DESC, snapshot_page_inner.id DESC
        LIMIT 1
      ) AS timesheet_snapshot_page ON true
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
    ),
    raw_item_rows_with_grouping AS (
      SELECT
        raw_item_rows.*,
        raw_item_rows.item_type AS source_item_type,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN 'TIMESHEET_PAYMENT'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'EXPENSE'
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN 'MILEAGE'
          ELSE 'ITEM'
        END AS overview_group_kind,
        CASE
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'SEGMENT_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
           AND UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.frozen_component_key_type, '')), '')) = 'TS_DAY'
            THEN CONCAT_WS('|', 'TIMESHEET_PAYMENT', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'EXPENSE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'EXPENSE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          WHEN UPPER(NULLIF(BTRIM(COALESCE(raw_item_rows.item_type, '')), '')) = 'MILEAGE_DELTA'
           AND raw_item_rows.timesheet_id IS NOT NULL
            THEN CONCAT_WS('|', 'MILEAGE', raw_item_rows.pay_batch_candidate_id::text, COALESCE(raw_item_rows.pay_channel, ''), raw_item_rows.timesheet_id::text, COALESCE(raw_item_rows.week_ending_date, ''))
          ELSE CONCAT_WS('|', 'ITEM', raw_item_rows.id::text)
        END AS overview_group_key
      FROM raw_item_rows
    ),
    grouped_rows AS (
      SELECT
        (ARRAY_AGG(group_source.id ORDER BY group_source.id ASC))[1] AS id,
        (ARRAY_AGG(group_source.pay_batch_candidate_id ORDER BY group_source.id ASC))[1] AS pay_batch_candidate_id,
        (ARRAY_AGG(group_source.candidate_id ORDER BY group_source.id ASC))[1] AS candidate_id,
        (ARRAY_AGG(group_source.candidate_tms_ref ORDER BY group_source.id ASC))[1] AS candidate_tms_ref,
        (ARRAY_AGG(group_source.candidate_display_name ORDER BY group_source.id ASC))[1] AS candidate_display_name,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'TIMESHEET_PAYMENT'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'EXPENSE'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'MILEAGE'
          ELSE (ARRAY_AGG(group_source.item_type ORDER BY group_source.id ASC))[1]
        END AS item_type,
        (ARRAY_AGG(group_source.source_item_type ORDER BY group_source.id ASC))[1] AS source_item_type,
        (ARRAY_AGG(group_source.timesheet_id ORDER BY group_source.id ASC))[1] AS timesheet_id,
        (ARRAY_AGG(group_source.pay_channel ORDER BY group_source.id ASC))[1] AS pay_channel,
        (ARRAY_AGG(group_source.source_ref ORDER BY group_source.id ASC) FILTER (WHERE group_source.source_ref IS NOT NULL))[1] AS source_ref,
        CASE
          WHEN group_source.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
          WHEN group_source.overview_group_kind = 'EXPENSE' THEN 'Expense'
          WHEN group_source.overview_group_kind = 'MILEAGE' THEN 'Mileage'
          ELSE (ARRAY_AGG(group_source.description ORDER BY group_source.id ASC))[1]
        END AS description,
        ROUND(SUM(COALESCE(group_source.amount_ex_vat, 0)), 2)::numeric(12,2) AS amount_ex_vat,
        ROUND(SUM(COALESCE(group_source.amount_vat, 0)), 2)::numeric(12,2) AS amount_vat,
        ROUND(SUM(COALESCE(group_source.amount_inc_vat, 0)), 2)::numeric(12,2) AS amount_inc_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_ex_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_ex_vat, group_source.amount_ex_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_ex_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_vat, group_source.amount_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_vat,
        CASE
          WHEN BOOL_OR(group_source.frozen_target_amount_inc_vat IS NOT NULL)
          THEN ROUND(SUM(COALESCE(group_source.frozen_target_amount_inc_vat, group_source.amount_inc_vat, 0)), 2)::numeric(12,2)
          ELSE NULL::numeric(12,2)
        END AS frozen_target_amount_inc_vat,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_type ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_type,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_key_value ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_key_value,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.frozen_component_classification::text ORDER BY group_source.id ASC))[1]
          ELSE NULL::text
        END AS frozen_component_classification,
        (ARRAY_AGG(group_source.frozen_source_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_source_pay_method IS NOT NULL))[1] AS frozen_source_pay_method,
        (ARRAY_AGG(group_source.frozen_target_pay_method ORDER BY group_source.id ASC) FILTER (WHERE group_source.frozen_target_pay_method IS NOT NULL))[1] AS frozen_target_pay_method,
        (ARRAY_AGG(group_source.pay_bank_transfer_id ORDER BY group_source.id ASC) FILTER (WHERE group_source.pay_bank_transfer_id IS NOT NULL))[1] AS pay_bank_transfer_id,
        (ARRAY_AGG(group_source.payee_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.payee_name IS NOT NULL))[1] AS payee_name,
        (ARRAY_AGG(group_source.week_ending_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.week_ending_date IS NOT NULL))[1] AS week_ending_date,
        (ARRAY_AGG(group_source.client_name ORDER BY group_source.id ASC) FILTER (WHERE group_source.client_name IS NOT NULL))[1] AS client_name,
        (ARRAY_AGG(group_source.role ORDER BY group_source.id ASC) FILTER (WHERE group_source.role IS NOT NULL))[1] AS role,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.worked_date ORDER BY group_source.id ASC) FILTER (WHERE group_source.worked_date IS NOT NULL))[1]
          ELSE NULL::text
        END AS worked_date,
        CASE
          WHEN group_source.overview_group_kind = 'ITEM'
          THEN (ARRAY_AGG(group_source.additional_code ORDER BY group_source.id ASC) FILTER (WHERE group_source.additional_code IS NOT NULL))[1]
          ELSE NULL::text
        END AS additional_code,
        group_source.overview_group_kind,
        (COUNT(*) > 1)::boolean AS overview_grouped,
        COUNT(*)::integer AS overview_grouped_item_count,
        TO_JSONB(ARRAY_AGG(group_source.id::text ORDER BY group_source.id ASC)) AS pay_batch_item_ids,
        COALESCE(
          jsonb_agg(
            jsonb_strip_nulls(jsonb_build_object(
              'pay_batch_item_id', group_source.id::text,
              'key_type', group_source.frozen_component_key_type,
              'key_value', group_source.frozen_component_key_value
            ))
            ORDER BY group_source.id ASC
          ) FILTER (
            WHERE group_source.frozen_component_key_type IS NOT NULL
               OR group_source.frozen_component_key_value IS NOT NULL
          ),
          '[]'::jsonb
        ) AS grouped_frozen_economic_keys
      FROM raw_item_rows_with_grouping AS group_source
      GROUP BY
        group_source.overview_group_key,
        group_source.overview_group_kind
    ),
    page_rows AS (
      SELECT grouped_rows.*
      FROM grouped_rows
      WHERE v_cursor_id IS NULL OR grouped_rows.id > v_cursor_id
      ORDER BY grouped_rows.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'id', page_rows.id::text,
              'pay_batch_item_id', page_rows.id::text,
              'pay_batch_item_ids', COALESCE(page_rows.pay_batch_item_ids, '[]'::jsonb),
              'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
              'candidate_id', page_rows.candidate_id::text,
              'candidate_tms_ref', page_rows.candidate_tms_ref,
              'candidate_display_name', page_rows.candidate_display_name,
              'candidate_name', page_rows.candidate_display_name,
              'payee_name', COALESCE(page_rows.payee_name, page_rows.candidate_display_name),
              'item_type', page_rows.item_type,
              'source_item_type', page_rows.source_item_type,
              'overview_group_kind', page_rows.overview_group_kind,
              'overview_grouped', page_rows.overview_grouped,
              'overview_grouped_item_count', page_rows.overview_grouped_item_count,
              'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
              'pay_channel', page_rows.pay_channel,
              'source_ref', page_rows.source_ref,
              'source_reference', page_rows.source_ref,
              'description', page_rows.description
            )
            || jsonb_build_object(
              'amount_ex_vat', page_rows.amount_ex_vat,
              'amount_vat', page_rows.amount_vat,
              'amount_inc_vat', page_rows.amount_inc_vat,
              'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
              'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
              'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat,
              'frozen_economic_key_type', page_rows.frozen_component_key_type,
              'frozen_economic_key_value', page_rows.frozen_component_key_value,
              'grouped_frozen_economic_keys', COALESCE(page_rows.grouped_frozen_economic_keys, '[]'::jsonb),
              'frozen_component_classification', page_rows.frozen_component_classification,
              'frozen_source_pay_method', page_rows.frozen_source_pay_method,
              'frozen_target_pay_method', page_rows.frozen_target_pay_method,
              'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'additional_code', page_rows.additional_code,
              'draft_not_submitted', COALESCE(UPPER(BTRIM(COALESCE(v_batch.status, ''))) IN ('DRAFT', 'DRAFT_CREATED'), false)
                AND COALESCE(UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) IN ('', 'NOT_SUBMITTED', 'NONE'), true)
            )
            || jsonb_build_object(
              'frozen_component_key_type', page_rows.frozen_component_key_type,
              'frozen_component_key_value', page_rows.frozen_component_key_value,
              'line_kind', page_rows.item_type,
              'unit_name', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'unit_label', CASE
                WHEN page_rows.overview_group_kind = 'TIMESHEET_PAYMENT' THEN 'Timesheet payment'
                WHEN page_rows.overview_group_kind = 'EXPENSE' THEN 'Expense'
                WHEN page_rows.overview_group_kind = 'MILEAGE' THEN 'Mileage'
                ELSE COALESCE(page_rows.additional_code, page_rows.role)
              END,
              'display_context_json', jsonb_strip_nulls(jsonb_build_object(
                'week_ending_date', page_rows.week_ending_date,
                'client_name', page_rows.client_name,
                'role', page_rows.role,
                'worked_date', page_rows.worked_date,
                'additional_code', page_rows.additional_code,
                'overview_group_kind', page_rows.overview_group_kind,
                'overview_grouped_item_count', page_rows.overview_grouped_item_count
              ))
            )
          )
          ORDER BY page_rows.id ASC
        ),
        '[]'::jsonb
      ),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO
      v_items,
      v_raw_count,
      v_last_cursor_text
    FROM page_rows;

ELSIF v_section = 'candidates' THEN
    WITH page_rows AS (
      SELECT
        pay_batch_candidate_page.*,
        latest_paye_net_input.id AS latest_paye_net_input_id,
        latest_paye_net_input.source AS paye_net_source,
        latest_paye_net_input.net_amount AS paye_net_amount,
        latest_paye_net_input.imported_at_utc AS paye_net_imported_at_utc,
        latest_paye_net_input.file_name AS paye_net_file_name,
        latest_paye_net_input.file_hash AS paye_net_file_hash,
        ROW_NUMBER() OVER (ORDER BY pay_batch_candidate_page.id ASC) AS row_ordinal
      FROM public.pay_batch_candidates AS pay_batch_candidate_page
      LEFT JOIN LATERAL (
        SELECT
          paye_net_input_page.id,
          paye_net_input_page.source,
          paye_net_input_page.net_amount,
          paye_net_input_page.imported_at_utc,
          paye_net_input_page.file_name,
          paye_net_input_page.file_hash
        FROM public.pay_batch_paye_net_inputs AS paye_net_input_page
        WHERE paye_net_input_page.pay_batch_candidate_id = pay_batch_candidate_page.id
        ORDER BY paye_net_input_page.imported_at_utc DESC, paye_net_input_page.id DESC
        LIMIT 1
      ) AS latest_paye_net_input ON true
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_candidate_page.id > v_cursor_id)
      ORDER BY pay_batch_candidate_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'paye_state', page_rows.paye_state,
            'mismatch_settlement_choice', page_rows.mismatch_settlement_choice,
            'gross_preview', page_rows.gross_preview,
            'net_bank_amount', page_rows.net_bank_amount,
            'debt_created', page_rows.debt_created,
            'loan_repayment_taken', page_rows.loan_repayment_taken,
            'overpayment_recovery_taken', page_rows.overpayment_recovery_taken,
            'awaiting_net_amount', page_rows.awaiting_net_amount,
            'settlement_status', page_rows.settlement_status,
            'settled_at_utc', page_rows.settled_at_utc,
            'settled_via', page_rows.settled_via,
            'remittance_trigger_status', page_rows.remittance_trigger_status,
            'remittance_sent_at_utc', page_rows.remittance_sent_at_utc,
            'last_remittance_error', page_rows.last_remittance_error,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'paye_net_amount', page_rows.paye_net_amount,
            'paye_net_source', page_rows.paye_net_source,
            'paye_net_imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
            'latest_paye_net_input', CASE
              WHEN page_rows.latest_paye_net_input_id IS NULL THEN NULL::jsonb
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'id', page_rows.latest_paye_net_input_id::text,
                'pay_batch_candidate_id', page_rows.id::text,
                'candidate_id', page_rows.candidate_id::text,
                'source', page_rows.paye_net_source,
                'net_amount', page_rows.paye_net_amount,
                'imported_at_utc', CASE WHEN page_rows.paye_net_imported_at_utc IS NULL THEN NULL::text ELSE page_rows.paye_net_imported_at_utc::text END,
                'file_name', page_rows.paye_net_file_name,
                'file_hash', page_rows.paye_net_file_hash
              ))
            END
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'items' THEN
    WITH candidate_scoped_item_ids AS MATERIALIZED (
      SELECT pay_batch_item_scope.id
      FROM public.pay_batch_items AS pay_batch_item_scope
      JOIN public.pay_batch_candidates AS pay_batch_candidate_scope
        ON pay_batch_candidate_scope.id = pay_batch_item_scope.pay_batch_candidate_id
      WHERE pay_batch_candidate_scope.pay_batch_id = p_pay_batch_id
        AND (
          v_candidate_scope_enabled IS NOT TRUE
          OR (
            pay_batch_candidate_scope.id = v_candidate_scope_pay_batch_candidate_id
            AND pay_batch_candidate_scope.candidate_id = v_candidate_scope_candidate_id
          )
        )
        AND (v_cursor_id IS NULL OR pay_batch_item_scope.id > v_cursor_id)
      ORDER BY pay_batch_item_scope.id ASC
      LIMIT (v_limit + 1)
    ), page_rows AS (
      SELECT
        pay_batch_item_page.id,
        pay_batch_item_page.pay_batch_candidate_id,
        pay_batch_candidate_page.candidate_id,
        pay_batch_candidate_page.candidate_tms_ref,
        pay_batch_candidate_page.candidate_display_name,
        pay_batch_candidate_page.paye_state AS candidate_paye_state,
        pay_batch_candidate_page.gross_preview AS candidate_gross_preview,
        pay_batch_candidate_page.net_bank_amount AS candidate_net_bank_amount,
        pay_batch_candidate_page.awaiting_net_amount AS candidate_awaiting_net_amount,
        pay_batch_candidate_page.settlement_status AS candidate_settlement_status,
        pay_batch_item_page.item_type,
        pay_batch_item_page.timesheet_id,
        pay_batch_item_page.segment_key,
        pay_batch_item_page.source_ref,
        pay_batch_item_page.description,
        pay_batch_item_page.amount_ex_vat,
        pay_batch_item_page.amount_vat,
        pay_batch_item_page.amount_inc_vat,
        pay_batch_item_page.frozen_target_amount_ex_vat,
        pay_batch_item_page.frozen_target_amount_vat,
        pay_batch_item_page.frozen_target_amount_inc_vat,
        pay_batch_item_page.pay_channel,
        pay_batch_item_page.umbrella_id,
        pay_batch_item_page.bank_reference,
        pay_batch_item_page.pay_bank_transfer_id,
        pay_batch_item_page.repayment_week_start,
        pay_batch_item_page.is_voided,
        pay_batch_item_page.is_mismatch,
        pay_batch_item_page.finance_case_id,
        pay_batch_item_page.finance_component_id,
        pay_batch_item_page.frozen_component_key_type,
        pay_batch_item_page.frozen_component_key_value,
        pay_batch_item_page.frozen_component_classification,
        pay_batch_item_page.frozen_source_basis_json,
        pay_batch_item_page.frozen_component_snapshot_json,
        pay_batch_item_page.frozen_source_pay_method,
        pay_batch_item_page.frozen_target_pay_method,
        pay_batch_item_page.frozen_resolution_mode,
        pay_batch_item_page.frozen_resolution_payload_json,
        pay_batch_item_page.frozen_resolution_result_json,
        pay_batch_item_page.operation_source_key,
        pay_batch_item_page.created_at,
        pay_batch_item_page.updated_at,
        breakdown_display.first_breakdown_id,
        breakdown_display.line_kind,
        breakdown_display.bucket_code,
        breakdown_display.breakdown_unit_name,
        breakdown_display.breakdown_units,
        breakdown_display.breakdown_rate,
        breakdown_display.breakdown_amount_ex_vat,
        breakdown_display.breakdowns_json,
        display_context.week_ending_date,
        display_context.client_name,
        display_context.role,
        display_context.worked_date,
        display_context.source_rate,
        display_context.source_charge_rate,
        display_context.additional_code,
        display_line.unit_name,
        CASE
          WHEN display_line.unit_name IS NOT NULL
           AND display_context.role IS NOT NULL
           AND UPPER(display_line.unit_name) <> UPPER(display_context.role) THEN display_line.unit_name || ' / ' || display_context.role
          ELSE COALESCE(display_line.unit_name, display_context.role)
        END AS unit_label,
        breakdown_display.breakdown_units AS units,
        breakdown_display.breakdown_rate AS rate
      FROM candidate_scoped_item_ids AS candidate_scoped_item
      JOIN public.pay_batch_items AS pay_batch_item_page
        ON pay_batch_item_page.id = candidate_scoped_item.id
      JOIN public.pay_batch_candidates AS pay_batch_candidate_page
        ON pay_batch_candidate_page.id = pay_batch_item_page.pay_batch_candidate_id
      LEFT JOIN LATERAL (
        SELECT
          (ARRAY_AGG(breakdown_page_inner.id ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_id,
          (ARRAY_AGG(breakdown_page_inner.line_kind ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS line_kind,
          (ARRAY_AGG(breakdown_page_inner.bucket_code ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS bucket_code,
          (ARRAY_AGG(breakdown_page_inner.unit_name ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_unit_name,
          (ARRAY_AGG(breakdown_page_inner.units ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_units,
          (ARRAY_AGG(breakdown_page_inner.rate ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_rate,
          (ARRAY_AGG(breakdown_page_inner.amount_ex_vat ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS breakdown_amount_ex_vat,
          (ARRAY_AGG(breakdown_page_inner.meta_json ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC))[1] AS first_breakdown_meta_json,
          COALESCE(
            jsonb_agg(
              jsonb_strip_nulls(jsonb_build_object(
                'id', breakdown_page_inner.id::text,
                'line_kind', breakdown_page_inner.line_kind,
                'bucket_code', breakdown_page_inner.bucket_code,
                'unit_name', breakdown_page_inner.unit_name,
                'units', breakdown_page_inner.units,
                'rate', breakdown_page_inner.rate,
                'amount_ex_vat', breakdown_page_inner.amount_ex_vat,
                'amount_vat', breakdown_page_inner.amount_vat,
                'amount_inc_vat', breakdown_page_inner.amount_inc_vat,
                'meta_json', COALESCE(breakdown_page_inner.meta_json, '{}'::jsonb),
                'operation_source_key', breakdown_page_inner.operation_source_key
              ))
              ORDER BY breakdown_page_inner.created_at_utc ASC, breakdown_page_inner.id ASC
            ),
            '[]'::jsonb
          ) AS breakdowns_json
        FROM public.pay_batch_item_breakdowns AS breakdown_page_inner
        WHERE breakdown_page_inner.pay_batch_item_id = pay_batch_item_page.id
      ) AS breakdown_display ON true
      LEFT JOIN LATERAL (
        SELECT
          snapshot_page_inner.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS snapshot_page_inner
        WHERE snapshot_page_inner.pay_batch_id = pay_batch_candidate_page.pay_batch_id
          AND snapshot_page_inner.timesheet_id = pay_batch_item_page.timesheet_id
          AND snapshot_page_inner.candidate_id = pay_batch_candidate_page.candidate_id
          AND (
            snapshot_page_inner.pay_channel IS NOT DISTINCT FROM pay_batch_item_page.pay_channel
            OR snapshot_page_inner.pay_channel IS NULL
            OR pay_batch_item_page.pay_channel IS NULL
          )
        ORDER BY snapshot_page_inner.created_at_utc DESC, snapshot_page_inner.id DESC
        LIMIT 1
      ) AS snapshot_page ON true
      CROSS JOIN LATERAL (
        SELECT
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json->>'week_ending_date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,week_ending_date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'week_ending_date',
            pay_batch_item_page.frozen_resolution_result_json->>'week_ending_date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,week_ending_date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,week_ending_date}',
            snapshot_page.target_snapshot_json->>'week_ending_date',
            pay_batch_item_page.payout_instruction_snapshot_json->>'week_ending_bucket'
          )), '') AS week_ending_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json->>'client_name',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,client_name}',
            pay_batch_item_page.frozen_resolution_payload_json->>'client_name',
            pay_batch_item_page.frozen_resolution_result_json->>'client_name',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,client_name}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,client_name}',
            snapshot_page.target_snapshot_json->>'client_name'
          )), '') AS client_name,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'role',
            pay_batch_item_page.frozen_source_basis_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json->>'role',
            pay_batch_item_page.frozen_component_snapshot_json->>'job_title',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,role}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,job_title}',
            pay_batch_item_page.frozen_resolution_payload_json->>'role',
            pay_batch_item_page.frozen_resolution_payload_json->>'job_title',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,job_title}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,role}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,job_title}',
            snapshot_page.target_snapshot_json->>'role',
            snapshot_page.target_snapshot_json->>'job_title'
          )), '') AS role,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json->>'date',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,date}',
            pay_batch_item_page.frozen_resolution_payload_json->>'date',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,date}',
            breakdown_display.first_breakdown_meta_json#>>'{resolution_payload_json,date}',
            snapshot_page.target_snapshot_json->>'date',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) = 'TS_DAY'
               AND NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS worked_date,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_rate',
            pay_batch_item_page.frozen_source_basis_json->>'pay_rate',
            pay_batch_item_page.frozen_source_basis_json->>'rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'pay_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,pay_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,pay_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,pay_rate}'
          )), '') AS source_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'source_charge_rate',
            pay_batch_item_page.frozen_source_basis_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'source_charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json->>'charge_rate',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,source_charge_rate}',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,charge_rate}',
            pay_batch_item_page.frozen_resolution_payload_json->>'source_charge_rate',
            pay_batch_item_page.frozen_resolution_result_json->>'source_charge_rate',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,source_charge_rate}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,charge_rate}'
          )), '') AS source_charge_rate,
          NULLIF(BTRIM(COALESCE(
            pay_batch_item_page.frozen_source_basis_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json->>'additional_code',
            pay_batch_item_page.frozen_component_snapshot_json#>>'{source_basis_json,additional_code}',
            pay_batch_item_page.frozen_resolution_payload_json->>'additional_code',
            breakdown_display.first_breakdown_meta_json#>>'{source_basis_json,additional_code}',
            breakdown_display.first_breakdown_meta_json#>>'{case_component_json,additional_code}',
            CASE
              WHEN UPPER(NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_type, '')), '')) IN ('ADDITIONAL_CODE', 'EXPENSE_CODE')
              THEN NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_key_value, '')), '')
              ELSE NULL
            END
          )), '') AS additional_code
      ) AS display_context
      CROSS JOIN LATERAL (
        SELECT
          COALESCE(
            NULLIF(BTRIM(COALESCE(breakdown_display.breakdown_unit_name, '')), ''),
            display_context.additional_code,
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_source_basis_json->>'unit_name', pay_batch_item_page.frozen_source_basis_json->>'unit', '')), ''),
            NULLIF(BTRIM(COALESCE(pay_batch_item_page.frozen_component_snapshot_json->>'unit_name', pay_batch_item_page.frozen_component_snapshot_json->>'unit', '')), ''),
            display_context.role
          ) AS unit_name
      ) AS display_line
      WHERE pay_batch_candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR pay_batch_item_page.id > v_cursor_id)
      ORDER BY pay_batch_item_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_item_id', page_rows.id::text,
            'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
            'candidate_id', page_rows.candidate_id::text,
            'candidate_tms_ref', page_rows.candidate_tms_ref,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_paye_state', page_rows.candidate_paye_state,
            'candidate_gross_preview', page_rows.candidate_gross_preview,
            'candidate_net_bank_amount', page_rows.candidate_net_bank_amount,
            'candidate_awaiting_net_amount', page_rows.candidate_awaiting_net_amount,
            'candidate_settlement_status', page_rows.candidate_settlement_status,
            'item_type', page_rows.item_type,
            'timesheet_id', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL::text ELSE page_rows.timesheet_id::text END,
            'segment_key', page_rows.segment_key,
            'source_ref', page_rows.source_ref,
            'description', page_rows.description,
            'amount_ex_vat', page_rows.amount_ex_vat,
            'amount_vat', page_rows.amount_vat,
            'amount_inc_vat', page_rows.amount_inc_vat,
            'frozen_target_amount_ex_vat', page_rows.frozen_target_amount_ex_vat,
            'frozen_target_amount_vat', page_rows.frozen_target_amount_vat,
            'frozen_target_amount_inc_vat', page_rows.frozen_target_amount_inc_vat
          )
          || jsonb_build_object(
            'pay_channel', page_rows.pay_channel,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'bank_reference', page_rows.bank_reference,
            'pay_bank_transfer_id', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL::text ELSE page_rows.pay_bank_transfer_id::text END,
            'repayment_week_start', CASE WHEN page_rows.repayment_week_start IS NULL THEN NULL::text ELSE page_rows.repayment_week_start::text END,
            'is_voided', page_rows.is_voided,
            'is_mismatch', page_rows.is_mismatch,
            'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
            'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
            'frozen_component_key_type', page_rows.frozen_component_key_type,
            'frozen_component_key_value', page_rows.frozen_component_key_value,
            'operation_source_key', page_rows.operation_source_key,
            'created_at', page_rows.created_at,
            'updated_at', page_rows.updated_at
          )
          || jsonb_build_object(
            'week_ending_date', page_rows.week_ending_date,
            'client_name', page_rows.client_name,
            'role', page_rows.role,
            'worked_date', page_rows.worked_date,
            'unit_name', page_rows.unit_name,
            'unit_label', page_rows.unit_label,
            'units', page_rows.units,
            'rate', page_rows.rate,
            'source_rate', page_rows.source_rate,
            'source_charge_rate', page_rows.source_charge_rate,
            'additional_code', page_rows.additional_code,
            'line_kind', page_rows.line_kind,
            'bucket_code', page_rows.bucket_code,
            'breakdown_unit_name', page_rows.breakdown_unit_name,
            'breakdown_amount_ex_vat', page_rows.breakdown_amount_ex_vat,
            'breakdowns', page_rows.breakdowns_json
          )
          || jsonb_build_object(
            'frozen_component_classification', page_rows.frozen_component_classification,
            'frozen_source_basis_json', COALESCE(page_rows.frozen_source_basis_json, '{}'::jsonb),
            'frozen_component_snapshot_json', COALESCE(page_rows.frozen_component_snapshot_json, '{}'::jsonb),
            'frozen_source_pay_method', page_rows.frozen_source_pay_method,
            'frozen_target_pay_method', page_rows.frozen_target_pay_method,
            'frozen_resolution_mode', page_rows.frozen_resolution_mode,
            'frozen_resolution_payload_json', COALESCE(page_rows.frozen_resolution_payload_json, '{}'::jsonb),
            'frozen_resolution_result_json', COALESCE(page_rows.frozen_resolution_result_json, '{}'::jsonb),
            'display_context_json', jsonb_strip_nulls(jsonb_build_object(
              'week_ending_date', page_rows.week_ending_date,
              'client_name', page_rows.client_name,
              'role', page_rows.role,
              'worked_date', page_rows.worked_date,
              'source_rate', page_rows.source_rate,
              'source_charge_rate', page_rows.source_charge_rate,
              'additional_code', page_rows.additional_code
            ))
          )
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'item_breakdowns' THEN
    WITH page_rows AS (
      SELECT
        breakdown_page.id,
        breakdown_page.pay_batch_item_id,
        item_page.pay_batch_candidate_id,
        candidate_page.candidate_id,
        breakdown_page.line_kind,
        breakdown_page.bucket_code,
        breakdown_page.unit_name,
        breakdown_page.units,
        breakdown_page.rate,
        breakdown_page.amount_ex_vat,
        breakdown_page.amount_vat,
        breakdown_page.amount_inc_vat,
        breakdown_page.meta_json,
        breakdown_page.operation_source_key,
        breakdown_page.created_at_utc
      FROM public.pay_batch_item_breakdowns AS breakdown_page
      JOIN public.pay_batch_items AS item_page
        ON item_page.id = breakdown_page.pay_batch_item_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR breakdown_page.id > v_cursor_id)
      ORDER BY breakdown_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'id', page_rows.id::text,
          'pay_batch_item_id', page_rows.pay_batch_item_id::text,
          'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
          'candidate_id', page_rows.candidate_id::text,
          'line_kind', page_rows.line_kind,
          'bucket_code', page_rows.bucket_code,
          'unit_name', page_rows.unit_name,
          'units', page_rows.units,
          'rate', page_rows.rate,
          'amount_ex_vat', page_rows.amount_ex_vat,
          'amount_vat', page_rows.amount_vat,
          'amount_inc_vat', page_rows.amount_inc_vat,
          'meta_json', COALESCE(page_rows.meta_json, '{}'::jsonb),
          'operation_source_key', page_rows.operation_source_key,
          'created_at_utc', page_rows.created_at_utc
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section IN ('transfers', 'current_payment_status') THEN
    WITH page_rows AS (
      SELECT
        transfer_page.id,
        transfer_page.pay_batch_id,
        transfer_page.candidate_id,
        transfer_page.umbrella_id,
        transfer_page.pay_channel,
        transfer_page.amount,
        transfer_page.currency,
        transfer_page.status,
        transfer_page.payment_reference,
        transfer_page.payee_name,
        transfer_page.sort_code,
        transfer_page.account_number,
        transfer_page.account_type,
        transfer_page.created_at_utc,
        transfer_page.completed_at_utc,
        transfer_page.failed_reason,
        transfer_page.rail_provider,
        transfer_page.rail_env,
        transfer_page.request_id,
        transfer_page.rail_tx_id,
        transfer_page.rail_state,
        transfer_page.rail_meta_json,
        transfer_page.bank_details_hash_snapshot,
        transfer_page.payee_entity_kind,
        transfer_page.payee_entity_id,
        transfer_page.transfer_group_key,
        transfer_page.grouping_mode_used,
        transfer_page.week_ending_bucket,
        candidate_page.id AS pay_batch_candidate_id,
        candidate_page.candidate_display_name,
        latest_event_page.provider_key AS latest_event_provider_key,
        latest_event_page.provider_transaction_id AS latest_provider_transaction_id,
        latest_event_page.provider_request_id AS latest_provider_request_id,
        latest_event_page.provider_event_key AS latest_provider_event_key,
        latest_event_page.provider_event_id AS latest_provider_event_id,
        latest_event_page.provider_reference AS latest_provider_reference,
        latest_event_page.normalised_state AS latest_event_normalised_state,
        latest_event_page.provider_state AS latest_event_provider_state,
        latest_event_page.provider_failure_reason_code AS latest_provider_failure_reason_code,
        latest_event_page.provider_failure_reason_group AS latest_provider_failure_reason_group,
        latest_event_page.event_time_utc AS latest_event_time_utc,
        latest_event_page.received_at_utc AS latest_event_received_at_utc,
        latest_event_page.correction_disposition AS latest_event_correction_disposition,
        latest_event_page.movement_classification AS latest_event_movement_classification
      FROM public.pay_bank_transfers AS transfer_page
      LEFT JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.pay_batch_id = transfer_page.pay_batch_id
       AND candidate_page.candidate_id = transfer_page.candidate_id
      LEFT JOIN LATERAL (
        SELECT
          event_page.provider_key,
          event_page.provider_transaction_id,
          event_page.provider_request_id,
          event_page.provider_event_key,
          event_page.provider_event_id,
          event_page.provider_reference,
          event_page.normalised_state,
          event_page.provider_state,
          event_page.provider_failure_reason_code,
          event_page.provider_failure_reason_group,
          event_page.event_time_utc,
          event_page.received_at_utc,
          event_page.correction_disposition,
          event_page.movement_classification
        FROM public.pay_bank_transfer_events AS event_page
        WHERE event_page.pay_batch_id = transfer_page.pay_batch_id
          AND event_page.pay_bank_transfer_id = transfer_page.id
        ORDER BY COALESCE(event_page.event_time_utc, event_page.received_at_utc, event_page.created_at_utc) DESC NULLS LAST,
                 event_page.id DESC
        LIMIT 1
      ) AS latest_event_page ON true
      WHERE transfer_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR transfer_page.id > v_cursor_id)
      ORDER BY transfer_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'id', page_rows.id::text,
            'pay_batch_id', page_rows.pay_batch_id::text,
            'candidate_id', CASE WHEN page_rows.candidate_id IS NULL THEN NULL::text ELSE page_rows.candidate_id::text END,
            'pay_batch_candidate_id', CASE WHEN page_rows.pay_batch_candidate_id IS NULL THEN NULL::text ELSE page_rows.pay_batch_candidate_id::text END,
            'candidate_display_name', page_rows.candidate_display_name,
            'candidate_name', page_rows.candidate_display_name,
            'umbrella_id', CASE WHEN page_rows.umbrella_id IS NULL THEN NULL::text ELSE page_rows.umbrella_id::text END,
            'pay_channel', page_rows.pay_channel,
            'amount', page_rows.amount,
            'currency', page_rows.currency,
            'status', page_rows.status,
            'payment_reference', page_rows.payment_reference,
            'payee_name', page_rows.payee_name,
            'sort_code', page_rows.sort_code,
            'account_number', page_rows.account_number,
            'account_type', page_rows.account_type
          )
          || jsonb_build_object(
            'created_at_utc', page_rows.created_at_utc,
            'completed_at_utc', page_rows.completed_at_utc,
            'failed_reason', page_rows.failed_reason,
            'rail_provider', page_rows.rail_provider,
            'rail_env', page_rows.rail_env,
            'request_id', page_rows.request_id,
            'rail_tx_id', page_rows.rail_tx_id,
            'rail_state', page_rows.rail_state,
            'rail_meta_json', COALESCE(page_rows.rail_meta_json, '{}'::jsonb),
            'bank_details_hash_snapshot', page_rows.bank_details_hash_snapshot,
            'payee_entity_kind', page_rows.payee_entity_kind,
            'payee_entity_id', CASE WHEN page_rows.payee_entity_id IS NULL THEN NULL::text ELSE page_rows.payee_entity_id::text END,
            'transfer_group_key', page_rows.transfer_group_key,
            'grouping_mode_used', page_rows.grouping_mode_used,
            'week_ending_bucket', CASE WHEN page_rows.week_ending_bucket IS NULL THEN NULL::text ELSE page_rows.week_ending_bucket::text END
          )
          || CASE
            WHEN v_section = 'current_payment_status' THEN jsonb_build_object(
              'payment_lifecycle_state', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state',
              'payment_lifecycle_label', transfer_diagnostic.diagnostic_json->>'payment_lifecycle_label',
              'recommended_action', transfer_diagnostic.diagnostic_json->>'recommended_action',
              'row_cancel_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
              'can_no_money_unwind', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
              'can_recover_overpayment', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
              'provider_outcome_unknown_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
              'provider_webhook_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
              'terminal_no_money_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
              'pending_provider_evidence_json', COALESCE(transfer_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
              'status_update_signature', NULLIF(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'status_update_signature', '')), ''),
              'provider_submission_status', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json->>'provider_submission_status',
                page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}',
                page_rows.rail_meta_json #>> '{providerSubmitDiagnostic,providerSubmissionStatus}',
                page_rows.rail_meta_json->>'provider_submission_status',
                ''
              )), ''),
              'money_movement_cash_state', NULLIF(BTRIM(COALESCE(
                transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}',
                transfer_diagnostic.diagnostic_json->>'cash_state',
                page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}',
                ''
              )), ''),
              'is_final_money_moved', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','SETTLED','PAID','COMMITTED','EXECUTED','BANK_CONFIRMED','MANUAL_CONFIRM')
              ),
              'safe_retry_available', LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'safe_retry_available', page_rows.rail_meta_json #>> '{provider_submit_diagnostic,safe_retry_available}', 'false'))) IN ('true','1','yes','y','on'),
              'payment_status_raw', page_rows.status,
              'payment_status_bucket', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                ) THEN 'SENT_CONFIRMED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                  THEN 'FAILED_RETURNED'
                WHEN UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'payment_lifecycle_state', ''))) IN ('PROVIDER_OUTCOME_UNKNOWN','CHECK_REQUIRED','UNKNOWN')
                  OR UPPER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'recommended_action', ''))) = 'CHECK_PROVIDER_STATUS'
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('UNKNOWN','UNCERTAIN','REVIEW_REQUIRED')
                  THEN 'CHECK_REQUIRED'
                WHEN UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','WAITING_BANK_CONFIRM')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('PENDING','SUBMITTED','PROCESSING','IN_FLIGHT','ACCEPTED','PENDING_SETTLEMENT','PENDING_CONFIRMATION')
                  OR NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), '') IS NOT NULL
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', page_rows.rail_meta_json->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED','ACCEPTED','SUBMITTED','PROVIDER_SUBMITTED')
                  THEN 'PENDING_SUBMITTED'
                ELSE 'NOT_SENT'
              END,
              'payment_status_label', public._pay_bank_transfer_status_display_label(
                page_rows.status,
                page_rows.rail_state,
                COALESCE(
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json #>> '{money_movement_classification,cash_state}'), ''),
                  NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'cash_state'), ''),
                  NULLIF(BTRIM(page_rows.rail_meta_json #>> '{money_movement_classification,cash_state}'), ''),
                  CASE
                    WHEN LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on') THEN 'FINAL_PAID'
                    ELSE NULL::text
                  END
                )
              ),
              'payment_terminal_success', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
              ),
              'payment_terminal_failed', (
                UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal', (
                LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM','FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                OR (
                  page_rows.completed_at_utc IS NOT NULL
                  AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                )
                OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
              ),
              'payment_terminal_timestamp', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'payment_terminal_at_utc', CASE
                WHEN (
                  LOWER(BTRIM(COALESCE(transfer_diagnostic.diagnostic_json->>'is_final_money_moved', transfer_diagnostic.diagnostic_json->>'final_money_moved', 'false'))) IN ('true','1','yes','y','on')
                  OR UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('COMPLETED','COMPLETE','SETTLED','PAID','COMMITTED','EXECUTED','SUCCESS','SUCCEEDED','BANK_CONFIRMED','MANUAL_CONFIRM')
                  OR (
                    page_rows.completed_at_utc IS NOT NULL
                    AND UPPER(BTRIM(COALESCE(page_rows.status, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                    AND UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) NOT IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  )
                ) THEN COALESCE(page_rows.completed_at_utc, page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc)::text
                WHEN (
                  UPPER(BTRIM(COALESCE(page_rows.status, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
                  OR UPPER(BTRIM(COALESCE(page_rows.rail_state, ''))) IN ('FAILED','REJECTED','DECLINED','RETURNED','REVERTED','CANCELLED','CANCELED')
                  OR (jsonb_typeof(COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb)) = 'object' AND COALESCE(transfer_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb) <> '{}'::jsonb)
                ) THEN COALESCE(page_rows.latest_event_time_utc, page_rows.latest_event_received_at_utc, page_rows.completed_at_utc)::text
                ELSE NULL::text
              END,
              'provider', COALESCE(page_rows.rail_provider, page_rows.latest_event_provider_key),
              'rail', page_rows.rail_env,
              'rail_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.rail_tx_id, '')), ''),
              'provider_transaction_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_transaction_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', page_rows.rail_meta_json #>> '{provider_transaction_id}', '')), ''),
              'provider_request_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_request_id, page_rows.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', page_rows.request_id, '')), ''),
              'provider_event_id', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_event_id, page_rows.latest_provider_event_key, '')), ''),
              'provider_reference', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_reference, page_rows.payment_reference, '')), ''),
              'provider_failure_reason_code', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_code, '')), ''),
              'provider_failure_reason_group', NULLIF(BTRIM(COALESCE(page_rows.latest_provider_failure_reason_group, '')), ''),
              'action_review_status', COALESCE(NULLIF(BTRIM(transfer_diagnostic.diagnostic_json->>'recommended_action'), ''), NULLIF(BTRIM(page_rows.latest_event_correction_disposition), ''))
            )
            ELSE '{}'::jsonb
          END
        )
        ORDER BY page_rows.id ASC
      ), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows
    LEFT JOIN LATERAL (
      SELECT CASE
        WHEN v_section = 'current_payment_status' THEN public.pay_payment_cancelability_diagnostic(
          p_pay_batch_id,
          jsonb_build_object(
            'scope_type', 'TRANSFER',
            'pay_bank_transfer_ids', jsonb_build_array(page_rows.id::text)
          ),
          p_actor_user_id,
          'CURRENT_PAYMENT_STATUS'
        )
        ELSE '{}'::jsonb
      END AS diagnostic_json
    ) AS transfer_diagnostic ON true;

  ELSIF v_section = 'finance_case_groups' THEN
    WITH group_keys AS (
      SELECT COALESCE(item_page.finance_case_id, item_page.finance_component_id) AS group_id
      FROM public.pay_batch_items AS item_page
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (item_page.finance_case_id IS NOT NULL OR item_page.finance_component_id IS NOT NULL)
      GROUP BY COALESCE(item_page.finance_case_id, item_page.finance_component_id)
    ),
    page_rows AS (
      SELECT
        group_keys.group_id,
        (ARRAY_AGG(item_page.finance_case_id ORDER BY item_page.finance_case_id::text) FILTER (WHERE item_page.finance_case_id IS NOT NULL))[1] AS finance_case_id,
        (ARRAY_AGG(item_page.finance_component_id ORDER BY item_page.finance_component_id::text) FILTER (WHERE item_page.finance_component_id IS NOT NULL))[1] AS finance_component_id,
        COUNT(*)::integer AS item_count,
        ROUND(COALESCE(SUM(COALESCE(item_page.amount_ex_vat, 0)), 0), 2)::numeric AS total_amount_ex_vat,
        COALESCE(jsonb_agg(DISTINCT item_page.item_type) FILTER (WHERE item_page.item_type IS NOT NULL), '[]'::jsonb) AS item_types,
        COALESCE(jsonb_agg(DISTINCT candidate_page.candidate_id::text) FILTER (WHERE candidate_page.candidate_id IS NOT NULL), '[]'::jsonb) AS candidate_ids
      FROM group_keys
      JOIN public.pay_batch_items AS item_page
        ON COALESCE(item_page.finance_case_id, item_page.finance_component_id) = group_keys.group_id
      JOIN public.pay_batch_candidates AS candidate_page
        ON candidate_page.id = item_page.pay_batch_candidate_id
      WHERE candidate_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR group_keys.group_id > v_cursor_id)
      GROUP BY group_keys.group_id
      ORDER BY group_keys.group_id ASC
      LIMIT (v_limit + 1)
    )
    SELECT
      COALESCE(jsonb_agg(jsonb_build_object(
        'group_id', page_rows.group_id::text,
        'finance_case_id', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL::text ELSE page_rows.finance_case_id::text END,
        'finance_component_id', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL::text ELSE page_rows.finance_component_id::text END,
        'item_count', page_rows.item_count,
        'total_amount_ex_vat', page_rows.total_amount_ex_vat,
        'item_types', page_rows.item_types,
        'candidate_ids', page_rows.candidate_ids
      ) ORDER BY page_rows.group_id ASC), '[]'::jsonb),
      COUNT(*)::integer,
      (ARRAY_AGG(page_rows.group_id::text ORDER BY page_rows.group_id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'remittances' THEN
    WITH page_rows AS (
      SELECT
        mail_page.id,
        mail_page.type,
        mail_page."to" AS mail_to,
        mail_page.cc,
        mail_page.bcc,
        mail_page.subject,
        mail_page.status::text AS status,
        mail_page.provider_status,
        mail_page.recipient_kind,
        mail_page.recipient_id,
        mail_page.context_kind,
        mail_page.context_id,
        mail_page.reference,
        mail_page.created_at_utc,
        mail_page.sent_at,
        mail_page.failed_at,
        mail_page.last_error,
        mail_page.deterministic_outbox_key
      FROM public.mail_outbox AS mail_page
      WHERE (
           mail_page.payment_scope_json->>'pay_batch_id' = p_pay_batch_id::text
        OR (LOWER(COALESCE(mail_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND mail_page.context_id = p_pay_batch_id)
        OR mail_page.reference = p_pay_batch_id::text
        OR mail_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR mail_page.id > v_cursor_id)
      ORDER BY mail_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'communications' THEN
    WITH page_rows AS (
      SELECT
        comms_page.id,
        comms_page.channel,
        comms_page.status,
        comms_page.to_address,
        comms_page.provider_key,
        comms_page.provider_message_id,
        comms_page.recipient_kind,
        comms_page.recipient_id,
        comms_page.context_kind,
        comms_page.context_id,
        comms_page.created_at_utc,
        comms_page.sent_at,
        comms_page.delivered_at,
        comms_page.read_at,
        comms_page.failed_at,
        comms_page.last_error,
        comms_page.deterministic_outbox_key
      FROM public.comms_outbox AS comms_page
      WHERE (
           (LOWER(COALESCE(comms_page.context_kind, '')) IN ('pay_batch', 'pay_batches') AND comms_page.context_id = p_pay_batch_id)
        OR comms_page.provider_payload_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.provider_response_json->>'pay_batch_id' = p_pay_batch_id::text
        OR comms_page.deterministic_outbox_key LIKE ('remittance:batch:' || p_pay_batch_id::text || ':%')
      )
        AND (v_cursor_id IS NULL OR comms_page.id > v_cursor_id)
      ORDER BY comms_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'auth_history' THEN
    WITH page_rows AS (
      SELECT
        auth_page.id,
        auth_page.pay_batch_id,
        auth_page.requested_by_user_id,
        auth_page.required_quantity,
        auth_page.schedule_kind,
        auth_page.scheduled_at_utc,
        auth_page.funding_account_ref,
        auth_page.state,
        auth_page.golden_key_used,
        auth_page.golden_key_user_id,
        auth_page.created_at_utc,
        auth_page.finalised_at_utc,
        auth_page.finalised_by_user_id,
        auth_page.execution_intent_json
      FROM public.pay_batch_auth_requests AS auth_page
      WHERE auth_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR auth_page.id > v_cursor_id)
      ORDER BY auth_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;

  ELSIF v_section = 'events' THEN
    WITH page_rows AS (
      SELECT
        event_page.id,
        event_page.pay_batch_id,
        event_page.pay_bank_transfer_id,
        event_page.candidate_id,
        event_page.umbrella_id,
        event_page.provider_key,
        event_page.provider_event_id,
        event_page.provider_reference,
        event_page.provider_state,
        event_page.normalised_state,
        event_page.event_source,
        event_page.event_time_utc,
        event_page.received_at_utc,
        event_page.amount,
        event_page.currency,
        event_page.mapping_status,
        event_page.movement_classification,
        event_page.correction_disposition,
        event_page.mapping_method,
        event_page.created_at_utc
      FROM public.pay_bank_transfer_events AS event_page
      WHERE event_page.pay_batch_id = p_pay_batch_id
        AND (v_cursor_id IS NULL OR event_page.id > v_cursor_id)
      ORDER BY event_page.id ASC
      LIMIT (v_limit + 1)
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(page_rows) ORDER BY page_rows.id ASC), '[]'::jsonb),
           COUNT(*)::integer,
           (ARRAY_AGG(page_rows.id::text ORDER BY page_rows.id DESC))[1]
    INTO v_items, v_raw_count, v_last_cursor_text
    FROM page_rows;
  END IF;

  v_raw_count := COALESCE(v_raw_count, 0);

  IF v_raw_count > v_limit THEN
    v_next_cursor := jsonb_build_object(
      'last_id',
      COALESCE(
        v_items -> (v_limit - 1) ->> 'id',
        v_items -> (v_limit - 1) ->> 'group_id',
        v_last_cursor_text
      )
    );

    SELECT COALESCE(jsonb_agg(trimmed_items.value ORDER BY trimmed_items.ordinality), '[]'::jsonb)
    INTO v_items
    FROM jsonb_array_elements(COALESCE(v_items, '[]'::jsonb)) WITH ORDINALITY AS trimmed_items(value, ordinality)
    WHERE trimmed_items.ordinality <= v_limit;

    v_returned_count := v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
    v_returned_count := v_raw_count;
  END IF;

  v_section_page_signature := 'pay_batch_section_page:v2:' || MD5(
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'section', v_section,
      'purpose', v_purpose,
      'items', COALESCE(v_items, '[]'::jsonb),
      'next_cursor', v_next_cursor,
      'live_signal_version', COALESCE(v_live_signal_version, 0),
      'payment_status_version', COALESCE(v_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_correction_progress_version, 0),
      'overview_version', COALESCE(v_overview_version, 0),
      'candidate_scope', CASE
        WHEN v_candidate_scope_enabled THEN jsonb_build_object(
          'scope_type', 'PAY_BATCH_CANDIDATE',
          'pay_batch_candidate_id', v_candidate_scope_pay_batch_candidate_id::text,
          'candidate_id', v_candidate_scope_candidate_id::text
        )
        ELSE NULL::jsonb
      END
    )::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'section', v_section,
    'purpose', v_purpose,
    'items', COALESCE(v_items, '[]'::jsonb),
    'next_cursor', v_next_cursor,
    'returned_count', COALESCE(v_returned_count, 0),
    'known_total_count', v_known_total_count,
    'pay_batch_id', p_pay_batch_id::text,
    'server_time_utc', v_server_time_utc::text,
    'section_page_signature', v_section_page_signature,
    'live_signal_version', COALESCE(v_live_signal_version, 0),
    'payment_status_version', COALESCE(v_payment_status_version, 0),
    'correction_progress_version', COALESCE(v_correction_progress_version, 0),
    'alert_version', COALESCE(v_alert_version, 0),
    'overview_version', COALESCE(v_overview_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'known_live_signal_version', v_known_live_signal_version,
    'changed_since_version', COALESCE(v_changed_since_version, false),
    'batch_status', v_batch.status,
    'execution_commit_state', v_batch.execution_commit_state,
    'freshness', v_freshness_summary,
    'limit', v_limit,
    'scope_type', CASE WHEN v_candidate_scope_enabled THEN 'PAY_BATCH_CANDIDATE' ELSE NULL::text END,
    'pay_batch_candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_pay_batch_candidate_id::text ELSE NULL::text END,
    'candidate_id', CASE WHEN v_candidate_scope_enabled THEN v_candidate_scope_candidate_id::text ELSE NULL::text END
  );
END;
$function$
;

-- [REPLACES] public.pay_batch_validate_freshness(p_pay_batch_id uuid, p_actor_user_id uuid, p_allow_large_full_scan boolean)  winner piece A24
CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness(p_pay_batch_id uuid, p_actor_user_id uuid, p_allow_large_full_scan boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base_result jsonb;
  v_base_diff jsonb := '[]'::jsonb;
  v_filtered_diff jsonb := '[]'::jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_fresh_chain_components jsonb := '[]'::jsonb;
  v_original_key_diff_count integer := 0;
  v_suppressed_key_diff_count integer := 0;
  v_remaining_key_diff_count integer := 0;
  v_source_head_drift jsonb := '[]'::jsonb;  -- A24
BEGIN
  v_base_result := public._pay_batch_validate_freshness_base_v1(
    p_pay_batch_id,
    p_actor_user_id,
    p_allow_large_full_scan
  );

  v_base_diff := COALESCE(v_base_result->'diff', '[]'::jsonb);
  v_reasons := COALESCE(v_base_result->'stale_reasons', '[]'::jsonb);

  /*
   * A correction-chain item freezes its complete residual evidence when the
   * draft is created. The base freshness validator intentionally uses the
   * ordinary timesheet entitlement comparison for all economic rows. That
   * ordinary comparison cannot distinguish a correction-chain residual from
   * its root timesheet and therefore sees this batch's own reservation as a
   * change.
   *
   * Reconstruct the pre-current-batch correction-chain residual through the
   * bounded Policy X helper. Suppress only the exact base diff when every
   * frozen component still equals the reconstructed component. Any helper
   * error or real component change fails closed and leaves the base stale
   * result untouched.
   */
  WITH correction_items AS (
    SELECT DISTINCT ON (
      correction_item.source_family_key,
      correction_item.candidate_id,
      correction_item.target_pay_method
    )
      correction_item.pay_batch_item_id,
      correction_item.root_timesheet_id,
      correction_item.candidate_id,
      correction_item.source_family_key,
      correction_item.target_pay_method,
      correction_item.frozen_residual
    FROM (
      SELECT
        pay_batch_item.id AS pay_batch_item_id,
        COALESCE(
          NULLIF(
            COALESCE(
              pay_batch_item.frozen_source_basis_json
                #>> '{correction_chain_residual,root_timesheet_id}',
              pay_batch_item.frozen_component_snapshot_json
                #>> '{correction_chain_residual,root_timesheet_id}'
            ),
            ''
          )::uuid,
          CASE
            WHEN COALESCE(
              pay_batch_item.frozen_source_basis_json->>'source_family_key',
              pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
              ''
            ) ~ '^correction-chain:[0-9a-fA-F-]{36}$'
              THEN replace(
                COALESCE(
                  pay_batch_item.frozen_source_basis_json->>'source_family_key',
                  pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
                ),
                'correction-chain:',
                ''
              )::uuid
            ELSE pay_batch_item.timesheet_id
          END
        ) AS root_timesheet_id,
        pay_batch_candidate.candidate_id,
        NULLIF(BTRIM(COALESCE(
          pay_batch_item.frozen_source_basis_json->>'source_family_key',
          pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
          ''
        )), '') AS source_family_key,
        UPPER(NULLIF(BTRIM(COALESCE(
          pay_batch_item.frozen_target_pay_method,
          pay_batch_item.pay_channel,
          pay_batch.batch_kind_fixed,
          ''
        )), '')) AS target_pay_method,
        COALESCE(
          pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
          pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
        ) AS frozen_residual
      FROM public.pay_batch_items AS pay_batch_item
      JOIN public.pay_batch_candidates AS pay_batch_candidate
        ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
      JOIN public.pay_batches AS pay_batch
        ON pay_batch.id = pay_batch_candidate.pay_batch_id
      WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
        AND COALESCE(pay_batch_item.is_voided, false) = false
        AND COALESCE(
          NULLIF(BTRIM(COALESCE(
            pay_batch_item.frozen_source_basis_json->>'source_family_key',
            pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
            ''
          )), ''),
          ''
        ) LIKE 'correction-chain:%'
        /*
         * Filter to the row that actually owns the frozen chain snapshot
         * before DISTINCT ON chooses one row for the family. A recovery item
         * can share the family key without carrying the snapshot; allowing it
         * into the ordering can hide the valid correction carrier entirely.
         */
        AND jsonb_typeof(
          COALESCE(
            pay_batch_item.frozen_source_basis_json->'correction_chain_residual',
            pay_batch_item.frozen_component_snapshot_json->'correction_chain_residual'
          )
        ) = 'object'
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS correction_item_exclusion
          WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
            AND correction_item_exclusion.status = 'APPLIED'
            AND correction_item_exclusion.correction_item_kind IN (
              'PRE_BANK_CANCEL',
              'NO_MONEY_UNWIND',
              'SETTLED_REVERSAL'
            )
        )
    ) AS correction_item
    WHERE correction_item.root_timesheet_id IS NOT NULL
      AND correction_item.candidate_id IS NOT NULL
      AND correction_item.target_pay_method IN ('PAYE', 'UMBRELLA')
      AND jsonb_typeof(correction_item.frozen_residual) = 'object'
    ORDER BY
      correction_item.source_family_key,
      correction_item.candidate_id,
      correction_item.target_pay_method,
      correction_item.pay_batch_item_id
  ),
  chain_results AS (
    SELECT
      correction_item.*,
      public.pay_correction_chain_residual_v1(
        correction_item.root_timesheet_id,
        correction_item.candidate_id,
        correction_item.target_pay_method,
        NULL::uuid,
        p_pay_batch_id,
        100
      ) AS live_residual
    FROM correction_items AS correction_item
  ),
  expected_components AS (
    SELECT
      chain_result.root_timesheet_id,
      chain_result.source_family_key,
      UPPER(NULLIF(BTRIM(component.component_json->>'component_key_type'), ''))
        AS key_type,
      NULLIF(BTRIM(component.component_json->>'component_key_value'), '')
        AS key_value,
      CASE
        WHEN COALESCE(
          component.component_json->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS amount_ex
    FROM chain_results AS chain_result
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(chain_result.frozen_residual->'components') = 'array'
          THEN chain_result.frozen_residual->'components'
        ELSE '[]'::jsonb
      END
    ) AS component(component_json)
  ),
  live_components AS (
    SELECT
      chain_result.root_timesheet_id,
      chain_result.source_family_key,
      UPPER(NULLIF(BTRIM(component.component_json->>'component_key_type'), ''))
        AS key_type,
      NULLIF(BTRIM(component.component_json->>'component_key_value'), '')
        AS key_value,
      CASE
        WHEN COALESCE(
          component.component_json->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS amount_ex
    FROM chain_results AS chain_result
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(chain_result.live_residual->'components') = 'array'
          THEN chain_result.live_residual->'components'
        ELSE '[]'::jsonb
      END
    ) AS component(component_json)
  ),
  chain_component_comparison AS (
    SELECT
      COALESCE(expected.root_timesheet_id, live.root_timesheet_id)
        AS root_timesheet_id,
      COALESCE(expected.source_family_key, live.source_family_key)
        AS source_family_key,
      COALESCE(expected.key_type, live.key_type) AS key_type,
      COALESCE(expected.key_value, live.key_value) AS key_value,
      expected.amount_ex AS expected_ex,
      live.amount_ex AS actual_ex,
      (
        expected.amount_ex IS NOT NULL
        AND live.amount_ex IS NOT NULL
        AND ABS(
          ROUND(expected.amount_ex, 2) - ROUND(live.amount_ex, 2)
        ) <= 0.01
      ) AS component_matches
    FROM expected_components AS expected
    FULL JOIN live_components AS live
      ON live.source_family_key = expected.source_family_key
     AND live.key_type = expected.key_type
     AND live.key_value = expected.key_value
  ),
  fresh_families AS (
    SELECT comparison.source_family_key
    FROM chain_component_comparison AS comparison
    GROUP BY comparison.source_family_key
    HAVING COUNT(*) > 0
       AND BOOL_AND(comparison.component_matches)
  ),
  fresh_components AS (
    SELECT comparison.*
    FROM chain_component_comparison AS comparison
    JOIN fresh_families AS fresh_family
      ON fresh_family.source_family_key = comparison.source_family_key
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'timesheet_id', fresh_component.root_timesheet_id::text,
        'key_type', fresh_component.key_type,
        'key_value', fresh_component.key_value,
        'expected_ex', fresh_component.expected_ex
      )
      ORDER BY
        fresh_component.root_timesheet_id,
        fresh_component.key_type,
        fresh_component.key_value
    ),
    '[]'::jsonb
  )
  INTO v_fresh_chain_components
  FROM fresh_components AS fresh_component;

  /*
   * Current canonical recovery items freeze one component per item rather
   * than embedding a second complete residual object. Accept that flat frozen
   * shape only when the chain and policy fingerprints still match and the
   * exact frozen component still equals the bounded live residual (with this
   * batch excluded). This also supplies the fresh anchor proof used by linked
   * resolved ordinary components below.
   */
  WITH flat_correction_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      (
        REPLACE(
          COALESCE(
            pay_batch_item.frozen_source_basis_json->>'source_family_key',
            pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
          ),
          'correction-chain:',
          ''
        )
      )::uuid AS root_timesheet_id,
      pay_batch_candidate.candidate_id,
      COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key'
      ) AS source_family_key,
      UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_target_pay_method,
        pay_batch_item.pay_channel,
        pay_batch.batch_kind_fixed,
        ''
      ))) AS target_pay_method,
      UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        pay_batch_item.frozen_component_snapshot_json->>'component_key_type',
        ''
      ))) AS key_type,
      BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        pay_batch_item.frozen_component_snapshot_json->>'component_key_value',
        ''
      )) AS key_value,
      CASE
        WHEN pay_batch_item.frozen_source_amount IS NOT NULL
          THEN ROUND(
            pay_batch_item.frozen_source_amount,
            2
          )::numeric(12,2)
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_pay_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'effective_source_outstanding_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            COALESCE(
              pay_batch_item.frozen_resolution_result_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_pay_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS expected_ex,
      CASE
        WHEN pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
          THEN ROUND(
            pay_batch_item.frozen_target_amount_ex_vat,
            2
          )::numeric(12,2)
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'target_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'target_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE ROUND(
          pay_batch_item.amount_ex_vat,
          2
        )::numeric(12,2)
      END AS expected_target_ex,
      ROUND(
        pay_batch_item.amount_ex_vat,
        2
      )::numeric(12,2) AS physical_target_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'source_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'source_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS result_source_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_result_json
            ->>'target_amount_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            (
              pay_batch_item.frozen_resolution_result_json
                ->>'target_amount_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS result_target_ex,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_amount_ex_vat',
          pay_batch_item.frozen_component_snapshot_json
            ->>'source_pay_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(
            COALESCE(
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_amount_ex_vat',
              pay_batch_item.frozen_component_snapshot_json
                ->>'source_pay_ex_vat'
            )::numeric,
            2
          )::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS snapshot_source_ex,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_source_basis_json
          ->>'correction_chain_fingerprint',
        pay_batch_item.frozen_component_snapshot_json
          ->>'correction_chain_fingerprint',
        ''
      )), '') AS frozen_chain_fingerprint,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_source_basis_json
          ->>'correction_financials_policy_envelope_fingerprint',
        pay_batch_item.frozen_component_snapshot_json
          ->>'correction_financials_policy_envelope_fingerprint',
        ''
      )), '') AS frozen_policy_fingerprint
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    JOIN public.pay_batches AS pay_batch
      ON pay_batch.id = pay_batch_candidate.pay_batch_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
        ''
      ) ~ '^correction-chain:[0-9a-fA-F-]{36}$'
      AND jsonb_typeof(
        pay_batch_item.frozen_component_snapshot_json
      ) = 'object'
      AND pay_batch_item.frozen_source_amount IS NOT NULL
      AND pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_exclusion
        WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
          AND correction_item_exclusion.status = 'APPLIED'
          AND correction_item_exclusion.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ),
  flat_chain_groups AS (
    SELECT DISTINCT
      flat_item.root_timesheet_id,
      flat_item.candidate_id,
      flat_item.source_family_key,
      flat_item.target_pay_method
    FROM flat_correction_items AS flat_item
    WHERE flat_item.root_timesheet_id IS NOT NULL
      AND flat_item.candidate_id IS NOT NULL
      AND flat_item.target_pay_method IN ('PAYE', 'UMBRELLA')
  ),
  flat_chain_results AS (
    SELECT
      flat_group.*,
      public.pay_correction_chain_residual_v1(
        flat_group.root_timesheet_id,
        flat_group.candidate_id,
        flat_group.target_pay_method,
        NULL::uuid,
        p_pay_batch_id,
        100
      ) AS live_residual
    FROM flat_chain_groups AS flat_group
  ),
  flat_fresh_components AS (
    SELECT
      flat_item.root_timesheet_id,
      flat_item.key_type,
      flat_item.key_value,
      flat_item.expected_ex
    FROM flat_correction_items AS flat_item
    JOIN flat_chain_results AS flat_result
      ON flat_result.root_timesheet_id = flat_item.root_timesheet_id
     AND flat_result.candidate_id = flat_item.candidate_id
     AND flat_result.source_family_key = flat_item.source_family_key
     AND flat_result.target_pay_method = flat_item.target_pay_method
    JOIN LATERAL (
      SELECT live_component.component_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(flat_result.live_residual->'components') = 'array'
            THEN flat_result.live_residual->'components'
          ELSE '[]'::jsonb
        END
      ) AS live_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(
              live_component.component_json->>'component_key_type',
              ''
            ))) = flat_item.key_type
        AND BTRIM(COALESCE(
              live_component.component_json->>'component_key_value',
              ''
            )) = flat_item.key_value
      LIMIT 1
    ) AS matched_live_component
      ON true
    WHERE flat_item.key_type IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE',
        'EXPENSE_CODE'
      )
      AND flat_item.key_value <> ''
      AND flat_item.expected_ex IS NOT NULL
      AND flat_item.expected_target_ex IS NOT NULL
      AND flat_item.result_source_ex IS NOT NULL
      AND flat_item.result_target_ex IS NOT NULL
      AND flat_item.snapshot_source_ex IS NOT NULL
      AND flat_item.frozen_chain_fingerprint IS NOT NULL
      AND flat_item.frozen_policy_fingerprint IS NOT NULL
      AND flat_item.frozen_chain_fingerprint
            = flat_result.live_residual->>'chain_fingerprint'
      AND flat_item.frozen_policy_fingerprint
            = flat_result.live_residual
                ->>'correction_financials_policy_envelope_fingerprint'
      AND COALESCE(
        matched_live_component.component_json
          ->>'target_outstanding_ex_vat',
        matched_live_component.component_json
          ->>'effective_source_outstanding_ex_vat',
        ''
      ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND(flat_item.expected_target_ex, 2)
        - ROUND(
            COALESCE(
              matched_live_component.component_json
                ->>'target_outstanding_ex_vat',
              matched_live_component.component_json
                ->>'effective_source_outstanding_ex_vat'
            )::numeric,
            2
          )
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.result_source_ex, 2)
        - ROUND(flat_item.expected_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.snapshot_source_ex, 2)
        - ROUND(flat_item.expected_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.result_target_ex, 2)
        - ROUND(flat_item.expected_target_ex, 2)
      ) <= 0.01
      AND ABS(
        ROUND(flat_item.physical_target_ex, 2)
        - ROUND(flat_item.expected_target_ex, 2)
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', flat_component.root_timesheet_id::text,
          'key_type', flat_component.key_type,
          'key_value', flat_component.key_value,
          'expected_ex', flat_component.expected_ex
        )
        ORDER BY
          flat_component.root_timesheet_id,
          flat_component.key_type,
          flat_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM flat_fresh_components AS flat_component;

  /*
   * A resolved ordinary timesheet component can also carry an approved target
   * rate. Its frozen source entitlement is the full original component, while
   * the item pays only the target-side remainder after the already-settled
   * baseline. The ordinary base comparison therefore reports the expected
   * source entitlement against zero even when:
   *
   *   - the live source component is unchanged;
   *   - no other active batch reserves the component;
   *   - the exact target remainder was frozen into this batch; and
   *   - its exact local-timesheet anchor remains valid, or its linked
   *     correction-chain anchor remains fresh.
   *
   * Suppress only that exact self-reservation diff. This is deliberately
   * stricter than trusting the summary flag: frozen component evidence,
   * physical/result parity, every frozen member of the economic component,
   * current source truth, settled baseline, absence of another reservation,
   * and the applicable frozen anchor must all agree. Any missing, partial or
   * contradictory evidence leaves the base stale result intact.
   */
  WITH linked_resolution_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      pay_batch_item.timesheet_id,
      UPPER(BTRIM(COALESCE(pay_batch_item.frozen_component_key_type, '')))
        AS key_type,
      BTRIM(COALESCE(pay_batch_item.frozen_component_key_value, ''))
        AS key_value,
      pay_batch_item.amount_ex_vat,
      pay_batch_item.frozen_source_amount,
      pay_batch_item.frozen_target_amount_ex_vat,
      pay_batch_item.frozen_resolution_result_json,
      pay_batch_item.frozen_resolution_payload_json
        ->'case_resolution_summary' AS resolution_summary,
      resolved_component.component_count,
      resolved_component.source_numeric_count,
      resolved_component.target_numeric_count,
      resolved_component.resolved_source_ex_vat,
      resolved_component.resolved_target_ex_vat,
      resolved_component.all_components_resolved,
      resolved_component.all_component_fingerprints_present,
      resolved_component.all_source_basis_fingerprints_present,
      resolved_component.all_components_current,
      resolved_component.all_saved_results_current,
      resolved_component.all_components_do_not_require_resolution,
      resolved_component.all_saved_anchor_modes_match,
      resolved_component.all_saved_anchor_case_keys_match,
      resolved_component.all_saved_anchor_timesheets_match,
      LOWER(BTRIM(COALESCE(
        pay_batch_item.frozen_resolution_payload_json
          #>> '{case_resolution_summary,resolved_rate_applied_via_linked_scope}',
        'false'
      ))) IN ('true','t','1','yes','y','on')
        AS applied_via_linked_scope,
      CASE
        WHEN COALESCE(
          pay_batch_item.frozen_resolution_payload_json
            #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}',
          ''
        ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (
            pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}'
          )::uuid
        ELSE NULL::uuid
      END AS anchor_timesheet_id,
      NULLIF(BTRIM(COALESCE(
        pay_batch_item.frozen_resolution_payload_json
          #>> '{case_resolution_summary,resolved_rate_source_anchor_case_key}',
        ''
      )), '') AS anchor_case_key
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS component_count,
        COUNT(*) FILTER (
          WHERE COALESCE(
            frozen_component.component_json->>'source_pay_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        )::integer AS source_numeric_count,
        COUNT(*) FILTER (
          WHERE COALESCE(
            frozen_component.component_json->>'target_pay_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        )::integer AS target_numeric_count,
        ROUND(SUM(
          CASE
            WHEN COALESCE(
              frozen_component.component_json->>'source_pay_ex_vat',
              ''
            ) ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (
                frozen_component.component_json->>'source_pay_ex_vat'
              )::numeric
            ELSE 0::numeric
          END
        ), 2)::numeric(12,2) AS resolved_source_ex_vat,
        ROUND(SUM(
          CASE
            WHEN COALESCE(
              frozen_component.component_json->>'target_pay_ex_vat',
              ''
            ) ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (
                frozen_component.component_json->>'target_pay_ex_vat'
              )::numeric
            ELSE 0::numeric
          END
        ), 2)::numeric(12,2) AS resolved_target_ex_vat,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'resolved_rate_resolution_id',
          ''
        )), '') IS NOT NULL) AS all_components_resolved,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'component_fingerprint',
          ''
        )), '') IS NOT NULL) AS all_component_fingerprints_present,
        BOOL_AND(NULLIF(BTRIM(COALESCE(
          frozen_component.component_json->>'source_basis_fingerprint',
          ''
        )), '') IS NOT NULL) AS all_source_basis_fingerprints_present,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'is_resolution_stale',
          'false'
        ))) NOT IN ('true','t','1','yes','y','on'))
          AS all_components_current,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'is_stale_saved_resolution',
          'false'
        ))) NOT IN ('true','t','1','yes','y','on'))
          AS all_saved_results_current,
        BOOL_AND(LOWER(BTRIM(COALESCE(
          frozen_component.component_json->>'requires_resolution',
          'true'
        ))) IN ('false','f','0','no','n','off'))
          AS all_components_do_not_require_resolution,
        BOOL_AND(
          (
            LOWER(BTRIM(COALESCE(
              frozen_component.component_json
                #>> '{saved_resolution_result_json,applied_via_linked_scope}',
              'false'
            ))) IN ('true','t','1','yes','y','on')
          ) = (
            LOWER(BTRIM(COALESCE(
              pay_batch_item.frozen_resolution_payload_json
                #>> '{case_resolution_summary,resolved_rate_applied_via_linked_scope}',
              'false'
            ))) IN ('true','t','1','yes','y','on')
          )
        ) AS all_saved_anchor_modes_match,
        BOOL_AND(
          frozen_component.component_json
            #>> '{saved_resolution_result_json,source_anchor_case_key}'
          = pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_case_key}'
        ) AS all_saved_anchor_case_keys_match,
        BOOL_AND(
          frozen_component.component_json
            #>> '{saved_resolution_result_json,source_anchor_timesheet_id}'
          = pay_batch_item.frozen_resolution_payload_json
              #>> '{case_resolution_summary,resolved_rate_source_anchor_timesheet_id}'
        ) AS all_saved_anchor_timesheets_match
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(
            pay_batch_item.frozen_resolution_payload_json->'case_components'
          ) = 'array'
            THEN pay_batch_item.frozen_resolution_payload_json->'case_components'
          ELSE '[]'::jsonb
        END
      ) AS frozen_component(component_json)
      WHERE UPPER(BTRIM(COALESCE(
              frozen_component.component_json->>'component_key_type',
              ''
            ))) = UPPER(BTRIM(COALESCE(
              pay_batch_item.frozen_component_key_type,
              ''
            )))
        AND BTRIM(COALESCE(
              frozen_component.component_json->>'component_key_value',
              ''
            )) = BTRIM(COALESCE(
              pay_batch_item.frozen_component_key_value,
              ''
            ))
    ) AS resolved_component
      ON true
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(pay_batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        ''
      ))) IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE'
      )
      AND BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        ''
      )) <> ''
      AND jsonb_typeof(
        pay_batch_item.frozen_resolution_payload_json
          ->'case_resolution_summary'
      ) = 'object'
      AND COALESCE(resolved_component.component_count, 0) > 0
  ),
  linked_timesheet_ids AS (
    SELECT COALESCE(
      ARRAY_AGG(
        DISTINCT linked_resolution_item.timesheet_id
        ORDER BY linked_resolution_item.timesheet_id
      ),
      ARRAY[]::uuid[]
    ) AS timesheet_ids
    FROM linked_resolution_items AS linked_resolution_item
  ),
  linked_outstanding AS (
    SELECT
      outstanding_component.timesheet_id,
      UPPER(BTRIM(COALESCE(outstanding_component.key_type, '')))
        AS key_type,
      BTRIM(COALESCE(outstanding_component.key_value, '')) AS key_value,
      ROUND(COALESCE(outstanding_component.truth_ex_vat, 0), 2)
        AS truth_ex_vat,
      ROUND(COALESCE(outstanding_component.baseline_ex_vat, 0), 2)
        AS baseline_ex_vat,
      ROUND(COALESCE(outstanding_component.reserved_ex_vat, 0), 2)
        AS other_reserved_ex_vat,
      ROUND(COALESCE(outstanding_component.outstanding_ex_vat, 0), 2)
        AS outstanding_ex_vat
    FROM linked_timesheet_ids AS linked_scope
    JOIN public._pay_outstanding_components(
      linked_scope.timesheet_ids,
      p_pay_batch_id
    ) AS outstanding_component
      ON true
  ),
  fresh_linked_resolution_components AS (
    SELECT
      linked_resolution_item.timesheet_id,
      linked_resolution_item.key_type,
      linked_resolution_item.key_value,
      linked_resolution_item.resolved_source_ex_vat AS expected_ex
    FROM linked_resolution_items AS linked_resolution_item
    JOIN linked_outstanding AS outstanding_component
      ON outstanding_component.timesheet_id
           = linked_resolution_item.timesheet_id
     AND outstanding_component.key_type = linked_resolution_item.key_type
     AND outstanding_component.key_value = linked_resolution_item.key_value
    WHERE linked_resolution_item.resolved_source_ex_vat IS NOT NULL
      AND linked_resolution_item.resolved_target_ex_vat IS NOT NULL
      AND linked_resolution_item.anchor_timesheet_id IS NOT NULL
      AND linked_resolution_item.anchor_case_key IS NOT NULL
      AND LOWER(BTRIM(COALESCE(
        linked_resolution_item.resolution_summary->>'has_resolved_rate',
        'false'
      ))) IN ('true','t','1','yes','y','on')
      AND LOWER(BTRIM(COALESCE(
        linked_resolution_item.resolution_summary
          ->>'case_resolution_satisfied_now',
        'false'
      ))) IN ('true','t','1','yes','y','on')
      AND linked_resolution_item.resolution_summary
            ->>'resolved_rate_timesheet_id'
          = linked_resolution_item.timesheet_id::text
      AND linked_resolution_item.component_count
            = linked_resolution_item.source_numeric_count
      AND linked_resolution_item.component_count
            = linked_resolution_item.target_numeric_count
      AND linked_resolution_item.all_components_resolved
      AND linked_resolution_item.all_component_fingerprints_present
      AND linked_resolution_item.all_source_basis_fingerprints_present
      AND linked_resolution_item.all_components_current
      AND linked_resolution_item.all_saved_results_current
      AND linked_resolution_item.all_components_do_not_require_resolution
      AND linked_resolution_item.all_saved_anchor_modes_match
      AND linked_resolution_item.all_saved_anchor_case_keys_match
      AND linked_resolution_item.all_saved_anchor_timesheets_match
      AND (
        (
          linked_resolution_item.applied_via_linked_scope
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(v_fresh_chain_components)
              AS fresh_anchor(value)
            WHERE fresh_anchor.value->>'timesheet_id'
                    = linked_resolution_item.anchor_timesheet_id::text
              AND LOWER(linked_resolution_item.anchor_case_key)
                    = LOWER(
                        'correction-chain:'
                        || linked_resolution_item.anchor_timesheet_id::text
                        || ':'
                        || COALESCE(fresh_anchor.value->>'key_type', '')
                        || ':'
                        || COALESCE(fresh_anchor.value->>'key_value', '')
                      )
          )
        )
        OR
        (
          NOT linked_resolution_item.applied_via_linked_scope
          AND linked_resolution_item.anchor_timesheet_id
                = linked_resolution_item.timesheet_id
          AND LOWER(linked_resolution_item.anchor_case_key)
                = LOWER(
                    'timesheet:'
                    || linked_resolution_item.timesheet_id::text
                  )
        )
      )
      AND ABS(
        ROUND(outstanding_component.truth_ex_vat, 2)
        - ROUND(linked_resolution_item.resolved_source_ex_vat, 2)
      ) <= 0.01
      AND ABS(
        ROUND(outstanding_component.baseline_ex_vat, 2)
        - ROUND(linked_resolution_item.resolved_source_ex_vat, 2)
      ) <= 0.01
      AND ABS(ROUND(outstanding_component.other_reserved_ex_vat, 2)) <= 0.01
      AND ABS(
        ROUND(linked_resolution_item.frozen_target_amount_ex_vat, 2)
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND COALESCE(
        linked_resolution_item.frozen_resolution_result_json
          ->>'target_amount_ex_vat',
        ''
      ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND(
          (
            linked_resolution_item.frozen_resolution_result_json
              ->>'target_amount_ex_vat'
          )::numeric,
          2
        )
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND linked_resolution_item.frozen_source_amount IS NOT NULL
      AND ABS(
        ROUND(linked_resolution_item.frozen_source_amount, 2)
        - ROUND(linked_resolution_item.amount_ex_vat, 2)
      ) <= 0.01
      AND ABS(
        ROUND(linked_resolution_item.amount_ex_vat, 2)
        - ROUND(
            GREATEST(
              linked_resolution_item.resolved_target_ex_vat
                - outstanding_component.baseline_ex_vat,
              0
            ),
            2
          )
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', linked_component.timesheet_id::text,
          'key_type', linked_component.key_type,
          'key_value', linked_component.key_value,
          'expected_ex', linked_component.expected_ex
        )
        ORDER BY
          linked_component.timesheet_id,
          linked_component.key_type,
          linked_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM fresh_linked_resolution_components AS linked_component;

  /*
   * A completed semantic-V3 source can retain a settled entitlement baseline
   * that the legacy live helper no longer exposes.  In that exact case the
   * base validator compares the frozen source amount with live truth alone
   * and mistakes this batch's own reservation for external drift.
   *
   * Recover the baseline only from the one current, parity-complete V3
   * publication that is fenced to the candidate registry's current sequence
   * and generation.  Live truth must still equal the certified build truth,
   * all other reservations are read live with this batch excluded, and the
   * complete frozen source/target evidence must reconcile exactly.  Any
   * missing, mixed or stale authority leaves the base stale result untouched.
   */
  WITH frozen_ordinary_items AS (
    SELECT
      pay_batch_item.id AS pay_batch_item_id,
      pay_batch_candidate.candidate_id,
      pay_batch_item.timesheet_id,
      UPPER(BTRIM(pay_batch_item.frozen_component_key_type)) AS key_type,
      BTRIM(pay_batch_item.frozen_component_key_value) AS key_value,
      ROUND(pay_batch_item.frozen_source_amount, 2)::numeric(12,2)
        AS frozen_source_ex,
      ROUND(pay_batch_item.frozen_target_amount_ex_vat, 2)::numeric(12,2)
        AS frozen_target_ex,
      ROUND(pay_batch_item.amount_ex_vat, 2)::numeric(12,2)
        AS physical_target_ex
    FROM public.pay_batch_items AS pay_batch_item
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.id = pay_batch_item.pay_batch_candidate_id
    WHERE pay_batch_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(pay_batch_item.is_voided, false) = false
      AND pay_batch_item.timesheet_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(pay_batch_item.item_type, ''))) IN (
        'SEGMENT_DELTA',
        'ADJUSTMENT_DELTA',
        'MILEAGE_DELTA'
      )
      AND UPPER(BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_type,
        ''
      ))) IN (
        'TS_DAY',
        'TS_TOTAL',
        'ADDITIONAL_CODE',
        'ADJUSTMENT_CODE',
        'EXPENSE_CODE'
      )
      AND BTRIM(COALESCE(
        pay_batch_item.frozen_component_key_value,
        ''
      )) <> ''
      AND pay_batch_item.frozen_source_amount IS NOT NULL
      AND pay_batch_item.frozen_target_amount_ex_vat IS NOT NULL
      AND ABS(
        ROUND(pay_batch_item.frozen_target_amount_ex_vat, 2)
        - ROUND(pay_batch_item.amount_ex_vat, 2)
      ) <= 0.01
      AND COALESCE(
        pay_batch_item.frozen_source_basis_json->>'source_family_key',
        pay_batch_item.frozen_component_snapshot_json->>'source_family_key',
        ''
      ) NOT LIKE 'correction-chain:%'
      AND jsonb_typeof(
        pay_batch_item.frozen_resolution_payload_json
          ->'case_resolution_summary'
      ) IS DISTINCT FROM 'object'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_exclusion
        WHERE correction_item_exclusion.pay_batch_item_id = pay_batch_item.id
          AND correction_item_exclusion.status = 'APPLIED'
          AND correction_item_exclusion.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ), certified_authority_candidates AS (
    SELECT
      registry.candidate_id,
      scope_row.session_id,
      scope_row.certified_preview_publication_source_build_run_id
        AS source_build_run_id,
      scope_row.certified_preview_publication_source_publication_id
        AS source_publication_id,
      economic_build.id AS build_id,
      registry.current_source_change_seq,
      registry.dirty_generation
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.candidate_id = registry.candidate_id
     AND scope_row.status = 'MATERIALISED'
     AND COALESCE(scope_row.dirty, false) = false
     AND COALESCE(
           scope_row.certified_preview_publication_required,
           false
         )
     AND COALESCE(
           scope_row.certified_preview_publication_parity_ok,
           false
         )
     AND scope_row.certified_preview_publication_source_change_seq
           = registry.current_source_change_seq
     AND scope_row.certified_preview_publication_source_build_run_id
           IS NOT NULL
     AND scope_row.certified_preview_publication_source_publication_id
           IS NOT NULL
    JOIN private.banking_pay_workbench_economic_builds AS economic_build
      ON economic_build.id = CASE
           WHEN COALESCE(
                  scope_row.certified_preview_publication_attestation_json
                    ->>'economic_build_id',
                  ''
                ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN (
               scope_row.certified_preview_publication_attestation_json
                 ->>'economic_build_id'
             )::uuid
           ELSE NULL::uuid
         END
     AND economic_build.candidate_id = registry.candidate_id
     AND economic_build.session_id = scope_row.session_id
     AND economic_build.source_build_run_id
           = scope_row.certified_preview_publication_source_build_run_id
     AND economic_build.source_change_seq
           = registry.current_source_change_seq
     AND economic_build.captured_candidate_generation
           = registry.evaluated_generation
     AND economic_build.status = 'COMPLETE'
    WHERE registry.dirty_generation = registry.evaluated_generation
      AND scope_row.certified_preview_publication_attestation_json
            ->>'attestation_version'
          = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
      AND LOWER(BTRIM(COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'parity_complete',
            'false'
          ))) IN ('true','t','1','yes','y','on')
      AND LOWER(BTRIM(COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'semantic_ready',
            'false'
          ))) IN ('true','t','1','yes','y','on')
      AND COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'invalid_selectable_row_count',
            ''
          ) ~ '^[0-9]+$'
      AND (
            scope_row.certified_preview_publication_attestation_json
              ->>'invalid_selectable_row_count'
          )::integer = 0
      AND scope_row.certified_preview_publication_attestation_json
            ->>'source_build_run_id'
          = scope_row.certified_preview_publication_source_build_run_id::text
      AND scope_row.certified_preview_publication_attestation_json
            ->>'source_publication_id'
          = scope_row.certified_preview_publication_source_publication_id::text
      AND COALESCE(
            scope_row.certified_preview_publication_attestation_json
              ->>'source_row_count',
            ''
          ) ~ '^[0-9]+$'
      AND (
        SELECT COUNT(*)::integer
        FROM public.banking_pay_workbench_candidate_source_lines
          AS current_source
        WHERE current_source.session_id = scope_row.session_id
          AND current_source.candidate_id = registry.candidate_id
          AND current_source.session_version
                = scope_row.certified_preview_publication_session_version
          AND current_source.source_change_seq
                = registry.current_source_change_seq
          AND current_source.source_build_run_id
                = scope_row.certified_preview_publication_source_build_run_id
          AND current_source.source_publication_id
                = scope_row.certified_preview_publication_source_publication_id
          AND current_source.status = 'CURRENT'
      ) = (
        scope_row.certified_preview_publication_attestation_json
          ->>'source_row_count'
      )::integer
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_candidate_source_lines
          AS conflicting_source
        WHERE conflicting_source.session_id = scope_row.session_id
          AND conflicting_source.candidate_id = registry.candidate_id
          AND conflicting_source.status = 'CURRENT'
          AND (
            conflicting_source.session_version
              IS DISTINCT FROM
                scope_row.certified_preview_publication_session_version
            OR conflicting_source.source_change_seq
              IS DISTINCT FROM registry.current_source_change_seq
            OR conflicting_source.source_build_run_id
              IS DISTINCT FROM
                scope_row.certified_preview_publication_source_build_run_id
            OR conflicting_source.source_publication_id
              IS DISTINCT FROM
                scope_row.certified_preview_publication_source_publication_id
          )
      )
  ), certified_current_authorities AS (
    SELECT authority.*
    FROM certified_authority_candidates AS authority
    WHERE 1 = (
      SELECT COUNT(*)
      FROM certified_authority_candidates AS candidate_authority
      WHERE candidate_authority.candidate_id = authority.candidate_id
    )
  ), certified_fresh_components AS (
    SELECT
      frozen_item.timesheet_id,
      frozen_item.key_type,
      frozen_item.key_value,
      frozen_item.frozen_source_ex AS expected_ex
    FROM frozen_ordinary_items AS frozen_item
    JOIN certified_current_authorities AS certified_authority
      ON certified_authority.candidate_id = frozen_item.candidate_id
    JOIN private.pay_current_timesheet_entitlement_components_from_build_v1(
      certified_authority.build_id,
      NULL::text
    ) AS certified_component
      ON certified_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(certified_component.key_type))
           = frozen_item.key_type
     AND BTRIM(certified_component.key_value) = frozen_item.key_value
    JOIN public._pay_current_timesheet_entitlement_components(
      ARRAY[frozen_item.timesheet_id]::uuid[]
    ) AS live_truth_component
      ON live_truth_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(live_truth_component.key_type))
           = frozen_item.key_type
     AND BTRIM(live_truth_component.key_value) = frozen_item.key_value
    JOIN LATERAL public._pay_outstanding_components(
      ARRAY[frozen_item.timesheet_id]::uuid[],
      p_pay_batch_id
    ) AS live_component
      ON live_component.timesheet_id = frozen_item.timesheet_id
     AND UPPER(BTRIM(live_component.key_type)) = frozen_item.key_type
     AND BTRIM(live_component.key_value) = frozen_item.key_value
    WHERE ABS(
        ROUND(COALESCE(live_truth_component.truth_ex_vat, 0), 2)
        - ROUND(COALESCE(certified_component.truth_ex_vat, 0), 2)
      ) <= 0.01
      AND ABS(
        ROUND(COALESCE(live_truth_component.baseline_ex_vat, 0), 2)
        - ROUND(COALESCE(certified_component.baseline_ex_vat, 0), 2)
      ) > 0.01
      AND ABS(
        ROUND(COALESCE(certified_component.baseline_ex_vat, 0), 2)
      ) > 0.01
      AND ABS(
        ROUND(
          COALESCE(certified_component.truth_ex_vat, 0)
          - COALESCE(certified_component.baseline_ex_vat, 0)
          - COALESCE(live_component.reserved_ex_vat, 0),
          2
        )
        - frozen_item.frozen_source_ex
      ) <= 0.01
      AND ABS(
        frozen_item.frozen_target_ex - frozen_item.physical_target_ex
      ) <= 0.01
  )
  SELECT
    v_fresh_chain_components
    || COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', certified_component.timesheet_id::text,
          'key_type', certified_component.key_type,
          'key_value', certified_component.key_value,
          'expected_ex', certified_component.expected_ex
        )
        ORDER BY
          certified_component.timesheet_id,
          certified_component.key_type,
          certified_component.key_value
      ),
      '[]'::jsonb
    )
  INTO v_fresh_chain_components
  FROM certified_fresh_components AS certified_component;

  SELECT COALESCE(
    MAX(
      CASE
        WHEN diff_row.value->>'key_type' = 'INFO'
         AND diff_row.value->>'key_value' = 'COUNTS'
          THEN COALESCE(
            (diff_row.value#>>'{expected,key_diffs}')::integer,
            0
          )
        ELSE NULL
      END
    ),
    0
  )
  INTO v_original_key_diff_count
  FROM jsonb_array_elements(v_base_diff) AS diff_row(value);

  SELECT COUNT(*)::integer
  INTO v_suppressed_key_diff_count
  FROM jsonb_array_elements(v_base_diff) WITH ORDINALITY AS diff_row(value, ordinality)
  WHERE EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_fresh_chain_components)
      AS fresh_component(value)
    WHERE fresh_component.value->>'timesheet_id'
            = diff_row.value->>'timesheet_id'
      AND fresh_component.value->>'key_type'
            = diff_row.value->>'key_type'
      AND fresh_component.value->>'key_value'
            = diff_row.value->>'key_value'
      AND COALESCE(diff_row.value->>'expected', '')
            ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND((diff_row.value->>'expected')::numeric, 2)
        - ROUND((fresh_component.value->>'expected_ex')::numeric, 2)
      ) <= 0.01
  );

  SELECT COALESCE(
    jsonb_agg(diff_row.value ORDER BY diff_row.ordinality),
    '[]'::jsonb
  )
  INTO v_filtered_diff
  FROM jsonb_array_elements(v_base_diff) WITH ORDINALITY AS diff_row(value, ordinality)
  WHERE NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_fresh_chain_components)
      AS fresh_component(value)
    WHERE fresh_component.value->>'timesheet_id'
            = diff_row.value->>'timesheet_id'
      AND fresh_component.value->>'key_type'
            = diff_row.value->>'key_type'
      AND fresh_component.value->>'key_value'
            = diff_row.value->>'key_value'
      AND COALESCE(diff_row.value->>'expected', '')
            ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND ABS(
        ROUND((diff_row.value->>'expected')::numeric, 2)
        - ROUND((fresh_component.value->>'expected_ex')::numeric, 2)
      ) <= 0.01
  );

  v_remaining_key_diff_count := GREATEST(
    v_original_key_diff_count - v_suppressed_key_diff_count,
    0
  );

  SELECT COALESCE(
    jsonb_agg(
      CASE
        WHEN diff_row.value->>'key_type' = 'INFO'
         AND diff_row.value->>'key_value' = 'COUNTS'
          THEN jsonb_set(
            diff_row.value,
            '{expected,key_diffs}',
            to_jsonb(v_remaining_key_diff_count),
            true
          )
        ELSE diff_row.value
      END
      ORDER BY diff_row.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_filtered_diff
  FROM jsonb_array_elements(v_filtered_diff)
    WITH ORDINALITY AS diff_row(value, ordinality);

  IF v_remaining_key_diff_count = 0 THEN
    SELECT COALESCE(jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
    INTO v_reasons
    FROM jsonb_array_elements(v_reasons)
      WITH ORDINALITY AS reason(value, ordinality)
    WHERE reason.value <> to_jsonb('RESERVATION_CHANGED'::text);
  END IF;

  -- A24: Source entitlement head changed after this Draft froze (comparison-only; stricter refusal).
  v_source_head_drift := private.pay_batch_source_head_drift_v1(p_pay_batch_id);
  IF jsonb_array_length(v_source_head_drift) > 0 THEN
    v_reasons := v_reasons || to_jsonb('SOURCE_ENTITLEMENT_HEAD_CHANGED'::text);
    v_filtered_diff := v_filtered_diff || v_source_head_drift;
  END IF;

  RETURN jsonb_build_object(
    'is_stale', jsonb_array_length(v_reasons) > 0,
    'stale_reasons', v_reasons,
    'diff', v_filtered_diff
  );
END;
$function$
;

-- [REPLACES] public.pay_batch_validate_freshness_chunk(p_operation_id uuid, p_cursor_json jsonb, p_limit integer)  winner piece A24
CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness_chunk(p_operation_id uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_date_context jsonb := '{}'::jsonb;
  v_today_uk date := NULL::date;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_invalid_scope_unit_count integer := 0;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_ordinal bigint := NULL::bigint;
  v_cursor_unit_key text := NULL::text;
  v_cursor_has_ordinal boolean := false;
  v_cursor_has_unit_key boolean := false;
  v_cursor_operation_id uuid := NULL::uuid;
  v_cursor_pay_batch_id uuid := NULL::uuid;
  v_raw_count integer := 0;
  v_validated_count integer := 0;
  v_fresh_count integer := 0;
  v_stale_count integer := 0;
  v_error_count integer := 0;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_diff_samples jsonb := '[]'::jsonb;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_prev_summary jsonb := '{}'::jsonb;
  v_new_summary jsonb := '{}'::jsonb;
  v_combined_stale_reasons jsonb := '[]'::jsonb;
  v_combined_diff_samples jsonb := '[]'::jsonb;
  v_prev_total_units integer := 0;
  v_prev_seeded_units integer := 0;
  v_prev_fresh_units integer := 0;
  v_prev_stale_units integer := 0;
  v_prev_pending_units integer := 0;
  v_prev_error_units integer := 0;
  v_new_total_units integer := 0;
  v_new_seeded_units integer := 0;
  v_new_fresh_units integer := 0;
  v_new_stale_units integer := 0;
  v_new_pending_units integer := 0;
  v_new_error_units integer := 0;
  v_new_status text := 'PENDING';
  v_persisted_batch_status text := 'PENDING';
  v_scope_hash text := NULL::text;
  v_prev_result_hash text := NULL::text;
  v_page_result_hash text := NULL::text;
  v_new_result_hash text := NULL::text;
  v_source_head_drift jsonb := '[]'::jsonb;  -- A24
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKER_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk: p_operation_id is required';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_validate_freshness_chunk operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
     OR UPPER(BTRIM(COALESCE(v_operation.status, ''))) <> 'RUNNING'
     OR UPPER(BTRIM(COALESCE(v_operation.phase, ''))) NOT IN ('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
     OR v_operation.pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_AUTHORITY_INVALID',
              'operation_id', p_operation_id::text,
              'operation_type', v_operation.operation_type,
              'operation_status', v_operation.status,
              'operation_phase', v_operation.phase,
              'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
              'required_operation_types', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
              'required_status', 'RUNNING',
              'allowed_phases', jsonb_build_array('FRESHNESS_VALIDATE', 'VALIDATE_FRESHNESS_CHUNK')
            )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation.pay_batch_id
  FOR UPDATE OF batch_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_BATCH_NOT_FOUND',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text
            )::text;
  END IF;

  IF v_batch.freshness_operation_id IS NOT NULL
     AND v_batch.freshness_operation_id IS DISTINCT FROM p_operation_id THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_OPERATION_SUPERSEDED',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'current_freshness_operation_id', v_batch.freshness_operation_id::text
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_invalid_scope_unit_count
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id;

  IF COALESCE(v_invalid_scope_unit_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_SCOPE_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'pay_batch_id', v_operation.pay_batch_id::text,
              'invalid_scope_unit_count', v_invalid_scope_unit_count
            )::text;
  END IF;

  v_date_context := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk := CASE
    WHEN COALESCE(v_date_context->>'london_current_date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      THEN (v_date_context->>'london_current_date')::date
    ELSE NULL::date
  END;
  IF v_today_uk IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_LONDON_DATE_UNAVAILABLE',
              'operation_id', p_operation_id::text,
              'message', 'The current Europe/London business date could not be resolved for chunked batch freshness.'
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL THEN
    IF jsonb_typeof(p_cursor_json) <> 'object' THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_MUST_BE_OBJECT'
              )::text;
    END IF;

    v_cursor_has_ordinal := p_cursor_json ? 'last_unit_ordinal';
    v_cursor_has_unit_key := p_cursor_json ? 'last_unit_key';

    IF v_cursor_has_ordinal IS DISTINCT FROM v_cursor_has_unit_key THEN
      RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                'operation_id', p_operation_id::text,
                'pay_batch_id', v_operation.pay_batch_id::text,
                'reason', 'CURSOR_ORDINAL_AND_KEY_REQUIRED_TOGETHER'
              )::text;
    END IF;

    IF v_cursor_has_ordinal THEN
      IF COALESCE(p_cursor_json->>'last_unit_ordinal', '') !~ '^[0-9]+$'
         OR NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '') IS NULL THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_ORDINAL_OR_KEY_INVALID'
                )::text;
      END IF;

      BEGIN
        v_cursor_ordinal := (p_cursor_json->>'last_unit_ordinal')::bigint;
      EXCEPTION
        WHEN numeric_value_out_of_range OR invalid_text_representation THEN
          RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                    'operation_id', p_operation_id::text,
                    'pay_batch_id', v_operation.pay_batch_id::text,
                    'reason', 'CURSOR_ORDINAL_OUT_OF_RANGE'
                  )::text;
      END;
      v_cursor_unit_key := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_unit_key', '')), '');
    END IF;

    IF p_cursor_json ? 'operation_id' THEN
      IF COALESCE(p_cursor_json->>'operation_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_OPERATION_ID_INVALID'
                )::text;
      END IF;
      v_cursor_operation_id := (p_cursor_json->>'operation_id')::uuid;
      IF v_cursor_operation_id IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'cursor_operation_id', v_cursor_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text
                )::text;
      END IF;
    END IF;

    IF p_cursor_json ? 'pay_batch_id' THEN
      IF COALESCE(p_cursor_json->>'pay_batch_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_INVALID',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'reason', 'CURSOR_PAY_BATCH_ID_INVALID'
                )::text;
      END IF;
      v_cursor_pay_batch_id := (p_cursor_json->>'pay_batch_id')::uuid;
      IF v_cursor_pay_batch_id IS DISTINCT FROM v_operation.pay_batch_id THEN
        RAISE EXCEPTION 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_BATCH_FRESHNESS_CURSOR_AUTHORITY_MISMATCH',
                  'operation_id', p_operation_id::text,
                  'pay_batch_id', v_operation.pay_batch_id::text,
                  'cursor_pay_batch_id', v_cursor_pay_batch_id::text
                )::text;
      END IF;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validate_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validate_page ON COMMIT DROP AS
  SELECT
    scope_unit.operation_id,
    scope_unit.pay_batch_id,
    scope_unit.phase,
    scope_unit.unit_type,
    scope_unit.unit_key,
    scope_unit.unit_payload_json,
    scope_unit.unit_ordinal,
    scope_unit.status,
    row_number() OVER (ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key)::integer AS page_ordinal
  FROM public.banking_pay_operation_scope_units AS scope_unit
  WHERE scope_unit.operation_id = p_operation_id
    AND scope_unit.phase = 'FRESHNESS'
    AND scope_unit.unit_type = 'PAY_BATCH_ITEM'
    AND scope_unit.pay_batch_id = v_operation.pay_batch_id
    AND UPPER(BTRIM(COALESCE(scope_unit.status, ''))) IN ('PENDING', 'QUEUED', 'READY')
    AND (
      v_cursor_ordinal IS NULL
      OR scope_unit.unit_ordinal > v_cursor_ordinal
      OR (scope_unit.unit_ordinal = v_cursor_ordinal AND v_cursor_unit_key IS NOT NULL AND scope_unit.unit_key > v_cursor_unit_key)
    )
  ORDER BY scope_unit.unit_ordinal, scope_unit.unit_key
  LIMIT (v_limit + 1);

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row;

  v_has_more := COALESCE(v_raw_count, 0) > v_limit;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_batch_freshness_validation_result;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_batch_freshness_validation_result ON COMMIT DROP AS
  WITH page_rows AS (
    SELECT page_row.*,
           CASE
             WHEN COALESCE(page_row.unit_payload_json->>'pay_batch_item_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN (page_row.unit_payload_json->>'pay_batch_item_id')::uuid
             ELSE NULL::uuid
           END AS pay_batch_item_id,
           UPPER(NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_type}', '')), '')) AS stored_key_type,
           NULLIF(BTRIM(COALESCE(page_row.unit_payload_json#>>'{economic_key,key_value}', '')), '') AS stored_key_value,
           CASE
             WHEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               THEN COALESCE(page_row.unit_payload_json#>>'{economic_key,timesheet_id}', page_row.unit_payload_json->>'timesheet_id')::uuid
             ELSE NULL::uuid
           END AS stored_timesheet_id,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_ex_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_ex_vat}')::numeric ELSE NULL::numeric END AS stored_amount_ex_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_vat}')::numeric ELSE NULL::numeric END AS stored_amount_vat,
           CASE WHEN COALESCE(page_row.unit_payload_json#>>'{amounts,amount_inc_vat}', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (page_row.unit_payload_json#>>'{amounts,amount_inc_vat}')::numeric ELSE NULL::numeric END AS stored_amount_inc_vat
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
  ), live_items AS (
    SELECT
      page_rows.*,
      batch_item.id AS live_pay_batch_item_id,
      batch_item.timesheet_id AS live_timesheet_id,
      batch_item.item_type AS live_item_type,
      batch_item.amount_ex_vat AS live_amount_ex_vat,
      batch_item.amount_vat AS live_amount_vat,
      batch_item.amount_inc_vat AS live_amount_inc_vat,
      COALESCE(batch_item.is_voided, false) AS live_is_voided,
      batch_item.frozen_component_key_type,
      batch_item.frozen_component_key_value,
      batch_item.frozen_component_snapshot_json,
      batch_item.frozen_source_basis_json,
      batch_item.payout_instruction_snapshot_json,
      NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') AS live_source_ref,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
        LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
      ) AS live_exact_source_ref,
      CASE
        WHEN COALESCE(
          CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
          LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
        ) ~* '^timesheet-expense:' THEN 'TIMESHEET_EXPENSE'
        WHEN batch_item.finance_case_id IS NOT NULL
          OR LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '')) ~* '^advance:' THEN 'FINANCE_CASE'
        WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') IS NOT NULL THEN 'EXACT_SOURCE'
        ELSE 'TIMESHEET_OR_SEGMENT'
      END AS live_source_identity_kind,
      NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') AS live_segment_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
        NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
      ) AS live_segment_stable_key,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
      ) AS live_segment_id,
      COALESCE(
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
        NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
        (
          SELECT COALESCE(
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
            NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
          )
          FROM public.pay_batch_timesheet_snapshots AS snapshot_row
          WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
            AND snapshot_row.timesheet_id = batch_item.timesheet_id
          ORDER BY snapshot_row.id
          LIMIT 1
        )
      ) AS live_booking_id,
      batch_item.finance_case_id AS live_finance_case_id,
      batch_item.finance_component_id AS live_finance_component_id,
      (
        batch_item.finance_case_id IS NOT NULL
        OR COALESCE(
          NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',
          false
        )
      ) AS live_is_finance_source,
      COALESCE(
        CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL END,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), '') ~* '^advance:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
          ELSE NULL
        END
      ) AS live_finance_source_ref,
      batch_candidate.candidate_id AS live_candidate_id,
      active_snooze.id AS active_snooze_id,
      active_snooze.snooze_kind AS active_snooze_kind,
      active_snooze.snooze_until_date AS active_snooze_until_date,
      active_snooze.source_ref AS active_snooze_source_ref,
      active_snooze.segment_stable_key AS active_snooze_segment_stable_key,
      active_snooze.segment_id AS active_snooze_segment_id,
      active_snooze.booking_id AS active_snooze_booking_id,
      active_snooze.match_scope AS active_snooze_match_scope
    FROM page_rows
    LEFT JOIN public.pay_batch_items AS batch_item
      ON batch_item.id = page_rows.pay_batch_item_id
    LEFT JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = page_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        snooze_row.id,
        snooze_row.snooze_kind,
        snooze_row.snooze_until_date,
        snooze_row.source_ref,
        snooze_row.segment_stable_key,
        snooze_row.segment_id,
        snooze_row.booking_id,
        CASE
          WHEN snooze_row.source_ref IS NOT NULL THEN 'EXACT_SOURCE_REF'
          ELSE 'LEGACY_TIMESHEET_SEGMENT'
        END AS match_scope
      FROM public.pay_item_snoozes AS snooze_row
      WHERE snooze_row.candidate_id = batch_candidate.candidate_id
        AND snooze_row.cleared_at_utc IS NULL
        AND snooze_row.cancelled_at_utc IS NULL
        AND (
          snooze_row.snooze_until_date IS NULL
          OR snooze_row.snooze_until_date >= v_today_uk
        )
        AND (
          (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NOT NULL
            AND LOWER(NULLIF(BTRIM(COALESCE(snooze_row.source_ref, '')), '')) = COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            )
          )
          OR (
            COALESCE(
              CASE WHEN batch_item.finance_case_id IS NOT NULL THEN 'advance:' || batch_item.finance_case_id::text ELSE NULL::text END,
              LOWER(NULLIF(BTRIM(COALESCE(batch_item.source_ref, '')), ''))
            ) IS NULL
            AND snooze_row.source_ref IS NULL
            AND (
              (
                batch_item.timesheet_id IS NOT NULL
                AND snooze_row.timesheet_id = batch_item.timesheet_id
              )
              OR (
                NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{booking,booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{booking,booking_id}'), ''),
                  (
                    SELECT COALESCE(
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{booking,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{timesheet,booking_id}'), ''),
                      NULLIF(BTRIM(snapshot_row.target_snapshot_json #>> '{target,booking_id}'), '')
                    )
                    FROM public.pay_batch_timesheet_snapshots AS snapshot_row
                    WHERE snapshot_row.pay_batch_id = page_rows.pay_batch_id
                      AND snapshot_row.timesheet_id = batch_item.timesheet_id
                    ORDER BY snapshot_row.id
                    LIMIT 1
                  )
                )
              )
            )
            AND (
              (
                NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') IS NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') IS NULL
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_stable_key}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,stable_key}'), ''),
                  NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '')
                )
              )
              OR (
                COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                ) IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') = COALESCE(
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_source_basis_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.frozen_component_snapshot_json #>> '{segment,id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment_id}'), ''),
                  NULLIF(BTRIM(batch_item.payout_instruction_snapshot_json #>> '{segment,id}'), '')
                )
              )
              OR (
                NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(batch_item.segment_key, '')), '') IN (
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), ''),
                  NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '')
                )
              )
            )
          )
        )
      ORDER BY snooze_row.updated_at_utc DESC, snooze_row.created_at_utc DESC, snooze_row.id
      LIMIT 1
    ) AS active_snooze ON TRUE
  ), resolved AS (
    SELECT
      live_items.*,
      policy_key.timesheet_id AS resolved_timesheet_id,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value,
      policy_key.key_resolution_source,
      policy_key.key_resolution_failure_reason
    FROM live_items
    LEFT JOIN LATERAL public._pay_policy_x_resolve_post_draft_economic_key(
      p_pay_batch_item_id => live_items.live_pay_batch_item_id,
      p_pay_batch_id => live_items.pay_batch_id,
      p_timesheet_id => live_items.live_timesheet_id,
      p_item_type => live_items.live_item_type,
      p_frozen_key_type => live_items.frozen_component_key_type,
      p_frozen_key_value => live_items.frozen_component_key_value,
      p_frozen_component_snapshot_json => COALESCE(live_items.frozen_component_snapshot_json, '{}'::jsonb),
      p_frozen_source_basis_json => COALESCE(live_items.frozen_source_basis_json, '{}'::jsonb),
      p_breakdown_meta_json => '{}'::jsonb,
      p_target_snapshot_json => NULL::jsonb
    ) AS policy_key ON true
  ), evaluated AS (
    SELECT
      resolved.*,
      (
        CASE WHEN resolved.live_pay_batch_item_id IS NULL THEN jsonb_build_array('PAY_BATCH_ITEM_MISSING') ELSE '[]'::jsonb END
        || CASE WHEN resolved.live_is_voided THEN jsonb_build_array('PAY_BATCH_ITEM_VOIDED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.resolved_key_type IS NULL OR resolved.resolved_key_value IS NULL THEN jsonb_build_array(COALESCE(resolved.key_resolution_failure_reason, 'POST_DRAFT_KEY_RESOLUTION_FAILED')) ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_type IS NOT NULL AND resolved.resolved_key_type IS NOT NULL AND resolved.stored_key_type IS DISTINCT FROM resolved.resolved_key_type THEN jsonb_build_array('ECONOMIC_KEY_TYPE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_key_value IS NOT NULL AND resolved.resolved_key_value IS NOT NULL AND resolved.stored_key_value IS DISTINCT FROM resolved.resolved_key_value THEN jsonb_build_array('ECONOMIC_KEY_VALUE_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_timesheet_id IS NOT NULL AND resolved.resolved_timesheet_id IS NOT NULL AND resolved.stored_timesheet_id IS DISTINCT FROM resolved.resolved_timesheet_id THEN jsonb_build_array('ECONOMIC_TIMESHEET_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_ex_vat IS NOT NULL AND resolved.live_amount_ex_vat IS NOT NULL AND ROUND(resolved.stored_amount_ex_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_ex_vat, 2) THEN jsonb_build_array('AMOUNT_EX_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_vat IS NOT NULL AND resolved.live_amount_vat IS NOT NULL AND ROUND(resolved.stored_amount_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_vat, 2) THEN jsonb_build_array('AMOUNT_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE WHEN resolved.stored_amount_inc_vat IS NOT NULL AND resolved.live_amount_inc_vat IS NOT NULL AND ROUND(resolved.stored_amount_inc_vat, 2) IS DISTINCT FROM ROUND(resolved.live_amount_inc_vat, 2) THEN jsonb_build_array('AMOUNT_INC_VAT_CHANGED') ELSE '[]'::jsonb END
        || CASE
          WHEN resolved.active_snooze_id IS NOT NULL
            THEN jsonb_build_array('ACTIVE_SNOOZE_CHANGED')
          ELSE '[]'::jsonb
        END
      ) AS stale_reasons_json
    FROM resolved
  )
  SELECT
    evaluated.*,
    (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0) AS is_stale,
    jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'stored_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.stored_timesheet_id IS NULL THEN NULL ELSE evaluated.stored_timesheet_id::text END, 'key_type', evaluated.stored_key_type, 'key_value', evaluated.stored_key_value)),
      'resolved_key', jsonb_strip_nulls(jsonb_build_object('timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END, 'key_type', evaluated.resolved_key_type, 'key_value', evaluated.resolved_key_value)),
      'stale_reasons', evaluated.stale_reasons_json,
      'stored_amount_ex_vat', evaluated.stored_amount_ex_vat,
      'current_amount_ex_vat', evaluated.live_amount_ex_vat,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE jsonb_strip_nulls(jsonb_build_object(
        'snooze_id', evaluated.active_snooze_id::text,
        'snooze_kind', evaluated.active_snooze_kind,
        'snooze_until_date', CASE WHEN evaluated.active_snooze_until_date IS NULL THEN NULL ELSE evaluated.active_snooze_until_date::text END,
        'active_as_of_london_date', v_today_uk::text,
        'source_ref', evaluated.active_snooze_source_ref,
        'segment_stable_key', evaluated.active_snooze_segment_stable_key,
        'segment_id', evaluated.active_snooze_segment_id,
        'booking_id', evaluated.active_snooze_booking_id,
        'source_match_scope', evaluated.active_snooze_match_scope
      )) END
    )) AS diff_json,
    md5(jsonb_strip_nulls(jsonb_build_object(
      'unit_key', evaluated.unit_key,
      'pay_batch_item_id', CASE WHEN evaluated.pay_batch_item_id IS NULL THEN NULL ELSE evaluated.pay_batch_item_id::text END,
      'resolved_key_type', evaluated.resolved_key_type,
      'resolved_key_value', evaluated.resolved_key_value,
      'resolved_timesheet_id', CASE WHEN evaluated.resolved_timesheet_id IS NULL THEN NULL ELSE evaluated.resolved_timesheet_id::text END,
      'is_stale', (jsonb_array_length(COALESCE(evaluated.stale_reasons_json, '[]'::jsonb)) > 0),
      'stale_reasons', evaluated.stale_reasons_json,
      'active_snooze_id', CASE WHEN evaluated.active_snooze_id IS NULL THEN NULL ELSE evaluated.active_snooze_id::text END,
      'frozen_source_ref', evaluated.live_exact_source_ref,
      'source_identity_kind', evaluated.live_source_identity_kind,
      'active_snooze_match_scope', evaluated.active_snooze_match_scope,
      'london_current_date', v_today_uk::text
    ))::text) AS proof_hash
  FROM evaluated;

  WITH updated_units AS (
    UPDATE public.banking_pay_operation_scope_units AS scope_unit
    SET status = CASE WHEN result_row.is_stale THEN 'STALE' ELSE 'FRESH' END,
        result_hash = result_row.proof_hash,
        error_json = NULL::jsonb,
        unit_payload_json = COALESCE(scope_unit.unit_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'validation_result', jsonb_build_object(
              'validated_at_utc', v_now::text,
              'is_stale', result_row.is_stale,
              'stale_reasons', result_row.stale_reasons_json,
              'diff', CASE WHEN result_row.is_stale THEN result_row.diff_json ELSE NULL::jsonb END,
              'proof_hash', result_row.proof_hash
            )
          ),
        updated_at_utc = v_now
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE scope_unit.operation_id = result_row.operation_id
      AND scope_unit.phase = result_row.phase
      AND scope_unit.unit_type = result_row.unit_type
      AND scope_unit.unit_key = result_row.unit_key
    RETURNING scope_unit.status
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'FRESH')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'STALE')::integer,
    COUNT(*) FILTER (WHERE updated_units.status = 'ERROR')::integer
  INTO v_validated_count, v_fresh_count, v_stale_count, v_error_count
  FROM updated_units;

  SELECT COALESCE(jsonb_agg(diff_source.diff_json ORDER BY diff_source.unit_ordinal, diff_source.unit_key), '[]'::jsonb)
  INTO v_diff_samples
  FROM (
    SELECT result_row.diff_json, result_row.unit_ordinal, result_row.unit_key
    FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
    WHERE result_row.is_stale = true
    ORDER BY result_row.unit_ordinal, result_row.unit_key
    LIMIT 25
  ) AS diff_source;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_element.value ORDER BY reason_element.value), '[]'::jsonb)
  INTO v_stale_reasons
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row
  CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(result_row.stale_reasons_json, '[]'::jsonb)) AS reason_element(value)
  WHERE result_row.is_stale = true;

  SELECT md5(COALESCE(string_agg(COALESCE(result_row.proof_hash, 'NO_RESULT'), '|' ORDER BY result_row.unit_ordinal, result_row.unit_key), 'EMPTY_VALIDATION_CHUNK'))
  INTO v_page_result_hash
  FROM pg_temp.tmp_pay_batch_freshness_validation_result AS result_row;

  IF v_has_more THEN
    SELECT jsonb_build_object(
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation.pay_batch_id::text,
      'last_unit_ordinal', page_row.unit_ordinal,
      'last_unit_key', page_row.unit_key
    )
    INTO v_next_cursor
    FROM pg_temp.tmp_pay_batch_freshness_validate_page AS page_row
    WHERE page_row.page_ordinal = v_limit;
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  v_prev_summary := CASE
    WHEN jsonb_typeof(COALESCE(v_operation.progress_json, '{}'::jsonb)->'freshness_summary') = 'object'
      THEN COALESCE(v_operation.progress_json->'freshness_summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_prev_total_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'total_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'total_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_total_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_total_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_seeded_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'seeded_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'seeded_units')::integer ELSE NULL::integer END,
    v_prev_total_units,
    0
  );
  v_prev_fresh_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'fresh_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'fresh_units')::integer ELSE NULL::integer END, 0);
  v_prev_stale_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'stale_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'stale_units')::integer ELSE NULL::integer END, 0);
  v_prev_pending_units := COALESCE(
    CASE WHEN COALESCE(v_prev_summary->>'pending_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'pending_units')::integer ELSE NULL::integer END,
    CASE WHEN COALESCE(v_operation.progress_json->>'freshness_pending_units', '') ~ '^[0-9]+$' THEN (v_operation.progress_json->>'freshness_pending_units')::integer ELSE NULL::integer END,
    0
  );
  v_prev_error_units := COALESCE(CASE WHEN COALESCE(v_prev_summary->>'error_units', '') ~ '^[0-9]+$' THEN (v_prev_summary->>'error_units')::integer ELSE NULL::integer END, 0);
  v_scope_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'scope_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_scope_hash', '')), '')
  );
  v_prev_result_hash := COALESCE(
    NULLIF(BTRIM(COALESCE(v_prev_summary->>'result_hash', '')), ''),
    NULLIF(BTRIM(COALESCE(v_operation.progress_json->>'freshness_result_hash', '')), '')
  );

  v_new_fresh_units := COALESCE(v_prev_fresh_units, 0) + COALESCE(v_fresh_count, 0);
  v_new_stale_units := COALESCE(v_prev_stale_units, 0) + COALESCE(v_stale_count, 0);
  v_new_error_units := COALESCE(v_prev_error_units, 0) + COALESCE(v_error_count, 0);
  v_new_pending_units := GREATEST(COALESCE(v_prev_pending_units, 0) - COALESCE(v_validated_count, 0), 0);
  v_new_seeded_units := GREATEST(COALESCE(v_prev_seeded_units, 0), COALESCE(v_prev_total_units, 0), v_new_fresh_units + v_new_stale_units + v_new_error_units + v_new_pending_units);
  v_new_total_units := GREATEST(COALESCE(v_prev_total_units, 0), v_new_seeded_units);

  v_new_status := CASE
    WHEN COALESCE(v_new_pending_units, 0) > 0 OR COALESCE(v_has_more, false) THEN 'PENDING'
    WHEN COALESCE(v_new_error_units, 0) > 0 THEN 'ERROR'
    WHEN COALESCE(v_new_stale_units, 0) > 0 THEN 'STALE'
    ELSE 'PASSED'
  END;
  v_persisted_batch_status := CASE WHEN v_new_status = 'ERROR' THEN 'FAILED' ELSE v_new_status END;

  -- A24: a completed chunked run may not persist PASSED over a Source entitlement head that was made current
  -- after this Draft froze.  Comparison-only; runs once, at completion.
  IF v_new_status = 'PASSED' AND v_operation.pay_batch_id IS NOT NULL THEN
    v_source_head_drift := private.pay_batch_source_head_drift_v1(v_operation.pay_batch_id);
    IF jsonb_array_length(v_source_head_drift) > 0 THEN
      v_new_status := 'STALE';
      v_persisted_batch_status := 'STALE';
      v_stale_reasons := COALESCE(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('SOURCE_ENTITLEMENT_HEAD_CHANGED');
      v_diff_samples := COALESCE(v_diff_samples, '[]'::jsonb) || v_source_head_drift;
      v_page_result_hash := md5(COALESCE(v_page_result_hash, 'EMPTY_VALIDATION_CHUNK') || '|SOURCE_ENTITLEMENT_HEAD_CHANGED|' || v_source_head_drift::text);
    END IF;
  END IF;

  v_new_result_hash := CASE
    WHEN v_prev_result_hash IS NULL THEN COALESCE(v_page_result_hash, 'EMPTY_RESULT')
    ELSE md5(v_prev_result_hash || '|chunk|' || COALESCE(v_page_result_hash, 'EMPTY_VALIDATION_CHUNK'))
  END;

  SELECT COALESCE(jsonb_agg(DISTINCT reason_union.reason_text ORDER BY reason_union.reason_text), '[]'::jsonb)
  INTO v_combined_stale_reasons
  FROM (
    SELECT previous_reason.value AS reason_text
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(v_prev_summary->'stale_reasons') = 'array' THEN COALESCE(v_prev_summary->'stale_reasons', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS previous_reason(value)
    UNION ALL
    SELECT current_reason.value AS reason_text
    FROM jsonb_array_elements_text(COALESCE(v_stale_reasons, '[]'::jsonb)) AS current_reason(value)
  ) AS reason_union
  WHERE NULLIF(BTRIM(COALESCE(reason_union.reason_text, '')), '') IS NOT NULL;

  SELECT COALESCE(jsonb_agg(capped_diff.diff_json ORDER BY capped_diff.sample_rank), '[]'::jsonb)
  INTO v_combined_diff_samples
  FROM (
    SELECT diff_union.diff_json, diff_union.sample_rank
    FROM (
      SELECT previous_diff.value AS diff_json, previous_diff.ordinality::integer AS sample_rank
      FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_prev_summary->'diff_samples') = 'array' THEN COALESCE(v_prev_summary->'diff_samples', '[]'::jsonb) ELSE '[]'::jsonb END
      ) WITH ORDINALITY AS previous_diff(value, ordinality)
      UNION ALL
      SELECT current_diff.value AS diff_json, (1000 + current_diff.ordinality)::integer AS sample_rank
      FROM jsonb_array_elements(COALESCE(v_diff_samples, '[]'::jsonb)) WITH ORDINALITY AS current_diff(value, ordinality)
    ) AS diff_union
    WHERE jsonb_typeof(diff_union.diff_json) = 'object'
    ORDER BY diff_union.sample_rank
    LIMIT 25
  ) AS capped_diff;

  v_new_summary := jsonb_strip_nulls(jsonb_build_object(
    'status', v_new_status,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'unit_type', 'PAY_BATCH_ITEM',
    'seeded_units', COALESCE(v_new_seeded_units, 0),
    'total_units', COALESCE(v_new_total_units, 0),
    'fresh_units', COALESCE(v_new_fresh_units, 0),
    'stale_units', COALESCE(v_new_stale_units, 0),
    'pending_units', COALESCE(v_new_pending_units, 0),
    'error_units', COALESCE(v_new_error_units, 0),
    'scope_hash', v_scope_hash,
    'result_hash', v_new_result_hash,
    'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
    'last_validated_at_utc', v_now::text,
    'london_current_date', v_today_uk::text,
    'last_validated_count', COALESCE(v_validated_count, 0),
    'last_fresh_count', COALESCE(v_fresh_count, 0),
    'last_stale_count', COALESCE(v_stale_count, 0),
    'last_error_count', COALESCE(v_error_count, 0),
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  ));

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_summary', v_new_summary,
          'freshness_status', v_new_status,
          'freshness_total_units', COALESCE(v_new_total_units, 0),
          'freshness_stale_units', COALESCE(v_new_stale_units, 0),
          'freshness_pending_units', COALESCE(v_new_pending_units, 0),
          'freshness_error_units', COALESCE(v_new_error_units, 0),
          'freshness_scope_hash', v_scope_hash,
          'freshness_result_hash', v_new_result_hash
        )
      ),
      result_json = CASE
        WHEN v_new_status <> 'PENDING' THEN jsonb_set(
          COALESCE(operation_update.result_json, '{}'::jsonb),
          '{freshness}',
          v_new_summary,
          true
        )
        ELSE operation_update.result_json
      END,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  IF v_operation.pay_batch_id IS NOT NULL THEN
    UPDATE public.pay_batches AS batch_update
    SET freshness_operation_id = p_operation_id,
        freshness_validation_status = v_persisted_batch_status,
        freshness_checked_at_utc = CASE WHEN v_new_status <> 'PENDING' THEN v_now ELSE batch_update.freshness_checked_at_utc END,
        freshness_scope_hash = COALESCE(v_scope_hash, batch_update.freshness_scope_hash),
        freshness_result_hash = CASE WHEN v_new_status <> 'PENDING' THEN v_new_result_hash ELSE batch_update.freshness_result_hash END,
        freshness_result_json = jsonb_build_object(
          'ok', true,
          'operation_id', p_operation_id::text,
          'pay_batch_id', v_operation.pay_batch_id::text,
          'phase', 'FRESHNESS',
          'status', v_new_status,
          'is_stale', v_new_status IN ('STALE', 'ERROR'),
          'stale_reasons', COALESCE(v_combined_stale_reasons, '[]'::jsonb),
          'diff', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'diff_samples', COALESCE(v_combined_diff_samples, '[]'::jsonb),
          'scope_hash', v_scope_hash,
          'result_hash', v_new_result_hash,
          'summary', v_new_summary,
          'checked_at_utc', CASE WHEN v_new_status <> 'PENDING' THEN v_now::text ELSE NULL END
        )
    WHERE batch_update.id = v_operation.pay_batch_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_operation.pay_batch_id IS NULL THEN NULL ELSE v_operation.pay_batch_id::text END,
    'phase', 'FRESHNESS',
    'london_current_date', v_today_uk::text,
    'validated_count', COALESCE(v_validated_count, 0),
    'fresh_count', COALESCE(v_fresh_count, 0),
    'stale_count', COALESCE(v_stale_count, 0),
    'error_count', COALESCE(v_error_count, 0),
    'stale_reasons', COALESCE(v_stale_reasons, '[]'::jsonb),
    'diff_samples', COALESCE(v_diff_samples, '[]'::jsonb),
    'limit', v_limit,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor', v_next_cursor
  );
END;
$function$
;

-- [REPLACES] public.pay_batches_list(p_limit integer, p_offset integer, p_status text, p_actor_user_id uuid, p_display_mode text, p_include_diagnostics boolean, p_include_alerts boolean, p_include_correction_summary boolean)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_batches_list(p_limit integer DEFAULT 5, p_offset integer DEFAULT 0, p_status text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_display_mode text DEFAULT 'LIGHT'::text, p_include_diagnostics boolean DEFAULT false, p_include_alerts boolean DEFAULT false, p_include_correction_summary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 5), 200));
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_status text := UPPER(NULLIF(BTRIM(COALESCE(p_status, '')), ''));
  v_display_mode text := UPPER(REPLACE(NULLIF(BTRIM(COALESCE(p_display_mode, 'LIGHT')), ''), '-', '_'));
  v_include_diagnostics boolean := false;
  v_include_alerts boolean := COALESCE(p_include_alerts, false);
  v_include_correction_summary boolean := false;
  v_rows jsonb := '[]'::jsonb;
  v_returned_count integer := 0;
  v_total_count integer := 0;
  v_has_more boolean := false;
  v_next_offset integer := NULL::integer;
  v_previous_offset integer := NULL::integer;
  v_actor_is_valid boolean := true;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_cached_alert_summary jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('BATCH_LIST');

  IF v_display_mode IS NULL THEN
    v_display_mode := 'LIGHT';
  END IF;

  -- This list RPC is always the safe display path.  Diagnostic/correction
  -- enrichment requests are intentionally ignored here; explicit diagnostic
  -- routes must use their own RPCs.  Cached alert signal data may still be
  -- included when requested because it is read from banking_alert_display_summary.
  v_include_diagnostics := false;
  v_include_correction_summary := false;

  IF v_display_mode NOT IN ('LIGHT', 'SUMMARY', 'BOOTSTRAP') THEN
    RAISE EXCEPTION 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCHES_LIST_DISPLAY_MODE_NOT_ALLOWED',
              'display_mode', v_display_mode,
              'message', 'pay_batches_list only supports LIGHT/SUMMARY/BOOTSTRAP display modes on this safe list path.'
            )::text;
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.tms_users AS actor_user
      WHERE actor_user.id = p_actor_user_id
        AND COALESCE(actor_user.is_active, false) = true
    )
    INTO v_actor_is_valid;

    IF COALESCE(v_actor_is_valid, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCHES_LIST_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    END IF;
  END IF;

  IF v_include_alerts AND p_actor_user_id IS NOT NULL THEN
    SELECT
      COALESCE(alert_summary.alert_hash, 'banking_alert_signal:v3:' || MD5('')),
      COALESCE(alert_summary.summary_hash, 'banking_alert_summary:v3:' || MD5('')),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label,
      COALESCE(alert_summary.summary_json, '{}'::jsonb)
    INTO
      v_cached_alert_hash,
      v_cached_summary_hash,
      v_cached_unacknowledged_count,
      v_cached_highest_severity,
      v_cached_highest_label,
      v_cached_alert_summary
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = p_actor_user_id;

    IF NOT FOUND THEN
      v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_cached_unacknowledged_count := 0;
      v_cached_highest_severity := NULL::text;
      v_cached_highest_label := NULL::text;
      v_cached_alert_summary := '{}'::jsonb;
    END IF;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_total_count
  FROM public.pay_batches AS pay_batch_count
  WHERE (v_status IS NULL
     OR UPPER(COALESCE(pay_batch_count.status, '')) = v_status)
    AND NOT EXISTS (
      -- A30 (PRE-EXISTING fix, H6 M3): hide a batch while its V8 Draft operation is unfinished (same predicate as
      -- private.pay_batch_v8_draft_preparation_unfinished_v1, inlined for the list's count and page scans)
      SELECT 1
      FROM public.banking_pay_operation_candidate_scope AS a30_scope
      JOIN public.banking_pay_operations AS a30_operation
        ON a30_operation.id = a30_scope.operation_id
      WHERE a30_scope.pay_batch_id = pay_batch_count.id
        AND a30_operation.operation_type = 'DRAFT_CREATE'
        AND a30_operation.status <> ALL (ARRAY['COMPLETE','FAILED','CANCELLED','CANCELED','REVIEW_REQUIRED']::text[])
        AND a30_operation.input_json ? 'workbench_settled_certificate_reference_v8'
    );

  WITH page_source AS (
    SELECT
      pay_batch_row.id,
      pay_batch_row.pay_date,
      pay_batch_row.authoritative_payment_date,
      pay_batch_row.authoritative_payment_date_source,
      pay_batch_row.created_at_utc,
      pay_batch_row.created_by_user_id,
      pay_batch_row.status,
      pay_batch_row.banking_system_snapshot,
      pay_batch_row.external_paye_system_snapshot,
      pay_batch_row.batch_kind_fixed,
      pay_batch_row.source_workbench_session_id,
      pay_batch_row.source_snapshot_run_id,
      pay_batch_row.source_session_version,
      pay_batch_row.execution_commit_state,
      pay_batch_row.execution_commit_ref,
      pay_batch_row.execution_committed_at_utc,
      pay_batch_row.rail_provider_snapshot,
      pay_batch_row.rail_env_snapshot,
      pay_batch_row.schedule_kind,
      pay_batch_row.scheduled_at_utc,
      pay_batch_row.funding_account_ref,
      pay_batch_row.total_bank_out,
      pay_batch_row.total_debt_created,
      pay_batch_row.freshness_validation_status,
      pay_batch_row.freshness_checked_at_utc,
      pay_batch_row.freshness_result_hash,
      display_summary.batch_status AS display_batch_status,
      display_summary.batch_kind AS display_batch_kind,
      display_summary.candidate_count,
      display_summary.item_count,
      display_summary.transfer_count,
      display_summary.total_payable,
      display_summary.total_bank_out AS display_total_bank_out,
      display_summary.execution_commit_state AS display_execution_commit_state,
      display_summary.rail_provider_label,
      display_summary.rail_env_label,
      display_summary.issue_summary_counts,
      display_summary.latest_operation_id,
      display_summary.latest_operation_status,
      display_summary.latest_operation_phase,
      active_execution_operation.id AS active_payment_operation_id,
      active_execution_operation.operation_type AS active_payment_operation_type,
      active_execution_operation.status AS active_payment_operation_status,
      active_execution_operation.phase AS active_payment_operation_phase,
      active_execution_operation.runner_state AS active_payment_operation_runner_state,
      active_execution_operation.requires_user_action AS active_payment_operation_requires_user_action,
      active_execution_operation.resume_reason AS active_payment_operation_resume_reason,
      active_execution_operation.updated_at_utc AS active_payment_operation_updated_at_utc,
      CASE
        WHEN active_execution_operation.id IS NULL THEN NULL::jsonb
        ELSE jsonb_strip_nulls(jsonb_build_object(
          'operation_id', active_execution_operation.id::text,
          'id', active_execution_operation.id::text,
          'operation_type', active_execution_operation.operation_type,
          'status', active_execution_operation.status,
          'phase', active_execution_operation.phase,
          'runner_state', active_execution_operation.runner_state,
          'requires_user_action', active_execution_operation.requires_user_action,
          'resume_reason', active_execution_operation.resume_reason,
          'pay_batch_id', active_execution_operation.pay_batch_id::text,
          'workbench_session_id', CASE WHEN active_execution_operation.workbench_session_id IS NULL THEN NULL::text ELSE active_execution_operation.workbench_session_id::text END,
          'progress_json', active_execution_operation.progress_json,
          'updated_at_utc', active_execution_operation.updated_at_utc
        ))
      END AS active_payment_operation,
      display_summary.display_label,
      display_summary.stale_summary_json,
      display_summary.freshness_validation_status AS display_freshness_validation_status,
      display_summary.freshness_checked_at_utc AS display_freshness_checked_at_utc,
      display_summary.freshness_result_hash AS display_freshness_result_hash,
      display_summary.summary_version,
      display_summary.updated_at_utc AS summary_updated_at_utc,
      COALESCE(batch_signal.version, 0) AS live_signal_version,
      COALESCE(batch_signal.payment_status_version, 0) AS payment_status_version,
      COALESCE(batch_signal.correction_progress_version, 0) AS correction_progress_version,
      COALESCE(batch_signal.alert_version, 0) AS alert_version,
      COALESCE(batch_signal.overview_version, 0) AS overview_version,
      batch_signal.last_status_hash,
      batch_signal.last_alert_hash,
      batch_signal.last_changed_at_utc,
      batch_signal.last_payment_status_changed_at_utc,
      batch_signal.last_correction_progress_changed_at_utc,
      batch_signal.last_alert_changed_at_utc,
      batch_signal.last_change_reason,
      batch_signal.last_change_source,
      COALESCE(batch_signal.last_change_scope_json, '{}'::jsonb) AS last_change_scope_json,
      COALESCE(batch_signal.last_changed_candidate_ids, '[]'::jsonb) AS last_changed_candidate_ids,
      COALESCE(batch_signal.last_changed_pay_batch_item_ids, '[]'::jsonb) AS last_changed_pay_batch_item_ids,
      COALESCE(batch_signal.last_changed_transfer_ids, '[]'::jsonb) AS last_changed_transfer_ids,
      ROW_NUMBER() OVER (ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC) AS row_ordinal
    FROM public.pay_batches AS pay_batch_row
    LEFT JOIN public.pay_batch_display_summary AS display_summary
      ON display_summary.pay_batch_id = pay_batch_row.id
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = pay_batch_row.id
    LEFT JOIN LATERAL (
      SELECT active_operation.*
      FROM public.banking_pay_operations AS active_operation
      WHERE active_operation.pay_batch_id = pay_batch_row.id
        AND upper(BTRIM(COALESCE(active_operation.operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
        AND upper(BTRIM(COALESCE(active_operation.status, ''))) IN ('QUEUED', 'RUNNING', 'WAITING', 'RUNNABLE', 'CONTINUING', 'WAITING_RETRY', 'WAITING_AUTHORISATION', 'WAITING_AUTHORIZATION', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'WAITING_PROVIDER', 'WAITING_FOR_PROVIDER', 'AWAITING_PROVIDER', 'WAITING_USER', 'WAITING_USER_REVIEW', 'REVIEW_REQUIRED')
      ORDER BY
        CASE upper(BTRIM(COALESCE(active_operation.status, '')))
          WHEN 'RUNNING' THEN 0
          WHEN 'WAITING' THEN 1
          WHEN 'RUNNABLE' THEN 2
          WHEN 'QUEUED' THEN 3
          WHEN 'CONTINUING' THEN 4
          WHEN 'WAITING_RETRY' THEN 5
          WHEN 'WAITING_AUTHORISATION' THEN 6
          WHEN 'WAITING_AUTHORIZATION' THEN 6
          WHEN 'AWAITING_AUTHORISATION' THEN 6
          WHEN 'AWAITING_AUTHORIZATION' THEN 6
          WHEN 'WAITING_PROVIDER' THEN 7
          WHEN 'WAITING_FOR_PROVIDER' THEN 7
          WHEN 'AWAITING_PROVIDER' THEN 7
          WHEN 'WAITING_USER' THEN 8
          WHEN 'WAITING_USER_REVIEW' THEN 8
          WHEN 'REVIEW_REQUIRED' THEN 9
          ELSE 10
        END,
        active_operation.updated_at_utc DESC NULLS LAST,
        active_operation.created_at_utc DESC NULLS LAST,
        active_operation.id DESC
      LIMIT 1
    ) AS active_execution_operation ON true
    WHERE (v_status IS NULL
       OR UPPER(COALESCE(pay_batch_row.status, '')) = v_status)
      AND NOT EXISTS (
      -- A30 (PRE-EXISTING fix, H6 M3): hide a batch while its V8 Draft operation is unfinished (same predicate as
      -- private.pay_batch_v8_draft_preparation_unfinished_v1, inlined for the list's count and page scans)
      SELECT 1
      FROM public.banking_pay_operation_candidate_scope AS a30_scope
      JOIN public.banking_pay_operations AS a30_operation
        ON a30_operation.id = a30_scope.operation_id
      WHERE a30_scope.pay_batch_id = pay_batch_row.id
        AND a30_operation.operation_type = 'DRAFT_CREATE'
        AND a30_operation.status <> ALL (ARRAY['COMPLETE','FAILED','CANCELLED','CANCELED','REVIEW_REQUIRED']::text[])
        AND a30_operation.input_json ? 'workbench_settled_certificate_reference_v8'
    )
    ORDER BY pay_batch_row.created_at_utc DESC, pay_batch_row.id DESC
    LIMIT v_limit
    OFFSET v_offset
  ),
  page_json AS (
    SELECT
      page_source.row_ordinal,
      jsonb_strip_nulls(
        jsonb_build_object(
          'id', page_source.id::text,
          'pay_date', CASE WHEN page_source.pay_date IS NULL THEN NULL::text ELSE page_source.pay_date::text END,
          'authoritative_payment_date', CASE WHEN page_source.authoritative_payment_date IS NULL THEN NULL::text ELSE page_source.authoritative_payment_date::text END,
          'authoritative_payment_date_source', page_source.authoritative_payment_date_source,
          'created_at_utc', page_source.created_at_utc,
          'created_by_user_id', CASE WHEN page_source.created_by_user_id IS NULL THEN NULL::text ELSE page_source.created_by_user_id::text END,
          'status', page_source.status,
          'db_status', page_source.status,
          'batch_kind_fixed', page_source.batch_kind_fixed,
          'batch_kind', COALESCE(page_source.display_batch_kind, page_source.batch_kind_fixed),
          'display_label', page_source.display_label,
          'banking_system_snapshot', page_source.banking_system_snapshot,
          'external_paye_system_snapshot', page_source.external_paye_system_snapshot,
          'source_workbench_session_id', CASE WHEN page_source.source_workbench_session_id IS NULL THEN NULL::text ELSE page_source.source_workbench_session_id::text END,
          'source_snapshot_run_id', CASE WHEN page_source.source_snapshot_run_id IS NULL THEN NULL::text ELSE page_source.source_snapshot_run_id::text END,
          'source_session_version', page_source.source_session_version,
          'execution_commit_state', COALESCE(page_source.display_execution_commit_state, page_source.execution_commit_state),
          'execution_commit_ref', page_source.execution_commit_ref,
          'execution_committed_at_utc', page_source.execution_committed_at_utc
        )
        || jsonb_build_object(
          'rail_provider_snapshot', COALESCE(page_source.rail_provider_label, page_source.rail_provider_snapshot),
          'rail_env_snapshot', COALESCE(page_source.rail_env_label, page_source.rail_env_snapshot),
          'schedule_kind', page_source.schedule_kind,
          'scheduled_at_utc', page_source.scheduled_at_utc,
          'funding_account_ref', page_source.funding_account_ref,
          'total_bank_out', COALESCE(page_source.display_total_bank_out, page_source.total_bank_out, 0),
          'total_debt_created', COALESCE(page_source.total_debt_created, 0),
          'candidate_count', COALESCE(page_source.candidate_count, 0),
          'item_count', COALESCE(page_source.item_count, 0),
          'transfer_count', COALESCE(page_source.transfer_count, 0),
          'total_payable', COALESCE(page_source.total_payable, 0),
          'latest_operation_id', CASE WHEN page_source.latest_operation_id IS NULL THEN NULL::text ELSE page_source.latest_operation_id::text END,
          'latest_operation_status', page_source.latest_operation_status,
          'latest_operation_phase', page_source.latest_operation_phase,
          'active_payment_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_payment_operation_type', page_source.active_payment_operation_type,
          'active_payment_operation_status', page_source.active_payment_operation_status,
          'active_payment_operation_phase', page_source.active_payment_operation_phase,
          'active_payment_operation_runner_state', page_source.active_payment_operation_runner_state,
          'active_payment_operation_requires_user_action', page_source.active_payment_operation_requires_user_action,
          'active_payment_operation_resume_reason', page_source.active_payment_operation_resume_reason,
          'active_payment_operation_updated_at_utc', page_source.active_payment_operation_updated_at_utc,
          'active_payment_operation', page_source.active_payment_operation,
          'active_payment_execute_operation', page_source.active_payment_operation,
          'payment_execute_operation', page_source.active_payment_operation,
          'active_operation_id', CASE WHEN page_source.active_payment_operation_id IS NULL THEN NULL::text ELSE page_source.active_payment_operation_id::text END,
          'active_operation_type', page_source.active_payment_operation_type,
          'active_operation_status', page_source.active_payment_operation_status,
          'active_operation_phase', page_source.active_payment_operation_phase,
          'active_operation', page_source.active_payment_operation,
          'issue_summary_counts', COALESCE(page_source.issue_summary_counts, '{}'::jsonb),
          'stale_summary_json', COALESCE(page_source.stale_summary_json, '{}'::jsonb),
          'freshness_validation_status', COALESCE(page_source.display_freshness_validation_status, page_source.freshness_validation_status),
          'freshness_checked_at_utc', COALESCE(page_source.display_freshness_checked_at_utc, page_source.freshness_checked_at_utc),
          'freshness_result_hash', COALESCE(page_source.display_freshness_result_hash, page_source.freshness_result_hash),
          'summary_version', COALESCE(page_source.summary_version, 0),
          'summary_updated_at_utc', page_source.summary_updated_at_utc
        )
        || jsonb_build_object(
          'live_signal_version', page_source.live_signal_version,
          'payment_status_version', page_source.payment_status_version,
          'correction_progress_version', page_source.correction_progress_version,
          'alert_version', page_source.alert_version,
          'overview_version', page_source.overview_version,
          'last_status_hash', page_source.last_status_hash,
          'last_alert_hash', page_source.last_alert_hash,
          'last_changed_at_utc', page_source.last_changed_at_utc,
          'last_payment_status_changed_at_utc', page_source.last_payment_status_changed_at_utc,
          'last_correction_progress_changed_at_utc', page_source.last_correction_progress_changed_at_utc,
          'last_alert_changed_at_utc', page_source.last_alert_changed_at_utc,
          'last_change_reason', page_source.last_change_reason,
          'last_change_source', page_source.last_change_source,
          'last_change_scope_json', COALESCE(page_source.last_change_scope_json, '{}'::jsonb),
          'last_changed_candidate_ids', COALESCE(page_source.last_changed_candidate_ids, '[]'::jsonb),
          'last_changed_pay_batch_item_ids', COALESCE(page_source.last_changed_pay_batch_item_ids, '[]'::jsonb),
          'last_changed_transfer_ids', COALESCE(page_source.last_changed_transfer_ids, '[]'::jsonb),
          'draft_stale_hint', LOWER(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_hint', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'draft_stale_reason', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'stale_reason', '')), ''),
          'draft_stale_policy_x_authority_scope', NULLIF(BTRIM(COALESCE(page_source.last_change_scope_json->>'policy_x_authority_scope', '')), ''),
          'diagnostics_deferred', true,
          'diagnostics_included', false,
          'alerts_included', false,
          'correction_summary_included', v_include_correction_summary,
          'display_mode', v_display_mode
        )
      ) AS row_json
    FROM page_source
  )
  SELECT
    COALESCE(jsonb_agg(page_json.row_json ORDER BY page_json.row_ordinal), '[]'::jsonb),
    (SELECT COUNT(*)::integer FROM page_source)
  INTO
    v_rows,
    v_returned_count
  FROM page_json;

  v_returned_count := COALESCE(v_returned_count, 0);
  v_total_count := COALESCE(v_total_count, 0);
  v_has_more := (v_offset + v_returned_count) < v_total_count;
  v_next_offset := CASE WHEN v_has_more THEN v_offset + v_limit ELSE NULL::integer END;
  v_previous_offset := CASE WHEN v_offset > 0 THEN GREATEST(0, v_offset - v_limit) ELSE NULL::integer END;

  RETURN jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'display_mode', v_display_mode,
      'limit', v_limit,
      'offset', v_offset,
      'next_offset', v_next_offset,
      'previous_offset', v_previous_offset,
      'has_more', v_has_more,
      'returned_count', v_returned_count,
      'count', v_total_count,
      'total_count', v_total_count,
      'known_total_count', true,
      'rows', COALESCE(v_rows, '[]'::jsonb),
      'items', COALESCE(v_rows, '[]'::jsonb),
      'diagnostics_included', false,
      'diagnostics_requested', v_include_diagnostics,
      'alerts_requested', v_include_alerts,
      'correction_summary_requested', v_include_correction_summary
    )
    || jsonb_build_object(
      'banking_alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE NULL::text END,
      'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE NULL::text END,
      'banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'grouped_banking_unacknowledged_alert_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
      'banking_highest_alert_severity', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_severity, '') ELSE '' END,
      'banking_highest_alert_label', CASE WHEN v_include_alerts THEN COALESCE(v_cached_highest_label, '') ELSE '' END,
      'banking_alerts', '[]'::jsonb,
      'banking_alert_summary', jsonb_build_object(
        'ok', true,
        'cached', true,
        'alerts', '[]'::jsonb,
        'unacknowledged_count', CASE WHEN v_include_alerts THEN v_cached_unacknowledged_count ELSE 0 END,
        'highest_severity', CASE WHEN v_include_alerts THEN v_cached_highest_severity ELSE NULL::text END,
        'highest_label', CASE WHEN v_include_alerts THEN v_cached_highest_label ELSE NULL::text END,
        'alert_hash', CASE WHEN v_include_alerts THEN v_cached_alert_hash ELSE 'banking_alert_signal:v3:' || MD5('') END,
        'banking_alert_summary_signature', CASE WHEN v_include_alerts THEN v_cached_summary_hash ELSE 'banking_alert_summary:v3:' || MD5('') END,
        'summary_json', CASE WHEN v_include_alerts THEN COALESCE(v_cached_alert_summary, '{}'::jsonb) ELSE '{}'::jsonb END
      )
    )
  );
END;
$function$
;

-- [REPLACES] public.pay_export_bank_csv(p_pay_batch_id uuid, p_scope text)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_export_bank_csv(p_pay_batch_id uuid, p_scope text DEFAULT 'ALL'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));

  v_default_cols jsonb := '["payment_reference","payee_name","sort_code","account_number","amount"]'::jsonb;
  v_cols_json jsonb;
  v_cols text[];
  v_col text;

  v_allowed_cols text[] := array[
    'transfer_id',
    'payment_reference',
    'payee_name',
    'sort_code',
    'account_number',
    'account_type',
    'amount',
    'currency',
    'pay_channel',
    'rail_provider',
    'rail_env',
    'request_id',
    'transfer_group_key',
    'grouping_mode_used',
    'week_ending_bucket',
    'candidate_id',
    'umbrella_id',
    'payee_entity_kind',
    'payee_entity_id',
    'bank_details_hash_snapshot'
  ];

  v_format_json jsonb := '{}'::jsonb;
  v_headers_json jsonb := '{}'::jsonb;
  v_include_header boolean := true;
  v_delimiter text := ',';
  v_line_ending text := E'\n';
  v_line_ending_key text := 'LF';
  v_quote_mode text := 'MINIMAL';
  v_bom boolean := false;
  v_sort_code_format text := 'AS_STORED';
  v_account_number_format text := 'AS_STORED';
  v_amount_decimals int := 2;
  v_empty_value text := '';

  v_header text := '';
  v_body text := '';
  v_csv text := '';

  v_missing_count int := 0;
  v_row_count int := 0;
  v_missing_paye_net_count int := 0;
  v_explicit_zero_count int := 0;
  v_positive_bank_payment_count int := 0;
  v_invalid_payment_row_count int := 0;

  v_hdr_part text;
  v_hdr_override text;
  v_val text;
  v_line text;
  v_digits text;

  v_batch_created_by_user_id uuid := null;
  v_batch_kind_fixed text := null;
  v_batch_status text := null;
  v_cancelled_at_utc timestamptz := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;
  v_pre_execution_export boolean := false;
  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  r record;
begin
  -- A30 (PRE-EXISTING fix, H6 M3): a batch whose V8 Draft operation is still being prepared (or failing and
  -- retrying) is not a published Draft. Its partial content is not readable until the operation finishes.
  IF private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id) THEN
    RAISE EXCEPTION 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED'
      USING ERRCODE = '55000',
            DETAIL = pg_catalog.jsonb_build_object('code', 'PAY_BATCH_DRAFT_PREPARATION_UNFINISHED',
              'pay_batch_id', p_pay_batch_id::text)::text;
  END IF;

  if v_scope not in ('ALL','PAYE','UMBRELLA','LOANS') then
    raise exception 'pay_export_bank_csv: invalid scope "%". Expected ALL|PAYE|UMBRELLA|LOANS.', v_scope;
  end if;

  select
    pb.created_by_user_id,
    upper(btrim(coalesce(pb.batch_kind_fixed, ''))),
    upper(btrim(coalesce(pb.status, ''))),
    pb.cancelled_at_utc,
    upper(btrim(coalesce(pb.execution_commit_state, 'NOT_SUBMITTED'))),
    nullif(btrim(coalesce(pb.execution_commit_ref, '')), ''),
    pb.execution_committed_at_utc,
    upper(btrim(coalesce(pb.freshness_validation_status, ''))),
    nullif(btrim(coalesce(pb.freshness_result_hash, '')), ''),
    nullif(btrim(coalesce(pb.freshness_scope_hash, '')), ''),
    coalesce(pb.freshness_result_json, '{}'::jsonb)
  into
    v_batch_created_by_user_id,
    v_batch_kind_fixed,
    v_batch_status,
    v_cancelled_at_utc,
    v_execution_commit_state,
    v_execution_commit_ref,
    v_execution_committed_at_utc,
    v_freshness_validation_status,
    v_freshness_result_hash,
    v_freshness_scope_hash,
    v_freshness_result_json
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if not found then
    raise exception 'pay_export_bank_csv: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;

  v_pre_execution_export := (
    v_cancelled_at_utc is null
    and v_batch_status not in ('CANCELLED', 'CANCELED')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id,
        coalesce(v_batch_created_by_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
        false
      );
      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_EXPORT_BANK_CSV',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_export_bank_csv: chunked freshness validation is required before payment-initiation export' else 'pay_export_bank_csv: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  -- Load configured CSV column order and formatting.
  -- Column inclusion/order remains controlled by pay_export_csv_columns_json.
  -- Formatting/header behaviour is controlled by pay_export_csv_format_json.
  select
    sd.pay_export_csv_columns_json,
    coalesce(sd.pay_export_csv_format_json, '{}'::jsonb)
  into
    v_cols_json,
    v_format_json
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cols_json is null or jsonb_typeof(v_cols_json) <> 'array' or jsonb_array_length(v_cols_json) = 0 then
    v_cols_json := v_default_cols;
  end if;

  if v_format_json is null or jsonb_typeof(v_format_json) <> 'object' then
    v_format_json := '{}'::jsonb;
  end if;

  if (v_format_json ? 'headers') and jsonb_typeof(v_format_json->'headers') = 'object' then
    v_headers_json := v_format_json->'headers';
  else
    v_headers_json := '{}'::jsonb;
  end if;

  if v_format_json ? 'include_header' then
    begin
      v_include_header := coalesce((v_format_json->>'include_header')::boolean, true);
    exception when others then
      v_include_header := true;
    end;
  end if;

  if v_format_json ? 'bom' then
    begin
      v_bom := coalesce((v_format_json->>'bom')::boolean, false);
    exception when others then
      v_bom := false;
    end;
  end if;

  v_delimiter := coalesce(nullif(v_format_json->>'delimiter', ''), ',');
  if upper(v_delimiter) = 'TAB' then
    v_delimiter := E'\t';
  elsif v_delimiter = '\\t' then
    v_delimiter := E'\t';
  elsif v_delimiter not in (',',';','|',E'\t') then
    v_delimiter := ',';
  end if;

  v_line_ending_key := upper(coalesce(nullif(v_format_json->>'line_ending', ''), 'LF'));
  if v_line_ending_key = 'CRLF' then
    v_line_ending := E'\r\n';
  else
    v_line_ending := E'\n';
  end if;

  v_quote_mode := upper(coalesce(nullif(v_format_json->>'quote_mode', ''), 'MINIMAL'));
  if v_quote_mode not in ('MINIMAL','ALL') then
    v_quote_mode := 'MINIMAL';
  end if;

  v_sort_code_format := upper(coalesce(nullif(v_format_json->>'sort_code_format', ''), 'AS_STORED'));
  if v_sort_code_format not in ('AS_STORED','DIGITS','HYPHENATED') then
    v_sort_code_format := 'AS_STORED';
  end if;

  v_account_number_format := upper(coalesce(nullif(v_format_json->>'account_number_format', ''), 'AS_STORED'));
  if v_account_number_format not in ('AS_STORED','DIGITS') then
    v_account_number_format := 'AS_STORED';
  end if;

  if v_format_json ? 'amount_decimals' then
    begin
      v_amount_decimals := greatest(0, least(4, (v_format_json->>'amount_decimals')::int));
    exception when others then
      v_amount_decimals := 2;
    end;
  end if;

  v_empty_value := coalesce(v_format_json->>'empty_value', '');

  select coalesce(array_agg(t.col order by t.ord), array[]::text[])
  into v_cols
  from jsonb_array_elements_text(v_cols_json) with ordinality as t(col, ord);

  if array_length(v_cols, 1) is null or array_length(v_cols, 1) = 0 then
    v_cols := array['payment_reference','payee_name','sort_code','account_number','amount']::text[];
  end if;

  -- Validate column keys: must be from allowed set.
  foreach v_col in array v_cols loop
    if v_col is null or btrim(v_col) = '' then
      raise exception 'pay_export_bank_csv: export columns contain an empty key';
    end if;

    if not (v_col = any(v_allowed_cols)) then
      raise exception 'pay_export_bank_csv: invalid export column "%". Allowed=%', v_col, array_to_string(v_allowed_cols, ',');
    end if;
  end loop;

  -- Reject duplicates (deterministic export).
  if (
    select count(*)::int
    from unnest(v_cols) x
  ) <> (
    select count(distinct x)::int
    from unnest(v_cols) x
  ) then
    raise exception 'pay_export_bank_csv: duplicate column keys in pay_export_csv_columns_json';
  end if;

  -- Materialise one bounded export row source. Pre-execution rows are projected
  -- directly from frozen batch artefacts; historical/cancelled rows remain the
  -- existing materialised transfer rows.
  DROP TABLE IF EXISTS pg_temp.tmp_pay_export_bank_csv_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_export_bank_csv_rows (
    row_ordinal bigint NOT NULL,
    transfer_id uuid NULL,
    payment_reference text NULL,
    payee_name text NULL,
    sort_code text NULL,
    account_number text NULL,
    account_type text NULL,
    amount numeric NULL,
    currency text NULL,
    pay_channel text NULL,
    rail_provider text NULL,
    rail_env text NULL,
    request_id text NULL,
    transfer_group_key text NULL,
    grouping_mode_used text NULL,
    week_ending_bucket date NULL,
    candidate_id uuid NULL,
    umbrella_id uuid NULL,
    payee_entity_kind text NULL,
    payee_entity_id uuid NULL,
    bank_details_hash_snapshot text NULL
  ) ON COMMIT DROP;

  IF v_pre_execution_export THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_export_bank_projection_rows;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_export_bank_projection_rows
    ON COMMIT DROP
    AS
    SELECT projection_row.*
    FROM public._pay_batch_bank_payment_projection_rows(
      p_pay_batch_id,
      v_scope
    ) AS projection_row;

    SELECT
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'MISSING'
      )::integer,
      COUNT(*) FILTER (
        WHERE projection_row.is_paye_net_state_row
          AND projection_row.paye_net_classification = 'ZERO'
      )::integer,
      COUNT(*) FILTER (
        WHERE (
          projection_row.paye_net_required IS TRUE
          AND COALESCE(projection_row.paye_net_classification, '') NOT IN ('MISSING', 'ZERO', 'POSITIVE')
        )
        OR (
          COALESCE(projection_row.paye_net_required, false) IS FALSE
          AND (
            projection_row.final_frozen_bank_amount IS NULL
            OR ROUND(projection_row.final_frozen_bank_amount, 2) <= 0
          )
        )
      )::integer
    INTO
      v_missing_paye_net_count,
      v_explicit_zero_count,
      v_invalid_payment_row_count
    FROM pg_temp.tmp_pay_export_bank_projection_rows AS projection_row;

    v_missing_paye_net_count := COALESCE(v_missing_paye_net_count, 0);
    v_explicit_zero_count := COALESCE(v_explicit_zero_count, 0);
    v_invalid_payment_row_count := COALESCE(v_invalid_payment_row_count, 0);

    IF v_missing_paye_net_count > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXPORT_BANK_CSV',
        'code', 'PAYE_NET_REQUIRED_FOR_BANK_CSV',
        'message', 'Bank CSV cannot be generated until every required PAYE net amount has been explicitly entered or imported.',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'missing_explicit_paye_input_count', v_missing_paye_net_count
      )::text USING ERRCODE = 'P0001';
    END IF;


    IF v_invalid_payment_row_count > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXPORT_BANK_CSV',
        'code', 'BANK_PAYMENT_PROJECTION_INVALID_FOR_BANK_CSV',
        'message', 'Bank CSV cannot be generated because one or more projected payment rows have a non-positive or otherwise invalid payable amount.',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'invalid_payment_row_count', v_invalid_payment_row_count
      )::text USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO pg_temp.tmp_pay_export_bank_csv_rows (
      row_ordinal,
      transfer_id,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      amount,
      currency,
      pay_channel,
      rail_provider,
      rail_env,
      request_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      bank_details_hash_snapshot
    )
    SELECT
      projection_row.payment_group_ordinal,
      NULL::uuid,
      projection_row.payment_reference,
      projection_row.payee_name,
      projection_row.sort_code,
      projection_row.account_number,
      projection_row.account_type,
      projection_row.amount,
      projection_row.currency,
      projection_row.pay_channel,
      projection_row.rail_provider,
      projection_row.rail_env,
      NULL::text,
      projection_row.transfer_group_key,
      projection_row.grouping_mode_used,
      projection_row.week_ending_bucket,
      projection_row.candidate_id,
      projection_row.umbrella_id,
      projection_row.payee_entity_kind,
      projection_row.payee_entity_id,
      projection_row.bank_details_hash_snapshot
    FROM pg_temp.tmp_pay_export_bank_projection_rows AS projection_row
    WHERE projection_row.is_positive_bank_payment
    ORDER BY projection_row.payment_group_ordinal,
             projection_row.stable_order_key;
  ELSE
    INSERT INTO pg_temp.tmp_pay_export_bank_csv_rows (
      row_ordinal,
      transfer_id,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      amount,
      currency,
      pay_channel,
      rail_provider,
      rail_env,
      request_id,
      transfer_group_key,
      grouping_mode_used,
      week_ending_bucket,
      candidate_id,
      umbrella_id,
      payee_entity_kind,
      payee_entity_id,
      bank_details_hash_snapshot
    )
    SELECT
      ROW_NUMBER() OVER (ORDER BY transfer_row.id),
      transfer_row.id,
      transfer_row.payment_reference,
      transfer_row.payee_name,
      transfer_row.sort_code,
      transfer_row.account_number,
      transfer_row.account_type,
      transfer_row.amount,
      transfer_row.currency,
      transfer_row.pay_channel,
      transfer_row.rail_provider,
      transfer_row.rail_env,
      transfer_row.request_id,
      transfer_row.transfer_group_key,
      transfer_row.grouping_mode_used,
      transfer_row.week_ending_bucket,
      transfer_row.candidate_id,
      transfer_row.umbrella_id,
      transfer_row.payee_entity_kind,
      transfer_row.payee_entity_id,
      transfer_row.bank_details_hash_snapshot
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (
        v_scope = 'ALL'
        OR transfer_row.pay_channel = v_scope
        OR (v_scope = 'LOANS' AND v_batch_kind_fixed = 'LOANS' AND transfer_row.pay_channel = 'PAYE')
      )
      AND UPPER(COALESCE(transfer_row.status, '')) <> 'BLOCKED'
    ORDER BY transfer_row.id;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_positive_bank_payment_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row;

  -- Ensure required snapshot fields exist for all exportable rows, but only for
  -- fields selected by configuration. Transfer/request identifiers are allowed
  -- to be blank for the direct pre-execution projection because they do not yet
  -- exist and must never be fabricated.
  SELECT COUNT(*)::integer
  INTO v_missing_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row
  WHERE
       (array_position(v_cols, 'payment_reference') IS NOT NULL AND export_row.payment_reference IS NULL)
    OR (array_position(v_cols, 'payee_name') IS NOT NULL AND export_row.payee_name IS NULL)
    OR (array_position(v_cols, 'sort_code') IS NOT NULL AND export_row.sort_code IS NULL)
    OR (array_position(v_cols, 'account_number') IS NOT NULL AND export_row.account_number IS NULL)
    OR (array_position(v_cols, 'amount') IS NOT NULL AND export_row.amount IS NULL)
    OR (array_position(v_cols, 'currency') IS NOT NULL AND export_row.currency IS NULL)
    OR (array_position(v_cols, 'pay_channel') IS NOT NULL AND export_row.pay_channel IS NULL)
    OR (array_position(v_cols, 'rail_provider') IS NOT NULL AND export_row.rail_provider IS NULL)
    OR (array_position(v_cols, 'rail_env') IS NOT NULL AND export_row.rail_env IS NULL)
    OR (
      v_pre_execution_export IS NOT TRUE
      AND array_position(v_cols, 'request_id') IS NOT NULL
      AND export_row.request_id IS NULL
    )
    OR (array_position(v_cols, 'transfer_group_key') IS NOT NULL AND export_row.transfer_group_key IS NULL)
    OR (array_position(v_cols, 'grouping_mode_used') IS NOT NULL AND export_row.grouping_mode_used IS NULL)
    OR (array_position(v_cols, 'week_ending_bucket') IS NOT NULL AND export_row.week_ending_bucket IS NULL)
    OR (array_position(v_cols, 'candidate_id') IS NOT NULL AND export_row.candidate_id IS NULL)
    OR (array_position(v_cols, 'umbrella_id') IS NOT NULL AND export_row.umbrella_id IS NULL)
    OR (array_position(v_cols, 'payee_entity_kind') IS NOT NULL AND export_row.payee_entity_kind IS NULL)
    OR (array_position(v_cols, 'payee_entity_id') IS NOT NULL AND export_row.payee_entity_id IS NULL)
    OR (array_position(v_cols, 'bank_details_hash_snapshot') IS NOT NULL AND export_row.bank_details_hash_snapshot IS NULL);

  IF v_missing_count > 0 THEN
    RAISE EXCEPTION 'pay_export_bank_csv: % exportable payment row(s) are missing one or more required fields for the configured export.', v_missing_count;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_row_count
  FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row;

  IF v_row_count = 0
     AND NOT (
       v_pre_execution_export
       AND v_missing_paye_net_count = 0
       AND v_explicit_zero_count > 0
       AND v_positive_bank_payment_count = 0
       AND v_invalid_payment_row_count = 0
     ) THEN
    RAISE EXCEPTION 'pay_export_bank_csv: no exportable transfers found for batch % (scope=%).', p_pay_batch_id, v_scope;
  END IF;

  -- Build header from configured columns and optional user overrides.
  v_header := '';
  if v_include_header = true then
    foreach v_col in array v_cols loop
      v_hdr_part := case v_col
        when 'transfer_id' then 'Transfer id'
        when 'payment_reference' then 'Payment reference'
        when 'payee_name' then 'Payee name'
        when 'sort_code' then 'Sort code'
        when 'account_number' then 'Bank account number'
        when 'account_type' then 'Bank account type'
        when 'amount' then 'Amount'
        when 'currency' then 'Currency'
        when 'pay_channel' then 'Channel'
        when 'rail_provider' then 'Rail provider'
        when 'rail_env' then 'Rail env'
        when 'request_id' then 'Request id'
        when 'transfer_group_key' then 'Transfer group key'
        when 'grouping_mode_used' then 'Grouping mode'
        when 'week_ending_bucket' then 'Week ending'
        when 'candidate_id' then 'Candidate id'
        when 'umbrella_id' then 'Umbrella id'
        when 'payee_entity_kind' then 'Payee entity kind'
        when 'payee_entity_id' then 'Payee entity id'
        when 'bank_details_hash_snapshot' then 'Bank details hash'
        else initcap(replace(v_col, '_', ' '))
      end;

      v_hdr_override := nullif(btrim(coalesce(v_headers_json->>v_col, '')), '');
      if v_hdr_override is not null then
        v_hdr_part := v_hdr_override;
      end if;

      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_hdr_part) > 0
        or position('"' in v_hdr_part) > 0
        or position(E'\r' in v_hdr_part) > 0
        or position(E'\n' in v_hdr_part) > 0
      then
        v_hdr_part := '"' || replace(v_hdr_part, '"', '""') || '"';
      end if;

      if v_header = '' then
        v_header := v_hdr_part;
      else
        v_header := v_header || v_delimiter || v_hdr_part;
      end if;
    end loop;
  end if;

  -- Build rows.
  v_body := '';
  for r in
    SELECT
      export_row.transfer_id,
      export_row.payment_reference,
      export_row.payee_name,
      export_row.sort_code,
      export_row.account_number,
      export_row.account_type,
      export_row.amount,
      export_row.currency,
      export_row.pay_channel,
      export_row.rail_provider,
      export_row.rail_env,
      export_row.request_id,
      export_row.transfer_group_key,
      export_row.grouping_mode_used,
      export_row.week_ending_bucket,
      export_row.candidate_id,
      export_row.umbrella_id,
      export_row.payee_entity_kind,
      export_row.payee_entity_id,
      export_row.bank_details_hash_snapshot
    FROM pg_temp.tmp_pay_export_bank_csv_rows AS export_row
    ORDER BY export_row.row_ordinal
  loop
    v_line := '';

    foreach v_col in array v_cols loop
      v_val := null;

      if v_col = 'transfer_id' then
        v_val := r.transfer_id::text;
      elsif v_col = 'payment_reference' then
        v_val := r.payment_reference;
      elsif v_col = 'payee_name' then
        v_val := r.payee_name;
      elsif v_col = 'sort_code' then
        if v_sort_code_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
        elsif v_sort_code_format = 'HYPHENATED' then
          v_digits := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
          if length(v_digits) = 6 then
            v_val := substr(v_digits, 1, 2) || '-' || substr(v_digits, 3, 2) || '-' || substr(v_digits, 5, 2);
          else
            v_val := v_digits;
          end if;
        else
          v_val := r.sort_code;
        end if;
      elsif v_col = 'account_number' then
        if v_account_number_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.account_number, ''), '[^0-9]', '', 'g');
        else
          v_val := r.account_number;
        end if;
      elsif v_col = 'account_type' then
        v_val := r.account_type;
      elsif v_col = 'amount' then
        v_val := case v_amount_decimals
          when 0 then to_char(round(r.amount, 0), 'FM9999999990')
          when 1 then to_char(round(r.amount, 1), 'FM9999999990.0')
          when 2 then to_char(round(r.amount, 2), 'FM9999999990.00')
          when 3 then to_char(round(r.amount, 3), 'FM9999999990.000')
          when 4 then to_char(round(r.amount, 4), 'FM9999999990.0000')
          else to_char(round(r.amount, 2), 'FM9999999990.00')
        end;
      elsif v_col = 'currency' then
        v_val := r.currency;
      elsif v_col = 'pay_channel' then
        v_val := r.pay_channel;
      elsif v_col = 'rail_provider' then
        v_val := r.rail_provider;
      elsif v_col = 'rail_env' then
        v_val := r.rail_env;
      elsif v_col = 'request_id' then
        v_val := r.request_id;
      elsif v_col = 'transfer_group_key' then
        v_val := r.transfer_group_key;
      elsif v_col = 'grouping_mode_used' then
        v_val := r.grouping_mode_used;
      elsif v_col = 'week_ending_bucket' then
        v_val := case when r.week_ending_bucket is null then null else r.week_ending_bucket::text end;
      elsif v_col = 'candidate_id' then
        v_val := case when r.candidate_id is null then null else r.candidate_id::text end;
      elsif v_col = 'umbrella_id' then
        v_val := case when r.umbrella_id is null then null else r.umbrella_id::text end;
      elsif v_col = 'payee_entity_kind' then
        v_val := r.payee_entity_kind;
      elsif v_col = 'payee_entity_id' then
        v_val := case when r.payee_entity_id is null then null else r.payee_entity_id::text end;
      elsif v_col = 'bank_details_hash_snapshot' then
        v_val := r.bank_details_hash_snapshot;
      else
        v_val := null;
      end if;

      v_val := coalesce(v_val, v_empty_value);

      -- CSV escaping: quote according to configured quote mode or when field contains delimiter/quote/newline.
      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_val) > 0
        or position('"' in v_val) > 0
        or position(E'\r' in v_val) > 0
        or position(E'\n' in v_val) > 0
      then
        v_val := '"' || replace(v_val, '"', '""') || '"';
      end if;

      if v_line = '' then
        v_line := v_val;
      else
        v_line := v_line || v_delimiter || v_val;
      end if;
    end loop;

    if v_body = '' then
      v_body := v_line;
    else
      v_body := v_body || v_line_ending || v_line;
    end if;
  end loop;

  if v_include_header = true then
    v_csv := v_header || v_line_ending || coalesce(v_body, '');
  else
    v_csv := coalesce(v_body, '');
  end if;

  if v_bom = true then
    v_csv := chr(65279) || v_csv;
  end if;

  return v_csv;
end;
$function$
;

-- [REPLACES] public.pay_finance_components_sync_from_preview(p_finance_case_id uuid, p_preview_lines_json jsonb, p_actor_user_id uuid)  winner piece A21
CREATE OR REPLACE FUNCTION public.pay_finance_components_sync_from_preview(p_finance_case_id uuid, p_preview_lines_json jsonb, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_case_candidate_id uuid;
  v_case_client_id uuid;
  v_case_linked_timesheet_id uuid;
  v_case_current_pay_method text;
  v_case_type public.pay_finance_case_type_enum;
  v_case_outstanding_amount numeric(12,2) := 0;

  v_input_json jsonb := coalesce(p_preview_lines_json, '[]'::jsonb);
  v_line_json jsonb;
  v_row_seq integer := 0;

  v_source_family_key text;
  v_component_key_type text;
  v_component_key_value text;
  v_raw_key_type text;
  v_raw_key_value text;
  v_raw_classification text;
  v_raw_item_type text;
  v_raw_source_ref text;
  v_raw_expense_kind text;
  v_source_pay_method text;
  v_current_target_pay_method text;

  v_source_amount_text text;
  v_remaining_amount_text text;
  v_relevant_erni_text text;
  v_allocation_group_text text;
  v_allocation_order_text text;

  v_source_amount numeric(12,2);
  v_incoming_remaining_source_amount numeric(12,2);
  v_incoming_remaining_is_explicit boolean;
  v_relevant_erni_pct numeric;
  v_allocation_priority_group integer;
  v_allocation_priority_order integer;

  v_source_basis_json jsonb;
  v_target_basis_json jsonb;
  v_current_basis_fingerprint text;
  v_classification public.pay_finance_component_classification_enum;

  v_line_candidate_id uuid;
  v_line_client_id uuid;
  v_line_linked_timesheet_id uuid;
  v_line_classification public.pay_finance_component_classification_enum;
  v_line_source_amount numeric(12,2);
  v_line_incoming_remaining_source_amount numeric(12,2);
  v_line_allocation_priority_group integer;
  v_line_allocation_priority_order integer;
  v_line_source_basis_json jsonb;
  v_line_current_target_pay_method text;
  v_line_source_pay_method text;

  v_existing_component public.pay_finance_case_components%ROWTYPE;
  v_reopen_component public.pay_finance_case_components%ROWTYPE;
  v_component_after public.pay_finance_case_components%ROWTYPE;

  v_before_json jsonb;
  v_after_json jsonb;

  v_has_saved_resolution boolean;
  v_should_be_stale boolean;
  v_stale_reason text;
  v_consumed_amount numeric(12,2);
  v_new_remaining_source_amount numeric(12,2);
  v_created_component_id uuid;

  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_reopened_count integer := 0;
  v_closed_count integer := 0;
  v_stale_marked_count integer := 0;

  v_open_components_json jsonb := '[]'::jsonb;

  v_case_status text;
  v_case_written_off_at_utc timestamptz;
  v_case_cleared_at_utc timestamptz;
  v_case_has_protected_event boolean := false;
  v_case_is_preview_auto_clear boolean := false;
  v_case_is_protected boolean := false;
  v_protected_skip_count integer := 0;

  v_component_has_protected_event boolean := false;
  v_component_is_protected boolean := false;
  v_active_consumed_amount numeric(12,2);
  v_active_reserved_source_amount numeric(12,2) := 0;
  v_identity_consumed_amount numeric(12,2);
  v_identity_reserved_source_amount numeric(12,2);
  v_case_active_consumed_amount numeric(12,2) := 0;
  v_case_active_reserved_source_amount numeric(12,2) := 0;
  v_raw_input_component_count integer := 0;
  v_input_component_count integer := 0;
  v_aggregated_duplicate_identity_count integer := 0;
  v_open_component_remaining_total numeric(12,2) := 0;
  v_component_case_mismatch_amount numeric(12,2) := 0;
  v_effective_source_amount numeric(12,2) := 0;
  v_active_reservation_deferred_count integer := 0;

  v_accepted_resolution_json jsonb;
  v_line_accepted_resolution_json jsonb;
  v_accepted_resolution_fingerprint text;
  v_resolution_target_ratio numeric := NULL;
  v_resolution_vat_ratio numeric := NULL;
  v_resolution_inc_ratio numeric := NULL;
  v_upstream_correction_resolution_applied boolean := false;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION 'p_finance_case_id is required';
  END IF;

  IF jsonb_typeof(v_input_json) <> 'array' THEN
    RAISE EXCEPTION 'p_preview_lines_json must be a jsonb array';
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_START',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'preview_line_count', jsonb_array_length(v_input_json),
      'actor_user_id', p_actor_user_id
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  SELECT
    pa.candidate_id,
    pa.client_id,
    pa.linked_timesheet_id,
    upper(coalesce(c.pay_method, '')),
    pa.case_type,
    round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
    upper(coalesce(pa.status::text, '')),
    pa.written_off_at_utc,
    pa.cleared_at_utc
  INTO
    v_case_candidate_id,
    v_case_client_id,
    v_case_linked_timesheet_id,
    v_case_current_pay_method,
    v_case_type,
    v_case_outstanding_amount,
    v_case_status,
    v_case_written_off_at_utc,
    v_case_cleared_at_utc
  FROM public.pay_advances pa
  JOIN public.candidates c
    ON c.id = pa.candidate_id
  WHERE pa.id = p_finance_case_id
  FOR UPDATE OF pa;

  IF v_case_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Finance case % not found in public.pay_advances', p_finance_case_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_finance_case_events AS protected_case_events
    WHERE protected_case_events.finance_case_id = p_finance_case_id
      AND (
        upper(btrim(coalesce(protected_case_events.event_type, ''))) LIKE '%WRITE%OFF%'
        OR upper(btrim(coalesce(protected_case_events.event_type, ''))) IN (
          'MANUAL_ECONOMIC_OVERRIDE',
          'MANUAL_WRITE_OFF',
          'CASE_MANUAL_ECONOMIC_OVERRIDE',
          'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
        )
        OR upper(btrim(coalesce(protected_case_events.reason, ''))) IN (
          'MANUAL_ECONOMIC_OVERRIDE',
          'WRITE_OFF',
          'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
        )
      )
  )
  INTO v_case_has_protected_event;

  SELECT COALESCE((
    SELECT
      upper(btrim(coalesce(latest_case_event.event_type, ''))) = 'CLEARED'
      AND upper(btrim(coalesce(latest_case_event.reason, ''))) = 'PREVIEW_FINANCE_SYNC'
    FROM public.pay_finance_case_events AS latest_case_event
    WHERE latest_case_event.finance_case_id = p_finance_case_id
    ORDER BY latest_case_event.event_at_utc DESC, latest_case_event.id DESC
    LIMIT 1
  ), false)
  INTO v_case_is_preview_auto_clear;

  v_case_is_protected := (
    v_case_written_off_at_utc IS NOT NULL
    OR (
      v_case_cleared_at_utc IS NOT NULL
      AND NOT (
        coalesce(v_case_is_preview_auto_clear, false)
        AND jsonb_array_length(v_input_json) = 0
        AND coalesce(v_case_status, '') = 'PAID_OFF'
        AND round(coalesce(v_case_outstanding_amount, 0), 2) = 0
      )
    )
    OR coalesce(v_case_status, '') NOT IN ('ACTIVE', 'PAUSED', 'PAID_OFF')
    OR coalesce(v_case_has_protected_event, false)
  );

  IF v_case_is_protected THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      NULL,
      'SYNC_SKIPPED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      jsonb_build_object(
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event,
        'is_preview_auto_clear', v_case_is_preview_auto_clear
      ),
      jsonb_build_object(
        'sync_skipped', true,
        'reason', 'PROTECTED_FINANCE_CASE'
      ),
      'COMPONENT_SYNC_SKIPPED_PROTECTED_CASE',
      'Skipped component sync because the finance case is written-off, cleared, closed, manually resolved, or already restructured.'
    );

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_SKIPPED_PROTECTED_CASE',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event,
        'is_preview_auto_clear', v_case_is_preview_auto_clear
      ),
      'pay_finance_components',
      p_finance_case_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'skipped', true,
      'skip_reason', 'PROTECTED_FINANCE_CASE',
      'inserted_count', 0,
      'updated_count', 0,
      'reopened_count', 0,
      'closed_count', 0,
      'stale_marked_count', 0,
      'open_components', (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', pfc.id::text,
              'finance_case_id', pfc.finance_case_id::text,
              'candidate_id', pfc.candidate_id::text,
              'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
              'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
              'source_family_key', pfc.source_family_key,
              'component_key_type', pfc.component_key_type,
              'component_key_value', pfc.component_key_value,
              'classification', pfc.classification::text,
              'source_pay_method', pfc.source_pay_method,
              'source_amount', round(coalesce(pfc.source_amount, 0), 2),
              'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
              'saved_target_pay_method', pfc.saved_target_pay_method,
              'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
              'is_resolution_stale', pfc.is_resolution_stale,
              'stale_reason', pfc.stale_reason,
              'allocation_priority_group', pfc.allocation_priority_group,
              'allocation_priority_order', pfc.allocation_priority_order,
              'created_at_utc', pfc.created_at_utc,
              'updated_at_utc', pfc.updated_at_utc
            )
            ORDER BY
              pfc.source_family_key,
              pfc.allocation_priority_group,
              pfc.allocation_priority_order,
              pfc.component_key_type,
              pfc.component_key_value
          ),
          '[]'::jsonb
        )
        FROM public.pay_finance_case_components AS pfc
        WHERE pfc.finance_case_id = p_finance_case_id
          AND pfc.closed_at_utc IS NULL
      )
    );
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_sync_input (
    row_seq integer NOT NULL,
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    classification public.pay_finance_component_classification_enum NOT NULL,
    candidate_id uuid NOT NULL,
    client_id uuid NULL,
    linked_timesheet_id uuid NULL,
    source_pay_method text NOT NULL,
    current_target_pay_method text NULL,
    source_basis_json jsonb NOT NULL,
    target_basis_json jsonb NULL,
    accepted_resolution_json jsonb NULL,
    source_amount numeric(12,2) NOT NULL,
    incoming_remaining_source_amount numeric(12,2) NULL,
    incoming_remaining_is_explicit boolean NOT NULL,
    relevant_erni_pct numeric NULL,
    allocation_priority_group integer NOT NULL,
    allocation_priority_order integer NOT NULL,
    current_basis_fingerprint text NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_input;

  FOR v_line_json IN
    SELECT x.value
    FROM jsonb_array_elements(v_input_json) AS x(value)
  LOOP
    v_row_seq := v_row_seq + 1;

    IF v_line_json IS NULL OR jsonb_typeof(v_line_json) <> 'object' THEN
      RAISE EXCEPTION 'Each preview line must be a jsonb object (row %)', v_row_seq;
    END IF;

    v_raw_key_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'component_key_type'), ''),
        nullif(btrim(v_line_json->>'frozen_component_key_type'), ''),
        nullif(btrim(v_line_json->>'key_type'), ''),
        ''
      )
    );

    v_raw_key_value := coalesce(
      nullif(btrim(v_line_json->>'component_key_value'), ''),
      nullif(btrim(v_line_json->>'frozen_component_key_value'), ''),
      nullif(btrim(v_line_json->>'key_value'), ''),
      ''
    );

    v_raw_classification := upper(
      coalesce(
        nullif(btrim(v_line_json->>'classification'), ''),
        nullif(btrim(v_line_json->>'component_classification'), ''),
        ''
      )
    );

    v_raw_item_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'item_type'), ''),
        nullif(btrim(v_line_json->>'line_type'), ''),
        ''
      )
    );

    v_raw_source_ref := upper(coalesce(nullif(btrim(v_line_json->>'source_ref'), ''), ''));
    v_raw_expense_kind := upper(
      coalesce(
        nullif(btrim(v_line_json->>'expense_kind'), ''),
        nullif(btrim(v_line_json->>'expense_code'), ''),
        nullif(btrim(v_line_json->>'expense_type'), ''),
        ''
      )
    );

    v_component_key_type := NULL;
    v_component_key_value := NULL;

    IF v_raw_key_type <> '' THEN
      v_component_key_type := v_raw_key_type;
    ELSIF v_raw_item_type = 'SEGMENT_DELTA' THEN
      IF coalesce(nullif(btrim(v_line_json->>'work_date'), ''), nullif(btrim(v_line_json->>'date'), '')) ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_component_key_type := 'TS_DAY';
      ELSE
        v_component_key_type := 'TS_TOTAL';
      END IF;
    ELSIF v_raw_item_type = 'ADDITIONAL_DELTA'
       OR nullif(btrim(v_line_json->>'additional_code'), '') IS NOT NULL THEN
      v_component_key_type := 'ADDITIONAL_CODE';
    ELSIF v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA', 'EXPENSE_DELTA')
       OR v_raw_expense_kind <> '' THEN
      v_component_key_type := 'EXPENSE_CODE';
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
      IF v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
        v_component_key_type := 'TS_TOTAL';
      ELSE
        v_component_key_type := 'EXPENSE_CODE';
      END IF;
    ELSE
      v_component_key_type := 'CASE_TOTAL';
    END IF;

    IF v_raw_key_value <> '' THEN
      v_component_key_value := v_raw_key_value;
    ELSIF v_component_key_type = 'TS_DAY' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'work_date'), ''),
        nullif(btrim(v_line_json->>'date'), ''),
        'UNKNOWN_DAY'
      );
    ELSIF v_component_key_type = 'TS_TOTAL' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'segment_id'), ''),
        CASE
          WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NULL THEN 'TOTAL'
          ELSE coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        END
      );
    ELSIF v_component_key_type = 'ADDITIONAL_CODE' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'additional_code'), ''),
        nullif(btrim(v_line_json->>'source_ref'), ''),
        nullif(btrim(v_line_json->>'code'), ''),
        'TOTAL'
      );
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'adjustment_code'), ''),
          nullif(btrim(v_line_json->>'adjustment_id'), ''),
          nullif(btrim(v_line_json->>'source_ref'), ''),
          'ADJUSTMENT'
        );
      ELSE
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'expense_code'), ''),
          nullif(btrim(v_line_json->>'expense_kind'), ''),
          nullif(btrim(v_line_json->>'expense_type'), ''),
          nullif(btrim(v_line_json->>'item_type'), ''),
          'EXPENSE'
        );
      END IF;
    ELSE
      v_component_key_value := 'TOTAL';
    END IF;

    IF v_raw_classification IN ('TAXABLE_CHANNEL_SENSITIVE', 'REIMBURSEMENT_GROSS_FIXED', 'NET_PAY_FIXED_RECOVERY') THEN
      v_classification := v_raw_classification::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type IN ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'CASE_TOTAL') THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA'
       OR v_raw_source_ref LIKE 'ADJ:%'
       OR v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF upper(v_component_key_value) IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_expense_kind IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA')
         OR v_raw_source_ref LIKE 'MILEAGE:%'
         OR v_raw_source_ref LIKE 'TRAVEL:%'
         OR v_raw_source_ref LIKE 'ACCOMMODATION:%'
         OR v_raw_source_ref LIKE 'OTHER:%'
         OR v_raw_source_ref LIKE 'EXPENSE:%'
      THEN
        v_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
      ELSE
        v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
      END IF;
    ELSE
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    END IF;

    v_source_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'source_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_current_target_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'current_target_pay_method'), ''),
        nullif(btrim(v_line_json->>'target_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_source_amount_text := nullif(btrim(v_line_json->>'source_amount'), '');
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount_ex_vat'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      RAISE EXCEPTION 'Preview line % is missing source_amount/amount/amount_ex_vat', v_row_seq;
    END IF;
    IF v_source_amount_text !~ '^-?\d+(\.\d+)?$' THEN
      RAISE EXCEPTION 'Preview line % has invalid source amount: %', v_row_seq, v_source_amount_text;
    END IF;
    v_source_amount := round(abs(v_source_amount_text::numeric), 2)::numeric(12,2);

    v_remaining_amount_text := nullif(btrim(v_line_json->>'remaining_source_amount'), '');
    v_incoming_remaining_is_explicit := v_remaining_amount_text IS NOT NULL;
    IF v_incoming_remaining_is_explicit THEN
      IF v_remaining_amount_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid remaining_source_amount: %', v_row_seq, v_remaining_amount_text;
      END IF;
      v_incoming_remaining_source_amount := round(abs(v_remaining_amount_text::numeric), 2)::numeric(12,2);
    ELSE
      v_incoming_remaining_source_amount := NULL;
    END IF;

    v_relevant_erni_text := nullif(
      btrim(
        coalesce(
          v_line_json->>'relevant_erni_pct',
          v_line_json->>'erni_pct'
        )
      ),
      ''
    );
    IF v_relevant_erni_text IS NOT NULL THEN
      IF v_relevant_erni_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid relevant_erni_pct: %', v_row_seq, v_relevant_erni_text;
      END IF;
      v_relevant_erni_pct := round(v_relevant_erni_text::numeric, 6);
    ELSE
      v_relevant_erni_pct := NULL;
    END IF;

    v_allocation_group_text := nullif(btrim(v_line_json->>'allocation_priority_group'), '');
    IF v_allocation_group_text IS NOT NULL THEN
      IF v_allocation_group_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_group: %', v_row_seq, v_allocation_group_text;
      END IF;
      v_allocation_priority_group := v_allocation_group_text::integer;
    ELSE
      v_allocation_priority_group := CASE
        WHEN v_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN 0
        ELSE 1
      END;
    END IF;

    v_allocation_order_text := nullif(btrim(v_line_json->>'allocation_priority_order'), '');
    IF v_allocation_order_text IS NOT NULL THEN
      IF v_allocation_order_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_order: %', v_row_seq, v_allocation_order_text;
      END IF;
      v_allocation_priority_order := v_allocation_order_text::integer;
    ELSE
      v_allocation_priority_order := v_row_seq;
    END IF;

    IF v_line_json ? 'source_basis_json'
       AND jsonb_typeof(v_line_json->'source_basis_json') IN ('object', 'array') THEN
      v_source_basis_json := v_line_json->'source_basis_json';
    ELSE
      v_source_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'linked_timesheet_id', coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text),
          'work_date', nullif(btrim(v_line_json->>'work_date'), ''),
          'date', nullif(btrim(v_line_json->>'date'), ''),
          'segment_id', nullif(btrim(v_line_json->>'segment_id'), ''),
          'item_type', nullif(btrim(v_line_json->>'item_type'), ''),
          'line_type', nullif(btrim(v_line_json->>'line_type'), ''),
          'source_ref', nullif(btrim(v_line_json->>'source_ref'), ''),
          'additional_code', nullif(btrim(v_line_json->>'additional_code'), ''),
          'expense_code', nullif(btrim(v_line_json->>'expense_code'), ''),
          'expense_kind', nullif(btrim(v_line_json->>'expense_kind'), ''),
          'adjustment_code', nullif(btrim(v_line_json->>'adjustment_code'), ''),
          'rate_code', nullif(btrim(v_line_json->>'rate_code'), ''),
          'units', nullif(btrim(v_line_json->>'units'), ''),
          'hours', nullif(btrim(v_line_json->>'hours'), ''),
          'rate', nullif(btrim(v_line_json->>'rate'), '')
        )
      );
    END IF;

    IF v_line_json ? 'target_basis_json'
       AND jsonb_typeof(v_line_json->'target_basis_json') IN ('object', 'array') THEN
      v_target_basis_json := v_line_json->'target_basis_json';
    ELSE
      v_target_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'current_target_pay_method', v_current_target_pay_method,
          'relevant_erni_pct', v_relevant_erni_pct
        )
      );
    END IF;

    v_line_accepted_resolution_json := NULL;
    IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_resolution_json';
    ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
    ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
    END IF;

    v_source_family_key := coalesce(
      nullif(btrim(v_line_json->>'source_family_key'), ''),
      CASE
        WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NOT NULL
          THEN 'timesheet:' || coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        ELSE 'case:' || p_finance_case_id::text
      END
    );

    v_current_basis_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => v_source_family_key,
      p_component_key_type        => v_component_key_type,
      p_component_key_value       => v_component_key_value,
      p_classification            => v_classification,
      p_source_pay_method         => v_source_pay_method,
      p_current_target_pay_method => v_current_target_pay_method,
      p_source_basis_json         => v_source_basis_json,
      p_source_amount             => v_source_amount,
      p_relevant_erni_pct         => v_relevant_erni_pct,
      p_target_basis_json         => v_target_basis_json
    );

    v_line_candidate_id := coalesce(
      CASE
        WHEN nullif(btrim(v_line_json->>'candidate_id'), '') IS NULL THEN NULL
        ELSE (nullif(btrim(v_line_json->>'candidate_id'), ''))::uuid
      END,
      v_case_candidate_id
    );

    v_line_client_id := CASE
      WHEN nullif(btrim(v_line_json->>'client_id'), '') IS NULL THEN v_case_client_id
      ELSE (nullif(btrim(v_line_json->>'client_id'), ''))::uuid
    END;

    v_line_linked_timesheet_id := CASE
      WHEN nullif(btrim(v_line_json->>'linked_timesheet_id'), '') IS NULL THEN v_case_linked_timesheet_id
      ELSE (nullif(btrim(v_line_json->>'linked_timesheet_id'), ''))::uuid
    END;

    IF v_line_linked_timesheet_id IS NOT NULL OR v_source_family_key LIKE 'timesheet:%' THEN
      IF COALESCE(v_raw_key_type, '') = '' OR COALESCE(v_raw_key_value, '') = '' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_ECONOMIC_KEY_REQUIRED'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_ECONOMIC_KEY_REQUIRED',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'source_family_key', v_source_family_key,
                  'raw_component_key_type', v_raw_key_type,
                  'raw_component_key_value', v_raw_key_value,
                  'message', 'Linked timesheet finance components must carry an explicit canonical component_key_type/component_key_value.'
                )::text;
      END IF;

      IF v_component_key_type IS NULL
         OR v_component_key_value IS NULL
         OR v_component_key_type = 'CASE_TOTAL'
         OR v_component_key_value IN ('UNKNOWN_DAY', '') THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_INVALID_ECONOMIC_KEY'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_INVALID_ECONOMIC_KEY',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'source_family_key', v_source_family_key,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'Linked timesheet finance components must not fall back to CASE_TOTAL/TOTAL or an unknown bucket.'
                )::text;
      END IF;

      IF v_component_key_type = 'TS_DAY' AND v_component_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_TS_DAY_KEY_NOT_DATE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_TS_DAY_KEY_NOT_DATE',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'TS_DAY finance components must be keyed by YYYY-MM-DD work date, not by segment id or stable id.'
                )::text;
      END IF;

      IF v_component_key_type = 'TS_TOTAL' AND v_component_key_value IS DISTINCT FROM 'TOTAL' THEN
        RAISE EXCEPTION 'COMPONENT_SYNC_TS_TOTAL_KEY_NOT_TOTAL'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'COMPONENT_SYNC_TS_TOTAL_KEY_NOT_TOTAL',
                  'finance_case_id', p_finance_case_id::text,
                  'row_seq', v_row_seq,
                  'linked_timesheet_id', CASE WHEN v_line_linked_timesheet_id IS NULL THEN NULL ELSE v_line_linked_timesheet_id::text END,
                  'component_key_type', v_component_key_type,
                  'component_key_value', v_component_key_value,
                  'message', 'TS_TOTAL finance components must use TOTAL as the economic key value.'
                )::text;
      END IF;
    END IF;

    INSERT INTO pg_temp.tmp_pay_finance_component_sync_input (
      row_seq,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_pay_method,
      current_target_pay_method,
      source_basis_json,
      target_basis_json,
      accepted_resolution_json,
      source_amount,
      incoming_remaining_source_amount,
      incoming_remaining_is_explicit,
      relevant_erni_pct,
      allocation_priority_group,
      allocation_priority_order,
      current_basis_fingerprint
    )
    VALUES (
      v_row_seq,
      v_source_family_key,
      v_component_key_type,
      v_component_key_value,
      v_classification,
      v_line_candidate_id,
      v_line_client_id,
      v_line_linked_timesheet_id,
      v_source_pay_method,
      v_current_target_pay_method,
      v_source_basis_json,
      v_target_basis_json,
      v_line_accepted_resolution_json,
      v_source_amount,
      v_incoming_remaining_source_amount,
      v_incoming_remaining_is_explicit,
      v_relevant_erni_pct,
      v_allocation_priority_group,
      v_allocation_priority_order,
      v_current_basis_fingerprint
    );
  END LOOP;

  /* Policy X economic identity is source_family_key + component_key_type +
     component_key_value.  Preview production may legitimately emit several
     physical rows for one economic identity (for example DAY and NIGHT work
     buckets on the same TS_DAY date).  Normalise those physical rows into one
     component before settlement/reservation reconciliation.  Keeping only the
     last row would understate the component and make the case/component parity
     guard reject an otherwise valid case. */
  SELECT COUNT(*)::integer
  INTO v_raw_input_component_count
  FROM pg_temp.tmp_pay_finance_component_sync_input AS raw_input_count_rows;

  SELECT COUNT(*)::integer
  INTO v_aggregated_duplicate_identity_count
  FROM (
    SELECT
      duplicate_identity.source_family_key,
      duplicate_identity.component_key_type,
      duplicate_identity.component_key_value
    FROM pg_temp.tmp_pay_finance_component_sync_input AS duplicate_identity
    GROUP BY
      duplicate_identity.source_family_key,
      duplicate_identity.component_key_type,
      duplicate_identity.component_key_value
    HAVING COUNT(*) > 1
  ) AS duplicate_identity_count_rows;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_finance_component_sync_input AS conflicting_identity
    GROUP BY
      conflicting_identity.source_family_key,
      conflicting_identity.component_key_type,
      conflicting_identity.component_key_value
    HAVING COUNT(*) > 1
       AND (
         COUNT(DISTINCT conflicting_identity.candidate_id) > 1
         OR COUNT(DISTINCT (conflicting_identity.client_id IS NULL, conflicting_identity.client_id)) > 1
         OR COUNT(DISTINCT (conflicting_identity.linked_timesheet_id IS NULL, conflicting_identity.linked_timesheet_id)) > 1
         OR COUNT(DISTINCT conflicting_identity.classification::text) > 1
         OR COUNT(DISTINCT upper(btrim(conflicting_identity.source_pay_method))) > 1
         OR COUNT(DISTINCT (conflicting_identity.current_target_pay_method IS NULL, upper(btrim(conflicting_identity.current_target_pay_method)))) > 1
         OR COUNT(DISTINCT (conflicting_identity.relevant_erni_pct IS NULL, conflicting_identity.relevant_erni_pct)) > 1
         OR BOOL_OR(conflicting_identity.incoming_remaining_is_explicit)
              IS DISTINCT FROM BOOL_AND(conflicting_identity.incoming_remaining_is_explicit)
         OR (
           COUNT(*) FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) > 0
           AND COUNT(*) FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) < COUNT(*)
         )
         OR COUNT(DISTINCT conflicting_identity.accepted_resolution_json)
              FILTER (WHERE conflicting_identity.accepted_resolution_json IS NOT NULL) > 1
       )
  ) THEN
    RAISE EXCEPTION 'PAY_FINANCE_COMPONENTS_DUPLICATE_IDENTITY_CONFLICT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_FINANCE_COMPONENTS_DUPLICATE_IDENTITY_CONFLICT',
              'finance_case_id', p_finance_case_id::text,
              'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
              'duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0),
              'message', 'Rows sharing one Policy X economic identity must agree on candidate, client, linked Timesheet, classification, route, ERNI basis, remaining-amount mode, and accepted resolution.'
            )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_sync_normalized
    (LIKE pg_temp.tmp_pay_finance_component_sync_input INCLUDING ALL)
    ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_normalized;

  INSERT INTO pg_temp.tmp_pay_finance_component_sync_normalized (
    row_seq,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_pay_method,
    current_target_pay_method,
    source_basis_json,
    target_basis_json,
    accepted_resolution_json,
    source_amount,
    incoming_remaining_source_amount,
    incoming_remaining_is_explicit,
    relevant_erni_pct,
    allocation_priority_group,
    allocation_priority_order,
    current_basis_fingerprint
  )
  WITH grouped_input AS (
    SELECT
      MIN(input_row.row_seq)::integer AS row_seq,
      input_row.source_family_key,
      input_row.component_key_type,
      input_row.component_key_value,
      (ARRAY_AGG(input_row.classification ORDER BY input_row.row_seq))[1] AS classification,
      (ARRAY_AGG(input_row.candidate_id ORDER BY input_row.row_seq))[1] AS candidate_id,
      (ARRAY_AGG(input_row.client_id ORDER BY input_row.row_seq))[1] AS client_id,
      (ARRAY_AGG(input_row.linked_timesheet_id ORDER BY input_row.row_seq))[1] AS linked_timesheet_id,
      (ARRAY_AGG(input_row.source_pay_method ORDER BY input_row.row_seq))[1] AS source_pay_method,
      (ARRAY_AGG(input_row.current_target_pay_method ORDER BY input_row.row_seq))[1] AS current_target_pay_method,
      (ARRAY_AGG(input_row.source_basis_json ORDER BY input_row.row_seq))[1] AS first_source_basis_json,
      (ARRAY_AGG(input_row.target_basis_json ORDER BY input_row.row_seq))[1] AS first_target_basis_json,
      (ARRAY_AGG(input_row.accepted_resolution_json ORDER BY input_row.row_seq))[1] AS accepted_resolution_json,
      ROUND(SUM(input_row.source_amount), 2)::numeric(12,2) AS source_amount,
      CASE
        WHEN BOOL_AND(input_row.incoming_remaining_is_explicit)
          THEN ROUND(SUM(COALESCE(input_row.incoming_remaining_source_amount, 0)), 2)::numeric(12,2)
        ELSE NULL::numeric(12,2)
      END AS incoming_remaining_source_amount,
      BOOL_AND(input_row.incoming_remaining_is_explicit) AS incoming_remaining_is_explicit,
      (ARRAY_AGG(input_row.relevant_erni_pct ORDER BY input_row.row_seq))[1] AS relevant_erni_pct,
      MIN(input_row.allocation_priority_group)::integer AS allocation_priority_group,
      MIN(input_row.allocation_priority_order)::integer AS allocation_priority_order,
      COUNT(*)::integer AS physical_row_count,
      COUNT(DISTINCT COALESCE(input_row.target_basis_json, 'null'::jsonb))::integer AS target_basis_distinct_count,
      JSONB_AGG(
        jsonb_build_object(
          'source_amount', input_row.source_amount,
          'source_basis_json', input_row.source_basis_json,
          'target_basis_json', input_row.target_basis_json
        )
        ORDER BY input_row.source_basis_json::text, input_row.target_basis_json::text, input_row.source_amount, input_row.row_seq
      ) AS physical_basis_rows,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_units', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_units_count,
      ROUND(SUM(
        CASE
          WHEN jsonb_typeof(input_row.source_basis_json) = 'object'
           AND COALESCE(input_row.source_basis_json->>'source_units', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            THEN (input_row.source_basis_json->>'source_units')::numeric
          ELSE 0::numeric
        END
      ), 6) AS source_units_sum,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_rate_count,
      COUNT(DISTINCT ROUND((input_row.source_basis_json->>'source_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_rate_distinct_count,
      MAX(ROUND((input_row.source_basis_json->>'source_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      ) AS common_source_rate,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_charge_rate_count,
      COUNT(DISTINCT ROUND((input_row.source_basis_json->>'source_charge_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      )::integer AS source_charge_rate_distinct_count,
      MAX(ROUND((input_row.source_basis_json->>'source_charge_rate')::numeric, 6)) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND COALESCE(input_row.source_basis_json->>'source_charge_rate', '') ~ '^-?[0-9]+([.][0-9]+)?$'
      ) AS common_source_charge_rate,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      )::integer AS bucket_code_count,
      COUNT(DISTINCT NULLIF(upper(btrim(input_row.source_basis_json->>'bucket_code')), '')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      )::integer AS bucket_code_distinct_count,
      MAX(NULLIF(upper(btrim(input_row.source_basis_json->>'bucket_code')), '')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND NULLIF(btrim(COALESCE(input_row.source_basis_json->>'bucket_code', '')), '') IS NOT NULL
      ) AS common_bucket_code,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      )::integer AS umbrella_vat_count,
      COUNT(DISTINCT lower(input_row.source_basis_json->>'umbrella_vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      )::integer AS umbrella_vat_distinct_count,
      MAX(lower(input_row.source_basis_json->>'umbrella_vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
      ) AS common_umbrella_vat_chargeable,
      COUNT(*) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      )::integer AS vat_chargeable_count,
      COUNT(DISTINCT lower(input_row.source_basis_json->>'vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      )::integer AS vat_chargeable_distinct_count,
      MAX(lower(input_row.source_basis_json->>'vat_chargeable')) FILTER (
        WHERE jsonb_typeof(input_row.source_basis_json) = 'object'
          AND lower(COALESCE(input_row.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
      ) AS common_vat_chargeable
    FROM pg_temp.tmp_pay_finance_component_sync_input AS input_row
    GROUP BY
      input_row.source_family_key,
      input_row.component_key_type,
      input_row.component_key_value
  ), normalized_basis AS (
    SELECT
      grouped_input.*,
      CASE
        WHEN grouped_input.physical_row_count = 1
          THEN grouped_input.first_source_basis_json
        ELSE jsonb_strip_nulls(
          jsonb_build_object(
            'aggregation_mode', 'POLICY_X_ECONOMIC_IDENTITY',
            'source_family_key', grouped_input.source_family_key,
            'component_key_type', grouped_input.component_key_type,
            'component_key_value', grouped_input.component_key_value,
            'candidate_id', grouped_input.candidate_id::text,
            'client_id', CASE WHEN grouped_input.client_id IS NULL THEN NULL ELSE grouped_input.client_id::text END,
            'linked_timesheet_id', CASE WHEN grouped_input.linked_timesheet_id IS NULL THEN NULL ELSE grouped_input.linked_timesheet_id::text END
          )
          || jsonb_build_object(
            'source_pay_method', grouped_input.source_pay_method,
            'current_target_pay_method', grouped_input.current_target_pay_method,
            'source_amount', grouped_input.source_amount,
            'work_date', CASE WHEN grouped_input.component_key_type = 'TS_DAY' THEN grouped_input.component_key_value ELSE NULL END,
            'physical_row_count', grouped_input.physical_row_count,
            'source_basis_rows', grouped_input.physical_basis_rows
          )
          || jsonb_build_object(
            'source_units', CASE
              WHEN grouped_input.source_units_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_distinct_count = 1
                THEN grouped_input.source_units_sum
              ELSE NULL
            END,
            'source_rate', CASE
              WHEN grouped_input.source_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_rate_distinct_count = 1 THEN grouped_input.common_source_rate
              ELSE NULL
            END,
            'source_charge_rate', CASE
              WHEN grouped_input.source_charge_rate_count = grouped_input.physical_row_count
               AND grouped_input.source_charge_rate_distinct_count = 1 THEN grouped_input.common_source_charge_rate
              ELSE NULL
            END,
            'bucket_code', CASE
              WHEN grouped_input.bucket_code_count = grouped_input.physical_row_count
               AND grouped_input.bucket_code_distinct_count = 1 THEN grouped_input.common_bucket_code
              ELSE NULL
            END,
            'umbrella_vat_chargeable', CASE
              WHEN grouped_input.umbrella_vat_count = grouped_input.physical_row_count
               AND grouped_input.umbrella_vat_distinct_count = 1 THEN grouped_input.common_umbrella_vat_chargeable::boolean
              ELSE NULL
            END,
            'vat_chargeable', CASE
              WHEN grouped_input.vat_chargeable_count = grouped_input.physical_row_count
               AND grouped_input.vat_chargeable_distinct_count = 1 THEN grouped_input.common_vat_chargeable::boolean
              ELSE NULL
            END
          )
        )
      END AS normalized_source_basis_json,
      CASE
        WHEN grouped_input.physical_row_count = 1
          THEN grouped_input.first_target_basis_json
        WHEN grouped_input.target_basis_distinct_count = 1
          THEN grouped_input.first_target_basis_json
        ELSE jsonb_strip_nulls(
          jsonb_build_object(
            'aggregation_mode', 'POLICY_X_ECONOMIC_IDENTITY',
            'current_target_pay_method', grouped_input.current_target_pay_method,
            'relevant_erni_pct', grouped_input.relevant_erni_pct,
            'physical_row_count', grouped_input.physical_row_count,
            'target_basis_rows', grouped_input.physical_basis_rows
          )
        )
      END AS normalized_target_basis_json
    FROM grouped_input
  )
  SELECT
    normalized_basis.row_seq,
    normalized_basis.source_family_key,
    normalized_basis.component_key_type,
    normalized_basis.component_key_value,
    normalized_basis.classification,
    normalized_basis.candidate_id,
    normalized_basis.client_id,
    normalized_basis.linked_timesheet_id,
    normalized_basis.source_pay_method,
    normalized_basis.current_target_pay_method,
    normalized_basis.normalized_source_basis_json,
    normalized_basis.normalized_target_basis_json,
    normalized_basis.accepted_resolution_json,
    normalized_basis.source_amount,
    normalized_basis.incoming_remaining_source_amount,
    normalized_basis.incoming_remaining_is_explicit,
    normalized_basis.relevant_erni_pct,
    normalized_basis.allocation_priority_group,
    normalized_basis.allocation_priority_order,
    public.pay_finance_component_fingerprint(
      p_source_family_key => normalized_basis.source_family_key,
      p_component_key_type => normalized_basis.component_key_type,
      p_component_key_value => normalized_basis.component_key_value,
      p_classification => normalized_basis.classification,
      p_source_pay_method => normalized_basis.source_pay_method,
      p_current_target_pay_method => normalized_basis.current_target_pay_method,
      p_source_basis_json => normalized_basis.normalized_source_basis_json,
      p_source_amount => normalized_basis.source_amount,
      p_relevant_erni_pct => normalized_basis.relevant_erni_pct,
      p_target_basis_json => normalized_basis.normalized_target_basis_json
    ) AS current_basis_fingerprint
  FROM normalized_basis;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_input;

  INSERT INTO pg_temp.tmp_pay_finance_component_sync_input
  SELECT normalized_input.*
  FROM pg_temp.tmp_pay_finance_component_sync_normalized AS normalized_input
  ORDER BY normalized_input.row_seq;

  SELECT COUNT(*)::integer
  INTO v_input_component_count
  FROM pg_temp.tmp_pay_finance_component_sync_input AS normalized_input_count_rows;

  /* Build the case-scoped frozen item/reservation set once using the existing
     finance_case_id, source_ref and pay_batch_item_id indexes.  All settlement
     and reservation reconciliation below joins this bounded set rather than
     repeatedly scanning unrelated historical batch items. */
  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_case_item_scope (
    pay_batch_item_id uuid NOT NULL PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_case_item_scope;

  INSERT INTO pg_temp.tmp_pay_finance_case_item_scope (pay_batch_item_id)
  SELECT scoped_item.id
  FROM public.pay_batch_items AS scoped_item
  WHERE scoped_item.finance_case_id = p_finance_case_id
     OR scoped_item.source_ref IN (
       'advance:' || p_finance_case_id::text,
       'ADVANCE:' || p_finance_case_id::text
     )
  ON CONFLICT (pay_batch_item_id) DO NOTHING;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_case_reservation_scope (
    reservation_id uuid NOT NULL PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_case_reservation_scope;

  INSERT INTO pg_temp.tmp_pay_finance_case_reservation_scope (reservation_id)
  SELECT scoped_reservation.id
  FROM public.pay_advance_reservations AS scoped_reservation
  WHERE scoped_reservation.finance_case_id = p_finance_case_id
  ON CONFLICT (reservation_id) DO NOTHING;

  INSERT INTO pg_temp.tmp_pay_finance_case_item_scope (pay_batch_item_id)
  SELECT scoped_reservation.pay_batch_item_id
  FROM public.pay_advance_reservations AS scoped_reservation
  JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS scoped_reservation_id
    ON scoped_reservation_id.reservation_id = scoped_reservation.id
  WHERE scoped_reservation.pay_batch_item_id IS NOT NULL
  ON CONFLICT (pay_batch_item_id) DO NOTHING;

  INSERT INTO pg_temp.tmp_pay_finance_case_reservation_scope (reservation_id)
  SELECT scoped_reservation.id
  FROM public.pay_advance_reservations AS scoped_reservation
  JOIN pg_temp.tmp_pay_finance_case_item_scope AS scoped_item_id
    ON scoped_item_id.pay_batch_item_id = scoped_reservation.pay_batch_item_id
  ON CONFLICT (reservation_id) DO NOTHING;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id uuid NOT NULL PRIMARY KEY,
    active_consumed_source_amount numeric(12,2) NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_active_recovered;

  INSERT INTO pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id,
    active_consumed_source_amount
  )
  SELECT
    settled_component_amounts.finance_component_id,
    round(sum(settled_component_amounts.component_source_amount), 2)::numeric(12,2) AS active_consumed_source_amount
  FROM (
    SELECT
      coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) AS finance_component_id,
      abs(coalesce(
        public.pay_advance_reservations.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id),
        public.pay_batch_items.frozen_source_amount,
        public.pay_batch_items.amount_ex_vat,
        public.pay_batch_items.amount_inc_vat,
        public.pay_advance_reservations.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_batch_items
    JOIN pg_temp.tmp_pay_finance_case_item_scope AS settled_component_scope
      ON settled_component_scope.pay_batch_item_id = public.pay_batch_items.id
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    JOIN public.pay_batches
      ON public.pay_batches.id = public.pay_batch_candidates.pay_batch_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations
      ON public.pay_advance_reservations.pay_batch_item_id = public.pay_batch_items.id
    WHERE coalesce(public.pay_batch_items.is_voided, false) = false
      AND coalesce(public.pay_advance_reservations.finance_case_id, public.pay_batch_items.finance_case_id) = p_finance_case_id
      AND coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) IS NOT NULL
      AND (
        v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(public.pay_batch_items.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
      AND (
        upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
        OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
        OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_advance_reservations.status, ''))) = 'SETTLED'
        OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
      )
  ) AS settled_component_amounts
  WHERE settled_component_amounts.finance_component_id IS NOT NULL
    AND round(coalesce(settled_component_amounts.component_source_amount, 0), 2) > 0
  GROUP BY settled_component_amounts.finance_component_id;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_active_reserved (
    finance_component_id uuid NOT NULL PRIMARY KEY,
    active_reserved_source_amount numeric(12,2) NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_active_reserved;

  INSERT INTO pg_temp.tmp_pay_finance_component_active_reserved (
    finance_component_id,
    active_reserved_source_amount
  )
  SELECT
    active_component_amounts.finance_component_id,
    round(sum(active_component_amounts.component_source_amount), 2)::numeric(12,2) AS active_reserved_source_amount
  FROM (
    SELECT
      coalesce(active_reservation.finance_component_id, active_item.finance_component_id) AS finance_component_id,
      abs(coalesce(
        active_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(active_item.id),
        active_item.frozen_source_amount,
        active_item.amount_ex_vat,
        active_item.amount_inc_vat,
        active_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_advance_reservations AS active_reservation
    JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS active_reservation_scope
      ON active_reservation_scope.reservation_id = active_reservation.id
    LEFT JOIN public.pay_batch_items AS active_item
      ON active_item.id = active_reservation.pay_batch_item_id
    WHERE coalesce(active_reservation.finance_case_id, active_item.finance_case_id) = p_finance_case_id
      AND coalesce(active_reservation.finance_component_id, active_item.finance_component_id) IS NOT NULL
      AND (
        active_item.id IS NULL
        OR v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(active_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND (active_item.id IS NULL OR coalesce(active_item.is_voided, false) = false)
      AND active_reservation.settled_at_utc IS NULL
      AND active_reservation.released_at_utc IS NULL
      AND upper(btrim(coalesce(active_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS active_corrections
        WHERE active_corrections.pay_batch_item_id = active_item.id
          AND active_corrections.status = 'APPLIED'
          AND active_corrections.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ) AS active_component_amounts
  WHERE active_component_amounts.finance_component_id IS NOT NULL
    AND round(coalesce(active_component_amounts.component_source_amount, 0), 2) > 0
  GROUP BY active_component_amounts.finance_component_id;

  /* v_input_component_count was established after Policy X identity normalisation. */

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_identity_recovered (
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    active_consumed_source_amount numeric(12,2) NOT NULL,
    PRIMARY KEY (source_family_key, component_key_type, component_key_value)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_identity_recovered;

  INSERT INTO pg_temp.tmp_pay_finance_component_identity_recovered (
    source_family_key,
    component_key_type,
    component_key_value,
    active_consumed_source_amount
  )
  SELECT
    normalized_settled_identity.source_family_key,
    normalized_settled_identity.component_key_type,
    normalized_settled_identity.component_key_value,
    round(sum(normalized_settled_identity.component_source_amount), 2)::numeric(12,2)
  FROM (
    SELECT
      coalesce(
        settled_identity_component.source_family_key,
        nullif(btrim(settled_identity_item.frozen_source_basis_json->>'source_family_key'), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'source_family_key'), ''),
        CASE
          WHEN coalesce(
            settled_identity_component.linked_timesheet_id,
            settled_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          ) IS NOT NULL
          THEN 'timesheet:' || coalesce(
            settled_identity_component.linked_timesheet_id,
            settled_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          )::text
          ELSE NULL::text
        END
      ) AS source_family_key,
      upper(coalesce(
        nullif(btrim(settled_identity_component.component_key_type), ''),
        nullif(btrim(settled_identity_item.frozen_component_key_type), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'component_key_type'), '')
      )) AS component_key_type,
      coalesce(
        nullif(btrim(settled_identity_component.component_key_value), ''),
        nullif(btrim(settled_identity_item.frozen_component_key_value), ''),
        nullif(btrim(settled_identity_item.frozen_component_snapshot_json->>'component_key_value'), '')
      ) AS component_key_value,
      abs(coalesce(
        settled_identity_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(settled_identity_item.id),
        settled_identity_item.frozen_source_amount,
        settled_identity_item.amount_ex_vat,
        settled_identity_item.amount_inc_vat,
        settled_identity_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_batch_items AS settled_identity_item
    JOIN pg_temp.tmp_pay_finance_case_item_scope AS settled_identity_scope
      ON settled_identity_scope.pay_batch_item_id = settled_identity_item.id
    JOIN public.pay_batch_candidates AS settled_identity_candidate
      ON settled_identity_candidate.id = settled_identity_item.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers AS settled_identity_transfer
      ON settled_identity_transfer.id = settled_identity_item.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations AS settled_identity_reservation
      ON settled_identity_reservation.pay_batch_item_id = settled_identity_item.id
    LEFT JOIN public.pay_finance_case_components AS settled_identity_component
      ON settled_identity_component.id = coalesce(
        settled_identity_reservation.finance_component_id,
        settled_identity_item.finance_component_id
      )
    WHERE coalesce(settled_identity_item.is_voided, false) = false
      AND coalesce(
        settled_identity_reservation.finance_case_id,
        settled_identity_item.finance_case_id,
        CASE
          WHEN upper(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 1))) = 'ADVANCE'
           AND nullif(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 2)), '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN nullif(btrim(split_part(coalesce(settled_identity_item.source_ref, ''), ':', 2)), '')::uuid
          ELSE NULL::uuid
        END
      ) = p_finance_case_id
      AND (
        v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(settled_identity_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS settled_identity_correction
        WHERE settled_identity_correction.pay_batch_item_id = settled_identity_item.id
          AND settled_identity_correction.status = 'APPLIED'
          AND settled_identity_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
      AND (
        upper(btrim(coalesce(settled_identity_candidate.settlement_status, ''))) = 'SETTLED'
        OR settled_identity_candidate.settled_at_utc IS NOT NULL
        OR upper(btrim(coalesce(settled_identity_transfer.status, ''))) = 'COMPLETED'
        OR settled_identity_transfer.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(settled_identity_reservation.status, ''))) = 'SETTLED'
        OR settled_identity_reservation.settled_at_utc IS NOT NULL
      )
  ) AS normalized_settled_identity
  WHERE normalized_settled_identity.source_family_key IS NOT NULL
    AND normalized_settled_identity.component_key_type IS NOT NULL
    AND normalized_settled_identity.component_key_value IS NOT NULL
    AND round(coalesce(normalized_settled_identity.component_source_amount, 0), 2) > 0
  GROUP BY
    normalized_settled_identity.source_family_key,
    normalized_settled_identity.component_key_type,
    normalized_settled_identity.component_key_value;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_identity_reserved (
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    active_reserved_source_amount numeric(12,2) NOT NULL,
    PRIMARY KEY (source_family_key, component_key_type, component_key_value)
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_identity_reserved;

  INSERT INTO pg_temp.tmp_pay_finance_component_identity_reserved (
    source_family_key,
    component_key_type,
    component_key_value,
    active_reserved_source_amount
  )
  SELECT
    normalized_reserved_identity.source_family_key,
    normalized_reserved_identity.component_key_type,
    normalized_reserved_identity.component_key_value,
    round(sum(normalized_reserved_identity.component_source_amount), 2)::numeric(12,2)
  FROM (
    SELECT
      coalesce(
        reserved_identity_component.source_family_key,
        nullif(btrim(reserved_identity_item.frozen_source_basis_json->>'source_family_key'), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'source_family_key'), ''),
        CASE
          WHEN coalesce(
            reserved_identity_component.linked_timesheet_id,
            reserved_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          ) IS NOT NULL
          THEN 'timesheet:' || coalesce(
            reserved_identity_component.linked_timesheet_id,
            reserved_identity_item.timesheet_id,
            v_case_linked_timesheet_id
          )::text
          ELSE NULL::text
        END
      ) AS source_family_key,
      upper(coalesce(
        nullif(btrim(reserved_identity_component.component_key_type), ''),
        nullif(btrim(reserved_identity_item.frozen_component_key_type), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'component_key_type'), '')
      )) AS component_key_type,
      coalesce(
        nullif(btrim(reserved_identity_component.component_key_value), ''),
        nullif(btrim(reserved_identity_item.frozen_component_key_value), ''),
        nullif(btrim(reserved_identity_item.frozen_component_snapshot_json->>'component_key_value'), '')
      ) AS component_key_value,
      abs(coalesce(
        reserved_identity_reservation.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(reserved_identity_item.id),
        reserved_identity_item.frozen_source_amount,
        reserved_identity_item.amount_ex_vat,
        reserved_identity_item.amount_inc_vat,
        reserved_identity_reservation.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_advance_reservations AS reserved_identity_reservation
    JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS reserved_identity_scope
      ON reserved_identity_scope.reservation_id = reserved_identity_reservation.id
    LEFT JOIN public.pay_batch_items AS reserved_identity_item
      ON reserved_identity_item.id = reserved_identity_reservation.pay_batch_item_id
    LEFT JOIN public.pay_finance_case_components AS reserved_identity_component
      ON reserved_identity_component.id = coalesce(
        reserved_identity_reservation.finance_component_id,
        reserved_identity_item.finance_component_id
      )
    WHERE coalesce(
        reserved_identity_reservation.finance_case_id,
        reserved_identity_item.finance_case_id
      ) = p_finance_case_id
      AND (
        reserved_identity_item.id IS NULL
        OR v_case_type NOT IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        )
        OR upper(btrim(coalesce(reserved_identity_item.item_type, ''))) IN (
          'OVERPAYMENT_RECOVERY',
          'UNDERPAYMENT_PAYMENT'
        )
      )
      AND (reserved_identity_item.id IS NULL OR coalesce(reserved_identity_item.is_voided, false) = false)
      AND reserved_identity_reservation.settled_at_utc IS NULL
      AND reserved_identity_reservation.released_at_utc IS NULL
      AND upper(btrim(coalesce(reserved_identity_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reserved_identity_correction
        WHERE reserved_identity_correction.pay_batch_item_id = reserved_identity_item.id
          AND reserved_identity_correction.status = 'APPLIED'
          AND reserved_identity_correction.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
  ) AS normalized_reserved_identity
  WHERE normalized_reserved_identity.source_family_key IS NOT NULL
    AND normalized_reserved_identity.component_key_type IS NOT NULL
    AND normalized_reserved_identity.component_key_value IS NOT NULL
    AND round(coalesce(normalized_reserved_identity.component_source_amount, 0), 2) > 0
  GROUP BY
    normalized_reserved_identity.source_family_key,
    normalized_reserved_identity.component_key_type,
    normalized_reserved_identity.component_key_value;

  SELECT round(coalesce(sum(abs(coalesce(
    case_settled_reservation.reserved_source_amount,
    public._pay_batch_item_source_reservation_amount_ex_vat(case_settled_item.id),
    case_settled_item.frozen_source_amount,
    case_settled_item.amount_ex_vat,
    case_settled_item.amount_inc_vat,
    case_settled_reservation.reserved_amount,
    0
  ))), 0), 2)::numeric(12,2)
  INTO v_case_active_consumed_amount
  FROM public.pay_batch_items AS case_settled_item
  JOIN pg_temp.tmp_pay_finance_case_item_scope AS case_settled_scope
    ON case_settled_scope.pay_batch_item_id = case_settled_item.id
  JOIN public.pay_batch_candidates AS case_settled_candidate
    ON case_settled_candidate.id = case_settled_item.pay_batch_candidate_id
  LEFT JOIN public.pay_bank_transfers AS case_settled_transfer
    ON case_settled_transfer.id = case_settled_item.pay_bank_transfer_id
  LEFT JOIN public.pay_advance_reservations AS case_settled_reservation
    ON case_settled_reservation.pay_batch_item_id = case_settled_item.id
  WHERE coalesce(case_settled_item.is_voided, false) = false
    AND coalesce(
      case_settled_reservation.finance_case_id,
      case_settled_item.finance_case_id,
      CASE
        WHEN upper(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 1))) = 'ADVANCE'
         AND nullif(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 2)), '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN nullif(btrim(split_part(coalesce(case_settled_item.source_ref, ''), ':', 2)), '')::uuid
        ELSE NULL::uuid
      END
    ) = p_finance_case_id
    AND (
      v_case_type NOT IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      )
      OR upper(btrim(coalesce(case_settled_item.item_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'UNDERPAYMENT_PAYMENT'
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS case_settled_correction
      WHERE case_settled_correction.pay_batch_item_id = case_settled_item.id
        AND case_settled_correction.status = 'APPLIED'
        AND case_settled_correction.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    )
    AND (
      upper(btrim(coalesce(case_settled_candidate.settlement_status, ''))) = 'SETTLED'
      OR case_settled_candidate.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(case_settled_transfer.status, ''))) = 'COMPLETED'
      OR case_settled_transfer.completed_at_utc IS NOT NULL
      OR upper(btrim(coalesce(case_settled_reservation.status, ''))) = 'SETTLED'
      OR case_settled_reservation.settled_at_utc IS NOT NULL
    );

  SELECT round(coalesce(sum(abs(coalesce(
    case_reserved_reservation.reserved_source_amount,
    public._pay_batch_item_source_reservation_amount_ex_vat(case_reserved_item.id),
    case_reserved_item.frozen_source_amount,
    case_reserved_item.amount_ex_vat,
    case_reserved_item.amount_inc_vat,
    case_reserved_reservation.reserved_amount,
    0
  ))), 0), 2)::numeric(12,2)
  INTO v_case_active_reserved_source_amount
  FROM public.pay_advance_reservations AS case_reserved_reservation
  JOIN pg_temp.tmp_pay_finance_case_reservation_scope AS case_reserved_scope
    ON case_reserved_scope.reservation_id = case_reserved_reservation.id
  LEFT JOIN public.pay_batch_items AS case_reserved_item
    ON case_reserved_item.id = case_reserved_reservation.pay_batch_item_id
  WHERE coalesce(
      case_reserved_reservation.finance_case_id,
      case_reserved_item.finance_case_id
    ) = p_finance_case_id
    AND (
      case_reserved_item.id IS NULL
      OR v_case_type NOT IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      )
      OR upper(btrim(coalesce(case_reserved_item.item_type, ''))) IN (
        'OVERPAYMENT_RECOVERY',
        'UNDERPAYMENT_PAYMENT'
      )
    )
    AND (case_reserved_item.id IS NULL OR coalesce(case_reserved_item.is_voided, false) = false)
    AND case_reserved_reservation.settled_at_utc IS NULL
    AND case_reserved_reservation.released_at_utc IS NULL
    AND upper(btrim(coalesce(case_reserved_reservation.status, ''))) IN ('RESERVED', 'COMMITTED')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS case_reserved_correction
      WHERE case_reserved_correction.pay_batch_item_id = case_reserved_item.id
        AND case_reserved_correction.status = 'APPLIED'
        AND case_reserved_correction.correction_item_kind IN (
          'PRE_BANK_CANCEL',
          'NO_MONEY_UNWIND',
          'SETTLED_REVERSAL'
        )
    );

  FOR v_existing_component IN
    SELECT
      pfc.*
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.closed_at_utc IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM (
          SELECT DISTINCT ON (
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          )
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          FROM pg_temp.tmp_pay_finance_component_sync_input src
          ORDER BY
            src.source_family_key,
            src.component_key_type,
            src.component_key_value,
            src.row_seq DESC
        ) keep_rows
        WHERE keep_rows.source_family_key = pfc.source_family_key
          AND keep_rows.component_key_type = pfc.component_key_type
          AND keep_rows.component_key_value = pfc.component_key_value
      )
  LOOP
    v_before_json := jsonb_build_object(
      'candidate_id', v_existing_component.candidate_id::text,
      'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
      'source_family_key', v_existing_component.source_family_key,
      'component_key_type', v_existing_component.component_key_type,
      'component_key_value', v_existing_component.component_key_value,
      'classification', v_existing_component.classification::text,
      'source_pay_method', v_existing_component.source_pay_method,
      'source_basis_json', v_existing_component.source_basis_json,
      'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_existing_component.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
      'resolution_fingerprint', v_existing_component.resolution_fingerprint,
      'is_resolution_stale', v_existing_component.is_resolution_stale,
      'stale_reason', v_existing_component.stale_reason,
      'closed_at_utc', v_existing_component.closed_at_utc
    );

    SELECT EXISTS (
      SELECT 1
      FROM public.pay_finance_case_events AS protected_component_events
      WHERE protected_component_events.finance_case_id = p_finance_case_id
        AND protected_component_events.finance_component_id = v_existing_component.id
        AND (
          upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
          OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE',
            'MANUAL_WRITE_OFF',
            'CASE_MANUAL_ECONOMIC_OVERRIDE',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
          OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
            'MANUAL_ECONOMIC_OVERRIDE',
            'WRITE_OFF',
            'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
          )
        )
    )
    INTO v_component_has_protected_event;

    v_component_is_protected := coalesce(v_component_has_protected_event, false);

    IF v_component_is_protected THEN
      INSERT INTO public.pay_finance_case_events (
        finance_case_id,
        finance_component_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      VALUES (
        p_finance_case_id,
        v_existing_component.id,
        'SYNC_SKIPPED',
        v_now_utc,
        p_actor_user_id,
        NULL,
        NULL,
        v_before_json,
        jsonb_build_object(
          'sync_skipped', true,
          'reason', 'PROTECTED_COMPONENT_NOT_CLOSED',
          'has_protected_event', v_component_has_protected_event,
          'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
          'is_resolution_stale', v_existing_component.is_resolution_stale
        ),
        'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
        'Skipped closing finance component because an explicit manual, write-off, or restructure event protects it.'
      );
      v_protected_skip_count := v_protected_skip_count + 1;
      CONTINUE;
    END IF;

    SELECT reserved_amounts.active_reserved_source_amount
    INTO v_active_reserved_source_amount
    FROM pg_temp.tmp_pay_finance_component_active_reserved AS reserved_amounts
    WHERE reserved_amounts.finance_component_id = v_existing_component.id;

    v_active_reserved_source_amount := round(coalesce(v_active_reserved_source_amount, 0), 2)::numeric(12,2);

    IF v_active_reserved_source_amount > 0 THEN
      UPDATE public.pay_finance_case_components AS preserved_component
      SET remaining_source_amount = greatest(round(coalesce(preserved_component.remaining_source_amount, 0), 2), v_active_reserved_source_amount)::numeric(12,2),
          updated_at_utc = v_now_utc
      WHERE preserved_component.id = v_existing_component.id
      RETURNING preserved_component.* INTO v_component_after;

      v_after_json := jsonb_build_object(
        'candidate_id', v_component_after.candidate_id::text,
        'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
        'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
        'source_family_key', v_component_after.source_family_key,
        'component_key_type', v_component_after.component_key_type,
        'component_key_value', v_component_after.component_key_value,
        'classification', v_component_after.classification::text,
        'source_pay_method', v_component_after.source_pay_method,
        'source_basis_json', v_component_after.source_basis_json,
        'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
        'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
        'active_reserved_source_amount', v_active_reserved_source_amount,
        'closed_at_utc', v_component_after.closed_at_utc
      );

      INSERT INTO public.pay_finance_case_events (
        finance_case_id,
        finance_component_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      VALUES (
        p_finance_case_id,
        v_existing_component.id,
        'SYNC_SKIPPED',
        v_now_utc,
        p_actor_user_id,
        NULL,
        NULL,
        v_before_json,
        v_after_json,
        'COMPONENT_SYNC_CLOSE_DEFERRED_ACTIVE_RESERVATION',
        'Deferred closing finance component because active RESERVED/COMMITTED recovery reservations still protect it.'
      );

      v_active_reservation_deferred_count := v_active_reservation_deferred_count + 1;
      CONTINUE;
    END IF;

    UPDATE public.pay_finance_case_components pfc
    SET
      remaining_source_amount = 0,
      is_resolution_stale = false,
      stale_reason = NULL,
      closed_at_utc = v_now_utc,
      updated_at_utc = v_now_utc
    WHERE pfc.id = v_existing_component.id
    RETURNING pfc.* INTO v_component_after;

    v_after_json := jsonb_build_object(
      'candidate_id', v_component_after.candidate_id::text,
      'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
      'source_family_key', v_component_after.source_family_key,
      'component_key_type', v_component_after.component_key_type,
      'component_key_value', v_component_after.component_key_value,
      'classification', v_component_after.classification::text,
      'source_pay_method', v_component_after.source_pay_method,
      'source_basis_json', v_component_after.source_basis_json,
      'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
      'resolution_fingerprint', v_component_after.resolution_fingerprint,
      'is_resolution_stale', v_component_after.is_resolution_stale,
      'stale_reason', v_component_after.stale_reason,
      'closed_at_utc', v_component_after.closed_at_utc
    );

    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      v_existing_component.id,
      'COMPONENT_CLOSED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      v_before_json,
      v_after_json,
      'COMPONENT_SYNC',
      'Closed finance component because it no longer exists in the current preview/truth line set'
    );

    v_closed_count := v_closed_count + 1;
  END LOOP;

  FOR v_line_json IN
    SELECT to_jsonb(src.*)
    FROM (
      SELECT DISTINCT ON (
        src.source_family_key,
        src.component_key_type,
        src.component_key_value
      )
        src.row_seq,
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.classification,
        src.candidate_id,
        src.client_id,
        src.linked_timesheet_id,
        src.source_pay_method,
        src.current_target_pay_method,
        src.source_basis_json,
        src.target_basis_json,
        src.accepted_resolution_json,
        src.source_amount,
        src.incoming_remaining_source_amount,
        src.incoming_remaining_is_explicit,
        src.relevant_erni_pct,
        src.allocation_priority_group,
        src.allocation_priority_order,
        src.current_basis_fingerprint
      FROM pg_temp.tmp_pay_finance_component_sync_input src
      ORDER BY
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.row_seq DESC
    ) src
    ORDER BY
      (src.source_basis_json->>'work_date') NULLS LAST,
      src.allocation_priority_group,
      src.allocation_priority_order,
      src.row_seq
  LOOP
    v_line_candidate_id := (v_line_json->>'candidate_id')::uuid;
    v_line_client_id := CASE
      WHEN nullif(v_line_json->>'client_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'client_id')::uuid
    END;
    v_line_linked_timesheet_id := CASE
      WHEN nullif(v_line_json->>'linked_timesheet_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'linked_timesheet_id')::uuid
    END;
    v_line_classification := (v_line_json->>'classification')::public.pay_finance_component_classification_enum;
    v_line_source_pay_method := v_line_json->>'source_pay_method';
    v_line_current_target_pay_method := coalesce(v_line_json->>'current_target_pay_method', '');
    v_line_source_basis_json := v_line_json->'source_basis_json';
    v_line_source_amount := round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2)::numeric(12,2);
    v_line_incoming_remaining_source_amount := CASE
      WHEN (v_line_json->>'incoming_remaining_is_explicit')::boolean
        THEN round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2)::numeric(12,2)
      ELSE NULL
    END;
    v_line_allocation_priority_group := (v_line_json->>'allocation_priority_group')::integer;
    v_line_allocation_priority_order := (v_line_json->>'allocation_priority_order')::integer;

    SELECT
      pfc.*
    INTO
      v_existing_component
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.source_family_key = v_line_json->>'source_family_key'
      AND pfc.component_key_type = v_line_json->>'component_key_type'
      AND pfc.component_key_value = v_line_json->>'component_key_value'
      AND pfc.closed_at_utc IS NULL
    ORDER BY
      pfc.updated_at_utc DESC,
      pfc.created_at_utc DESC,
      pfc.id DESC
    LIMIT 1;

    IF FOUND THEN
      v_active_consumed_amount := NULL::numeric;
      v_active_reserved_source_amount := 0::numeric(12,2);
      v_identity_consumed_amount := NULL::numeric;
      v_identity_reserved_source_amount := NULL::numeric;

      SELECT recovered_amounts.active_consumed_source_amount
      INTO v_active_consumed_amount
      FROM pg_temp.tmp_pay_finance_component_active_recovered AS recovered_amounts
      WHERE recovered_amounts.finance_component_id = v_existing_component.id;

      SELECT reserved_amounts.active_reserved_source_amount
      INTO v_active_reserved_source_amount
      FROM pg_temp.tmp_pay_finance_component_active_reserved AS reserved_amounts
      WHERE reserved_amounts.finance_component_id = v_existing_component.id;

      SELECT identity_recovered.active_consumed_source_amount
      INTO v_identity_consumed_amount
      FROM pg_temp.tmp_pay_finance_component_identity_recovered AS identity_recovered
      WHERE identity_recovered.source_family_key = v_existing_component.source_family_key
        AND identity_recovered.component_key_type = v_existing_component.component_key_type
        AND identity_recovered.component_key_value = v_existing_component.component_key_value;

      SELECT identity_reserved.active_reserved_source_amount
      INTO v_identity_reserved_source_amount
      FROM pg_temp.tmp_pay_finance_component_identity_reserved AS identity_reserved
      WHERE identity_reserved.source_family_key = v_existing_component.source_family_key
        AND identity_reserved.component_key_type = v_existing_component.component_key_type
        AND identity_reserved.component_key_value = v_existing_component.component_key_value;

      IF v_case_type IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum
      ) THEN
        v_consumed_amount := round(coalesce(
          v_identity_consumed_amount,
          CASE WHEN v_input_component_count = 1 THEN v_case_active_consumed_amount ELSE NULL::numeric END,
          0
        ), 2)::numeric(12,2);
        v_active_reserved_source_amount := round(greatest(
          coalesce(v_identity_reserved_source_amount, 0),
          coalesce(v_active_reserved_source_amount, 0),
          CASE WHEN v_input_component_count = 1 THEN coalesce(v_case_active_reserved_source_amount, 0) ELSE 0::numeric END
        ), 2)::numeric(12,2);
      ELSE
        v_active_reserved_source_amount := round(coalesce(v_active_reserved_source_amount, 0), 2)::numeric(12,2);
        v_consumed_amount := coalesce(
          v_active_consumed_amount,
          greatest(
            round(coalesce(v_existing_component.source_amount, 0), 2) - round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
            0
          )::numeric(12,2)
        );
      END IF;

      IF (v_line_json->>'incoming_remaining_is_explicit')::boolean THEN
        /* Explicit remaining is the upstream net-open authority.  Correction
           residual inputs already include settled recovery/underpayment
           movements, so subtracting v_consumed_amount again would double
           consume the frozen movement.  v_effective_source_amount below keeps
           the cumulative source basis at consumed + still open, while the
           active-reservation floor prevents a live draft from being stranded. */
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2),
          0
        )::numeric(12,2);
      ELSE
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2) - v_consumed_amount,
          0
        )::numeric(12,2);
      END IF;

      IF v_active_reserved_source_amount > 0
         AND round(coalesce(v_new_remaining_source_amount, 0), 2) < v_active_reserved_source_amount THEN
        v_new_remaining_source_amount := v_active_reserved_source_amount;
        v_active_reservation_deferred_count := v_active_reservation_deferred_count + 1;
      END IF;

      v_effective_source_amount := greatest(
        round(coalesce(v_line_source_amount, 0), 2),
        round(coalesce(v_consumed_amount, 0), 2) + round(coalesce(v_new_remaining_source_amount, 0), 2)
      )::numeric(12,2);

      v_upstream_correction_resolution_applied := (
        lower(coalesce(
          v_line_source_basis_json->>'upstream_correction_pay_method_resolution_applied',
          'false'
        )) in ('true','t','1','yes','y','on')
        and upper(coalesce(v_line_source_pay_method,'')) =
            upper(coalesce(v_line_current_target_pay_method,''))
      );

      v_has_saved_resolution := not v_upstream_correction_resolution_applied and (
        v_existing_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND (
          v_existing_component.saved_target_pay_method IS NOT NULL
          OR v_existing_component.saved_resolution_mode IS NOT NULL
          OR v_existing_component.saved_resolution_payload_json IS NOT NULL
          OR v_existing_component.saved_resolution_result_json IS NOT NULL
          OR v_existing_component.resolution_fingerprint IS NOT NULL
          OR v_existing_component.is_resolution_stale = true
        )
      );

      IF v_has_saved_resolution THEN
        IF v_existing_component.classification IS DISTINCT FROM v_line_classification THEN
          v_should_be_stale := true;
          v_stale_reason := 'COMPONENT_CLASSIFICATION_CHANGED';
        ELSIF v_existing_component.saved_target_pay_method IS NOT NULL
           AND upper(v_existing_component.saved_target_pay_method) IS DISTINCT FROM upper(v_line_current_target_pay_method) THEN
          v_should_be_stale := true;
          v_stale_reason := 'TARGET_PAY_METHOD_CHANGED';
        ELSIF upper(coalesce(v_existing_component.source_pay_method, '')) IS DISTINCT FROM upper(coalesce(v_line_source_pay_method, '')) THEN
          v_should_be_stale := true;
          v_stale_reason := 'SOURCE_PAY_METHOD_CHANGED';
        ELSIF (
          coalesce(v_existing_component.source_basis_json, '{}'::jsonb)
            - 'amount'
            - 'amount_ex_vat'
            - 'amount_inc_vat'
            - 'component_amount_ex_vat'
            - 'remaining_source_amount'
            - 'source_amount'
            - 'source_units'
            - 'units'
            - 'hours'
            - 'quantity'
            - 'line_total'
            - 'total'
            - 'current_amount'
            - 'current_units'
        ) IS DISTINCT FROM (
          coalesce(v_line_source_basis_json, '{}'::jsonb)
            - 'amount'
            - 'amount_ex_vat'
            - 'amount_inc_vat'
            - 'component_amount_ex_vat'
            - 'remaining_source_amount'
            - 'source_amount'
            - 'source_units'
            - 'units'
            - 'hours'
            - 'quantity'
            - 'line_total'
            - 'total'
            - 'current_amount'
            - 'current_units'
        ) THEN
          v_should_be_stale := true;
          v_stale_reason := 'COMPONENT_BASIS_CHANGED';
        /* A21 / F-PRE-RATE-R2 (user ruling 25 Sep 2026): an Office-typed MANUAL_AMOUNT is re-confirmed, never
           rescaled, when the underlying amount, units or hours change. Once stale, it stays stale until the Office
           re-confirms through the existing owners (taxable-channel restructure / component resolution), which clear
           is_resolution_stale; the source fields compared above are overwritten on every sync, so without this the
           flag would clear itself on the next identical sync and the amount would be reused silently.
           The effective source amount is consumed + still open, so recovery/consumption alone leaves it unchanged
           and keeps the existing proportional reuse. MANUAL_REPLACEMENT_RATE and SUGGESTED_EQUIVALENT_BASIS keep the
           existing behaviour unchanged. */
        ELSIF v_existing_component.saved_resolution_mode = 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
          AND coalesce(v_existing_component.is_resolution_stale, false) = true THEN
          v_should_be_stale := true;
          v_stale_reason := coalesce(v_existing_component.stale_reason, 'MANUAL_AMOUNT_UNDERLYING_CHANGED');
        ELSIF v_existing_component.saved_resolution_mode = 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
          AND (
            round(coalesce(v_effective_source_amount, v_line_source_amount, 0), 2)
               IS DISTINCT FROM round(coalesce(v_existing_component.source_amount, 0), 2)
            OR jsonb_build_object(
                 'source_units', coalesce(v_existing_component.source_basis_json, '{}'::jsonb)->'source_units',
                 'units', coalesce(v_existing_component.source_basis_json, '{}'::jsonb)->'units',
                 'hours', coalesce(v_existing_component.source_basis_json, '{}'::jsonb)->'hours',
                 'quantity', coalesce(v_existing_component.source_basis_json, '{}'::jsonb)->'quantity',
                 'current_units', coalesce(v_existing_component.source_basis_json, '{}'::jsonb)->'current_units'
               ) IS DISTINCT FROM jsonb_build_object(
                 'source_units', coalesce(v_line_source_basis_json, '{}'::jsonb)->'source_units',
                 'units', coalesce(v_line_source_basis_json, '{}'::jsonb)->'units',
                 'hours', coalesce(v_line_source_basis_json, '{}'::jsonb)->'hours',
                 'quantity', coalesce(v_line_source_basis_json, '{}'::jsonb)->'quantity',
                 'current_units', coalesce(v_line_source_basis_json, '{}'::jsonb)->'current_units'
               )
          ) THEN
          v_should_be_stale := true;
          v_stale_reason := 'MANUAL_AMOUNT_UNDERLYING_CHANGED';
        ELSE
          v_should_be_stale := false;
          v_stale_reason := NULL;
        END IF;
      ELSE
        v_should_be_stale := false;
        v_stale_reason := NULL;
      END IF;

      v_resolution_target_ratio := NULL;
      v_resolution_vat_ratio := NULL;
      v_resolution_inc_ratio := NULL;

      IF v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
        v_resolution_target_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_source_ratio', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN (v_existing_component.saved_resolution_result_json->>'target_source_ratio')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_ex_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          1::numeric
        );

        v_resolution_vat_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          0::numeric
        );

        v_resolution_inc_ratio := COALESCE(
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND coalesce(v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs((v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat')::numeric
                   / (v_existing_component.saved_resolution_result_json->>'source_remaining_amount_ex_vat')::numeric
            ELSE NULL::numeric
          END,
          CASE
            WHEN coalesce(v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
             AND round(abs(coalesce(v_existing_component.remaining_source_amount, 0)), 2) <> 0
              THEN (v_existing_component.saved_resolution_result_json->>'target_remaining_amount_inc_vat')::numeric
                   / v_existing_component.remaining_source_amount
            ELSE NULL::numeric
          END,
          v_resolution_target_ratio
        );
      END IF;

      v_before_json := jsonb_build_object(
        'candidate_id', v_existing_component.candidate_id::text,
        'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
        'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
        'source_family_key', v_existing_component.source_family_key,
        'component_key_type', v_existing_component.component_key_type,
        'component_key_value', v_existing_component.component_key_value,
        'classification', v_existing_component.classification::text,
        'source_pay_method', v_existing_component.source_pay_method,
        'source_basis_json', v_existing_component.source_basis_json,
        'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
        'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
        'saved_target_pay_method', v_existing_component.saved_target_pay_method,
        'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
        'resolution_fingerprint', v_existing_component.resolution_fingerprint,
        'is_resolution_stale', v_existing_component.is_resolution_stale,
        'stale_reason', v_existing_component.stale_reason,
        'closed_at_utc', v_existing_component.closed_at_utc
      );

      SELECT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protected_component_events
        WHERE protected_component_events.finance_case_id = p_finance_case_id
          AND protected_component_events.finance_component_id = v_existing_component.id
          AND (
            upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'MANUAL_WRITE_OFF',
                'CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
              OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'WRITE_OFF',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
          )
      )
      INTO v_component_has_protected_event;

      v_component_is_protected := coalesce(v_component_has_protected_event, false);

      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        v_accepted_resolution_fingerprint := coalesce(
          nullif(btrim(v_accepted_resolution_json->>'component_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'resolution_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['component_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['resolution_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['validation', 'component_fingerprints', v_existing_component.id::text]), '')
        );

        IF v_component_is_protected
           OR v_existing_component.closed_at_utc IS NOT NULL
           OR v_accepted_resolution_fingerprint IS NULL
           OR v_should_be_stale THEN
          RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'ACCEPTED_RESOLUTION_STALE',
            'code', 'ACCEPTED_RESOLUTION_STALE',
            'message', 'Accepted suggested correction resolution is stale or no longer matches the open finance component state.',
            'finance_case_id', p_finance_case_id::text,
            'finance_component_id', v_existing_component.id::text,
            'component_still_open', v_existing_component.closed_at_utc IS NULL,
            'has_protected_event', v_component_has_protected_event,
            'accepted_fingerprint', v_accepted_resolution_fingerprint,
            'current_fingerprint', v_line_json->>'current_basis_fingerprint'
          )::text;
        END IF;
      END IF;

      IF v_component_is_protected THEN
        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
            'has_protected_event', v_component_has_protected_event,
            'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
            'is_resolution_stale', v_existing_component.is_resolution_stale
          ),
          'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
          'Skipped updating finance component because an explicit write-off or manual economic override protects it.'
        );
        v_protected_skip_count := v_protected_skip_count + 1;
        CONTINUE;
      END IF;

      IF round(coalesce(v_existing_component.source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_effective_source_amount, v_line_source_amount, 0), 2)
         OR round(coalesce(v_existing_component.remaining_source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_new_remaining_source_amount, 0), 2)
         OR v_existing_component.candidate_id IS DISTINCT FROM v_line_candidate_id
         OR v_existing_component.client_id IS DISTINCT FROM v_line_client_id
         OR v_existing_component.linked_timesheet_id IS DISTINCT FROM v_line_linked_timesheet_id
         OR v_existing_component.source_pay_method IS DISTINCT FROM v_line_source_pay_method
         OR v_existing_component.source_basis_json IS DISTINCT FROM v_line_source_basis_json
         OR v_existing_component.classification IS DISTINCT FROM v_line_classification
         OR v_existing_component.allocation_priority_group IS DISTINCT FROM v_line_allocation_priority_group
         OR v_existing_component.allocation_priority_order IS DISTINCT FROM v_line_allocation_priority_order
         OR v_existing_component.is_resolution_stale IS DISTINCT FROM v_should_be_stale
          OR v_existing_component.stale_reason IS DISTINCT FROM v_stale_reason
          OR (
            v_upstream_correction_resolution_applied
            AND (
              v_existing_component.saved_target_pay_method IS NOT NULL
              OR v_existing_component.saved_resolution_mode IS NOT NULL
              OR v_existing_component.saved_resolution_payload_json IS NOT NULL
              OR v_existing_component.saved_resolution_result_json IS NOT NULL
              OR v_existing_component.resolution_fingerprint IS NOT NULL
            )
          )
      THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.pay_finance_case_events AS protected_component_events
          WHERE protected_component_events.finance_case_id = p_finance_case_id
            AND protected_component_events.finance_component_id = v_existing_component.id
            AND (
              upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'MANUAL_WRITE_OFF',
                'CASE_MANUAL_ECONOMIC_OVERRIDE',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
              OR upper(btrim(coalesce(protected_component_events.reason, ''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE',
                'WRITE_OFF',
                'COMPONENT_MANUAL_ECONOMIC_OVERRIDE'
              )
            )
        )
        INTO v_component_has_protected_event;

        v_component_is_protected := coalesce(v_component_has_protected_event, false);

        IF v_component_is_protected THEN
          INSERT INTO public.pay_finance_case_events (
            finance_case_id,
            finance_component_id,
            event_type,
            event_at_utc,
            actor_user_id,
            pay_batch_id,
            reservation_id,
            before_json,
            after_json,
            reason,
            note
          )
          VALUES (
            p_finance_case_id,
            v_existing_component.id,
            'SYNC_SKIPPED',
            v_now_utc,
            p_actor_user_id,
            NULL,
            NULL,
            v_before_json,
            jsonb_build_object(
              'sync_skipped', true,
              'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
              'has_protected_event', v_component_has_protected_event
            ),
            'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
            'Skipped updating finance component because it has an explicit write-off or manual economic override protection.'
          );
          v_protected_skip_count := v_protected_skip_count + 1;
          CONTINUE;
        END IF;

        UPDATE public.pay_finance_case_components pfc
        SET
          candidate_id = v_line_candidate_id,
          client_id = v_line_client_id,
          linked_timesheet_id = v_line_linked_timesheet_id,
          classification = v_line_classification,
          source_pay_method = v_line_source_pay_method,
          source_basis_json = v_line_source_basis_json,
          source_amount = round(coalesce(v_effective_source_amount, v_line_source_amount, 0), 2)::numeric(12,2),
          remaining_source_amount = round(coalesce(v_new_remaining_source_amount, 0), 2)::numeric(12,2),
          saved_target_pay_method = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_target_pay_method
          END,
          saved_resolution_mode = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_resolution_mode
          END,
          saved_resolution_payload_json = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            ELSE pfc.saved_resolution_payload_json
          END,
          saved_resolution_result_json = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            WHEN v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
              jsonb_strip_nulls(
                coalesce(pfc.saved_resolution_result_json, '{}'::jsonb)
                || jsonb_build_object(
                  'source_remaining_amount_ex_vat', round(coalesce(v_new_remaining_source_amount, 0), 2),
                  'target_remaining_amount_ex_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_target_ratio, 1), 2),
                  'target_remaining_amount_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_vat_ratio, 0), 2),
                  'target_remaining_amount_inc_vat', round(coalesce(v_new_remaining_source_amount, 0) * coalesce(v_resolution_inc_ratio, coalesce(v_resolution_target_ratio, 1)), 2),
                  'target_source_ratio', round(coalesce(v_resolution_target_ratio, 1), 12),
                  'amount_only_resolution_reused', true,
                  'amount_only_resolution_reused_at_utc', v_now_utc::text
                )
              )
            ELSE pfc.saved_resolution_result_json
          END,
          resolution_fingerprint = CASE
            WHEN v_upstream_correction_resolution_applied THEN NULL
            WHEN v_has_saved_resolution AND v_should_be_stale IS DISTINCT FROM true THEN
              coalesce(nullif(btrim(coalesce(v_line_json->>'current_basis_fingerprint', '')), ''), pfc.resolution_fingerprint)
            ELSE pfc.resolution_fingerprint
          END,
          is_resolution_stale = v_should_be_stale,
          stale_reason = v_stale_reason,
          allocation_priority_group = v_line_allocation_priority_group,
          allocation_priority_order = v_line_allocation_priority_order,
          updated_at_utc = v_now_utc
        WHERE pfc.id = v_existing_component.id
        RETURNING pfc.* INTO v_component_after;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN 'COMPONENT_STALE'
            ELSE 'COMPONENT_UPDATED'
          END,
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          v_after_json,
          'COMPONENT_SYNC',
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true
              THEN 'Updated finance component and marked saved taxable resolution stale because the basis or target pay method changed materially'
            ELSE 'Updated finance component from current preview/truth line set'
          END
        );

        IF v_active_reserved_source_amount > 0
           AND round(coalesce(v_line_source_amount, 0), 2) < round(coalesce(v_effective_source_amount, 0), 2) THEN
          INSERT INTO public.pay_finance_case_events (
            finance_case_id,
            finance_component_id,
            event_type,
            event_at_utc,
            actor_user_id,
            pay_batch_id,
            reservation_id,
            before_json,
            after_json,
            reason,
            note
          )
          VALUES (
            p_finance_case_id,
            v_existing_component.id,
            'COMPONENT_UPDATED',
            v_now_utc,
            p_actor_user_id,
            NULL,
            NULL,
            v_before_json,
            v_after_json || jsonb_build_object(
              'active_reserved_source_amount', v_active_reserved_source_amount,
              'incoming_source_amount', round(coalesce(v_line_source_amount, 0), 2),
              'effective_source_amount', round(coalesce(v_effective_source_amount, 0), 2),
              'effective_remaining_source_amount', round(coalesce(v_new_remaining_source_amount, 0), 2)
            ),
            'COMPONENT_SYNC_SHRINK_DEFERRED_ACTIVE_RESERVATION',
            'Deferred component shrink below active RESERVED/COMMITTED recovery reservations.'
          );
        END IF;

        IF v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN
          v_stale_marked_count := v_stale_marked_count + 1;
        END IF;

        v_updated_count := v_updated_count + 1;
      END IF;
    ELSE
      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'ACCEPTED_RESOLUTION_STALE',
          'code', 'ACCEPTED_RESOLUTION_STALE',
          'message', 'Accepted suggested correction resolution cannot be applied because the finance component is no longer open.',
          'finance_case_id', p_finance_case_id::text,
          'source_family_key', v_line_json->>'source_family_key',
          'component_key_type', v_line_json->>'component_key_type',
          'component_key_value', v_line_json->>'component_key_value',
          'component_still_open', false
        )::text;
      END IF;

      SELECT
        pfc.*
      INTO
        v_reopen_component
      FROM public.pay_finance_case_components pfc
      WHERE pfc.finance_case_id = p_finance_case_id
        AND pfc.source_family_key = v_line_json->>'source_family_key'
        AND pfc.component_key_type = v_line_json->>'component_key_type'
        AND pfc.component_key_value = v_line_json->>'component_key_value'
        AND pfc.closed_at_utc IS NOT NULL
      ORDER BY
        pfc.closed_at_utc DESC,
        pfc.updated_at_utc DESC,
        pfc.created_at_utc DESC,
        pfc.id DESC
      LIMIT 1;

      IF FOUND THEN
        v_before_json := jsonb_build_object(
          'candidate_id', v_reopen_component.candidate_id::text,
          'client_id', CASE WHEN v_reopen_component.client_id IS NULL THEN NULL ELSE v_reopen_component.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_reopen_component.linked_timesheet_id IS NULL THEN NULL ELSE v_reopen_component.linked_timesheet_id::text END,
          'source_family_key', v_reopen_component.source_family_key,
          'component_key_type', v_reopen_component.component_key_type,
          'component_key_value', v_reopen_component.component_key_value,
          'classification', v_reopen_component.classification::text,
          'source_pay_method', v_reopen_component.source_pay_method,
          'source_basis_json', v_reopen_component.source_basis_json,
          'source_amount', round(coalesce(v_reopen_component.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_reopen_component.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_reopen_component.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_reopen_component.saved_resolution_mode IS NULL THEN NULL ELSE v_reopen_component.saved_resolution_mode::text END,
          'resolution_fingerprint', v_reopen_component.resolution_fingerprint,
          'is_resolution_stale', v_reopen_component.is_resolution_stale,
          'stale_reason', v_reopen_component.stale_reason,
          'closed_at_utc', v_reopen_component.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_reopen_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'CLOSED_COMPONENT_PRESERVED',
            'new_component_will_be_created', true,
            'source_family_key', v_line_json->>'source_family_key',
            'component_key_type', v_line_json->>'component_key_type',
            'component_key_value', v_line_json->>'component_key_value'
          ),
          'COMPONENT_SYNC_CLOSED_COMPONENT_PRESERVED',
          'Preserved closed finance component and created a new open component for the current preview/truth line set instead of silently reopening or overwriting the closed component.'
        );

        v_protected_skip_count := v_protected_skip_count + 1;
      END IF;

        v_identity_consumed_amount := NULL::numeric;
        v_identity_reserved_source_amount := NULL::numeric;
        v_consumed_amount := 0::numeric(12,2);
        v_active_reserved_source_amount := 0::numeric(12,2);

        SELECT identity_recovered.active_consumed_source_amount
        INTO v_identity_consumed_amount
        FROM pg_temp.tmp_pay_finance_component_identity_recovered AS identity_recovered
        WHERE identity_recovered.source_family_key = v_line_json->>'source_family_key'
          AND identity_recovered.component_key_type = v_line_json->>'component_key_type'
          AND identity_recovered.component_key_value = v_line_json->>'component_key_value';

        SELECT identity_reserved.active_reserved_source_amount
        INTO v_identity_reserved_source_amount
        FROM pg_temp.tmp_pay_finance_component_identity_reserved AS identity_reserved
        WHERE identity_reserved.source_family_key = v_line_json->>'source_family_key'
          AND identity_reserved.component_key_type = v_line_json->>'component_key_type'
          AND identity_reserved.component_key_value = v_line_json->>'component_key_value';

        IF v_case_type IN (
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum
        ) THEN
          v_consumed_amount := round(coalesce(
            v_identity_consumed_amount,
            CASE WHEN v_input_component_count = 1 THEN v_case_active_consumed_amount ELSE NULL::numeric END,
            0
          ), 2)::numeric(12,2);
          v_active_reserved_source_amount := round(greatest(
            coalesce(v_identity_reserved_source_amount, 0),
            CASE WHEN v_input_component_count = 1 THEN coalesce(v_case_active_reserved_source_amount, 0) ELSE 0::numeric END
          ), 2)::numeric(12,2);
        END IF;

        IF (v_line_json->>'incoming_remaining_is_explicit')::boolean THEN
          v_new_remaining_source_amount := greatest(
            round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2),
            v_active_reserved_source_amount,
            0
          )::numeric(12,2);
        ELSE
          v_new_remaining_source_amount := greatest(
            round(coalesce(v_line_source_amount, 0), 2) - round(coalesce(v_consumed_amount, 0), 2),
            v_active_reserved_source_amount,
            0
          )::numeric(12,2);
        END IF;

        v_effective_source_amount := greatest(
          round(coalesce(v_line_source_amount, 0), 2),
          round(coalesce(v_consumed_amount, 0), 2) + round(coalesce(v_new_remaining_source_amount, 0), 2)
        )::numeric(12,2);

        v_created_component_id := gen_random_uuid();

        INSERT INTO public.pay_finance_case_components (
          id,
          finance_case_id,
          candidate_id,
          client_id,
          linked_timesheet_id,
          source_family_key,
          component_key_type,
          component_key_value,
          classification,
          source_pay_method,
          source_basis_json,
          source_amount,
          remaining_source_amount,
          saved_target_pay_method,
          saved_resolution_mode,
          saved_resolution_payload_json,
          saved_resolution_result_json,
          resolution_fingerprint,
          is_resolution_stale,
          stale_reason,
          allocation_priority_group,
          allocation_priority_order,
          created_at_utc,
          updated_at_utc,
          resolved_at_utc,
          closed_at_utc
        )
        VALUES (
          v_created_component_id,
          p_finance_case_id,
          v_line_candidate_id,
          v_line_client_id,
          v_line_linked_timesheet_id,
          v_line_json->>'source_family_key',
          v_line_json->>'component_key_type',
          v_line_json->>'component_key_value',
          v_line_classification,
          v_line_source_pay_method,
          v_line_source_basis_json,
          round(coalesce(v_effective_source_amount, 0), 2)::numeric(12,2),
          round(coalesce(v_new_remaining_source_amount, 0), 2)::numeric(12,2),
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          false,
          NULL,
          v_line_allocation_priority_group,
          v_line_allocation_priority_order,
          v_now_utc,
          v_now_utc,
          NULL,
          NULL
        );

        SELECT
          pfc.*
        INTO
          v_component_after
        FROM public.pay_finance_case_components pfc
        WHERE pfc.id = v_created_component_id;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_created_component_id,
          'COMPONENT_CREATED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          NULL,
          v_after_json,
          'COMPONENT_SYNC',
          'Created finance component from current preview/truth line set'
        );

        v_inserted_count := v_inserted_count + 1;
    END IF;
  END LOOP;

  SELECT
    round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2),
    round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)) FILTER (WHERE pfc.closed_at_utc IS NULL), 0), 2)::numeric(12,2)
  INTO
    v_case_outstanding_amount,
    v_open_component_remaining_total
  FROM public.pay_advances AS pa
  LEFT JOIN public.pay_finance_case_components AS pfc
    ON pfc.finance_case_id = pa.id
  WHERE pa.id = p_finance_case_id
  GROUP BY pa.outstanding_amount;

  v_component_case_mismatch_amount := round(
    coalesce(v_case_outstanding_amount, 0) - coalesce(v_open_component_remaining_total, 0),
    2
  )::numeric(12,2);

  IF v_case_type IN (
       'OVERPAYMENT'::public.pay_finance_case_type_enum,
       'UNDERPAYMENT'::public.pay_finance_case_type_enum
     )
     AND abs(coalesce(v_component_case_mismatch_amount, 0)) > 0.01 THEN
    RAISE EXCEPTION 'PAY_FINANCE_COMPONENTS_CASE_OUTSTANDING_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_FINANCE_COMPONENTS_CASE_OUTSTANDING_MISMATCH',
              'finance_case_id', p_finance_case_id::text,
              'case_type', CASE WHEN v_case_type IS NULL THEN NULL ELSE v_case_type::text END,
              'case_outstanding_amount', coalesce(v_case_outstanding_amount, 0),
              'open_component_remaining_total', coalesce(v_open_component_remaining_total, 0),
              'mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
              'raw_input_component_count', coalesce(v_raw_input_component_count, 0),
              'input_component_count', coalesce(v_input_component_count, 0),
              'aggregated_duplicate_identity_count', coalesce(v_aggregated_duplicate_identity_count, 0),
              'case_active_consumed_amount', coalesce(v_case_active_consumed_amount, 0),
              'case_active_reserved_source_amount', coalesce(v_case_active_reserved_source_amount, 0),
              'message', 'Finance-case outstanding does not reconcile to the open component remaining-source total after component synchronisation.'
            )::text;
  END IF;

  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', pfc.id::text,
          'finance_case_id', pfc.finance_case_id::text,
          'candidate_id', pfc.candidate_id::text,
          'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
          'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
          'source_family_key', pfc.source_family_key,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
          'is_resolution_stale', pfc.is_resolution_stale,
          'stale_reason', pfc.stale_reason,
          'allocation_priority_group', pfc.allocation_priority_group,
          'allocation_priority_order', pfc.allocation_priority_order,
          'created_at_utc', pfc.created_at_utc,
          'updated_at_utc', pfc.updated_at_utc
        )
        ORDER BY
          pfc.source_family_key,
          pfc.allocation_priority_group,
          pfc.allocation_priority_order,
          pfc.component_key_type,
          pfc.component_key_value
      ),
      '[]'::jsonb
    )
  INTO
    v_open_components_json
  FROM public.pay_finance_case_components pfc
  WHERE pfc.finance_case_id = p_finance_case_id
    AND pfc.closed_at_utc IS NULL;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'inserted_count', v_inserted_count,
      'updated_count', v_updated_count,
      'reopened_count', v_reopened_count,
      'closed_count', v_closed_count,
      'stale_marked_count', v_stale_marked_count,
      'protected_skip_count', v_protected_skip_count,
      'active_reservation_deferred_count', v_active_reservation_deferred_count,
      'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
      'normalized_input_component_count', COALESCE(v_input_component_count, 0),
      'aggregated_duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0)
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'inserted_count', v_inserted_count,
    'updated_count', v_updated_count,
    'reopened_count', v_reopened_count,
    'closed_count', v_closed_count,
    'stale_marked_count', v_stale_marked_count,
    'protected_skip_count', v_protected_skip_count,
    'active_reservation_deferred_count', v_active_reservation_deferred_count,
    'raw_input_component_count', COALESCE(v_raw_input_component_count, 0),
    'normalized_input_component_count', COALESCE(v_input_component_count, 0),
    'aggregated_duplicate_identity_count', COALESCE(v_aggregated_duplicate_identity_count, 0),
    'case_outstanding_amount', coalesce(v_case_outstanding_amount, 0),
    'open_component_remaining_total', coalesce(v_open_component_remaining_total, 0),
    'component_case_mismatch_amount', coalesce(v_component_case_mismatch_amount, 0),
    'component_case_reconciled', abs(coalesce(v_component_case_mismatch_amount, 0)) <= 0.01,
    'open_components', v_open_components_json
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_finance_components',
      COALESCE(p_finance_case_id::text, 'NO_FINANCE_CASE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
END;
$function$;

-- [REPLACES] public.pay_preview_candidate_build_canonical_lines(p_context_json jsonb, p_candidate_id uuid)  winner piece A28
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_canonical_lines(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;

  v_workbench_session_id uuid := NULL::uuid;
  v_workbench_session_id_text text := NULL::text;
  v_line_materialise_limit integer := 100;
  v_line_materialise_result jsonb := '{}'::jsonb;
  v_workbench_line_source_mode text := NULL::text;
  v_workbench_classifier_only boolean := false;
  v_source_build_mode boolean := false;
  v_source_build_context_required boolean := false;
  v_collect_called_inside_canonical boolean := false;
  v_collect_recollect_attempted boolean := false;
  v_collect_recollect_blocked boolean := false;
  v_canonical_started_at timestamptz := clock_timestamp();
  v_canonical_elapsed_ms numeric := 0;
  v_semantic_ready_observe_enabled boolean := false;
  v_semantic_ready_publication_enabled boolean := false;
  v_allocation_segment_failure jsonb := '{}'::jsonb;
  -- A28 reconciliation slicing (final slice only; bound to the current Workbench build token)
  v_a28_slice jsonb := CASE WHEN COALESCE(current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true), '') ~ '^\s*\{'
    THEN current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true)::jsonb ELSE NULL::jsonb END;
  v_a28_slice_applies boolean := false;
  v_a28_slice_candidate_id uuid := NULL::uuid;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  SELECT
    COALESCE(settings_row.banking_pay_workbench_semantic_ready_observe_v2_enabled,false),
    COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled,false)
  INTO v_semantic_ready_observe_enabled,v_semantic_ready_publication_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;


  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_source_build_context_required := COALESCE(v_source_build_mode, false);


  v_workbench_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,session_id}',
    v_context_json#>>'{line_work,session_id}',
    ''
  )), '');

  IF v_workbench_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_session_id := v_workbench_session_id_text::uuid;
  END IF;

  IF COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_line_materialise_limit := LEAST(GREATEST(COALESCE(v_context_json->>'line_work_limit', v_context_json#>>'{line_work,limit}', v_context_json->>'limit')::integer, 1), 100);
  ELSE
    v_line_materialise_limit := 100;
  END IF;

  v_workbench_line_source_mode := UPPER(NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_line_source_mode',
    v_context_json->>'line_source_mode',
    v_context_json#>>'{line_work,source_mode}',
    v_context_json#>>'{workbench,line_source_mode}',
    ''
  )), ''));

  v_workbench_classifier_only := COALESCE(v_workbench_line_source_mode, '') IN (
    'CLASSIFY_ONLY',
    'CLASSIFIER_ONLY',
    'LINE_SOURCE_CLASSIFY_ONLY',
    'CANONICAL_CLASSIFY_ONLY'
  );

  IF v_workbench_session_id IS NOT NULL AND COALESCE(v_workbench_classifier_only, false) IS NOT TRUE AND COALESCE(v_source_build_mode, false) IS NOT TRUE THEN
    v_line_materialise_result := public.pay_workbench_preview_rows_materialise_chunk(
      p_session_id => v_workbench_session_id,
      p_candidate_id => v_candidate_id,
      p_cursor_json => COALESCE(
        v_context_json->'line_materialise_cursor',
        v_context_json->'line_work_cursor',
        v_context_json#>'{line_work,cursor}',
        NULL::jsonb
      ),
      p_limit => v_line_materialise_limit
    );

    RETURN jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'session_id', v_workbench_session_id::text,
      'row_backed_line_work', true,
      'canonical_display_rows_written', true,
      'canonical_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'ready_preview_line_count', COALESCE(NULLIF(BTRIM(COALESCE(v_line_materialise_result->>'materialised_count', '')), '')::integer, 0),
      'blocked_preview_line_count', 0,
      'hidden_recovery_template_line_count', 0,
      'manual_adjustment_carry_forward_line_count', 0,
      'next_cursor', v_line_materialise_result->'next_cursor',
      'has_more', COALESCE(NULLIF(v_line_materialise_result->>'has_more', '')::boolean, false),
      'materialise_result', COALESCE(v_line_materialise_result, '{}'::jsonb)
    );
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    v_collect_recollect_attempted := true;

    IF COALESCE(v_source_build_context_required, false) = true THEN
      v_collect_recollect_blocked := true;
      RAISE EXCEPTION 'SOURCE_BUILD_CANONICAL_REQUIRES_PRECOLLECTED_CONTEXT'
        USING DETAIL = 'WORKBENCH_CANDIDATE_SOURCE_BUILD canonical mode refuses to call pay_preview_candidate_collect_scope implicitly. Call pay_preview_candidate_collect_scope first with the bounded source-build payload.';
    END IF;

    v_collect_called_inside_canonical := true;
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.finance_case_resolution_rollup') is null then
    perform public.pay_preview_candidate_build_finance_case_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.hidden_recovery_template_lines, pg_temp.manual_adjustment_carry_forward_lines, pg_temp.timesheet_allocation_component_lines, pg_temp.semantic_finance_case_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup;

  create temporary table canonical_timesheet_lines on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tb.ts_booking_id as booking_id,
          tb.ts_role,
          tb.ts_band,
          tcr.client_id,
          tcr.ts_client_name as client_name,
          tcr.ts_week_ending_date as week_ending_date,
          tcr.ts_pay_method as source_pay_method,
          tcr.umb_vat_chargeable,
          cp.cand_pay_method as candidate_pay_method,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          cp.payee_bank_hash,
          cp.payee_name_check_status,
          cp.payee_name_check_has_override,
          cp.payee_map_present,
          coalesce(cp.blockers, '[]'::jsonb) as payee_blockers,
          (jsonb_array_length(coalesce(cp.blockers, '[]'::jsonb)) > 0) as has_payee_readiness_block,
          (cp.is_ready_for_draft and coalesce(tcr.is_blocked, false) = false) as is_ready_for_draft,
          ato.override_id,
          ato.override_reason,
          ats.snooze_id,
          ats.snooze_until_date,
          ats.note as snooze_note,
          round(coalesce(tcr.payment_amount_ex_vat,0),2) as amount_ex_vat,
          round(coalesce(tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, 0),2) as amount_display,
          coalesce(tcr.is_blocked, false) as case_is_blocked,
          coalesce(tcr.case_resolution_summary_json, '{}'::jsonb) as case_resolution_summary_json,
          coalesce(expense_components.expense_aware_case_components_json, tcr.case_components_json, '[]'::jsonb) as case_components_json,
          coalesce(expense_components.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(expense_components.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(expense_components.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(expense_components.ready_expense_count, 0) as ready_expense_count,
          coalesce(expense_components.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(expense_components.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(expense_components.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(expense_components.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                'segment_key', nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                'segment_stable_key', coalesce(
                  nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                ),
                'date', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')),
                'client_name', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'client_name','')), ''), tcr.ts_client_name),
                'role', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'role','')), ''), tb.ts_role),
                'band', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'band','')), ''), tb.ts_band),
                'start', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')),
                'finish', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'end_hhmm','')), '')),
                'start_utc', nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), ''),
                'end_utc', nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), ''),
                'break_start', nullif(btrim(coalesce(cur_seg.seg->>'break_start','')), ''),
                'break_end', nullif(btrim(coalesce(cur_seg.seg->>'break_end','')), ''),
                'break_mins', coalesce(nullif(cur_seg.seg->>'break_mins','')::numeric, nullif(cur_seg.seg->>'break_minutes','')::numeric),
                'breaks', coalesce(cur_seg.seg->'breaks', '[]'::jsonb),
                'ref_num', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')),
                'nhsp_shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'shift_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'shift_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'nhsp_shift_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'nhsp_shift_id','')), '')
                ),
                'external_row_key', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'external_row_key','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'external_row_key','')), '')
                ),
                'hr_request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'request_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'request_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'hr_request_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'hr_request_id','')), '')
                ),
                'source_system', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'source_system','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'source_system','')), '')
                ),
                'latest_import_id', coalesce(
                  nullif(btrim(coalesce(cur_seg.seg->>'latest_import_id','')), ''),
                  nullif(btrim(coalesce(delta_seg.seg->>'latest_import_id','')), '')
                ),
                'pay_amount_ex_vat', round(coalesce(nullif(delta_seg.seg->>'delta_pay_ex_vat','')::numeric,0),2),
                'snooze_identity', jsonb_build_object(
                  'identity_type', 'TIMESHEET_SEGMENT',
                  'timesheet_id', tcr.timesheet_id::text,
                  'booking_id', tb.ts_booking_id,
                  'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                  ),
                  'source_ref', null
                ),
                'snooze_state', case
                  when ass.snooze_id is null then jsonb_build_object('state','NONE')
                  when ass.snooze_until_date is null then jsonb_build_object(
                    'state', 'INDEFINITE_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', null,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                  else jsonb_build_object(
                    'state', 'DATED_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', ass.snooze_until_date::text,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                end
              )
              order by
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), '')) nulls last,
                nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') nulls last
            )
            from jsonb_array_elements(coalesce(tcr.segment_deltas_json, '[]'::jsonb)) as delta_seg(seg)
            left join lateral (
              select seg.value as seg
              from jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) as seg(value)
              where coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'date','')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num','')), '')
                    ) is not distinct from coalesce(
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_id','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')
                    )
              order by 1
              limit 1
            ) cur_seg on true
            left join active_segment_snoozes ass
              on ass.candidate_id = tcr.candidate_id
             and (
               (ass.booking_id is not null and ass.booking_id = tb.ts_booking_id and ass.segment_stable_key is not distinct from coalesce(
                 nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
               ))
               or (ass.booking_id is null and ass.timesheet_id = tcr.timesheet_id and ass.segment_id is not distinct from nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''))
             )
          ), '[]'::jsonb) as segment_rows_json
        from timesheet_case_rollup_effective tcr
        join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
        join ts_baseline tb
          on tb.timesheet_id = tcr.timesheet_id
         and tb.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_overrides ato
          on ato.timesheet_id = tcr.timesheet_id
         and ato.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_snoozes ats
          on ats.candidate_id = tcr.candidate_id
         and (
           (ats.booking_id is not null and ats.booking_id = tb.ts_booking_id)
           or (ats.booking_id is null and ats.timesheet_id = tcr.timesheet_id)
         )
        left join lateral (
          with component_rows as (
            select
              component_element.value as component_json,
              component_element.ordinality::integer as component_ordinal,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_type', '')), '')) as component_key_type,
              upper(nullif(btrim(coalesce(component_element.value->>'component_key_value', component_element.value#>>'{source_basis_json,expense_code}', '')), '')) as expense_code,
              case
                when jsonb_typeof(component_element.value->'source_basis_json') = 'object'
                  then coalesce(component_element.value->'source_basis_json', '{}'::jsonb)
                else '{}'::jsonb
              end as source_basis_json,
              lower(coalesce(
                nullif(btrim(coalesce(component_element.value->>'source_basis_fingerprint', '')), ''),
                md5(coalesce(component_element.value->'source_basis_json', '{}'::jsonb)::text)
              )) as source_basis_fingerprint,
              round(coalesce(
                case when coalesce(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                case when coalesce(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (component_element.value->>'target_pay_ex_vat')::numeric else null::numeric end,
                0::numeric
              ), 2) as component_amount_ex_vat
            from jsonb_array_elements(
              case
                when jsonb_typeof(tcr.case_components_json) = 'array' then coalesce(tcr.case_components_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) with ordinality as component_element(value, ordinality)
          ), expense_identity_rows as (
            select
              component_rows.*,
              (
                component_rows.component_key_type = 'EXPENSE_CODE'
                and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
              ) as is_expense_component,
              case
                when component_rows.component_key_type = 'EXPENSE_CODE'
                 and component_rows.expense_code in ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
                 and component_rows.source_basis_fingerprint ~ '^[0-9a-f]{32}$'
                then lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  component_rows.expense_code || ':' || component_rows.source_basis_fingerprint
                )
                else null::text
              end as expense_source_ref,
              case component_rows.expense_code
                when 'EXPENSES' then 'Expenses'
                when 'TRAVEL' then 'Travel'
                when 'ACCOMMODATION' then 'Accommodation'
                when 'OTHER' then 'Other'
                when 'MILEAGE' then 'Mileage'
                else null::text
              end as expense_label
            from component_rows
          ), enriched_rows as (
            select
              expense_identity_rows.*,
              exact_snooze.snooze_id as exact_snooze_id,
              exact_snooze.snooze_until_date as exact_snooze_until_date,
              exact_snooze.note as exact_snooze_note,
              exact_snooze.snooze_kind as exact_snooze_kind,
              stale_snooze.snooze_id as stale_snooze_id,
              stale_snooze.source_ref as stale_source_ref,
              stale_snooze.snooze_until_date as stale_snooze_until_date,
              stale_snooze.note as stale_snooze_note
            from expense_identity_rows
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.snooze_until_date,
                active_snooze.note,
                active_snooze.snooze_kind
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) = expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as exact_snooze on true
            left join lateral (
              select
                active_snooze.snooze_id,
                active_snooze.source_ref,
                active_snooze.snooze_until_date,
                active_snooze.note
              from active_snoozes as active_snooze
              where expense_identity_rows.is_expense_component
                and exact_snooze.snooze_id is null
                and active_snooze.candidate_id = tcr.candidate_id
                and active_snooze.timesheet_id = tcr.timesheet_id
                and active_snooze.source_ref is not null
                and lower(active_snooze.source_ref) like lower(
                  'timesheet-expense:' || tcr.timesheet_id::text || ':' ||
                  expense_identity_rows.expense_code || ':%'
                )
                and lower(active_snooze.source_ref) is distinct from expense_identity_rows.expense_source_ref
                and active_snooze.snooze_kind = 'DO_NOT_PAY'
              order by active_snooze.snooze_id
              limit 1
            ) as stale_snooze on true
          ), state_rows as (
            select
              enriched_rows.*,
              case
                when not enriched_rows.is_expense_component then 'NOT_EXPENSE'
                when enriched_rows.exact_snooze_id is not null and enriched_rows.exact_snooze_until_date is null then 'HIDDEN_INDEFINITE'
                when enriched_rows.exact_snooze_id is not null then 'BLOCKED_DATED'
                when enriched_rows.stale_snooze_id is not null then 'BLOCKED_STALE_IDENTITY'
                else 'READY'
              end as expense_presentation_state
            from enriched_rows
          )
          select
            coalesce(
              jsonb_agg(
                case
                  when state_rows.is_expense_component then
                    state_rows.component_json
                    || jsonb_build_object(
                      'expense_code', state_rows.expense_code,
                      'expense_label', state_rows.expense_label,
                      'expense_item_type', case when state_rows.expense_code = 'MILEAGE' then 'MILEAGE_DELTA' else 'EXPENSE_DELTA' end,
                      'source_ref', state_rows.expense_source_ref,
                      'source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_fingerprint', state_rows.source_basis_fingerprint,
                      'expense_source_basis_json', state_rows.source_basis_json
                    )
                    || jsonb_build_object(
                      'presentation_section', case
                        when state_rows.expense_presentation_state = 'READY' then 'READY_TO_PAY'
                        when state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY') then 'BLOCKED_FOR_PAY'
                        else 'INTERNAL_ONLY'
                      end,
                      'expense_presentation_state', state_rows.expense_presentation_state,
                      'draftable', (state_rows.expense_presentation_state = 'READY'),
                      'is_ready_for_draft', (state_rows.expense_presentation_state = 'READY'),
                      'is_excluded_from_allocation', (state_rows.expense_presentation_state <> 'READY'),
                      'selection_allowed', (state_rows.expense_presentation_state = 'READY'),
                      'expense_identity_stale', (state_rows.expense_presentation_state = 'BLOCKED_STALE_IDENTITY')
                    )
                    || jsonb_build_object(
                      'snooze_identity', jsonb_build_object(
                        'identity_type', 'TIMESHEET_EXPENSE',
                        'timesheet_id', tcr.timesheet_id::text,
                        'booking_id', tb.ts_booking_id,
                        'segment_id', null,
                        'segment_stable_key', null,
                        'source_ref', state_rows.expense_source_ref,
                        'expense_code', state_rows.expense_code,
                        'source_basis_fingerprint', state_rows.source_basis_fingerprint
                      ),
                      'snooze_state', case
                        when state_rows.exact_snooze_id is null and state_rows.stale_snooze_id is null
                          then jsonb_build_object('state', 'NONE')
                        when state_rows.exact_snooze_id is not null and state_rows.exact_snooze_until_date is null
                          then jsonb_build_object(
                            'state', 'INDEFINITE_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', null,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        when state_rows.exact_snooze_id is not null
                          then jsonb_build_object(
                            'state', 'DATED_SNOOZED',
                            'snooze_id', state_rows.exact_snooze_id::text,
                            'snooze_until_date', state_rows.exact_snooze_until_date::text,
                            'note', state_rows.exact_snooze_note,
                            'snooze_kind', state_rows.exact_snooze_kind
                          )
                        else jsonb_build_object(
                          'state', 'STALE_SOURCE_IDENTITY',
                          'snooze_id', state_rows.stale_snooze_id::text,
                          'snooze_until_date', case when state_rows.stale_snooze_until_date is null then null else state_rows.stale_snooze_until_date::text end,
                          'note', state_rows.stale_snooze_note,
                          'stale_source_ref', state_rows.stale_source_ref,
                          'refresh_required', true
                        )
                      end
                    )
                  else state_rows.component_json
                end
                order by state_rows.component_ordinal
              ),
              '[]'::jsonb
            ) as expense_aware_case_components_json,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            ), 0), 2) as ready_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            ), 0), 2) as blocked_expense_amount_ex_vat,
            round(coalesce(sum(state_rows.component_amount_ex_vat) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            ), 0), 2) as hidden_expense_amount_ex_vat,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'READY'
            )::integer as ready_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state in ('BLOCKED_DATED', 'BLOCKED_STALE_IDENTITY')
            )::integer as blocked_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.expense_presentation_state = 'HIDDEN_INDEFINITE'
            )::integer as hidden_expense_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.exact_snooze_id is not null
            )::integer as active_expense_snooze_count,
            count(*) filter (
              where state_rows.is_expense_component and state_rows.stale_snooze_id is not null
            )::integer as stale_expense_identity_count
          from state_rows
        ) as expense_components on true
        -- Protected presentation authority is built for every authoritative
        -- target. Public eligibility is applied only when final lines are
        -- emitted below, so zero-net and indefinitely snoozed targets remain
        -- attestable without becoming public economic rows.

  ;

  create temporary table timesheet_active_segment_snooze_meta on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          count(*)::int as active_segment_snooze_count,
          count(*) filter (where ass.snooze_until_date is not null)::int as active_segment_dated_snooze_count,
          count(*) filter (where ass.snooze_until_date is null)::int as active_segment_indefinite_snooze_count
        from canonical_timesheet_lines ctl
        join active_segment_snoozes ass
          on ass.candidate_id = ctl.candidate_id
         and (
           (ass.booking_id is not null and ctl.booking_id is not null and ass.booking_id = ctl.booking_id)
           or (ass.booking_id is null and ass.timesheet_id = ctl.timesheet_id)
         )
        group by ctl.candidate_id, ctl.timesheet_id, ctl.booking_id

  ;

  create temporary table canonical_timesheet_segment_rows on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          cur_seg_norm.seg_ord,
          cur_seg_norm.segment_id,
          cur_seg_norm.segment_key,
          cur_seg_norm.segment_stable_key,
          cur_seg_norm.segment_date,
          cur_seg_norm.client_name,
          cur_seg_norm.role,
          cur_seg_norm.band,
          cur_seg_norm.start_hhmm,
          cur_seg_norm.finish_hhmm,
          cur_seg_norm.start_utc,
          cur_seg_norm.end_utc,
          cur_seg_norm.break_start,
          cur_seg_norm.break_end,
          cur_seg_norm.break_mins,
          cur_seg_norm.breaks,
          coalesce(cur_seg_norm.ref_num, ss_match.ref_num) as ref_num,
          round(
            case
              when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
              when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
              else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
            end,
            2
          ) as presentation_amount_ex_vat,
          round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) as raw_delta_ex_vat,
          round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) as effective_delta_ex_vat,
          coalesce(ss_match.is_blocked, false) as status_is_blocked,
          coalesce(ss_match.is_do_not_pay, false) as status_is_do_not_pay,
          ass_match.snooze_id as segment_snooze_id,
          ass_match.snooze_until_date as segment_snooze_until_date,
          ass_match.note as segment_snooze_note,
          ass_match.snooze_kind as segment_snooze_kind,
          case
            when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
            when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_blocked, false) = true
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'BLOCKED_VISIBLE'
            when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'READY'
            else 'IGNORED'
          end as presentation_segment_state,
          jsonb_build_object(
            'timesheet_id', ctl.timesheet_id::text,
            'booking_id', ctl.booking_id,
            'segment_id', cur_seg_norm.segment_id,
            'segment_key', cur_seg_norm.segment_key,
            'segment_stable_key', cur_seg_norm.segment_stable_key,
            'date', cur_seg_norm.segment_date,
            'client_name', cur_seg_norm.client_name,
            'role', cur_seg_norm.role,
            'band', cur_seg_norm.band,
            'start', cur_seg_norm.start_hhmm,
            'finish', cur_seg_norm.finish_hhmm,
            'start_utc', cur_seg_norm.start_utc,
            'end_utc', cur_seg_norm.end_utc,
            'break_start', cur_seg_norm.break_start,
            'break_end', cur_seg_norm.break_end,
            'break_mins', cur_seg_norm.break_mins,
            'breaks', cur_seg_norm.breaks,
            'ref_num', coalesce(cur_seg_norm.ref_num, ss_match.ref_num),
            'nhsp_shift_id', cur_seg_norm.nhsp_shift_id,
            'shift_id', cur_seg_norm.shift_id,
            'external_row_key', cur_seg_norm.external_row_key,
            'hr_request_id', cur_seg_norm.hr_request_id,
            'request_id', cur_seg_norm.request_id,
            'source_system', cur_seg_norm.source_system,
            'latest_import_id', cur_seg_norm.latest_import_id,
            'pay_amount_ex_vat', round(
              case
                when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
                when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
                else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
              end,
              2
            ),
            'raw_delta_ex_vat', round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2),
            'effective_delta_ex_vat', round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2),
            'is_blocked', coalesce(ss_match.is_blocked, false),
            'is_do_not_pay', coalesce(ss_match.is_do_not_pay, false),
            'presentation_segment_state', case
              when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
              when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_blocked, false) = true
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'BLOCKED_VISIBLE'
              when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'READY'
              else 'IGNORED'
            end,
            'is_ready_segment', (
              ass_match.snooze_id is null
              and coalesce(ss_match.is_blocked, false) = false
              and coalesce(ss_match.is_do_not_pay, false) = false
              and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              and round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
            ),
            'is_blocked_visible_segment', (
              (ass_match.snooze_id is not null and ass_match.snooze_until_date is not null)
              or (
                coalesce(ss_match.is_blocked, false) = true
                and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              )
              or coalesce(ss_match.is_do_not_pay, false) = true
            ),
            'is_hidden_indefinite_segment', (ass_match.snooze_id is not null and ass_match.snooze_until_date is null),
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', ctl.timesheet_id::text,
              'booking_id', ctl.booking_id,
              'segment_id', cur_seg_norm.segment_id,
              'segment_stable_key', cur_seg_norm.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', case
              when ass_match.snooze_id is null then jsonb_build_object('state', 'NONE')
              when ass_match.snooze_until_date is null then jsonb_build_object(
                'state', 'INDEFINITE_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', null,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
              else jsonb_build_object(
                'state', 'DATED_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', ass_match.snooze_until_date::text,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
            end
          ) as segment_base_json
        from canonical_timesheet_lines ctl
        join ts_baseline tb
          on tb.timesheet_id = ctl.timesheet_id
         and tb.candidate_id = ctl.candidate_id
        cross join lateral jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg_json, seg_ord)
        cross join lateral (
          select
            cur_seg.seg_ord,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), '') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), '') as segment_key,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_stable_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '')
            ) as segment_stable_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), '') as segment_date,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'client_name','')), ''), ctl.client_name) as client_name,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'role','')), ''), ctl.ts_role) as role,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'band','')), ''), ctl.ts_band) as band,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'start_hhmm','')), '')) as start_hhmm,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'end_hhmm','')), '')) as finish_hhmm,
            nullif(btrim(coalesce(cur_seg.seg_json->>'start_utc','')), '') as start_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'end_utc','')), '') as end_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_start','')), '') as break_start,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_end','')), '') as break_end,
            coalesce(nullif(cur_seg.seg_json->>'break_mins','')::numeric, nullif(cur_seg.seg_json->>'break_minutes','')::numeric) as break_mins,
            case when jsonb_typeof(cur_seg.seg_json->'breaks') = 'array' then cur_seg.seg_json->'breaks' else '[]'::jsonb end as breaks,
            nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '') as ref_num,
            nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '') as nhsp_shift_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'shift_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'nhsp_shift_id','')), '')
            ) as shift_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'external_row_key','')), '') as external_row_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '') as hr_request_id,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'request_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'hr_request_id','')), '')
            ) as request_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'source_system','')), '') as source_system,
            nullif(btrim(coalesce(cur_seg.seg_json->>'latest_import_id','')), '') as latest_import_id
        ) cur_seg_norm
        left join lateral (
          select
            ss.segment_id,
            ss.segment_stable_key,
            ss.ref_num,
            ss.work_date,
            ss.delta_pay_ex_vat,
            ss.eff_delta_ex,
            ss.is_blocked,
            ss.is_do_not_pay
          from segment_status ss
          where ss.candidate_id = ctl.candidate_id
            and ss.timesheet_id = ctl.timesheet_id
            and (
              (cur_seg_norm.segment_stable_key is not null and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and ss.segment_id is not distinct from cur_seg_norm.segment_id
              )
            )
          order by
            case
              when cur_seg_norm.segment_stable_key is not null
               and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key
              then 0 else 1
            end,
            case
              when cur_seg_norm.segment_id is not null
               and ss.segment_id is not distinct from cur_seg_norm.segment_id
              then 0 else 1
            end,
            ss.segment_stable_key nulls last,
            ss.segment_id nulls last
          limit 1
        ) ss_match on true
        left join lateral (
          select
            round(sum(coalesce(ttre.preview_component_amount_ex_vat, 0)), 2) as preview_component_amount_ex_vat,
            round(sum(coalesce(ttre.ready_preview_amount_ex_vat, ttre.preview_component_amount_ex_vat, 0)), 2) as ready_preview_amount_ex_vat,
            bool_or(coalesce(ttre.requires_resolution, false)) as requires_resolution,
            bool_or(coalesce(ttre.is_actionable_resolution_row, false)) as is_actionable_resolution_row
          from transient_timesheet_component_review_rows_effective ttre
          where ttre.candidate_id = ctl.candidate_id
            and ttre.timesheet_id = ctl.timesheet_id
            and ttre.component_key_type in ('TS_DAY','TS_TOTAL')
            and (
              (
                cur_seg_norm.segment_stable_key is not null
                and coalesce(
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'work_date','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'ref_num','')), '')
                ) is not distinct from cur_seg_norm.segment_stable_key
              )
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), '') is not distinct from cur_seg_norm.segment_id
              )
            )
        ) ttre_match on true
        left join lateral (
          select
            ass.snooze_id,
            ass.snooze_until_date,
            ass.note,
            ass.snooze_kind,
            ass.segment_id,
            ass.segment_stable_key
          from active_segment_snoozes ass
          where ass.candidate_id = ctl.candidate_id
            and (
              (
                ass.booking_id is not null
                and ctl.booking_id is not null
                and ass.booking_id = ctl.booking_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
              or (
                ass.booking_id is null
                and ass.timesheet_id = ctl.timesheet_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
            )
          order by
            case when ass.segment_stable_key is not null then 0 else 1 end,
            ass.snooze_id
          limit 1
        ) ass_match on true
        where (
          ass_match.snooze_id is not null
          or coalesce(ss_match.is_blocked, false) = true
          or coalesce(ss_match.is_do_not_pay, false) = true
          or round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
          or round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) <> 0
        )

  ;

  create temporary table canonical_timesheet_segment_rollup on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          coalesce(tasm.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(tasm.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(tasm.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          count(*) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE'))::int as total_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'READY')::int as ready_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE')::int as blocked_visible_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE')::int as hidden_indefinite_segment_count,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'READY' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as ready_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'BLOCKED_VISIBLE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as blocked_visible_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'READY'),
            '[]'::jsonb
          ) as ready_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE'),
            '[]'::jsonb
          ) as blocked_visible_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE')),
            '[]'::jsonb
          ) as visible_segment_rows_json
        from canonical_timesheet_lines ctl
        left join timesheet_active_segment_snooze_meta tasm
          on tasm.candidate_id = ctl.candidate_id
         and tasm.timesheet_id = ctl.timesheet_id
         and tasm.booking_id is not distinct from ctl.booking_id
        left join canonical_timesheet_segment_rows ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
        group by
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.snooze_id,
          tasm.active_segment_snooze_count,
          tasm.active_segment_dated_snooze_count,
          tasm.active_segment_indefinite_snooze_count

  ;

  create temporary table canonical_timesheet_presentation_seed on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.ts_role,
          ctl.ts_band,
          ctl.client_id,
          ctl.client_name,
          ctl.week_ending_date,
          ctl.source_pay_method,
          ctl.umb_vat_chargeable,
          ctl.candidate_pay_method,
          ctl.cand_tms_ref,
          ctl.cand_display_name,
          ctl.payee_entity_kind,
          ctl.payee_entity_id,
          ctl.payee_bank_hash,
          ctl.payee_name_check_status,
          ctl.payee_name_check_has_override,
          ctl.payee_map_present,
          coalesce(ctl.payee_blockers, '[]'::jsonb) as payee_blockers,
          coalesce(ctl.has_payee_readiness_block, false) as has_payee_readiness_block,
          ctl.is_ready_for_draft,
          ctl.override_id,
          ctl.override_reason,
          ctl.snooze_id,
          ctl.snooze_until_date,
          ctl.snooze_note,
          ctl.amount_ex_vat,
          ctl.amount_display,
          ctl.case_is_blocked,
          ctl.case_resolution_summary_json,
          ctl.case_components_json,
          coalesce(ctl.ready_expense_amount_ex_vat, 0) as ready_expense_amount_ex_vat,
          coalesce(ctl.blocked_expense_amount_ex_vat, 0) as blocked_expense_amount_ex_vat,
          coalesce(ctl.hidden_expense_amount_ex_vat, 0) as hidden_expense_amount_ex_vat,
          coalesce(ctl.ready_expense_count, 0) as ready_expense_count,
          coalesce(ctl.blocked_expense_count, 0) as blocked_expense_count,
          coalesce(ctl.hidden_expense_count, 0) as hidden_expense_count,
          coalesce(ctl.active_expense_snooze_count, 0) as active_expense_snooze_count,
          coalesce(ctl.stale_expense_identity_count, 0) as stale_expense_identity_count,
          coalesce(ctsr.total_segment_count, 0) as total_segment_count,
          coalesce(ctsr.ready_segment_count, 0) as ready_segment_count,
          coalesce(ctsr.blocked_visible_segment_count, 0) as blocked_visible_segment_count,
          coalesce(ctsr.hidden_indefinite_segment_count, 0) as hidden_indefinite_segment_count,
          coalesce(ctsr.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(ctsr.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(ctsr.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          coalesce(ctsr.ready_segment_amount_ex_vat, 0) as ready_segment_amount_ex_vat,
          coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0) as blocked_visible_segment_amount_ex_vat,
          coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(ctsr.ready_segment_rows_json, '[]'::jsonb) as ready_segment_rows_json,
          coalesce(ctsr.blocked_visible_segment_rows_json, '[]'::jsonb) as blocked_visible_segment_rows_json,
          coalesce(ctsr.visible_segment_rows_json, '[]'::jsonb) as visible_segment_rows_json,
          (
            coalesce(ctsr.total_segment_count, 0) > 0
            and (
              lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
              or (
                coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
              )
            )
          ) as resolved_segment_rows_replace_source_total,
          case
            when coalesce(ctsr.total_segment_count, 0) > 0
             and (
               lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
               or (
                 coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count', '') ~ '^[0-9]+$'
                 and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
               )
             ) then round(coalesce(ctl.ready_expense_amount_ex_vat, 0), 2)
            else round(
              coalesce(ctl.amount_ex_vat, 0)
              - coalesce(ctsr.ready_segment_amount_ex_vat, 0)
              - coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0)
              - coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0)
              - coalesce(ctl.blocked_expense_amount_ex_vat, 0)
              - coalesce(ctl.hidden_expense_amount_ex_vat, 0),
              2
            )
          end as non_segment_amount_ex_vat,
          (ctl.snooze_id is not null) as has_active_timesheet_snooze,
          (coalesce(ctsr.active_segment_snooze_count, 0) > 0) as has_active_segment_snoozes
        from canonical_timesheet_lines ctl
        left join canonical_timesheet_segment_rollup ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
         and ctsr.booking_id is not distinct from ctl.booking_id

  ;

  create temporary table canonical_timesheet_presentation_state on commit drop as
        select
          ctps.*,
          coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) as case_needs_resolution,
          exists (
            select 1
            from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as case_component(value)
            where coalesce(nullif(case_component.value->>'requires_resolution','')::boolean, false) = true
              and coalesce(nullif(case_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
          ) as has_actionable_resolution_component,
          round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) as ready_section_amount_ex_vat,
          round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2) as blocked_section_amount_ex_vat,
          round(
            coalesce(
              nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
              0::numeric
            ),
            2
          ) as case_resolution_section_amount_ex_vat,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2),
                  v_vat_rate_pct,
                  ctps.umb_vat_chargeable
                )->>'inc')::numeric
              else round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2)
            end,
            2
          ) as ready_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2), v_vat_rate_pct, ctps.umb_vat_chargeable)->>'inc')::numeric
              else round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0) + coalesce(ctps.blocked_expense_amount_ex_vat, 0), 2)
            end,
            2
          ) as blocked_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(
                round(
                  coalesce(
                    nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                    0::numeric
                  ),
                  2
                ),
                v_vat_rate_pct,
                ctps.umb_vat_chargeable
              )->>'inc')::numeric
              else round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              )
            end,
            2
          ) as case_resolution_section_amount_display,
          (
            round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
            or coalesce(ctps.ready_segment_count, 0) > 0
          ) as has_ready_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.is_ready_for_draft = false
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
            and (
              ctps.case_is_blocked = false
              or coalesce(ctps.has_payee_readiness_block, false) = true
            )
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
          ) as has_non_resolution_readiness_block,
          (
            ctps.has_active_timesheet_snooze = true
            or coalesce(ctps.blocked_visible_segment_count, 0) > 0
            or coalesce(ctps.blocked_expense_count, 0) > 0
            or (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_blocked_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = true
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = true
            and (
              round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              ) <> 0
              or exists (
                select 1
                from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as actionable_component(value)
                where coalesce(nullif(actionable_component.value->>'requires_resolution','')::boolean, false) = true
                  and coalesce(nullif(actionable_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
              )
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) = 0
            and not (
              ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                ctps.case_is_blocked = false
                or coalesce(ctps.has_payee_readiness_block, false) = true
              )
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_case_resolution_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_ready,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and (coalesce(ctps.blocked_visible_segment_count, 0) > 0 or coalesce(ctps.blocked_expense_count, 0) > 0)
          ) as is_partially_blocked
        from canonical_timesheet_presentation_seed ctps

  ;

  create temporary table canonical_timesheet_presentation_rows on commit drop as
        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'amount_display', ctpp.ready_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', ctpp.is_ready_for_draft,
              'segment_rows', ctpp.ready_segment_rows_json,
              'segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb))
            )
            || jsonb_build_object(
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'section_amount_display', ctpp.ready_section_amount_display,
              'section_segment_rows', ctpp.ready_segment_rows_json,
              'section_segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)),
              'section_non_segment_amount_ex_vat', ctpp.non_segment_amount_ex_vat,
              'resolved_segment_rows_replace_source_total', coalesce(ctpp.resolved_segment_rows_replace_source_total, false)
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.is_partially_ready then 'PARTIAL_READY_TO_PAY'
                when ctpp.hidden_indefinite_segment_count > 0 then 'READY_WITH_HIDDEN_INDEFINITE_SEGMENTS'
                else 'READY_TO_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_ready and ctpp.blocked_visible_segment_count > 0 and ctpp.blocked_expense_count > 0 then 'Some segments and expenses are blocked'
                when ctpp.is_partially_ready and ctpp.blocked_expense_count > 0 then 'Some expenses are blocked'
                when ctpp.is_partially_ready then 'Some segments are blocked'
                when ctpp.hidden_indefinite_segment_count > 0 and ctpp.hidden_expense_count > 0 then 'Some segments and expenses are snoozed indefinitely'
                when ctpp.hidden_expense_count > 0 then 'Some expenses are snoozed indefinitely'
                when ctpp.hidden_indefinite_segment_count > 0 then 'Some segments are snoozed indefinitely'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.ready_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_active_timesheet_snooze = false
          and ctpp.case_is_blocked = false
          and ctpp.has_ready_presentation = true
          and ctpp.is_ready_for_draft = true
          and round(coalesce(ctpp.amount_ex_vat,0),2) <> 0
        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', (ctpp.timesheet_id::text || ':03:case'),
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'amount_display', ctpp.case_resolution_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', case
                when jsonb_typeof(ctpp.case_resolution_summary_json->'blocked_reason_codes') = 'array'
                then coalesce(ctpp.case_resolution_summary_json->'blocked_reason_codes', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', false,
              'segment_rows', '[]'::jsonb,
              'segment_count', 0
            )
            || jsonb_build_object(
              'presentation_section', 'CASES_RESOLUTIONS',
              'presentation_role', 'PARENT',
              'presentation_line_id', (ctpp.timesheet_id::text || ':03:case'),
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', false,
              'is_partially_blocked', false,
              'section_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'section_amount_display', ctpp.case_resolution_section_amount_display,
              'section_segment_rows', '[]'::jsonb,
              'section_segment_count', 0,
              'section_non_segment_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
              'presentation_advisory_text', 'Resolve this case before draft'
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.case_resolution_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_case_resolution_presentation = true


        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'payee_entity_kind', ctpp.payee_entity_kind,
              'payee_entity_id', case when ctpp.payee_entity_id is null then null else ctpp.payee_entity_id::text end,
              'payee_bank_hash', ctpp.payee_bank_hash,
              'bank_details_hash', ctpp.payee_bank_hash,
              'name_check_status', ctpp.payee_name_check_status,
              'name_check_has_override', ctpp.payee_name_check_has_override,
              'payee_map_present', ctpp.payee_map_present,
              'blockers', coalesce(ctpp.payee_blockers, '[]'::jsonb),
              'payee_blockers', coalesce(ctpp.payee_blockers, '[]'::jsonb)
            )
            || jsonb_build_object(
              'amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', (
                coalesce(ctpp.payee_blockers, '[]'::jsonb)
                ||
                (case
                  when ctpp.has_active_timesheet_snooze = true then jsonb_build_array('BLOCKED_DATED_SNOOZE')
                  else '[]'::jsonb
                end)
              ),
              'is_excluded_from_allocation', (ctpp.has_active_timesheet_snooze = true),
              'is_ready_for_draft', case
                when ctpp.has_active_timesheet_snooze = true then ctpp.is_ready_for_draft
                else false
              end,
              'segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end
            )
            || jsonb_build_object(
              'presentation_section', 'BLOCKED_FOR_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'section_amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'section_segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'section_segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end,
              'section_non_segment_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.non_segment_amount_ex_vat
                else coalesce(ctpp.blocked_expense_amount_ex_vat, 0)
              end
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.has_active_timesheet_snooze = true then 'WHOLE_TIMESHEET_SNOOZED'
                when ctpp.is_partially_blocked then 'PARTIAL_BLOCKED_FOR_PAY'
                else 'BLOCKED_FOR_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_blocked and ctpp.ready_segment_count > 0 and ctpp.ready_expense_count > 0 then 'Some segments and expenses are ready to pay'
                when ctpp.is_partially_blocked and ctpp.ready_expense_count > 0 then 'Some expenses are ready to pay'
                when ctpp.is_partially_blocked then 'Some segments are ready to pay'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          case
            when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
            else ctpp.blocked_section_amount_ex_vat
          end as amount_ex_vat,
          (ctpp.has_active_timesheet_snooze = true) as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_blocked_presentation = true
          and round(coalesce(ctpp.amount_ex_vat,0),2) <> 0
          and not (ctpp.snooze_id is not null and ctpp.snooze_until_date is null)
          and (
            ctpp.has_active_timesheet_snooze = true
            or ctpp.has_non_resolution_readiness_block = true
            or ctpp.blocked_visible_segment_count > 0
            or ctpp.blocked_expense_count > 0
          )


  ;

  -- An aggregate ordinary timesheet parent is presentation evidence, not an
  -- independently payable economic component.  Negative parents without an
  -- actionable case were previously left under READY_TO_PAY and only made
  -- non-selectable later by the strict line contract.  That was structurally
  -- safe but visually false: a negative payment cannot be paid.  Move the
  -- single parent row to Blocked while retaining its exact amount and lineage.
  UPDATE canonical_timesheet_presentation_rows AS presentation_row
  SET
    line_json = presentation_row.line_json
      || pg_catalog.jsonb_build_object(
        'presentation_section', 'BLOCKED_FOR_PAY',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NEGATIVE_ORDINARY_PRESENTATION_ONLY',
        'presentation_advisory_text', 'Negative ordinary entitlement cannot be paid directly',
        'blocked_reason_codes', COALESCE(presentation_row.line_json->'blocked_reason_codes', '[]'::jsonb)
          || pg_catalog.jsonb_build_array('NEGATIVE_ORDINARY_PRESENTATION_ONLY'),
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true
      ),
    is_excluded_from_allocation = true
  WHERE pg_catalog.upper(COALESCE(presentation_row.line_json->>'line_type', '')) = 'TIMESHEET_PAYMENT'
    AND pg_catalog.upper(COALESCE(presentation_row.line_json->>'presentation_role', '')) = 'PARENT'
    AND pg_catalog.upper(COALESCE(presentation_row.line_json->>'presentation_section', '')) = 'READY_TO_PAY'
    AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
      presentation_row.line_json->'case_resolution_summary'->>'case_needs_resolution',
      'false'
    ))) NOT IN ('true','t','1','yes','y','on')
    AND pg_catalog.round(COALESCE(presentation_row.amount_ex_vat, 0), 2) < 0;

  create temporary table finance_case_lines on commit drop as
        select
          fcrr.candidate_id,
          fcrr.finance_case_id,
          fcrr.client_id,
          fcrr.client_name,
          fcrr.candidate_pay_method,
          fcrr.cand_tms_ref,
          fcrr.cand_display_name,
          fcrr.payee_entity_kind,
          fcrr.payee_entity_id,
          fcrr.candidate_ready_for_draft,
          fcrr.case_type,
          fcrr.taxability,
          fcrr.routing_kind,
          fcrr.destination_label,
          fcrr.beneficiary_name,
          fcrr.masked_bank_account,
          fcrr.payee_bank_hash,
          fcrr.adjustment_comment,
          fcrr.linked_timesheet_id,
          fcrr.linked_shift_date,
          fcrr.next_due_week_start,
          fcrr.active_snooze_id,
          fcrr.active_snooze_kind,
          fcrr.active_snooze_until_date,
          fcrr.active_snooze_note,
          round(coalesce(fcrr.due_amount_ex_vat, 0), 2) as due_amount_ex_vat,
          coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) as nominal_due_amount_ex_vat,
          round(coalesce(finance_case_baseline.outstanding_amount, 0), 2)
            as recovery_source_outstanding_ex_vat,
          round(coalesce(finance_case_baseline.active_reserved_amount, 0), 2)
            as recovery_active_reserved_ex_vat,
          finance_due_meta.recovery_created_at_utc as semantic_recovery_sort_at_utc,
          fcrr.is_blocked as case_is_blocked,
          (
            coalesce(fcrr.blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is null then jsonb_build_array('BLOCKED_INDEFINITE_SNOOZE')
              when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then jsonb_build_array('BLOCKED_DATED_SNOOZE')
              else '[]'::jsonb
            end)
            ||
            (case
              when round(coalesce(fcrr.due_amount_ex_vat, 0), 2) = 0
               and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0
               and fcrr.case_type in (
                 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                 'OVERPAYMENT'::public.pay_finance_case_type_enum,
                 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
               ) then jsonb_build_array('NO_PAY_HEADROOM')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          fcrr.case_resolution_summary_json,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'finance_resolution_clearability_state', 'NOT_REQUIRED'))) as finance_resolution_clearability_state,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_family', ''))) as current_saved_resolution_family,
          upper(btrim(coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_owner_kind', 'NONE'))) as current_saved_resolution_owner_kind,
          nullif(btrim(coalesce(fcrr.case_resolution_summary_json->>'finance_resolution_clear_block_reason', '')), '') as finance_resolution_clear_block_reason,
          case
            when coalesce(fcrr.case_resolution_summary_json->>'current_saved_resolution_linked_timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then (fcrr.case_resolution_summary_json->>'current_saved_resolution_linked_timesheet_id')::uuid
            else null::uuid
          end as current_saved_resolution_linked_timesheet_id,
          fcrr.taxable_manual_debt_resolution_json,
          fcrr.case_components_json,
          fcrr.oneoff_bank_details_present,
          fcrr.is_candidate_directed_oneoff_payout,
          fcrr.appears_on_umbrella_remittance,
          fcrr.generates_candidate_payment_advice,
          fcrr.snooze_allowed,
          fcrr.lifecycle_status_display,
          finance_case_baseline.payout_status as source_payout_status,
          component_identity.component_count,
          component_identity.finance_component_id,
          component_identity.component_key_type,
          component_identity.component_key_value,
          component_identity.component_classification,
          component_identity.component_source_basis_json,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(finance_case_baseline.payout_status::text,'')) <> 'PAID' then 'LOAN_PAYOUT'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'PAYMENT_ADVANCE_REPAYMENT'
            when fcrr.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrr.case_type = 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrr.case_type::text
          end as line_type,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(finance_case_baseline.payout_status::text,'')) <> 'PAID' then 'Loan payment'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'Loan repayment'
            when fcrr.case_type = 'OVERPAYMENT' then 'Overpayment recovery'
            when fcrr.case_type = 'UNDERPAYMENT' then 'Underpayment payment'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual credit adjustment payment'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            else replace(fcrr.case_type::text, '_', ' ')
          end as item_type_label,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(finance_case_baseline.payout_status::text,'')) <> 'PAID' then 'PAYMENT'
            when fcrr.case_type = 'UNDERPAYMENT' then 'PAYMENT'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'PAYMENT'
            else 'DEDUCTION'
          end as item_direction,
          case
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
             and upper(coalesce(finance_case_baseline.payout_status::text,'')) <> 'PAID'
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'UNDERPAYMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'UNDERPAYMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            else 'NONE'
          end as paye_treatment,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(finance_case_baseline.payout_status::text,'')) <> 'PAID' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            when fcrr.case_type = 'UNDERPAYMENT' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            else round(-coalesce(fcrr.due_amount_ex_vat,0),2)
          end as signed_amount_ex_vat,
          case
            when fcrr.active_snooze_id is not null then 'BLOCKED_FOR_PAY'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASES_RESOLUTIONS'
            when fcrr.is_blocked then 'BLOCKED_FOR_PAY'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 then 'BLOCKED_FOR_PAY'
            else 'READY_TO_PAY'
          end as readiness_state,
          case
            when fcrr.active_snooze_id is not null then 'BLOCKED_FOR_PAY'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASES_RESOLUTIONS'
            when fcrr.is_blocked then 'BLOCKED_FOR_PAY'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 then 'BLOCKED_FOR_PAY'
            else 'READY_TO_PAY'
          end as presentation_section,
          case
            when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
            when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then 'DATED_SNOOZE'
            when lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') then 'CASE_RESOLUTION_REQUIRED'
            when fcrr.is_blocked then 'CASE_BLOCKED'
            when round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0 and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0 then 'NO_PAY_HEADROOM'
            else 'READY_TO_PAY'
          end as presentation_reason,
          lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_resolution_satisfied_now', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') as is_case_resolution_satisfied,
          lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on') as case_needs_resolution_now,
          (
            fcrr.is_blocked = false
            and fcrr.active_snooze_id is null
            and lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) not in ('true', 't', '1', 'yes', 'y', 'on')
            and round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
          ) as draftable
        from finance_case_resolution_rollup fcrr
        left join finance_case_baseline_scope finance_case_baseline
          on finance_case_baseline.finance_case_id = fcrr.finance_case_id
         and finance_case_baseline.candidate_id = fcrr.candidate_id
        left join lateral (
          select
            round(coalesce(max(fcrrb.nominal_due_amount), 0), 2) as nominal_due_amount_ex_vat,
            min(fcrrb.created_at) as recovery_created_at_utc
          from finance_case_recovery_rows_base fcrrb
          where fcrrb.finance_case_id = fcrr.finance_case_id
        ) finance_due_meta on true
        left join lateral (
          with component_rows as (
            select
              component_element.value as component_json,
              component_element.ordinality
            from jsonb_array_elements(
              case
                when jsonb_typeof(coalesce(fcrr.case_components_json, '[]'::jsonb)) = 'array' then coalesce(fcrr.case_components_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) with ordinality as component_element(value, ordinality)
            where component_element.value is not null
              and jsonb_typeof(component_element.value) = 'object'
          )
          select
            count(*)::integer as component_count,
            case
              when count(*) = 1
               and (array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'finance_component_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then ((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'finance_component_id')::uuid
              else null::uuid
            end as finance_component_id,
            coalesce(
              case when count(*) = 1 then upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'component_key_type', '')), '')) else null::text end,
              case when fcrr.linked_timesheet_id is not null then 'TS_TOTAL' else 'ADJUSTMENT_CODE' end
            ) as component_key_type,
            coalesce(
              case when count(*) = 1 then nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'component_key_value', '')), '') else null::text end,
              case when fcrr.linked_timesheet_id is not null then 'TOTAL' else fcrr.finance_case_id::text end
            ) as component_key_value,
            case
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'TAXABLE_CHANNEL_SENSITIVE'
                then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
                then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
              when count(*) = 1 and upper(nullif(btrim(coalesce((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->>'classification', '')), '')) = 'NET_PAY_FIXED_RECOVERY'
                then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              else null::public.pay_finance_component_classification_enum
            end as component_classification,
            case
              when count(*) = 1 and jsonb_typeof((array_agg(component_rows.component_json order by component_rows.ordinality))[1]->'source_basis_json') = 'object'
                then (array_agg(component_rows.component_json order by component_rows.ordinality))[1]->'source_basis_json'
              else '{}'::jsonb
            end as component_source_basis_json
          from component_rows
        ) component_identity on true
        where (
          round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
          or fcrr.active_snooze_id is not null
          or coalesce(fcrr.is_blocked, false) = true
          or lower(btrim(coalesce(fcrr.case_resolution_summary_json->>'case_needs_resolution', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
          or (
            round(coalesce(fcrr.due_amount_ex_vat,0),2) = 0
            and coalesce(finance_due_meta.nominal_due_amount_ex_vat, 0) > 0
            and fcrr.case_type in (
              'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
              'OVERPAYMENT'::public.pay_finance_case_type_enum,
              'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
            )
          )
        )


  ;

  create temporary table hidden_recovery_template_lines on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          case
            when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
            when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrrb.case_type::text
          end as recovery_family,
          ('advance:' || fcrrb.finance_case_id::text) as source_ref,
          row_number() over (
            partition by fcrrb.candidate_id,
                         case
                           when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                           when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                           when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                           else fcrrb.case_type::text
                         end
            order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
          )::integer as sort_order,
          jsonb_strip_nulls(
            jsonb_build_object(
              'template_state', 'HIDDEN_ZERO_TAKE',
              'candidate_id', fcrrb.candidate_id::text,
              'finance_case_id', fcrrb.finance_case_id::text,
              'recovery_family', case
                when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                else fcrrb.case_type::text
              end,
              'case_type', fcrrb.case_type::text,
              'source_ref', ('advance:' || fcrrb.finance_case_id::text),
              'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'umbrella_id', case when c.umbrella_id is null then null else c.umbrella_id::text end,
              'paye_treatment', case
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'PAYMENT_ADVANCE'
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                else 'NONE'
              end,
              'finance_component_id', null,
              'frozen_component_key_type', 'CASE_TOTAL',
              'frozen_component_key_value', 'TOTAL',
              'frozen_component_classification', null,
              'frozen_component_snapshot_json', null,
              'frozen_source_basis_json', jsonb_strip_nulls(
                jsonb_build_object(
                  'case_type', fcrrb.case_type::text,
                  'recovery_family', case
                    when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                    when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                    when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                    else fcrrb.case_type::text
                  end,
                  'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'taxability', case when fcbs.taxability is null then null else fcbs.taxability::text end,
                  'routing_kind', case when fcbs.routing_kind is null then null else fcbs.routing_kind::text end,
                  'nominal_due_amount_ex_vat', round(coalesce(fcrrb.nominal_due_amount, 0), 2),
                  'current_due_amount_ex_vat', round(coalesce(fcrr.due_amount_ex_vat, 0), 2),
                  'outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
                  'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
                  'active_reserved_amount', round(coalesce(fcbs.active_reserved_amount, 0), 2),
                  'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
                  'take_home_floor_override', fcrrb.take_home_floor_override,
                  'default_take_home_floor', fcrrb.default_take_home_floor,
                  'run_earnings_headroom_ex', round(coalesce(fcrrb.run_earnings_headroom_ex, 0), 2),
                  'run_take_home_before', round(coalesce(fcrrb.run_take_home_before, 0), 2),
                  'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
                  'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
                  'sort_order', row_number() over (
                    partition by fcrrb.candidate_id,
                                 case
                                   when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                                   when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                                   when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                                   else fcrrb.case_type::text
                                 end
                    order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
                  )
                )
              ),
              'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_source_amount', round(coalesce(fcbs.outstanding_amount, fcrrb.nominal_due_amount, 0), 2),
              'frozen_outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
              'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
              'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
              'take_home_floor_override', fcrrb.take_home_floor_override,
              'default_take_home_floor', fcrrb.default_take_home_floor,
              'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
              'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
              'sort_order', row_number() over (
                partition by fcrrb.candidate_id,
                             case
                               when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                               when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                               when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                               else fcrrb.case_type::text
                             end
                order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
              ),
              'frozen_resolution_mode', coalesce(
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'mode', '')), '')
              ),
              'frozen_resolution_payload_json', case
                when fcrr.taxable_manual_debt_resolution_json is not null then fcrr.taxable_manual_debt_resolution_json
                when jsonb_typeof(fcrr.case_resolution_summary_json->'non_bucket_resolution') = 'object' then fcrr.case_resolution_summary_json->'non_bucket_resolution'
                else null
              end,
              'frozen_resolution_result_json', fcrr.case_resolution_summary_json,
              'case_components_json', coalesce(fcrr.case_components_json, '[]'::jsonb),
              'case_resolution_summary_json', coalesce(fcrr.case_resolution_summary_json, '{}'::jsonb),
              'taxable_manual_debt_resolution_json', fcrr.taxable_manual_debt_resolution_json,
              'eligibility_state', jsonb_build_object(
                'candidate_ready_for_draft', coalesce(fcrr.candidate_ready_for_draft, false),
                'case_is_blocked', coalesce(fcrr.is_blocked, false),
                'has_active_dated_snooze', (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
              )
            )
          ) as template_json
        from finance_case_recovery_rows_base fcrrb
        join finance_case_baseline_scope fcbs
          on fcbs.finance_case_id = fcrrb.finance_case_id
        join finance_case_resolution_rollup fcrr
          on fcrr.finance_case_id = fcrrb.finance_case_id
        left join public.candidates c
          on c.id = fcrrb.candidate_id
        where fcrrb.case_type in (
            'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
          and round(coalesce(fcrrb.nominal_due_amount, 0), 2) > 0
          and round(coalesce(fcrr.due_amount_ex_vat, 0), 2) = 0
          and coalesce(fcrr.candidate_ready_for_draft, false) = true
          and coalesce(fcrr.is_blocked, false) = false
          and not (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
          and (
            fcrrb.case_type <> 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
            or upper(coalesce(fcrrb.payout_status::text, '')) = 'PAID'
          )
  ;



  CREATE TEMPORARY TABLE IF NOT EXISTS manual_adjustment_carry_forward_scope (
    id uuid,
    source_pay_batch_id uuid,
    source_pay_batch_item_id uuid,
    source_pay_bank_transfer_id uuid,
    source_pay_batch_candidate_id uuid,
    source_correction_request_id uuid,
    source_correction_work_item_id uuid,
    candidate_id uuid,
    umbrella_id uuid,
    client_id uuid,
    timesheet_id uuid,
    pay_channel text,
    adjustment_direction text,
    amount_ex_vat numeric,
    amount_vat numeric,
    amount_inc_vat numeric,
    amount_basis text,
    paye_treatment text,
    tax_treatment_json jsonb,
    description text,
    reason text,
    source_ref text,
    source_operation_source_key text,
    source_snapshot_json jsonb,
    status text,
    target_pay_batch_id uuid,
    target_pay_batch_item_id uuid,
    target_operation_source_key text,
    created_at_utc timestamptz,
    updated_at_utc timestamptz,
    reserved_at_utc timestamptz,
    consumed_at_utc timestamptz,
    released_at_utc timestamptz,
    cancelled_at_utc timestamptz,
    status_reason text,
    source_batch_ref text
  ) ON COMMIT DROP;

  create temporary table manual_adjustment_carry_forward_lines on commit drop as
        select
          carry_forward_scope.candidate_id,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          carry_forward_scope.id as manual_adjustment_carry_forward_id,
          carry_forward_scope.source_pay_batch_id,
          carry_forward_scope.source_pay_batch_item_id,
          carry_forward_scope.source_pay_bank_transfer_id,
          carry_forward_scope.source_pay_batch_candidate_id,
          carry_forward_scope.source_correction_request_id,
          carry_forward_scope.source_correction_work_item_id,
          carry_forward_scope.umbrella_id,
          carry_forward_scope.client_id,
          carry_forward_scope.timesheet_id,
          upper(btrim(coalesce(carry_forward_scope.pay_channel, ''))) as pay_channel,
          carry_forward_scope.adjustment_direction,
          round(coalesce(carry_forward_scope.amount_ex_vat, 0), 2)::numeric as amount_ex_vat,
          round(coalesce(carry_forward_scope.amount_vat, 0), 2)::numeric as amount_vat,
          round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2)::numeric as amount_inc_vat,
          carry_forward_scope.amount_basis,
          carry_forward_scope.paye_treatment,
          coalesce(carry_forward_scope.tax_treatment_json, '{}'::jsonb) as tax_treatment_json,
          nullif(btrim(coalesce(carry_forward_scope.description, '')), '') as original_description,
          carry_forward_scope.reason,
          carry_forward_scope.source_ref,
          carry_forward_scope.source_operation_source_key,
          coalesce(carry_forward_scope.source_snapshot_json, '{}'::jsonb) as source_snapshot_json,
          carry_forward_scope.status,
          carry_forward_scope.target_pay_batch_id,
          carry_forward_scope.target_pay_batch_item_id,
          carry_forward_scope.target_operation_source_key,
          coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text) as source_batch_ref,
          ('carry_forward:' || carry_forward_scope.id::text) as preview_row_id,
          ('carry_forward:' || carry_forward_scope.id::text) as operation_source_key,
          ('Carried forward from cancelled payment '
            || coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text)
            || ': '
            || coalesce(nullif(btrim(carry_forward_scope.description), ''), nullif(btrim(carry_forward_scope.reason), ''), 'Manual adjustment')
          ) as display_description
        from manual_adjustment_carry_forward_scope as carry_forward_scope
        join cand_payee cp
          on cp.candidate_id = carry_forward_scope.candidate_id
        where carry_forward_scope.candidate_id = p_candidate_id
          and upper(btrim(coalesce(carry_forward_scope.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2) <> 0
  ;

  -- Aggregate timesheet rows are presentation parents only.  Exact economic
  -- allocation authority already exists in case_components_json; promote each
  -- positive, resolved component as its own top-level Ready-to-Pay row instead
  -- of making the aggregate parent selectable.  This preserves Policy X's
  -- existing TS_DAY / expense / correction identities and prevents a recovery
  -- row from becoming the only selectable row for a candidate.
  create temporary table timesheet_allocation_component_lines on commit drop as
        with component_rows as (
          select
            ctl.*,
            component.value as component_json,
            upper(nullif(btrim(coalesce(component.value->>'component_key_type','')), '')) as component_key_type,
            nullif(btrim(coalesce(component.value->>'component_key_value','')), '') as component_key_value,
            round(case
              when exists (
                select 1
                from canonical_timesheet_segment_rows resolved_segment
                where resolved_segment.candidate_id=ctl.candidate_id
                  and resolved_segment.timesheet_id=ctl.timesheet_id
              )
              and (
                lower(btrim(coalesce(ctl.case_resolution_summary_json->>'has_resolved_rate','false'))) in ('true','t','1','yes','y','on')
                or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_applied','false'))) in ('true','t','1','yes','y','on')
                or lower(btrim(coalesce(ctl.case_resolution_summary_json->>'resolved_rate_active','false'))) in ('true','t','1','yes','y','on')
                or (
                  coalesce(ctl.case_resolution_summary_json->>'resolved_rate_component_count','') ~ '^[0-9]+$'
                  and (ctl.case_resolution_summary_json->>'resolved_rate_component_count')::integer > 0
                )
              ) then coalesce(
                nullif(component.value->>'ready_preview_amount_ex_vat','')::numeric,
                nullif(component.value->>'target_pay_ex_vat','')::numeric,
                nullif(component.value->>'preview_component_amount_ex_vat','')::numeric
              )
              else coalesce(
                nullif(component.value->>'component_amount_ex_vat','')::numeric,
                nullif(component.value->>'authoritative_outstanding_ex_vat','')::numeric,
                nullif(component.value->>'preview_due_amount_ex_vat','')::numeric,
                nullif(component.value->>'ready_preview_amount_ex_vat','')::numeric,
                nullif(component.value->>'target_pay_ex_vat','')::numeric,
                nullif(component.value->>'preview_component_amount_ex_vat','')::numeric,
                0::numeric
              )
            end, 2) as component_amount_ex_vat,
            coalesce(nullif(btrim(coalesce(component.value->>'component_fingerprint','')), ''), md5(component.value::text)) as component_fingerprint,
            coalesce(
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_stable_key}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_id}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,segment_key}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,work_date}','')), ''),
              nullif(btrim(coalesce(component.value#>>'{source_basis_json,date}','')), ''),
              nullif(btrim(coalesce(component.value->>'component_key_value','')), '')
            ) as stable_component_identity,
            lower(btrim(coalesce(component.value->>'requires_resolution','false'))) in ('true','t','1','yes','y','on') as requires_resolution
          from canonical_timesheet_lines ctl
          cross join lateral jsonb_array_elements(
            case when jsonb_typeof(ctl.case_components_json)='array'
              then ctl.case_components_json else '[]'::jsonb end
          ) component(value)
        ), eligible_components as (
          select
            component_rows.*,
            coalesce(segment_match.segment_match_count, 0)::integer as segment_match_count,
            segment_match.segment_json as matched_segment_json,
            count(*) over (
              partition by component_rows.candidate_id,
                component_rows.timesheet_id,
                component_rows.component_key_type,
                component_rows.stable_component_identity
            ) as stable_component_identity_count,
            case
              when component_rows.component_key_type='TS_DAY' then
                component_rows.timesheet_id::text || ':segment:' || component_rows.stable_component_identity
                || case
                  when count(*) over (
                    partition by component_rows.candidate_id,
                      component_rows.timesheet_id,
                      component_rows.component_key_type,
                      component_rows.stable_component_identity
                  ) > 1 then ':bucket:' || lower(coalesce(
                    nullif(btrim(coalesce(component_rows.component_json->>'bucket_code','')), ''),
                    nullif(btrim(coalesce(component_rows.component_json#>>'{source_basis_json,bucket_code}','')), ''),
                    '~'
                  ))
                  else ''
                end
              when component_rows.component_key_type='EXPENSE_CODE' then
                component_rows.timesheet_id::text || ':component:expense:' || component_rows.component_fingerprint
              when lower(coalesce(component_rows.component_json->>'source_family_key','')) like 'correction%'
              then 'correction-chain:'
                || coalesce(
                  nullif(btrim(coalesce(component_rows.component_json->>'source_family_key','')), ''),
                  component_rows.timesheet_id::text
                )
                || ':' || lower(component_rows.component_key_type)
                || ':' || component_rows.component_key_value
              else component_rows.timesheet_id::text
                || ':component:' || lower(component_rows.component_key_type)
                || ':' || component_rows.component_fingerprint
            end as allocation_line_key
          from component_rows
          left join lateral (
            select
              count(*)::integer as segment_match_count,
              (jsonb_agg(
                matched_segment.segment_json
                order by matched_segment.match_rank,
                         matched_segment.seg_ord,
                         matched_segment.segment_stable_key
              )->0) as segment_json
            from (
              select
                segment_row.seg_ord,
                segment_row.segment_stable_key,
                segment_row.segment_base_json as segment_json,
                case
                  when nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                   and segment_row.segment_stable_key is not distinct from component_rows.stable_component_identity
                    then 10
                  else 20
                end as match_rank
              from canonical_timesheet_segment_rows as segment_row
              where component_rows.component_key_type = 'TS_DAY'
                and segment_row.candidate_id = component_rows.candidate_id
                and segment_row.timesheet_id = component_rows.timesheet_id
                and segment_row.presentation_segment_state = 'READY'
                and (
                  (
                    nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                    and segment_row.segment_stable_key is not distinct from component_rows.stable_component_identity
                  )
                  or (
                    not exists (
                      select 1
                      from canonical_timesheet_segment_rows as exact_segment
                      where exact_segment.candidate_id = component_rows.candidate_id
                        and exact_segment.timesheet_id = component_rows.timesheet_id
                        and exact_segment.presentation_segment_state = 'READY'
                        and nullif(btrim(coalesce(component_rows.stable_component_identity, '')), '') is not null
                        and exact_segment.segment_stable_key is not distinct from component_rows.stable_component_identity
                    )
                    and segment_row.segment_date::text is not distinct from component_rows.component_key_value
                  )
                )
            ) as matched_segment
          ) as segment_match on true
          where component_rows.component_key_type in ('TS_DAY','EXPENSE_CODE','ADDITIONAL_CODE','ADJUSTMENT_CODE')
            and component_rows.component_key_value is not null
            and component_rows.stable_component_identity is not null
            and (
              component_rows.component_key_type <> 'TS_DAY'
              or not exists (
                select 1
                from canonical_timesheet_segment_rows as exact_non_ready_segment
                where exact_non_ready_segment.candidate_id = component_rows.candidate_id
                  and exact_non_ready_segment.timesheet_id = component_rows.timesheet_id
                  and exact_non_ready_segment.segment_stable_key is not distinct from component_rows.stable_component_identity
                  and exact_non_ready_segment.presentation_segment_state in ('BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE')
              )
            )
            and component_rows.component_amount_ex_vat > 0
            and component_rows.requires_resolution is not true
            and component_rows.is_ready_for_draft is true
            and component_rows.case_is_blocked is false
            and component_rows.snooze_id is null
            and coalesce(jsonb_array_length(component_rows.payee_blockers),0)=0
        )
        select
          eligible_components.candidate_id,
          jsonb_strip_nulls(
            jsonb_build_object(
              'preview_row_id', eligible_components.allocation_line_key,
              'line_id', eligible_components.allocation_line_key,
              'line_key', eligible_components.allocation_line_key,
              'row_key', eligible_components.allocation_line_key,
              'source_ref', eligible_components.allocation_line_key,
              'parent_line_key', eligible_components.timesheet_id::text,
              'candidate_id', eligible_components.candidate_id::text,
              'tms_ref', eligible_components.cand_tms_ref,
              'display_name', eligible_components.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'case_type', 'TIMESHEET_PAYMENT',
              'case_key', 'timesheet:' || eligible_components.timesheet_id::text
            )
            || jsonb_build_object(
              'finance_case_id', null,
              'finance_component_id', nullif(eligible_components.component_json->>'finance_component_id',''),
              'timesheet_id', eligible_components.timesheet_id::text,
              'real_business_timesheet_id', eligible_components.timesheet_id::text,
              'booking_id', eligible_components.booking_id,
              'client_id', case when eligible_components.client_id is null then null else eligible_components.client_id::text end,
              'client_name', eligible_components.client_name,
              'week_ending_date', case when eligible_components.week_ending_date is null then null else eligible_components.week_ending_date::text end,
              'linked_shift_date', case when eligible_components.component_key_type='TS_DAY' then eligible_components.component_key_value else null end,
              'component_key_type', eligible_components.component_key_type,
              'component_key_value', eligible_components.component_key_value,
              'key_type', eligible_components.component_key_type,
              'key_value', eligible_components.component_key_value,
              'economic_key', jsonb_build_object(
                'timesheet_id', eligible_components.timesheet_id::text,
                'key_type', eligible_components.component_key_type,
                'key_value', eligible_components.component_key_value
              ),
              'component_fingerprint', eligible_components.component_fingerprint,
              'bucket_code', nullif(btrim(coalesce(eligible_components.component_json->>'bucket_code','')), ''),
              'physical_bucket_key', eligible_components.component_json->'physical_bucket_key',
              'physical_bucket_digest', eligible_components.component_json->'physical_bucket_digest',
              'source_family_key', eligible_components.component_json->'source_family_key',
              'source_basis_fingerprint', eligible_components.component_json->'source_basis_fingerprint',
              'source_basis_json', eligible_components.component_json->'source_basis_json',
              'source_units', eligible_components.component_json->'source_units',
              'source_rate', eligible_components.component_json->'source_rate',
              'source_charge_rate', eligible_components.component_json->'source_charge_rate',
              'source_pay_ex_vat', eligible_components.component_json->'source_pay_ex_vat',
              'source_charge_ex_vat', eligible_components.component_json->'source_charge_ex_vat',
              'target_rate', eligible_components.component_json->'target_rate',
              'target_pay_ex_vat', eligible_components.component_json->'target_pay_ex_vat',
              'source_pay_method', eligible_components.component_json->'source_pay_method',
              'current_target_pay_method', eligible_components.component_json->'current_target_pay_method',
              'segment_id', eligible_components.matched_segment_json->'segment_id',
              'segment_key', eligible_components.matched_segment_json->'segment_key',
              'segment_stable_key', eligible_components.matched_segment_json->'segment_stable_key',
              'date', eligible_components.matched_segment_json->'date',
              'work_date', coalesce(
                eligible_components.matched_segment_json->'work_date',
                eligible_components.matched_segment_json->'date'
              ),
              'role', eligible_components.matched_segment_json->'role',
              'band', eligible_components.matched_segment_json->'band',
              'start', eligible_components.matched_segment_json->'start',
              'finish', eligible_components.matched_segment_json->'finish',
              'start_utc', eligible_components.matched_segment_json->'start_utc',
              'end_utc', eligible_components.matched_segment_json->'end_utc',
              'break_start', eligible_components.matched_segment_json->'break_start',
              'break_end', eligible_components.matched_segment_json->'break_end',
              'break_mins', eligible_components.matched_segment_json->'break_mins',
              'breaks', eligible_components.matched_segment_json->'breaks',
              'ref_num', eligible_components.matched_segment_json->'ref_num'
            )
            || jsonb_build_object(
              'case_resolution_summary', coalesce(eligible_components.case_resolution_summary_json, '{}'::jsonb),
              'case_resolution_summary_json', coalesce(eligible_components.case_resolution_summary_json, '{}'::jsonb),
              'has_resolved_rate', eligible_components.case_resolution_summary_json->'has_resolved_rate',
              'resolved_rate_applied', eligible_components.case_resolution_summary_json->'resolved_rate_applied',
              'resolved_rate_active', eligible_components.case_resolution_summary_json->'resolved_rate_active',
              'case_resolution_satisfied_now', eligible_components.case_resolution_summary_json->'case_resolution_satisfied_now',
              'resolved_rate_family', eligible_components.case_resolution_summary_json->'resolved_rate_family',
              'resolved_rate_component_count', eligible_components.case_resolution_summary_json->'resolved_rate_component_count',
              'resolved_rate_candidate_id', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_candidate_id',
                eligible_components.case_resolution_summary_json->'resolution_candidate_id'
              ),
              'resolved_rate_timesheet_id', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_timesheet_id',
                eligible_components.case_resolution_summary_json->'resolution_timesheet_id'
              ),
              'resolved_rate_case_key', coalesce(
                eligible_components.case_resolution_summary_json->'resolved_rate_case_key',
                eligible_components.case_resolution_summary_json->'resolution_case_key'
              ),
              'resolution_candidate_id', eligible_components.case_resolution_summary_json->'resolution_candidate_id',
              'resolution_timesheet_id', eligible_components.case_resolution_summary_json->'resolution_timesheet_id',
              'resolution_case_key', eligible_components.case_resolution_summary_json->'resolution_case_key',
              'case_resolution_id', eligible_components.case_resolution_summary_json->'case_resolution_id',
              'case_resolution_ids', eligible_components.case_resolution_summary_json->'case_resolution_ids',
              'resolution_identity_keys', eligible_components.case_resolution_summary_json->'resolution_identity_keys',
              'resolved_rate_clear_payload_json', eligible_components.case_resolution_summary_json->'resolved_rate_clear_payload_json',
              'case_components', jsonb_build_array(eligible_components.component_json),
              'amount_ex_vat', eligible_components.component_amount_ex_vat,
              'amount_display', eligible_components.component_amount_ex_vat,
              'item_direction', 'PAYMENT',
              'pay_channel', eligible_components.candidate_pay_method,
              'paye_treatment', case when eligible_components.candidate_pay_method='PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'payee_entity_kind', eligible_components.payee_entity_kind,
              'payee_entity_id', case when eligible_components.payee_entity_id is null then null else eligible_components.payee_entity_id::text end,
              'payee_bank_hash', eligible_components.payee_bank_hash,
              'bank_details_hash', eligible_components.payee_bank_hash,
              'name_check_status', eligible_components.payee_name_check_status,
              'name_check_has_override', eligible_components.payee_name_check_has_override,
              'payee_map_present', eligible_components.payee_map_present,
              'blockers', eligible_components.payee_blockers,
              'payee_blockers', eligible_components.payee_blockers,
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'ALLOCATION_COMPONENT',
              'presentation_parent_line_id', eligible_components.timesheet_id::text,
              'readiness_state', 'READY_TO_PAY',
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', true,
              'draftable', true,
              'selection_allowed', true,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ) as line_json,
          eligible_components.candidate_pay_method as pay_channel,
          case when eligible_components.candidate_pay_method='PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          eligible_components.component_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation,
          eligible_components.component_key_type,
          eligible_components.segment_match_count
        from eligible_components

  ;

  if exists (
    select 1
    from timesheet_allocation_component_lines as component_line
    where component_line.component_key_type = 'TS_DAY'
      and component_line.segment_match_count = 0
  ) then
    SELECT pg_catalog.jsonb_build_object(
      'code', 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_MISSING',
      'candidate_id', component_line.candidate_id,
      'timesheet_id', component_line.timesheet_id,
      'component_key_type', component_line.component_key_type,
      'component_key_value', component_line.key_value,
      'source_basis_fingerprint', component_line.line_json->>'source_basis_fingerprint',
      'match_count', component_line.segment_match_count
    )
    INTO v_allocation_segment_failure
    FROM timesheet_allocation_component_lines AS component_line
    WHERE component_line.component_key_type = 'TS_DAY'
      AND component_line.segment_match_count = 0
    ORDER BY component_line.candidate_id, component_line.timesheet_id,
      component_line.key_value, component_line.line_key
    LIMIT 1;

    raise exception 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_MISSING'
      using errcode = 'P0001', detail = v_allocation_segment_failure::text;
  end if;

  if exists (
    select 1
    from timesheet_allocation_component_lines as component_line
    where component_line.component_key_type = 'TS_DAY'
      and component_line.segment_match_count > 1
  ) then
    SELECT pg_catalog.jsonb_build_object(
      'code', 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_AMBIGUOUS',
      'candidate_id', component_line.candidate_id,
      'timesheet_id', component_line.timesheet_id,
      'component_key_type', component_line.component_key_type,
      'component_key_value', component_line.key_value,
      'source_basis_fingerprint', component_line.line_json->>'source_basis_fingerprint',
      'match_count', component_line.segment_match_count
    )
    INTO v_allocation_segment_failure
    FROM timesheet_allocation_component_lines AS component_line
    WHERE component_line.component_key_type = 'TS_DAY'
      AND component_line.segment_match_count > 1
    ORDER BY component_line.candidate_id, component_line.timesheet_id,
      component_line.key_value, component_line.line_key
    LIMIT 1;

    raise exception 'PAY_WORKBENCH_ALLOCATION_SEGMENT_IDENTITY_AMBIGUOUS'
      using errcode = 'P0001', detail = v_allocation_segment_failure::text;
  end if;

  -- The finance resolver's run-level headroom predates semantic allocation
  -- children and therefore used aggregate presentation parents.  V3 replaces
  -- that display-only basis with exact positive keyed allocation authority.
  -- Nominal debt is never changed: only the amount recoverable in this pay run
  -- is capped, in the existing oldest-case order, to same-candidate headroom.
  -- A28: honour the slice hand-over only inside the exact authoritative Workbench build that set it.
  v_a28_slice_applies := v_a28_slice IS NOT NULL
    AND COALESCE((v_a28_slice->>'final')::boolean, false)
    AND COALESCE(v_a28_slice->>'build_token', '') <> ''
    AND v_a28_slice->>'build_token' = COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token', true), '');
  IF v_a28_slice_applies THEN
    v_a28_slice_candidate_id := (v_a28_slice->>'candidate_id')::uuid;
  END IF;
  create temporary table semantic_finance_case_lines on commit drop as
        with allocation_headroom as (
          select
            component_line.candidate_id,
            round(coalesce(sum(component_line.amount_ex_vat),0),2) as ordinary_positive_headroom
          from timesheet_allocation_component_lines component_line
          where component_line.amount_ex_vat > 0
          group by component_line.candidate_id
        ), ranked as (
          select
            finance_line.*,
            (coalesce(headroom.ordinary_positive_headroom,0)
              + case when v_a28_slice_applies and finance_line.candidate_id = v_a28_slice_candidate_id
                  then coalesce((v_a28_slice->>'prior_ordinary_positive_headroom_ex')::numeric,0) else 0 end
            )::numeric as ordinary_positive_headroom, /* A28 */
            coalesce(
              sum(
                case
                  when finance_line.draftable is true
                   and finance_line.item_direction='DEDUCTION'
                   and finance_line.signed_amount_ex_vat < 0
                  then abs(finance_line.signed_amount_ex_vat)
                  else 0
                end
              ) over (
                partition by finance_line.candidate_id
                order by finance_line.semantic_recovery_sort_at_utc nulls last,
                         finance_line.finance_case_id
                rows between unbounded preceding and 1 preceding
              ),
              0
            )::numeric as prior_semantic_recovery_amount,
            (
              finance_line.draftable is true
              and finance_line.item_direction='DEDUCTION'
              and finance_line.signed_amount_ex_vat < 0
            ) as is_semantic_recovery
          from finance_case_lines finance_line
          left join allocation_headroom headroom
            on headroom.candidate_id=finance_line.candidate_id
        ), capped as (
          select
            ranked.*,
            case
              when v_semantic_ready_publication_enabled and ranked.is_semantic_recovery
              then round(least(
                abs(ranked.signed_amount_ex_vat),
                greatest(ranked.ordinary_positive_headroom-ranked.prior_semantic_recovery_amount,0)
              ),2)
              else round(abs(ranked.signed_amount_ex_vat),2)
            end as semantic_recovery_due_amount
          from ranked
        )
        select
          capped.*,
          case
            when v_semantic_ready_publication_enabled and capped.is_semantic_recovery
            then -capped.semantic_recovery_due_amount
            else capped.signed_amount_ex_vat
          end as semantic_signed_amount_ex_vat,
          case
            when v_semantic_ready_publication_enabled and capped.is_semantic_recovery
            then capped.draftable and capped.semantic_recovery_due_amount > 0
            else capped.draftable
          end as semantic_draftable,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'BLOCKED_FOR_PAY'
            else capped.readiness_state
          end as semantic_readiness_state,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'BLOCKED_FOR_PAY'
            else capped.presentation_section
          end as semantic_presentation_section,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then 'NO_PAY_HEADROOM'
            else capped.presentation_reason
          end as semantic_presentation_reason,
          case
            when v_semantic_ready_publication_enabled
             and capped.is_semantic_recovery
             and capped.semantic_recovery_due_amount = 0
            then capped.blocked_reason_codes || jsonb_build_array('NO_PAY_HEADROOM')
            else capped.blocked_reason_codes
          end as semantic_blocked_reason_codes,
          (
            v_semantic_ready_publication_enabled
            and capped.is_semantic_recovery
            and capped.semantic_recovery_due_amount < abs(capped.signed_amount_ex_vat)
          ) as semantic_recovery_headroom_capped
        from capped

  ;

  create temporary table timesheet_canonical_preview_lines on commit drop as
        select
          ctpr.candidate_id,
          (
            ctpr.line_json
            || jsonb_build_object(
              'preview_row_id', coalesce(nullif(btrim(coalesce(ctpr.line_json->>'line_id','')), ''), md5(ctpr.line_json::text)),
              'readiness_state', case
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'CASES_RESOLUTIONS'
                then 'CASES_RESOLUTIONS'
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
                  or coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = false
                then 'BLOCKED_FOR_PAY'
                else 'READY_TO_PAY'
              end,
              'draftable', CASE WHEN v_semantic_ready_publication_enabled THEN false ELSE (
                upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'READY_TO_PAY'
                and coalesce(nullif(ctpr.line_json->>'is_excluded_from_allocation','')::boolean, false) = false
                and coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = true
              ) END,
              'is_ready_for_draft', CASE WHEN v_semantic_ready_publication_enabled THEN false
                ELSE coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean,false) END,
              'selection_allowed', CASE WHEN v_semantic_ready_publication_enabled THEN false
                ELSE coalesce(nullif(ctpr.line_json->>'selection_allowed','')::boolean,
                  coalesce(nullif(ctpr.line_json->>'draftable','')::boolean,false)) END,
              'is_excluded_from_allocation', CASE WHEN v_semantic_ready_publication_enabled THEN true
                ELSE coalesce(nullif(ctpr.line_json->>'is_excluded_from_allocation','')::boolean,false) END
            )
          ) as line_json,
          ctpr.pay_channel,
          ctpr.paye_treatment,
          ctpr.amount_ex_vat,
          CASE WHEN v_semantic_ready_publication_enabled THEN true
            ELSE ctpr.is_excluded_from_allocation END as is_excluded_from_allocation
        from canonical_timesheet_presentation_rows ctpr

        union all

        select
          component_line.candidate_id,
          component_line.line_json,
          component_line.pay_channel,
          component_line.paye_treatment,
          component_line.amount_ex_vat,
          component_line.is_excluded_from_allocation
        from timesheet_allocation_component_lines component_line
        where v_semantic_ready_publication_enabled

  ;

  create temporary table canonical_preview_lines on commit drop as
        select
          tcpl.candidate_id,
          tcpl.line_json,
          tcpl.pay_channel,
          tcpl.paye_treatment,
          tcpl.amount_ex_vat,
          tcpl.is_excluded_from_allocation
        from timesheet_canonical_preview_lines tcpl

        union all

        select
          fcl.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'candidate_id', fcl.candidate_id::text,
              'tms_ref', fcl.cand_tms_ref,
              'display_name', fcl.cand_display_name,
              'line_type', fcl.line_type,
              'item_type_label', fcl.item_type_label,
              'item_direction', fcl.item_direction,
              'finance_case_id', fcl.finance_case_id::text,
              'case_key', ('finance:' || fcl.finance_case_id::text),
              'case_type', fcl.case_type::text,
              'case_is_blocked', (
                fcl.case_is_blocked
                or (v_semantic_ready_publication_enabled
                  and fcl.is_semantic_recovery
                  and fcl.semantic_recovery_due_amount = 0)
              )
            )
            || jsonb_build_object(
              'case_resolution_summary', fcl.case_resolution_summary_json,
              'case_components', fcl.case_components_json,
              'finance_component_id', case when fcl.finance_component_id is null then null else fcl.finance_component_id::text end,
              'component_key_type', fcl.component_key_type,
              'component_key_value', fcl.component_key_value,
              'key_type', fcl.component_key_type,
              'key_value', fcl.component_key_value,
              'economic_key', jsonb_strip_nulls(jsonb_build_object(
                'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                'key_type', fcl.component_key_type,
                'key_value', fcl.component_key_value
              )),
              'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
              'client_id', case when fcl.client_id is null then null else fcl.client_id::text end,
              'client_name', fcl.client_name,
              'week_ending_date', null,
              'linked_shift_date', case when fcl.linked_shift_date is null then null else fcl.linked_shift_date::text end,
              'pay_channel', fcl.candidate_pay_method,
              'paye_treatment', fcl.paye_treatment,
              'route_type', case when fcl.routing_kind is null then 'NORMAL_PAYMENT' else fcl.routing_kind::text end,
              'routing_kind', case when fcl.routing_kind is null then null else fcl.routing_kind::text end,
              'destination_label', fcl.destination_label,
              'taxability', case when fcl.taxability is null then null else fcl.taxability::text end
            )
            || jsonb_strip_nulls(
              jsonb_build_object(
                'taxable_manual_debt_resolution', fcl.taxable_manual_debt_resolution_json
              )
            )
            || jsonb_build_object(
              'beneficiary_name', fcl.beneficiary_name,
              'masked_bank_account', fcl.masked_bank_account,
              'bank_details_hash', fcl.payee_bank_hash,
              'blocked_reason_codes', fcl.semantic_blocked_reason_codes,
              'readiness_state', fcl.semantic_readiness_state,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'draftable', fcl.semantic_draftable,
              'snooze_allowed', fcl.snooze_allowed,
              'oneoff_bank_details_present', fcl.oneoff_bank_details_present,
              'is_candidate_directed_oneoff_payout', fcl.is_candidate_directed_oneoff_payout,
              'appears_on_umbrella_remittance', fcl.appears_on_umbrella_remittance,
              'generates_candidate_payment_advice', fcl.generates_candidate_payment_advice,
              'adjustment_comment', fcl.adjustment_comment,
              'amount_ex_vat', fcl.semantic_signed_amount_ex_vat,
              'amount_display', fcl.semantic_signed_amount_ex_vat,
              'nominal_due_amount_ex_vat', round(coalesce(fcl.nominal_due_amount_ex_vat, 0), 2),
              'recoverable_this_pay_run_ex_vat', case
                when v_semantic_ready_publication_enabled and fcl.is_semantic_recovery
                then fcl.semantic_recovery_due_amount
                else round(greatest(coalesce(fcl.due_amount_ex_vat, 0), 0), 2)
              end,
              'semantic_ordinary_positive_headroom_ex_vat', case
                when v_semantic_ready_publication_enabled then fcl.ordinary_positive_headroom
                else null end,
              'semantic_recovery_headroom_capped', fcl.semantic_recovery_headroom_capped,
              'next_due_week_start', case when fcl.next_due_week_start is null then null else fcl.next_due_week_start::text end,
              'is_advanced', false,
              'advanced_override_id', null,
              'advanced_reason', null
            )
            || case
              when fcl.line_type = 'OVERPAYMENT_RECOVERY' then jsonb_build_object(
                'recovery_residual_contract_version', 1,
                'recovery_source_outstanding_ex_vat', round(
                  coalesce(fcl.recovery_source_outstanding_ex_vat, 0),
                  2
                ),
                'recovery_active_reserved_ex_vat', round(
                  coalesce(fcl.recovery_active_reserved_ex_vat, 0),
                  2
                ),
                'recovery_residual_outstanding_ex_vat', round(
                  coalesce(fcl.nominal_due_amount_ex_vat, 0),
                  2
                )
              )
              else '{}'::jsonb
            end
            || jsonb_build_object(
              'resolution_state', case
                when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE' then 'RESOLVED'
                when fcl.finance_resolution_clearability_state = 'REQUIRES_RESOLUTION' then 'REQUIRES_RESOLUTION'
                when fcl.finance_resolution_clearability_state = 'STALE_OR_AMBIGUOUS' then 'STALE'
                else 'NOT_REQUIRED'
              end,
              'resolution_badge', case when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE' then 'RESOLVED' else null end,
              'is_case_resolution_satisfied', fcl.is_case_resolution_satisfied,
              'case_needs_resolution_now', fcl.case_needs_resolution_now,
              'finance_resolution_clearability_state', fcl.finance_resolution_clearability_state,
              'finance_resolution_clear_block_reason', fcl.finance_resolution_clear_block_reason,
              'current_saved_resolution_family', nullif(fcl.current_saved_resolution_family, ''),
              'current_saved_resolution_owner_kind', fcl.current_saved_resolution_owner_kind,
              'case_resolution_actions', jsonb_strip_nulls(jsonb_build_object(
                'apply', case when fcl.case_needs_resolution_now then jsonb_strip_nulls(jsonb_build_object(
                  'enabled', true,
                  'action', 'APPLY_CASE_RESOLUTION',
                  'candidate_id', fcl.candidate_id::text,
                  'finance_case_id', fcl.finance_case_id::text,
                  'case_key', ('finance:' || fcl.finance_case_id::text),
                  'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                  'resolution_family', fcl.case_resolution_summary_json->>'resolution_family',
                  'label', nullif(btrim(coalesce(fcl.case_resolution_summary_json->>'resolution_action_label','')), '')
                )) else null end,
                'clear', case
                  when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE'
                   and fcl.current_saved_resolution_family in ('TAXABLE_CHANNEL_RESTRUCTURE', 'NON_BUCKET')
                  then jsonb_strip_nulls(jsonb_build_object(
                  'enabled', true,
                  'action', 'CLEAR_CASE_RESOLUTION',
                  'candidate_id', fcl.candidate_id::text,
                  'finance_case_id', fcl.finance_case_id::text,
                  'case_key', ('finance:' || fcl.finance_case_id::text),
                  'linked_timesheet_id', case
                    when fcl.current_saved_resolution_family = 'NON_BUCKET'
                     and fcl.current_saved_resolution_linked_timesheet_id is not null
                      then fcl.current_saved_resolution_linked_timesheet_id::text
                    else null
                  end,
                  'resolution_family', fcl.current_saved_resolution_family,
                  'label', case
                    when fcl.current_saved_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' then 'Cancel Resolved Pay Channel'
                    when fcl.current_saved_resolution_family = 'NON_BUCKET' then 'Cancel Resolved Gross Total'
                    else null
                  end
                )) else null end
              )),
              'apply_case_resolution_action', case when fcl.case_needs_resolution_now then jsonb_strip_nulls(jsonb_build_object(
                'enabled', true,
                'action', 'APPLY_CASE_RESOLUTION',
                'candidate_id', fcl.candidate_id::text,
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
                'resolution_family', fcl.case_resolution_summary_json->>'resolution_family',
                'label', nullif(btrim(coalesce(fcl.case_resolution_summary_json->>'resolution_action_label','')), '')
              )) else null end,
              'clear_case_resolution_action', case
                when fcl.finance_resolution_clearability_state = 'RESOLVED_AND_CLEARABLE'
                 and fcl.current_saved_resolution_family in ('TAXABLE_CHANNEL_RESTRUCTURE', 'NON_BUCKET')
                then jsonb_strip_nulls(jsonb_build_object(
                'enabled', true,
                'action', 'CLEAR_CASE_RESOLUTION',
                'candidate_id', fcl.candidate_id::text,
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'linked_timesheet_id', case
                  when fcl.current_saved_resolution_family = 'NON_BUCKET'
                   and fcl.current_saved_resolution_linked_timesheet_id is not null
                    then fcl.current_saved_resolution_linked_timesheet_id::text
                  else null
                end,
                'resolution_family', fcl.current_saved_resolution_family,
                'label', case
                  when fcl.current_saved_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' then 'Cancel Resolved Pay Channel'
                  when fcl.current_saved_resolution_family = 'NON_BUCKET' then 'Cancel Resolved Gross Total'
                  else null
                end
              )) else null end
            )
            || jsonb_build_object(
              'is_excluded_from_allocation', (fcl.semantic_draftable is not true),
              'selection_allowed', fcl.semantic_draftable,
              'is_ready_for_draft', fcl.semantic_draftable,
              'presentation_section', fcl.semantic_presentation_section,
              'presentation_role', 'PARENT',
              'presentation_line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'presentation_parent_line_id', ('finance:' || fcl.finance_case_id::text),
              'presentation_reason', fcl.semantic_presentation_reason,
              'source_ref', ('advance:' || fcl.finance_case_id::text),
              'snooze_kind', case
                when fcl.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcl.source_payout_status::text,'')) = 'PAID' then 'PAYMENT_ADVANCE_REPAYMENT'
                when fcl.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                when fcl.case_type = 'UNDERPAYMENT' then 'UNDERPAYMENT_PAYMENT'
                else ''
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'FINANCE_CASE',
                'timesheet_id', null,
                'booking_id', null,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', ('advance:' || fcl.finance_case_id::text)
              ),
              'snooze_state', case
                when fcl.active_snooze_id is null then jsonb_build_object('state','NONE')
                when fcl.active_snooze_until_date is null then jsonb_build_object(
                  'state', 'INDEFINITE_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', null,
                  'note', fcl.active_snooze_note
                )
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', fcl.active_snooze_until_date::text,
                  'note', fcl.active_snooze_note
                )
              end
            )
          ) as line_json,
          fcl.candidate_pay_method as pay_channel,
          fcl.paye_treatment,
          fcl.semantic_signed_amount_ex_vat as amount_ex_vat,
          (fcl.semantic_draftable is not true) as is_excluded_from_allocation
        from semantic_finance_case_lines fcl

        union all

        select
          cf_lines.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', cf_lines.preview_row_id,
              'line_id', cf_lines.preview_row_id,
              'candidate_id', cf_lines.candidate_id::text,
              'tms_ref', cf_lines.cand_tms_ref,
              'display_name', cf_lines.cand_display_name,
              'payee_entity_kind', cf_lines.payee_entity_kind,
              'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
              'payee_context', jsonb_build_object(
                'payee_entity_kind', cf_lines.payee_entity_kind,
                'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
                'pay_channel', cf_lines.pay_channel,
                'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END
              ),
              'line_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_key', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'case_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_is_blocked', false
            )
            || jsonb_build_object(
              'case_resolution_summary', '{}'::jsonb,
              'case_components', '[]'::jsonb,
              'item_type_label', 'Manual adjustment carry-forward',
              'item_direction', CASE WHEN coalesce(cf_lines.amount_inc_vat, 0) < 0 THEN 'DEBIT' ELSE 'CREDIT' END,
              'manual_adjustment_carry_forward_id', cf_lines.manual_adjustment_carry_forward_id::text,
              'component_key_type', 'MANUAL_CARRY_FORWARD',
              'component_key_value', cf_lines.manual_adjustment_carry_forward_id::text,
              'key_type', 'MANUAL_CARRY_FORWARD',
              'key_value', cf_lines.manual_adjustment_carry_forward_id::text,
              'economic_key', jsonb_strip_nulls(jsonb_build_object(
                'timesheet_id', CASE WHEN cf_lines.timesheet_id IS NULL THEN NULL ELSE cf_lines.timesheet_id::text END,
                'key_type', 'MANUAL_CARRY_FORWARD',
                'key_value', cf_lines.manual_adjustment_carry_forward_id::text
              )),
              'source_ref', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'operation_source_key', cf_lines.operation_source_key,
              'source_operation_source_key', cf_lines.source_operation_source_key,
              'description', cf_lines.display_description,
              'adjustment_comment', cf_lines.display_description,
              'original_description', cf_lines.original_description,
              'reason', cf_lines.reason
            )
            || jsonb_build_object(
              'source_pay_batch_id', CASE WHEN cf_lines.source_pay_batch_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_id::text END,
              'source_pay_batch_item_id', CASE WHEN cf_lines.source_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_item_id::text END,
              'source_pay_bank_transfer_id', CASE WHEN cf_lines.source_pay_bank_transfer_id IS NULL THEN NULL ELSE cf_lines.source_pay_bank_transfer_id::text END,
              'source_pay_batch_candidate_id', CASE WHEN cf_lines.source_pay_batch_candidate_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_candidate_id::text END,
              'source_correction_request_id', CASE WHEN cf_lines.source_correction_request_id IS NULL THEN NULL ELSE cf_lines.source_correction_request_id::text END,
              'source_correction_work_item_id', CASE WHEN cf_lines.source_correction_work_item_id IS NULL THEN NULL ELSE cf_lines.source_correction_work_item_id::text END,
              'source_batch_ref', cf_lines.source_batch_ref,
              'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END,
              'client_id', CASE WHEN cf_lines.client_id IS NULL THEN NULL ELSE cf_lines.client_id::text END,
              'timesheet_id', CASE WHEN cf_lines.timesheet_id IS NULL THEN NULL ELSE cf_lines.timesheet_id::text END,
              'pay_channel', cf_lines.pay_channel,
              'candidate_pay_method', cf_lines.pay_channel
            )
            || jsonb_build_object(
              'paye_treatment', cf_lines.paye_treatment,
              'tax_treatment_json', cf_lines.tax_treatment_json,
              'taxability', cf_lines.tax_treatment_json->>'taxability',
              'amount_basis', cf_lines.amount_basis,
              'adjustment_direction', cf_lines.adjustment_direction,
              'amount_ex_vat', cf_lines.amount_ex_vat,
              'amount_vat', cf_lines.amount_vat,
              'amount_inc_vat', cf_lines.amount_inc_vat,
              'amount_display', cf_lines.amount_inc_vat,
              'payment_amount_ex_vat', cf_lines.amount_ex_vat,
              'payment_amount_vat', cf_lines.amount_vat,
              'payment_amount_inc_vat', cf_lines.amount_inc_vat
            )
            || jsonb_build_object(
              'payment_amount', cf_lines.amount_inc_vat,
              'source_snapshot_json', cf_lines.source_snapshot_json,
              'manual_adjustment_carry_forward_status', cf_lines.status,
              'target_pay_batch_id', CASE WHEN cf_lines.target_pay_batch_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_id::text END,
              'target_pay_batch_item_id', CASE WHEN cf_lines.target_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_item_id::text END,
              'target_operation_source_key', cf_lines.target_operation_source_key,
              'readiness_state', 'READY_TO_PAY',
              'draftable', true,
              'is_ready_for_draft', true,
              'selection_allowed', true,
              'is_excluded_from_allocation', false,
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT'
            )
            || jsonb_build_object(
              'presentation_line_id', cf_lines.preview_row_id,
              'presentation_parent_line_id', cf_lines.preview_row_id,
              'presentation_reason', 'READY_TO_PAY',
              'route_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'routing_kind', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'appears_on_umbrella_remittance', (cf_lines.pay_channel = 'UMBRELLA'),
              'generates_candidate_payment_advice', true
            )
          ) as line_json,
          cf_lines.pay_channel,
          cf_lines.paye_treatment,
          cf_lines.amount_ex_vat,
          false as is_excluded_from_allocation
        from manual_adjustment_carry_forward_lines cf_lines

  ;

  create temporary table candidate_preview_line_rollup on commit drop as
        select
          cpl.candidate_id,
          count(*) filter (
            where coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          )::int as ready_preview_line_count,
          count(*) filter (
            where upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
          )::int as blocked_preview_line_count,
          bool_or(
            coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          ) as has_ready_preview_line
        from canonical_preview_lines cpl
        group by cpl.candidate_id

  ;

  create temporary table candidate_preview_timesheet_rollup on commit drop as
        with emitted_public_timesheets as (
          select
            tcpl.candidate_id,
            (tcpl.line_json->>'real_business_timesheet_id')::uuid as timesheet_id,
            bool_or(
              upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'READY_TO_PAY'
              and coalesce(nullif(tcpl.line_json->>'draftable','')::boolean, false) = true
            ) as has_ready_public_line,
            bool_or(
              upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
            ) as has_blocked_public_line,
            round(
              coalesce(sum(tcpl.amount_ex_vat) filter (
                where upper(coalesce(tcpl.line_json->>'presentation_section','')) = 'READY_TO_PAY'
                  and coalesce(nullif(tcpl.line_json->>'draftable','')::boolean, false) = true
              ), 0),
              2
            ) as ready_public_amount_ex_vat
          from timesheet_canonical_preview_lines tcpl
          where upper(coalesce(tcpl.line_json->>'line_type','')) = 'TIMESHEET_PAYMENT'
            and nullif(btrim(coalesce(tcpl.line_json->>'real_business_timesheet_id','')), '') is not null
            and upper(coalesce(tcpl.line_json->>'presentation_section','')) in ('READY_TO_PAY','BLOCKED_FOR_PAY')
          group by
            tcpl.candidate_id,
            (tcpl.line_json->>'real_business_timesheet_id')::uuid
        )
        select
          ctpp.candidate_id,
          round(
            coalesce(sum(ept.ready_public_amount_ex_vat), 0),
            2
          ) as ready_timesheet_total_ex_vat,
          count(*) filter (
            where coalesce(ept.has_blocked_public_line, false) = true
          )::int as blocked_timesheet_preview_count,
          count(*) filter (
            where coalesce(ept.has_ready_public_line, false) = true
          )::int as ready_timesheet_preview_count,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'timesheet_id', ctpp.timesheet_id::text,
                'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
                'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
                'client_name', ctpp.client_name,
                'payment_amount_ex_vat', ept.ready_public_amount_ex_vat,
                'payment_amount_inc_vat', ctpp.ready_section_amount_display,
                'payment_amount', ctpp.ready_section_amount_display,
                'source_pay_method', ctpp.source_pay_method,
                'candidate_pay_method', ctpp.candidate_pay_method,
                'segment_deltas', (
                  select coalesce(
                    jsonb_agg(
                      jsonb_build_object(
                        'segment_id', rs->>'segment_id',
                        'segment_key', rs->>'segment_key',
                        'segment_stable_key', rs->>'segment_stable_key',
                        'work_date', rs->>'date',
                        'ref_num', rs->>'ref_num',
                        'delta_pay_ex_vat', round(coalesce(nullif(rs->>'pay_amount_ex_vat','')::numeric, 0), 2),
                        'raw_delta_ex_vat', round(coalesce(nullif(rs->>'raw_delta_ex_vat','')::numeric, 0), 2),
                        'effective_delta_ex_vat', round(coalesce(nullif(rs->>'effective_delta_ex_vat','')::numeric, 0), 2)
                      )
                      order by
                        nullif(btrim(coalesce(rs->>'date','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'start','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_stable_key','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_id','')), '') nulls last
                    ),
                    '[]'::jsonb
                  )
                  from jsonb_array_elements(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)) rs
                ),
                'adjustment_deltas', coalesce(tcr.adjustment_deltas_json, '[]'::jsonb),
                'delta_additional_pay_ex_vat', coalesce(tcr.delta_additional_pay_ex_vat, 0),
                'additional_unit_deltas', coalesce(tcr.additional_unit_deltas_json, '[]'::jsonb),
                'reservation_overrun_detected', coalesce(tcr.reservation_overrun_detected, false),
                'delta_expenses_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'EXPENSES'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_travel_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'TRAVEL'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_accommodation_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'ACCOMMODATION'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_other_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'OTHER'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'delta_mileage_pay_ex_vat', coalesce((
                  select round(sum(coalesce(
                    case when coalesce(expense_component.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'ready_preview_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'preview_component_amount_ex_vat')::numeric else null::numeric end,
                    case when coalesce(expense_component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$' then (expense_component.value->>'component_amount_ex_vat')::numeric else null::numeric end,
                    0::numeric
                  )), 2)
                  from jsonb_array_elements(coalesce(ctpp.case_components_json, '[]'::jsonb)) as expense_component(value)
                  where upper(btrim(coalesce(expense_component.value->>'component_key_type', ''))) = 'EXPENSE_CODE'
                    and upper(btrim(coalesce(expense_component.value->>'component_key_value', expense_component.value->>'expense_code', ''))) = 'MILEAGE'
                    and upper(btrim(coalesce(expense_component.value->>'presentation_section', 'READY_TO_PAY'))) = 'READY_TO_PAY'
                ), 0),
                'case_key', ('timesheet:' || ctpp.timesheet_id::text),
                'case_resolution_summary', coalesce(ctpp.case_resolution_summary_json, '{}'::jsonb),
                'components', coalesce(ctpp.case_components_json, '[]'::jsonb),
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'PARENT',
                'total_segment_count', ctpp.total_segment_count,
                'ready_segment_count', ctpp.ready_segment_count,
                'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
                'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
                'is_partially_ready', ctpp.is_partially_ready,
                'is_partially_blocked', ctpp.is_partially_blocked
              )
              order by ctpp.week_ending_date, ctpp.client_name, ctpp.timesheet_id
            ) filter (where coalesce(ept.has_ready_public_line, false) = true),
            '[]'::jsonb
          ) as ready_timesheets_itemisation
        from canonical_timesheet_presentation_state ctpp
        left join emitted_public_timesheets ept
          on ept.candidate_id = ctpp.candidate_id
         and ept.timesheet_id = ctpp.timesheet_id
        left join timesheet_case_rollup_effective tcr
          on tcr.timesheet_id = ctpp.timesheet_id
         and tcr.candidate_id = ctpp.candidate_id
        group by ctpp.candidate_id

  ;

  v_canonical_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_canonical_started_at)) * 1000.0)::numeric, 3);

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'canonical_preview_line_count', (select count(*)::int from canonical_preview_lines),
    'ready_preview_line_count', coalesce((select sum(case when coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'blocked_preview_line_count', coalesce((select sum(case when upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY' then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'hidden_recovery_template_line_count', (select count(*)::int from hidden_recovery_template_lines),
    'manual_adjustment_carry_forward_line_count', (select count(*)::int from manual_adjustment_carry_forward_lines),
    'hidden_recovery_template_lines', coalesce(
      (
        select jsonb_agg(
                 hrtl.template_json
                 order by hrtl.candidate_id, hrtl.recovery_family, hrtl.sort_order, hrtl.finance_case_id
               )
        from hidden_recovery_template_lines hrtl
      ),
      '[]'::jsonb
    ),
    'source_build_canonical_diagnostics', jsonb_build_object(
      'source_build_mode', COALESCE(v_source_build_mode, false),
      'precollected_context_required', COALESCE(v_source_build_context_required, false),
      'collect_called_inside_canonical', COALESCE(v_collect_called_inside_canonical, false),
      'recollect_attempted', COALESCE(v_collect_recollect_attempted, false),
      'recollect_blocked', COALESCE(v_collect_recollect_blocked, false),
      'source_rows_seen', COALESCE((select count(*)::int from ts_baseline), 0),
      'canonical_preview_line_count', (select count(*)::int from canonical_preview_lines),
      'ready_preview_line_count', coalesce((select sum(case when coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
      'blocked_preview_line_count', coalesce((select sum(case when upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY' then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
      'canonical_elapsed_ms', v_canonical_elapsed_ms,
      'semantic_ready_observe_enabled',v_semantic_ready_observe_enabled,
      'semantic_ready_publication_enabled',v_semantic_ready_publication_enabled,
      'proposed_semantic_allocation_component_count',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN (SELECT count(*)::integer FROM timesheet_allocation_component_lines)
        ELSE 0 END,
      'proposed_semantic_allocation_component_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(component_line.amount_ex_vat),2)
          FROM timesheet_allocation_component_lines AS component_line),0)
        ELSE 0 END,
      'proposed_semantic_recovery_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(
          CASE WHEN finance_line.is_semantic_recovery
            THEN -least(
              abs(finance_line.signed_amount_ex_vat),
              greatest(finance_line.ordinary_positive_headroom-finance_line.prior_semantic_recovery_amount,0)
            ) ELSE 0 END
        ),2) FROM semantic_finance_case_lines AS finance_line),0)
        ELSE 0 END,
      'proposed_semantic_ready_amount',CASE
        WHEN v_semantic_ready_observe_enabled OR v_semantic_ready_publication_enabled
        THEN COALESCE((SELECT round(sum(component_line.amount_ex_vat),2)
          FROM timesheet_allocation_component_lines AS component_line),0)
          + COALESCE((SELECT round(sum(
            CASE WHEN finance_line.is_semantic_recovery
              THEN -least(
                abs(finance_line.signed_amount_ex_vat),
                greatest(finance_line.ordinary_positive_headroom-finance_line.prior_semantic_recovery_amount,0)
              ) ELSE 0 END
          ),2) FROM semantic_finance_case_lines AS finance_line),0)
        ELSE 0 END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )
  );
end;
$function$
;

-- [REPLACES] public.pay_preview_candidate_build_finance_case_baseline(p_context_json jsonb, p_candidate_id uuid)  winner piece A28
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_finance_case_baseline(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- A28 reconciliation slicing (final slice only; bound to the current Workbench build token)
  v_a28_slice jsonb := CASE WHEN COALESCE(current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true), '') ~ '^\s*\{'
    THEN current_setting('cloudtms.pay_workbench_reconcile_slice_v1', true)::jsonb ELSE NULL::jsonb END;
  v_a28_slice_applies boolean := false;
  v_a28_slice_candidate_id uuid := NULL::uuid;
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_workbench_resolution_session_id uuid := null::uuid;
  v_workbench_resolution_session_id_text text := null::text;
begin
  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_START',
    jsonb_build_object(
      'candidate_id', p_candidate_id,
      'context_pay_date', p_context_json->>'pay_date',
      'context_pay_week_start', p_context_json->>'pay_week_start'
    ),
    'pay_preview_finance',
    COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_workbench_resolution_session_id_text := NULLIF(BTRIM(COALESCE(
    v_context_json->>'workbench_resolution_session_id',
    v_context_json->>'workbench_session_id',
    v_context_json->>'session_id',
    v_context_json#>>'{workbench,resolution_session_id}',
    v_context_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_workbench_resolution_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_workbench_resolution_session_id := v_workbench_resolution_session_id_text::uuid;

    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS resolution_session
    WHERE resolution_session.id = v_workbench_resolution_session_id
      AND UPPER(BTRIM(COALESCE(resolution_session.status, ''))) = 'OPEN'
      AND resolution_session.discarded_at_utc IS NULL
      AND (
        v_candidate_id = ANY(COALESCE(resolution_session.scope_candidate_ids, ARRAY[]::uuid[]))
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS resolution_scope
          WHERE resolution_scope.session_id = resolution_session.id
            AND resolution_scope.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS resolution_preview_row
          WHERE resolution_preview_row.session_id = resolution_session.id
            AND resolution_preview_row.candidate_id = v_candidate_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS resolution_line_work
          WHERE resolution_line_work.session_id = resolution_session.id
            AND resolution_line_work.candidate_id = v_candidate_id
        )
      );

    IF NOT FOUND THEN
      v_workbench_resolution_session_id := NULL::uuid;
    END IF;
  ELSE
    v_workbench_resolution_session_id := NULL::uuid;
  END IF;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.cand_payee') is null then
    perform public.pay_preview_candidate_build_payee_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_bucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay, pg_temp.finance_case_nonbucket_resolution_overlay_alloc, pg_temp.finance_case_taxable_channel_restructure_resolution, pg_temp.finance_case_resolution_owner_state, pg_temp.finance_case_resolution_rollup;

  create temporary table finance_case_repaid_wtd on commit drop as
        select
          nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid as finance_case_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as repaid_wtd_ex
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        left join public.pay_bank_transfers pbt
          on pbt.id = pbi.pay_bank_transfer_id
        where coalesce(pbi.is_voided, false) = false
          and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
          and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
          and pbi.repayment_week_start = v_week_start
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
          and not exists (
            select 1
            from public.pay_payment_correction_items pci_repaid_wtd
            where pci_repaid_wtd.pay_batch_item_id = pbi.id
              and pci_repaid_wtd.status = 'APPLIED'
              and pci_repaid_wtd.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
            or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
            or pbt.completed_at_utc is not null
            or exists (
              select 1
              from public.pay_advance_reservations par_repaid_wtd
              where par_repaid_wtd.pay_batch_item_id = pbi.id
                and (
                  upper(btrim(coalesce(par_repaid_wtd.status, ''))) = 'SETTLED'
                  or par_repaid_wtd.settled_at_utc is not null
                )
            )
          )
        group by nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid

  ;


  /* Policy X: recovery headroom is pre-draft live truth, but it must use the
     same central economic-outstanding authority that preview materialisation
     uses.  Raw timesheet deltas whose settled baseline is already exhausted
     must not create funds from which a recovery can be taken. */
  drop table if exists pg_temp.candidate_authoritative_recovery_headroom;

  create temporary table candidate_authoritative_recovery_headroom on commit drop as
        with recovery_timesheet_scope as (
          select
            cr.candidate_id,
            coalesce(
              array_agg(distinct tcr.timesheet_id order by tcr.timesheet_id)
                filter (where tcr.timesheet_id is not null),
              array[]::uuid[]
            ) as timesheet_ids
          from candidate_rollup cr
          left join timesheet_case_rollup_payable tcr
            on tcr.candidate_id = cr.candidate_id
           and coalesce(tcr.is_blocked, false) = false
          group by cr.candidate_id
        )
        select
          rts.candidate_id,
          round(
            coalesce(
              sum(greatest(coalesce(oc.outstanding_ex_vat, 0), 0)),
              0
            ),
            2
          )::numeric(12,2) as authoritative_recovery_headroom_ex
        from recovery_timesheet_scope rts
        left join lateral public._pay_outstanding_components(
          rts.timesheet_ids,
          null::uuid
        ) oc on true
        group by rts.candidate_id

  ;


  -- A28: honour the slice hand-over only inside the exact authoritative Workbench build that set it.
  v_a28_slice_applies := v_a28_slice IS NOT NULL
    AND COALESCE((v_a28_slice->>'final')::boolean, false)
    AND COALESCE(v_a28_slice->>'build_token', '') <> ''
    AND v_a28_slice->>'build_token' = COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token', true), '');
  IF v_a28_slice_applies THEN
    v_a28_slice_candidate_id := (v_a28_slice->>'candidate_id')::uuid;
  END IF;
  IF v_a28_slice_applies THEN
    -- The final slice's own payable Timesheets plus the carried, additive headroom of the earlier slices equals
    -- the headroom an unsliced reconciliation of the whole Candidate computes.
    UPDATE pg_temp.candidate_authoritative_recovery_headroom
    SET authoritative_recovery_headroom_ex = ROUND(authoritative_recovery_headroom_ex
      + COALESCE((v_a28_slice->>'prior_recovery_headroom_ex')::numeric, 0), 2)::numeric(12,2)
    WHERE candidate_id = v_a28_slice_candidate_id;
  END IF;

create temporary table finance_case_recovery_rows_base on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          upper(coalesce(cr.cand_pay_method,'')) as candidate_pay_method,
          round(greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),2)::numeric(12,2) as run_earnings_headroom_ex,
          round(
            greatest(
              coalesce(pwb.paid_wtd_before,0)
              + greatest(coalesce(carh.authoritative_recovery_headroom_ex,0),0),
              0
            ),
            2
          )::numeric(12,2) as run_take_home_before,
          round(greatest(coalesce(c.min_take_home_wtd,0),0),2)::numeric(12,2) as default_take_home_floor,
          vfcr.payout_status,
          vfcr.created_at,
          case
            when vfcr.minimum_earnings_threshold is null then null::numeric(12,2)
            else round(greatest(vfcr.minimum_earnings_threshold,0),2)::numeric(12,2)
          end as minimum_earnings_threshold,
          case
            when vfcr.take_home_floor_override is null then null::numeric(12,2)
            else round(greatest(vfcr.take_home_floor_override,0),2)::numeric(12,2)
          end as take_home_floor_override,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE'
                 and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'OVERPAYMENT'
                then greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                else 0::numeric
              end,
              0::numeric
            ),
            2
          )::numeric(12,2) as nominal_due_amount
        from finance_case_baseline_scope vfcr
        join candidate_rollup cr
          on cr.candidate_id = vfcr.candidate_id
        join candidate_authoritative_recovery_headroom carh
          on carh.candidate_id = vfcr.candidate_id
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join paid_wtd_before pwb
          on pwb.candidate_id = vfcr.candidate_id
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        where vfcr.case_type in ('PAYMENT_ADVANCE','MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          and (
            (vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID')
            or vfcr.case_type in ('MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          )

  ;

  create temporary table manual_debt_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table manual_debt_recovery_allocations on commit drop as
        select
          mdra.candidate_id,
          mdra_alloc.finance_case_id,
          round(coalesce(mdra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            mdrr.candidate_id,
            max(mdrr.run_earnings_headroom_ex) as run_earnings_headroom_ex,
            max(mdrr.run_take_home_before) as run_take_home_before,
            max(mdrr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', mdrr.sort_order,
                'finance_case_id', mdrr.finance_case_id::text,
                'case_type', mdrr.case_type::text,
                'payout_status', case when mdrr.payout_status is null then null else mdrr.payout_status::text end,
                'nominal_due_amount', mdrr.nominal_due_amount,
                'minimum_earnings_threshold', mdrr.minimum_earnings_threshold,
                'take_home_floor_override', mdrr.take_home_floor_override
              )
              order by mdrr.sort_order, mdrr.finance_case_id
            ) as recovery_rows_json
          from manual_debt_recovery_rows mdrr
          group by mdrr.candidate_id
        ) mdra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => mdra.recovery_rows_json,
          p_run_earnings_headroom => mdra.run_earnings_headroom_ex,
          p_run_take_home_headroom => mdra.run_take_home_before,
          p_default_take_home_floor => mdra.default_take_home_floor
        ) mdra_alloc

  ;

  create temporary table manual_debt_recovery_totals on commit drop as
        select
          mdra.candidate_id,
          round(sum(mdra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from manual_debt_recovery_allocations mdra
        group by mdra.candidate_id

  ;

  create temporary table overpayment_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'OVERPAYMENT'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table overpayment_recovery_allocations on commit drop as
        select
          opra.candidate_id,
          opra_alloc.finance_case_id,
          round(coalesce(opra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            oprr.candidate_id,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_take_home_before
              end
            ) as run_take_home_before,
            max(oprr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', oprr.sort_order,
                'finance_case_id', oprr.finance_case_id::text,
                'case_type', 'MANUAL_DEBT_ADJUSTMENT',
                'payout_status', null,
                'nominal_due_amount', oprr.nominal_due_amount,
                'minimum_earnings_threshold', oprr.minimum_earnings_threshold,
                'take_home_floor_override', oprr.take_home_floor_override
              )
              order by oprr.sort_order, oprr.finance_case_id
            ) as recovery_rows_json
          from overpayment_recovery_rows oprr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = oprr.candidate_id
          group by oprr.candidate_id
        ) opra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => opra.recovery_rows_json,
          p_run_earnings_headroom => opra.run_earnings_headroom_ex,
          p_run_take_home_headroom => opra.run_take_home_before,
          p_default_take_home_floor => opra.default_take_home_floor
        ) opra_alloc

  ;

  create temporary table overpayment_recovery_totals on commit drop as
        select
          opra.candidate_id,
          round(sum(opra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from overpayment_recovery_allocations opra
        group by opra.candidate_id

  ;

  create temporary table payment_advance_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'PAYMENT_ADVANCE'
          and upper(coalesce(fcrrb.payout_status::text,'')) = 'PAID'
          and fcrrb.nominal_due_amount > 0

  ;

  create temporary table payment_advance_recovery_allocations on commit drop as
        select
          para.candidate_id,
          para_alloc.finance_case_id,
          round(coalesce(para_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            parr.candidate_id,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_take_home_before
              end
            ) as run_take_home_before,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', parr.sort_order,
                'finance_case_id', parr.finance_case_id::text,
                'case_type', parr.case_type::text,
                'payout_status', case when parr.payout_status is null then null else parr.payout_status::text end,
                'nominal_due_amount', parr.nominal_due_amount,
                'minimum_earnings_threshold', parr.minimum_earnings_threshold,
                'take_home_floor_override', parr.take_home_floor_override
              )
              order by parr.sort_order, parr.finance_case_id
            ) as recovery_rows_json
          from payment_advance_recovery_rows parr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = parr.candidate_id
          left join overpayment_recovery_totals oprt
            on oprt.candidate_id = parr.candidate_id
          group by parr.candidate_id
        ) para
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => para.recovery_rows_json,
          p_run_earnings_headroom => para.run_earnings_headroom_ex,
          p_run_take_home_headroom => para.run_take_home_before,
          p_default_take_home_floor => null::numeric
        ) para_alloc

  ;

  create temporary table finance_case_protected_allocations on commit drop as
        select
          mdra.finance_case_id,
          mdra.protected_recoverable_amount
        from manual_debt_recovery_allocations mdra

        union all

        select
          opra.finance_case_id,
          opra.protected_recoverable_amount
        from overpayment_recovery_allocations opra

        union all

        select
          para.finance_case_id,
          para.protected_recoverable_amount
        from payment_advance_recovery_allocations para

  ;

  create temporary table finance_case_payee_readiness on commit drop as
        select
          f0.finance_case_id,
          f0.payee_entity_kind,
          f0.payee_entity_id,
          f0.bank_details_hash,
          f0.beneficiary_name,
          f0.sort_code,
          f0.account_number,
          case
            when f0.account_number is null or btrim(coalesce(f0.account_number,'')) = '' then null
            else lpad(right(f0.account_number, 4), greatest(length(f0.account_number), 4), '*')
          end as masked_bank_account,
          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash) as name_check_has_override,
          (bpm.payee_id is not null) as payee_map_present,
          (
            f0.payee_entity_id is null
            or f0.bank_details_hash is null
            or btrim(coalesce(f0.bank_details_hash,'')) = ''
            or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
            or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
            or nullif(btrim(coalesce(f0.account_number,'')), '') is null
          ) as is_missing_bank_details,
          (
            v_need_name_check = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
          ) as is_name_check_blocked,
          (
            v_requires_payee_map = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and bpm.payee_id is null
          ) as is_payee_map_blocked,
          (
            (case
              when (
                f0.payee_entity_id is null
                or f0.bank_details_hash is null
                or btrim(coalesce(f0.bank_details_hash,'')) = ''
                or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                or nullif(btrim(coalesce(f0.account_number,'')), '') is null
              )
              then jsonb_build_array('BLOCKED_BANK_DETAILS')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_need_name_check = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
                and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
              )
              then jsonb_build_array('BLOCKED_NAME_CHECK')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_requires_payee_map = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and bpm.payee_id is null
              )
              then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes
        from (
          select
            vfcr.finance_case_id,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
              else 'CANDIDATE'
            end as payee_entity_kind,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c.umbrella_id
              else vfcr.candidate_id
            end as payee_entity_id,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.bank_details_hash
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.bank_details_hash
              else c.bank_details_hash
            end as bank_details_hash,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.beneficiary_name
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.name
              else coalesce(c.account_holder, c.display_name)
            end as beneficiary_name,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.sort_code
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.sort_code
              else c.sort_code
            end as sort_code,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.account_number
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.account_number
              else c.account_number
            end as account_number
          from finance_case_baseline_scope vfcr
          join public.candidates c
            on c.id = vfcr.candidate_id
          left join public.umbrellas u
            on u.id = c.umbrella_id
          left join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
        ) f0
        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = f0.payee_entity_kind
         and bnc.entity_id = f0.payee_entity_id
         and bnc.bank_details_hash is not distinct from f0.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = f0.payee_entity_kind
         and bpm.entity_id = f0.payee_entity_id
         and bpm.bank_details_hash is not distinct from f0.bank_details_hash

  ;

  create temporary table finance_case_component_rows on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          pfc.id as finance_component_id,
          pfc.source_family_key,
          pfc.component_key_type,
          pfc.component_key_value,
          pfc.classification,
          upper(coalesce(pfc.source_pay_method, '')) as source_pay_method,
          upper(coalesce(cp.cand_pay_method, '')) as current_target_pay_method,
          cp.umb_vat_chargeable,
          pfc.source_basis_json,
          round(coalesce(pfc.source_amount, 0), 2) as source_amount,
          round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_source_amount,
          pfc.saved_target_pay_method,
          pfc.saved_resolution_mode,
          pfc.saved_resolution_payload_json,
          pfc.saved_resolution_result_json,
          pfc.resolution_fingerprint,
          pfc.is_resolution_stale,
          pfc.stale_reason,
          public.pay_finance_component_fingerprint(
            pfc.source_family_key,
            pfc.component_key_type,
            pfc.component_key_value,
            pfc.classification,
            upper(coalesce(pfc.source_pay_method, '')),
            upper(coalesce(cp.cand_pay_method, '')),
            coalesce(pfc.source_basis_json, '{}'::jsonb),
            round(coalesce(pfc.source_amount, 0), 2),
            case
              when coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
                then coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct')::numeric
              else v_erni_pct
            end,
            coalesce(pfc.saved_resolution_payload_json, pfc.saved_resolution_result_json, '{}'::jsonb)
          ) as current_component_fingerprint
        from finance_case_baseline_scope vfcr
        join cand_payee cp
          on cp.candidate_id = vfcr.candidate_id
        join public.pay_finance_case_components pfc
          on pfc.finance_case_id = vfcr.finance_case_id
         and pfc.closed_at_utc is null
         and coalesce(pfc.remaining_source_amount, 0) > 0

  ;


  WITH policy_x_finance_component_rows AS (
    SELECT
      component_row.ctid AS row_ctid,
      policy_key.key_type AS resolved_key_type,
      policy_key.key_value AS resolved_key_value
    FROM finance_case_component_rows AS component_row
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_live_source_json => COALESCE(component_row.source_basis_json, '{}'::jsonb)
        || jsonb_build_object(
          'finance_case_id', component_row.finance_case_id::text,
          'finance_component_id', CASE WHEN component_row.finance_component_id IS NULL THEN NULL ELSE component_row.finance_component_id::text END,
          'source_family_key', component_row.source_family_key,
          'component_key_type', component_row.component_key_type,
          'component_key_value', component_row.component_key_value,
          'classification', CASE WHEN component_row.classification IS NULL THEN NULL ELSE component_row.classification::text END,
          'item_type', CASE
            WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE'
             AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
            WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
            ELSE 'ADJUSTMENT_DELTA'
          END
        ),
      p_item_type => CASE
        WHEN component_row.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE'
         AND UPPER(BTRIM(COALESCE(component_row.component_key_value, ''))) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN component_row.component_key_type = 'EXPENSE_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA'
        WHEN component_row.component_key_type = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        ELSE 'ADJUSTMENT_DELTA'
      END,
      p_key_type_hint => NULL::text,
      p_key_value_hint => NULL::text,
      p_work_date => CASE
        WHEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN NULLIF(BTRIM(COALESCE(component_row.source_basis_json->>'work_date', component_row.source_basis_json->>'date', '')), '')::date
        ELSE NULL::date
      END
    ) AS policy_key ON true
  )
  UPDATE finance_case_component_rows AS component_row
  SET component_key_type = policy_x_finance_component_rows.resolved_key_type,
      component_key_value = policy_x_finance_component_rows.resolved_key_value,
      current_component_fingerprint = public.pay_finance_component_fingerprint(
        component_row.source_family_key,
        policy_x_finance_component_rows.resolved_key_type,
        policy_x_finance_component_rows.resolved_key_value,
        component_row.classification,
        component_row.source_pay_method,
        component_row.current_target_pay_method,
        COALESCE(component_row.source_basis_json, '{}'::jsonb),
        round(COALESCE(component_row.source_amount, 0), 2),
        CASE
          WHEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
            THEN COALESCE(component_row.saved_resolution_payload_json->>'relevant_erni_pct', component_row.saved_resolution_result_json->>'relevant_erni_pct')::numeric
          ELSE v_erni_pct
        END,
        COALESCE(component_row.saved_resolution_payload_json, component_row.saved_resolution_result_json, '{}'::jsonb)
      )
  FROM policy_x_finance_component_rows
  WHERE component_row.ctid = policy_x_finance_component_rows.row_ctid
    AND policy_x_finance_component_rows.resolved_key_type IS NOT NULL
    AND policy_x_finance_component_rows.resolved_key_value IS NOT NULL;

  create temporary table finance_case_component_review_rows on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          nullif(fccr.source_basis_json->>'source_units','')::numeric as source_units,
          nullif(fccr.source_basis_json->>'source_rate','')::numeric as source_rate,
          nullif(fccr.source_basis_json->>'source_charge_rate','')::numeric as source_charge_rate,
          coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) as source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'REUSABLE_SAVED_RESOLUTION'
            when fccr.saved_resolution_mode is not null then 'STALE_SAVED_RESOLUTION'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
            and fccr.saved_resolution_mode is null
          ) as is_fresh_suggested_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and coalesce(fccr.is_resolution_stale,false) = false
            and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,''))
            and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
          ) as is_reusable_saved_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and (
              coalesce(fccr.is_resolution_stale,false) = true
              or upper(coalesce(fccr.saved_target_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              or (fccr.resolution_fingerprint is not null and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint)
            )
          ) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_payload_json
            else jsonb_strip_nulls(jsonb_build_object(
              'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
              'target_pay_method', fccr.current_target_pay_method,
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'suggested_target_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
            ))
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_result_json
            else jsonb_strip_nulls(jsonb_build_object(
              'target_pay_method', fccr.current_target_pay_method,
              'target_amount_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_amount_vat', round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2),
              'target_amount_inc_vat', round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2),
              'basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'replacement_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'target_amount_ex_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_inc_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_units_per_source_ex_vat', case when nullif(fccr.source_basis_json->>'source_units','') is not null and coalesce(fccr.source_amount,0) <> 0 then round((nullif(fccr.source_basis_json->>'source_units','')::numeric) / fccr.source_amount, 10) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
              'source_pay_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'source_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'source_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - fccr.source_amount,2) end,
              'target_pay_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'target_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end,
              'margin_delta_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(fccr.source_amount - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end
            ))
          end as suggested_resolution_result_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'This component already has a reusable saved resolution for the current target pay method.'
            when fccr.saved_resolution_mode is not null then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.source_pay_method <> fccr.current_target_pay_method then 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
            else 'This suggestion preserves equivalent basis using the current target pay method.'
          end as suggestion_explanation_text
        from finance_case_component_rows fccr
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(fccr.source_amount, v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct))
              when fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(fccr.source_amount,0),2), 'vat', 0, 'inc', round(coalesce(fccr.source_amount,0),2))
              when fccr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(fccr.source_amount, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) fcsr on true

  ;

  create temporary table finance_case_component_review_rows_effective on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          fccr.source_units,
          fccr.source_rate,
          fccr.source_charge_rate,
          fccr.source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          fctx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          fctx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          null::text as approved_nonbucket_resolution_mode,
          null::numeric as approved_nonbucket_target_amount_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then false
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then not (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then false
            when fctx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then true
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then true
            when fctx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'REUSABLE_SAVED_RESOLUTION'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'STALE_SAVED_RESOLUTION'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'FRESH_SUGGESTION'
            when fctx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
            and coalesce(fccr.is_reusable_saved_resolution,false) = false
            and coalesce(fccr.is_stale_saved_resolution,false) = false
            and (
              fctx.is_actionable_bucket_resolution = true
              or fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
            )
          ) as is_fresh_suggested_resolution,
          coalesce(fccr.is_reusable_saved_resolution,false) as is_reusable_saved_resolution,
          coalesce(fccr.is_stale_saved_resolution,false) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_payload_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else fccr.suggested_resolution_payload_json
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_result_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            else fccr.suggested_resolution_result_json
          end as suggested_resolution_result_json,
          round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end as source_charge_component_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
            else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null then round(fbasis.source_charge_basis_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.source_charge_basis_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as target_margin_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.basis_source_amount_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'This component already has a reusable saved resolution for the current target pay method.'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'This non-bucket finance case resolves as one suggested/editable gross total. The total remaining source amount is converted onto the current target pay method.'
            when fctx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text
        from finance_case_component_review_rows fccr
        left join lateral (
          select
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and fccr.source_units is not null
              and coalesce(fccr.source_units,0) <> 0
              and fccr.source_rate is not null
              and fccr.source_charge_rate is not null
              and fccr.component_key_type <> 'ADJUSTMENT_CODE'
    and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
            ) as is_actionable_bucket_resolution,
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and not (
                fccr.source_units is not null
                and coalesce(fccr.source_units,0) <> 0
                and fccr.source_rate is not null
                and fccr.source_charge_rate is not null
                and fccr.component_key_type <> 'ADJUSTMENT_CODE'
                and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
              )
            ) as is_fixed_taxable_conversion
        ) fctx on true
        left join lateral (
          select
            round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0), 2) as basis_source_amount_ex_vat,
            case
              when fccr.source_charge_ex_vat is null then null::numeric
              when round(coalesce(fccr.source_amount,0),2) = 0 then round(coalesce(fccr.source_charge_ex_vat,0),2)
              else round(round(coalesce(fccr.source_charge_ex_vat,0),2) * (round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0),2) / nullif(round(coalesce(fccr.source_amount,0),2),0)), 2)
            end as source_charge_basis_ex_vat
        ) fbasis on true
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct),2)
              when fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) fbase_pre on true
        left join lateral (
          select
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(fbase_pre.target_ex_before_rate / fccr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(round(fbase_pre.target_ex_before_rate / fccr.source_units, 2) * fccr.source_units, 2)
              else round(fbase_pre.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) fbase on true
        left join lateral (
          select
            case
              when fbase.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(fccr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) fbase_amounts on true
        left join lateral (
          select
            case
              when coalesce(fccr.is_reusable_saved_resolution,false) = true
               and coalesce(fccr.is_stale_saved_resolution,false) = false
               and coalesce(fccr.saved_resolution_result_json->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              then round((fccr.saved_resolution_result_json->>'target_amount_ex_vat')::numeric, 2)
              else null::numeric
            end as reusable_saved_target_pay_ex_vat
        ) fsaved on true

  ;


  IF v_workbench_resolution_session_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE finance_case_bucket_resolution_overlay ON COMMIT DROP AS
    WITH stored_resolution_components AS (
      SELECT
        stored_resolution.id AS resolution_id,
        stored_resolution.case_key,
        stored_resolution.timesheet_id,
        stored_resolution.source_basis_fingerprint,
        stored_resolution.source_family_key,
        stored_resolution.bucket_code,
        stored_resolution.component_key_type,
        stored_resolution.component_key_value,
        stored_resolution.payload_json,
        stored_resolution.updated_at_utc,
        bucket_element.ordinality::integer AS bucket_ordinal,
        bucket_element.value AS bucket_json
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(stored_resolution.payload_json->'bucket_resolutions') = 'array'
            THEN stored_resolution.payload_json->'bucket_resolutions'
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS bucket_element(value, ordinality)
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'BUCKETED'
        AND jsonb_typeof(bucket_element.value) = 'object'
    )
    SELECT DISTINCT ON (
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value
    )
      resolved_component.resolution_id,
      resolved_component.finance_case_id,
      resolved_component.case_key,
      resolved_component.timesheet_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      resolved_component.bucket_code,
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.payload_json,
      resolved_component.bucket_json,
      resolved_component.classification,
      resolved_component.source_pay_method,
      resolved_component.target_pay_method,
      resolved_component.source_units,
      resolved_component.source_rate,
      resolved_component.source_charge_rate,
      resolved_component.resolution_mode,
      resolved_component.target_rate
    FROM (
      SELECT
        stored_component.resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_component.payload_json->>'finance_case_id', stored_component.bucket_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_component.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_component.case_key,
        stored_component.timesheet_id,
        COALESCE(
          NULLIF(BTRIM(COALESCE(stored_component.source_basis_fingerprint, '')), ''),
          NULLIF(BTRIM(COALESCE(stored_component.bucket_json->>'source_basis_fingerprint', '')), ''),
          CASE
            WHEN jsonb_typeof(stored_component.bucket_json->'source_basis_json') = 'object'
              THEN md5((stored_component.bucket_json->'source_basis_json')::text)
            ELSE NULL::text
          END
        ) AS source_basis_fingerprint,
        NULLIF(BTRIM(COALESCE(stored_component.source_family_key, stored_component.bucket_json->>'source_family_key', '')), '') AS source_family_key,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.bucket_code, stored_component.bucket_json->>'bucket_code', ''))), '') AS bucket_code,
        NULLIF(UPPER(BTRIM(COALESCE(stored_component.component_key_type, stored_component.bucket_json->>'component_key_type', ''))), '') AS component_key_type,
        NULLIF(BTRIM(COALESCE(stored_component.component_key_value, stored_component.bucket_json->>'component_key_value', '')), '') AS component_key_value,
        stored_component.payload_json,
        stored_component.bucket_json,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'classification', ''))) AS classification,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'source_pay_method', ''))) AS source_pay_method,
        UPPER(BTRIM(COALESCE(
          stored_component.bucket_json->>'target_pay_method',
          stored_component.bucket_json->>'current_target_pay_method',
          stored_component.payload_json->>'target_pay_method',
          stored_component.payload_json->>'current_target_pay_method',
          ''
        ))) AS target_pay_method,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_units')::numeric, 6)
          ELSE NULL::numeric
        END AS source_units,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_rate,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round((stored_component.bucket_json->>'source_charge_rate')::numeric, 6)
          ELSE NULL::numeric
        END AS source_charge_rate,
        UPPER(BTRIM(COALESCE(stored_component.bucket_json->>'resolution_mode', stored_component.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_component.bucket_json->>'target_rate', stored_component.payload_json->>'target_rate')::numeric, 2)
          ELSE NULL::numeric
        END AS target_rate,
        stored_component.updated_at_utc,
        stored_component.bucket_ordinal
      FROM stored_resolution_components AS stored_component
    ) AS resolved_component
    WHERE resolved_component.finance_case_id IS NOT NULL
      AND resolved_component.source_basis_fingerprint IS NOT NULL
      AND resolved_component.source_family_key IS NOT NULL
      AND resolved_component.component_key_type IS NOT NULL
      AND resolved_component.component_key_value IS NOT NULL
      AND resolved_component.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE')
      AND resolved_component.target_rate IS NOT NULL
      AND resolved_component.target_rate >= 0
    ORDER BY
      resolved_component.finance_case_id,
      resolved_component.source_basis_fingerprint,
      resolved_component.source_family_key,
      COALESCE(resolved_component.bucket_code, ''),
      resolved_component.component_key_type,
      resolved_component.component_key_value,
      resolved_component.updated_at_utc DESC,
      resolved_component.resolution_id DESC,
      resolved_component.bucket_ordinal DESC;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_resolution_mode = resolution_overlay.resolution_mode,
        approved_target_rate = resolution_overlay.target_rate,
        saved_target_pay_method = COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
        saved_resolution_mode = resolution_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', resolution_overlay.resolution_mode,
            'target_pay_method', COALESCE(NULLIF(resolution_overlay.target_pay_method, ''), effective_component.current_target_pay_method),
            'target_units', round(effective_component.source_units, 6),
            'target_rate', round(resolution_overlay.target_rate, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(resolution_overlay.bucket_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_units', round(effective_component.source_units, 6),
            'replacement_rate', round(resolution_overlay.target_rate, 2),
            'target_rate', round(resolution_overlay.target_rate, 2),
            'target_amount_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_pay_ex_vat', round(effective_component.source_units * resolution_overlay.target_rate, 2),
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
              ELSE round(
                (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
                - effective_component.source_margin_ex_vat,
                2
              )
            END
          )
        ),
        target_pay_ex_vat = round(effective_component.source_units * resolution_overlay.target_rate, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate), 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL OR effective_component.source_margin_ex_vat IS NULL THEN NULL
          ELSE round(
            (effective_component.source_charge_component_ex_vat - (effective_component.source_units * resolution_overlay.target_rate))
            - effective_component.source_margin_ex_vat,
            2
          )
        END,
        suggestion_explanation_text = 'This component uses the current Workbench Case Resolution selected for this finance case.'
    FROM finance_case_bucket_resolution_overlay AS resolution_overlay
    WHERE effective_component.candidate_id = v_candidate_id
      AND effective_component.finance_case_id = resolution_overlay.finance_case_id
      AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      AND effective_component.source_family_key = resolution_overlay.source_family_key
      AND md5(COALESCE(effective_component.source_basis_json::text, '{}'::text)) = resolution_overlay.source_basis_fingerprint
      AND COALESCE(NULLIF(UPPER(BTRIM(COALESCE(effective_component.source_basis_json->>'bucket_code', ''))), ''), '') = COALESCE(resolution_overlay.bucket_code, '')
      AND effective_component.component_key_type = resolution_overlay.component_key_type
      AND effective_component.component_key_value = resolution_overlay.component_key_value
      AND round(effective_component.source_units, 6) = resolution_overlay.source_units
      AND round(effective_component.source_rate, 6) = resolution_overlay.source_rate
      AND round(effective_component.source_charge_rate, 6) = resolution_overlay.source_charge_rate
      AND (resolution_overlay.classification = '' OR UPPER(effective_component.classification::text) = resolution_overlay.classification)
      AND (resolution_overlay.source_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.source_pay_method, ''))) = resolution_overlay.source_pay_method)
      AND (resolution_overlay.target_pay_method = '' OR UPPER(BTRIM(COALESCE(effective_component.current_target_pay_method, ''))) = resolution_overlay.target_pay_method)
      AND effective_component.is_actionable_resolution_row = true;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay ON COMMIT DROP AS
    SELECT DISTINCT ON (resolved_nonbucket.finance_case_id)
      resolved_nonbucket.resolution_id,
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.case_key,
      resolved_nonbucket.payload_json,
      resolved_nonbucket.resolution_mode,
      resolved_nonbucket.target_amount_ex_vat
    FROM (
      SELECT
        stored_resolution.id AS resolution_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(stored_resolution.payload_json->>'finance_case_id', '')), '')::uuid
          WHEN NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN substring(NULLIF(BTRIM(COALESCE(stored_resolution.case_key, '')), '') from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        stored_resolution.case_key,
        stored_resolution.payload_json,
        UPPER(BTRIM(COALESCE(stored_resolution.payload_json->>'resolution_mode', ''))) AS resolution_mode,
        CASE
          WHEN COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN round(COALESCE(stored_resolution.payload_json->>'target_amount_ex_vat', stored_resolution.payload_json->>'target_amount', stored_resolution.payload_json->>'amount_ex_vat', stored_resolution.payload_json->>'amount')::numeric, 2)
          ELSE NULL::numeric
        END AS target_amount_ex_vat,
        stored_resolution.updated_at_utc
      FROM public.banking_pay_workbench_session_case_resolutions AS stored_resolution
      WHERE stored_resolution.session_id = v_workbench_resolution_session_id
        AND stored_resolution.candidate_id = v_candidate_id
        AND UPPER(BTRIM(COALESCE(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
    ) AS resolved_nonbucket
    WHERE resolved_nonbucket.finance_case_id IS NOT NULL
      AND resolved_nonbucket.resolution_mode IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
      AND resolved_nonbucket.target_amount_ex_vat IS NOT NULL
      AND resolved_nonbucket.target_amount_ex_vat >= 0
    ORDER BY
      resolved_nonbucket.finance_case_id,
      resolved_nonbucket.updated_at_utc DESC,
      resolved_nonbucket.resolution_id DESC;

    CREATE TEMPORARY TABLE finance_case_nonbucket_resolution_overlay_alloc ON COMMIT DROP AS
    WITH target_components AS (
      SELECT
        effective_component.ctid AS row_ctid,
        effective_component.finance_case_id,
        effective_component.finance_component_id,
        resolution_overlay.resolution_id,
        resolution_overlay.payload_json,
        resolution_overlay.resolution_mode,
        resolution_overlay.target_amount_ex_vat,
        round(coalesce(effective_component.remaining_source_amount, 0), 2) AS remaining_source_amount,
        round(sum(coalesce(effective_component.remaining_source_amount, 0)) OVER (PARTITION BY effective_component.finance_case_id), 2) AS total_remaining_source_amount,
        row_number() OVER (PARTITION BY effective_component.finance_case_id ORDER BY effective_component.finance_component_id) AS component_ord,
        count(*) OVER (PARTITION BY effective_component.finance_case_id) AS component_count
      FROM finance_case_component_review_rows_effective AS effective_component
      JOIN finance_case_nonbucket_resolution_overlay AS resolution_overlay
        ON resolution_overlay.finance_case_id = effective_component.finance_case_id
       AND resolution_overlay.case_key = ('finance:' || effective_component.finance_case_id::text)
      WHERE effective_component.candidate_id = v_candidate_id
        AND effective_component.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
        AND effective_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND round(coalesce(effective_component.remaining_source_amount, 0), 2) > 0
    ), preliminary_components AS (
      SELECT
        target_components.*,
        round(
          CASE
            WHEN coalesce(target_components.target_amount_ex_vat, 0) = 0 THEN 0::numeric
            WHEN coalesce(target_components.total_remaining_source_amount, 0) = 0 THEN 0::numeric
            WHEN target_components.component_count = 1 THEN target_components.target_amount_ex_vat
            WHEN target_components.component_ord < target_components.component_count THEN target_components.target_amount_ex_vat * target_components.remaining_source_amount / nullif(target_components.total_remaining_source_amount, 0)
            ELSE 0::numeric
          END,
          2
        ) AS preliminary_target_amount_ex_vat
      FROM target_components
    )
    SELECT
      preliminary_components.row_ctid,
      preliminary_components.finance_case_id,
      preliminary_components.finance_component_id,
      preliminary_components.resolution_id,
      preliminary_components.payload_json,
      preliminary_components.resolution_mode,
      round(
        CASE
          WHEN preliminary_components.component_count = 1 THEN preliminary_components.target_amount_ex_vat
          WHEN preliminary_components.component_ord < preliminary_components.component_count THEN preliminary_components.preliminary_target_amount_ex_vat
          ELSE preliminary_components.target_amount_ex_vat - coalesce(
            sum(preliminary_components.preliminary_target_amount_ex_vat) OVER (
              PARTITION BY preliminary_components.finance_case_id
              ORDER BY preliminary_components.component_ord
              ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ),
            0
          )
        END,
        2
      ) AS allocated_target_amount_ex_vat
    FROM preliminary_components;

    UPDATE finance_case_component_review_rows_effective AS effective_component
    SET approved_nonbucket_resolution_mode = nonbucket_overlay.resolution_mode,
        approved_nonbucket_target_amount_ex_vat = nonbucket_overlay.allocated_target_amount_ex_vat,
        saved_target_pay_method = effective_component.current_target_pay_method,
        saved_resolution_mode = nonbucket_overlay.resolution_mode::public.pay_finance_component_resolution_mode_enum,
        saved_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        saved_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        resolution_fingerprint = effective_component.current_component_fingerprint,
        is_resolution_stale = false,
        stale_reason = NULL,
        requires_resolution = false,
        case_resolution_satisfied_now_component = true,
        suggestion_provenance = 'PREVIEW_CASE_RESOLUTION',
        is_fresh_suggested_resolution = false,
        is_reusable_saved_resolution = true,
        is_stale_saved_resolution = false,
        suggested_resolution_payload_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'resolution_family', 'NON_BUCKET',
            'resolution_mode', nonbucket_overlay.resolution_mode,
            'target_pay_method', effective_component.current_target_pay_method,
            'applied_basis_source_amount_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2)
          )
        ),
        suggested_resolution_result_json = jsonb_strip_nulls(
          COALESCE(nonbucket_overlay.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'target_pay_method', effective_component.current_target_pay_method,
            'target_amount_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'target_pay_ex_vat', round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
            'source_pay_ex_vat', round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2),
            'source_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_charge_ex_vat', effective_component.source_charge_component_ex_vat,
            'target_margin_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END,
            'margin_delta_ex_vat', CASE
              WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
              ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
            END
          )
        ),
        target_pay_ex_vat = round(nonbucket_overlay.allocated_target_amount_ex_vat, 2),
        target_charge_ex_vat = effective_component.source_charge_component_ex_vat,
        target_margin_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(effective_component.source_charge_component_ex_vat - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        margin_delta_ex_vat = CASE
          WHEN effective_component.source_charge_component_ex_vat IS NULL THEN NULL
          ELSE round(round(coalesce(effective_component.remaining_source_amount, effective_component.source_amount, 0), 2) - nonbucket_overlay.allocated_target_amount_ex_vat, 2)
        END,
        suggestion_explanation_text = 'This finance case uses the current Workbench non-bucket Case Resolution selected for this session.'
    FROM finance_case_nonbucket_resolution_overlay_alloc AS nonbucket_overlay
    WHERE effective_component.ctid = nonbucket_overlay.row_ctid;
  END IF;

  create temporary table finance_case_due_source_amounts on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'PAYMENT_ADVANCE' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                when vfcr.case_type = 'UNDERPAYMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else greatest(coalesce(vfcr.outstanding_amount, vfcr.original_amount, 0) - coalesce(vfcr.active_reserved_amount,0), 0)
                end
                when vfcr.case_type = 'OVERPAYMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                )
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                else 0::numeric
              end,
              0::numeric
            ),
            2
          ) as due_source_amount_ex_vat
        from finance_case_baseline_scope vfcr
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        left join finance_case_protected_allocations fcpa
          on fcpa.finance_case_id = vfcr.finance_case_id
        where vfcr.finance_case_id is not null

  ;

  create temporary table finance_case_component_due_source_base on commit drop as
        select
          fce.finance_case_id,
          fce.candidate_id,
          fce.case_type,
          fce.taxability,
          fce.finance_component_id,
          round(coalesce(fce.remaining_source_amount,0),2) as remaining_source_amount,
          round(coalesce(fcds.due_source_amount_ex_vat,0),2) as due_source_amount_ex_vat,
          round(sum(coalesce(fce.remaining_source_amount,0)) over (partition by fce.finance_case_id),2) as total_remaining_source_amount,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count
        from finance_case_component_review_rows_effective fce
        join finance_case_due_source_amounts fcds
          on fcds.finance_case_id = fce.finance_case_id

  ;

  create temporary table finance_case_component_due_source_shares on commit drop as
        select
          fcdsb.*,
          round(
            case
              when coalesce(fcdsb.due_source_amount_ex_vat,0) = 0 then 0::numeric
              when coalesce(fcdsb.total_remaining_source_amount,0) = 0 then 0::numeric
              when fcdsb.component_count = 1 then fcdsb.due_source_amount_ex_vat
              when fcdsb.component_ord < fcdsb.component_count then (fcdsb.due_source_amount_ex_vat * fcdsb.remaining_source_amount / nullif(fcdsb.total_remaining_source_amount,0))
              else 0::numeric
            end,
            2
          ) as preliminary_source_due_amount_ex_vat
        from finance_case_component_due_source_base fcdsb

  ;

  create temporary table finance_case_component_due_source_allocations on commit drop as
        select
          fcdss.finance_case_id,
          fcdss.finance_component_id,
          round(
            case
              when fcdss.component_count = 1 then fcdss.due_source_amount_ex_vat
              when fcdss.component_ord < fcdss.component_count then fcdss.preliminary_source_due_amount_ex_vat
              else fcdss.due_source_amount_ex_vat - coalesce(sum(fcdss.preliminary_source_due_amount_ex_vat) over (partition by fcdss.finance_case_id order by fcdss.component_ord rows between unbounded preceding and 1 preceding), 0)
            end,
            2
          ) as allocated_source_due_amount_ex_vat
        from finance_case_component_due_source_shares fcdss

  ;

  create temporary table finance_case_component_due_preview_base on commit drop as
        select
          fce.finance_case_id,
          fce.finance_component_id,
          fcda.allocated_source_due_amount_ex_vat,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count,
          round(
            case
              when coalesce(fcda.allocated_source_due_amount_ex_vat,0) = 0 then 0::numeric
              when fce.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fce.approved_nonbucket_target_amount_ex_vat,0) <> 0 and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when fce.case_type = 'OVERPAYMENT' and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when round(coalesce(fce.remaining_source_amount,0),2) <> 0 and round(coalesce(fce.target_pay_ex_vat,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              else fcda.allocated_source_due_amount_ex_vat
            end,
            2
          ) as preliminary_preview_due_amount_ex_vat
        from finance_case_component_review_rows_effective fce
        join finance_case_component_due_source_allocations fcda
          on fcda.finance_case_id = fce.finance_case_id
         and fcda.finance_component_id = fce.finance_component_id

  ;

  create temporary table finance_case_component_due_preview_allocations on commit drop as
        select
          fcdpb.finance_case_id,
          fcdpb.finance_component_id,
          round(fcdpb.preliminary_preview_due_amount_ex_vat, 2) as allocated_preview_due_amount_ex_vat
        from finance_case_component_due_preview_base fcdpb

  ;

  create temporary table finance_case_taxable_channel_restructure_resolution on commit drop as
        with component_base as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.candidate_id,
            vfcr.client_id,
            vfcr.next_due_week_start,
            vfcr.weekly_due,
            vfcr.weeks_total,
            vfcr.outstanding_amount,
            vfcr.schedule_json,
            cp.cand_pay_method as target_pay_method,
            fccr.finance_component_id,
            fccr.source_family_key,
            fccr.component_key_type,
            fccr.component_key_value,
            fccr.classification,
            fccr.source_pay_method,
            fccr.current_target_pay_method,
            fccr.umb_vat_chargeable,
            fccr.source_basis_json,
            fccr.source_amount,
            fccr.remaining_source_amount,
            fccr.source_units,
            fccr.source_rate,
            fccr.source_charge_rate,
            fccr.source_charge_ex_vat,
            fccr.saved_target_pay_method,
            fccr.saved_resolution_mode,
            fccr.saved_resolution_payload_json,
            fccr.saved_resolution_result_json,
            fccr.resolution_fingerprint,
            fccr.current_component_fingerprint,
            fccr.is_stale_saved_resolution,
            fccr.is_reusable_saved_resolution,
            fccr.stale_reason,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
            ) as has_taxable_channel_mismatch,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
              and (
                coalesce(fccr.is_stale_saved_resolution,false) = true
                or nullif(btrim(coalesce(fccr.saved_target_pay_method,'')), '') is null
                or upper(coalesce(fccr.saved_target_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
                or (
                  fccr.resolution_fingerprint is not null
                  and fccr.current_component_fingerprint is not null
                  and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint
                )
              )
            ) as requires_component_restructure
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          where vfcr.case_type in (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'UNDERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
            'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
            and fccr.finance_component_id is not null
            and round(coalesce(fccr.remaining_source_amount,0),2) > 0
        ),
        component_projected as (
          select
            cb.*,
            round(
              case
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'UMBRELLA'
                 and cb.current_target_pay_method = 'PAYE'
                  then public._pay_convert_umbrella_to_paye_ex(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct)
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'PAYE'
                 and cb.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_convert_paye_to_umbrella(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct, v_vat_rate_pct, coalesce(cb.umb_vat_chargeable,false))->>'ex')::numeric, 0)
                else round(coalesce(cb.remaining_source_amount,0),2)
              end,
              2
            ) as target_remaining_ex
          from component_base cb
        ),
        component_projected_vat as (
          select
            cpj.*,
            round(
              case
                when cpj.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                else 0
              end,
              2
            ) as target_remaining_vat,
            round(
              coalesce(cpj.target_remaining_ex,0)
              + case
                  when cpj.current_target_pay_method = 'UMBRELLA'
                    then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                  else 0
                end,
              2
            ) as target_remaining_inc
          from component_projected cpj
        ),
        case_shape as (
          select
            cpv.finance_case_id,
            (array_agg(cpv.case_type))[1] as case_type,
            (array_remove(array_agg(cpv.candidate_id), null::uuid))[1] as candidate_id,
            (array_remove(array_agg(cpv.client_id), null::uuid))[1] as client_id,
            max(cpv.next_due_week_start) as next_due_week_start,
            max(cpv.weekly_due) as weekly_due,
            max(cpv.weeks_total) as weeks_total,
            max(cpv.outstanding_amount) as outstanding_amount,
            coalesce((jsonb_agg(cpv.schedule_json order by cpv.finance_component_id) filter (where cpv.schedule_json is not null))->0, '[]'::jsonb) as schedule_json,
            max(cpv.target_pay_method) as target_pay_method,
            count(*)::int as open_component_count,
            count(*) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum)::int as open_taxable_count,
            count(*) filter (where cpv.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum))::int as open_fixed_count,
            bool_or(cpv.has_taxable_channel_mismatch) as has_taxable_channel_mismatch,
            bool_or(cpv.requires_component_restructure) as requires_restructure,
            bool_or(coalesce(cpv.is_reusable_saved_resolution,false)) as is_reusable_saved_resolution,
            bool_or(coalesce(cpv.is_stale_saved_resolution,false)) as is_stale_saved_resolution,
            round(coalesce(sum(cpv.remaining_source_amount),0),2) as existing_source_total_ex,
            round(coalesce(sum(cpv.remaining_source_amount) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as existing_taxable_source_total_ex,
            round(coalesce(sum(cpv.target_remaining_ex),0),2) as suggested_target_total_ex,
            round(coalesce(sum(cpv.target_remaining_vat),0),2) as suggested_target_total_vat,
            round(coalesce(sum(cpv.target_remaining_inc),0),2) as suggested_target_total_inc,
            round(coalesce(sum(cpv.target_remaining_ex) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as suggested_taxable_target_total_ex,
            bool_or(coalesce(cpv.umb_vat_chargeable,false)) as umbrella_vat_chargeable,
            coalesce(
              jsonb_agg(
                jsonb_strip_nulls(jsonb_build_object(
                  'finance_component_id', cpv.finance_component_id::text,
                  'source_family_key', cpv.source_family_key,
                  'component_key_type', cpv.component_key_type,
                  'component_key_value', cpv.component_key_value,
                  'classification', cpv.classification::text,
                  'source_pay_method', cpv.source_pay_method,
                  'target_pay_method', cpv.current_target_pay_method,
                  'source_remaining_amount_ex_vat', round(coalesce(cpv.remaining_source_amount,0),2),
                  'target_remaining_amount_ex_vat', round(coalesce(cpv.target_remaining_ex,0),2),
                  'target_remaining_amount_vat', round(coalesce(cpv.target_remaining_vat,0),2),
                  'target_remaining_amount_inc_vat', round(coalesce(cpv.target_remaining_inc,0),2),
                  'requires_component_conversion', cpv.has_taxable_channel_mismatch,
                  'requires_restructure', cpv.requires_component_restructure,
                  'source_units', cpv.source_units,
                  'source_rate', cpv.source_rate,
                  'source_charge_rate', cpv.source_charge_rate,
                  'source_charge_ex_vat', cpv.source_charge_ex_vat,
                  'saved_target_pay_method', cpv.saved_target_pay_method,
                  'saved_resolution_mode', case when cpv.saved_resolution_mode is null then null else cpv.saved_resolution_mode::text end,
                  'is_reusable_saved_resolution', cpv.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', cpv.is_stale_saved_resolution,
                  'stale_reason', cpv.stale_reason
                ))
                order by cpv.classification::text, cpv.component_key_type, cpv.component_key_value, cpv.finance_component_id
              ),
              '[]'::jsonb
            ) as component_breakdown_json
          from component_projected_vat cpv
          group by cpv.finance_case_id
        ),
        case_with_schedule as (
          select
            cs.*,
            coalesce(cs.next_due_week_start, v_week_start) as restructure_start_week_start,
            coalesce(
              (
                select count(*)::integer
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched(schedule_entry)
                where jsonb_typeof(sched.schedule_entry) = 'object'
                  and coalesce(sched.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched.schedule_entry->>'amount')::numeric) > 0
              ),
              case
                when coalesce(cs.weekly_due,0) > 0 and coalesce(cs.existing_source_total_ex,0) > 0 then greatest(ceil(cs.existing_source_total_ex / cs.weekly_due)::integer, 1)
                when coalesce(cs.weeks_total,0) > 0 then cs.weeks_total
                else 1
              end
            ) as existing_weeks_remaining,
            coalesce(
              nullif(round(coalesce(cs.weekly_due,0),2),0),
              (
                select round(abs((sched2.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched2(schedule_entry)
                where jsonb_typeof(sched2.schedule_entry) = 'object'
                  and coalesce(sched2.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched2.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched2.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched2.schedule_entry->>'amount')::numeric) > 0
                order by (sched2.schedule_entry->>'week_start')::date asc
                limit 1
              ),
              round(ceil((cs.existing_source_total_ex / greatest(coalesce(cs.weeks_total,1),1)) * 100) / 100, 2)
            ) as existing_weekly_due,
            coalesce(
              (
                select round(abs((sched3.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched3(schedule_entry)
                where jsonb_typeof(sched3.schedule_entry) = 'object'
                  and coalesce(sched3.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched3.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched3.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched3.schedule_entry->>'amount')::numeric) > 0
                order by (sched3.schedule_entry->>'week_start')::date desc
                limit 1
              ),
              0::numeric
            ) as existing_final_week_amount
          from case_shape cs
        ),
        open_batch as (
          select
            cws.finance_case_id,
            exists (
              select 1
              from public.pay_batch_items pbi_open
              join public.pay_batch_candidates pbc_open
                on pbc_open.id = pbi_open.pay_batch_candidate_id
              join public.pay_batches pb_open
                on pb_open.id = pbc_open.pay_batch_id
              where coalesce(pbi_open.is_voided,false) = false
                and pb_open.cancelled_at_utc is null
                and upper(coalesce(pb_open.status::text,'')) not in ('CANCELLED','COMPLETED','SETTLED')
                and (
                  pbi_open.finance_case_id = cws.finance_case_id
                  or exists (
                    select 1
                    from public.pay_finance_case_components pfc_open
                    where pfc_open.finance_case_id = cws.finance_case_id
                      and pfc_open.closed_at_utc is null
                      and pfc_open.id = pbi_open.finance_component_id
                  )
                )
            ) as has_open_batch_item
          from case_with_schedule cws
        )
        select
          cws.finance_case_id,
          coalesce(cws.requires_restructure,false) as has_dedicated_resolution_payload,
          coalesce(cws.requires_restructure,false) as use_dedicated_blocker,
          case
            when coalesce(cws.requires_restructure,false) = true then jsonb_strip_nulls(jsonb_build_object(
              'resolution_kind', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_action_label', 'Suggested Restructure',
              'modal_title', 'Finance Restructure',
              'finance_case_id', cws.finance_case_id::text,
              'case_type', cws.case_type::text,
              'source_method', (
                select coalesce(jsonb_agg(distinct cb.source_pay_method), '[]'::jsonb)
                from component_base cb
                where cb.finance_case_id = cws.finance_case_id
                  and cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              ),
              'target_method', cws.target_pay_method,
              'can_apply', coalesce(ob.has_open_batch_item,false) = false,
              'open_batch_blocked_reason', case when coalesce(ob.has_open_batch_item,false) = true then 'CASE_ALREADY_IN_OPEN_BATCH' else null end,
              'existing_arrangement', jsonb_build_object(
                'source_remaining_balance_ex_vat', cws.existing_source_total_ex,
                'taxable_source_remaining_balance_ex_vat', cws.existing_taxable_source_total_ex,
                'weekly_due', round(coalesce(cws.existing_weekly_due,0),2),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', case
                  when coalesce(cws.existing_final_week_amount,0) > 0 then round(cws.existing_final_week_amount,2)
                  else round(least(round(coalesce(cws.existing_weekly_due,0),2), greatest(cws.existing_source_total_ex - (round(coalesce(cws.existing_weekly_due,0),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),0)),2)
                end,
                'start_week_start', cws.restructure_start_week_start::text,
                'schedule_json', coalesce(cws.schedule_json,'[]'::jsonb)
              ),
              'suggested_arrangement', jsonb_build_object(
                'target_remaining_balance_ex_vat', cws.suggested_target_total_ex,
                'target_remaining_balance_vat', cws.suggested_target_total_vat,
                'target_remaining_balance_inc_vat', cws.suggested_target_total_inc,
                'taxable_target_remaining_balance_ex_vat', cws.suggested_taxable_target_total_ex,
                'weekly_due', round(
                  greatest(
                    round(coalesce(cws.existing_weekly_due,0),2)
                    * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end,
                    0.01
                  ),
                  2
                ),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', round(
                  least(
                    greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),
                    greatest(
                      cws.suggested_target_total_ex
                      - (round(greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),
                      0
                    )
                  ),
                  2
                ),
                'erni_rate_pct', round(v_erni_pct,6),
                'erni_component_ex_vat', round(abs(cws.existing_taxable_source_total_ex - cws.suggested_taxable_target_total_ex),2),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'vat_amount', cws.suggested_target_total_vat,
                'umbrella_vat_chargeable', coalesce(cws.umbrella_vat_chargeable,false)
              ),
              'component_breakdown', cws.component_breakdown_json,
              'suggestion_explanation_text', 'This taxable finance case must be durably restructured onto the current pay method before it can move to Ready to Pay.'
            ))
            else null::jsonb
          end as taxable_channel_restructure_resolution_json
        from case_with_schedule cws
        left join open_batch ob
          on ob.finance_case_id = cws.finance_case_id

  ;

  /*
   * Cancellation ownership is deliberately independent from the blocker that
   * an applied resolution has satisfied.  A finance line is clearable only
   * when one exact, current, server-owned resolution can be proved.  This is
   * pre-Draft live authority; frozen Draft and downstream artefacts are not
   * consulted or rewritten here (Policy X).
   */
  create temporary table finance_case_resolution_owner_state on commit drop as
  with taxable_owner_rows as (
    select
      component_row.finance_case_id,
      component_row.finance_component_id,
      component_row.classification,
      component_row.saved_target_pay_method,
      component_row.saved_resolution_mode,
      component_row.saved_resolution_payload_json,
      component_row.saved_resolution_result_json,
      component_row.resolution_fingerprint,
      component_row.is_resolution_stale,
      component_row.current_target_pay_method,
      component_row.current_component_fingerprint,
      (
        component_row.saved_target_pay_method is not null
        or component_row.saved_resolution_mode is not null
        or component_row.saved_resolution_payload_json is not null
        or component_row.saved_resolution_result_json is not null
        or nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        or coalesce(component_row.is_resolution_stale, false) = true
      ) as has_saved_evidence,
      (
        component_row.saved_resolution_mode is not null
        and jsonb_typeof(component_row.saved_resolution_payload_json) = 'object'
        and jsonb_typeof(component_row.saved_resolution_result_json) = 'object'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_payload_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and (
          case upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
            when 'TAXABLE_CHANNEL' then 'TAXABLE_CHANNEL_RESTRUCTURE'
            else upper(btrim(coalesce(component_row.saved_resolution_result_json->>'resolution_family', '')))
          end
        ) = 'TAXABLE_CHANNEL_RESTRUCTURE'
        and coalesce(component_row.is_resolution_stale, false) = false
        and nullif(btrim(coalesce(component_row.saved_target_pay_method, '')), '') is not null
        and upper(btrim(component_row.saved_target_pay_method)) = upper(btrim(coalesce(component_row.current_target_pay_method, '')))
        and nullif(btrim(coalesce(component_row.resolution_fingerprint, '')), '') is not null
        and component_row.resolution_fingerprint is not distinct from component_row.current_component_fingerprint
      ) as is_current_taxable_owner_component
    from finance_case_component_review_rows as component_row
    where component_row.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and round(coalesce(component_row.remaining_source_amount, 0), 2) > 0
  ), taxable_owner_state as (
    select
      taxable_row.finance_case_id,
      count(*)::integer as taxable_component_count,
      count(*) filter (where taxable_row.is_current_taxable_owner_component)::integer as current_taxable_component_count,
      count(*) filter (where taxable_row.has_saved_evidence)::integer as taxable_saved_evidence_count
    from taxable_owner_rows as taxable_row
    group by taxable_row.finance_case_id
  ), nonbucket_owner_rows as (
    select
      stored_resolution.id as resolution_id,
      case
        when stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then substring(stored_resolution.case_key from 9)::uuid
        else null::uuid
      end as finance_case_id,
      stored_resolution.case_key,
      stored_resolution.timesheet_id,
      stored_resolution.payload_json,
      linked_identity.linked_timesheet_id,
      (
        jsonb_typeof(stored_resolution.payload_json) = 'object'
        and stored_resolution.case_key ~* '^finance:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
        and upper(btrim(coalesce(stored_resolution.payload_json->>'resolution_mode', ''))) in ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT')
        and coalesce(
          stored_resolution.payload_json->>'target_amount_ex_vat',
          stored_resolution.payload_json->>'target_amount',
          stored_resolution.payload_json->>'amount_ex_vat',
          stored_resolution.payload_json->>'amount',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
        and case
          when coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          then coalesce(
            stored_resolution.payload_json->>'target_amount_ex_vat',
            stored_resolution.payload_json->>'target_amount',
            stored_resolution.payload_json->>'amount_ex_vat',
            stored_resolution.payload_json->>'amount'
          )::numeric >= 0
          else false
        end
        and (
          nullif(btrim(coalesce(stored_resolution.payload_json->>'finance_case_id', '')), '') is null
          or btrim(stored_resolution.payload_json->>'finance_case_id') = substring(stored_resolution.case_key from 9)
        )
        and linked_identity.identity_is_valid
      ) as is_valid_nonbucket_owner
    from public.banking_pay_workbench_session_case_resolutions as stored_resolution
    left join lateral (
      select
        case
          when count(distinct identity_value) <= 1
            and count(*) filter (where identity_value is null and raw_value <> '') = 0
          then min(identity_value)::uuid
          else null::uuid
        end as linked_timesheet_id,
        (
          count(distinct identity_value) <= 1
          and count(*) filter (where identity_value is null and raw_value <> '') = 0
        ) as identity_is_valid
      from (
        select
          raw_identity.raw_value,
          case
            when raw_identity.raw_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then lower(raw_identity.raw_value)
            else null::text
          end as identity_value
        from unnest(array[
          coalesce(stored_resolution.timesheet_id::text, ''),
          btrim(coalesce(stored_resolution.payload_json->>'linked_timesheet_id', '')),
          btrim(coalesce(stored_resolution.payload_json->>'timesheet_id', ''))
        ]) as raw_identity(raw_value)
      ) as normalized_identity
    ) as linked_identity on true
    where stored_resolution.session_id = v_workbench_resolution_session_id
      and stored_resolution.candidate_id = v_candidate_id
      and upper(btrim(coalesce(stored_resolution.resolution_family, ''))) = 'NON_BUCKET'
  ), nonbucket_owner_state as (
    select
      nonbucket_row.finance_case_id,
      count(*)::integer as nonbucket_owner_row_count,
      count(*) filter (where nonbucket_row.is_valid_nonbucket_owner)::integer as valid_nonbucket_owner_row_count,
      case
        when count(*) = 1 and count(*) filter (where nonbucket_row.is_valid_nonbucket_owner) = 1
          then min(nonbucket_row.linked_timesheet_id::text)::uuid
        else null::uuid
      end as current_nonbucket_linked_timesheet_id
    from nonbucket_owner_rows as nonbucket_row
    where nonbucket_row.finance_case_id is not null
    group by nonbucket_row.finance_case_id
  )
  select
    scope_row.finance_case_id,
    coalesce(taxable_state.taxable_component_count, 0) as taxable_component_count,
    coalesce(taxable_state.current_taxable_component_count, 0) as current_taxable_component_count,
    coalesce(taxable_state.taxable_saved_evidence_count, 0) as taxable_saved_evidence_count,
    coalesce(nonbucket_state.nonbucket_owner_row_count, 0) as nonbucket_owner_row_count,
    coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) as valid_nonbucket_owner_row_count,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'TAXABLE_CHANNEL_RESTRUCTURE'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'NON_BUCKET'
      else null::text
    end as current_saved_resolution_family,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        then 'FINANCE_COMPONENT_SET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT'
        then 'SESSION_NON_BUCKET'
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
        then 'AMBIGUOUS'
      else 'NONE'
    end as current_saved_resolution_owner_kind,
    case
      when coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
        then taxable_state.current_taxable_component_count
      when coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
        then 1
      else 0
    end::integer as current_saved_resolution_owner_count,
    (
      (coalesce(taxable_state.taxable_component_count, 0) > 0
       and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
       and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT'))
      or
      (coalesce(taxable_state.taxable_saved_evidence_count, 0) = 0
       and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
       and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) = 1
       and scope_row.case_type = 'MANUAL_DEBT_ADJUSTMENT')
    ) as has_current_saved_resolution,
    (
      (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and not (
          coalesce(taxable_state.taxable_component_count, 0) > 0
          and taxable_state.current_taxable_component_count = taxable_state.taxable_component_count
          and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 0
          and scope_row.case_type in ('OVERPAYMENT', 'UNDERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT_ADJUSTMENT')
        )
      )
      or coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 1
      or (
        coalesce(nonbucket_state.nonbucket_owner_row_count, 0) = 1
        and coalesce(nonbucket_state.valid_nonbucket_owner_row_count, 0) <> 1
      )
      or (
        coalesce(taxable_state.taxable_saved_evidence_count, 0) > 0
        and coalesce(nonbucket_state.nonbucket_owner_row_count, 0) > 0
      )
    ) as has_ambiguous_saved_resolution,
    nonbucket_state.current_nonbucket_linked_timesheet_id as current_saved_resolution_linked_timesheet_id
  from finance_case_baseline_scope as scope_row
  left join taxable_owner_state as taxable_state
    on taxable_state.finance_case_id = scope_row.finance_case_id
  left join nonbucket_owner_state as nonbucket_state
    on nonbucket_state.finance_case_id = scope_row.finance_case_id
  where scope_row.finance_case_id is not null;

  create temporary table finance_case_resolution_rollup on commit drop as
        with grouped as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method as candidate_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            fpr.bank_details_hash as payee_bank_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then true
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then true
              else false
            end as is_recovery_case,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then '[]'::jsonb
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then '[]'::jsonb
              else coalesce(fpr.blocked_reason_codes, '[]'::jsonb)
            end as payee_blocked_reason_codes,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then 'one-off specified bank account'
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'umbrella company'
              else 'normal PAYE route'
            end as destination_label,
            round(coalesce(max(fcds.due_source_amount_ex_vat),0),2) as due_source_amount_ex_vat,
            round(coalesce(sum(fcdpa.allocated_preview_due_amount_ex_vat), max(fcds.due_source_amount_ex_vat), 0),2) as due_amount_ex_vat,
            coalesce(fctcr.has_dedicated_resolution_payload,false) as has_taxable_channel_restructure_payload,
            coalesce(fctcr.use_dedicated_blocker,false) as use_taxable_channel_restructure_blocker,
            fctcr.taxable_channel_restructure_resolution_json as taxable_channel_restructure_resolution_json,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'TAXABLE_CHANNEL_RESTRUCTURE'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'NON_BUCKET'::text
              else 'BUCKETED'::text
            end as resolution_family,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'Suggested Restructure'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Suggested Gross Total'::text
              else 'Suggested Rate'::text
            end as resolution_action_label,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            coalesce(fcros.current_saved_resolution_owner_count, 0)::integer as current_saved_resolution_owner_count,
            coalesce(fcros.has_current_saved_resolution, false) as has_current_saved_resolution,
            coalesce(fcros.has_ambiguous_saved_resolution, false) as has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0)::int as open_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0)::int as open_reimbursement_count,
            (coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true), 0)
              + case when coalesce(fctcr.use_dedicated_blocker,false) = true then 1 else 0 end)::int as unresolved_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.is_stale_saved_resolution,false) = true), 0)::int as stale_count,
            (coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0) > 0
             and
             coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0) > 0) as is_mixed_case,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = true
              or coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) > 0
            ) as case_needs_resolution,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = false
              and coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) = 0
            ) as case_resolution_satisfied_now,
            case when coalesce(fctcr.use_dedicated_blocker,false) = true then null::jsonb else coalesce(
              (jsonb_agg(
                jsonb_build_object(
                  'resolution_kind', 'NON_BUCKET_GROSS_TOTAL',
                  'resolution_family', 'NON_BUCKET',
                  'resolution_action_label', 'Suggested Gross Total',
                  'source_amount_ex_vat', round(coalesce(fccr.remaining_source_amount,0),2),
                  'suggested_target_amount_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'approved_target_amount_ex_vat', case when fccr.approved_nonbucket_target_amount_ex_vat is null then null else round(fccr.approved_nonbucket_target_amount_ex_vat,2) end,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text
                )
              ) filter (where vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fccr.finance_component_id is not null))->0,
              null::jsonb
            ) end as non_bucket_resolution_json,
            coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'finance_component_id', fccr.finance_component_id::text,
                  'source_family_key', fccr.source_family_key,
                  'component_key_type', fccr.component_key_type,
                  'component_key_value', fccr.component_key_value,
                  'classification', fccr.classification::text,
                  'source_pay_method', fccr.source_pay_method,
                  'current_target_pay_method', fccr.current_target_pay_method,
                  'source_amount', round(coalesce(fccr.source_amount,0),2),
                  'remaining_source_amount', round(coalesce(fccr.remaining_source_amount,0),2),
                  'source_basis_json', jsonb_strip_nulls(fccr.source_basis_json || jsonb_build_object('source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end, 'source_charge_rate', case when fccr.source_charge_rate is null then null else round(fccr.source_charge_rate,2) end)),
                  'saved_target_pay_method', fccr.saved_target_pay_method,
                  'saved_resolution_mode', case when fccr.saved_resolution_mode is null then null else fccr.saved_resolution_mode::text end,
                  'saved_resolution_payload_json', fccr.saved_resolution_payload_json,
                  'saved_resolution_result_json', fccr.saved_resolution_result_json,
                  'has_suggested_resolution', fccr.has_suggested_resolution,
                  'suggestion_provenance', fccr.suggestion_provenance,
                  'is_fresh_suggested_resolution', fccr.is_fresh_suggested_resolution,
                  'is_reusable_saved_resolution', fccr.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', fccr.is_stale_saved_resolution,
                  'suggested_resolution_payload_json', fccr.suggested_resolution_payload_json,
                  'suggested_resolution_result_json', fccr.suggested_resolution_result_json,
                  'source_units', fccr.source_units,
                  'target_units', case when nullif(fccr.suggested_resolution_result_json->>'target_units','') is not null then (fccr.suggested_resolution_result_json->>'target_units')::numeric else fccr.source_units end,
                  'source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end,
                  'target_rate', case when nullif(fccr.suggested_resolution_result_json->>'replacement_rate','') is not null then round((fccr.suggested_resolution_result_json->>'replacement_rate')::numeric,2) when nullif(fccr.suggested_resolution_payload_json->>'suggested_target_rate','') is not null then round((fccr.suggested_resolution_payload_json->>'suggested_target_rate')::numeric,2) else null end,
                  'source_pay_ex_vat', round(coalesce(fccr.source_pay_ex_vat,0),2),
                  'source_charge_ex_vat', fccr.source_charge_component_ex_vat,
                  'source_margin_ex_vat', fccr.source_margin_ex_vat,
                  'target_pay_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'target_charge_ex_vat', fccr.target_charge_ex_vat,
                  'target_margin_ex_vat', fccr.target_margin_ex_vat,
                  'margin_delta_ex_vat', fccr.margin_delta_ex_vat,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text,
                  'component_fingerprint', fccr.current_component_fingerprint,
                  'is_resolution_stale', coalesce(fccr.is_stale_saved_resolution,false),
                  'stale_reason', fccr.stale_reason,
                  'requires_resolution', coalesce(fccr.requires_resolution,false),
                  'resolution_state', case
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fccr.requires_resolution,false) = true then 'REQUIRED'
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'RESOLVED'
                    else case when fccr.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'FIXED' when coalesce(fccr.requires_resolution,false) = true then 'REQUIRED' else 'RESOLVED' end
                  end,
                  'is_actionable_resolution_row', coalesce(fccr.is_actionable_resolution_row,false),
                  'is_fixed_no_action_taxable_row', coalesce(fccr.is_fixed_no_action_taxable_row,false),
                  'allocated_source_due_amount_ex_vat', round(coalesce(fcda.allocated_source_due_amount_ex_vat,0),2),
                  'preview_due_amount_ex_vat', round(coalesce(fcdpa.allocated_preview_due_amount_ex_vat, coalesce(fcda.allocated_source_due_amount_ex_vat,0)),2)
                )
                order by fccr.classification::text, fccr.component_key_type, fccr.component_key_value
              ) filter (where fccr.finance_component_id is not null),
              '[]'::jsonb
            ) as case_components_json
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          left join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          left join finance_case_payee_readiness fpr
            on fpr.finance_case_id = vfcr.finance_case_id
          left join finance_case_due_source_amounts fcds
            on fcds.finance_case_id = vfcr.finance_case_id
          left join finance_case_component_due_source_allocations fcda
            on fcda.finance_case_id = fccr.finance_case_id
           and fcda.finance_component_id = fccr.finance_component_id
          left join finance_case_component_due_preview_allocations fcdpa
            on fcdpa.finance_case_id = fccr.finance_case_id
           and fcdpa.finance_component_id = fccr.finance_component_id
          left join finance_case_taxable_channel_restructure_resolution fctcr
            on fctcr.finance_case_id = vfcr.finance_case_id
          left join finance_case_resolution_owner_state fcros
            on fcros.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
          group by
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            fpr.bank_details_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            fpr.blocked_reason_codes,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            vfcr.payout_status,
            fctcr.has_dedicated_resolution_payload,
            fctcr.use_dedicated_blocker,
            fctcr.taxable_channel_restructure_resolution_json,
            fcros.current_saved_resolution_family,
            fcros.current_saved_resolution_owner_kind,
            fcros.current_saved_resolution_owner_count,
            fcros.has_current_saved_resolution,
            fcros.has_ambiguous_saved_resolution,
            fcros.current_saved_resolution_linked_timesheet_id
        )
        select
          g.finance_case_id,
          g.case_type,
          g.advance_kind,
          g.reason,
          g.candidate_id,
          g.cand_tms_ref,
          g.cand_display_name,
          g.candidate_pay_method,
          g.payee_entity_kind,
          g.payee_entity_id,
          (jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) = 0) as candidate_ready_for_draft,
          g.client_id,
          g.client_name,
          g.linked_timesheet_id,
          g.linked_shift_date,
          g.adjustment_comment,
          g.next_due_week_start,
          g.active_snooze_id,
          g.active_snooze_kind,
          g.active_snooze_until_date,
          g.active_snooze_note,
          g.taxability,
          g.routing_kind,
          g.oneoff_bank_details_present,
          g.oneoff_bank_details_required,
          g.is_candidate_directed_oneoff_payout,
          g.appears_on_umbrella_remittance,
          g.generates_candidate_payment_advice,
          g.snooze_allowed,
          g.lifecycle_status_display,
          g.payee_bank_hash,
          g.beneficiary_name,
          g.masked_bank_account,
          g.destination_label,
          g.due_amount_ex_vat,
          g.open_taxable_count,
          g.open_reimbursement_count,
          g.unresolved_taxable_count,
          g.stale_count,
          g.is_mixed_case,
          g.resolution_family,
          case when g.case_needs_resolution then g.resolution_family else null::text end as required_resolution_family,
          g.current_saved_resolution_family,
          g.current_saved_resolution_owner_kind,
          g.current_saved_resolution_owner_count,
          g.has_current_saved_resolution,
          g.has_ambiguous_saved_resolution,
          g.current_saved_resolution_linked_timesheet_id,
          case
            when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
            when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
            when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
            else 'NOT_REQUIRED'
          end as finance_resolution_clearability_state,
          case
            when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
            else null::text
          end as finance_resolution_clear_block_reason,
          g.case_needs_resolution,
          g.case_resolution_satisfied_now,
          g.resolution_action_label,
          g.taxable_channel_restructure_resolution_json,
          null::jsonb as linked_resolution_scope_json,
          (
            g.case_needs_resolution = true
            or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
          ) as is_blocked,
          (
            coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
              when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
              when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          jsonb_strip_nulls(
            jsonb_build_object(
              'case_key', ('finance:' || g.finance_case_id::text),
              'case_type', g.case_type::text,
              'resolution_family', g.resolution_family,
              'required_resolution_family', case when g.case_needs_resolution then g.resolution_family else null end,
              'current_saved_resolution_family', g.current_saved_resolution_family,
              'current_saved_resolution_owner_kind', g.current_saved_resolution_owner_kind,
              'current_saved_resolution_owner_count', g.current_saved_resolution_owner_count,
              'has_current_saved_resolution', g.has_current_saved_resolution,
              'has_ambiguous_saved_resolution', g.has_ambiguous_saved_resolution,
              'current_saved_resolution_linked_timesheet_id', case
                when g.current_saved_resolution_linked_timesheet_id is null then null
                else g.current_saved_resolution_linked_timesheet_id::text
              end,
              'finance_resolution_clearability_state', case
                when g.has_ambiguous_saved_resolution then 'STALE_OR_AMBIGUOUS'
                when g.has_current_saved_resolution then 'RESOLVED_AND_CLEARABLE'
                when g.case_needs_resolution then 'REQUIRES_RESOLUTION'
                else 'NOT_REQUIRED'
              end,
              'finance_resolution_clear_block_reason', case
                when g.has_ambiguous_saved_resolution then 'SAVED_RESOLUTION_OWNER_STALE_OR_AMBIGUOUS'
                else null
              end,
              'case_needs_resolution', g.case_needs_resolution,
              'case_resolution_satisfied_now', g.case_resolution_satisfied_now,
              'resolution_action_label', g.resolution_action_label,
              'linked_resolution_scope_json', null,
              'taxability', case when g.taxability is null then null else g.taxability::text end,
              'routing_kind', case when g.routing_kind is null then null else g.routing_kind::text end,
              'destination_label', g.destination_label,
              'is_mixed_case', g.is_mixed_case,
              'open_taxable_count', g.open_taxable_count,
              'open_reimbursement_count', g.open_reimbursement_count,
              'unresolved_taxable_count', g.unresolved_taxable_count,
              'stale_count', g.stale_count,
              'is_blocked', (
                g.case_needs_resolution = true
                or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
              ),
              'due_amount_ex_vat', g.due_amount_ex_vat,
              'blocked_reason_codes', (
                coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
                ||
                (case
                  when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
                  when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
                  when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                  else '[]'::jsonb
                end)
              ),
              'non_bucket_resolution', g.non_bucket_resolution_json,
              'taxable_channel_restructure', g.taxable_channel_restructure_resolution_json,
              'taxable_channel_restructure_resolution', g.taxable_channel_restructure_resolution_json
            )
          ) as case_resolution_summary_json,
          case
            when g.resolution_family = 'NON_BUCKET'
              and jsonb_typeof(g.non_bucket_resolution_json) = 'object'
            then g.non_bucket_resolution_json
            else null::jsonb
          end as taxable_manual_debt_resolution_json,
          g.case_components_json
        from grouped g

  ;

  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_RESULT',
    jsonb_build_object(
      'candidate_id', v_candidate_id,
      'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
      'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup),
      'finance_case_repaid_wtd_count', (select count(*)::int from finance_case_repaid_wtd)
    ),
    'pay_preview_finance',
    COALESCE(v_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
    'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup)
  );

exception
  when others then
    PERFORM public._imp_debug_audit(
      v_actor_user_id,
      'PAY_PREVIEW_FINANCE_CASE_BASELINE_ERROR',
      jsonb_build_object(
        'candidate_id', p_candidate_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_preview_finance',
      COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$
;

-- [REPLACES] public.pay_preview_candidate_collect_scope(p_context_json jsonb, p_candidate_id uuid, p_cursor_json jsonb, p_limit integer)  winner piece A16
CREATE OR REPLACE FUNCTION public.pay_preview_candidate_collect_scope(p_context_json jsonb, p_candidate_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL;
  v_effective_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_targeted_timesheet_ids_requested_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_requested_json jsonb := '[]'::jsonb;
  v_pay_channel_scope text := 'ALL';
  v_candidate_pay_method text := NULL::text;
  v_target_pay_batch_id_raw text := NULL::text;
  v_target_pay_batch_id uuid := NULL::uuid;
  v_target_operation_source_key text := NULL::text;
  v_source_build_mode boolean := false;
  v_source_build_requested_scope_kind text := NULL::text;
  v_source_build_actual_scope_kind text := NULL::text;
  v_source_build_cursor_in_json jsonb := NULL::jsonb;
  v_source_build_cursor_out_json jsonb := NULL::jsonb;
  v_source_build_page_limit integer := 100;
  v_source_build_last_timesheet_id uuid := NULL::uuid;
  v_source_build_next_timesheet_id uuid := NULL::uuid;
  v_source_build_target_page_count integer := 0;
  v_source_build_target_total_count integer := 0;
  v_source_build_has_more boolean := false;
  v_source_build_targeted_payload_received boolean := false;
  v_source_build_fallback_used boolean := false;
  v_source_build_fallback_reason text := NULL::text;
  v_source_build_allow_full_fallback boolean := false;
  v_source_build_candidate_filter_applied_early boolean := false;
  v_source_build_timesheet_filter_applied_early boolean := false;
  v_source_build_large_aggregation_avoided boolean := false;
  v_source_build_collect_started_at timestamptz := clock_timestamp();
  v_source_build_collect_elapsed_ms numeric := 0;
  v_lifecycle_reconciliation_mode boolean := false;
  v_historic_metadata_allowed boolean := false;
  v_signed_finance_reconciliation boolean := false;
  v_exclude_lifecycle_ineligible_current_payability boolean := false;
  v_authoritative_timesheet_scope boolean := false;
  v_internal_reconciliation_requested boolean := false;
  v_internal_reconciliation_authorised boolean := false;
  v_current_internal_authority_token text := NULL::text;
begin
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;


  v_source_build_mode := (
    LOWER(BTRIM(COALESCE(
      v_context_json->>'source_build_mode',
      v_context_json->>'workbench_source_build_mode',
      v_context_json #>> '{source_build,enabled}',
      v_context_json #>> '{workbench,source_build_mode}',
      ''
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR UPPER(BTRIM(COALESCE(
      v_context_json->>'job_type',
      v_context_json #>> '{job,type}',
      v_context_json #>> '{source_build,job_type}',
      v_context_json #>> '{workbench,job_type}',
      ''
    ))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
  );

  v_lifecycle_reconciliation_mode := LOWER(BTRIM(COALESCE(
    v_context_json->>'lifecycle_reconciliation_mode',
    v_context_json #>> '{preview_decisions_json,lifecycle_reconciliation_mode}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_historic_metadata_allowed := LOWER(BTRIM(COALESCE(
    v_context_json->>'historic_metadata_allowed',
    v_context_json #>> '{preview_decisions_json,historic_metadata_allowed}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_signed_finance_reconciliation := LOWER(BTRIM(COALESCE(
    v_context_json->>'signed_finance_reconciliation',
    v_context_json #>> '{preview_decisions_json,signed_finance_reconciliation}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_exclude_lifecycle_ineligible_current_payability := LOWER(BTRIM(COALESCE(
    v_context_json->>'exclude_lifecycle_ineligible_current_payability',
    v_context_json #>> '{preview_decisions_json,exclude_lifecycle_ineligible_current_payability}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_authoritative_timesheet_scope := LOWER(BTRIM(COALESCE(
    v_context_json->>'authoritative_timesheet_scope',
    v_context_json #>> '{preview_decisions_json,authoritative_timesheet_scope}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_internal_reconciliation_requested :=
    v_source_build_mode
    OR v_lifecycle_reconciliation_mode
    OR v_historic_metadata_allowed
    OR v_signed_finance_reconciliation
    OR v_exclude_lifecycle_ineligible_current_payability
    OR v_authoritative_timesheet_scope;

  v_current_internal_authority_token := NULLIF(BTRIM(COALESCE(
    current_setting('cloudtms.pay_workbench_overpayment_sync_token', true),
    ''
  )), '');

  v_internal_reconciliation_authorised :=
    v_internal_reconciliation_requested
    AND v_source_build_mode
    AND v_current_internal_authority_token IS NOT NULL;

  IF v_internal_reconciliation_requested
     AND v_internal_reconciliation_authorised IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_PREVIEW_COLLECT_SCOPE_INTERNAL_AUTHORITY_REQUIRED'
      USING ERRCODE = '42501',
            DETAIL = jsonb_build_object(
              'source_build_mode', COALESCE(v_source_build_mode, false),
              'transaction_authority_present', v_current_internal_authority_token IS NOT NULL,
              'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
              'historic_metadata_allowed', v_historic_metadata_allowed,
              'signed_finance_reconciliation', v_signed_finance_reconciliation,
              'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
              'authoritative_timesheet_scope', v_authoritative_timesheet_scope
            )::text;
  END IF;

  IF v_historic_metadata_allowed
     AND (
       v_authoritative_timesheet_scope IS NOT TRUE
       OR UPPER(BTRIM(COALESCE(
         v_context_json->>'refresh_scope_kind',
         v_context_json #>> '{preview_decisions_json,refresh_scope_kind}',
         ''
       ))) <> 'TARGETED_TIMESHEETS'
     ) THEN
    RAISE EXCEPTION 'PAY_PREVIEW_COLLECT_SCOPE_HISTORIC_METADATA_SCOPE_INVALID'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
              'refresh_scope_kind', COALESCE(
                v_context_json->>'refresh_scope_kind',
                v_context_json #>> '{preview_decisions_json,refresh_scope_kind}'
              )
            )::text;
  END IF;

  v_source_build_cursor_in_json := COALESCE(
    p_cursor_json,
    v_context_json->'source_cursor',
    v_context_json #> '{source_build,cursor}',
    v_context_json #> '{workbench,source_cursor}',
    NULL::jsonb
  );

  IF NULLIF(BTRIM(COALESCE(
       v_context_json->>'source_page_limit',
       v_context_json #>> '{source_build,limit}',
       v_context_json #>> '{workbench,source_build_limit}',
       ''
     )), '') ~ '^[0-9]+$' THEN
    v_source_build_page_limit := LEAST(
      GREATEST(
        NULLIF(BTRIM(COALESCE(
          v_context_json->>'source_page_limit',
          v_context_json #>> '{source_build,limit}',
          v_context_json #>> '{workbench,source_build_limit}',
          ''
        )), '')::integer,
        1
      ),
      100
    );
  ELSE
    v_source_build_page_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  END IF;

  IF COALESCE(v_source_build_cursor_in_json->>'last_timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_source_build_last_timesheet_id := (v_source_build_cursor_in_json->>'last_timesheet_id')::uuid;
  END IF;

  v_source_build_allow_full_fallback := LOWER(BTRIM(COALESCE(
    v_context_json->>'source_build_allow_full_fallback',
    v_context_json #>> '{source_build,allow_full_fallback}',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');


  /*
    5.3 PAGE mode: when no single candidate is supplied, this function acts as a
    bounded pre-draft scope collector. It returns one candidate page only and
    never aggregates all candidate ids for workbench open.
  */
  IF v_candidate_id IS NULL THEN
    RETURN public.pay_preview_build_context(
      p_pay_date => NULLIF(BTRIM(COALESCE(v_context_json->>'pay_date', '')), '')::date,
      p_week_ending_cutoff => NULLIF(BTRIM(COALESCE(v_context_json->>'week_ending_cutoff_date', v_context_json->>'week_ending_cutoff', '')), '')::date,
      p_actor_user_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,actor_user_id}', v_context_json->>'actor_user_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,actor_user_id}', v_context_json->>'actor_user_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_candidate_id => NULL::uuid,
      p_client_id => CASE
        WHEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,client_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(v_context_json #>> '{filters,client_id}', '')), '')::uuid
        ELSE NULL::uuid
      END,
      p_preview_decisions_json => COALESCE(v_context_json->'preview_decisions_json', '{}'::jsonb)
        || jsonb_build_object(
          'preview_context_mode', 'PAGE',
          'scope_limit', LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100),
          'scope_cursor', COALESCE(p_cursor_json, NULL::jsonb)
        )
    );
  END IF;


  v_pay_date := nullif(btrim(coalesce(v_context_json->>'pay_date', '')), '')::date;
  v_week_ending_cutoff := DATE '9999-12-31';
  v_client_id := nullif(btrim(coalesce(v_context_json #>> '{filters,client_id}', '')), '')::uuid;
  v_week_start := nullif(btrim(coalesce(v_context_json->>'pay_week_start', '')), '')::date;
  v_today_uk := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,today_uk}', '')), '')::date, (now() at time zone 'Europe/London')::date);
  v_eligibility_from_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,from_date}', '')), '')::date;
  v_eligibility_to_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,to_date}', '')), '')::date;
  v_pay_eligibility_months_back := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,months_back}', '')), '')::int, 6);
  v_pay_eligibility_weeks_ahead := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,weeks_ahead}', '')), '')::int, 2);
  v_vat_rate_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,vat_rate_pct}', '')), '')::numeric;
  v_erni_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,erni_pct}', '')), '')::numeric;
  v_rail_provider_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,provider_default}', '')), '');
  v_rail_env_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,env_default}', '')), '');
  v_rail_supports_scheduling := coalesce((v_context_json #>> '{settings,rail,supports_scheduling}')::boolean, false);
  v_rail_supports_name_check := coalesce((v_context_json #>> '{settings,rail,supports_name_check}')::boolean, false);
  v_rail_supports_auto_execute := coalesce((v_context_json #>> '{settings,rail,supports_auto_execute}')::boolean, false);
  v_default_schedule_umbrella_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,umbrella_local}', '')), '');
  v_default_schedule_paye_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,paye_local}', '')), '');
  v_funds_warning_hours_json := case when jsonb_typeof(v_context_json #> '{settings,funds_warning_hours_json}') = 'array' then coalesce(v_context_json #> '{settings,funds_warning_hours_json}', '[]'::jsonb) else '[]'::jsonb end;
  v_need_name_check := coalesce((v_context_json #>> '{settings,rail,need_name_check}')::boolean, false);
  v_requires_payee_map := coalesce((v_context_json #>> '{settings,rail,requires_payee_map}')::boolean, false);
  v_paye_guardrails := case when jsonb_typeof(v_context_json->'paye_guardrails') = 'object' then coalesce(v_context_json->'paye_guardrails', '{}'::jsonb) else '{}'::jsonb end;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_context_json->>'pay_channel_scope',
    v_context_json #>> '{filters,pay_channel_scope}',
    v_context_json #>> '{preview_decisions_json,pay_channel_scope}',
    'ALL'
  ))), '');
  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_target_pay_batch_id_raw := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_pay_batch_id',
    v_context_json->>'pay_batch_id',
    v_context_json->>'draft_pay_batch_id',
    v_context_json #>> '{preview_decisions_json,target_pay_batch_id}',
    v_context_json #>> '{preview_decisions_json,pay_batch_id}',
    ''
  )), '');
  IF v_target_pay_batch_id_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_pay_batch_id := v_target_pay_batch_id_raw::uuid;
  END IF;

  v_target_operation_source_key := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_operation_source_key',
    v_context_json #>> '{preview_decisions_json,target_operation_source_key}',
    ''
  )), '');

  SELECT UPPER(NULLIF(BTRIM(COALESCE(public.candidates.pay_method, '')), ''))
  INTO v_candidate_pay_method
  FROM public.candidates
  WHERE public.candidates.id = v_candidate_id;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_context_json->>'refresh_scope_kind', v_context_json #>> '{preview_decisions_json,refresh_scope_kind}', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') AS targeted_timesheet_id
    FROM (
      SELECT targeted_scope_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'array' THEN v_context_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'targeted_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,targeted_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_array(value)
    ) AS targeted_scope_values
    WHERE NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') AS linked_timesheet_id
    FROM (
      SELECT linked_scope_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'array' THEN v_context_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'linked_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,linked_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,linked_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_array(value)
    ) AS linked_scope_values
    WHERE NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') IS NOT NULL
  ) AS linked_scope_ids;


  v_targeted_timesheet_ids_requested_json := CASE
    WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids_requested') = 'array' THEN v_context_json->'targeted_timesheet_ids_requested'
    WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids_requested}') = 'array' THEN v_context_json #> '{preview_decisions_json,targeted_timesheet_ids_requested}'
    ELSE COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)
  END;

  v_linked_timesheet_ids_requested_json := CASE
    WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids_requested') = 'array' THEN v_context_json->'linked_timesheet_ids_requested'
    WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids_requested}') = 'array' THEN v_context_json #> '{preview_decisions_json,linked_timesheet_ids_requested}'
    ELSE COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
  END;

  v_source_build_requested_scope_kind := COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE');
  v_source_build_targeted_payload_received := (
    jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
    OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
  );

  IF COALESCE(v_source_build_mode, false) = true
     AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND (
       jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
     ) THEN
    WITH source_requested_ids AS (
      SELECT
        'TARGETED'::text AS source_scope_kind,
        NULLIF(BTRIM(target_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS target_values(value)
      WHERE NULLIF(BTRIM(target_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION ALL

      SELECT
        'LINKED'::text AS source_scope_kind,
        NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ),
    source_requested_dedup AS (
      SELECT DISTINCT ON (source_requested_ids.timesheet_id)
        source_requested_ids.source_scope_kind,
        source_requested_ids.timesheet_id
      FROM source_requested_ids
      WHERE source_requested_ids.timesheet_id IS NOT NULL
      ORDER BY
        source_requested_ids.timesheet_id,
        CASE WHEN source_requested_ids.source_scope_kind = 'TARGETED' THEN 0 ELSE 1 END
    ),
    source_remaining_ids AS (
      SELECT
        source_requested_dedup.source_scope_kind,
        source_requested_dedup.timesheet_id
      FROM source_requested_dedup
      WHERE v_source_build_last_timesheet_id IS NULL
         OR source_requested_dedup.timesheet_id > v_source_build_last_timesheet_id
    ),
    source_page AS (
      SELECT
        source_remaining_ids.source_scope_kind,
        source_remaining_ids.timesheet_id
      FROM source_remaining_ids
      ORDER BY source_remaining_ids.timesheet_id
      LIMIT v_source_build_page_limit
    )
    SELECT
      COALESCE(
        jsonb_agg(source_page.timesheet_id ORDER BY source_page.timesheet_id)
          FILTER (WHERE source_page.source_scope_kind = 'TARGETED'),
        '[]'::jsonb
      ),
      COALESCE(
        jsonb_agg(source_page.timesheet_id ORDER BY source_page.timesheet_id)
          FILTER (WHERE source_page.source_scope_kind = 'LINKED'),
        '[]'::jsonb
      ),
      count(source_page.timesheet_id)::integer,
      COALESCE((SELECT count(*)::integer FROM source_remaining_ids), 0),
      (
        SELECT ordered_source_page.timesheet_id
        FROM source_page AS ordered_source_page
        ORDER BY ordered_source_page.timesheet_id DESC
        LIMIT 1
      )
    INTO
      v_targeted_timesheet_ids_json,
      v_linked_timesheet_ids_json,
      v_source_build_target_page_count,
      v_source_build_target_total_count,
      v_source_build_next_timesheet_id
    FROM source_page;

    v_targeted_timesheet_ids_requested_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_linked_timesheet_ids_requested_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);
    v_source_build_has_more := v_source_build_target_total_count > v_source_build_target_page_count;
    v_source_build_cursor_out_json := CASE
      WHEN v_source_build_next_timesheet_id IS NULL THEN NULL::jsonb
      ELSE jsonb_build_object(
        'last_timesheet_id', v_source_build_next_timesheet_id::text,
        'source_page_limit', v_source_build_page_limit,
        'requested_refresh_scope_kind', v_source_build_requested_scope_kind
      )
    END;
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
  ELSIF COALESCE(v_source_build_mode, false) = true
        AND COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE') = 'CANDIDATE_FULL_LIVE'
        AND v_candidate_id IS NOT NULL THEN
    WITH retained_finance_cases AS (
      SELECT retained_case.id AS finance_case_id,
             retained_case.linked_timesheet_id
      FROM public.pay_advances AS retained_case
      WHERE retained_case.candidate_id = v_candidate_id
        AND retained_case.linked_timesheet_id IS NOT NULL
        AND (
          retained_case.advance_kind IN (
            'OVERPAYMENT'::public.pay_advance_kind_enum,
            'UNDERPAYMENT'::public.pay_advance_kind_enum
          )
          OR retained_case.case_type IN (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'UNDERPAYMENT'::public.pay_finance_case_type_enum
          )
        )
        AND (
          (
            retained_case.status IN (
              'ACTIVE'::public.pay_advance_status_enum,
              'PAUSED'::public.pay_advance_status_enum
            )
            AND ROUND(COALESCE(retained_case.outstanding_amount, 0), 2) > 0
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_finance_case_components AS retained_component
            WHERE retained_component.finance_case_id = retained_case.id
              AND retained_component.candidate_id = v_candidate_id
              AND (
                retained_component.closed_at_utc IS NULL
                OR ROUND(COALESCE(retained_component.remaining_source_amount, 0), 2) > 0
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_advance_reservations AS retained_reservation
            WHERE retained_reservation.finance_case_id = retained_case.id
              AND UPPER(BTRIM(COALESCE(retained_reservation.status, ''))) IN ('RESERVED', 'COMMITTED', 'SETTLED')
              AND retained_reservation.released_at_utc IS NULL
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS retained_item
            JOIN public.pay_batch_candidates AS retained_candidate
              ON retained_candidate.id = retained_item.pay_batch_candidate_id
             AND retained_candidate.candidate_id = v_candidate_id
            WHERE retained_item.finance_case_id = retained_case.id
              AND retained_item.is_voided IS NOT TRUE
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_items AS retained_correction
            WHERE retained_correction.finance_case_id = retained_case.id
              AND retained_correction.candidate_id = v_candidate_id
              AND retained_correction.status = 'APPLIED'
          )
        )
    ),
    candidate_source_seed AS (
      SELECT candidate_scope_financials.timesheet_id
      FROM public.timesheets_financials AS candidate_scope_financials
      JOIN public.timesheets AS candidate_scope_timesheets
        ON candidate_scope_timesheets.timesheet_id = candidate_scope_financials.timesheet_id
      JOIN public.candidates AS candidate_scope_candidates
        ON candidate_scope_candidates.id = candidate_scope_financials.candidate_id
      WHERE candidate_scope_financials.is_current = true
        AND candidate_scope_financials.candidate_id = v_candidate_id
        AND COALESCE(candidate_scope_financials.pay_on_hold, false) = false
        AND COALESCE(candidate_scope_financials.has_rate_issue, false) = false
        AND COALESCE(candidate_scope_financials.has_pay_channel_issue, false) = false
        AND UPPER(COALESCE(candidate_scope_financials.processing_status::text, '')) NOT IN (
          'UNASSIGNED',
          'CLIENT_UNRESOLVED',
          'RATE_MISSING',
          'PAY_CHANNEL_MISSING'
        )
        AND UPPER(COALESCE(candidate_scope_candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
        AND (
          v_pay_channel_scope = 'ALL'
          OR UPPER(COALESCE(candidate_scope_candidates.pay_method, '')) = v_pay_channel_scope
        )
        AND (v_client_id IS NULL OR candidate_scope_financials.client_id = v_client_id)
        AND (
          (
            candidate_scope_timesheets.authorised_at_server IS NOT NULL
            AND candidate_scope_timesheets.revoked_at IS NULL
            AND candidate_scope_timesheets.archived_at_utc IS NULL
          )
          OR EXISTS (
            SELECT 1
            FROM public.timesheet_payment_overrides AS candidate_scope_overrides
            WHERE candidate_scope_overrides.timesheet_id = candidate_scope_financials.timesheet_id
              AND candidate_scope_overrides.candidate_id = v_candidate_id
              AND candidate_scope_overrides.cleared_at_utc IS NULL
              AND candidate_scope_overrides.consumed_at_utc IS NULL
              AND candidate_scope_overrides.consumed_by_pay_batch_id IS NULL
              AND UPPER(COALESCE(candidate_scope_overrides.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
          )
        )

      UNION

      SELECT retained_finance_cases.linked_timesheet_id
      FROM retained_finance_cases

      UNION

      SELECT retained_component.linked_timesheet_id
      FROM public.pay_finance_case_components AS retained_component
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_component.finance_case_id
      WHERE retained_component.candidate_id = v_candidate_id
        AND retained_component.linked_timesheet_id IS NOT NULL

      UNION

      SELECT retained_item.timesheet_id
      FROM public.pay_batch_items AS retained_item
      JOIN public.pay_batch_candidates AS retained_candidate
        ON retained_candidate.id = retained_item.pay_batch_candidate_id
       AND retained_candidate.candidate_id = v_candidate_id
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_item.finance_case_id
      WHERE retained_item.timesheet_id IS NOT NULL
        AND retained_item.is_voided IS NOT TRUE

      UNION

      SELECT retained_correction.timesheet_id
      FROM public.pay_payment_correction_items AS retained_correction
      JOIN retained_finance_cases
        ON retained_finance_cases.finance_case_id = retained_correction.finance_case_id
      WHERE retained_correction.candidate_id = v_candidate_id
        AND retained_correction.timesheet_id IS NOT NULL
        AND retained_correction.status = 'APPLIED'

      UNION

      SELECT forced_source_timesheet.timesheet_id
      FROM (
        SELECT NULLIF(BTRIM(forced_source_values.value), '')::uuid AS timesheet_id
        FROM jsonb_array_elements_text(
          CASE
            WHEN v_internal_reconciliation_authorised IS TRUE
             AND jsonb_typeof(v_context_json->'source_build_force_include_timesheet_ids') = 'array'
              THEN v_context_json->'source_build_force_include_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) WITH ORDINALITY AS forced_source_values(value, position)
        WHERE forced_source_values.position <= 500
          AND NULLIF(BTRIM(forced_source_values.value), '') ~*
            '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS forced_source_timesheet
      JOIN public.timesheets AS forced_candidate_timesheet
        ON forced_candidate_timesheet.timesheet_id = forced_source_timesheet.timesheet_id
      WHERE EXISTS (
        SELECT 1
        FROM public.timesheets_financials AS forced_candidate_financials
        WHERE forced_candidate_financials.timesheet_id = forced_source_timesheet.timesheet_id
          AND forced_candidate_financials.candidate_id = v_candidate_id
      )
    ),
    candidate_source_timesheets AS (
      SELECT DISTINCT candidate_source_seed.timesheet_id
      FROM candidate_source_seed
      WHERE candidate_source_seed.timesheet_id IS NOT NULL
        AND (
          v_source_build_last_timesheet_id IS NULL
          OR candidate_source_seed.timesheet_id > v_source_build_last_timesheet_id
        )
    ),
    candidate_source_page AS (
      SELECT candidate_source_timesheets.timesheet_id
      FROM candidate_source_timesheets
      ORDER BY candidate_source_timesheets.timesheet_id
      LIMIT v_source_build_page_limit
    )
    SELECT
      COALESCE(jsonb_agg(candidate_source_page.timesheet_id ORDER BY candidate_source_page.timesheet_id), '[]'::jsonb),
      count(candidate_source_page.timesheet_id)::integer,
      COALESCE((SELECT count(*)::integer FROM candidate_source_timesheets), 0),
      (
        SELECT ordered_candidate_source_page.timesheet_id
        FROM candidate_source_page AS ordered_candidate_source_page
        ORDER BY ordered_candidate_source_page.timesheet_id DESC
        LIMIT 1
      )
    INTO
      v_targeted_timesheet_ids_json,
      v_source_build_target_page_count,
      v_source_build_target_total_count,
      v_source_build_next_timesheet_id
    FROM candidate_source_page;

    v_targeted_timesheet_ids_requested_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_linked_timesheet_ids_json := '[]'::jsonb;
    v_linked_timesheet_ids_requested_json := '[]'::jsonb;
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    v_source_build_has_more := v_source_build_target_total_count > v_source_build_target_page_count;
    v_source_build_cursor_out_json := CASE
      WHEN v_source_build_next_timesheet_id IS NULL THEN NULL::jsonb
      ELSE jsonb_build_object(
        'last_timesheet_id', v_source_build_next_timesheet_id::text,
        'source_page_limit', v_source_build_page_limit,
        'requested_refresh_scope_kind', v_source_build_requested_scope_kind
      )
    END;
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
    v_authoritative_timesheet_scope := v_internal_reconciliation_authorised IS TRUE
      AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0;
    v_historic_metadata_allowed := v_signed_finance_reconciliation IS TRUE
      AND v_authoritative_timesheet_scope IS TRUE;
  END IF;

  IF COALESCE(v_source_build_mode, false) = true
     AND v_source_build_requested_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
     AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    IF COALESCE(v_source_build_targeted_payload_received, false) = true THEN
      v_effective_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    ELSIF v_source_build_allow_full_fallback = true THEN
      v_source_build_fallback_used := true;
      v_source_build_fallback_reason := COALESCE(
        NULLIF(BTRIM(v_context_json->>'source_build_fallback_reason'), ''),
        NULLIF(BTRIM(v_context_json #>> '{source_build,fallback_reason}'), ''),
        'TARGETED_TIMESHEETS_REQUESTED_WITHOUT_TARGET_IDS'
      );
      v_effective_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    ELSE
      RAISE EXCEPTION 'SOURCE_BUILD_TARGETED_TIMESHEETS_REQUIRES_TARGET_IDS'
        USING DETAIL = 'WORKBENCH_CANDIDATE_SOURCE_BUILD TARGETED_TIMESHEETS requires targeted_timesheet_ids or linked_timesheet_ids unless source_build_allow_full_fallback is true.';
    END IF;
  ELSIF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
        AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
        AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0
        AND COALESCE(v_source_build_mode, false) = false THEN
    v_effective_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  ELSE
    v_effective_refresh_scope_kind := COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE');
  END IF;

  v_source_build_actual_scope_kind := v_effective_refresh_scope_kind;

  IF COALESCE(v_source_build_mode, false) = true
     AND v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND (
       jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
     ) THEN
    v_source_build_candidate_filter_applied_early := true;
    v_source_build_timesheet_filter_applied_early := true;
    v_source_build_large_aggregation_avoided := true;
  END IF;

  if v_pay_date is null then
    raise exception 'pay_date missing from p_context_json';
  end if;

  if v_week_start is null then
    raise exception 'pay_week_start missing from p_context_json';
  end if;

  if v_eligibility_from_date is null or v_eligibility_to_date is null then
    raise exception 'eligibility window missing from p_context_json';
  end if;

  if v_vat_rate_pct is null or v_erni_pct is null then
    raise exception 'finance window values missing from p_context_json';
  end if;

  if v_rail_provider_default is null or v_rail_env_default is null then
    raise exception 'rail defaults missing from p_context_json';
  end if;

  drop table if exists pg_temp.pay_preview_candidate_context, pg_temp.targeted_refresh_requested_timesheet_ids, pg_temp.linked_refresh_requested_timesheet_ids, pg_temp.targeted_refresh_rotation_scope, pg_temp.targeted_refresh_scope_projection, pg_temp.targeted_refresh_timesheet_ids, pg_temp.linked_refresh_timesheet_ids, pg_temp.targeted_refresh_family_timesheet_ids, pg_temp.linked_refresh_family_timesheet_ids, pg_temp.targeted_refresh_all_family_timesheet_ids, pg_temp.targeted_refresh_all_family_projection, pg_temp.targeted_refresh_all_baseline_projection, pg_temp.targeted_refresh_all_timesheet_ids, pg_temp.active_snoozes, pg_temp.active_timesheet_payment_snoozes, pg_temp.active_segment_snoozes, pg_temp.active_timesheet_payment_overrides, pg_temp.force_include, pg_temp.reserved_batch_items, pg_temp.reserved_by_source_ref, pg_temp.reserved_total_by_timesheet, pg_temp.reserved_segment_key_map, pg_temp.reserved_segment_sums, pg_temp.reserved_preview_segment_ords, pg_temp.reserved_additional_by_code, pg_temp.eligible_tsfin, pg_temp.debted_overpayment_cases, pg_temp.umb_map, pg_temp.adjustment_family_projection, pg_temp.adj, pg_temp.ts_current, pg_temp.targeted_baseline_only_ts_current, pg_temp.active_settled_artifact_components, pg_temp.active_settled_artifact_baseline_by_timesheet, pg_temp.ts_baseline, pg_temp.finance_case_baseline_scope, pg_temp.manual_adjustment_carry_forward_scope, pg_temp.segment_status, pg_temp.blocked_items_all, pg_temp.blocked_items, pg_temp.blocked_items_snoozed, pg_temp.do_not_pay_all, pg_temp.do_not_pay_items, pg_temp.do_not_pay_items_snoozed, pg_temp.ts_deltas, pg_temp.ts_itemised, pg_temp.worked_time_current_segment_rows, pg_temp.worked_time_baseline_segment_rows, pg_temp.worked_time_current_ranked, pg_temp.worked_time_baseline_ranked, pg_temp.worked_time_bucket_ids, pg_temp.worked_time_bucket_agg, pg_temp.worked_time_bucket_calc, pg_temp.worked_time_bucket_alloc, pg_temp.worked_time_bucket_effective, pg_temp.worked_time_bucket_component_rows, pg_temp.worked_time_key_totals, pg_temp.worked_time_bucket_component_sums, pg_temp.worked_time_amount_fallback_rows, pg_temp.timesheet_component_rows, pg_temp.timesheet_component_match_rows, pg_temp.transient_timesheet_component_rows, pg_temp.transient_timesheet_component_review_rows, pg_temp.timesheet_case_actionable_basis, pg_temp.timesheet_live_scope, pg_temp.timesheet_linked_scope_counts, pg_temp.transient_timesheet_component_review_rows_effective, pg_temp.timesheet_case_rollup, pg_temp.finance_candidate_seed, pg_temp.candidate_base, pg_temp.timesheet_candidate_rollup, pg_temp.candidate_rollup, pg_temp.blocked_counts, pg_temp.do_not_pay_counts, pg_temp.loan_due, pg_temp.overpayment_balances, pg_temp.loan_due_this_week, pg_temp.loan_repaid_wtd, pg_temp.paid_wtd_before, pg_temp.cand_enriched, pg_temp.payee_baseline_rows, pg_temp.payees_src, pg_temp.payees, pg_temp.payees_enriched, pg_temp.payees_json, pg_temp.cand_payee0, pg_temp.cand_payee, pg_temp.timesheet_case_rollup_effective, pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_resolution_rollup, pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup, pg_temp.summary_json, pg_temp.timesheet_case_states_flat, pg_temp.finance_case_states_flat, pg_temp.candidate_case_states_flat, pg_temp.candidate_case_states, pg_temp.case_resolution_states_json, pg_temp.finance_candidate_totals, pg_temp.candidate_finance_itemisation, pg_temp.paye_summary_breakdown_json, pg_temp.timesheet_baseline_component_rows, pg_temp.finance_baseline_component_rows, pg_temp.baseline_component_rows_json;

  create temporary table pay_preview_candidate_context on commit drop as
    select
      v_context_json as context_json,
      v_candidate_id as candidate_id,
      v_pay_date as pay_date,
      v_week_ending_cutoff as week_ending_cutoff,
      v_client_id as client_id,
      v_actor_user_id as actor_user_id,
      v_week_start as week_start,
      v_today_uk as today_uk,
      v_pay_eligibility_months_back as pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead as pay_eligibility_weeks_ahead,
      v_eligibility_from_date as eligibility_from_date,
      v_eligibility_to_date as eligibility_to_date,
      v_vat_rate_pct as vat_rate_pct,
      v_erni_pct as erni_pct,
      v_rail_provider_default as rail_provider_default,
      v_rail_env_default as rail_env_default,
      v_rail_supports_scheduling as rail_supports_scheduling,
      v_rail_supports_name_check as rail_supports_name_check,
      v_rail_supports_auto_execute as rail_supports_auto_execute,
      v_default_schedule_umbrella_local as default_schedule_umbrella_local,
      v_default_schedule_paye_local as default_schedule_paye_local,
      v_funds_warning_hours_json as funds_warning_hours_json,
      v_need_name_check as need_name_check,
      v_requires_payee_map as requires_payee_map,
      v_paye_guardrails as paye_guardrails,
      v_effective_refresh_scope_kind as refresh_scope_kind,
      v_targeted_timesheet_ids_json as targeted_timesheet_ids_json,
      v_linked_timesheet_ids_json as linked_timesheet_ids_json,
      v_lifecycle_reconciliation_mode as lifecycle_reconciliation_mode,
      v_historic_metadata_allowed as historic_metadata_allowed,
      v_signed_finance_reconciliation as signed_finance_reconciliation,
      v_exclude_lifecycle_ineligible_current_payability as exclude_lifecycle_ineligible_current_payability,
      v_authoritative_timesheet_scope as authoritative_timesheet_scope
  ;

  create temporary table targeted_refresh_requested_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(targeted_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_requested_json, '[]'::jsonb)) as targeted_scope_array(value)
    where nullif(btrim(targeted_scope_array.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ;

  create temporary table linked_refresh_requested_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(linked_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_requested_json, '[]'::jsonb)) as linked_scope_array(value)
    where nullif(btrim(linked_scope_array.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ;

  create temporary table targeted_refresh_rotation_scope on commit drop as
    select
      requested_scope.source_scope_kind,
      requested_scope.requested_timesheet_id as source_requested_timesheet_id,
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.booking_id,
      rotation_scope_rows.canonical_timesheet_id,
      rotation_scope_rows.family_timesheet_id,
      rotation_scope_rows.family_is_current,
      rotation_scope_rows.family_version,
      rotation_scope_rows.requested_is_canonical
    from (
      select 'TARGETED'::text as source_scope_kind, targeted_requested.timesheet_id as requested_timesheet_id
      from targeted_refresh_requested_timesheet_ids as targeted_requested
      union
      select 'LINKED'::text as source_scope_kind, linked_requested.timesheet_id as requested_timesheet_id
      from linked_refresh_requested_timesheet_ids as linked_requested
      union
      select 'TARGETED'::text as source_scope_kind, nullif(btrim(targeted_context_values.value), '')::uuid as requested_timesheet_id
      from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_json, '[]'::jsonb)) as targeted_context_values(value)
      where nullif(btrim(targeted_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      union
      select 'LINKED'::text as source_scope_kind, nullif(btrim(linked_context_values.value), '')::uuid as requested_timesheet_id
      from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_json, '[]'::jsonb)) as linked_context_values(value)
      where nullif(btrim(linked_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) as requested_scope
    join public._pay_timesheet_rotation_scope(
      (
        select coalesce(
          array_agg(distinct all_requested_scope.requested_timesheet_id order by all_requested_scope.requested_timesheet_id),
          array[]::uuid[]
        )
        from (
          select targeted_requested.timesheet_id as requested_timesheet_id
          from targeted_refresh_requested_timesheet_ids as targeted_requested
          union
          select linked_requested.timesheet_id as requested_timesheet_id
          from linked_refresh_requested_timesheet_ids as linked_requested
          union
          select nullif(btrim(targeted_context_values.value), '')::uuid as requested_timesheet_id
          from jsonb_array_elements_text(coalesce(v_targeted_timesheet_ids_json, '[]'::jsonb)) as targeted_context_values(value)
          where nullif(btrim(targeted_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          union
          select nullif(btrim(linked_context_values.value), '')::uuid as requested_timesheet_id
          from jsonb_array_elements_text(coalesce(v_linked_timesheet_ids_json, '[]'::jsonb)) as linked_context_values(value)
          where nullif(btrim(linked_context_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) as all_requested_scope
        where all_requested_scope.requested_timesheet_id is not null
      )
    ) as rotation_scope_rows
      on rotation_scope_rows.requested_timesheet_id = requested_scope.requested_timesheet_id
  ;

  create temporary table targeted_refresh_scope_projection on commit drop as
    select distinct
      targeted_refresh_rotation_scope.source_scope_kind,
      targeted_refresh_rotation_scope.source_requested_timesheet_id,
      coalesce(targeted_refresh_rotation_scope.canonical_timesheet_id, targeted_refresh_rotation_scope.source_requested_timesheet_id) as canonical_timesheet_id,
      targeted_refresh_rotation_scope.family_timesheet_id,
      targeted_refresh_rotation_scope.family_is_current,
      targeted_refresh_rotation_scope.family_version,
      targeted_refresh_rotation_scope.booking_id,
      coalesce(targeted_refresh_rotation_scope.requested_is_canonical, false) as requested_is_canonical
    from targeted_refresh_rotation_scope
    where targeted_refresh_rotation_scope.source_requested_timesheet_id is not null
      and targeted_refresh_rotation_scope.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id as timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'TARGETED'
      and targeted_refresh_scope_projection.canonical_timesheet_id is not null
  ;

  create temporary table linked_refresh_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id as timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'LINKED'
      and targeted_refresh_scope_projection.canonical_timesheet_id is not null
  ;

  create temporary table targeted_refresh_family_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.family_timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'TARGETED'
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table linked_refresh_family_timesheet_ids on commit drop as
    select distinct
      targeted_refresh_scope_projection.family_timesheet_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.source_scope_kind = 'LINKED'
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_all_family_timesheet_ids on commit drop as
    select distinct targeted_refresh_family_timesheet_ids.family_timesheet_id
    from targeted_refresh_family_timesheet_ids
    union
    select distinct linked_refresh_family_timesheet_ids.family_timesheet_id
    from linked_refresh_family_timesheet_ids
  ;

  create temporary table targeted_refresh_all_family_projection on commit drop as
    select distinct
      targeted_refresh_scope_projection.canonical_timesheet_id,
      targeted_refresh_scope_projection.family_timesheet_id,
      targeted_refresh_scope_projection.family_is_current,
      targeted_refresh_scope_projection.family_version,
      targeted_refresh_scope_projection.booking_id
    from targeted_refresh_scope_projection
    where targeted_refresh_scope_projection.canonical_timesheet_id is not null
      and targeted_refresh_scope_projection.family_timesheet_id is not null
  ;

  create temporary table targeted_refresh_all_baseline_projection on commit drop as
    select distinct on (targeted_refresh_all_family_projection.canonical_timesheet_id)
      targeted_refresh_all_family_projection.canonical_timesheet_id,
      targeted_refresh_all_family_projection.family_timesheet_id,
      targeted_refresh_all_family_projection.family_is_current,
      targeted_refresh_all_family_projection.family_version,
      targeted_refresh_all_family_projection.booking_id
    from targeted_refresh_all_family_projection
    join public.timesheet_pay_state as baseline_projection_state
      on baseline_projection_state.timesheet_id = targeted_refresh_all_family_projection.family_timesheet_id
    order by
      targeted_refresh_all_family_projection.canonical_timesheet_id,
      (targeted_refresh_all_family_projection.family_timesheet_id = targeted_refresh_all_family_projection.canonical_timesheet_id) desc,
      targeted_refresh_all_family_projection.family_is_current desc nulls last,
      targeted_refresh_all_family_projection.family_version desc nulls last,
      targeted_refresh_all_family_projection.family_timesheet_id
  ;

  create temporary table targeted_refresh_all_timesheet_ids on commit drop as
    select distinct x.timesheet_id
    from (
      select trti.timesheet_id
      from targeted_refresh_timesheet_ids trti
      union
      select lrti.timesheet_id
      from linked_refresh_timesheet_ids lrti
    ) as x
    where x.timesheet_id is not null
  ;
  create temporary table active_snoozes on commit drop as
        select
          s.id as snooze_id,
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          s.segment_stable_key,
          s.source_ref,
          upper(coalesce(s.snooze_kind,'')) as snooze_kind,
          s.snooze_until_date,
          s.note
        from public.pay_item_snoozes s
        where s.cleared_at_utc is null
          and s.cancelled_at_utc is null
          and s.candidate_id = v_candidate_id
          and (
            s.snooze_until_date is null
            or s.snooze_until_date >= v_today_uk
          )
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or s.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or s.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or s.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
            or (
              s.booking_id is not null
              and exists (
                select 1
                from public.timesheets ts_scope
                where ts_scope.booking_id = s.booking_id
                  and (
                    ts_scope.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                    or ts_scope.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                  )
              )
            )
            or (s.timesheet_id is null and s.booking_id is null)
          )
  
  ;

  create temporary table active_timesheet_payment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and s.segment_id is null
          and s.segment_stable_key is null
          and s.snooze_kind = 'TIMESHEET_PAYMENT'
  
  ;

  create temporary table active_segment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          coalesce(s.segment_stable_key, s.segment_id) as segment_stable_key,
          s.snooze_kind,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and (s.segment_stable_key is not null or s.segment_id is not null)
          and s.snooze_kind in ('DO_NOT_PAY','BLOCKED_TIMESHEET')
  
  ;

  create temporary table active_timesheet_payment_overrides on commit drop as
        select
          coalesce(tpo_family_projection.canonical_timesheet_id, tpo.timesheet_id) as timesheet_id,
          tpo.candidate_id,
          tpo.id as override_id,
          tpo.reason as override_reason,
          tpo.created_at_utc
        from public.timesheet_payment_overrides tpo
        left join targeted_refresh_all_family_projection as tpo_family_projection
          on tpo_family_projection.family_timesheet_id = tpo.timesheet_id
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or tpo.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  
  ;

  create temporary table force_include on commit drop as
        select distinct
          coalesce(tpo_family_projection.canonical_timesheet_id, tpo.timesheet_id) as timesheet_id
        from public.timesheet_payment_overrides tpo
        left join targeted_refresh_all_family_projection as tpo_family_projection
          on tpo_family_projection.family_timesheet_id = tpo.timesheet_id
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.timesheet_id is not null
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or tpo.timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  
  ;

  create temporary table reserved_batch_items on commit drop as
        -- Items are considered "reserved" if they belong to an ACTIVE (non-cancelled, non-settled) batch.
        -- Policy X/source-target rule: entitlement reservations must subtract the positive ORIGINAL SOURCE
        -- entitlement amount, not the resolved target payout amount. Finance bookkeeping item types are excluded.
        -- Rotation rule: discover candidate/scoped reservation items by family id, project them to the canonical
        -- current timesheet id for pre-draft preview, and resolve artifact keys in one set-based helper call.
        with reserved_batch_item_candidates as (
          select distinct
            reserved_pay_batch_item.id as pay_batch_item_id,
            reserved_pay_batch_candidate.pay_batch_id as pay_batch_id,
            reserved_pay_batch_item.timesheet_id as source_timesheet_id,
            reserved_pay_batch_item.segment_key as segment_key,
            reserved_pay_batch_item.source_ref as source_ref,
            reserved_pay_batch_item.item_type as item_type,
            round(public._pay_batch_item_source_reservation_amount_ex_vat(reserved_pay_batch_item.id), 2) as amount_ex_vat
          from public.pay_batch_items as reserved_pay_batch_item
          join public.pay_batch_candidates as reserved_pay_batch_candidate
            on reserved_pay_batch_candidate.id = reserved_pay_batch_item.pay_batch_candidate_id
          join public.pay_batches as reserved_pay_batch
            on reserved_pay_batch.id = reserved_pay_batch_candidate.pay_batch_id
          left join public.pay_bank_transfers as reserved_pay_bank_transfer
            on reserved_pay_bank_transfer.id = reserved_pay_batch_item.pay_bank_transfer_id
          where reserved_pay_batch_item.timesheet_id is not null
            and reserved_pay_batch_candidate.candidate_id = v_candidate_id
            and (
              v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
              or reserved_pay_batch_item.timesheet_id in (
                select targeted_family_scope.family_timesheet_id
                from targeted_refresh_all_family_timesheet_ids as targeted_family_scope
              )
            )
            and upper(coalesce(reserved_pay_batch_item.pay_channel,'')) in ('PAYE','UMBRELLA')
            and reserved_pay_batch_item.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            and public._pay_batch_item_source_reservation_amount_ex_vat(reserved_pay_batch_item.id) is not null
            and coalesce(reserved_pay_batch_item.is_voided, false) = false
            and not exists (
              select 1
              from public.pay_payment_correction_items as applied_corrections
              where applied_corrections.pay_batch_item_id = reserved_pay_batch_item.id
                and applied_corrections.status = 'APPLIED'
                and applied_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
            )
            and not (
              upper(btrim(coalesce(reserved_pay_batch_candidate.settlement_status, ''))) = 'SETTLED'
              or reserved_pay_batch_candidate.settled_at_utc is not null
              or upper(btrim(coalesce(reserved_pay_bank_transfer.status, ''))) = 'COMPLETED'
              or reserved_pay_bank_transfer.completed_at_utc is not null
            )
            and (
              public._pay_batch_status_is_active_reservation(reserved_pay_batch.status)
              or exists (
                select 1
                from public.pay_payment_correction_requests as open_correction_requests
                join lateral public._pay_payment_correction_selected_items(
                  open_correction_requests.pay_batch_id,
                  case
                    when jsonb_typeof(open_correction_requests.plan_json->'selected_pay_batch_item_ids') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids'
                      )
                    when jsonb_typeof(open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}'
                      )
                    when jsonb_typeof(open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}') = 'array' then
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}',
                        'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}'
                      )
                    else
                      coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                  end,
                  false
                ) as open_correction_selected_items
                  on open_correction_selected_items.pay_batch_id = open_correction_requests.pay_batch_id
                where open_correction_requests.pay_batch_id = reserved_pay_batch_candidate.pay_batch_id
                  and open_correction_requests.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED')
                  and open_correction_requests.correction_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
                  and open_correction_selected_items.pay_batch_item_id = reserved_pay_batch_item.id
              )
              or exists (
                select 1
                from public.pay_bank_transfer_events as unresolved_terminal_failure_events
                where unresolved_terminal_failure_events.pay_batch_id = reserved_pay_batch_candidate.pay_batch_id
                  and unresolved_terminal_failure_events.pay_bank_transfer_id = reserved_pay_batch_item.pay_bank_transfer_id
                  and unresolved_terminal_failure_events.mapping_status = 'MATCHED'
                  and unresolved_terminal_failure_events.normalised_state in ('FAILED','DECLINED','REJECTED','CANCELLED')
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as applied_failure_corrections
                    where applied_failure_corrections.pay_batch_item_id = reserved_pay_batch_item.id
                      and applied_failure_corrections.status = 'APPLIED'
                      and applied_failure_corrections.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL','SETTLED_REVERSAL')
                  )
              )
            )
        ),
        reserved_batch_item_rotation_scope as (
          select
            rotation_scope_rows.requested_timesheet_id,
            rotation_scope_rows.canonical_timesheet_id,
            rotation_scope_rows.family_timesheet_id,
            rotation_scope_rows.family_is_current,
            rotation_scope_rows.family_version
          from public._pay_timesheet_rotation_scope(
            (
              select coalesce(
                array_agg(distinct reserved_batch_item_candidates.source_timesheet_id order by reserved_batch_item_candidates.source_timesheet_id),
                array[]::uuid[]
              )
              from reserved_batch_item_candidates
              where reserved_batch_item_candidates.source_timesheet_id is not null
            )
          ) as rotation_scope_rows
        ),
        reserved_batch_item_projection as (
          select distinct on (reserved_batch_item_rotation_scope.requested_timesheet_id)
            reserved_batch_item_rotation_scope.requested_timesheet_id as requested_timesheet_id,
            coalesce(
              reserved_batch_item_rotation_scope.canonical_timesheet_id,
              reserved_batch_item_rotation_scope.requested_timesheet_id
            ) as projected_timesheet_id
          from reserved_batch_item_rotation_scope
          where reserved_batch_item_rotation_scope.requested_timesheet_id is not null
          order by
            reserved_batch_item_rotation_scope.requested_timesheet_id,
            reserved_batch_item_rotation_scope.family_is_current desc nulls last,
            reserved_batch_item_rotation_scope.family_version desc nulls last,
            reserved_batch_item_rotation_scope.family_timesheet_id
        ),
        reserved_batch_item_projected as (
          select
            reserved_batch_item_candidates.pay_batch_item_id,
            reserved_batch_item_candidates.pay_batch_id,
            coalesce(
              reserved_batch_item_projection.projected_timesheet_id,
              reserved_batch_item_candidates.source_timesheet_id
            ) as projected_timesheet_id,
            reserved_batch_item_candidates.segment_key,
            reserved_batch_item_candidates.source_ref,
            reserved_batch_item_candidates.item_type,
            reserved_batch_item_candidates.amount_ex_vat
          from reserved_batch_item_candidates
          left join reserved_batch_item_projection
            on reserved_batch_item_projection.requested_timesheet_id = reserved_batch_item_candidates.source_timesheet_id
        ),
        reserved_batch_item_id_array as (
          select
            case
              when count(*) = 0 then array['00000000-0000-0000-0000-000000000000'::uuid]
              else array_agg(reserved_batch_item_projected.pay_batch_item_id order by reserved_batch_item_projected.pay_batch_item_id)
            end as pay_batch_item_ids
          from reserved_batch_item_projected
        ),
        reserved_batch_item_components as (
          select distinct
            economic_component_rows.pay_batch_item_id,
            economic_component_rows.key_type,
            economic_component_rows.key_value,
            economic_component_rows.key_resolution_source,
            economic_component_rows.key_resolution_failure_reason
          from reserved_batch_item_id_array
          join lateral public._pay_batch_item_economic_components(
            p_pay_batch_id => null::uuid,
            p_pay_batch_item_ids => reserved_batch_item_id_array.pay_batch_item_ids
          ) as economic_component_rows
            on true
        )
        select
          reserved_batch_item_projected.pay_batch_item_id as pay_batch_item_id,
          reserved_batch_item_projected.pay_batch_id as pay_batch_id,
          reserved_batch_item_projected.projected_timesheet_id as timesheet_id,
          reserved_batch_item_projected.segment_key as segment_key,
          -- Normalise segment_id (some legacy items store it in source_ref 'seg:<id>')
          nullif(
            btrim(coalesce(
              case
                when nullif(btrim(coalesce(reserved_batch_item_projected.segment_key,'')), '') is not null then reserved_batch_item_projected.segment_key
                when nullif(btrim(coalesce(reserved_batch_item_projected.source_ref,'')), '') like 'seg:%' then split_part(reserved_batch_item_projected.source_ref, ':', 2)
                else null
              end,
              ''
            )),
            ''
          ) as segment_id_norm,
          reserved_batch_item_projected.source_ref as source_ref,
          reserved_batch_item_projected.item_type as item_type,
          reserved_batch_item_components.key_type as component_key_type,
          reserved_batch_item_components.key_value as component_key_value,
          reserved_batch_item_components.key_resolution_source as key_resolution_source,
          reserved_batch_item_components.key_resolution_failure_reason as key_resolution_failure_reason,
          reserved_batch_item_projected.amount_ex_vat as amount_ex_vat
        from reserved_batch_item_projected
        left join reserved_batch_item_components
          on reserved_batch_item_components.pay_batch_item_id = reserved_batch_item_projected.pay_batch_item_id

  ;

  create temporary table reserved_by_source_ref on commit drop as
        select
          rbi.timesheet_id,
          rbi.source_ref,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) <> ''
        group by rbi.timesheet_id, rbi.source_ref
  
  ;

  create temporary table reserved_total_by_timesheet on commit drop as
        select
          rbi.timesheet_id,
          round(sum(rbi.amount_ex_vat),2) as reserved_total_ex_vat
        from reserved_batch_items rbi
        group by rbi.timesheet_id
  
  ;

  create temporary table reserved_segment_key_map on commit drop as
        select
          rbi.timesheet_id,
          rbi.segment_id_norm as segment_id_norm,
          rbi.component_key_type as component_key_type,
          rbi.component_key_value as component_key_value
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
  
  ;

  create temporary table reserved_segment_sums on commit drop as
        select
          rbi.timesheet_id,
          rbi.component_key_type,
          rbi.component_key_value,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        group by rbi.timesheet_id, rbi.component_key_type, rbi.component_key_value
  
  ;

  create temporary table reserved_preview_segment_ords on commit drop as
        select
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end as preview_seg_ord,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'ADJUSTMENT_DELTA'
          and rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) like 'preview_seg:%'
        group by
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end
  
  ;

  create temporary table reserved_additional_by_code on commit drop as
        select
          rbi.timesheet_id,
          nullif(btrim(coalesce(bd.bucket_code,'')), '') as code,
          round(
            sum(
              case
                when nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), ''))::numeric)
                when nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), ''))::numeric)
                else abs(coalesce(bd.amount_ex_vat,0))
              end
            ),
            2
          ) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        join public.pay_batch_item_breakdowns bd
          on bd.pay_batch_item_id = rbi.pay_batch_item_id
        where rbi.item_type in ('ADJUSTMENT_DELTA','SEGMENT_DELTA')
          and bd.line_kind = 'ADDITIONAL_UNIT'
          and bd.bucket_code is not null
          and btrim(coalesce(bd.bucket_code,'')) <> ''
        group by rbi.timesheet_id, nullif(btrim(coalesce(bd.bucket_code,'')), '')
  
  ;

  create temporary table eligible_tsfin on commit drop as
        select
          tf.id as tsfin_id,
          tf.timesheet_id,
          tf.candidate_id,
          tf.client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf.band, con.band, ts.band) as ts_band,

          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,

          upper(coalesce(tf.pay_method,'')) as ts_pay_method,
          upper(coalesce(c.pay_method,'')) as cand_pay_method,

          c.tms_ref as cand_tms_ref,
          c.display_name as cand_display_name,

          c.umbrella_id as cand_umbrella_id,

          -- ✅ Bank readiness (candidate)
          c.bank_details_hash as cand_bank_hash,

          ts.reference_number,
          coalesce((private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)#>>'{values,require_reference_to_pay}')::boolean,false) as require_reference_to_pay,

          -- Timesheet advance: force-include even if unauthorised/outside window
          (fi.timesheet_id is not null) as is_forced_advance,

          tf.invoice_breakdown_json,

          ts.sheet_scope as ts_sheet_scope,
          ts.worked_start_iso as ts_worked_start_iso,
          ts.worked_end_iso as ts_worked_end_iso,
          ts.break_start_iso as ts_break_start_iso,
          ts.break_end_iso as ts_break_end_iso,
          ts.break_minutes as ts_break_minutes,
          ts.actual_schedule_json as ts_actual_schedule_json,
          tf.worked_start_iso as tf_worked_start_iso,
          tf.worked_end_iso as tf_worked_end_iso,
          tf.break_start_iso as tf_break_start_iso,
          tf.break_end_iso as tf_break_end_iso,
          tf.break_minutes as tf_break_minutes,
          tf.actual_schedule_json as tf_actual_schedule_json,
          coalesce(tf.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
          coalesce(tf.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
          coalesce(tf.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
          coalesce(tf.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
          coalesce(tf.break_minutes, ts.break_minutes) as effective_break_minutes,
          case
            when jsonb_typeof(tf.actual_schedule_json) = 'object' then tf.actual_schedule_json
            when jsonb_typeof(tf.actual_schedule_json) = 'array' then (
              select tf_sched_item.value
              from jsonb_array_elements(tf.actual_schedule_json) as tf_sched_item(value)
              where tf_sched_item.value is not null
                and jsonb_typeof(tf_sched_item.value) = 'object'
              limit 1
            )
            when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
            when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
              select ts_sched_item.value
              from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
              where ts_sched_item.value is not null
                and jsonb_typeof(ts_sched_item.value) = 'object'
              limit 1
            )
            else null::jsonb
          end as effective_daily_schedule_json,

          tf.total_hours,
          tf.total_pay_ex_vat,
          tf.total_charge_ex_vat,

          tf.hours_day,
          tf.hours_night,
          tf.hours_sat,
          tf.hours_sun,
          tf.hours_bh,
          tf.pay_day,
          tf.pay_night,
          tf.pay_sat,
          tf.pay_sun,
          tf.pay_bh,
          tf.charge_day,
          tf.charge_night,
          tf.charge_sat,
          tf.charge_sun,
          tf.charge_bh,

          -- ✅ Use TSFIN canonical totals for additional units
          tf.additional_pay_ex_vat,
          tf.additional_charge_ex_vat,
          tf.additional_units_json,

          tf.expenses_pay_ex_vat,
          tf.expenses_charge_ex_vat,
          tf.travel_pay_ex_vat,
          tf.travel_charge_ex_vat,
          tf.accommodation_pay_ex_vat,
          tf.accommodation_charge_ex_vat,
          tf.other_pay_ex_vat,
          tf.other_charge_ex_vat,
          tf.mileage_pay_ex_vat,
          tf.mileage_charge_ex_vat,

          -- Baseline snapshot (settled)
          tps.last_settled_snapshot_json,
          tps.last_settled_signature,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as effective_last_settled_signature,

          ts.authorised_at_server,
          tf.pay_on_hold,
          tf.has_rate_issue,
          tf.has_pay_channel_issue,
          tf.processing_status
        from public.timesheets_financials tf
        join public.timesheets ts
          on ts.timesheet_id = tf.timesheet_id
        join public.clients cl
          on cl.id = tf.client_id
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf.client_id
        join public.candidates c
          on c.id = tf.candidate_id
        left join public.timesheet_pay_state tps
          on tps.timesheet_id = tf.timesheet_id
        left join force_include fi
          on fi.timesheet_id = tf.timesheet_id
        where tf.is_current = true
          and ts.archived_at_utc is null
          and coalesce(tf.pay_on_hold,false) = false
          and coalesce(tf.has_rate_issue,false) = false
          and coalesce(tf.has_pay_channel_issue,false) = false
          and upper(coalesce(tf.processing_status::text,'')) not in ('UNASSIGNED','CLIENT_UNRESOLVED','RATE_MISSING','PAY_CHANNEL_MISSING')
          and upper(coalesce(c.pay_method,'')) in ('PAYE','UMBRELLA')

          -- ✅ Eligibility: targeted rows only for TARGETED_TIMESHEETS; current live authorised rows / force include for CANDIDATE_FULL_LIVE
          and (
            (
              v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
              and (
                (
                  tf.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                  or tf.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                )
                and (
                  (
                    ts.authorised_at_server is not null
                    and ts.revoked_at is null
                  )
                  or fi.timesheet_id is not null
                )
              )
            )
            or (
              v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
              and (
                (
                  ts.authorised_at_server is not null
                  and ts.revoked_at is null
                )
                or fi.timesheet_id is not null
              )
            )
          )

          -- ✅ Optional filters (default ALL/ALL when NULL)
          and (v_candidate_id is null or tf.candidate_id = v_candidate_id)
          and (v_client_id is null or tf.client_id = v_client_id)
  
  ;

  create temporary table debted_overpayment_cases on commit drop as
        select
          pa.candidate_id,
          coalesce(pay_advance_family_projection.canonical_timesheet_id, pa.linked_timesheet_id) as timesheet_id,
          pa.baseline_signature
        from public.pay_advances pa
        left join targeted_refresh_all_family_projection as pay_advance_family_projection
          on pay_advance_family_projection.family_timesheet_id = pa.linked_timesheet_id
        where pa.advance_kind = 'OVERPAYMENT'::public.pay_advance_kind_enum
          and pa.status in ('ACTIVE'::public.pay_advance_status_enum, 'PAID_OFF'::public.pay_advance_status_enum)
          and pa.candidate_id = v_candidate_id
          and pa.linked_timesheet_id is not null
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or pa.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or pa.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or pa.linked_timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
        group by
          pa.candidate_id,
          coalesce(pay_advance_family_projection.canonical_timesheet_id, pa.linked_timesheet_id),
          pa.baseline_signature
  
  ;

  create temporary table umb_map on commit drop as
        select
          u.id as umbrella_id,
          coalesce(u.enabled,false) as umb_enabled,
          coalesce(u.vat_chargeable,false) as vat_chargeable,
          -- ✅ Bank readiness (umbrella)
          u.bank_details_hash as umb_bank_hash
        from public.umbrellas u
  
  ;

  create temporary table adjustment_family_projection on commit drop as
        with eligible_current_timesheet_ids as (
          select distinct
            eligible_tsfin.timesheet_id as timesheet_id
          from eligible_tsfin
          where eligible_tsfin.timesheet_id is not null
        ),
        full_live_rotation_scope as (
          select
            full_live_scope.requested_timesheet_id,
            full_live_scope.canonical_timesheet_id,
            full_live_scope.family_timesheet_id,
            full_live_scope.family_is_current,
            full_live_scope.family_version,
            full_live_scope.booking_id
          from public._pay_timesheet_rotation_scope(
            case
              when v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' then (
                select coalesce(
                  array_agg(distinct eligible_current_timesheet_ids.timesheet_id order by eligible_current_timesheet_ids.timesheet_id),
                  array[]::uuid[]
                )
                from eligible_current_timesheet_ids
              )
              else array[]::uuid[]
            end
          ) as full_live_scope
        )
        select distinct
          adjustment_projection_rows.canonical_timesheet_id,
          adjustment_projection_rows.family_timesheet_id
        from (
          select
            eligible_tsfin.timesheet_id as canonical_timesheet_id,
            targeted_refresh_all_family_projection.family_timesheet_id as family_timesheet_id
          from eligible_tsfin
          join targeted_refresh_all_family_projection
            on targeted_refresh_all_family_projection.canonical_timesheet_id = eligible_tsfin.timesheet_id
          where v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
            and eligible_tsfin.timesheet_id is not null
            and targeted_refresh_all_family_projection.family_timesheet_id is not null

          union all

          select
            coalesce(full_live_rotation_scope.canonical_timesheet_id, full_live_rotation_scope.requested_timesheet_id) as canonical_timesheet_id,
            full_live_rotation_scope.family_timesheet_id as family_timesheet_id
          from full_live_rotation_scope
          join eligible_current_timesheet_ids
            on eligible_current_timesheet_ids.timesheet_id = full_live_rotation_scope.requested_timesheet_id
          where v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
            and coalesce(full_live_rotation_scope.canonical_timesheet_id, full_live_rotation_scope.requested_timesheet_id) is not null
            and full_live_rotation_scope.family_timesheet_id is not null
        ) as adjustment_projection_rows
        where adjustment_projection_rows.canonical_timesheet_id is not null
          and adjustment_projection_rows.family_timesheet_id is not null
  
  ;

  create temporary table adj on commit drop as
        select distinct on (
          adjustment_family_projection.canonical_timesheet_id,
          adjustment_rows.id
        )
          adjustment_rows.id as adj_id,
          adjustment_family_projection.canonical_timesheet_id as timesheet_id,
          adjustment_rows.timesheet_id as source_timesheet_id,
          adjustment_rows.candidate_id,
          adjustment_rows.created_at as adjustment_created_at,
          round(coalesce(adjustment_rows.delta_pay_ex_vat,0),2) as delta_pay_ex_vat
        from adjustment_family_projection
        join public.ts_pay_adjustments as adjustment_rows
          on adjustment_rows.timesheet_id = adjustment_family_projection.family_timesheet_id
        where adjustment_rows.as_advance = false
          and adjustment_rows.timesheet_id is not null
          and adjustment_rows.id is not null
          and adjustment_rows.candidate_id = v_candidate_id
        order by
          adjustment_family_projection.canonical_timesheet_id,
          adjustment_rows.id,
          adjustment_rows.created_at nulls last,
          adjustment_rows.timesheet_id
  
  ;

  create temporary table ts_current on commit drop as
        select
          e.candidate_id,
          e.timesheet_id,
          e.tsfin_id,
          e.client_id,
          e.ts_booking_id,
          e.ts_role,
          e.ts_band,
          e.ts_week_ending_date,
          e.ts_client_name,
          e.ts_pay_method,
          e.cand_pay_method,
          e.cand_tms_ref,
          e.cand_display_name,
          e.cand_umbrella_id,
          e.cand_bank_hash,
          e.reference_number,
          e.require_reference_to_pay,
          coalesce(e.is_forced_advance,false) as is_forced_advance,

          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,

          -- ✅ segments retain stable segment identity for preview/snooze matching
          case
            when e.invoice_breakdown_json is not null
             and jsonb_typeof(e.invoice_breakdown_json) = 'object'
             and upper(coalesce(e.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
             and jsonb_typeof(e.invoice_breakdown_json->'segments') = 'array'
            then (
              select coalesce(jsonb_agg(
                jsonb_build_object(
                  'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                  'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
                  'charge_amount', round(coalesce(nullif(seg->>'charge_amount','')::numeric, nullif(seg->>'charge_ex_vat','')::numeric,0),2),
                  'units', coalesce(nullif(seg->>'units','')::numeric, nullif(seg->>'hours','')::numeric),
                  'hours', coalesce(nullif(seg->>'hours','')::numeric, nullif(seg->>'units','')::numeric),
                  'hours_day', coalesce(nullif(seg->>'hours_day','')::numeric, 0),
                  'hours_night', coalesce(nullif(seg->>'hours_night','')::numeric, 0),
                  'hours_sat', coalesce(nullif(seg->>'hours_sat','')::numeric, 0),
                  'hours_sun', coalesce(nullif(seg->>'hours_sun','')::numeric, 0),
                  'hours_bh', coalesce(nullif(seg->>'hours_bh','')::numeric, 0),
                  'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean, false),
                  'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), ''),
                  'nhsp_shift_id', nullif(btrim(coalesce(seg->>'nhsp_shift_id','')), ''),
                  'shift_id', coalesce(
                    nullif(btrim(coalesce(seg->>'shift_id','')), ''),
                    nullif(btrim(coalesce(seg->>'nhsp_shift_id','')), '')
                  ),
                  'external_row_key', nullif(btrim(coalesce(seg->>'external_row_key','')), ''),
                  'hr_request_id', nullif(btrim(coalesce(seg->>'hr_request_id','')), ''),
                  'request_id', coalesce(
                    nullif(btrim(coalesce(seg->>'request_id','')), ''),
                    nullif(btrim(coalesce(seg->>'hr_request_id','')), '')
                  ),
                  'source_system', nullif(btrim(coalesce(seg->>'source_system','')), ''),
                  'latest_import_id', nullif(btrim(coalesce(seg->>'latest_import_id','')), ''),
                  'date', nullif(btrim(coalesce(seg->>'date','')), ''),
                  'segment_key', nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(seg->>'date','')), ''),
                    nullif(btrim(coalesce(seg->>'ref_num','')), '')
                  ),
                  'start_utc', nullif(btrim(coalesce(seg->>'start_utc','')), ''),
                  'end_utc', nullif(btrim(coalesce(seg->>'end_utc','')), ''),
                  'start', case
                    when nullif(btrim(coalesce(seg->>'start','')), '') is not null then nullif(btrim(coalesce(seg->>'start','')), '')
                    when nullif(btrim(coalesce(seg->>'start_utc','')), '') is not null then to_char(((seg->>'start_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'end', case
                    when nullif(btrim(coalesce(seg->>'end','')), '') is not null then nullif(btrim(coalesce(seg->>'end','')), '')
                    when nullif(btrim(coalesce(seg->>'end_utc','')), '') is not null then to_char(((seg->>'end_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'break_start', nullif(btrim(coalesce(seg->>'break_start','')), ''),
                  'break_end', nullif(btrim(coalesce(seg->>'break_end','')), ''),
                  'break_mins', coalesce(nullif(seg->>'break_mins','')::numeric, nullif(seg->>'break_minutes','')::numeric),
                  'breaks', case when jsonb_typeof(seg->'breaks') = 'array' then seg->'breaks' else '[]'::jsonb end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              ), '[]'::jsonb)
              from jsonb_array_elements(e.invoice_breakdown_json->'segments') seg
              where seg is not null and jsonb_typeof(seg)='object'
            )
            else case
              when upper(coalesce(e.ts_sheet_scope::text,'')) = 'DAILY'
              then jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', case
                    when e.effective_worked_start_iso is not null then ((e.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'work_date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'ymd','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date_ymd','')), '')
                    )
                  end,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', case
                    when e.effective_worked_start_iso is not null then e.effective_worked_start_iso::text
                    else null
                  end,
                  'end_utc', case
                    when e.effective_worked_end_iso is not null then e.effective_worked_end_iso::text
                    else null
                  end,
                  'start', case
                    when e.effective_worked_start_iso is not null then to_char((e.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'start','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_start','')), '')
                    )
                  end,
                  'end', case
                    when e.effective_worked_end_iso is not null then to_char((e.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'end','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_end','')), '')
                    )
                  end,
                  'break_start', case
                    when e.effective_break_start_iso is not null then to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '')
                  end,
                  'break_end', case
                    when e.effective_break_end_iso is not null then to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '')
                  end,
                  'break_mins', coalesce(
                    e.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                    case
                      when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  ),
                  'breaks', case
                    when jsonb_typeof(e.effective_daily_schedule_json->'breaks') = 'array' then e.effective_daily_schedule_json->'breaks'
                    when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'end', to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            case
                              when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                                then greatest(
                                  0::numeric,
                                  round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                                )
                              else null::numeric
                            end
                          )
                        )
                      )
                    when nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '') is not null
                     and nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '') is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), ''),
                          'end', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), ''),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                          )
                        )
                      )
                    else '[]'::jsonb
                  end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
              else jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', null,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', null,
                  'end_utc', null,
                  'start', null,
                  'end', null,
                  'break_start', null,
                  'break_end', null,
                  'break_mins', null,
                  'breaks', '[]'::jsonb,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
            end
          end as current_segments_json,

          round(coalesce(e.total_hours,0),2) as total_hours,
          round(coalesce(e.total_pay_ex_vat,0),2) as total_pay_ex_vat,
          round(coalesce(e.total_charge_ex_vat,0),2) as total_charge_ex_vat,
          round(coalesce(e.hours_day,0),6) as hours_day,
          round(coalesce(e.hours_night,0),6) as hours_night,
          round(coalesce(e.hours_sat,0),6) as hours_sat,
          round(coalesce(e.hours_sun,0),6) as hours_sun,
          round(coalesce(e.hours_bh,0),6) as hours_bh,
          case when e.pay_day is null then null else round(e.pay_day,6) end as pay_day,
          case when e.pay_night is null then null else round(e.pay_night,6) end as pay_night,
          case when e.pay_sat is null then null else round(e.pay_sat,6) end as pay_sat,
          case when e.pay_sun is null then null else round(e.pay_sun,6) end as pay_sun,
          case when e.pay_bh is null then null else round(e.pay_bh,6) end as pay_bh,
          case when e.charge_day is null then null else round(e.charge_day,6) end as charge_day,
          case when e.charge_night is null then null else round(e.charge_night,6) end as charge_night,
          case when e.charge_sat is null then null else round(e.charge_sat,6) end as charge_sat,
          case when e.charge_sun is null then null else round(e.charge_sun,6) end as charge_sun,
          case when e.charge_bh is null then null else round(e.charge_bh,6) end as charge_bh,
          coalesce(e.additional_units_json, '{}'::jsonb) as current_additional_units_json,

          -- Canonical additional truth is the TSFIN top-level additional bucket plus
          -- additional_units_json. SEGMENTS invoice_breakdown_json.additional is not a
          -- Banking Pay entitlement source: in expense-only manual rows it can be a
          -- catch-all presentation artefact for non-segment totals.
          round(coalesce(e.additional_pay_ex_vat,0),2) as current_additional_pay_ex_vat,
          round(coalesce(e.additional_charge_ex_vat,0),2) as current_additional_charge_ex_vat,
          round(coalesce(e.expenses_pay_ex_vat,0),2) as current_expenses_pay_ex_vat,
          round(coalesce(e.expenses_charge_ex_vat,0),2) as current_expenses_charge_ex_vat,
          round(coalesce(e.travel_pay_ex_vat,0),2) as current_travel_pay_ex_vat,
          round(coalesce(e.travel_charge_ex_vat,0),2) as current_travel_charge_ex_vat,
          round(coalesce(e.accommodation_pay_ex_vat,0),2) as current_accommodation_pay_ex_vat,
          round(coalesce(e.accommodation_charge_ex_vat,0),2) as current_accommodation_charge_ex_vat,
          round(coalesce(e.other_pay_ex_vat,0),2) as current_other_pay_ex_vat,
          round(coalesce(e.other_charge_ex_vat,0),2) as current_other_charge_ex_vat,
          round(coalesce(e.mileage_pay_ex_vat,0),2) as current_mileage_pay_ex_vat,
          round(coalesce(e.mileage_charge_ex_vat,0),2) as current_mileage_charge_ex_vat,

          coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'id', a.adj_id::text,
                  'delta_pay_ex_vat', a.delta_pay_ex_vat
                )
                order by a.adjustment_created_at nulls last, a.adj_id
              )
              from adj a
              where a.timesheet_id = e.timesheet_id
            ),
            '[]'::jsonb
          ) as current_adjustments_json,

          e.last_settled_snapshot_json,
          e.effective_last_settled_signature as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from eligible_tsfin e
        left join umb_map um
          on um.umbrella_id = e.cand_umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = e.candidate_id
         and doc.timesheet_id = e.timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(e.effective_last_settled_signature, '')
  
  ;

  create temporary table targeted_baseline_only_ts_current on commit drop as
        select
          coalesce(tf_any.candidate_id, v_candidate_id) as candidate_id,
          tri.canonical_timesheet_id as timesheet_id,
          tf_any.id as tsfin_id,
          tf_any.client_id as client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf_any.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf_any.band, con.band, ts.band) as ts_band,
          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,
          upper(coalesce(tf_any.pay_method, cand.pay_method, '')) as ts_pay_method,
          upper(coalesce(cand.pay_method, '')) as cand_pay_method,
          cand.tms_ref as cand_tms_ref,
          cand.display_name as cand_display_name,
          cand.umbrella_id as cand_umbrella_id,
          cand.bank_details_hash as cand_bank_hash,
          ts.reference_number,
          coalesce((private._timesheet_settings_authority_frozen_v1(ts.timesheet_id)#>>'{values,require_reference_to_pay}')::boolean,false) as require_reference_to_pay,
          false as is_forced_advance,
          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,
          case
            when upper(coalesce(ts.sheet_scope::text,'')) = 'DAILY'
            then jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.canonical_timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', case
                  when daily_sched.effective_worked_start_iso is not null then ((daily_sched.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'work_date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'ymd','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date_ymd','')), '')
                  )
                end,
                'segment_key', ('ts:' || tri.canonical_timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.canonical_timesheet_id::text)),
                'start_utc', case
                  when daily_sched.effective_worked_start_iso is not null then daily_sched.effective_worked_start_iso::text
                  else null
                end,
                'end_utc', case
                  when daily_sched.effective_worked_end_iso is not null then daily_sched.effective_worked_end_iso::text
                  else null
                end,
                'start', case
                  when daily_sched.effective_worked_start_iso is not null then to_char((daily_sched.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'start','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_start','')), '')
                  )
                end,
                'end', case
                  when daily_sched.effective_worked_end_iso is not null then to_char((daily_sched.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'end','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_end','')), '')
                  )
                end,
                'break_start', case
                  when daily_sched.effective_break_start_iso is not null then to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '')
                end,
                'break_end', case
                  when daily_sched.effective_break_end_iso is not null then to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '')
                end,
                'break_mins', coalesce(
                  daily_sched.effective_break_minutes::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                  case
                    when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                      then greatest(
                        0::numeric,
                        round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                      )
                    else null::numeric
                  end
                ),
                'breaks', case
                  when jsonb_typeof(daily_sched.effective_daily_schedule_json->'breaks') = 'array' then daily_sched.effective_daily_schedule_json->'breaks'
                  when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'end', to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          case
                            when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                              then greatest(
                                0::numeric,
                                round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                              )
                            else null::numeric
                          end
                        )
                      )
                    )
                  when nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '') is not null
                   and nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '') is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), ''),
                        'end', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), ''),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                        )
                      )
                    )
                  else '[]'::jsonb
                end,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
            else jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.canonical_timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', null,
                'segment_key', ('ts:' || tri.canonical_timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.canonical_timesheet_id::text)),
                'start_utc', null,
                'end_utc', null,
                'start', null,
                'end', null,
                'break_start', null,
                'break_end', null,
                'break_mins', null,
                'breaks', '[]'::jsonb,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
          end as current_segments_json,
          0::numeric as total_hours,
          0::numeric as total_pay_ex_vat,
          0::numeric as total_charge_ex_vat,
          0::numeric as hours_day,
          0::numeric as hours_night,
          0::numeric as hours_sat,
          0::numeric as hours_sun,
          0::numeric as hours_bh,
          null::numeric as pay_day,
          null::numeric as pay_night,
          null::numeric as pay_sat,
          null::numeric as pay_sun,
          null::numeric as pay_bh,
          null::numeric as charge_day,
          null::numeric as charge_night,
          null::numeric as charge_sat,
          null::numeric as charge_sun,
          null::numeric as charge_bh,
          '{}'::jsonb as current_additional_units_json,
          0::numeric as current_additional_pay_ex_vat,
          0::numeric as current_additional_charge_ex_vat,
          0::numeric as current_expenses_pay_ex_vat,
          0::numeric as current_expenses_charge_ex_vat,
          0::numeric as current_travel_pay_ex_vat,
          0::numeric as current_travel_charge_ex_vat,
          0::numeric as current_accommodation_pay_ex_vat,
          0::numeric as current_accommodation_charge_ex_vat,
          0::numeric as current_other_pay_ex_vat,
          0::numeric as current_other_charge_ex_vat,
          0::numeric as current_mileage_pay_ex_vat,
          0::numeric as current_mileage_charge_ex_vat,
          '[]'::jsonb as current_adjustments_json,
          tps.last_settled_snapshot_json,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from targeted_refresh_all_baseline_projection tri
        join public.timesheet_pay_state tps
          on tps.timesheet_id = tri.family_timesheet_id
        left join lateral (
          select tf.*
          from public.timesheets_financials tf
          where tf.timesheet_id = tri.canonical_timesheet_id
          order by tf.is_current desc, tf.computed_at_utc desc nulls last, tf.id desc
          limit 1
        ) tf_any on true
        join public.candidates cand
          on cand.id = coalesce(tf_any.candidate_id, v_candidate_id)
        left join public.timesheets ts
          on ts.timesheet_id = tri.canonical_timesheet_id
        left join lateral (
          select
            coalesce(tf_any.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
            coalesce(tf_any.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
            coalesce(tf_any.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
            coalesce(tf_any.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
            coalesce(tf_any.break_minutes, ts.break_minutes) as effective_break_minutes,
            case
              when jsonb_typeof(tf_any.actual_schedule_json) = 'object' then tf_any.actual_schedule_json
              when jsonb_typeof(tf_any.actual_schedule_json) = 'array' then (
                select tf_sched_item.value
                from jsonb_array_elements(tf_any.actual_schedule_json) as tf_sched_item(value)
                where tf_sched_item.value is not null
                  and jsonb_typeof(tf_sched_item.value) = 'object'
                limit 1
              )
              when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
              when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
                select ts_sched_item.value
                from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
                where ts_sched_item.value is not null
                  and jsonb_typeof(ts_sched_item.value) = 'object'
                limit 1
              )
              else null::jsonb
            end as effective_daily_schedule_json
        ) daily_sched on true
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf_any.client_id
        left join public.clients cl
          on cl.id = tf_any.client_id
        left join umb_map um
          on um.umbrella_id = cand.umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = coalesce(tf_any.candidate_id, v_candidate_id)
         and doc.timesheet_id = tri.canonical_timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(tps.last_settled_signature, md5(coalesce(tps.last_settled_snapshot_json::text, '{}')))
        where v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
          and (
            tps.last_settled_snapshot_json is not null
            or tps.last_settled_signature is not null
            or tps.last_settled_pay_batch_id is not null
            or tps.last_settled_at_utc is not null
          )
          and not exists (
            select 1
            from ts_current cur
            where cur.timesheet_id = tri.canonical_timesheet_id
          )
  ;

  create temporary table active_settled_artifact_components on commit drop as
        select
          active_settled_components.timesheet_id,
          active_settled_components.key_type,
          active_settled_components.key_value,
          active_settled_components.amount_ex_vat,
          active_settled_components.amount_inc_vat
        from public._pay_active_settled_components(
          ARRAY(
            select distinct active_baseline_scope.timesheet_id
            from (
              select ts_current.timesheet_id
              from ts_current
              where ts_current.timesheet_id is not null
              union
              select targeted_baseline_only_ts_current.timesheet_id
              from targeted_baseline_only_ts_current
              where targeted_baseline_only_ts_current.timesheet_id is not null
            ) as active_baseline_scope
          )
        ) as active_settled_components
        where active_settled_components.timesheet_id is not null
          and active_settled_components.key_type is not null
          and active_settled_components.key_value is not null
  ;

  create temporary table active_settled_artifact_baseline_by_timesheet on commit drop as
        select
          active_settled_artifact_components.timesheet_id,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'key_type', active_settled_artifact_components.key_type,
                'key_value', active_settled_artifact_components.key_value,
                'amount_ex_vat', active_settled_artifact_components.amount_ex_vat,
                'amount_inc_vat', active_settled_artifact_components.amount_inc_vat,
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT'
              )
              order by active_settled_artifact_components.key_type, active_settled_artifact_components.key_value
            ),
            '[]'::jsonb
          ) as active_settled_components_json,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_ex_vat, 0)), 0), 2)::numeric as active_settled_amount_ex_vat,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_inc_vat, 0)), 0), 2)::numeric as active_settled_amount_inc_vat,
          count(*)::int as active_settled_component_count
        from active_settled_artifact_components
        group by active_settled_artifact_components.timesheet_id
  ;

  create temporary table ts_baseline on commit drop as
        select
          t.candidate_id,
          t.timesheet_id,
          t.client_id,
          t.ts_booking_id,
          t.ts_role,
          t.ts_band,
          t.ts_week_ending_date,
          t.ts_client_name,
          t.ts_pay_method,
          t.cand_pay_method,
          t.cand_tms_ref,
          t.cand_display_name,
          t.cand_umbrella_id,
          t.umb_enabled,
          t.umb_vat_chargeable,
          t.require_reference_to_pay,
          t.is_forced_advance,

          -- ✅ bank readiness propagation
          t.cand_bank_hash,
          t.umb_bank_hash,

          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then
              jsonb_build_object(
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT',
                'active_settled_artifact_components', coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb),
                'active_settled_amount_ex_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0),
                'active_settled_amount_inc_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0),
                'legacy_timesheet_pay_state_snapshot_json', coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
              )
            else coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
          end as base_json,
          coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb) as active_settled_artifact_components_json,
          coalesce(active_settled_artifact_baseline.active_settled_component_count, 0)::int as active_settled_artifact_component_count,
          coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0)::numeric as active_settled_artifact_amount_ex_vat,
          coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0)::numeric as active_settled_artifact_amount_inc_vat,
          (coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0) as has_active_settled_artifact_baseline,
          t.baseline_signature,
          coalesce(t.has_active_overpayment_case,false) as has_active_overpayment_case,

          coalesce(t.current_segments_json, '[]'::jsonb) as current_segments_json,
          coalesce(t.current_adjustments_json, '[]'::jsonb) as current_adjustments_json,

          t.total_hours,
          t.total_pay_ex_vat,
          t.total_charge_ex_vat,
          t.hours_day,
          t.hours_night,
          t.hours_sat,
          t.hours_sun,
          t.hours_bh,
          t.pay_day,
          t.pay_night,
          t.pay_sat,
          t.pay_sun,
          t.pay_bh,
          t.charge_day,
          t.charge_night,
          t.charge_sat,
          t.charge_sun,
          t.charge_bh,
          t.hours_day as cur_hours_day,
          t.hours_night as cur_hours_night,
          t.hours_sat as cur_hours_sat,
          t.hours_sun as cur_hours_sun,
          t.hours_bh as cur_hours_bh,
          t.pay_day as cur_pay_day,
          t.pay_night as cur_pay_night,
          t.pay_sat as cur_pay_sat,
          t.pay_sun as cur_pay_sun,
          t.pay_bh as cur_pay_bh,
          t.charge_day as cur_charge_day,
          t.charge_night as cur_charge_night,
          t.charge_sat as cur_charge_sat,
          t.charge_sun as cur_charge_sun,
          t.charge_bh as cur_charge_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}')::numeric), 6)
            else 0::numeric
          end as bas_hours_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}')::numeric), 6)
            else 0::numeric
          end as bas_hours_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}')::numeric), 6)
            else 0::numeric
          end as bas_hours_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_pay_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_pay_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_pay_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_pay_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_pay_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_charge_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_charge_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_charge_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_charge_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_charge_bh,
          t.current_additional_pay_ex_vat,
          t.current_additional_charge_ex_vat,
          t.current_additional_units_json,
          t.current_expenses_pay_ex_vat,
          t.current_expenses_charge_ex_vat,
          t.current_travel_pay_ex_vat,
          t.current_travel_charge_ex_vat,
          t.current_accommodation_pay_ex_vat,
          t.current_accommodation_charge_ex_vat,
          t.current_other_pay_ex_vat,
          t.current_other_charge_ex_vat,
          t.current_mileage_pay_ex_vat,
          t.current_mileage_charge_ex_vat
        from (
          select * from ts_current
          union all
          select * from targeted_baseline_only_ts_current
        ) t
        left join active_settled_artifact_baseline_by_timesheet as active_settled_artifact_baseline
          on active_settled_artifact_baseline.timesheet_id = t.timesheet_id
  
  ;

  create temporary table finance_case_baseline_scope on commit drop as
        select
          vfcr.*
        from public.v_finance_cases_register vfcr
        where vfcr.case_type in (
          'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'UNDERPAYMENT'::public.pay_finance_case_type_enum,
          'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
          'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
        )
          and upper(coalesce(vfcr.status::text,'')) = 'ACTIVE'
          and coalesce(vfcr.outstanding_amount,0) > 0
          and (
            (
              vfcr.case_type in (
                'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and (
                upper(coalesce(vfcr.payout_status::text,'')) <> 'PAID'
                or vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type in (
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and (
                vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type in (
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'UNDERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and exists (
                select 1
                from public.pay_finance_case_components as pfc_restructure_scope
                join public.candidates as c_restructure_scope
                  on c_restructure_scope.id = pfc_restructure_scope.candidate_id
                where pfc_restructure_scope.finance_case_id = vfcr.finance_case_id
                  and pfc_restructure_scope.closed_at_utc is null
                  and pfc_restructure_scope.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                  and round(coalesce(pfc_restructure_scope.remaining_source_amount, 0), 2) > 0
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(c_restructure_scope.pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  and (
                    coalesce(pfc_restructure_scope.is_resolution_stale, false) = true
                    or nullif(btrim(coalesce(pfc_restructure_scope.saved_target_pay_method, '')), '') is null
                    or upper(coalesce(pfc_restructure_scope.saved_target_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  )
              )
            )
          )
          and (v_candidate_id is null or vfcr.candidate_id = v_candidate_id)
          and (v_client_id is null or vfcr.client_id = v_client_id)
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or vfcr.linked_timesheet_id is null
            -- S-08 D5 (ruling 4): in the authoritative Workbench source build the preparation scope no
            -- longer pulls in Timesheets merely because an advance, recovery or manual adjustment is linked
            -- to them, so those Candidate balances are read here as balances whatever Timesheet they are
            -- linked to.  Underpayments stay Timesheet-scoped (they are owed only while authorised).
            or (
              v_internal_reconciliation_authorised is true
              and coalesce(v_source_build_mode, false) = true
              and vfcr.case_type in (
                'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
            )
            or vfcr.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or vfcr.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or vfcr.linked_timesheet_id in (select trf.family_timesheet_id from targeted_refresh_all_family_timesheet_ids trf)
          )
  ;



  create temporary table manual_adjustment_carry_forward_scope on commit drop as
        select
          carry_forward_rows.id,
          carry_forward_rows.source_pay_batch_id,
          carry_forward_rows.source_pay_batch_item_id,
          carry_forward_rows.source_pay_bank_transfer_id,
          carry_forward_rows.source_pay_batch_candidate_id,
          carry_forward_rows.source_correction_request_id,
          carry_forward_rows.source_correction_work_item_id,
          carry_forward_rows.candidate_id,
          carry_forward_rows.umbrella_id,
          carry_forward_rows.client_id,
          carry_forward_rows.timesheet_id,
          carry_forward_rows.pay_channel,
          carry_forward_rows.adjustment_direction,
          carry_forward_rows.amount_ex_vat,
          carry_forward_rows.amount_vat,
          carry_forward_rows.amount_inc_vat,
          carry_forward_rows.amount_basis,
          carry_forward_rows.paye_treatment,
          carry_forward_rows.tax_treatment_json,
          carry_forward_rows.description,
          carry_forward_rows.reason,
          carry_forward_rows.source_ref,
          carry_forward_rows.source_operation_source_key,
          carry_forward_rows.source_snapshot_json,
          carry_forward_rows.status,
          carry_forward_rows.target_pay_batch_id,
          carry_forward_rows.target_pay_batch_item_id,
          carry_forward_rows.target_operation_source_key,
          carry_forward_rows.created_at_utc,
          carry_forward_rows.updated_at_utc,
          carry_forward_rows.reserved_at_utc,
          carry_forward_rows.consumed_at_utc,
          carry_forward_rows.released_at_utc,
          carry_forward_rows.cancelled_at_utc,
          carry_forward_rows.status_reason,
          COALESCE(source_batch_rows.execution_commit_ref, carry_forward_rows.source_pay_batch_id::text) AS source_batch_ref
        from public.pay_manual_adjustment_carry_forwards as carry_forward_rows
        left join public.pay_batches as source_batch_rows
          on source_batch_rows.id = carry_forward_rows.source_pay_batch_id
        where carry_forward_rows.candidate_id = v_candidate_id
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) not in ('CONSUMED_IN_BATCH', 'CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW')
          and (
            (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'PENDING_CARRY_FORWARD'
              and carry_forward_rows.target_pay_batch_id is null
              and carry_forward_rows.target_pay_batch_item_id is null
              and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') is null
            )
            or (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'RESERVED_IN_DRAFT'
              and (
                (v_target_pay_batch_id is not null and carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
                or (
                  v_target_operation_source_key is not null
                  and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') = v_target_operation_source_key
                )
              )
            )
          )
          and (
            (
              v_pay_channel_scope = 'ALL'
              and (
                v_candidate_pay_method is null
                or upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_candidate_pay_method
              )
            )
            or (
              v_pay_channel_scope <> 'ALL'
              and upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_pay_channel_scope
            )
          )
  ;

  v_source_build_collect_elapsed_ms := round((extract(epoch from (clock_timestamp() - v_source_build_collect_started_at)) * 1000.0)::numeric, 3);

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'refresh_scope_kind', v_effective_refresh_scope_kind,
    'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
    'linked_timesheet_ids', v_linked_timesheet_ids_json,
    'ts_baseline_count', (select count(*)::int from ts_baseline),
    'finance_case_scope_count', (select count(*)::int from finance_case_baseline_scope),
    'manual_adjustment_carry_forward_count', (select count(*)::int from manual_adjustment_carry_forward_scope),
    'active_snooze_count', (select count(*)::int from active_snoozes),
    'source_build_collect_diagnostics', jsonb_build_object(
      'source_build_mode', COALESCE(v_source_build_mode, false),
      'requested_refresh_scope_kind', COALESCE(v_source_build_requested_scope_kind, 'CANDIDATE_FULL_LIVE'),
      'actual_refresh_scope_kind', COALESCE(v_source_build_actual_scope_kind, v_effective_refresh_scope_kind),
      'targeted_payload_received', COALESCE(v_source_build_targeted_payload_received, false),
      'targeted_timesheet_count', jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)),
      'linked_timesheet_count', jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)),
      'candidate_filter_applied_early', COALESCE(v_source_build_candidate_filter_applied_early, false),
      'timesheet_filter_applied_early', COALESCE(v_source_build_timesheet_filter_applied_early, false),
      'fallback_used', COALESCE(v_source_build_fallback_used, false),
      'fallback_reason', v_source_build_fallback_reason,
      'source_page_limit', v_source_build_page_limit,
      'source_page_count', v_source_build_target_page_count,
      'source_remaining_after_cursor_count', v_source_build_target_total_count,
      'cursor_in', COALESCE(v_source_build_cursor_in_json, 'null'::jsonb),
      'cursor_out', COALESCE(v_source_build_cursor_out_json, 'null'::jsonb),
      'cursor_advanced', (v_source_build_next_timesheet_id IS NOT NULL),
      'has_more', COALESCE(v_source_build_has_more, false),
      'large_aggregation_avoided', COALESCE(v_source_build_large_aggregation_avoided, false),
      'collect_elapsed_ms', v_source_build_collect_elapsed_ms,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )
    || jsonb_build_object(
      'lifecycle_reconciliation_mode', v_lifecycle_reconciliation_mode,
      'historic_metadata_allowed', v_historic_metadata_allowed,
      'signed_finance_reconciliation', v_signed_finance_reconciliation,
      'exclude_lifecycle_ineligible_current_payability', v_exclude_lifecycle_ineligible_current_payability,
      'authoritative_timesheet_scope', v_authoritative_timesheet_scope,
      'internal_reconciliation_authorised', v_internal_reconciliation_authorised
    )
  );
end;
$function$;

-- [REPLACES] public.pay_search(p_query text, p_limit integer, p_offset integer)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_search(p_query text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  v_q_digits text := null;
  v_limit int := greatest(coalesce(p_limit, 20), 0);
  v_offset int := greatest(coalesce(p_offset, 0), 0);

  v_is_digits7 boolean := false;
  v_is_digits15 boolean := false;
  v_is_digits8 boolean := false;

  v_digits7_int int := null;
  v_amount_query numeric := null;

  v_batches jsonb := '[]'::jsonb;
  v_matches jsonb := '[]'::jsonb;
begin
  if v_q is null then
    return jsonb_build_object(
      'query', coalesce(p_query, ''),
      'query_digits', '',
      'batches', '[]'::jsonb,
      'matches', '[]'::jsonb
    );
  end if;

  v_q_digits := regexp_replace(v_q, '[^0-9]', '', 'g');

  v_is_digits7 := (length(v_q_digits) = 7);
  v_is_digits15 := (length(v_q_digits) = 15);
  v_is_digits8 := (length(v_q_digits) = 8);

  if v_is_digits7 then
    begin
      v_digits7_int := v_q_digits::int;
    exception when others then
      v_digits7_int := null;
    end;
  end if;

  -- numeric amount search (optional): allow "123" or "123.45" (strip commas/spaces)
  begin
    if regexp_replace(v_q, '[ ,]', '', 'g') ~ '^[0-9]+(\.[0-9]{1,2})?$' then
      v_amount_query := regexp_replace(v_q, '[ ,]', '', 'g')::numeric;
    end if;
  exception when others then
    v_amount_query := null;
  end;

  -- ---------------------------------------------------------
  -- BATCH matches
  -- ---------------------------------------------------------
  with batches_raw as (
    select
      pb.id as batch_id,
      pb.pay_date,
      pb.bulk_reference,
      pb.bulk_ref_num,
      pb.bulk_ref_date,
      pb.status,
      pb.total_bank_out,
      pb.total_debt_created
    from public.pay_batches pb
    where
      (
        -- 7 digits -> bulk_ref_num
        (v_is_digits7 and v_digits7_int is not null and pb.bulk_ref_num = v_digits7_int)
        or
        -- 15 digits -> bulk_reference (support digits-only or hyphenated storage)
        (v_is_digits15 and pb.bulk_reference is not null
          and (
            pb.bulk_reference = v_q_digits
            or regexp_replace(pb.bulk_reference, '[^0-9]', '', 'g') = v_q_digits
          )
        )
        or
        -- 8 digits -> DDMMYYYY match against bulk_ref_date or pay_date
        (v_is_digits8 and (
          to_char(pb.pay_date, 'DDMMYYYY') = v_q_digits
          or (pb.bulk_ref_date is not null and to_char(pb.bulk_ref_date, 'DDMMYYYY') = v_q_digits)
        ))
        or
        -- ISO date
        (v_q ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pb.pay_date = v_q::date)
        or
        -- free-text match against bulk_reference (if present)
        (not v_is_digits7 and not v_is_digits15 and not v_is_digits8
          and pb.bulk_reference is not null and pb.bulk_reference ilike ('%' || v_q || '%')
        )
      )
      -- A30 (PRE-EXISTING fix, H6 M3): a batch whose V8 Draft operation is unfinished is not published
      and not private.pay_batch_v8_draft_preparation_unfinished_v1(pb.id)
    order by pb.pay_date desc, pb.created_at_utc desc, pb.id desc
    offset v_offset
    limit v_limit
  )
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'batch_id', br.batch_id,
      'pay_date', br.pay_date,
      'bulk_reference', br.bulk_reference,
      'status', br.status,
      'total_bank_out', br.total_bank_out,
      'total_debt_created', br.total_debt_created
    )),
    '[]'::jsonb
  )
  into v_batches
  from batches_raw br;

  -- ---------------------------------------------------------
  -- TRANSFER matches (and link back to batch bulk ref)
  -- ---------------------------------------------------------
  with matches_raw as (
    select
      pbt.id as transfer_id,
      pbt.pay_batch_id,
      pb.pay_date,
      pb.bulk_reference,
      pbt.pay_channel,
      pbt.amount,
      pbt.currency,
      pbt.status as transfer_status,
      pbt.payment_reference,

      pbt.candidate_id,
      c.display_name as candidate_display_name,
      c.first_name as candidate_first_name,
      c.last_name as candidate_last_name,

      pbt.umbrella_id,
      u.name as umbrella_name
    from public.pay_bank_transfers pbt
    join public.pay_batches pb
      on pb.id = pbt.pay_batch_id
    left join public.candidates c
      on c.id = pbt.candidate_id
    left join public.umbrellas u
      on u.id = pbt.umbrella_id
    where
      (
        -- 7 digits -> match batch bulk_ref_num
        (v_is_digits7 and v_digits7_int is not null and pb.bulk_ref_num = v_digits7_int)
        or
        -- 15 digits -> match batch bulk_reference (digits-only or hyphenated)
        (v_is_digits15 and pb.bulk_reference is not null
          and (
            pb.bulk_reference = v_q_digits
            or regexp_replace(pb.bulk_reference, '[^0-9]', '', 'g') = v_q_digits
          )
        )
        or
        -- 8 digits -> DDMMYYYY match against bulk_ref_date or pay_date
        (v_is_digits8 and (
          to_char(pb.pay_date, 'DDMMYYYY') = v_q_digits
          or (pb.bulk_ref_date is not null and to_char(pb.bulk_ref_date, 'DDMMYYYY') = v_q_digits)
        ))
        or
        -- ISO date
        (v_q ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pb.pay_date = v_q::date)
        or
        -- free-text against payment_reference, candidate, umbrella, or bulk_reference
        (
          not v_is_digits7 and not v_is_digits15 and not v_is_digits8 and
          (
            (pbt.payment_reference is not null and pbt.payment_reference ilike ('%' || v_q || '%'))
            or
            (pb.bulk_reference is not null and pb.bulk_reference ilike ('%' || v_q || '%'))
            or
            (u.name is not null and u.name ilike ('%' || v_q || '%'))
            or
            (c.display_name is not null and c.display_name ilike ('%' || v_q || '%'))
            or
            (trim(concat_ws(' ', c.first_name, c.last_name)) <> '' and trim(concat_ws(' ', c.first_name, c.last_name)) ilike ('%' || v_q || '%'))
            or
            (v_amount_query is not null and pbt.amount = v_amount_query)
          )
        )
      )
    order by pb.pay_date desc, pbt.id desc
    offset v_offset
    limit v_limit
  )
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'transfer_id', mr.transfer_id,
      'pay_batch_id', mr.pay_batch_id,
      'pay_date', mr.pay_date,
      'bulk_reference', mr.bulk_reference,
      'pay_channel', mr.pay_channel,
      'amount', mr.amount,
      'currency', mr.currency,
      'transfer_status', mr.transfer_status,
      'payment_reference', mr.payment_reference,
      'candidate_id', mr.candidate_id,
      'candidate_name', coalesce(mr.candidate_display_name, nullif(btrim(concat_ws(' ', mr.candidate_first_name, mr.candidate_last_name)), '')),
      'umbrella_id', mr.umbrella_id,
      'umbrella_name', mr.umbrella_name
    )),
    '[]'::jsonb
  )
  into v_matches
  from matches_raw mr;

  return jsonb_build_object(
    'query', v_q,
    'query_digits', coalesce(v_q_digits, ''),
    'batches', v_batches,
    'matches', v_matches
  );
end;
$function$
;

-- [REPLACES] public.pay_workbench_complete_job(p_job_id uuid, p_result_json jsonb)  winner piece A26
CREATE OR REPLACE FUNCTION public.pay_workbench_complete_job(p_job_id uuid, p_result_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_result_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_job_type text := NULL::text;
  v_stage_job_type text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_has_open_session boolean := false;
  v_has_more boolean := false;
  v_next_cursor jsonb := NULL::jsonb;
  v_seeded_count integer := 0;
  v_new_scope_count integer := 0;
  v_processed_count integer := 0;
  v_ready_count_delta integer := 0;
  v_materialised_count integer := 0;
  v_error_count integer := 0;
  v_source_rows_written integer := 0;
  v_current_source_row_count integer := 0;
  v_current_source_row_count_authoritative boolean := false;
  v_source_build_run_id_text text := NULL::text;
  v_source_change_seq bigint := NULL::bigint;
  v_result_session_version bigint := NULL::bigint;
  v_source_seed_cursor_json jsonb := '{}'::jsonb;
  v_pending_line_work_exists boolean := false;
  v_ready_line_work_exists boolean := false;
  v_continuation_result jsonb := '{}'::jsonb;
  v_continuation_job_id_text text := NULL::text;
  v_continuation_jobs jsonb := '[]'::jsonb;
  v_continuation_count integer := 0;
  v_continuation_enqueued boolean := false;
  v_continuation_reused_count integer := 0;
  v_next_recommended_action text := NULL::text;
  v_existing_completion_json jsonb := '{}'::jsonb;
  v_payload_limit integer := 100;
  v_duplicate_completion boolean := false;
  v_completed_at_utc timestamptz := NULL::timestamptz;
  v_scope_pending_job_cleared_count integer := 0;
  v_scope_status_before_continuation text := NULL::text;
  v_scope_status_after_continuation text := NULL::text;
  v_scope_bucket_before_continuation text := NULL::text;
  v_scope_bucket_after_continuation text := NULL::text;
  v_scope_continuation_pending_delta integer := 0;
  v_scope_continuation_ready_delta integer := 0;
  v_scope_continuation_failed_delta integer := 0;
  v_scope_continuation_counter_adjusted boolean := false;
  v_finalisation_should_evaluate boolean := false;
  v_finalisation_actual_precheck_required boolean := false;
  v_finalisation_actual_precheck_passed boolean := false;
  v_current_candidate_terminal_success boolean := false;
  v_finalisation_evaluated boolean := false;
  v_finalisation_progress_json jsonb := '{}'::jsonb;
  v_finalisation_session_ready boolean := false;
  v_finalisation_ready_for_draft boolean := false;
  v_finalisation_ready_empty boolean := false;
  v_finalisation_stored_ready_mismatch boolean := false;
  v_finalisation_counter_reconciliation_required boolean := false;
  v_finalisation_counter_reconciliation_applied boolean := false;
  v_finalisation_counter_reconciled boolean := false;
  v_finalisation_counter_reconciliation_json jsonb := '{}'::jsonb;
  v_finalisation_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_draft_blocker_codes jsonb := '[]'::jsonb;
  v_finalisation_blocker_counts jsonb := '{}'::jsonb;
  v_final_progress_state text := NULL::text;
  v_final_phase text := NULL::text;
  v_final_status_text text := NULL::text;
  v_final_next_recommended_action text := NULL::text;
  v_authoritative_scope_total integer := 0;
  v_authoritative_scope_seeded integer := 0;
  v_authoritative_scope_ready integer := 0;
  v_authoritative_scope_pending integer := 0;
  v_authoritative_scope_failed integer := 0;
  v_authoritative_line_total integer := 0;
  v_authoritative_line_pending integer := 0;
  v_authoritative_line_ready integer := 0;
  v_authoritative_line_failed integer := 0;
  v_authoritative_preview_row_count integer := 0;
  v_authoritative_selected_row_count integer := 0;
  v_authoritative_section_counts_json jsonb := '{}'::jsonb;
  v_authoritative_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_completion_finalisation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_json jsonb := '{}'::jsonb;
  v_source_reconciliation_applied boolean := false;
  v_source_reconciliation_deferred boolean := false;
  v_source_reconciliation_deferred_reason text := NULL::text;
  v_certified_publication_json jsonb := '{}'::jsonb;
  v_certified_publication_applied boolean := false;
  v_certified_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_certified_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_source_empty_session_progress_deferred boolean := false;
  v_source_empty_session_progress_deferred_reason text := NULL::text;
  v_source_empty_cleanup_source_row_count integer := 0;
  v_source_empty_cleanup_line_work_count integer := 0;
  v_source_empty_cleanup_preview_row_count integer := 0;
  v_source_empty_targeted_timesheet_count integer := 0;
  v_bounded_terminal_refresh_scope_kind text := NULL::text;
  v_bounded_terminal_targeted_timesheet_count integer := 0;
  v_bounded_terminal_source_rows_retired_count integer := 0;
  v_bounded_terminal_line_work_retired_count integer := 0;
  v_bounded_terminal_scope_finalised_count integer := 0;
  v_continuation_scope_counter_deferred boolean := false;
  v_continuation_scope_counter_deferred_reason text := NULL::text;
  v_finalisation_deferred boolean := false;
  v_finalisation_deferred_reason text := NULL::text;
  v_delta_fallback_required boolean := false;
  v_delta_fallback_reason text := NULL::text;
  v_delta_refresh_complete boolean := false;
  v_delta_more_due boolean := false;
  v_delta_made_progress boolean := false;
  v_delta_projection_run_id_text text := NULL::text;
  v_delta_next_cursor_json jsonb := NULL::jsonb;
  v_delta_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_delta_source_rows_written integer := 0;
  v_delta_line_rows_written integer := 0;
  v_delta_preview_rows_written integer := 0;
  v_delta_rows_superseded integer := 0;
  v_delta_shadow_compare_status text := NULL::text;
  v_delta_shadow_compare_required boolean := false;
  v_delta_shadow_compare_enforced boolean := false;
  v_delta_shadow_compare_failed boolean := false;
  v_clone_more_due boolean := false;
  v_clone_complete boolean := false;
  v_clone_copied_candidate_count integer := 0;
  v_clone_copied_preview_row_count integer := 0;
  v_clone_legacy_refresh_enqueued_count integer := 0;
  v_clone_continuation_job_id uuid := NULL::uuid;
  v_clone_source_session_id_text text := NULL::text;
  v_clone_source_session_id uuid := NULL::uuid;
  v_clone_source_session_retired_count integer := 0;
  v_delta_fallback_enqueue_result jsonb := '{}'::jsonb;
  v_delta_fallback_job_id_text text := NULL::text;
  v_delta_scope_total_count integer := 0;
  v_delta_scope_ready_count integer := 0;
  v_delta_scope_pending_count integer := 0;
  v_delta_scope_failed_count integer := 0;
  v_delta_line_units_total integer := 0;
  v_delta_line_units_ready integer := 0;
  v_delta_line_units_pending integer := 0;
  v_delta_line_units_failed integer := 0;
  v_delta_preview_row_count integer := 0;
  v_delta_selected_row_count integer := 0;
  v_delta_section_counts_json jsonb := '{}'::jsonb;
  v_delta_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_live_source_change_seq bigint := 0;
  v_delta_superseded_by_live_source_guard boolean := false;
  v_delta_superseded_projection_runs integer := 0;
  v_delta_projection_mode text := 'DELTA';
  v_delta_projection_class text := 'UNKNOWN';
  v_delta_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_delta_lifecycle_context text := NULL::text;
  v_delta_is_normal_targeted_lifecycle boolean := false;
  v_delta_recovery_enqueue_result jsonb := '{}'::jsonb;
  v_delta_recovery_job_id_text text := NULL::text;
  v_delta_recovery_job_id uuid := NULL::uuid;
  v_delta_recovery_source_change_seq bigint := 0;
  v_delta_recovery_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_delta_recovery_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_material_attempt_id uuid := NULL::uuid;
  v_semantic_publication_v3_enabled boolean := false;
  v_correction_request_id uuid := NULL::uuid;
  v_correction_pay_batch_id uuid := NULL::uuid;
  v_correction_signal_claimed boolean := false;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  SELECT workbench_job.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs AS workbench_job
  WHERE workbench_job.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled, false)
  INTO v_semantic_publication_v3_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  IF v_job_row.candidate_id IS NOT NULL
     AND UPPER(BTRIM(COALESCE(v_job_row.job_type,''))) IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
       'CANDIDATE_SOURCE_BUILD',
       'CANDIDATE_SOURCE_BUILD_CHUNK',
       'SOURCE_BUILD',
       'SOURCE_BUILD_PAGE',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'SESSION_CLONE_REBASE',
       'CLONE_REBASE'
     ) THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        public._pay_workbench_candidate_serial_key(v_job_row.candidate_id),
        24062027
      )
    );
  END IF;

  v_duplicate_completion := UPPER(BTRIM(COALESCE(v_job_row.status, ''))) = 'SUCCEEDED'
    AND v_job_row.completed_at_utc IS NOT NULL;

  IF v_duplicate_completion THEN
    v_existing_completion_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'completion_json', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    v_result_json := CASE
      WHEN jsonb_typeof(COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)) = 'object'
        THEN COALESCE(v_job_row.payload_json->'result_json', '{}'::jsonb)
      ELSE v_result_json
    END;

    v_continuation_jobs := CASE
      WHEN jsonb_typeof(COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)) = 'array'
        THEN COALESCE(v_existing_completion_json->'continuation_jobs', '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    v_continuation_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_count')::integer
      ELSE jsonb_array_length(v_continuation_jobs)
    END;

    v_continuation_reused_count := CASE
      WHEN COALESCE(v_existing_completion_json->>'continuation_reused_count', '') ~ '^[0-9]+$'
        THEN (v_existing_completion_json->>'continuation_reused_count')::integer
      ELSE 0
    END;

    v_continuation_enqueued := COALESCE(v_continuation_count, 0) > 0
      OR LOWER(BTRIM(COALESCE(v_existing_completion_json->>'continuation_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_next_recommended_action := NULLIF(BTRIM(COALESCE(v_existing_completion_json->>'next_recommended_action', '')), '');
    v_completed_at_utc := v_job_row.completed_at_utc;
  END IF;

  v_job_type := UPPER(BTRIM(COALESCE(v_job_row.job_type, '')));
  v_stage_job_type := CASE
    WHEN v_job_type IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED') THEN 'WORKBENCH_SESSION_SCOPE_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE') THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    WHEN v_job_type IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN 'WORKBENCH_SESSION_CLONE_REBASE'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    WHEN v_job_type IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS', 'LINE_WORK_PROCESS') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
    WHEN v_job_type IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE') THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    WHEN v_job_type IN ('SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH')
      AND v_job_row.session_id IS NOT NULL
      AND COALESCE((v_job_row.payload_json->>'line_work_only')::boolean, false) IS TRUE THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    ELSE v_job_type
  END;

  IF COALESCE(v_result_json->>'has_more', '') ~* '^(true|t|1|yes)$' THEN
    v_has_more := true;
  ELSE
    v_has_more := false;
  END IF;

  v_next_cursor := CASE
    WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
    WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
    WHEN jsonb_typeof(v_result_json->'nextCursor') = 'object' THEN v_result_json->'nextCursor'
    WHEN jsonb_typeof(v_result_json->'nextCursorJson') = 'object' THEN v_result_json->'nextCursorJson'
    ELSE NULL::jsonb
  END;

  -- Material bounded-source stages have their own exact completion path.  The
  -- immutable attempt must already be COMPLETED by RPC 2, and at most one
  -- typed continuation is committed with this job completion.
  IF v_stage_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_job_row.economic_build_id IS NOT NULL THEN
    IF v_duplicate_completion THEN
      -- A lost terminal response may leave certified CURRENT source without
      -- the public preview.  Duplicate completion is therefore the normal,
      -- idempotent self-heal owner; it never reruns source economics.
      SELECT build_row.source_build_run_id::text,
             build_row.source_change_seq,
             build_row.session_version
      INTO v_source_build_run_id_text,
           v_source_change_seq,
           v_result_session_version
      FROM private.banking_pay_workbench_economic_builds AS build_row
      WHERE build_row.id = v_job_row.economic_build_id
        AND build_row.session_id = v_job_row.session_id
        AND build_row.candidate_id = v_job_row.candidate_id
        AND UPPER(BTRIM(COALESCE(build_row.status, ''))) = 'COMPLETE'
        AND UPPER(BTRIM(COALESCE(build_row.private_stage, ''))) = 'COMPLETE';

      IF FOUND THEN
        v_certified_targeted_timesheet_ids := CASE
          WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array'
            THEN v_job_row.payload_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array'
            THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
          ELSE COALESCE((
            SELECT jsonb_agg(DISTINCT build_scope.timesheet_id::text ORDER BY build_scope.timesheet_id::text)
            FROM private.banking_pay_workbench_economic_build_scope AS build_scope
            WHERE build_scope.build_id = v_job_row.economic_build_id
              AND build_scope.timesheet_id IS NOT NULL
          ), '[]'::jsonb)
        END;
        v_certified_linked_timesheet_ids := CASE
          WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array'
            THEN v_job_row.payload_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array'
            THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
          ELSE '[]'::jsonb
        END;

        v_certified_publication_json := private.pay_workbench_publish_certified_source_preview_v1(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_economic_build_id => v_job_row.economic_build_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => v_result_session_version,
          p_completion_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(v_job_row.payload_json->>'refresh_scope_kind'), ''),
            NULLIF(BTRIM(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}'), ''),
            'CANDIDATE_FULL_LIVE'
          ),
          p_targeted_timesheet_ids => v_certified_targeted_timesheet_ids,
          p_linked_timesheet_ids => v_certified_linked_timesheet_ids,
          p_publication_options_json => CASE
            WHEN v_semantic_publication_v3_enabled THEN jsonb_build_object(
              'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
              'invocation_kind', 'DUPLICATE_REPLAY_REPAIR',
              'contract_version', 3,
              'final_state', CASE WHEN EXISTS (
                SELECT 1
                FROM public.banking_pay_workbench_candidate_source_lines AS duplicate_source
                WHERE duplicate_source.session_id=v_job_row.session_id
                  AND duplicate_source.candidate_id=v_job_row.candidate_id
                  AND duplicate_source.source_build_run_id=v_source_build_run_id_text::uuid
                  AND duplicate_source.source_change_seq=v_source_change_seq
                  AND duplicate_source.status='CURRENT'
              ) THEN 'READY' ELSE 'SOURCE_EMPTY' END,
              'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2'
            )
            ELSE jsonb_build_object(
              'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
              'invocation_kind', 'DUPLICATE_REPLAY_REPAIR',
              'contract_version', 1
            )
          END
        );
        v_certified_publication_applied := COALESCE((v_certified_publication_json->>'parity_complete')::boolean, false);

        IF v_certified_publication_applied IS NOT TRUE THEN
          RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED' USING ERRCODE = 'P0001';
        END IF;

        IF COALESCE((v_certified_publication_json->>'already_current')::boolean, false) IS NOT TRUE THEN
          UPDATE public.banking_pay_workbench_session_scope AS duplicate_scope
          SET status = CASE
                WHEN COALESCE((v_certified_publication_json->>'source_row_count')::integer, 0) = 0 THEN 'SOURCE_EMPTY'
                ELSE 'MATERIALISED'
              END,
              seeded = true,
              dirty = false,
              pending_job_id = NULL::uuid,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE duplicate_scope.session_id = v_job_row.session_id
            AND duplicate_scope.candidate_id = v_job_row.candidate_id;

          PERFORM public.pay_workbench_session_recompute_progress_counters(
            v_job_row.session_id,
            true,
            'CERTIFIED_SOURCE_PREVIEW_DUPLICATE_SELF_HEAL',
            true
          );
        END IF;
      END IF;

      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'duplicate_completion',true,'continuation_enqueued',
        COALESCE((v_existing_completion_json->>'continuation_enqueued')::boolean,false),
        'continuation_jobs',COALESCE(v_existing_completion_json->'continuation_jobs','[]'::jsonb),
        'certified_source_preview',v_certified_publication_json,
        'completed_at_utc',v_job_row.completed_at_utc);
    END IF;
    SELECT attempt.id INTO v_material_attempt_id
    FROM private.banking_pay_workbench_stage_attempts attempt
    WHERE attempt.job_id=p_job_id AND attempt.build_id=v_job_row.economic_build_id
      AND attempt.private_stage=v_job_row.private_stage
      AND attempt.attempt_status='COMPLETED'
      AND attempt.attempt_number=v_job_row.attempt_count
    ORDER BY attempt.id DESC LIMIT 1;
    IF v_material_attempt_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_COMPLETION_REQUIRED' USING ERRCODE='40001';
    END IF;
    IF v_has_more AND v_next_cursor IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_CONTINUATION_CURSOR_REQUIRED' USING ERRCODE='22023';
    END IF;
    IF v_has_more THEN
      v_continuation_result:=public.pay_workbench_enqueue_stage_continuation(
        p_session_id=>v_job_row.session_id,p_candidate_id=>v_job_row.candidate_id,
        p_job_type=>'WORKBENCH_CANDIDATE_SOURCE_BUILD',p_cursor_json=>v_next_cursor,
        p_source_job_id=>p_job_id,p_result_json=>v_result_json,
        p_actor_user_id=>NULLIF(v_job_row.payload_json->>'actor_user_id','')::uuid,
        p_reason=>COALESCE(v_result_json->>'next_action','BOUNDED_STAGE_CONTINUATION'),
        p_priority=>v_job_row.priority,p_limit=>COALESCE(
          NULLIF(v_job_row.payload_json->>'source_build_limit','')::integer,
          NULLIF(v_job_row.payload_json->>'limit','')::integer,25)
      );
      v_continuation_job_id_text:=NULLIF(v_continuation_result->>'job_id','');
      v_continuation_enqueued:=v_continuation_job_id_text IS NOT NULL;
      v_continuation_jobs:=CASE WHEN v_continuation_job_id_text IS NULL THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('job_id',v_continuation_job_id_text,
          'job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD','private_stage',v_result_json->>'next_action')) END;
      v_continuation_count:=CASE WHEN v_continuation_enqueued THEN 1 ELSE 0 END;
    END IF;
    -- A nonterminal material page owns only its exact continuation. Terminal
    -- material completion must continue through the common successful-source
    -- reconciliation below so the public session scope cannot remain bound to
    -- a job that has already succeeded.
    IF v_has_more THEN
      UPDATE public.banking_pay_workbench_jobs target_job SET status='SUCCEEDED',
        completed_at_utc=clock_timestamp(),failed_at_utc=NULL,last_error_json=NULL,
        payload_json=COALESCE(target_job.payload_json,'{}'::jsonb)
          ||jsonb_build_object('result_json',public.pay_workbench_compact_job_result_json(v_result_json))
          ||jsonb_build_object('completion_json',jsonb_build_object(
            'attempt_id',v_material_attempt_id,'continuation_enqueued',v_continuation_enqueued,
            'continuation_jobs',v_continuation_jobs,'continuation_count',v_continuation_count,
            'next_recommended_action',v_result_json->>'next_action',
            'completed_at_utc',clock_timestamp())),updated_at_utc=clock_timestamp()
      WHERE target_job.id=p_job_id AND target_job.status='RUNNING';
      IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_JOB_COMPLETION_STALE' USING ERRCODE='40001'; END IF;
      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'duplicate_completion',false,'continuation_enqueued',v_continuation_enqueued,
        'continuation_jobs',v_continuation_jobs,'continuation_count',v_continuation_count,
        'next_recommended_action',v_result_json->>'next_action','completed_at_utc',clock_timestamp());
    END IF;
  END IF;

  v_seeded_count := CASE WHEN COALESCE(v_result_json->>'seeded_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'seeded_count')::integer ELSE 0 END;
  v_new_scope_count := CASE WHEN COALESCE(v_result_json->>'new_scope_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'new_scope_count')::integer ELSE 0 END;
  v_processed_count := CASE WHEN COALESCE(v_result_json->>'processed_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'processed_count')::integer ELSE 0 END;
  v_ready_count_delta := CASE WHEN COALESCE(v_result_json->>'ready_count_delta', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'ready_count_delta')::integer ELSE 0 END;
  v_materialised_count := CASE
    WHEN COALESCE(v_result_json->>'materialised_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialised_count')::integer
    WHEN COALESCE(v_result_json->>'materialized_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialized_count')::integer
    ELSE 0
  END;
  v_error_count := CASE
    WHEN COALESCE(v_result_json->>'error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'error_count')::integer
    WHEN COALESCE(v_result_json->>'materialisation_error_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'materialisation_error_count')::integer
    ELSE 0
  END;
  v_source_rows_written := CASE
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    WHEN COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'published_count')::integer
    ELSE 0
  END;
  v_current_source_row_count := CASE
    WHEN COALESCE(v_result_json->>'current_source_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'current_source_row_count')::integer
    WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer
    WHEN COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'published_count')::integer
    ELSE 0
  END;
  v_current_source_row_count_authoritative := LOWER(BTRIM(COALESCE(
    v_result_json->>'current_source_row_count_authoritative',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND v_job_row.economic_build_id IS NOT NULL
      AND COALESCE(v_has_more, false) IS NOT TRUE
      AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
      AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
      AND COALESCE(v_result_json->>'published_count', '') ~ '^-?[0-9]+$'
    );
  v_source_build_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,source_build_run_id}', '')), '')
  );
  v_source_change_seq := CASE
    WHEN COALESCE(v_result_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_seq')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'source_change_sequence')::bigint
    ELSE NULL::bigint
  END;
  v_result_session_version := CASE
    WHEN COALESCE(v_result_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_result_json->>'session_version')::bigint
    WHEN COALESCE(v_job_row.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_job_row.payload_json->>'session_version')::bigint
    ELSE NULL::bigint
  END;
  v_source_seed_cursor_json := jsonb_strip_nulls(jsonb_build_object(
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'session_version', v_result_session_version,
    'source_snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'source_row_cursor', 'START'
  ));
  v_payload_limit := LEAST(
    GREATEST(
      CASE
        WHEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''), '') ~ '^[0-9]+$'
          THEN COALESCE(NULLIF(BTRIM(v_job_row.payload_json->>'line_limit'), ''), NULLIF(BTRIM(v_job_row.payload_json->>'limit'), ''))::integer
        ELSE 100
      END,
      1
    ),
    100
  );

  IF v_job_row.session_id IS NOT NULL THEN
    SELECT session_row.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_job_row.session_id;

    v_has_open_session := FOUND
      AND UPPER(BTRIM(COALESCE(v_session_row.status, ''))) = 'OPEN'
      AND v_session_row.discarded_at_utc IS NULL;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_COMPLETE_JOB_SESSION_NOT_OPEN',
              'job_id', p_job_id::text,
              'session_id', v_job_row.session_id::text,
              'job_type', v_stage_job_type,
              'status', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.status END,
              'discarded_at_utc', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.discarded_at_utc END
            )::text;
  END IF;

  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_delta_fallback_required := LOWER(BTRIM(COALESCE(v_result_json->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_fallback_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'fallback_reason', '')), ''), 'DELTA_REFRESH_FALLBACK_REQUIRED');
    v_delta_refresh_complete := LOWER(BTRIM(COALESCE(v_result_json->>'delta_refresh_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_made_progress := LOWER(BTRIM(COALESCE(v_result_json->>'made_progress', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_projection_run_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_run_id', '')), '')
    );
    v_delta_next_cursor_json := CASE
      WHEN jsonb_typeof(v_result_json->'next_cursor_json') = 'object' THEN v_result_json->'next_cursor_json'
      WHEN jsonb_typeof(v_result_json->'next_cursor') = 'object' THEN v_result_json->'next_cursor'
      WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
      ELSE '{}'::jsonb
    END;
    v_delta_targeted_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_linked_timesheet_ids_json := CASE
      WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
      WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
      ELSE '[]'::jsonb
    END;
    v_delta_source_rows_written := CASE WHEN COALESCE(v_result_json->>'source_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'source_rows_written')::integer ELSE 0 END;
    v_delta_line_rows_written := CASE WHEN COALESCE(v_result_json->>'line_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'line_rows_written')::integer ELSE 0 END;
    v_delta_preview_rows_written := CASE WHEN COALESCE(v_result_json->>'preview_rows_written', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'preview_rows_written')::integer ELSE 0 END;
    v_delta_rows_superseded := CASE WHEN COALESCE(v_result_json->>'rows_superseded', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'rows_superseded')::integer ELSE 0 END;
    v_delta_shadow_compare_status := UPPER(BTRIM(COALESCE(v_result_json->>'shadow_compare_status', '')));
    v_delta_shadow_compare_required := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_required',
      v_job_row.payload_json->>'shadow_compare_required',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := LOWER(BTRIM(COALESCE(
      v_result_json->>'shadow_compare_enforced',
      v_job_row.payload_json->>'shadow_compare_enforced',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_delta_shadow_compare_enforced := COALESCE(v_delta_shadow_compare_required, false)
      AND COALESCE(v_delta_shadow_compare_enforced, false);
    v_delta_shadow_compare_failed := LOWER(BTRIM(COALESCE(v_result_json->>'shadow_compare_failed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR v_delta_shadow_compare_status = 'MISMATCH'
      OR (
        COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
        AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
      );
    IF v_delta_shadow_compare_failed IS TRUE THEN
      v_delta_fallback_required := true;
      v_delta_fallback_reason := CASE
        WHEN COALESCE(v_delta_shadow_compare_enforced, false) IS TRUE
         AND v_delta_shadow_compare_status IN ('REFERENCE_UNAVAILABLE', 'REFERENCE_MISSING', 'UNAVAILABLE')
          THEN 'SHADOW_REFERENCE_UNAVAILABLE'
        ELSE 'SHADOW_COMPARE_MISMATCH'
      END;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT parsed_target.timesheet_id ORDER BY parsed_target.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_targeted_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(target_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) AS target_value(value)
      WHERE NULLIF(BTRIM(target_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_target;

    SELECT COALESCE(array_agg(DISTINCT parsed_linked.timesheet_id ORDER BY parsed_linked.timesheet_id), ARRAY[]::uuid[])
    INTO v_delta_recovery_linked_timesheet_ids
    FROM (
      SELECT NULLIF(BTRIM(linked_value.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
      WHERE NULLIF(BTRIM(linked_value.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS parsed_linked;

    v_delta_projection_mode := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_mode',
      v_job_row.payload_json->>'projection_mode',
      v_result_json->>'resolved_mode',
      v_job_row.payload_json->>'resolved_mode',
      'DELTA'
    ))), ''), 'DELTA');

    v_delta_projection_class := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'projection_class',
      v_job_row.payload_json->>'projection_class',
      'UNKNOWN'
    ))), ''), 'UNKNOWN');

    v_delta_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
      v_result_json->>'refresh_scope_kind',
      v_job_row.payload_json->>'refresh_scope_kind',
      ''
    ))), ''), CASE
      WHEN COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
        OR COALESCE(array_length(v_delta_recovery_linked_timesheet_ids, 1), 0) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END);

    v_delta_lifecycle_context := LOWER(BTRIM(COALESCE(
      v_result_json->>'lifecycle_mutation_context',
      v_job_row.payload_json->>'lifecycle_mutation_context',
      v_result_json->>'mutation_context',
      v_job_row.payload_json->>'mutation_context',
      v_result_json->>'lifecycle_context',
      v_job_row.payload_json->>'lifecycle_context',
      v_result_json->>'trigger_source',
      v_job_row.payload_json->>'trigger_source',
      v_result_json->>'reason',
      v_job_row.payload_json->>'reason_latest',
      v_job_row.payload_json->>'reason',
      ''
    )));

    v_delta_is_normal_targeted_lifecycle := v_delta_projection_mode = 'DELTA'
      AND v_delta_projection_class = 'NORMAL_TIMESHEET'
      AND v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS'
      AND COALESCE(array_length(v_delta_recovery_targeted_timesheet_ids, 1), 0) > 0
      AND COALESCE(v_delta_shadow_compare_failed, false) IS NOT TRUE
      AND (
        COALESCE(v_delta_fallback_required, false) IS NOT TRUE
        OR UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
        OR LOWER(BTRIM(COALESCE(v_result_json->>'identical_cursor_self_reuse_suppressed', v_result_json->>'continuation_not_enqueued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_legacy', v_job_row.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'force_broad_legacy', v_job_row.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'source_build_required', v_job_row.payload_json->>'source_build_required', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(v_result_json->>'ordinary_timesheet_edit_save_no_dirty', v_job_row.payload_json->>'ordinary_timesheet_edit_save_no_dirty', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND (
        LOWER(BTRIM(COALESCE(v_result_json->>'authorise_boundary_changed', v_job_row.payload_json->>'authorise_boundary_changed', v_result_json->>'timesheet_authorise_boundary_changed', v_job_row.payload_json->>'timesheet_authorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR v_delta_lifecycle_context IN ('timesheet_authorise', 'authorise_timesheet', 'timesheet_unauthorise', 'unauthorise_timesheet')
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%authorise%'
        OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
      );

    v_delta_next_cursor_json := COALESCE(v_delta_next_cursor_json, '{}'::jsonb)
      || jsonb_strip_nulls(jsonb_build_object(
        'projection_run_id', v_delta_projection_run_id_text,
        'phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'next_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_result_json->>'phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'phase', '')), '')),
        'cursor', CASE
          WHEN jsonb_typeof(v_delta_next_cursor_json->'cursor') = 'object' THEN v_delta_next_cursor_json->'cursor'
          WHEN jsonb_typeof(v_job_row.payload_json->'cursor_json') = 'object' THEN v_job_row.payload_json->'cursor_json'
          ELSE '{}'::jsonb
        END,
        'write_phase', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'write_phase', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'write_phase', '')), '')),
        'write_cursor_json', CASE
          WHEN jsonb_typeof(v_result_json->'write_cursor_json') = 'object' THEN v_result_json->'write_cursor_json'
          WHEN jsonb_typeof(v_delta_next_cursor_json->'write_cursor_json') = 'object' THEN v_delta_next_cursor_json->'write_cursor_json'
          WHEN jsonb_typeof(v_job_row.payload_json->'write_cursor_json') = 'object' THEN v_job_row.payload_json->'write_cursor_json'
          ELSE NULL::jsonb
        END,
        'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', CASE WHEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq', '') ~ '^-?[0-9]+$' THEN COALESCE(v_result_json->>'source_change_seq', v_job_row.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END
      ));

    IF v_job_row.candidate_id IS NOT NULL
       AND v_source_change_seq IS NOT NULL THEN
      SELECT COALESCE(change_counter.seq, 0)
      INTO v_live_source_change_seq
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

      v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);

      IF COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
        v_delta_superseded_by_live_source_guard := true;
        v_delta_more_due := false;
        v_delta_fallback_required := false;
        v_delta_refresh_complete := true;
        v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';

        v_result_json := jsonb_strip_nulls(
          COALESCE(v_result_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_newer_source_change_seq', true,
            'complete_job_live_source_guard_applied', true,
            'source_change_seq', v_source_change_seq,
            'newer_source_change_seq', v_live_source_change_seq,
            'live_source_change_seq', v_live_source_change_seq,
            'fallback_required', false,
            'delta_refresh_complete', true,
            'more_due', false,
            'has_more', false,
            'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
          )
        );

        IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
          SET status = 'FAILED',
              fallback_required = false,
              fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
              diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                || jsonb_build_object(
                  'superseded_by_newer_source_change_seq', true,
                  'complete_job_live_source_guard_applied', true,
                  'source_change_seq', v_source_change_seq,
                  'newer_source_change_seq', v_live_source_change_seq,
                  'terminalised_by', 'pay_workbench_complete_job',
                  'terminalised_at_utc', v_now::text
                ),
              updated_at_utc = v_now,
              completed_at_utc = v_now
          WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
            AND projection_run_update.session_id = v_job_row.session_id
            AND projection_run_update.candidate_id = v_job_row.candidate_id
            AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

          GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
        END IF;
      END IF;
    ELSE
      v_live_source_change_seq := 0;
    END IF;

    IF v_delta_superseded_by_live_source_guard IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := '[]'::jsonb;
      v_continuation_count := 0;
      v_continuation_reused_count := 0;
      v_continuation_enqueued := false;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_more_due IS TRUE THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => v_job_row.candidate_id,
        p_job_type => 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        p_cursor_json => COALESCE(v_delta_next_cursor_json, '{}'::jsonb),
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'DELTA_REFRESH_MORE_DUE',
        p_priority => COALESCE(v_job_row.priority, 43),
        p_limit => v_payload_limit
      );

      v_continuation_job_id_text := NULLIF(BTRIM(COALESCE(v_continuation_result->>'job_id', '')), '');

      IF LOWER(BTRIM(COALESCE(
           v_continuation_result->>'identical_cursor_self_reuse_suppressed',
           v_continuation_result->>'continuation_not_enqueued',
           'false'
         ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        IF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL THEN
          SELECT COALESCE(change_counter.seq, 0)
          INTO v_live_source_change_seq
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

          v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
        END IF;

        IF v_delta_is_normal_targeted_lifecycle IS TRUE THEN
          v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
          v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'identical_cursor_self_reuse_suppressed', true,
              'delta_identical_cursor_self_reuse_no_source_build', true,
              'fallback_required', false,
              'fallback_reason', v_delta_fallback_reason,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'source_change_seq', COALESCE(v_source_change_seq, 0),
              'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
              'next_recommended_action', 'DELTA_REFRESH_CHUNK'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'delta_identical_cursor_self_reuse_no_source_build', true,
                    'successor_required', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'source_change_seq', COALESCE(v_source_change_seq, 0),
                    'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                    'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              (COALESCE(v_job_row.payload_json, '{}'::jsonb) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present',
                'projection_run_id'
              ]::text[])
              || jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'workbench_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', false,
                'force_broad_legacy', false,
                'fallback_from_delta', false,
                'fallback_reason', v_delta_fallback_reason,
                'projection_mode', 'DELTA',
                'projection_class', 'NORMAL_TIMESHEET',
                'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                'phase', 'INIT_PREFLIGHT',
                'cursor_json', '{}'::jsonb,
                'source_build_required', false,
                'line_work_required', false,
                'delta_refresh_required', true,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'successor_for_job_id', p_job_id::text,
                'previous_projection_run_id', v_delta_projection_run_id_text,
                'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                'lifecycle_mutation_context', CASE
                  WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                    OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                    OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                  THEN 'timesheet_unauthorise'
                  ELSE 'timesheet_authorise'
                END,
                'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                'policy_x_dirtying_only', true,
                'economic_truth_mutation_allowed', false
              )
            )
          );

          v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

          IF v_delta_recovery_job_id_text = p_job_id::text THEN
            v_delta_recovery_job_id_text := NULL;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL THEN
            v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
              p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
              p_scope_kind => 'CANDIDATE',
              p_scope_id => v_job_row.candidate_id::text,
              p_candidate_id => v_job_row.candidate_id,
              p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
              p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
              p_payload_json => jsonb_strip_nulls(
                COALESCE(v_job_row.payload_json, '{}'::jsonb)
                || jsonb_build_object(
                  'session_id', v_job_row.session_id::text,
                  'source_session_id', v_job_row.session_id::text,
                  'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                  'session_version', COALESCE(v_session_row.version, 0),
                  'session_signature', v_session_row.session_signature,
                  'refresh_scope_kind', 'TARGETED_TIMESHEETS',
                  'projection_mode', 'DELTA',
                  'projection_class', 'NORMAL_TIMESHEET',
                  'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                  'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                  'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                  'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
                  'fallback_reason', v_delta_fallback_reason,
                  'source_build_required', false,
                  'line_work_required', false,
                  'delta_refresh_required', true,
                  'identical_cursor_self_reuse_suppressed', true,
                  'delta_identical_cursor_self_reuse_no_source_build', true,
                  'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
                  'lifecycle_mutation_context', CASE
                    WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                      OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                      OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
                    THEN 'timesheet_unauthorise'
                    ELSE 'timesheet_authorise'
                  END,
                  'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
                  'policy_x_dirtying_only', true,
                  'economic_truth_mutation_allowed', false
                )
              ),
              p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
              p_priority => -1000,
              p_run_at_utc => v_now
            );

            v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

            IF v_delta_recovery_job_id_text IS NULL
               AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
              SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
              INTO v_delta_recovery_job_id_text
              FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
              WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
                AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              LIMIT 1;
            END IF;

            IF v_delta_recovery_job_id_text = p_job_id::text THEN
              v_delta_recovery_job_id_text := NULL;
            END IF;
          END IF;

          IF v_delta_recovery_job_id_text IS NULL
             OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
              USING ERRCODE = 'P0001',
                    DETAIL = jsonb_build_object(
                      'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                      'job_id', p_job_id::text,
                      'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                      'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                      'projection_run_id', v_delta_projection_run_id_text,
                      'source_change_seq', v_source_change_seq,
                      'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                      'message', 'Normal targeted lifecycle DELTA self-reuse suppression could not create or reuse a cron-claimable recovery job.'
                    )::text;
          END IF;

          v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

          UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
          SET status = CASE
                WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
                 AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
                  THEN 'PENDING'
                ELSE 'DELTA_REFRESH_PENDING'
              END,
              dirty = true,
              pending_job_id = v_delta_recovery_job_id,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_recovery_scope.session_id = v_job_row.session_id
            AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
          v_continuation_count := 1;
          v_continuation_reused_count := CASE
            WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            THEN 1
            ELSE 0
          END;
          v_continuation_enqueued := true;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSIF v_job_row.candidate_id IS NOT NULL
           AND v_source_change_seq IS NOT NULL
           AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
          v_delta_more_due := false;
          v_delta_fallback_required := false;
          v_delta_refresh_complete := true;
          v_delta_fallback_reason := 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ';
          v_delta_superseded_by_live_source_guard := true;

          v_result_json := jsonb_strip_nulls(
            COALESCE(v_result_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_newer_source_change_seq', true,
              'complete_job_live_source_guard_applied', true,
              'identical_cursor_self_reuse_suppressed', true,
              'source_change_seq', v_source_change_seq,
              'newer_source_change_seq', v_live_source_change_seq,
              'live_source_change_seq', v_live_source_change_seq,
              'fallback_required', false,
              'delta_refresh_complete', true,
              'more_due', false,
              'has_more', false,
              'stop_reason', 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
            )
          );

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FAILED',
                fallback_required = false,
                fallback_reason = 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ',
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'superseded_by_newer_source_change_seq', true,
                    'complete_job_live_source_guard_applied', true,
                    'identical_cursor_self_reuse_suppressed', true,
                    'source_change_seq', v_source_change_seq,
                    'newer_source_change_seq', v_live_source_change_seq,
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';

            GET DIAGNOSTICS v_delta_superseded_projection_runs = ROW_COUNT;
          END IF;

          UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
          SET dirty = true,
              pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_superseded_scope.session_id = v_job_row.session_id
            AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result);
          v_continuation_count := 0;
          v_continuation_reused_count := 0;
          v_continuation_enqueued := false;
          v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
        ELSE
          v_delta_more_due := false;
          v_delta_fallback_required := true;
          v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';

          IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
            SET status = 'FALLBACK_REQUIRED',
                fallback_required = true,
                fallback_reason = v_delta_fallback_reason,
                diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
                  || jsonb_build_object(
                    'identical_cursor_self_reuse_suppressed', true,
                    'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                    'terminalised_by', 'pay_workbench_complete_job',
                    'terminalised_at_utc', v_now::text
                  ),
                updated_at_utc = v_now,
                completed_at_utc = v_now
            WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
              AND projection_run_update.session_id = v_job_row.session_id
              AND projection_run_update.candidate_id = v_job_row.candidate_id
              AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) = 'RUNNING';
          END IF;

          v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
            p_snapshot_run_id => v_session_row.source_snapshot_run_id,
            p_candidate_id => v_job_row.candidate_id,
            p_reason => v_delta_fallback_reason,
            p_actor_user_id => v_session_row.actor_user_id,
            p_payload_json => jsonb_strip_nulls(
              jsonb_build_object(
                'session_id', v_job_row.session_id::text,
                'source_session_id', v_job_row.session_id::text,
                'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
                'session_version', COALESCE(v_session_row.version, 0),
                'session_signature', v_session_row.session_signature,
                'force_legacy', true,
                'fallback_from_delta', true,
                'fallback_reason', v_delta_fallback_reason,
                'projection_run_id', v_delta_projection_run_id_text,
                'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
                'source_build_required', true,
                'line_work_required', true,
                'delta_refresh_required', false,
                'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
                'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
                'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
              )
            )
          );

          v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');

          UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
          SET status = 'SOURCE_BUILD_PENDING',
              dirty = true,
              pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE delta_fallback_scope.session_id = v_job_row.session_id
            AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;

          v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_fallback_enqueue_result);
          v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
          v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
          v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
          v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
        END IF;
      ELSE
        IF v_continuation_job_id_text IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_JOB_ID_MISSING',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta more_due completion did not receive a concrete continuation job id.'
                  )::text;
        END IF;

        IF v_continuation_job_id_text = p_job_id::text THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_DELTA_CONTINUATION_SELF_REUSE_GUARD_FAILED',
                    'job_id', p_job_id::text,
                    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                    'projection_run_id', v_delta_projection_run_id_text,
                    'source_change_seq', v_source_change_seq,
                    'continuation_result', v_continuation_result,
                    'message', 'Delta continuation helper returned the currently completing job as its own continuation.'
                  )::text;
        END IF;

        v_continuation_jobs := jsonb_build_array(v_continuation_result);
        v_continuation_count := 1;
        v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_continuation_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
        v_continuation_enqueued := true;
        v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
      END IF;
    ELSIF v_delta_fallback_required IS TRUE
          AND v_delta_is_normal_targeted_lifecycle IS TRUE
          AND UPPER(BTRIM(COALESCE(v_delta_fallback_reason, ''))) = 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED' THEN
      IF v_job_row.candidate_id IS NOT NULL
         AND v_source_change_seq IS NOT NULL THEN
        SELECT COALESCE(change_counter.seq, 0)
        INTO v_live_source_change_seq
        FROM public.app_change_counters AS change_counter
        WHERE change_counter.entity_key = 'pay_candidate:' || v_job_row.candidate_id::text;

        v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);
      END IF;

      v_delta_recovery_source_change_seq := GREATEST(COALESCE(v_live_source_change_seq, 0), COALESCE(v_source_change_seq, 0));
      v_delta_more_due := false;
      v_delta_fallback_required := false;
      v_delta_refresh_complete := true;
      v_delta_fallback_reason := 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED';
      v_delta_superseded_by_live_source_guard := COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0);

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'action', 'DIRECT_FALLBACK_SELF_REUSE_SUPPRESSED_NO_SOURCE_BUILD',
        'continuation_not_enqueued', true,
        'identical_cursor_self_reuse_suppressed', true,
        'delta_identical_cursor_self_reuse_no_source_build', true,
        'normal_targeted_lifecycle_delta', true,
        'successor_required', true,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
        'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
        'projection_run_id', v_delta_projection_run_id_text
      );

      v_result_json := jsonb_strip_nulls(
        COALESCE(v_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'fallback_required', false,
          'fallback_reason', v_delta_fallback_reason,
          'delta_refresh_complete', true,
          'more_due', false,
          'has_more', false,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
          'stop_reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRECT_FALLBACK_NO_SOURCE_BUILD_SUCCESSOR_REQUIRED',
          'next_recommended_action', 'DELTA_REFRESH_CHUNK'
        )
      );

      IF v_delta_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
        SET status = 'FAILED',
            fallback_required = false,
            fallback_reason = v_delta_fallback_reason,
            diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
              || jsonb_build_object(
                'identical_cursor_self_reuse_suppressed', true,
                'delta_identical_cursor_self_reuse_no_source_build', true,
                'direct_fallback_intercepted', true,
                'successor_required', true,
                'continuation_result', COALESCE(v_continuation_result, '{}'::jsonb),
                'source_change_seq', COALESCE(v_source_change_seq, 0),
                'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
                'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
                'terminalised_by', 'pay_workbench_complete_job',
                'terminalised_at_utc', v_now::text
              ),
            updated_at_utc = v_now,
            completed_at_utc = v_now
        WHERE projection_run_update.id = v_delta_projection_run_id_text::uuid
          AND projection_run_update.session_id = v_job_row.session_id
          AND projection_run_update.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(projection_run_update.status, ''))) IN ('RUNNING', 'FALLBACK_REQUIRED');
      END IF;

      v_delta_recovery_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DELTA_SUCCESSOR',
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'workbench_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', false,
          'force_broad_legacy', false,
          'fallback_from_delta', false,
          'fallback_reason', v_delta_fallback_reason,
          'projection_mode', 'DELTA',
          'projection_class', 'NORMAL_TIMESHEET',
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'phase', 'INIT_PREFLIGHT',
          'cursor_json', '{}'::jsonb,
          'source_build_required', false,
          'line_work_required', false,
          'delta_refresh_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
          'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
          'identical_cursor_self_reuse_suppressed', true,
          'delta_identical_cursor_self_reuse_no_source_build', true,
          'direct_fallback_intercepted', true,
          'successor_for_job_id', p_job_id::text,
          'previous_projection_run_id', v_delta_projection_run_id_text,
          'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
          'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'lifecycle_mutation_context', CASE
            WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
              OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
            THEN 'timesheet_unauthorise'
            ELSE 'timesheet_authorise'
          END,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'policy_x_dirtying_only', true,
          'economic_truth_mutation_allowed', false
        ))
      );

      v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

      IF v_delta_recovery_job_id_text = p_job_id::text THEN
        v_delta_recovery_job_id_text := NULL;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL THEN
        v_delta_recovery_enqueue_result := public.pay_workbench_dirty_event_enqueue(
          p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          p_scope_kind => 'CANDIDATE',
          p_scope_id => v_job_row.candidate_id::text,
          p_candidate_id => v_job_row.candidate_id,
          p_targeted_timesheet_ids => v_delta_recovery_targeted_timesheet_ids,
          p_linked_timesheet_ids => v_delta_recovery_linked_timesheet_ids,
          p_payload_json => jsonb_strip_nulls(jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'refresh_scope_kind', 'TARGETED_TIMESHEETS',
            'projection_mode', 'DELTA',
            'projection_class', 'NORMAL_TIMESHEET',
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'source_change_sequence', COALESCE(v_delta_recovery_source_change_seq, 0),
            'latest_source_change_seq', COALESCE(v_delta_recovery_source_change_seq, 0),
            'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
            'fallback_reason', v_delta_fallback_reason,
            'source_build_required', false,
            'line_work_required', false,
            'delta_refresh_required', true,
            'identical_cursor_self_reuse_suppressed', true,
            'delta_identical_cursor_self_reuse_no_source_build', true,
            'direct_fallback_intercepted', true,
            'authorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'),
            'unauthorise_boundary_changed', LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
            'lifecycle_mutation_context', CASE
              WHEN LOWER(BTRIM(COALESCE(v_result_json->>'unauthorise_boundary_changed', v_job_row.payload_json->>'unauthorise_boundary_changed', v_result_json->>'timesheet_unauthorise_boundary_changed', v_job_row.payload_json->>'timesheet_unauthorise_boundary_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                OR v_delta_lifecycle_context IN ('timesheet_unauthorise', 'unauthorise_timesheet')
                OR LOWER(COALESCE(v_result_json->>'reason', v_job_row.payload_json->>'reason_latest', v_job_row.payload_json->>'reason', '')) LIKE '%unauthorise%'
              THEN 'timesheet_unauthorise'
              ELSE 'timesheet_authorise'
            END,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true,
            'economic_truth_mutation_allowed', false
          )),
          p_reason => 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED_DIRTY_RECOVERY',
          p_priority => -1000,
          p_run_at_utc => v_now
        );

        v_delta_recovery_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_id', '')), '');

        IF v_delta_recovery_job_id_text IS NULL
           AND jsonb_typeof(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) = 'array' THEN
          SELECT NULLIF(BTRIM(COALESCE(coalesced_scope_result.value->>'job_id', '')), '')
          INTO v_delta_recovery_job_id_text
          FROM jsonb_array_elements(COALESCE(v_delta_recovery_enqueue_result->'coalesced_scope_results', '[]'::jsonb)) AS coalesced_scope_result(value)
          WHERE COALESCE(coalesced_scope_result.value->>'session_id', '') = v_job_row.session_id::text
            AND COALESCE(coalesced_scope_result.value->>'job_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          LIMIT 1;
        END IF;

        IF v_delta_recovery_job_id_text = p_job_id::text THEN
          v_delta_recovery_job_id_text := NULL;
        END IF;
      END IF;

      IF v_delta_recovery_job_id_text IS NULL
         OR v_delta_recovery_job_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_DELTA_SELF_REUSE_RECOVERY_JOB_ID_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
                  'projection_run_id', v_delta_projection_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'recovery_enqueue_result', COALESCE(v_delta_recovery_enqueue_result, '{}'::jsonb),
                  'message', 'Normal targeted lifecycle DELTA self-reuse fallback could not create or reuse a cron-claimable recovery job.'
                )::text;
      END IF;

      v_delta_recovery_job_id := v_delta_recovery_job_id_text::uuid;

      UPDATE public.banking_pay_workbench_session_scope AS delta_recovery_scope
      SET status = CASE
            WHEN UPPER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
             AND LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'PENDING'
            ELSE 'DELTA_REFRESH_PENDING'
          END,
          dirty = true,
          pending_job_id = v_delta_recovery_job_id,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_recovery_scope.session_id = v_job_row.session_id
        AND delta_recovery_scope.candidate_id = v_job_row.candidate_id;

      v_continuation_jobs := jsonb_build_array(v_continuation_result, v_delta_recovery_enqueue_result);
      v_continuation_count := 1;
      v_continuation_reused_count := CASE
        WHEN LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR LOWER(BTRIM(COALESCE(v_delta_recovery_enqueue_result->>'dirty_enqueue_coalesced_all_relevant_scopes', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        THEN 1
        ELSE 0
      END;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_fallback_required IS TRUE THEN
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => COALESCE(v_delta_fallback_reason, 'DELTA_REFRESH_FALLBACK_REQUIRED'),
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_job_row.session_id::text,
            'source_session_id', v_job_row.session_id::text,
            'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
            'session_version', COALESCE(v_session_row.version, 0),
            'session_signature', v_session_row.session_signature,
            'force_legacy', true,
            'fallback_from_delta', true,
            'fallback_reason', v_delta_fallback_reason,
            'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
            'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
            'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
            'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
            'projection_run_id', v_delta_projection_run_id_text,
            'projection_class', COALESCE(NULLIF(BTRIM(COALESCE(v_result_json->>'projection_class', '')), ''), NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'projection_class', '')), '')),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb),
            'refresh_scope_kind', CASE WHEN jsonb_array_length(COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END
          )
        )
      );
      v_delta_fallback_job_id_text := NULLIF(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'job_id', '')), '');
      UPDATE public.banking_pay_workbench_session_scope AS delta_fallback_scope
      SET status = 'SOURCE_BUILD_PENDING',
          dirty = true,
          pending_job_id = CASE WHEN v_delta_fallback_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN v_delta_fallback_job_id_text::uuid ELSE delta_fallback_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_fallback_scope.session_id = v_job_row.session_id
        AND delta_fallback_scope.candidate_id = v_job_row.candidate_id;
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := CASE WHEN v_delta_fallback_job_id_text IS NULL THEN 0 ELSE 1 END;
      v_continuation_reused_count := CASE WHEN LOWER(BTRIM(COALESCE(v_delta_fallback_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 1 ELSE 0 END;
      v_continuation_enqueued := v_delta_fallback_job_id_text IS NOT NULL;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE
          AND LOWER(BTRIM(COALESCE(v_result_json->>'superseded_by_newer_source_change_seq', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_superseded_scope
      SET dirty = true,
          pending_job_id = CASE WHEN delta_superseded_scope.pending_job_id = p_job_id THEN NULL::uuid ELSE delta_superseded_scope.pending_job_id END,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_superseded_scope.session_id = v_job_row.session_id
        AND delta_superseded_scope.candidate_id = v_job_row.candidate_id;

      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
    ELSIF v_delta_refresh_complete IS TRUE THEN
      UPDATE public.banking_pay_workbench_session_scope AS delta_ready_scope
      SET status = 'READY',
          seeded = true,
          dirty = false,
          pending_job_id = NULL::uuid,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE delta_ready_scope.session_id = v_job_row.session_id
        AND delta_ready_scope.candidate_id = v_job_row.candidate_id;

      -- Session counters/progress are recomputed authoritatively after the completing
      -- delta job is marked SUCCEEDED, so stored active_jobs never captures this job as stale.


      v_next_recommended_action := 'READ_PREVIEW_PAGE';
    ELSE
      v_delta_fallback_required := true;
      v_delta_fallback_reason := COALESCE(v_delta_fallback_reason, 'DELTA_RESULT_NOT_TERMINAL');
      v_delta_fallback_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => v_job_row.candidate_id,
        p_reason => v_delta_fallback_reason,
        p_actor_user_id => v_session_row.actor_user_id,
        p_payload_json => jsonb_build_object(
          'session_id', v_job_row.session_id::text,
          'source_session_id', v_job_row.session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'force_legacy', true,
          'fallback_from_delta', true,
          'fallback_reason', v_delta_fallback_reason,
          'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
          'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
          'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
          'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
          'projection_run_id', v_delta_projection_run_id_text,
          'source_build_required', true,
          'line_work_required', true,
          'targeted_timesheet_ids', COALESCE(v_delta_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_delta_linked_timesheet_ids_json, '[]'::jsonb)
        )
      );
      v_continuation_jobs := jsonb_build_array(v_delta_fallback_enqueue_result);
      v_continuation_count := 1;
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_delta_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'delta_completion_handled', true,
              'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
              'fallback_required', COALESCE(v_delta_fallback_required, false),
              'fallback_reason', v_delta_fallback_reason,
              'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
              'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
              'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
              'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
              'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
              'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
              'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
              'projection_run_id', v_delta_projection_run_id_text,
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_delta_job.id = p_job_id
    RETURNING update_delta_job.*
    INTO v_job_row;

    PERFORM public.pay_workbench_session_recompute_progress_counters(
      p_session_id => v_job_row.session_id,
      p_apply => true,
      p_reason => CASE
        WHEN COALESCE(v_delta_fallback_required, false) IS TRUE THEN 'DELTA_COMPLETE_JOB_FALLBACK_AUTHORITATIVE_RECOMPUTE'
        ELSE 'DELTA_COMPLETE_JOB_AUTHORITATIVE_RECOMPUTE'
      END,
      p_write_progress_json => true
    );

    PERFORM public.pay_workbench_projection_lifecycle_repair(
      p_session_id => v_job_row.session_id,
      p_candidate_id => v_job_row.candidate_id,
      p_safe_age_seconds => 300,
      p_limit => 50,
      p_reason => 'DELTA_COMPLETE_JOB_PROJECTION_LIFECYCLE_REPAIR'
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'stage_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_completion_handled', true,
      'delta_refresh_complete', COALESCE(v_delta_refresh_complete, false),
      'fallback_required', COALESCE(v_delta_fallback_required, false),
      'fallback_reason', v_delta_fallback_reason,
      'superseded_by_newer_source_change_seq', COALESCE(v_delta_superseded_by_live_source_guard, false),
      'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
      'superseded_projection_runs', COALESCE(v_delta_superseded_projection_runs, 0),
      'shadow_compare_status', NULLIF(v_delta_shadow_compare_status, ''),
      'shadow_compare_required', COALESCE(v_delta_shadow_compare_required, false),
      'shadow_compare_enforced', COALESCE(v_delta_shadow_compare_enforced, false),
      'shadow_compare_failed', COALESCE(v_delta_shadow_compare_failed, false),
      'projection_run_id', v_delta_projection_run_id_text,
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'next_recommended_action', v_next_recommended_action,
      'old_line_work_seed_enqueued', false,
      'old_line_work_process_enqueued', false,
      'old_preview_materialise_enqueued', false,
      'source_rows_written', COALESCE(v_delta_source_rows_written, 0),
      'line_rows_written', COALESCE(v_delta_line_rows_written, 0),
      'preview_rows_written', COALESCE(v_delta_preview_rows_written, 0),
      'rows_superseded', COALESCE(v_delta_rows_superseded, 0),
      'completed_at_utc', v_now::text
    );
  END IF;


  IF v_duplicate_completion IS NOT TRUE
     AND v_stage_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_clone_more_due := LOWER(BTRIM(COALESCE(v_result_json->>'more_due', v_result_json->>'has_more', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_clone_complete := LOWER(BTRIM(COALESCE(v_result_json->>'clone_rebase_complete', v_result_json->>'complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_clone_more_due IS NOT TRUE;
    v_clone_copied_candidate_count := CASE WHEN COALESCE(v_result_json->>'copied_candidate_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_candidate_count')::integer ELSE 0 END;
    v_clone_copied_preview_row_count := CASE WHEN COALESCE(v_result_json->>'copied_preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'copied_preview_row_count')::integer ELSE 0 END;
    v_clone_legacy_refresh_enqueued_count := CASE WHEN COALESCE(v_result_json->>'legacy_refresh_enqueued_count', '') ~ '^-?[0-9]+$' THEN (v_result_json->>'legacy_refresh_enqueued_count')::integer ELSE 0 END;
    v_clone_source_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'clone_from_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'source_session_id_text', '')), ''),
      NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'clone_from_session_id', '')), '')
    );
    IF v_clone_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_clone_source_session_id := v_clone_source_session_id_text::uuid;
    ELSE
      v_clone_source_session_id := NULL::uuid;
    END IF;

    PERFORM session_lock.id
    FROM public.banking_pay_workbench_sessions AS session_lock
    WHERE session_lock.id=ANY(array_remove(ARRAY[
      v_job_row.session_id,
      v_clone_source_session_id
    ]::uuid[],NULL::uuid))
    ORDER BY session_lock.id
    FOR UPDATE;

    SELECT target_session.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions AS target_session
    WHERE target_session.id=v_job_row.session_id;

    IF v_clone_more_due IS TRUE THEN
      INSERT INTO public.banking_pay_workbench_jobs AS clone_continuation (
        job_type,
        status,
        priority,
        run_at_utc,
        dedupe_key,
        snapshot_run_id,
        session_id,
        candidate_id,
        payload_json,
        created_at_utc,
        updated_at_utc
      )
      VALUES (
        'WORKBENCH_SESSION_CLONE_REBASE',
        'QUEUED',
        COALESCE(v_job_row.priority, 45),
        v_now,
        'WORKBENCH_SESSION_CLONE_REBASE:session:' || v_job_row.session_id::text || ':cursor:' || md5(COALESCE(v_next_cursor, '{}'::jsonb)::text),
        v_job_row.snapshot_run_id,
        v_job_row.session_id,
        v_job_row.candidate_id,
        jsonb_strip_nulls(
          COALESCE(v_job_row.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
            'cursor_json', COALESCE(v_next_cursor, '{}'::jsonb),
            'source_job_id', p_job_id::text,
            'continuation', true,
            'more_due_from_previous', true,
            'previous_result_summary', jsonb_build_object(
              'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
              'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
              'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0)
            )
          )
        ),
        v_now,
        v_now
      )
      ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
      DO UPDATE SET
        run_at_utc = LEAST(clone_continuation.run_at_utc, EXCLUDED.run_at_utc),
        priority = LEAST(clone_continuation.priority, EXCLUDED.priority),
        payload_json = COALESCE(clone_continuation.payload_json, '{}'::jsonb) || EXCLUDED.payload_json,
        updated_at_utc = v_now
      RETURNING clone_continuation.id
      INTO v_clone_continuation_job_id;

      v_continuation_result := jsonb_build_object(
        'ok', true,
        'job_id', v_clone_continuation_job_id::text,
        'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
        'continuation_enqueued', true
      );
      v_continuation_jobs := jsonb_build_array(v_continuation_result);
      v_continuation_count := 1;
      v_continuation_enqueued := true;
      v_next_recommended_action := 'CLONE_REBASE_CHUNK';
    ELSE
      v_next_recommended_action := CASE WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'WAIT_FOR_WORKER' ELSE 'READ_PREVIEW_PAGE' END;
    END IF;

    IF COALESCE(v_clone_more_due, false) IS NOT TRUE
       AND v_clone_source_session_id IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_clone_source_session_id IS DISTINCT FROM v_job_row.session_id THEN
      UPDATE public.banking_pay_workbench_sessions AS clone_source_session
      SET status = 'DISCARDED',
          discarded_at_utc = COALESCE(clone_source_session.discarded_at_utc, v_now),
          replacement_session_id = v_job_row.session_id,
          replacement_idempotency_key = COALESCE(
            clone_source_session.replacement_idempotency_key,
            'clone-rebase-complete:' || clone_source_session.id::text || ':replacement:' || v_job_row.session_id::text
          ),
          progress_state = 'DISCARDED',
          progress_json = jsonb_strip_nulls(
            COALESCE(clone_source_session.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'discard_reason', 'SUPERSEDED_BY_COMPLETED_CLONE_REBASE',
              'discarded_by_function', 'pay_workbench_complete_job',
              'replacement_session_id', v_job_row.session_id::text,
              'replacement_linked_at_utc', v_now::text,
              'clone_rebase_completed_by_job_id', p_job_id::text,
              'superseded_by_pay_date', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
              'superseded_by_week_ending_cutoff', CASE WHEN v_session_row.id IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END
            )
          ),
          progress_counter_version = COALESCE(clone_source_session.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE clone_source_session.id = v_clone_source_session_id
        AND clone_source_session.status = 'OPEN'
        AND clone_source_session.discarded_at_utc IS NULL
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.actor_user_id = v_session_row.actor_user_id
        )
        AND (
          v_session_row.id IS NULL
          OR clone_source_session.pay_date IS DISTINCT FROM v_session_row.pay_date
          OR clone_source_session.week_ending_cutoff IS DISTINCT FROM v_session_row.week_ending_cutoff
        );

      GET DIAGNOSTICS v_clone_source_session_retired_count = ROW_COUNT;
    END IF;

    UPDATE public.banking_pay_workbench_sessions AS clone_session_update
    SET progress_state = CASE
          WHEN v_clone_more_due IS TRUE THEN 'CLONE_REBASING'
          WHEN COALESCE(v_clone_legacy_refresh_enqueued_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
          WHEN COALESCE(clone_session_update.scope_pending_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_pending, 0) = 0
           AND COALESCE(clone_session_update.scope_failed_count, 0) = 0
           AND COALESCE(clone_session_update.line_units_failed, 0) = 0
          THEN 'READY'
          ELSE COALESCE(NULLIF(BTRIM(clone_session_update.progress_state), ''), 'REFRESHING_CANDIDATES')
        END,
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(clone_session_update.progress_json, '{}'::jsonb), true)
          || jsonb_build_object(
            'last_clone_rebase_job_id', p_job_id::text,
            'last_clone_rebase_completed_at_utc', v_now::text,
            'last_clone_rebase_more_due', COALESCE(v_clone_more_due, false),
            'last_clone_rebase_copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
            'last_clone_rebase_copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
            'last_clone_rebase_legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
            'last_clone_rebase_source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
            'last_clone_rebase_source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
            'next_recommended_action', v_next_recommended_action
          )
        ),
        progress_counter_version = COALESCE(clone_session_update.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE clone_session_update.id = v_job_row.session_id;

    UPDATE public.banking_pay_workbench_jobs AS update_clone_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_clone_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'clone_rebase_completion_handled', true,
              'clone_rebase_complete', COALESCE(v_clone_complete, false),
              'more_due', COALESCE(v_clone_more_due, false),
              'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
              'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
              'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_clone_job.id = p_job_id
    RETURNING update_clone_job.*
    INTO v_job_row;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'stage_job_type', 'WORKBENCH_SESSION_CLONE_REBASE',
      'clone_rebase_completion_handled', true,
      'clone_rebase_complete', COALESCE(v_clone_complete, false),
      'more_due', COALESCE(v_clone_more_due, false),
      'continuation_enqueued', COALESCE(v_continuation_enqueued, false),
      'continuation_count', COALESCE(v_continuation_count, 0),
      'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
      'copied_candidate_count', COALESCE(v_clone_copied_candidate_count, 0),
      'copied_preview_row_count', COALESCE(v_clone_copied_preview_row_count, 0),
      'legacy_refresh_enqueued_count', COALESCE(v_clone_legacy_refresh_enqueued_count, 0),
      'source_session_id', CASE WHEN v_clone_source_session_id IS NULL THEN NULL ELSE v_clone_source_session_id::text END,
      'source_session_retired_count', COALESCE(v_clone_source_session_retired_count, 0),
      'source_session_retired', COALESCE(v_clone_source_session_retired_count, 0) > 0,
      'next_recommended_action', v_next_recommended_action,
      'completed_at_utc', v_now::text
    );
  END IF;

  IF v_duplicate_completion IS NOT TRUE THEN
    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_has_more IS NOT TRUE THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
        WHERE line_work_pending.session_id = v_job_row.session_id
          AND line_work_pending.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) = 'PENDING'
      )
      INTO v_pending_line_work_exists;

      SELECT EXISTS(
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
        WHERE line_work_ready.session_id = v_job_row.session_id
          AND line_work_ready.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) = 'READY'
      )
      INTO v_ready_line_work_exists;
    END IF;

    IF v_stage_job_type IN (
         'WORKBENCH_CANDIDATE_SOURCE_BUILD',
         'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
         'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
         'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
       )
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_before_continuation.status, 'PENDING')))
      INTO v_scope_status_before_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_before_continuation
      WHERE scope_before_continuation.session_id = v_job_row.session_id
        AND scope_before_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;
    END IF;

    IF v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
       AND v_has_more IS TRUE
       AND v_next_cursor IS NOT NULL THEN
      v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
        p_session_id => v_job_row.session_id,
        p_candidate_id => NULL::uuid,
        p_job_type => 'WORKBENCH_SESSION_SCOPE_SEED',
        p_cursor_json => v_next_cursor,
        p_source_job_id => p_job_id,
        p_result_json => v_result_json,
        p_actor_user_id => v_session_row.actor_user_id,
        p_reason => 'SCOPE_SEED_CURSOR_CONTINUATION',
        p_priority => 40,
        p_limit => v_payload_limit
      );
      v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
      v_next_recommended_action := 'SEED_SCOPE_CHUNK';
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_SOURCE_BUILD_CURSOR_MISSING',
                  'job_id', p_job_id::text,
                  'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
                  'candidate_id', v_job_row.candidate_id::text,
                  'job_type', v_stage_job_type,
                  'source_build_run_id', v_source_build_run_id_text,
                  'source_change_seq', v_source_change_seq,
                  'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD returned has_more=true without a next cursor; refusing to start line seed early.'
                )::text;
      ELSIF v_has_more IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_CURSOR_CONTINUATION',
          p_priority => 44,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
      ELSIF v_job_row.economic_build_id IS NOT NULL
            AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
            AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
            AND v_current_source_row_count_authoritative
            AND COALESCE(v_current_source_row_count, 0) > 0 THEN
        -- Bounded SOURCE_PUBLISH has already produced the complete canonical
        -- CURRENT set. The common terminal path below owns public scope and
        -- progress reconciliation; it must not enter the legacy line-work
        -- pipeline or carry private build identity into a legacy job.
        v_bounded_terminal_refresh_scope_kind := UPPER(BTRIM(COALESCE(
          NULLIF(v_result_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''),
          'CANDIDATE_FULL_LIVE'
        )));

        DROP TABLE IF EXISTS pg_temp._bpay_complete_job_bounded_terminal_timesheets;
        CREATE TEMP TABLE _bpay_complete_job_bounded_terminal_timesheets ON COMMIT DROP AS
        WITH raw_timesheet_ids(timesheet_id_text) AS (
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION
          SELECT current_source.timesheet_id::text
          FROM public.banking_pay_workbench_candidate_source_lines AS current_source
          WHERE current_source.session_id = v_job_row.session_id
            AND current_source.candidate_id = v_job_row.candidate_id
            AND current_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
            AND current_source.source_build_run_id = v_source_build_run_id_text::uuid
            AND current_source.source_change_seq = v_source_change_seq
            AND current_source.status = 'CURRENT'
            AND current_source.timesheet_id IS NOT NULL
          UNION
          SELECT bounded_scope.timesheet_id::text
          FROM private.banking_pay_workbench_economic_build_scope AS bounded_scope
          WHERE bounded_scope.build_id = v_job_row.economic_build_id
        )
        SELECT DISTINCT LOWER(BTRIM(timesheet_id_text))::uuid AS timesheet_id
        FROM raw_timesheet_ids
        WHERE NULLIF(BTRIM(timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

        SELECT COUNT(*)::integer
        INTO v_bounded_terminal_targeted_timesheet_count
        FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets;

        IF v_bounded_terminal_refresh_scope_kind = 'TARGETED_TIMESHEETS'
           AND COALESCE(v_bounded_terminal_targeted_timesheet_count, 0) = 0 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_BOUNDED_TERMINAL_TARGET_SCOPE_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_BOUNDED_TERMINAL_TARGET_SCOPE_REQUIRED',
                    'session_id', v_job_row.session_id::text,
                    'candidate_id', v_job_row.candidate_id::text,
                    'job_id', p_job_id::text,
                    'source_build_run_id', v_source_build_run_id_text,
                    'source_change_seq', v_source_change_seq
                  )::text;
        END IF;

        UPDATE public.banking_pay_workbench_candidate_source_lines AS bounded_previous_source
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(bounded_previous_source.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'bounded_source_publish_superseded', true,
                'bounded_source_publish_job_id', p_job_id::text,
                'bounded_source_publish_build_id', v_job_row.economic_build_id::text,
                'bounded_source_publish_run_id', v_source_build_run_id_text,
                'bounded_source_publish_change_seq', v_source_change_seq,
                'bounded_source_publish_at_utc', v_now::text,
                'bounded_source_publish_reason', 'NEWER_CANONICAL_SOURCE_ALREADY_PUBLISHED'
              )
            ),
            updated_at_utc = v_now
        WHERE bounded_previous_source.session_id = v_job_row.session_id
          AND bounded_previous_source.candidate_id = v_job_row.candidate_id
          AND bounded_previous_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
          AND UPPER(BTRIM(COALESCE(bounded_previous_source.status, ''))) IN (
            'CURRENT', 'DIRTY', 'ERROR', 'PENDING', 'READY'
          )
          AND bounded_previous_source.source_change_seq <= v_source_change_seq
          AND NOT (
            bounded_previous_source.status = 'CURRENT'
            AND bounded_previous_source.source_build_run_id = v_source_build_run_id_text::uuid
            AND bounded_previous_source.source_change_seq = v_source_change_seq
          )
          AND (
            v_bounded_terminal_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR bounded_previous_source.timesheet_id IN (
              SELECT bounded_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets AS bounded_timesheets
            )
          );
        GET DIAGNOSTICS v_bounded_terminal_source_rows_retired_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_candidate_line_work AS bounded_legacy_line_work
        SET status = 'SKIPPED',
            work_payload_json = jsonb_strip_nulls(
              COALESCE(bounded_legacy_line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'bounded_source_publish_superseded', true,
                'bounded_source_publish_job_id', p_job_id::text,
                'bounded_source_publish_build_id', v_job_row.economic_build_id::text,
                'bounded_source_publish_at_utc', v_now::text,
                'bounded_source_publish_reason', 'CANONICAL_SOURCE_ALREADY_PUBLISHED'
              )
            ),
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE bounded_legacy_line_work.session_id = v_job_row.session_id
          AND bounded_legacy_line_work.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(bounded_legacy_line_work.status, ''))) IN (
            'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED', 'DIRTY', 'READY'
          )
          AND (
            v_bounded_terminal_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR bounded_legacy_line_work.timesheet_id IN (
              SELECT bounded_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_bounded_terminal_timesheets AS bounded_timesheets
            )
          );
        GET DIAGNOSTICS v_bounded_terminal_line_work_retired_count = ROW_COUNT;

        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      ELSIF (
        (
          v_current_source_row_count_authoritative
          AND COALESCE(v_current_source_row_count, 0) > 0
        )
        OR (
          v_current_source_row_count_authoritative IS NOT TRUE
          AND (
            COALESCE(v_current_source_row_count, 0) > 0
            OR COALESCE(v_source_rows_written, 0) > 0
          )
        )
      ) THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_source_seed_cursor_json,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'SOURCE_BUILD_COMPLETE_SEED_LINE_WORK',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSE
        DROP TABLE IF EXISTS pg_temp._bpay_complete_job_source_empty_timesheets;
        CREATE TEMP TABLE _bpay_complete_job_source_empty_timesheets ON COMMIT DROP AS
        WITH raw_timesheet_ids(timesheet_id_text) AS (
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_result_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_result_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,targeted_timesheet_ids}' ELSE '[]'::jsonb END)
          UNION ALL
          SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_job_row.payload_json #> '{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json #> '{source_build,linked_timesheet_ids}' ELSE '[]'::jsonb END)
        )
        SELECT DISTINCT LOWER(BTRIM(timesheet_id_text))::uuid AS timesheet_id
        FROM raw_timesheet_ids
        WHERE NULLIF(BTRIM(timesheet_id_text), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

        SELECT COUNT(*)::integer
        INTO v_source_empty_targeted_timesheet_count
        FROM pg_temp._bpay_complete_job_source_empty_timesheets;

        v_delta_refresh_scope_kind := UPPER(BTRIM(COALESCE(
          NULLIF(v_result_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json->>'refresh_scope_kind', ''),
          NULLIF(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''),
          'CANDIDATE_FULL_LIVE'
        )));

        IF v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS'
           AND COALESCE(v_source_empty_targeted_timesheet_count, 0) = 0 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_EMPTY_TARGET_SCOPE_REQUIRED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_SOURCE_EMPTY_TARGET_SCOPE_REQUIRED',
                    'session_id', v_job_row.session_id::text,
                    'candidate_id', v_job_row.candidate_id::text,
                    'job_id', p_job_id::text,
                    'refresh_scope_kind', v_delta_refresh_scope_kind
                  )::text;
        END IF;

        -- A26 (PRE-EXISTING SB02 fix, AC-F1): a source build that stopped at the reconciliation-scale envelope
        -- (stage_status BLOCKED_UNVALIDATED_RECONCILIATION_SCALE) has published NO rows because it was never
        -- prepared, not because the Candidate has nothing to pay. It previously fell through to this
        -- zero-rows branch and was marked SOURCE_EMPTY, so the Candidate silently vanished (READY_EMPTY, no
        -- blocker). Keep the same retirement of stale rows below (nothing unprepared may be paid), but record a
        -- visible failed scope with a coded reason instead. SOURCE_BUILD_ERROR is an existing failed status that
        -- every progress/modal reader already surfaces. No amount or economic logic is involved.
        UPDATE public.banking_pay_workbench_session_scope AS source_empty_scope
        SET status = CASE
              WHEN UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'BLOCKED_UNVALIDATED_RECONCILIATION_SCALE' THEN 'SOURCE_BUILD_ERROR'
              WHEN v_delta_refresh_scope_kind = 'TARGETED_TIMESHEETS' THEN 'READY'
              ELSE 'SOURCE_EMPTY'
            END,
            seeded = true,
            dirty = false,
            pending_job_id = NULL::uuid,
            error_json = CASE
              WHEN UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'BLOCKED_UNVALIDATED_RECONCILIATION_SCALE' THEN jsonb_build_object(
                'code', 'BLOCKED_UNVALIDATED_RECONCILIATION_SCALE',
                'reason', COALESCE((SELECT scale_build.attestation_json #>> '{reconciliation_scale_block,reason}'
                  FROM private.banking_pay_workbench_economic_builds AS scale_build
                  WHERE scale_build.id = v_job_row.economic_build_id), 'UNVALIDATED_RECONCILIATION_SCALE'),
                'message', 'Banking Pay cannot yet prepare this many Timesheets for one Candidate at once. None of this Candidate''s payments are shown or can be included in a Draft until it is prepared.',
                'relevant_timesheet_count', v_result_json #> '{complexity_vector,relevant_timesheet_count}',
                'relevant_timesheet_limit', (SELECT scale_build.envelope_snapshot_json -> 'relevant_timesheet_count'
                  FROM private.banking_pay_workbench_economic_builds AS scale_build
                  WHERE scale_build.id = v_job_row.economic_build_id),
                'economic_build_id', v_job_row.economic_build_id,
                'job_id', p_job_id,
                'recorded_at_utc', v_now::text
              )
              ELSE NULL::jsonb
            END,
            updated_at_utc = v_now
        WHERE source_empty_scope.session_id = v_job_row.session_id
          AND source_empty_scope.candidate_id = v_job_row.candidate_id;

        UPDATE public.banking_pay_workbench_candidate_source_lines AS source_empty_source_line
        SET status = 'SUPERSEDED',
            source_row_json = jsonb_strip_nulls(
              COALESCE(source_empty_source_line.source_row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_source_line.session_id = v_job_row.session_id
          AND source_empty_source_line.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_source_line.status, ''))) IN ('CURRENT', 'READY', 'PENDING', 'DIRTY')
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_source_line.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_source_row_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_candidate_line_work AS source_empty_line_work
        SET status = 'SKIPPED',
            work_payload_json = jsonb_strip_nulls(
              COALESCE(source_empty_line_work.work_payload_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
              )
            ),
            error_json = NULL::jsonb,
            updated_at_utc = v_now
        WHERE source_empty_line_work.session_id = v_job_row.session_id
          AND source_empty_line_work.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_line_work.status, ''))) IN (
            'PENDING',
            'PROCESSING',
            'RUNNING',
            'QUEUED',
            'DIRTY',
            'READY',
            'MATERIALISED',
            'MATERIALIZED'
          )
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_line_work.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_line_work_count = ROW_COUNT;

        UPDATE public.banking_pay_workbench_preview_rows AS source_empty_preview_row
        SET status = 'SUPERSEDED',
            selected = false,
            selection_state = 'SUPERSEDED',
            row_json = jsonb_strip_nulls(
              COALESCE(source_empty_preview_row.row_json, '{}'::jsonb)
              || jsonb_build_object(
                'source_empty_cleanup', true,
                'source_empty_cleanup_job_id', p_job_id::text,
                'source_empty_cleanup_at_utc', v_now::text,
                'source_empty_cleanup_reason', 'TARGETED_SOURCE_BUILD_RETURNED_ZERO_CURRENT_SOURCE_ROWS',
                'not_payable_reason', 'SOURCE_EMPTY_AFTER_UNAUTHORISE_OR_SOURCE_CHANGE'
              )
            ),
            updated_at_utc = v_now
        WHERE source_empty_preview_row.session_id = v_job_row.session_id
          AND source_empty_preview_row.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(source_empty_preview_row.status, ''))) IN ('READY', 'DIRTY', 'PENDING')
          AND (
            v_delta_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            OR source_empty_preview_row.timesheet_id IN (
              SELECT empty_timesheets.timesheet_id
              FROM pg_temp._bpay_complete_job_source_empty_timesheets AS empty_timesheets
            )
          );
        GET DIAGNOSTICS v_source_empty_cleanup_preview_row_count = ROW_COUNT;

        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS source_empty_session_lock
          WHERE source_empty_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(source_empty_session_lock.status, ''))) = 'OPEN'
            AND source_empty_session_lock.discarded_at_utc IS NULL
            AND COALESCE(source_empty_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND source_empty_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND source_empty_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS source_empty_session
            SET scope_ready_count = COALESCE(source_scope_counts.ready_count, 0),
                scope_pending_count = COALESCE(source_scope_counts.pending_count, 0),
                scope_failed_count = COALESCE(source_scope_counts.failed_count, 0),
                progress_state = CASE
                  WHEN COALESCE(source_scope_counts.pending_count, 0) > 0 THEN 'REFRESHING_CANDIDATES'
                  WHEN COALESCE(source_scope_counts.failed_count, 0) > 0 THEN 'ERROR'
                  ELSE source_empty_session.progress_state
                END,
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(source_empty_session.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_source_build_empty_candidate_id', v_job_row.candidate_id::text,
                    'last_source_build_empty_at_utc', v_now::text,
                    'last_source_build_empty_job_id', p_job_id::text,
                    'next_recommended_action', 'READ_PREVIEW_PAGE',
                    'terminal_readiness_deferred', true,
                    'terminal_readiness_deferred_to', 'pay_workbench_complete_job',
                    'source_empty_session_progress_locking', 'NOWAIT',
                    'source_empty_session_progress_update_applied', true,
                    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
                    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
                    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
                    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0)
                  ),
                progress_counter_version = COALESCE(source_empty_session.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            FROM (
              SELECT
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer AS ready_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS failed_count,
                COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_recount.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer AS pending_count
              FROM public.banking_pay_workbench_session_scope AS scope_recount
              WHERE scope_recount.session_id = v_job_row.session_id
            ) AS source_scope_counts
            WHERE source_empty_session.id = v_job_row.session_id
            RETURNING source_empty_session.*
            INTO v_session_row;
          ELSE
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_source_empty_session_progress_deferred := true;
            v_source_empty_session_progress_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;

        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_CURSOR_CONTINUATION',
          p_priority => 45,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      ELSIF COALESCE(v_seeded_count, 0) > 0 OR v_pending_line_work_exists IS TRUE THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_SEED_COMPLETE_PROCESS_PENDING',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_PROCESS_CURSOR_CONTINUATION',
          p_priority => 42,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      END IF;

      IF v_has_more IS NOT TRUE
         AND v_pending_line_work_exists IS NOT TRUE
         AND (COALESCE(v_ready_count_delta, 0) > 0 OR v_ready_line_work_exists IS TRUE) THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => NULL::jsonb,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'LINE_WORK_READY_MATERIALISE_PREVIEW_ROWS',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := COALESCE(v_next_recommended_action, 'MATERIALISE_PREVIEW_ROWS_CHUNK');
      END IF;
    ELSIF v_stage_job_type = 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
          AND v_job_row.candidate_id IS NOT NULL THEN
      IF v_has_more IS TRUE AND v_next_cursor IS NOT NULL THEN
        v_continuation_result := public.pay_workbench_enqueue_stage_continuation(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_job_type => 'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
          p_cursor_json => v_next_cursor,
          p_source_job_id => p_job_id,
          p_result_json => v_result_json,
          p_actor_user_id => v_session_row.actor_user_id,
          p_reason => 'PREVIEW_ROWS_MATERIALISE_CURSOR_CONTINUATION',
          p_priority => 41,
          p_limit => v_payload_limit
        );
        v_continuation_jobs := v_continuation_jobs || jsonb_build_array(v_continuation_result);
        v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      ELSIF COALESCE(v_materialised_count, 0) > 0 THEN
        v_next_recommended_action := 'READ_PREVIEW_PAGE';
      END IF;
    END IF;

    v_continuation_count := jsonb_array_length(COALESCE(v_continuation_jobs, '[]'::jsonb));
    v_continuation_enqueued := v_continuation_count > 0;

    SELECT COUNT(*)::integer
    INTO v_continuation_reused_count
    FROM jsonb_array_elements(COALESCE(v_continuation_jobs, '[]'::jsonb)) AS continuation_items(continuation_item)
    WHERE LOWER(BTRIM(COALESCE(continuation_items.continuation_item->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    IF COALESCE(v_continuation_count, 0) > 0
       AND v_scope_status_before_continuation IS NOT NULL
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL THEN
      SELECT UPPER(BTRIM(COALESCE(scope_after_continuation.status, 'PENDING')))
      INTO v_scope_status_after_continuation
      FROM public.banking_pay_workbench_session_scope AS scope_after_continuation
      WHERE scope_after_continuation.session_id = v_job_row.session_id
        AND scope_after_continuation.candidate_id = v_job_row.candidate_id
      FOR UPDATE;

      v_scope_bucket_before_continuation := CASE
        WHEN v_scope_status_before_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_before_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_bucket_after_continuation := CASE
        WHEN v_scope_status_after_continuation IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY') THEN 'READY'
        WHEN v_scope_status_after_continuation IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR') THEN 'FAILED'
        ELSE 'PENDING'
      END;

      v_scope_continuation_pending_delta := CASE WHEN v_scope_bucket_after_continuation = 'PENDING' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'PENDING' THEN 1 ELSE 0 END;
      v_scope_continuation_ready_delta := CASE WHEN v_scope_bucket_after_continuation = 'READY' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'READY' THEN 1 ELSE 0 END;
      v_scope_continuation_failed_delta := CASE WHEN v_scope_bucket_after_continuation = 'FAILED' THEN 1 ELSE 0 END
        - CASE WHEN v_scope_bucket_before_continuation = 'FAILED' THEN 1 ELSE 0 END;

      IF COALESCE(v_scope_continuation_pending_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_ready_delta, 0) <> 0
         OR COALESCE(v_scope_continuation_failed_delta, 0) <> 0 THEN
        BEGIN
          PERFORM 1
          FROM public.banking_pay_workbench_sessions AS continuation_session_lock
          WHERE continuation_session_lock.id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(continuation_session_lock.status, ''))) = 'OPEN'
            AND continuation_session_lock.discarded_at_utc IS NULL
            AND COALESCE(continuation_session_lock.version, 1) = COALESCE(v_session_row.version, 1)
            AND continuation_session_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
            AND continuation_session_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
          FOR UPDATE NOWAIT;

          IF FOUND THEN
            UPDATE public.banking_pay_workbench_sessions AS continuation_session_update
            SET scope_pending_count = GREATEST(
                  COALESCE(continuation_session_update.scope_pending_count, 0)
                    + COALESCE(v_scope_continuation_pending_delta, 0),
                  0
                ),
                scope_ready_count = GREATEST(
                  COALESCE(continuation_session_update.scope_ready_count, 0)
                    + COALESCE(v_scope_continuation_ready_delta, 0),
                  0
                ),
                scope_failed_count = GREATEST(
                  COALESCE(continuation_session_update.scope_failed_count, 0)
                    + COALESCE(v_scope_continuation_failed_delta, 0),
                  0
                ),
                progress_json = public.pay_workbench_session_compact_progress_json(COALESCE(continuation_session_update.progress_json, '{}'::jsonb), true)
                  || jsonb_build_object(
                    'last_continuation_scope_old_status', v_scope_status_before_continuation,
                    'last_continuation_scope_new_status', v_scope_status_after_continuation,
                    'last_continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
                    'last_continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
                    'last_continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
                    'last_continuation_scope_counter_adjusted_at_utc', v_now::text,
                    'last_continuation_scope_counter_locking', 'NOWAIT',
                    'last_continuation_scope_counter_lock_skipped', false
                  ),
                progress_counter_version = COALESCE(continuation_session_update.progress_counter_version, 0) + 1,
                progress_updated_at_utc = v_now,
                updated_at_utc = v_now
            WHERE continuation_session_update.id = v_job_row.session_id;

            v_scope_continuation_counter_adjusted := true;
          ELSE
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
          END IF;
        EXCEPTION
          WHEN lock_not_available THEN
            v_continuation_scope_counter_deferred := true;
            v_continuation_scope_counter_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
        END;
      END IF;
    END IF;

    -- Bounded terminal ownership is not complete until the certified CURRENT
    -- source has been reconciled and published into the one public preview
    -- read model.  All work remains in this completion transaction.
    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_job_row.economic_build_id IS NOT NULL
       AND COALESCE(v_has_more, false) IS NOT TRUE
       AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
       AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
       AND v_current_source_row_count_authoritative IS TRUE
       AND v_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND v_source_change_seq IS NOT NULL THEN
      IF COALESCE(v_current_source_row_count, 0) > 0 THEN
        v_source_reconciliation_json := public.pay_workbench_reconcile_successful_source_build(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => COALESCE(v_result_session_version, v_session_row.version),
          p_success_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), ''),
            'CANDIDATE_FULL_LIVE'
          ),
          p_targeted_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_linked_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_recompute_session_progress => false
        );

        v_source_reconciliation_deferred := LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'deferred', 'false')))
          IN ('true', 't', '1', 'yes', 'y', 'on');
        v_source_reconciliation_applied := v_source_reconciliation_deferred IS NOT TRUE
          AND LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'ok', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off');

        IF v_source_reconciliation_applied IS NOT TRUE THEN
          RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
                    'reason', 'SOURCE_RECONCILIATION_NOT_COMPLETE'
                  )::text;
        END IF;
      ELSE
        v_source_reconciliation_applied := true;
        v_source_reconciliation_json := jsonb_build_object(
          'ok', true,
          'skipped', true,
          'reason', 'POSITIVELY_CERTIFIED_EMPTY_SOURCE',
          'progress_recomputed', false
        );
      END IF;

      v_certified_targeted_timesheet_ids := CASE
        WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array'
          THEN v_result_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array'
          THEN v_job_row.payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array'
          THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
        ELSE COALESCE((
          SELECT jsonb_agg(DISTINCT build_scope.timesheet_id::text ORDER BY build_scope.timesheet_id::text)
          FROM private.banking_pay_workbench_economic_build_scope AS build_scope
          WHERE build_scope.build_id = v_job_row.economic_build_id
            AND build_scope.timesheet_id IS NOT NULL
        ), '[]'::jsonb)
      END;
      v_certified_linked_timesheet_ids := CASE
        WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array'
          THEN v_result_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array'
          THEN v_job_row.payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array'
          THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
        ELSE '[]'::jsonb
      END;

      v_certified_publication_json := private.pay_workbench_publish_certified_source_preview_v1(
        p_session_id => v_job_row.session_id,
        p_candidate_id => v_job_row.candidate_id,
        p_economic_build_id => v_job_row.economic_build_id,
        p_source_build_run_id => v_source_build_run_id_text::uuid,
        p_source_change_seq => v_source_change_seq,
        p_session_version => COALESCE(v_result_session_version, v_session_row.version),
        p_completion_job_id => p_job_id,
        p_refresh_scope_kind => COALESCE(
          NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
          NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
          NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), ''),
          'CANDIDATE_FULL_LIVE'
        ),
        p_targeted_timesheet_ids => v_certified_targeted_timesheet_ids,
        p_linked_timesheet_ids => v_certified_linked_timesheet_ids,
        p_publication_options_json => CASE
          WHEN v_semantic_publication_v3_enabled THEN jsonb_build_object(
            'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind', 'INITIAL_COMPLETION',
            'contract_version', 3,
            'final_state', CASE WHEN COALESCE(v_current_source_row_count,0)=0 THEN 'SOURCE_EMPTY' ELSE 'READY' END,
            'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2'
          )
          ELSE jsonb_build_object(
            'authority_kind', 'BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind', 'INITIAL_COMPLETION',
            'contract_version', 1
          )
        END
      );
      v_certified_publication_applied := COALESCE((v_certified_publication_json->>'parity_complete')::boolean, false);

      IF v_certified_publication_applied IS NOT TRUE THEN
        RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED' USING ERRCODE = 'P0001';
      END IF;

      UPDATE public.banking_pay_workbench_session_scope AS certified_scope
      SET status = CASE
            WHEN COALESCE((v_certified_publication_json->>'source_row_count')::integer, 0) = 0 THEN 'SOURCE_EMPTY'
            ELSE 'MATERIALISED'
          END,
          seeded = true,
          dirty = false,
          pending_job_id = NULL::uuid,
          error_json = NULL::jsonb,
          updated_at_utc = v_now
      WHERE certified_scope.session_id = v_job_row.session_id
        AND certified_scope.candidate_id = v_job_row.candidate_id;
      GET DIAGNOSTICS v_bounded_terminal_scope_finalised_count = ROW_COUNT;

      v_finalisation_progress_json := public.pay_workbench_session_recompute_progress_counters(
        v_job_row.session_id,
        true,
        'CERTIFIED_SOURCE_PREVIEW_TERMINAL_COMPLETION',
        true
      );
      v_next_recommended_action := 'READ_PREVIEW_PAGE';
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET status = 'SUCCEEDED',
        updated_at_utc = v_now,
        completed_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL,
        payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('result_json', public.pay_workbench_compact_job_result_json(v_result_json))
          || jsonb_build_object(
            'completion_json', jsonb_build_object(
              'continuation_enqueued', v_continuation_enqueued,
              'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
              'continuation_count', COALESCE(v_continuation_count, 0),
              'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
              'next_recommended_action', v_next_recommended_action,
              'completed_at_utc', v_now::text
            )
          )
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    v_completed_at_utc := v_now;

    IF v_stage_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_source_reconciliation_applied IS NOT TRUE
       AND v_job_row.session_id IS NOT NULL
       AND v_job_row.candidate_id IS NOT NULL
       AND v_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND v_source_change_seq IS NOT NULL
       AND COALESCE(v_has_more, false) IS NOT TRUE
       AND (COALESCE(v_source_rows_written, 0) > 0 OR COALESCE(v_current_source_row_count, 0) > 0) THEN
      BEGIN
        v_source_reconciliation_json := public.pay_workbench_reconcile_successful_source_build(
          p_session_id => v_job_row.session_id,
          p_candidate_id => v_job_row.candidate_id,
          p_source_build_run_id => v_source_build_run_id_text::uuid,
          p_source_change_seq => v_source_change_seq,
          p_session_version => COALESCE(v_result_session_version, v_session_row.version),
          p_success_job_id => p_job_id,
          p_refresh_scope_kind => COALESCE(
            NULLIF(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json->>'refresh_scope_kind', '')), ''),
            NULLIF(BTRIM(COALESCE(v_job_row.payload_json#>>'{source_build,refresh_scope_kind}', '')), '')
          ),
          p_targeted_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'targeted_timesheet_ids') = 'array' THEN v_result_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN v_job_row.payload_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_linked_timesheet_ids => CASE
            WHEN jsonb_typeof(v_result_json->'linked_timesheet_ids') = 'array' THEN v_result_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json->'linked_timesheet_ids') = 'array' THEN v_job_row.payload_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_job_row.payload_json#>'{source_build,linked_timesheet_ids}'
            ELSE '[]'::jsonb
          END,
          p_recompute_session_progress => true
        );

        v_source_reconciliation_deferred := LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'deferred', 'false')))
          IN ('true', 't', '1', 'yes', 'y', 'on');
        v_source_reconciliation_deferred_reason := CASE
          WHEN v_source_reconciliation_deferred THEN NULLIF(BTRIM(COALESCE(v_source_reconciliation_json->>'reason', '')), '')
          ELSE NULL::text
        END;
        v_source_reconciliation_applied := v_source_reconciliation_deferred IS NOT TRUE
          AND LOWER(BTRIM(COALESCE(v_source_reconciliation_json->>'ok', 'true')))
            NOT IN ('false', 'f', '0', 'no', 'n', 'off');

        IF v_source_reconciliation_applied
           AND v_job_row.economic_build_id IS NOT NULL
           AND UPPER(BTRIM(COALESCE(v_result_json->>'private_stage', ''))) = 'COMPLETE'
           AND UPPER(BTRIM(COALESCE(v_result_json->>'stage_status', ''))) = 'COMPLETE'
           AND v_current_source_row_count_authoritative
           AND COALESCE(v_current_source_row_count, 0) > 0
           AND COALESCE(NULLIF(v_source_reconciliation_json->>'scope_rows_repaired', '')::integer, 0) > 0 THEN
          -- The bounded path publishes its canonical CURRENT set itself. Once
          -- that source is reconciled, no legacy line-work stage remains to
          -- move SOURCE_READY to a public terminal scope state.
          UPDATE public.banking_pay_workbench_session_scope AS bounded_terminal_scope
          SET status = 'MATERIALISED',
              seeded = true,
              dirty = false,
              pending_job_id = NULL::uuid,
              error_json = NULL::jsonb,
              updated_at_utc = v_now
          WHERE bounded_terminal_scope.session_id = v_job_row.session_id
            AND bounded_terminal_scope.candidate_id = v_job_row.candidate_id
            AND NOT EXISTS (
              SELECT 1
              FROM public.banking_pay_workbench_jobs AS newer_active_source_job
              WHERE newer_active_source_job.session_id = v_job_row.session_id
                AND newer_active_source_job.candidate_id = v_job_row.candidate_id
                AND newer_active_source_job.id <> p_job_id
                AND UPPER(BTRIM(COALESCE(newer_active_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
                AND UPPER(BTRIM(COALESCE(newer_active_source_job.job_type, ''))) IN (
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                  'CANDIDATE_SOURCE_BUILD',
                  'CANDIDATE_SOURCE_BUILD_CHUNK',
                  'SOURCE_BUILD',
                  'SOURCE_BUILD_PAGE'
                )
            )
            AND EXISTS (
              SELECT 1
              FROM public.banking_pay_workbench_candidate_source_lines AS bounded_current_source
              WHERE bounded_current_source.session_id = v_job_row.session_id
                AND bounded_current_source.candidate_id = v_job_row.candidate_id
                AND bounded_current_source.session_version = COALESCE(v_result_session_version, v_session_row.version)
                AND bounded_current_source.source_build_run_id = v_source_build_run_id_text::uuid
                AND bounded_current_source.source_change_seq = v_source_change_seq
                AND bounded_current_source.status = 'CURRENT'
            );
          GET DIAGNOSTICS v_bounded_terminal_scope_finalised_count = ROW_COUNT;
        END IF;
      EXCEPTION
        WHEN lock_not_available THEN
          v_source_reconciliation_applied := false;
          v_source_reconciliation_deferred := true;
          v_source_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
          v_source_reconciliation_json := jsonb_build_object(
            'ok', true,
            'deferred', true,
            'reason', 'SESSION_LOCK_NOT_AVAILABLE',
            'session_id', v_job_row.session_id::text,
            'candidate_id', v_job_row.candidate_id::text,
            'source_build_run_id', v_source_build_run_id_text,
            'source_change_seq', v_source_change_seq,
            'progress_recomputed', false,
            'counter_reconciled', false,
            'retry_safe', true
          );
      END;
    END IF;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_job_row.candidate_id IS NOT NULL
     AND COALESCE(v_continuation_count, 0) = 0 THEN
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET pending_job_id = NULL::uuid,
        updated_at_utc = v_now
    WHERE scope_update.session_id = v_job_row.session_id
      AND scope_update.candidate_id = v_job_row.candidate_id
      AND scope_update.pending_job_id = p_job_id;

    GET DIAGNOSTICS v_scope_pending_job_cleared_count = ROW_COUNT;
  END IF;

  IF v_stage_job_type IN (
       'WORKBENCH_SESSION_SCOPE_SEED',
       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
       'WORKBENCH_CANDIDATE_DELTA_REFRESH',
       'WORKBENCH_SESSION_CLONE_REBASE',
       'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
       'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
       'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
     )
     AND v_job_row.session_id IS NOT NULL
     AND v_has_open_session THEN
    BEGIN
      SELECT session_row.*
      INTO v_session_row
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = v_job_row.session_id
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND COALESCE(session_row.version, 1) = COALESCE(v_session_row.version, 1)
        AND session_row.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_row.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      IF NOT FOUND THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
      END IF;
    EXCEPTION
      WHEN lock_not_available THEN
        v_finalisation_deferred := true;
        v_finalisation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_finalisation_deferred IS NOT TRUE THEN
      IF v_job_row.candidate_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS terminal_scope
        WHERE terminal_scope.session_id = v_job_row.session_id
          AND terminal_scope.candidate_id = v_job_row.candidate_id
          AND UPPER(BTRIM(COALESCE(terminal_scope.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
          AND COALESCE(terminal_scope.dirty, false) IS NOT TRUE
          AND (
            terminal_scope.error_json IS NULL
            OR terminal_scope.error_json = '{}'::jsonb
            OR terminal_scope.error_json = 'null'::jsonb
          )
      )
      INTO v_current_candidate_terminal_success;
    END IF;

    v_finalisation_should_evaluate := (
      COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_pending_count, 0) = 0
      AND COALESCE(v_session_row.scope_failed_count, 0) = 0
      AND COALESCE(v_session_row.line_units_pending, 0) = 0
      AND COALESCE(v_session_row.line_units_failed, 0) = 0
    )
    OR UPPER(BTRIM(COALESCE(v_session_row.progress_state, ''))) IN ('READY', 'READY_EMPTY');

    v_finalisation_actual_precheck_required := v_finalisation_should_evaluate IS NOT TRUE
      AND COALESCE(v_continuation_count, 0) = 0
      AND COALESCE(v_session_row.scope_seed_complete, false)
      AND COALESCE(v_session_row.scope_next_cursor_json, '{}'::jsonb) = '{}'::jsonb
      AND (
        v_stage_job_type = 'WORKBENCH_SESSION_SCOPE_SEED'
        OR v_current_candidate_terminal_success
      );

    IF v_finalisation_actual_precheck_required THEN
      SELECT
        NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS unresolved_scope
          WHERE unresolved_scope.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_scope.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
              OR COALESCE(unresolved_scope.seeded, false) IS NOT TRUE
              OR COALESCE(unresolved_scope.dirty, false)
              OR NOT (
                unresolved_scope.error_json IS NULL
                OR unresolved_scope.error_json = '{}'::jsonb
                OR unresolved_scope.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS unresolved_line_work
          WHERE unresolved_line_work.session_id = v_job_row.session_id
            AND (
              UPPER(BTRIM(COALESCE(unresolved_line_work.status, ''))) NOT IN ('MATERIALISED', 'MATERIALIZED', 'SKIPPED')
              OR NOT (
                unresolved_line_work.error_json IS NULL
                OR unresolved_line_work.error_json = '{}'::jsonb
                OR unresolved_line_work.error_json = 'null'::jsonb
              )
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_jobs AS active_job
          CROSS JOIN LATERAL (
            SELECT CASE
              WHEN COALESCE(active_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
                THEN (active_job.payload_json->>'session_version')::bigint
              ELSE NULL::bigint
            END AS job_session_version
          ) AS active_job_version
          WHERE active_job.session_id = v_job_row.session_id
            AND UPPER(BTRIM(COALESCE(active_job.status, ''))) IN ('QUEUED', 'RUNNING')
            AND (
              active_job_version.job_session_version IS NULL
              OR active_job_version.job_session_version >= COALESCE(v_session_row.version, 0)
            )
        )
      INTO v_finalisation_actual_precheck_passed;

      v_finalisation_should_evaluate := COALESCE(v_finalisation_actual_precheck_passed, false);
    END IF;

    IF v_finalisation_should_evaluate THEN
      v_finalisation_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_job_row.session_id,
        p_apply => false,
        p_reason => 'COMPLETE_JOB_FINALISATION_AUTHORITATIVE_COUNTER_SNAPSHOT',
        p_write_progress_json => false
      );

      IF jsonb_typeof(COALESCE(v_finalisation_progress_json, '{}'::jsonb)) <> 'object'
         OR LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR NOT (v_finalisation_progress_json ? 'session_ready') THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_COMPLETE_JOB_FINALISATION_PROGRESS_INVALID',
                  'job_id', p_job_id::text,
                  'session_id', v_job_row.session_id::text,
                  'progress_result', COALESCE(v_finalisation_progress_json, '{}'::jsonb)
                )::text;
      END IF;

      v_finalisation_evaluated := true;
      v_finalisation_session_ready := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'session_ready', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_for_draft := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_ready_empty := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'ready_empty', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_stored_ready_mismatch := LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'stored_ready_mismatch', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_finalisation_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'session_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_draft_blocker_codes := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'draft_blocker_codes', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;
      v_finalisation_blocker_counts := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'blocker_counts', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      v_authoritative_scope_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_total_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_total_count')::integer ELSE 0 END;
      v_authoritative_scope_seeded := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_seeded_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_seeded_count')::integer ELSE 0 END;
      v_authoritative_scope_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_ready_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_ready_count')::integer ELSE 0 END;
      v_authoritative_scope_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_pending_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_pending_count')::integer ELSE 0 END;
      v_authoritative_scope_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'scope_failed_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'scope_failed_count')::integer ELSE 0 END;
      v_authoritative_line_total := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_total', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_total')::integer ELSE 0 END;
      v_authoritative_line_pending := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_pending', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_pending')::integer ELSE 0 END;
      v_authoritative_line_ready := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_ready', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_ready')::integer ELSE 0 END;
      v_authoritative_line_failed := CASE WHEN COALESCE(v_finalisation_progress_json->>'line_units_failed', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'line_units_failed')::integer ELSE 0 END;
      v_authoritative_preview_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'preview_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'preview_row_count')::integer ELSE 0 END;
      v_authoritative_selected_row_count := CASE WHEN COALESCE(v_finalisation_progress_json->>'selected_row_count', '') ~ '^[0-9]+$' THEN (v_finalisation_progress_json->>'selected_row_count')::integer ELSE 0 END;
      v_authoritative_section_counts_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)) = 'object'
          THEN COALESCE(v_finalisation_progress_json->'section_counts_json', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;
      v_authoritative_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_finalisation_progress_json->'candidate_sample_rows_json', '[]'::jsonb)
        ELSE '[]'::jsonb
      END;

      v_finalisation_counter_reconciliation_required := COALESCE(v_session_row.scope_total_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_total, 0)
        OR COALESCE(v_session_row.scope_seeded_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_seeded, 0)
        OR COALESCE(v_session_row.scope_ready_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_ready, 0)
        OR COALESCE(v_session_row.scope_pending_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_pending, 0)
        OR COALESCE(v_session_row.scope_failed_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_scope_failed, 0)
        -- A23 (PRE-EXISTING SB02 fix, AA-B2): compare the stored RAW total with the RAW total (see the write below).
        OR COALESCE(v_session_row.line_units_total, 0) IS DISTINCT FROM (COALESCE(v_authoritative_line_ready, 0) + COALESCE(v_authoritative_line_pending, 0) + COALESCE(v_authoritative_line_failed, 0))
        OR COALESCE(v_session_row.line_units_pending, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_pending, 0)
        OR COALESCE(v_session_row.line_units_ready, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_ready, 0)
        OR COALESCE(v_session_row.line_units_failed, 0) IS DISTINCT FROM COALESCE(v_authoritative_line_failed, 0)
        OR COALESCE(v_session_row.preview_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_preview_row_count, 0)
        OR COALESCE(v_session_row.selected_row_count, 0) IS DISTINCT FROM COALESCE(v_authoritative_selected_row_count, 0)
        OR COALESCE(v_session_row.section_counts_json, '{}'::jsonb) IS DISTINCT FROM COALESCE(v_authoritative_section_counts_json, '{}'::jsonb);
      v_finalisation_counter_reconciliation_applied := v_duplicate_completion IS NOT TRUE;
      v_finalisation_counter_reconciled := v_finalisation_counter_reconciliation_applied;

      v_finalisation_counter_reconciliation_json := jsonb_build_object(
        'required', v_finalisation_counter_reconciliation_required,
        'applied', v_finalisation_counter_reconciliation_applied,
        'changed', v_finalisation_counter_reconciliation_required AND v_finalisation_counter_reconciliation_applied,
        'reconciled', v_finalisation_counter_reconciled,
        'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
        'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
        'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
        'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
        'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
        'line_units_total', COALESCE(v_authoritative_line_total, 0),
        'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
        'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
        'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
        'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
        'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
        'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb)
      );

      IF v_finalisation_session_ready THEN
        v_final_progress_state := CASE WHEN v_finalisation_ready_empty THEN 'READY_EMPTY' ELSE 'READY' END;
        v_final_phase := 'READY';
        v_final_status_text := 'Payment preview is ready.';
        v_final_next_recommended_action := 'READ_PREVIEW_PAGE';
      ELSE
        v_final_progress_state := UPPER(BTRIM(COALESCE(v_finalisation_progress_json->>'progress_state', '')));
        IF v_final_progress_state IN ('', 'READY', 'READY_EMPTY') THEN
          v_final_progress_state := CASE
            WHEN COALESCE(v_authoritative_scope_failed, 0) > 0
              OR COALESCE(v_authoritative_line_failed, 0) > 0
              OR (COALESCE(v_finalisation_blocker_codes, '[]'::jsonb) ? 'WORKBENCH_JOBS_FAILED') THEN 'ERROR'
            WHEN COALESCE(v_authoritative_line_ready, 0) > 0 THEN 'MATERIALISING_PREVIEW_ROWS'
            WHEN COALESCE(v_authoritative_line_pending, 0) > 0 THEN 'PROCESSING_LINE_WORK'
            ELSE 'REFRESHING_CANDIDATES'
          END;
        END IF;
        v_final_phase := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'phase'), ''), 'REFRESHING_CANDIDATES');
        v_final_status_text := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'status_text'), ''), 'Preparing payment preview.');
        v_final_next_recommended_action := COALESCE(NULLIF(BTRIM(v_finalisation_progress_json->>'next_recommended_action'), ''), 'WAIT_FOR_WORKER');
      END IF;

      IF v_duplicate_completion IS NOT TRUE THEN
        UPDATE public.banking_pay_workbench_sessions AS session_update
        SET scope_total_count = GREATEST(COALESCE(v_authoritative_scope_total, 0), 0),
          scope_seeded_count = GREATEST(COALESCE(v_authoritative_scope_seeded, 0), 0),
          scope_ready_count = GREATEST(COALESCE(v_authoritative_scope_ready, 0), 0),
          scope_pending_count = GREATEST(COALESCE(v_authoritative_scope_pending, 0), 0),
          scope_failed_count = GREATEST(COALESCE(v_authoritative_scope_failed, 0), 0),
          -- A23 (PRE-EXISTING SB02 fix, AA-B2): v_authoritative_line_total is recompute's DISPLAY figure
          -- GREATEST(line work, preview rows). The column holds the RAW line-work count, the same unit as
          -- line_units_ready (ready + pending + failed partition every line-work row). JSON outputs keep the display value.
          line_units_total = GREATEST((COALESCE(v_authoritative_line_ready, 0) + COALESCE(v_authoritative_line_pending, 0) + COALESCE(v_authoritative_line_failed, 0)), 0),
          line_units_pending = GREATEST(COALESCE(v_authoritative_line_pending, 0), 0),
          line_units_ready = GREATEST(COALESCE(v_authoritative_line_ready, 0), 0),
          line_units_failed = GREATEST(COALESCE(v_authoritative_line_failed, 0), 0),
          preview_row_count = GREATEST(COALESCE(v_authoritative_preview_row_count, 0), 0),
          selected_row_count = GREATEST(COALESCE(v_authoritative_selected_row_count, 0), 0),
          section_counts_json = COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
          candidate_sample_rows_json = COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
          progress_state = v_final_progress_state,
          progress_json = public.pay_workbench_session_compact_progress_json(
            jsonb_strip_nulls(
              jsonb_build_object(
              'ok', true,
              'server_utc', v_now,
              'updated_at_utc', v_now,
              'phase', v_final_phase,
              'status_text', v_final_status_text,
              'next_recommended_action', v_final_next_recommended_action,
              'progress_state', v_final_progress_state,
              'ready', v_finalisation_session_ready,
              'ready_flag', v_finalisation_session_ready,
              'session_ready', v_finalisation_session_ready,
              'ready_for_draft', v_finalisation_ready_for_draft,
              'can_create_draft', v_finalisation_ready_for_draft,
              'ready_empty', v_finalisation_ready_empty,
              'preview_ready', v_finalisation_session_ready,
              'work_queued', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'work_queued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'still_running', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'still_running', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'pending_refresh', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'pending_refresh', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_refresh_pending', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_refresh_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'preview_deferred', CASE
                WHEN v_finalisation_session_ready THEN false
                ELSE LOWER(BTRIM(COALESCE(v_finalisation_progress_json->>'preview_deferred', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              END,
              'authoritative_session_ready', v_finalisation_session_ready,
              'authoritative_ready_for_draft', v_finalisation_ready_for_draft,
              'authoritative_ready_empty', v_finalisation_ready_empty,
              'authoritative_progress_state', v_final_progress_state,
              'session_blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
              'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
              'blocker_counts', COALESCE(v_finalisation_blocker_counts, '{}'::jsonb),
              'stored_ready_mismatch', v_finalisation_stored_ready_mismatch
            )
            || jsonb_build_object(
              'scope_total_count', COALESCE(v_authoritative_scope_total, 0),
              'scope_seeded_count', COALESCE(v_authoritative_scope_seeded, 0),
              'scope_ready_count', COALESCE(v_authoritative_scope_ready, 0),
              'scope_pending_count', COALESCE(v_authoritative_scope_pending, 0),
              'scope_failed_count', COALESCE(v_authoritative_scope_failed, 0),
              'line_units_total', COALESCE(v_authoritative_line_total, 0),
              'line_units_pending', COALESCE(v_authoritative_line_pending, 0),
              'line_units_ready', COALESCE(v_authoritative_line_ready, 0),
              'line_units_failed', COALESCE(v_authoritative_line_failed, 0),
              'preview_row_count', COALESCE(v_authoritative_preview_row_count, 0),
              'selected_row_count', COALESCE(v_authoritative_selected_row_count, 0),
              'selected_eligible_ready_row_count', CASE
                WHEN COALESCE(v_finalisation_progress_json->>'selected_eligible_ready_row_count', '') ~ '^[0-9]+$'
                  THEN (v_finalisation_progress_json->>'selected_eligible_ready_row_count')::integer
                ELSE COALESCE(v_authoritative_selected_row_count, 0)
              END,
              'section_counts_json', COALESCE(v_authoritative_section_counts_json, '{}'::jsonb),
              'candidate_sample_rows_json', COALESCE(v_authoritative_candidate_sample_rows_json, '[]'::jsonb),
              'candidate_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'candidate_counts') = 'object'
                  THEN v_finalisation_progress_json->'candidate_counts'
                ELSE '{}'::jsonb
              END,
              'line_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'line_counts') = 'object'
                  THEN v_finalisation_progress_json->'line_counts'
                ELSE '{}'::jsonb
              END,
              'job_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'job_counts') = 'object'
                  THEN v_finalisation_progress_json->'job_counts'
                ELSE '{}'::jsonb
              END,
              'source_build_counts', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'source_build_counts') = 'object'
                  THEN v_finalisation_progress_json->'source_build_counts'
                ELSE '{}'::jsonb
              END,
              'pending_job_ids_json', CASE
                WHEN v_finalisation_session_ready THEN '[]'::jsonb
                WHEN jsonb_typeof(v_finalisation_progress_json->'pending_job_ids_json') = 'array'
                  THEN v_finalisation_progress_json->'pending_job_ids_json'
                ELSE '[]'::jsonb
              END,
              'session_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'session_blockers') = 'array'
                  THEN v_finalisation_progress_json->'session_blockers'
                ELSE '[]'::jsonb
              END,
              'draft_blockers', CASE
                WHEN jsonb_typeof(v_finalisation_progress_json->'draft_blockers') = 'array'
                  THEN v_finalisation_progress_json->'draft_blockers'
                ELSE '[]'::jsonb
              END
            )
            || jsonb_build_object(
              'finalisation_evaluated', true,
              'finalisation_evaluated_at_utc', v_now::text,
              'finalisation_source_job_id', p_job_id::text,
              'finalisation_source_job_type', v_stage_job_type,
              'terminal_readiness_deferred', v_finalisation_session_ready IS NOT TRUE,
              'finalisation_pending', v_finalisation_session_ready IS NOT TRUE,
              'finalised_at_utc', CASE WHEN v_finalisation_session_ready THEN v_now::text ELSE NULL::text END,
              'counter_reconciled', v_finalisation_counter_reconciled,
              'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb)
            )
            ),
            true
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
        WHERE session_update.id = v_job_row.session_id
        RETURNING session_update.*
        INTO v_session_row;
      END IF;
    END IF;
    END IF;
  END IF;

  v_completion_finalisation_json := jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
    'certified_source_preview_applied', v_certified_publication_applied,
    'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'bounded_terminal_targeted_timesheet_count', COALESCE(v_bounded_terminal_targeted_timesheet_count, 0),
    'bounded_terminal_source_rows_retired_count', COALESCE(v_bounded_terminal_source_rows_retired_count, 0),
    'bounded_terminal_line_work_retired_count', COALESCE(v_bounded_terminal_line_work_retired_count, 0),
    'bounded_terminal_scope_finalised_count', COALESCE(v_bounded_terminal_scope_finalised_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason,
    'evaluated_at_utc', CASE WHEN v_finalisation_evaluated THEN v_now::text ELSE NULL::text END
  );

  IF v_duplicate_completion IS NOT TRUE THEN
    UPDATE public.banking_pay_workbench_jobs AS update_job
    SET payload_json = COALESCE(update_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'completion_json', COALESCE(update_job.payload_json->'completion_json', '{}'::jsonb)
              || v_completion_finalisation_json
          ),
        updated_at_utc = v_now
    WHERE update_job.id = p_job_id
    RETURNING update_job.*
    INTO v_job_row;

    -- A correction fallback build can finish after the correction operation.
    -- Emit one lightweight batch signal only when this exact source-build job
    -- has made its candidate physically current.  The payload claim makes the
    -- hook idempotent and does not create a second financial or queue owner.
    IF v_stage_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_has_more IS NOT TRUE AND COALESCE(v_continuation_count,0)=0
       AND COALESCE(v_current_candidate_terminal_success,false)
       AND COALESCE(v_job_row.payload_json->>'correction_request_id','')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_correction_request_id:=(v_job_row.payload_json->>'correction_request_id')::uuid;
      SELECT request_row.pay_batch_id
      INTO v_correction_pay_batch_id
      FROM public.pay_payment_correction_requests AS request_row
      WHERE request_row.id=v_correction_request_id
        AND request_row.status IN ('APPLIED','APPLIED_WITH_BLOCKERS','BLOCKED');

      IF v_correction_pay_batch_id IS NOT NULL THEN
        UPDATE public.banking_pay_workbench_jobs AS signal_job
        SET payload_json=COALESCE(signal_job.payload_json,'{}'::jsonb)||pg_catalog.jsonb_build_object(
              'correction_terminal_current_signal_emitted',true,
              'correction_terminal_current_signal_emitted_at_utc',v_now
            ),updated_at_utc=v_now
        WHERE signal_job.id=p_job_id
          AND COALESCE((signal_job.payload_json->>'correction_terminal_current_signal_emitted')::boolean,false)
            IS NOT TRUE
        RETURNING true INTO v_correction_signal_claimed;

        IF COALESCE(v_correction_signal_claimed,false) THEN
          PERFORM public.banking_pay_batch_signal_touch(
            p_pay_batch_id:=v_correction_pay_batch_id,
            p_change_reason:='PAYMENT_CORRECTION_WORKBENCH_CURRENT',
            p_change_source:='pay_workbench_complete_job',
            p_change_scope_json:=pg_catalog.jsonb_build_object(
              'correction_request_id',v_correction_request_id,
              'job_id',p_job_id,'candidate_id',v_job_row.candidate_id,
              'workbench_status','CURRENT'
            ),
            p_touch_payment_status:=true,p_touch_correction_progress:=true,
            p_touch_alerts:=false,p_touch_overview:=true
          );
        END IF;
      END IF;
    END IF;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      p_job_id::text,
      'SUCCEEDED',
      NULL,
      jsonb_build_object(
        'id', p_job_id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
        'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
        'attempt_count', v_job_row.attempt_count,
        'completed_at_utc', v_job_row.completed_at_utc,
        'continuation_count', COALESCE(v_continuation_count, 0),
        'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
        'next_recommended_action', v_next_recommended_action
      )
      || jsonb_build_object(
        'has_more', v_has_more,
        'next_cursor_present', v_next_cursor IS NOT NULL,
        'seeded_count', COALESCE(v_seeded_count, 0),
        'source_rows_written', COALESCE(v_source_rows_written, 0),
        'current_source_row_count', COALESCE(v_current_source_row_count, 0),
        'source_build_run_id', v_source_build_run_id_text,
        'source_change_seq', v_source_change_seq,
        'new_scope_count', COALESCE(v_new_scope_count, 0),
        'processed_count', COALESCE(v_processed_count, 0),
        'ready_count_delta', COALESCE(v_ready_count_delta, 0),
        'materialised_count', COALESCE(v_materialised_count, 0),
        'error_count', COALESCE(v_error_count, 0),
        'finalisation', v_completion_finalisation_json,
        'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
        'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb),
        'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
        'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason
      ),
      'WORKBENCH_JOB_COMPLETED',
      NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', 'SUCCEEDED',
    'completed_at_utc', COALESCE(v_completed_at_utc, v_job_row.completed_at_utc, v_now),
    'result_json', v_result_json,
    'continuation_enqueued', v_continuation_enqueued,
    'continuation_jobs', COALESCE(v_continuation_jobs, '[]'::jsonb),
    'continuation_count', COALESCE(v_continuation_count, 0),
    'continuation_reused_count', COALESCE(v_continuation_reused_count, 0),
    'next_recommended_action', v_next_recommended_action,
    'has_more', v_has_more,
    'next_cursor_present', v_next_cursor IS NOT NULL,
    'line_work_pending_after_completion', CASE WHEN v_stage_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN v_pending_line_work_exists ELSE NULL END,
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'source_build_run_id', v_source_build_run_id_text,
    'source_change_seq', v_source_change_seq,
    'stage_job_type', v_stage_job_type,
    'duplicate_completion', v_duplicate_completion,
    'source_build_reconciliation_applied', v_source_reconciliation_applied,
    'source_build_reconciliation_deferred', COALESCE(v_source_reconciliation_deferred, false),
    'source_build_reconciliation_deferred_reason', v_source_reconciliation_deferred_reason,
    'source_build_reconciliation', COALESCE(v_source_reconciliation_json, '{}'::jsonb),
    'certified_source_preview_applied', v_certified_publication_applied,
    'certified_source_preview', COALESCE(v_certified_publication_json, '{}'::jsonb)
  )
  || jsonb_build_object(
    'finalisation_evaluated', v_finalisation_evaluated,
    'session_ready', CASE WHEN v_finalisation_evaluated THEN v_finalisation_session_ready ELSE NULL::boolean END,
    'ready_for_draft', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_for_draft ELSE NULL::boolean END,
    'ready_empty', CASE WHEN v_finalisation_evaluated THEN v_finalisation_ready_empty ELSE NULL::boolean END,
    'final_progress_state', CASE WHEN v_finalisation_evaluated THEN v_final_progress_state ELSE v_session_row.progress_state END,
    'blocker_codes', COALESCE(v_finalisation_blocker_codes, '[]'::jsonb),
    'draft_blocker_codes', COALESCE(v_finalisation_draft_blocker_codes, '[]'::jsonb),
    'counter_reconciliation_required', v_finalisation_counter_reconciliation_required,
    'counter_reconciliation_applied', v_finalisation_counter_reconciliation_applied,
    'counter_reconciled', v_finalisation_counter_reconciled,
    'counter_reconciliation', COALESCE(v_finalisation_counter_reconciliation_json, '{}'::jsonb),
    'actual_precheck_required', v_finalisation_actual_precheck_required,
    'actual_precheck_passed', v_finalisation_actual_precheck_passed,
    'scope_pending_job_cleared_count', COALESCE(v_scope_pending_job_cleared_count, 0),
    'continuation_scope_counter_adjusted', v_scope_continuation_counter_adjusted,
    'continuation_scope_old_status', v_scope_status_before_continuation,
    'continuation_scope_new_status', v_scope_status_after_continuation,
    'continuation_scope_pending_delta', COALESCE(v_scope_continuation_pending_delta, 0),
    'continuation_scope_ready_delta', COALESCE(v_scope_continuation_ready_delta, 0),
    'continuation_scope_failed_delta', COALESCE(v_scope_continuation_failed_delta, 0),
    'source_empty_session_progress_deferred', COALESCE(v_source_empty_session_progress_deferred, false),
    'source_empty_session_progress_deferred_reason', v_source_empty_session_progress_deferred_reason,
    'source_empty_cleanup_source_row_count', COALESCE(v_source_empty_cleanup_source_row_count, 0),
    'source_empty_cleanup_line_work_count', COALESCE(v_source_empty_cleanup_line_work_count, 0),
    'source_empty_cleanup_preview_row_count', COALESCE(v_source_empty_cleanup_preview_row_count, 0),
    'source_empty_cleanup_targeted_timesheet_count', COALESCE(v_source_empty_targeted_timesheet_count, 0),
    'bounded_terminal_targeted_timesheet_count', COALESCE(v_bounded_terminal_targeted_timesheet_count, 0),
    'bounded_terminal_source_rows_retired_count', COALESCE(v_bounded_terminal_source_rows_retired_count, 0),
    'bounded_terminal_line_work_retired_count', COALESCE(v_bounded_terminal_line_work_retired_count, 0),
    'bounded_terminal_scope_finalised_count', COALESCE(v_bounded_terminal_scope_finalised_count, 0),
    'continuation_scope_counter_deferred', COALESCE(v_continuation_scope_counter_deferred, false),
    'continuation_scope_counter_deferred_reason', v_continuation_scope_counter_deferred_reason,
    'finalisation_deferred', COALESCE(v_finalisation_deferred, false),
    'finalisation_deferred_reason', v_finalisation_deferred_reason
  );
END;
$function$
;

-- [REPLACES] public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb, p_reason text, p_priority integer, p_run_at_utc timestamp with time zone)  winner piece A15
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid DEFAULT NULL::uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT '-1000'::integer, p_run_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_scope_kind text := UPPER(BTRIM(COALESCE(p_scope_kind, '')));
  v_scope_id text := NULLIF(BTRIM(COALESCE(p_scope_id, '')), '');
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_key_part text := 'ALL';
  v_dedupe_key text;
  v_reason text := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_payload_json jsonb := '{}'::jsonb;
  v_incoming_payload jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb;
  v_priority integer := COALESCE(p_priority, -1000);
  v_run_at_utc timestamptz := COALESCE(p_run_at_utc, v_now);
  v_scope_uuid uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_scope_change_tx_token uuid := NULL::uuid;
  -- A15 (PRE-EXISTING SB02 Workbench fix): bounded active-dedupe identity.
  v_full_dedupe_key text := NULL::text;
  v_dedupe_is_digest boolean := false;
BEGIN
  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RAISE EXCEPTION 'Unsupported Banking Pay dirty event job_type: %', p_job_type
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_kind = '' OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event requires scope_kind and scope_id'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_uuid := v_scope_id::uuid;
  END IF;

  IF v_job_type IN ('WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
     AND v_scope_uuid IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event scope_id must be a UUID for job_type %, scope_kind %, scope_id %', v_job_type, v_scope_kind, v_scope_id
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_id ORDER BY target_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_id
  WHERE target_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_id ORDER BY linked_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_id
  WHERE linked_id IS NOT NULL;

  -- The central invalidator owns durable candidate/timesheet economic state.
  -- Its guarded callback into this function preserves the installed queue
  -- envelope without recursion or a second queue authority.
  IF v_job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
     AND p_candidate_id IS NOT NULL
     AND COALESCE(current_setting('cloudtms.bpay_scope_invalidator_active',true),'')<>'true' THEN
    IF COALESCE(p_payload_json->>'scope_change_tx_token','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_scope_change_tx_token:=(p_payload_json->>'scope_change_tx_token')::uuid;
    END IF;
    v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
        ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_targeted_timesheet_ids)]) END,
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
        ELSE v_targeted_timesheet_ids END,
      COALESCE(v_reason,'DIRTY_TRIGGER:'||v_scope_kind),
      v_scope_change_tx_token,
      COALESCE(p_payload_json,'{}'::jsonb)||jsonb_build_object('skip_candidate_job_enqueue',true)
    );
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
    v_targeted_key_part := array_to_string(v_targeted_timesheet_ids, ',');
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_latest_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(v_latest_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'latest_source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_sequence', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_sequence')::bigint END, 0)
  );

  IF v_reason IS NULL THEN
    v_reason := 'DIRTY_TRIGGER:' || v_scope_kind;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'Candidate dirty apply job requires p_candidate_id'
        USING ERRCODE = '22023';
    END IF;
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
      || p_candidate_id::text
      || ':TIMESHEETS:' || v_targeted_key_part;
    -- A15: the full key names every targeted Timesheet, so above about 69
    -- Timesheets it cannot be stored in the active-dedupe B-tree index
    -- (2,704-byte / 8,191-byte limits) and the whole business statement fails.
    -- Keys up to 2,048 bytes (<=52 Timesheets) keep their exact historical
    -- text.  A longer key is replaced by a fixed-size SHA-256 of the SAME
    -- canonical, sorted, de-duplicated Timesheet list, so equal scopes still
    -- share one key and different scopes still get different keys.  The full
    -- list stays in the unindexed payload_json.targeted_timesheet_ids that the
    -- consumer already reads; the key is never parsed.
    IF pg_catalog.octet_length(v_dedupe_key) > 2048 THEN
      v_full_dedupe_key := v_dedupe_key;
      v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
        || p_candidate_id::text
        || ':TIMESHEETS:SHA256:'
        || pg_catalog.encode(
             pg_catalog.sha256(pg_catalog.convert_to(v_targeted_key_part, 'UTF8')),
             'hex'
           )
        || ':COUNT:' || cardinality(v_targeted_timesheet_ids)::text;
      v_dedupe_is_digest := true;
      -- Transition exactness: a job queued before A15 under the full key
      -- (53..69 Timesheets were storable) keeps absorbing the same scope.
      IF EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS legacy_job
        WHERE legacy_job.dedupe_key = v_full_dedupe_key
          AND legacy_job.status IN ('QUEUED', 'RUNNING')
      ) THEN
        v_dedupe_key := v_full_dedupe_key;
        v_dedupe_is_digest := false;
      END IF;
    END IF;
  ELSIF v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_FINANCE_CASE_DIRTY_APPLY:' || v_scope_kind || ':' || v_scope_id;
  ELSE
    v_dedupe_key := 'DIRTY_TRIGGER:CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope_kind || ':' || v_scope_id;
  END IF;

  v_incoming_payload := jsonb_strip_nulls(
    COALESCE(p_payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'job_type', v_job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'finance_case_id', CASE WHEN v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'contract_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CONTRACT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'client_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CLIENT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'umbrella_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'UMBRELLA' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'reason', v_reason,
      'reason_latest', v_reason,
      'reason_count', 1,
      'trigger_source', COALESCE(p_payload_json->>'trigger_source', p_payload_json->>'trigger_table', v_scope_kind),
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', v_now::text,
      'event_at_utc', v_now::text,
      'rerun_required', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_payload_json := public._pay_workbench_dirty_payload_merge('{}'::jsonb, v_incoming_payload);

  INSERT INTO public.banking_pay_workbench_jobs AS queued_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_run_at_utc,
    0,
    8,
    v_dedupe_key,
    NULL,
    NULL,
    CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN p_candidate_id ELSE NULL::uuid END,
    v_payload_json,
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(queued_job.priority, EXCLUDED.priority),
      run_at_utc = LEAST(queued_job.run_at_utc, EXCLUDED.run_at_utc),
      updated_at_utc = v_now,
      failed_at_utc = CASE WHEN queued_job.status = 'QUEUED' THEN NULL ELSE queued_job.failed_at_utc END,
      last_error_json = CASE WHEN queued_job.status = 'QUEUED' THEN NULL::jsonb ELSE queued_job.last_error_json END,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(queued_job.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        || CASE
             WHEN queued_job.status = 'RUNNING' THEN jsonb_build_object('rerun_required', true)
             ELSE '{}'::jsonb
           END
      )
  -- A15: a digest key may only coalesce into a job that already covers every
  -- Timesheet of the incoming canonical scope (the durable targeted list only
  -- grows by union).  Anything else would be a digest collision: refuse it.
  WHERE v_dedupe_is_digest IS NOT TRUE
     OR NOT EXISTS (
       SELECT incoming_id.value::text
       FROM pg_catalog.unnest(v_targeted_timesheet_ids) AS incoming_id(value)
       EXCEPT
       SELECT covered_id.value
       FROM pg_catalog.jsonb_array_elements_text(
         CASE WHEN pg_catalog.jsonb_typeof(queued_job.payload_json->'targeted_timesheet_ids') = 'array'
           THEN queued_job.payload_json->'targeted_timesheet_ids'
           ELSE '[]'::jsonb END
       ) AS covered_id(value)
     )
  RETURNING queued_job.id, queued_job.status, queued_job.payload_json
  INTO v_job_id, v_job_status, v_job_payload;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DIRTY_DEDUPE_DIGEST_SCOPE_MISMATCH',
              'dedupe_key', v_dedupe_key,
              'candidate_id', p_candidate_id,
              'targeted_timesheet_count', cardinality(v_targeted_timesheet_ids)
            )::text;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    v_scope_id,
    jsonb_build_object(
      'function_name', 'pay_workbench_dirty_event_enqueue',
      'stage', CASE WHEN v_job_status = 'RUNNING' THEN 'dirty_enqueue_coalesced_existing_running' ELSE 'dirty_enqueue_inserted_or_coalesced_queued' END,
      'job_id', v_job_id::text,
      'job_type', v_job_type,
      'dedupe_key', v_dedupe_key,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority', v_priority,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'latest_source_change_seq', v_latest_source_change_seq,
      'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'dedupe_key', v_dedupe_key,
    'queue_class', 'DIRTY_TRIGGER_PRIORITY',
    'priority', v_priority,
    'scope_kind', v_scope_kind,
    'scope_id', v_scope_id,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'latest_source_change_seq', v_latest_source_change_seq,
    'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
  );
END;
$function$;

-- [REPLACES] public.pay_workbench_mark_candidate_dirty()  winner piece A10
CREATE OR REPLACE FUNCTION public.pay_workbench_mark_candidate_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_previous_tsfin_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_old_timesheet_id uuid := NULL::uuid;
  v_new_timesheet_id uuid := NULL::uuid;
  v_old_contract_id uuid := NULL::uuid;
  v_new_contract_id uuid := NULL::uuid;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_old_payment_eligible boolean := false;
  v_new_payment_eligible boolean := false;
  v_authorise_boundary_changed boolean := false;
  v_authorise_boundary_is_authorise boolean := false;
  v_authorise_boundary_is_unauthorise boolean := false;
  v_archive_boundary_changed boolean := false;
  v_archive_boundary_is_archive boolean := false;
  v_archive_boundary_is_unarchive boolean := false;
  v_material_live_source_changed boolean := false;
  v_tsfin_payability_state_changed boolean := false;
  v_timesheet_pay_state_settlement_changed boolean := false;
  v_timesheet_pay_state_summary_changed boolean := false;
  v_timesheet_pay_state_bookkeeping_ignored boolean := false;
  v_timesheet_pay_state_noop_ignored boolean := false;
  v_timesheet_pay_state_routing_reason text := NULL::text;
  v_tsfin_insert_authorise_like boolean := false;
  v_tsfin_insert_not_coalesced_reason text := NULL::text;
  v_tsfin_insert_coalesced_job_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_projection_run_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_session_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_source_change_seq bigint := NULL::bigint;
  v_lifecycle_context text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.lifecycle_mutation_context', true), '')), '');
  v_effective_lifecycle_context text := NULL::text;
  v_lifecycle_dedupe_keys text := '';
  v_lifecycle_dedupe_token text := '';
  v_explicit_banking_pay_action boolean := false;
  v_banking_pay_dirty_required boolean := false;
  v_ordinary_timesheet_edit_save_no_dirty boolean := false;
  v_entity_kind_old text := '';
  v_entity_kind_new text := '';
  v_umbrella_id_old uuid := NULL::uuid;
  v_umbrella_id_new uuid := NULL::uuid;
  v_scope_id text;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
  v_candidate_route_change boolean := false;
  v_route_source_method text := NULL::text;
  v_route_target_method text := NULL::text;
  v_route_operation_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_operation_id', true), '')), '');
  v_route_actor_user_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_actor_user_id', true), '')), '');
  v_route_reason text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_reason', true), '')), '');
  v_route_scope_result jsonb := '{}'::jsonb;
  v_route_authoritative_sessions jsonb := '[]'::jsonb;
  v_route_replaced_source_session_ids jsonb := '[]'::jsonb;
  v_route_target_details jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_ids jsonb := '[]'::jsonb;
  v_route_active_advance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_retained_finance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_count integer := 0;
  v_route_active_advance_timesheet_count integer := 0;
  v_route_retained_finance_timesheet_count integer := 0;
  v_route_source_target_mismatch_count integer := 0;
  v_route_exact_scope boolean := false;
  v_route_coverage_complete boolean := false;
  v_route_targeted_scope_is_empty boolean := false;
  v_route_job_id uuid := NULL::uuid;
  v_route_job_status text := NULL::text;
  v_route_job_source_change_seq bigint := 0;
  v_route_dedupe_key text := NULL::text;
  v_internal_build_token uuid := NULL::uuid;
  v_internal_candidate_id uuid := NULL::uuid;
  v_internal_source_id uuid := NULL::uuid;
  v_internal_timesheet_id uuid := NULL::uuid;
  v_internal_logical_source_id uuid := NULL::uuid;
  v_internal_before_digest text := NULL::text;
  v_internal_after_digest text := NULL::text;
  v_expected_match_count integer := 0;
  v_delete_owner_candidate_id uuid := NULL::uuid;
  v_delete_context regclass := pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1');
  v_delete_context_suppressed boolean := false;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    NULL::text,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', 'entry',
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;


  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL THEN
    IF v_trigger_table='candidates' AND NULLIF(v_old_row->>'id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'id')::uuid;
    ELSIF NULLIF(v_old_row->>'candidate_id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'candidate_id')::uuid;
    ELSIF NULLIF(COALESCE(v_old_row->>'timesheet_id',v_old_row->>'linked_timesheet_id'),'')~*v_uuid_re THEN
      SELECT COALESCE(
        financial.candidate_id,
        contract_row.candidate_id,
        deleted_timesheet_contract.candidate_id
      )
      INTO v_delete_owner_candidate_id
      FROM (SELECT COALESCE(NULLIF(v_old_row->>'timesheet_id','')::uuid,
             NULLIF(v_old_row->>'linked_timesheet_id','')::uuid) AS timesheet_id) owner_key
      LEFT JOIN public.timesheets_financials financial
        ON financial.timesheet_id=owner_key.timesheet_id AND financial.is_current
      LEFT JOIN public.timesheets timesheet_row ON timesheet_row.timesheet_id=owner_key.timesheet_id
      LEFT JOIN public.contracts contract_row ON contract_row.id=timesheet_row.contract_id
      LEFT JOIN public.contracts deleted_timesheet_contract
        ON deleted_timesheet_contract.id=NULLIF(v_old_row->>'contract_id','')::uuid
      LIMIT 1;
    ELSIF NULLIF(v_old_row->>'contract_id','')~*v_uuid_re THEN
      SELECT contract_row.candidate_id INTO v_delete_owner_candidate_id
      FROM public.contracts contract_row WHERE contract_row.id=(v_old_row->>'contract_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_case_id','')~*v_uuid_re THEN
      SELECT finance_case.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_advances finance_case WHERE finance_case.id=(v_old_row->>'finance_case_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_component_id','')~*v_uuid_re THEN
      SELECT component.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_finance_case_components component
      WHERE component.id=(v_old_row->>'finance_component_id')::uuid;
    END IF;
  END IF;

  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL
     AND v_delete_owner_candidate_id IS NOT NULL THEN
    IF EXISTS(
         SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_delete_context
           AND relation.relowner=current_user::regrole::oid AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema()
       )
       AND (SELECT array_agg(attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
              ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_delete_context
              AND attribute.attnum>0 AND NOT attribute.attisdropped)
         =ARRAY['candidate_id:uuid','delete_operation_id:uuid','candidate_lock_key:bigint',
           'backend_pid:integer','transaction_id:bigint','created_at_utc:timestamp with time zone',
           'suppress:boolean'] THEN
      -- The delete context is optional.  Keep its only row read behind dynamic
      -- SQL so an ordinary finance DELETE cannot fail during statement planning
      -- merely because candidate deletion did not create the temporary table.
      EXECUTE $delete_context$
        SELECT EXISTS(
          SELECT 1
          FROM pg_temp._bpay_candidate_delete_context_v1 context
          WHERE context.candidate_id=$1 AND context.suppress
            AND context.candidate_lock_key=pg_catalog.hashtextextended(
              public._pay_workbench_candidate_serial_key(context.candidate_id),24062027)
            AND context.backend_pid=pg_catalog.pg_backend_pid()
            AND context.transaction_id=pg_catalog.txid_current()
            AND (SELECT count(*) FROM pg_temp._bpay_candidate_delete_context_v1)=1
        )
      $delete_context$ INTO v_delete_context_suppressed USING v_delete_owner_candidate_id;
    END IF;
    IF v_delete_context_suppressed THEN
      RETURN OLD;
    END IF;
  END IF;

  -- The retained pay_advances dirty trigger is recreated as BEFORE ROW.  It
  -- declares the exact full transition before the row mutation and suppresses
  -- only an owner-controlled effect inside the current sealed build scope.
  IF v_trigger_table='pay_advances'
     AND to_regclass('pg_temp._bpay_wb_sync_context_v1') IS NOT NULL
     AND to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL
     AND COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token',true),'')
       ~* v_uuid_re THEN
    v_internal_build_token:=current_setting(
      'cloudtms.pay_workbench_overpayment_sync_token',true)::uuid;
    SELECT build_row.candidate_id INTO v_internal_candidate_id
    FROM pg_temp._bpay_wb_sync_context_v1 sync_context
       JOIN private.banking_pay_workbench_economic_builds build_row
         ON build_row.id=sync_context.build_id AND build_row.build_token=sync_context.build_token
       JOIN private.banking_pay_workbench_stage_attempts attempt
         ON attempt.id=sync_context.attempt_id AND attempt.attempt_nonce=sync_context.attempt_nonce
        AND attempt.build_id=build_row.id AND attempt.attempt_status='STARTED'
    WHERE build_row.status='RECONCILING' AND build_row.private_stage='RECONCILE_EXECUTE'
      AND build_row.build_token=v_internal_build_token;
    IF v_internal_candidate_id IS NOT NULL THEN
      IF TG_WHEN<>'BEFORE' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_internal_source_id:=COALESCE(NULLIF(v_new_row->>'id','')::uuid,
        NULLIF(v_old_row->>'id','')::uuid);
      v_internal_timesheet_id:=COALESCE(NULLIF(v_new_row->>'linked_timesheet_id','')::uuid,
        NULLIF(v_old_row->>'linked_timesheet_id','')::uuid);
      v_internal_before_digest:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_old_row,v_old_row)::text) END;
      v_internal_after_digest:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_new_row,v_old_row)::text) END;
      IF v_internal_source_id IS NULL
         OR COALESCE(NULLIF(v_new_row->>'candidate_id','')::uuid,
              NULLIF(v_old_row->>'candidate_id','')::uuid)
            IS DISTINCT FROM v_internal_candidate_id
         OR (v_internal_timesheet_id IS NOT NULL AND NOT EXISTS(
           SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
           JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
             ON sync_context.build_id=scope_row.build_id
           WHERE scope_row.timesheet_id=v_internal_timesheet_id
         )) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
      END IF;
      IF v_effect_capture_mode THEN
        INSERT INTO pg_temp._bpay_wb_expected_effects(
          build_token,candidate_id,timesheet_id,relation_name,operation,source_id,
          finance_case_id,finance_component_id,economic_key_type,economic_key_value,
          expected_before_digest,expected_after_digest,proposed,observed
        ) VALUES(
          v_internal_build_token,v_internal_candidate_id,v_internal_timesheet_id,
          v_trigger_table,TG_OP,v_internal_source_id,v_internal_source_id,NULL,NULL,NULL,
          v_internal_before_digest,v_internal_after_digest,true,false
        );
      ELSIF TG_OP='INSERT' THEN
        UPDATE pg_temp._bpay_wb_expected_effects expected
        SET actual_source_id=v_internal_source_id,proposed=true
        WHERE expected.ctid=(SELECT candidate.ctid
          FROM pg_temp._bpay_wb_expected_effects candidate
          WHERE candidate.build_token=v_internal_build_token
            AND candidate.candidate_id=v_internal_candidate_id
            AND candidate.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
            AND candidate.relation_name=v_trigger_table AND candidate.operation=TG_OP
            AND candidate.proposed IS NOT TRUE AND candidate.observed IS NOT TRUE
            AND candidate.expected_before_digest IS NULL
            AND candidate.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest
          ORDER BY candidate.source_id LIMIT 1)
        RETURNING expected.source_id INTO v_internal_logical_source_id;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 OR v_internal_logical_source_id IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_effect_identity_map_v1(
          relation_name,logical_source_id,actual_source_id)
        VALUES(v_trigger_table,v_internal_logical_source_id,v_internal_source_id);
      ELSE
        UPDATE pg_temp._bpay_wb_expected_effects expected SET proposed=true
        WHERE expected.build_token=v_internal_build_token
          AND expected.candidate_id=v_internal_candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
          AND expected.relation_name=v_trigger_table AND expected.operation=TG_OP
          AND expected.source_id=v_internal_source_id
          AND expected.proposed IS NOT TRUE AND expected.observed IS NOT TRUE
          AND expected.expected_before_digest IS NOT DISTINCT FROM v_internal_before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  -- Natural-expiry fields are derived scheduler metadata.  An update confined
  -- to this allowlist must not create another generation or candidate build.
  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'pay_item_snoozes'
     AND (
       v_new_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) IS NOT DISTINCT FROM (
       v_old_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_old_contract_id := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_new_contract_id := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid;
  END IF;

  v_explicit_banking_pay_action := lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_explicit_action', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_dirty_allowed', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN (
      'timesheet_authorise',
      'timesheet_unauthorise',
      'timesheet_archive',
      'timesheet_unarchive',
      'authorise_timesheet',
      'unauthorise_timesheet',
      'archive_timesheet',
      'unarchive_timesheet',
      'banking_pay',
      'banking_pay_refresh',
      'banking_pay_dirty',
      'banking_pay_action',
      'banking_pay_recalculate',
      'banking_pay_decision',
      'banking_pay_case_resolution',
      'banking_pay_timesheet_advance',
      'banking_pay_patch'
    );

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('manual_timesheet_save', 'ordinary_timesheet_save', 'timesheet_manual_save', 'manual_save')
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', v_new_row->>'revoked_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_insert_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_server_present', false,
        'revoked_at_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_authorise_boundary_changed :=
      (
        NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      ) IS DISTINCT FROM (
        NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      );

    v_archive_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL);

    v_material_live_source_changed :=
      (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'additional_units_week') IS DISTINCT FROM (v_new_row->'additional_units_week')
      OR (v_old_row->'additional_units_per_day') IS DISTINCT FROM (v_new_row->'additional_units_per_day')
      OR (v_old_row->'week_ending_date') IS DISTINCT FROM (v_new_row->'week_ending_date')
      OR (v_old_row->'booking_id') IS DISTINCT FROM (v_new_row->'booking_id')
      OR (v_old_row->'line_type') IS DISTINCT FROM (v_new_row->'line_type')
      OR (v_old_row->'sheet_scope') IS DISTINCT FROM (v_new_row->'sheet_scope')
      OR (v_old_row->'reference_number') IS DISTINCT FROM (v_new_row->'reference_number')
      OR (v_old_row->'status') IS DISTINCT FROM (v_new_row->'status')
      OR (v_old_row->'submission_mode') IS DISTINCT FROM (v_new_row->'submission_mode')
      OR (v_old_row->'contract_id') IS DISTINCT FROM (v_new_row->'contract_id')
      OR (v_old_row->'is_adjustment') IS DISTINCT FROM (v_new_row->'is_adjustment')
      OR (v_old_row->'parent_timesheet_id') IS DISTINCT FROM (v_new_row->'parent_timesheet_id')
      OR (v_old_row->'correction_id') IS DISTINCT FROM (v_new_row->'correction_id')
      OR (v_old_row->'correction_kind') IS DISTINCT FROM (v_new_row->'correction_kind')
      OR (v_old_row->'adjustment_origin') IS DISTINCT FROM (v_new_row->'adjustment_origin');
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_authorise_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL);

    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_material_live_source_changed :=
      (v_old_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
      OR (v_old_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
      OR (v_old_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
      OR (v_old_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
      OR (v_old_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
      OR (v_old_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
      OR (v_old_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
      OR (v_old_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
      OR (v_old_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
      OR (v_old_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
      OR (v_old_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
      OR (v_old_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
      OR (v_old_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
      OR (v_old_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
      OR (v_old_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
      OR (v_old_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
      OR (v_old_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
      OR (v_old_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
      OR (v_old_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
      OR (v_old_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
      OR (v_old_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
      OR (v_old_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
      OR (v_old_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
      OR (v_old_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
      OR (v_old_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
      OR (v_old_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
      OR (v_old_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
      OR (v_old_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
      OR (v_old_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
      OR (v_old_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
      OR (v_old_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
      OR (v_old_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

-- [REPLACES] public.pay_workbench_reconcile_successful_source_build(p_session_id uuid, p_candidate_id uuid, p_source_build_run_id uuid, p_source_change_seq bigint, p_session_version bigint, p_success_job_id uuid, p_refresh_scope_kind text, p_targeted_timesheet_ids jsonb, p_linked_timesheet_ids jsonb, p_recompute_session_progress boolean)  winner piece A23
CREATE OR REPLACE FUNCTION public.pay_workbench_reconcile_successful_source_build(p_session_id uuid, p_candidate_id uuid, p_source_build_run_id uuid, p_source_change_seq bigint, p_session_version bigint DEFAULT NULL::bigint, p_success_job_id uuid DEFAULT NULL::uuid, p_refresh_scope_kind text DEFAULT NULL::text, p_targeted_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_linked_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_recompute_session_progress boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_session_version bigint := NULL::bigint;
  v_refresh_scope_kind text := NULL::text;
  v_current_source_row_count integer := 0;
  v_current_source_identity_count integer := 0;
  v_source_rows_superseded integer := 0;
  v_source_build_jobs_superseded integer := 0;
  v_scope_rows_repaired integer := 0;
  v_progress_json jsonb := '{}'::jsonb;
  v_counter_reconciled boolean := false;
  v_progress_state text := NULL::text;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_session_progress_lock_acquired boolean := false;
  v_reconciliation_deferred boolean := false;
  v_reconciliation_deferred_reason text := NULL::text;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  IF p_source_build_run_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED')::text;
  END IF;

  IF p_source_change_seq IS NULL OR p_source_change_seq < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED')::text;
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SOURCE_LINES_TABLE_MISSING',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  v_session_version := COALESCE(p_session_version, v_session_row.version);
  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(p_refresh_scope_kind, ''))), '');

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets ON COMMIT DROP AS
    SELECT DISTINCT scope_ids.timesheet_id
    FROM (
      SELECT NULLIF(BTRIM(target_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS target_values(value)
      WHERE NULLIF(BTRIM(target_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION

      SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_linked_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_linked_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS scope_ids
    WHERE scope_ids.timesheet_id IS NOT NULL;

  SELECT COUNT(*)::integer,
         COUNT(DISTINCT jsonb_build_object(
           'timesheet_id', COALESCE(current_source.timesheet_id::text, '00000000-0000-0000-0000-000000000000'),
           'line_key', current_source.line_key,
           'parent_line_key', COALESCE(current_source.parent_line_key, ''),
           'split_suffix', COALESCE(current_source.split_suffix, ''),
           'section', COALESCE(current_source.section, '')
         ))::integer
  INTO v_current_source_row_count,
       v_current_source_identity_count
  FROM public.banking_pay_workbench_candidate_source_lines AS current_source
  WHERE current_source.session_id = p_session_id
    AND current_source.candidate_id = p_candidate_id
    AND current_source.session_version = v_session_version
    AND current_source.source_build_run_id = p_source_build_run_id
    AND current_source.source_change_seq = p_source_change_seq
    AND current_source.status = 'CURRENT';

  IF COALESCE(v_current_source_row_count, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SUCCESSFUL_SOURCE_BUILD_HAS_NO_CURRENT_SOURCE_ROWS',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'source_rows_superseded', 0,
      'source_build_jobs_superseded', 0,
      'scope_rows_repaired', 0,
      'deferred', false,
      'progress_recomputed', false,
      'counter_reconciled', false,
      'retry_safe', true
    );
  END IF;

  WITH current_identity AS (
    SELECT DISTINCT
      current_source.timesheet_id,
      current_source.line_key,
      current_source.parent_line_key,
      current_source.split_suffix,
      current_source.section
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
  ), source_rows_to_supersede AS (
    SELECT older_source.id,
           older_source.status AS previous_status
    FROM public.banking_pay_workbench_candidate_source_lines AS older_source
    JOIN current_identity AS current_source
      ON COALESCE(older_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
           = COALESCE(current_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND older_source.line_key = current_source.line_key
     AND COALESCE(older_source.parent_line_key, '') = COALESCE(current_source.parent_line_key, '')
     AND COALESCE(older_source.split_suffix, '') = COALESCE(current_source.split_suffix, '')
     AND COALESCE(older_source.section, '') = COALESCE(current_source.section, '')
    WHERE older_source.session_id = p_session_id
      AND older_source.candidate_id = p_candidate_id
      AND older_source.session_version = v_session_version
      AND older_source.source_change_seq < p_source_change_seq
      AND UPPER(BTRIM(COALESCE(older_source.status, ''))) IN ('CURRENT', 'DIRTY', 'ERROR')
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR older_source.timesheet_id IS NULL
        OR older_source.timesheet_id IN (
          SELECT scoped_timesheets.timesheet_id
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
        )
        OR NOT EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS any_scoped_timesheets
        )
      )
  )
  UPDATE public.banking_pay_workbench_candidate_source_lines AS update_source
  SET status = 'SUPERSEDED',
      source_row_json = jsonb_strip_nulls(
        COALESCE(update_source.source_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'previous_status', source_rows_to_supersede.previous_status,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_rows_to_supersede
  WHERE update_source.id = source_rows_to_supersede.id;

  GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;

  WITH successful_scope_timesheets AS (
    SELECT DISTINCT current_source.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
      AND current_source.timesheet_id IS NOT NULL

    UNION

    SELECT scoped_timesheets.timesheet_id
    FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
  ), source_build_jobs_to_supersede AS (
    SELECT
      job_row.id,
      job_seq.job_source_change_seq,
      job_scope_kind.job_refresh_scope_kind,
      job_scope.scoped_timesheet_count,
      job_scope.success_scope_overlap_count
    FROM public.banking_pay_workbench_jobs AS job_row
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN COALESCE(job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_seq')::bigint
        WHEN COALESCE(job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_sequence')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_sequence}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_sequence}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{result_json,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{completion_json,result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{completion_json,result_json,source_change_seq}')::bigint
        ELSE NULL::bigint
      END AS job_source_change_seq
    ) AS job_seq
    CROSS JOIN LATERAL (
      SELECT NULLIF(UPPER(BTRIM(COALESCE(
        job_row.payload_json->>'refresh_scope_kind',
        job_row.payload_json#>>'{source_build,refresh_scope_kind}',
        job_row.payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
        job_row.payload_json#>>'{result_json,refresh_scope_kind}',
        job_row.payload_json#>>'{completion_json,result_json,refresh_scope_kind}',
        ''
      ))), '') AS job_refresh_scope_kind
    ) AS job_scope_kind
    CROSS JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS scoped_timesheet_count,
        COUNT(*) FILTER (
          WHERE job_scope_timesheet_ids.timesheet_id IN (
            SELECT successful_scope_timesheets.timesheet_id
            FROM successful_scope_timesheets
          )
        )::integer AS success_scope_overlap_count
      FROM (
        SELECT DISTINCT parsed_job_scope_values.timesheet_id_text::uuid AS timesheet_id
        FROM (
          SELECT NULLIF(BTRIM(target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS target_values(value)

          UNION

          SELECT NULLIF(BTRIM(target_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS target_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_target_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids') = 'array' THEN job_row.payload_json->'linked_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'linked_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS linked_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,linked_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(COALESCE(
            job_row.payload_json->>'timesheet_id',
            job_row.payload_json->>'real_business_timesheet_id',
            job_row.payload_json#>>'{trigger,timesheet_id}',
            job_row.payload_json#>>'{source_build,timesheet_id}',
            job_row.payload_json#>>'{source_build,real_business_timesheet_id}',
            job_row.payload_json#>>'{result_json,timesheet_id}',
            ''
          )), '') AS timesheet_id_text
        ) AS parsed_job_scope_values
        WHERE parsed_job_scope_values.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS job_scope_timesheet_ids
    ) AS job_scope
    WHERE job_row.session_id = p_session_id
      AND job_row.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(job_row.status, ''))) IN ('FAILED', 'DEAD')
      AND CASE
            WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN (
              'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
              'CANDIDATE_SOURCE_BUILD',
              'CANDIDATE_SOURCE_BUILD_CHUNK',
              'SOURCE_BUILD',
              'SOURCE_BUILD_PAGE'
            ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            ELSE UPPER(BTRIM(COALESCE(job_row.job_type, '')))
          END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND NOT (
        COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_by_newer_session_version_at_utc'
        OR COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_at_utc'
        OR UPPER(BTRIM(COALESCE(job_row.last_error_json->>'code', ''))) = 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION'
      )
      AND (
        COALESCE(job_row.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
        OR (job_row.payload_json->>'session_version')::bigint = v_session_version
      )
      AND job_seq.job_source_change_seq < p_source_change_seq
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR COALESCE(job_scope.success_scope_overlap_count, 0) > 0
        OR (
          COALESCE(job_scope.scoped_timesheet_count, 0) = 0
          AND COALESCE(job_scope_kind.job_refresh_scope_kind, '') IN ('', 'TARGETED_TIMESHEETS')
        )
      )
  )
  UPDATE public.banking_pay_workbench_jobs AS update_job
  SET payload_json = jsonb_strip_nulls(
        COALESCE(update_job.payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'superseded_refresh_scope_kind', v_refresh_scope_kind,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_build_jobs_to_supersede
  WHERE update_job.id = source_build_jobs_to_supersede.id;

  GET DIAGNOSTICS v_source_build_jobs_superseded = ROW_COUNT;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
          WHERE line_work_pending.session_id = p_session_id
            AND line_work_pending.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) IN ('PENDING', 'READY', 'RUNNING', 'PROCESSING', 'QUEUED')
        ) THEN scope_update.status
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
          WHERE line_work_ready.session_id = p_session_id
            AND line_work_ready.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) IN ('MATERIALISED', 'MATERIALIZED')
        ) THEN 'MATERIALISED'
        ELSE 'SOURCE_READY'
      END,
      dirty = false,
      error_json = CASE
        WHEN scope_update.error_json IS NULL
          OR scope_update.error_json = '{}'::jsonb
          OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
            'SOURCE_BUILD_ERROR',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            '42P01'
          )
          THEN NULL::jsonb
        ELSE scope_update.error_json
      END,
      pending_job_id = CASE
        WHEN scope_update.pending_job_id = p_success_job_id THEN NULL::uuid
        WHEN scope_update.pending_job_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_jobs AS active_pending_job
            WHERE active_pending_job.id = scope_update.pending_job_id
              AND UPPER(BTRIM(COALESCE(active_pending_job.status, ''))) IN ('QUEUED', 'RUNNING')
          ) THEN NULL::uuid
        ELSE scope_update.pending_job_id
      END,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id
    AND (
      COALESCE(scope_update.dirty, false) IS TRUE
      OR UPPER(BTRIM(COALESCE(scope_update.status, ''))) IN ('SOURCE_BUILD_ERROR', 'ERROR', 'FAILED')
      OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
        'SOURCE_BUILD_ERROR',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        '42P01'
      )
      OR scope_update.pending_job_id = p_success_job_id
    )
    AND EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS current_source_exists
      WHERE current_source_exists.session_id = p_session_id
        AND current_source_exists.candidate_id = p_candidate_id
        AND current_source_exists.session_version = v_session_version
        AND current_source_exists.source_build_run_id = p_source_build_run_id
        AND current_source_exists.source_change_seq = p_source_change_seq
        AND current_source_exists.status = 'CURRENT'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS unresolved_source_row
      WHERE unresolved_source_row.session_id = p_session_id
        AND unresolved_source_row.candidate_id = p_candidate_id
        AND unresolved_source_row.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(unresolved_source_row.status, ''))) IN ('DIRTY', 'ERROR')
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_jobs AS active_source_job
      WHERE active_source_job.session_id = p_session_id
        AND active_source_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(active_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
        AND CASE
              WHEN UPPER(BTRIM(COALESCE(active_source_job.job_type, ''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE'
              ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              ELSE UPPER(BTRIM(COALESCE(active_source_job.job_type, '')))
            END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND (
          COALESCE(active_source_job.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
          OR (active_source_job.payload_json->>'session_version')::bigint = v_session_version
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS line_work_error
      WHERE line_work_error.session_id = p_session_id
        AND line_work_error.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(line_work_error.status, ''))) IN ('ERROR', 'FAILED')
    );

  GET DIAGNOSTICS v_scope_rows_repaired = ROW_COUNT;

  IF COALESCE(p_recompute_session_progress, true) THEN
    BEGIN
      PERFORM 1
      FROM public.banking_pay_workbench_sessions AS session_progress_lock
      WHERE session_progress_lock.id = p_session_id
        AND UPPER(BTRIM(COALESCE(session_progress_lock.status, ''))) = 'OPEN'
        AND session_progress_lock.discarded_at_utc IS NULL
        AND COALESCE(session_progress_lock.version, 1) = COALESCE(v_session_version, 1)
        AND session_progress_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_progress_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      v_session_progress_lock_acquired := FOUND;
    EXCEPTION
      WHEN lock_not_available THEN
        v_session_progress_lock_acquired := false;
        v_reconciliation_deferred := true;
        v_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_session_progress_lock_acquired THEN
      v_progress_json := public.pay_workbench_session_get_progress_light(p_session_id);

      IF COALESCE((v_progress_json->>'ok')::boolean, false) THEN
      v_progress_state := UPPER(BTRIM(COALESCE(v_progress_json->>'progress_state', v_progress_json->>'phase', '')));
      IF v_progress_state = '' THEN
        v_progress_state := v_session_row.progress_state;
      END IF;

      v_section_counts_json := CASE
        WHEN jsonb_typeof(v_progress_json->'section_counts_json') = 'object'
          THEN v_progress_json->'section_counts_json'
        ELSE '{}'::jsonb
      END;
      v_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(v_progress_json->'candidate_sample_rows_json') = 'array'
          THEN v_progress_json->'candidate_sample_rows_json'
        ELSE '[]'::jsonb
      END;

      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_total_count = CASE WHEN COALESCE(v_progress_json->>'scope_total_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_total_count')::integer ELSE COALESCE(session_update.scope_total_count, 0) END,
          scope_seeded_count = CASE WHEN COALESCE(v_progress_json->>'scope_seeded_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_seeded_count')::integer ELSE COALESCE(session_update.scope_seeded_count, 0) END,
          scope_ready_count = CASE WHEN COALESCE(v_progress_json->>'scope_ready_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_ready_count')::integer ELSE COALESCE(session_update.scope_ready_count, 0) END,
          scope_pending_count = CASE WHEN COALESCE(v_progress_json->>'scope_pending_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_pending_count')::integer ELSE COALESCE(session_update.scope_pending_count, 0) END,
          scope_failed_count = CASE WHEN COALESCE(v_progress_json->>'scope_failed_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_failed_count')::integer ELSE COALESCE(session_update.scope_failed_count, 0) END,
          -- A23 (PRE-EXISTING SB02 fix, AA-B2): progress_light's 'line_units_total' is the DISPLAY figure
          -- GREATEST(line work, preview rows); its ready/pending/failed are RAW line-work counts that partition
          -- every line-work row. Persist the raw total (their sum) so the column counts the same thing as
          -- line_units_ready, exactly as pay_workbench_session_recompute_progress_counters(p_apply => true) does.
          line_units_total = CASE
            WHEN COALESCE(v_progress_json->>'line_units_ready', '') ~ '^-?[0-9]+$'
             AND COALESCE(v_progress_json->>'line_units_pending', '') ~ '^-?[0-9]+$'
             AND COALESCE(v_progress_json->>'line_units_failed', '') ~ '^-?[0-9]+$'
              THEN (v_progress_json->>'line_units_ready')::integer
                 + (v_progress_json->>'line_units_pending')::integer
                 + (v_progress_json->>'line_units_failed')::integer
            ELSE COALESCE(session_update.line_units_total, 0)
          END,
          line_units_pending = CASE WHEN COALESCE(v_progress_json->>'line_units_pending', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_pending')::integer ELSE COALESCE(session_update.line_units_pending, 0) END,
          line_units_ready = CASE WHEN COALESCE(v_progress_json->>'line_units_ready', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_ready')::integer ELSE COALESCE(session_update.line_units_ready, 0) END,
          line_units_failed = CASE WHEN COALESCE(v_progress_json->>'line_units_failed', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_failed')::integer ELSE COALESCE(session_update.line_units_failed, 0) END,
          preview_row_count = CASE WHEN COALESCE(v_progress_json->>'preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'preview_row_count')::integer ELSE COALESCE(session_update.preview_row_count, 0) END,
          selected_row_count = CASE WHEN COALESCE(v_progress_json->>'selected_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'selected_row_count')::integer ELSE COALESCE(session_update.selected_row_count, 0) END,
          section_counts_json = v_section_counts_json,
          candidate_sample_rows_json = v_candidate_sample_rows_json,
          progress_state = COALESCE(NULLIF(v_progress_state, ''), session_update.progress_state),
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || COALESCE(v_progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_source_build_reconciliation', jsonb_build_object(
                'applied_at_utc', v_now::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', p_source_build_run_id::text,
                'source_change_seq', p_source_change_seq,
                'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
                'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
                'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0)
              ),
              'counter_reconciled', true,
              'counter_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = p_session_id
      RETURNING session_update.*
      INTO v_session_row;

        v_counter_reconciled := true;
      END IF;
    ELSIF v_reconciliation_deferred IS NOT TRUE THEN
      v_reconciliation_deferred := true;
      v_reconciliation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
    END IF;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_source_build_reconciliation',
    p_session_id::text,
    'RECONCILE_SUCCESSFUL_SOURCE_BUILD',
    NULL::jsonb,
    jsonb_build_object(
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'current_source_row_count', COALESCE(v_current_source_row_count, 0),
      'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
      'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
      'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
      'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
      'deferred', COALESCE(v_reconciliation_deferred, false),
      'deferred_reason', v_reconciliation_deferred_reason,
      'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
      'counter_reconciled', COALESCE(v_counter_reconciled, false),
      'retry_safe', COALESCE(v_reconciliation_deferred, false),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    'NEWER_SOURCE_BUILD_SUCCEEDED',
    v_session_row.actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'skipped', false,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_build_run_id', p_source_build_run_id::text,
    'source_change_seq', p_source_change_seq,
    'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
    'refresh_scope_kind', v_refresh_scope_kind,
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
    'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
    'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
    'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
    'deferred', COALESCE(v_reconciliation_deferred, false),
    'reason', v_reconciliation_deferred_reason,
    'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
    'counter_reconciled', COALESCE(v_counter_reconciled, false),
    'progress_phase', CASE WHEN v_progress_json = '{}'::jsonb THEN NULL ELSE v_progress_json->>'phase' END,
    'progress_blocker_codes', CASE WHEN v_progress_json = '{}'::jsonb THEN '[]'::jsonb ELSE COALESCE(v_progress_json->'blocker_codes', '[]'::jsonb) END,
    'retry_safe', COALESCE(v_reconciliation_deferred, false),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$
;

-- [REPLACES] public.pay_workbench_scope_blocker_state_v1(p_session_id uuid, p_target_generation bigint, p_operation_id uuid)  winner piece A27
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_blocker_state_v1(p_session_id uuid, p_target_generation bigint, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_session_active integer := 0;
  v_session_failed integer := 0;
  v_broad_pending integer := 0;
  v_unknown_relevance integer := 0;
  v_active_sample jsonb := '[]'::jsonb;
  v_failure_sample jsonb := '[]'::jsonb;
  v_session_active_sample jsonb := '[]'::jsonb;
  v_session_failure_sample jsonb := '[]'::jsonb;
  -- A14 (F-DRAFT-04): read only live / possibly-UNKNOWN generated rows and their complete work-identity
  -- partitions instead of every dirty/fan-out row ever written.
  v_unknown_possible boolean := false;
  v_prefilter_candidate_id uuid := NULL::uuid;
  v_prefilter_path jsonpath := NULL::jsonpath;
  -- A27 (Draft perf)
  v_light boolean := false;
  v_operation_candidate_ids uuid[] := NULL::uuid[];
  v_operation_path jsonpath := NULL::jsonpath;
  v_unknown_terminal integer := 0;
BEGIN
  IF p_session_id IS NULL OR p_target_generation IS NULL OR p_target_generation < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_INPUT_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.workbench_session_id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_OPERATION_MISMATCH'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'candidate_id', v_session.filters_json->>'candidateId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(
      v_session.filters_json->>'candidate_id',
      v_session.filters_json->>'candidateId'
    )::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'client_id', v_session.filters_json->>'clientId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(
      v_session.filters_json->>'client_id',
      v_session.filters_json->>'clientId'
    )::uuid;
  END IF;

  -- A27: sessions with no operation and no Candidate filter (unfiltered, or Client-only) take the light path below.
  -- A Client-only filter classifies every dirty-apply row UNKNOWN and unknown_relevance_count counts them over the
  -- whole history; the light path counts the identities made only of SUCCEEDED dirty-apply rows from index columns.
  v_light := p_operation_id IS NULL AND v_filter_candidate_id IS NULL;
  v_unknown_possible := p_operation_id IS NOT NULL OR v_filter_candidate_id IS NOT NULL;
  IF p_operation_id IS NOT NULL THEN
    -- A27: the operation's Candidate set for the live-seed prefilter, and one strict jsonpath that matches a payload
    -- candidate_id / processed_candidate_id / candidate_ids[] string equal (case-insensitively) to one of them. As
    -- A14's Candidate prefilter: the original rule (value ~* uuid pattern AND value::uuid in the set) is a
    -- case-insensitive exact match of a canonical uuid text. An empty set gives no path, so no payload names it.
    SELECT COALESCE(array_agg(DISTINCT operation_scope.candidate_id ORDER BY operation_scope.candidate_id), ARRAY[]::uuid[])
    INTO v_operation_candidate_ids
    FROM public.banking_pay_operation_candidate_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND operation_scope.candidate_id IS NOT NULL;
    IF cardinality(v_operation_candidate_ids) > 0 THEN
      v_operation_path := format(
        'strict $ ? (@.candidate_id like_regex %1$s flag "i" || @.processed_candidate_id like_regex %1$s flag "i"'
          || ' || exists (@.candidate_ids[*] ? (@ like_regex %1$s flag "i")))',
        to_json('^(' || array_to_string(v_operation_candidate_ids::text[], '|') || ')$')::text
      )::jsonpath;
    END IF;
  END IF;
  IF p_operation_id IS NULL THEN
    v_prefilter_candidate_id := v_filter_candidate_id;
    IF v_prefilter_candidate_id IS NOT NULL THEN
      v_prefilter_path := format(
        'strict $ ? (@.candidate_id like_regex %1$s flag "i" || @.processed_candidate_id like_regex %1$s flag "i"'
          || ' || exists (@.candidate_ids[*] ? (@ like_regex %1$s flag "i")))',
        to_json('^' || v_prefilter_candidate_id::text || '$')::text
      )::jsonpath;
    END IF;
  END IF;

  IF v_light THEN
    -- A27 (Draft perf): no operation and no Candidate filter. Here relevance never reads Candidate evidence
    -- (unfiltered: every row RELEVANT; Client-only: a fan-out by its payload scope, every other row UNKNOWN), and the
    -- evidence is read only by the effective-status rules, which apply to FAILED/DEAD rows only. So ranking uses light
    -- columns, and the full row plus evidence is read only for FAILED/DEAD winners. Classification, ranking,
    -- effective-status rules, counts and samples are A14's text.
    WITH generated_seed_rows AS MATERIALIZED (
      -- (a) every live generated row (as A14).
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')
        AND seed_job.scope_change_generation <= p_target_generation
      UNION ALL
      -- (b) Client-only: every SUCCEEDED fan-out row (its relevance depends on its payload scope). Identities with no
      --     seed consist only of SUCCEEDED dirty-apply rows; they are counted in (c) below.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE v_filter_client_id IS NOT NULL
        AND seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status = 'SUCCEEDED'
        AND (seed_job.candidate_id IS NULL OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation <= p_target_generation
    ), generated_seed_identity AS MATERIALIZED (
      SELECT DISTINCT COALESCE(NULLIF(BTRIM(seed_row.dedupe_key), ''), 'JOB:' || seed_row.id::text) AS work_identity
      FROM generated_seed_rows AS seed_row
    ), generated_partition_ids AS MATERIALIZED (
      -- Complete work-identity partitions of the seeds (ranking is per work identity), so each winner is exact.
      SELECT seed_row.id FROM generated_seed_rows AS seed_row
      UNION
      -- same raw dedupe_key (idx_bpay_workbench_jobs_generated_work_authority)
      SELECT same_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT key_job.id
        FROM public.banking_pay_workbench_jobs AS key_job
        WHERE key_job.dedupe_key = seed_identity.work_identity
          AND key_job.scope_change_generation IS NOT NULL
          AND key_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        OFFSET 0
      ) AS same_key
      UNION
      -- dedupe_key with leading/trailing blanks whose BTRIM is the identity (idx_bpay_wb_jobs_generated_padded_key_v1)
      SELECT padded_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT padded_job.id
        FROM public.banking_pay_workbench_jobs AS padded_job
        WHERE md5(BTRIM(padded_job.dedupe_key)) = md5(seed_identity.work_identity)
          AND BTRIM(padded_job.dedupe_key) = seed_identity.work_identity
          AND padded_job.scope_change_generation IS NOT NULL
          AND padded_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND padded_job.dedupe_key <> BTRIM(padded_job.dedupe_key)
        OFFSET 0
      ) AS padded_key
      UNION
      -- blank dedupe_key: identity 'JOB:' || id (primary key)
      SELECT blank_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT blank_job.id
        FROM public.banking_pay_workbench_jobs AS blank_job
        WHERE blank_job.id = CASE
            WHEN seed_identity.work_identity ~* '^JOB:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN SUBSTRING(seed_identity.work_identity FROM 5)::uuid
            ELSE NULL::uuid
          END
          AND NULLIF(BTRIM(blank_job.dedupe_key), '') IS NULL
          AND 'JOB:' || blank_job.id::text = seed_identity.work_identity
        OFFSET 0
      ) AS blank_key
    ), generated_light AS MATERIALIZED (
      SELECT job_row.*
      FROM generated_partition_ids AS partition_row
      CROSS JOIN LATERAL (
        SELECT
          partition_job.id,
          partition_job.job_type,
          partition_job.status,
          partition_job.scope_change_generation,
          partition_job.created_at_utc,
          COALESCE(NULLIF(BTRIM(partition_job.dedupe_key), ''), 'JOB:' || partition_job.id::text) AS work_identity,
          CASE
            WHEN v_filter_client_id IS NULL THEN 'RELEVANT'
            -- A14's Client rule gives UNKNOWN to every row that is not a fan-out.
            WHEN partition_job.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN 'UNKNOWN'
            ELSE (
              -- A14's Client rule and scope columns, verbatim, for a fan-out row.
              SELECT
                CASE
                  WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
                   AND generated_raw.scope_kind = 'CLIENT'
                   AND generated_raw.direct_client_id IS NOT NULL
                    THEN CASE WHEN generated_raw.direct_client_id = v_filter_client_id THEN 'RELEVANT' ELSE 'IRRELEVANT' END
                  WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
                   AND generated_raw.scope_kind = 'CONTRACT'
                   AND generated_raw.direct_contract_id IS NOT NULL
                    THEN CASE
                      WHEN EXISTS (
                        SELECT 1
                        FROM public.contracts AS contract_row
                        WHERE contract_row.id = generated_raw.direct_contract_id
                          AND contract_row.client_id = v_filter_client_id
                      ) THEN 'RELEVANT'
                      ELSE 'IRRELEVANT'
                    END
                  ELSE 'UNKNOWN'
                END
              FROM (
                SELECT
                  partition_job.job_type,
                  UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) AS scope_kind,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) = 'CLIENT'
                     AND COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'client_id', '')
                           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'client_id')::uuid
                    ELSE NULL::uuid
                  END AS direct_client_id,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(partition_job.payload_json->>'scope_kind', ''))) = 'CONTRACT'
                     AND COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'contract_id', '')
                           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN COALESCE(partition_job.payload_json->>'scope_id', partition_job.payload_json->>'contract_id')::uuid
                    ELSE NULL::uuid
                  END AS direct_contract_id
              ) AS generated_raw
            )
          END AS relevance_decision
        FROM public.banking_pay_workbench_jobs AS partition_job
        WHERE partition_job.id = partition_row.id
          AND partition_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND partition_job.scope_change_generation IS NOT NULL
          AND partition_job.scope_change_generation <= p_target_generation
          AND partition_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
        OFFSET 0
      ) AS job_row
    ), generated_winner AS MATERIALIZED (
      SELECT generated_ranked.*
      FROM (
        SELECT
          generated_light.*,
          ROW_NUMBER() OVER (
            -- COLLATE "C": the same partitions (en_US.utf8 is deterministic, so equality is byte equality) with a
            -- byte-wise sort instead of a locale sort; the ORDER BY inside each partition is unchanged.
            PARTITION BY generated_light.work_identity COLLATE "C"
            ORDER BY generated_light.scope_change_generation DESC,
                     generated_light.created_at_utc DESC,
                     generated_light.id DESC
          ) AS authority_ordinal
        FROM generated_light
        WHERE generated_light.relevance_decision <> 'IRRELEVANT'
      ) AS generated_ranked
      WHERE generated_ranked.authority_ordinal = 1
    ), generated_effective AS MATERIALIZED (
      SELECT
        generated_winner.id,
        generated_winner.job_type,
        generated_winner.status,
        generated_winner.scope_change_generation,
        generated_winner.work_identity,
        generated_winner.relevance_decision,
        CASE
          WHEN generated_winner.status IN ('FAILED', 'DEAD') THEN (
            -- A14's effective-status rules, verbatim, on the winner's full row and Candidate evidence.
            SELECT
                CASE
                  -- A terminal row that the normal failure processor has proved obsolete
                  -- is audit history, not current blocking authority.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'non_blocking_terminal_failure', 'false'))) = 'true'
                    THEN 'SUCCEEDED'
                  -- A direct dirty-apply failure is also recovered once every candidate
                  -- asserted by that row has subsequently completed and published a
                  -- generation-fenced build for this exact session version.  The
                  -- original FAILED/DEAD row is immutable history and can have a
                  -- different dedupe key from the replacement source build, so ranking
                  -- by work_identity alone cannot establish recovery.  Require the
                  -- registry and completed build to agree on generation and source
                  -- sequence, and require the registry to have no newer dirty work,
                  -- active build or failure authority.  Partial or stale recovery keeps
                  -- the original terminal row blocking.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND generated_ranked.job_type IN (
                     'WORKBENCH_CANDIDATE_DIRTY_APPLY',
                     'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
                   )
                   AND COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) > 0
                   AND NOT EXISTS (
                     SELECT 1
                     FROM unnest(generated_ranked.candidate_ids) AS recovered_candidate(candidate_id)
                     WHERE NOT EXISTS (
                       SELECT 1
                       FROM private.banking_pay_workbench_candidate_scope_registry AS recovered_registry
                       JOIN private.banking_pay_workbench_economic_builds AS recovered_build
                         ON recovered_build.candidate_id = recovered_registry.candidate_id
                        AND recovered_build.session_id = p_session_id
                        AND recovered_build.session_version = v_session.version
                        AND recovered_build.captured_candidate_generation = recovered_registry.evaluated_generation
                        AND recovered_build.source_change_seq = recovered_registry.current_source_change_seq
                        AND recovered_build.status = 'COMPLETE'
                        AND recovered_build.private_stage = 'COMPLETE'
                        AND recovered_build.completed_at_utc IS NOT NULL
                        AND recovered_build.completed_at_utc >= generated_ranked.created_at_utc
                       WHERE recovered_registry.candidate_id = recovered_candidate.candidate_id
                         AND recovered_registry.initialisation_status = 'READY'
                         AND recovered_registry.current_build_id IS NULL
                         AND recovered_registry.dirty_generation = recovered_registry.evaluated_generation
                         AND recovered_registry.evaluated_generation >= generated_ranked.scope_change_generation
                         AND COALESCE(recovered_registry.failure_json, '{}'::jsonb) = '{}'::jsonb
                     )
                   ) THEN 'SUCCEEDED'
                  -- Backward compatibility for cancellation jobs written before
                  -- supersessions became successful terminal work. Do not trust the flag
                  -- alone: require the exact legacy code and the replacement full-candidate
                  -- job for this session/batch. The replacement's own active/error state is
                  -- evaluated independently with the session pipeline below.
                  WHEN generated_ranked.status IN ('FAILED', 'DEAD')
                   AND generated_ranked.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
                   AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'superseded_by_cancel_full_candidate_refresh', 'false'))) = 'true'
                   AND UPPER(BTRIM(COALESCE(generated_ranked.last_error_json->>'code', '')))
                         = 'WORKBENCH_FINANCE_DIRTY_SUPERSEDED_BY_CANCEL_FULL_CANDIDATE_REFRESH'
                   AND generated_ranked.payload_json->>'superseding_session_id' = p_session_id::text
                   AND COALESCE(generated_ranked.payload_json->>'superseding_pay_batch_id', '')
                         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   AND EXISTS (
                     SELECT 1
                     FROM public.banking_pay_workbench_jobs AS replacement_job
                     WHERE replacement_job.session_id = p_session_id
                       AND replacement_job.job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
                       AND replacement_job.created_at_utc >= generated_ranked.created_at_utc
                       AND COALESCE(
                             replacement_job.payload_json->>'pay_batch_id',
                             replacement_job.payload_json#>>'{source_build,pay_batch_id}',
                             ''
                           ) = generated_ranked.payload_json->>'superseding_pay_batch_id'
                       AND UPPER(BTRIM(COALESCE(
                             replacement_job.payload_json->>'refresh_scope_kind',
                             replacement_job.payload_json#>>'{source_build,refresh_scope_kind}',
                             ''
                           ))) = 'CANDIDATE_FULL_LIVE'
                       AND LOWER(BTRIM(COALESCE(
                             replacement_job.payload_json->>'full_candidate_recovery_reallocation_required',
                             'false'
                           ))) = 'true'
                       AND (
                         COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) = 0
                         OR replacement_job.candidate_id = ANY(generated_ranked.candidate_ids)
                       )
                   ) THEN 'SUCCEEDED'
                  ELSE generated_ranked.status
                END
            FROM (
              SELECT failed_job.*, evidence.candidate_ids
              FROM public.banking_pay_workbench_jobs AS failed_job
              CROSS JOIN LATERAL (
                  SELECT COALESCE(array_agg(DISTINCT candidate_source.candidate_id ORDER BY candidate_source.candidate_id), ARRAY[]::uuid[]) AS candidate_ids
                  FROM (
                    SELECT failed_job.candidate_id
                    WHERE failed_job.candidate_id IS NOT NULL
                    UNION ALL
                    SELECT (failed_job.payload_json->>'candidate_id')::uuid
                    WHERE COALESCE(failed_job.payload_json->>'candidate_id', '')
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    UNION ALL
                    SELECT (failed_job.payload_json->>'processed_candidate_id')::uuid
                    WHERE COALESCE(failed_job.payload_json->>'processed_candidate_id', '')
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    UNION ALL
                    SELECT candidate_value.value::uuid
                    FROM jsonb_array_elements_text(
                      CASE
                        WHEN jsonb_typeof(failed_job.payload_json->'candidate_ids') = 'array'
                          THEN failed_job.payload_json->'candidate_ids'
                        ELSE '[]'::jsonb
                      END
                    ) AS candidate_value(value)
                    WHERE candidate_value.value
                      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  ) AS candidate_source
                ) AS evidence
              WHERE failed_job.id = generated_winner.id
            ) AS generated_ranked
          )
          ELSE generated_winner.status
        END AS effective_status
      FROM generated_winner
    )
    SELECT
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('QUEUED', 'RUNNING')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective
        WHERE job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
          AND effective_status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE relevance_decision = 'UNKNOWN'),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('QUEUED', 'RUNNING')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('FAILED', 'DEAD')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb)
    INTO
      v_upstream_active,
      v_upstream_failed,
      v_broad_pending,
      v_unknown_relevance,
      v_active_sample,
      v_failure_sample;

    IF v_filter_client_id IS NOT NULL THEN
      -- (c) Client-only: an identity whose every row (up to the target) is a SUCCEEDED dirty-apply row has a SUCCEEDED,
      --     UNKNOWN winner under A14's rules, so it adds exactly one to unknown_relevance_count and nothing else. Every
      --     other identity has a seed in (a) or (b) and was counted above. Index columns only
      --     (idx_bpay_workbench_jobs_generated_work_authority carries dedupe_key, id, job_type, status, generation).
      SELECT COUNT(*)::integer
      INTO v_unknown_terminal
      FROM (
        SELECT COALESCE(NULLIF(BTRIM(history_job.dedupe_key), ''), 'JOB:' || history_job.id::text) AS work_identity
        FROM public.banking_pay_workbench_jobs AS history_job
        WHERE history_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND history_job.scope_change_generation IS NOT NULL
          AND history_job.scope_change_generation <= p_target_generation
          AND history_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
        GROUP BY 1
        HAVING bool_and(history_job.status = 'SUCCEEDED' AND history_job.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT')
      ) AS terminal_identity;
      v_unknown_relevance := COALESCE(v_unknown_relevance, 0) + COALESCE(v_unknown_terminal, 0);
    END IF;
  ELSE
    WITH generated_seed_rows AS MATERIALIZED (
      -- (a) every live generated row. FAILED/DEAD stay here: a terminal failure is still a blocker unless the
      --     unchanged effective-status rules below prove it recovered or superseded.
      --     Candidate-filtered sessions skip rows that are provably IRRELEVANT (the unchanged classification
      --     would drop them before ranking): non-fan-out, with a candidate, whose candidate evidence
      --     (column, payload candidate_id / processed_candidate_id / candidate_ids) excludes the filter.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')
        AND seed_job.scope_change_generation <= p_target_generation
          AND (
            v_prefilter_candidate_id IS NULL
            OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
            OR seed_job.candidate_id IS NULL
            OR seed_job.candidate_id = v_prefilter_candidate_id
            -- payload candidate_id / processed_candidate_id / candidate_ids[] naming the filter Candidate: the
            -- original rule (value ~* uuid pattern AND value::uuid = filter) is a case-insensitive exact match of
            -- the filter text; one strict jsonpath pass reads the payload once (non-object payload or non-array
            -- candidate_ids: no match, as in the original).
            OR seed_job.payload_json @? v_prefilter_path
          )
          -- A27: an operation-bound session skips live rows that are provably IRRELEVANT to the operation (the
          -- unchanged classification drops them before ranking): not a fan-out, with a candidate_id outside the
          -- operation's Candidate set, and no payload candidate_id / processed_candidate_id / candidate_ids[] naming a
          -- Candidate of the set (v_operation_path; NULL when the set is empty, so the test is then never true).
          AND (
            v_operation_candidate_ids IS NULL
            OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
            OR seed_job.candidate_id IS NULL
            OR seed_job.candidate_id = ANY(v_operation_candidate_ids)
            OR seed_job.payload_json @? v_operation_path
          )
      UNION ALL
      -- (b) Candidate-filtered or operation-bound sessions only: SUCCEEDED rows whose relevance can be
      --     UNKNOWN (no candidate_id column, or fan-out). unknown_relevance_count counts terminal winners.
      SELECT seed_job.id, seed_job.dedupe_key
      FROM public.banking_pay_workbench_jobs AS seed_job
      WHERE v_unknown_possible
        AND seed_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation IS NOT NULL
        AND seed_job.status = 'SUCCEEDED'
        AND (seed_job.candidate_id IS NULL OR seed_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT')
        AND seed_job.scope_change_generation <= p_target_generation
    ), generated_seed_identity AS MATERIALIZED (
      SELECT DISTINCT COALESCE(NULLIF(BTRIM(seed_row.dedupe_key), ''), 'JOB:' || seed_row.id::text) AS work_identity
      FROM generated_seed_rows AS seed_row
    ), generated_partition_ids AS MATERIALIZED (
      -- Complete work-identity partitions of the seeds (ranking is per work identity), so each winner is exact.
      SELECT seed_row.id FROM generated_seed_rows AS seed_row
      UNION
      -- same raw dedupe_key (idx_bpay_workbench_jobs_generated_work_authority)
      SELECT same_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT key_job.id
        FROM public.banking_pay_workbench_jobs AS key_job
        WHERE key_job.dedupe_key = seed_identity.work_identity
          AND key_job.scope_change_generation IS NOT NULL
          AND key_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
        OFFSET 0
      ) AS same_key
      UNION
      -- dedupe_key with leading/trailing blanks whose BTRIM is the identity (idx_bpay_wb_jobs_generated_padded_key_v1)
      SELECT padded_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT padded_job.id
        FROM public.banking_pay_workbench_jobs AS padded_job
        WHERE md5(BTRIM(padded_job.dedupe_key)) = md5(seed_identity.work_identity)
          AND BTRIM(padded_job.dedupe_key) = seed_identity.work_identity
          AND padded_job.scope_change_generation IS NOT NULL
          AND padded_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
          AND padded_job.dedupe_key <> BTRIM(padded_job.dedupe_key)
        OFFSET 0
      ) AS padded_key
      UNION
      -- blank dedupe_key: identity 'JOB:' || id (primary key)
      SELECT blank_key.id
      FROM generated_seed_identity AS seed_identity
      CROSS JOIN LATERAL (
        SELECT blank_job.id
        FROM public.banking_pay_workbench_jobs AS blank_job
        WHERE blank_job.id = CASE
            WHEN seed_identity.work_identity ~* '^JOB:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN SUBSTRING(seed_identity.work_identity FROM 5)::uuid
            ELSE NULL::uuid
          END
          AND NULLIF(BTRIM(blank_job.dedupe_key), '') IS NULL
          AND 'JOB:' || blank_job.id::text = seed_identity.work_identity
        OFFSET 0
      ) AS blank_key
    ), generated_raw AS MATERIALIZED (
      SELECT
        job_row.*,
        COALESCE(NULLIF(BTRIM(job_row.dedupe_key), ''), 'JOB:' || job_row.id::text) AS work_identity,
        UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) AS scope_kind,
        COALESCE(
          NULLIF(BTRIM(job_row.payload_json->>'scope_id'), ''),
          NULLIF(BTRIM(job_row.payload_json->>'client_id'), ''),
          NULLIF(BTRIM(job_row.payload_json->>'contract_id'), '')
        ) AS direct_scope_id,
        evidence.candidate_ids,
        CASE
          WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CLIENT'
           AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id')::uuid
          ELSE NULL::uuid
        END AS direct_client_id,
        CASE
          WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CONTRACT'
           AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id')::uuid
          ELSE NULL::uuid
        END AS direct_contract_id
      FROM generated_partition_ids AS partition_row
      CROSS JOIN LATERAL (
        SELECT partition_job.*
        FROM public.banking_pay_workbench_jobs AS partition_job
        WHERE partition_job.id = partition_row.id
        OFFSET 0
      ) AS job_row
      CROSS JOIN LATERAL (
        SELECT COALESCE(array_agg(DISTINCT candidate_source.candidate_id ORDER BY candidate_source.candidate_id), ARRAY[]::uuid[]) AS candidate_ids
        FROM (
          SELECT job_row.candidate_id
          WHERE job_row.candidate_id IS NOT NULL
          UNION ALL
          SELECT (job_row.payload_json->>'candidate_id')::uuid
          WHERE COALESCE(job_row.payload_json->>'candidate_id', '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          UNION ALL
          SELECT (job_row.payload_json->>'processed_candidate_id')::uuid
          WHERE COALESCE(job_row.payload_json->>'processed_candidate_id', '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          UNION ALL
          SELECT candidate_value.value::uuid
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'candidate_ids') = 'array'
                THEN job_row.payload_json->'candidate_ids'
              ELSE '[]'::jsonb
            END
          ) AS candidate_value(value)
          WHERE candidate_value.value
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS candidate_source
      ) AS evidence
      WHERE job_row.job_type IN (
        'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
        'CONTRACT_CLIENT_DIRTY_FANOUT'
      )
        AND job_row.scope_change_generation IS NOT NULL
        AND job_row.scope_change_generation <= p_target_generation
        AND job_row.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
    ), generated_classified AS MATERIALIZED (
      SELECT
        generated_raw.*,
        CASE
          WHEN p_operation_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
                CASE
                  WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.banking_pay_operation_candidate_scope AS operation_scope
                    WHERE operation_scope.operation_id = p_operation_id
                      AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              WHEN generated_raw.scope_kind = 'CANDIDATE'
               AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
                CASE
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.banking_pay_operation_candidate_scope AS operation_scope
                    WHERE operation_scope.operation_id = p_operation_id
                      AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              ELSE 'UNKNOWN'
            END
          WHEN v_filter_candidate_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
                CASE
                  WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                  WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              WHEN generated_raw.scope_kind = 'CANDIDATE'
               AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
                CASE WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT' ELSE 'IRRELEVANT' END
              ELSE 'UNKNOWN'
            END
          WHEN v_filter_client_id IS NOT NULL THEN
            CASE
              WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
               AND generated_raw.scope_kind = 'CLIENT'
               AND generated_raw.direct_client_id IS NOT NULL
                THEN CASE WHEN generated_raw.direct_client_id = v_filter_client_id THEN 'RELEVANT' ELSE 'IRRELEVANT' END
              WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
               AND generated_raw.scope_kind = 'CONTRACT'
               AND generated_raw.direct_contract_id IS NOT NULL
                THEN CASE
                  WHEN EXISTS (
                    SELECT 1
                    FROM public.contracts AS contract_row
                    WHERE contract_row.id = generated_raw.direct_contract_id
                      AND contract_row.client_id = v_filter_client_id
                  ) THEN 'RELEVANT'
                  ELSE 'IRRELEVANT'
                END
              ELSE 'UNKNOWN'
            END
          ELSE 'RELEVANT'
        END AS relevance_decision
      FROM generated_raw
    ), generated_ranked AS MATERIALIZED (
      SELECT
        generated_classified.*,
        ROW_NUMBER() OVER (
          -- A27: COLLATE "C" gives the same partitions (deterministic collation: equality is byte equality) with a
          -- byte-wise sort; the ORDER BY inside each partition is unchanged.
          PARTITION BY generated_classified.work_identity COLLATE "C"
          ORDER BY generated_classified.scope_change_generation DESC,
                   generated_classified.created_at_utc DESC,
                   generated_classified.id DESC
        ) AS authority_ordinal
      FROM generated_classified
      WHERE generated_classified.relevance_decision <> 'IRRELEVANT'
    ), generated_effective AS MATERIALIZED (
      SELECT
        generated_ranked.*,
        CASE
          -- A terminal row that the normal failure processor has proved obsolete
          -- is audit history, not current blocking authority.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'non_blocking_terminal_failure', 'false'))) = 'true'
            THEN 'SUCCEEDED'
          -- A direct dirty-apply failure is also recovered once every candidate
          -- asserted by that row has subsequently completed and published a
          -- generation-fenced build for this exact session version.  The
          -- original FAILED/DEAD row is immutable history and can have a
          -- different dedupe key from the replacement source build, so ranking
          -- by work_identity alone cannot establish recovery.  Require the
          -- registry and completed build to agree on generation and source
          -- sequence, and require the registry to have no newer dirty work,
          -- active build or failure authority.  Partial or stale recovery keeps
          -- the original terminal row blocking.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND generated_ranked.job_type IN (
             'WORKBENCH_CANDIDATE_DIRTY_APPLY',
             'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
           )
           AND COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) > 0
           AND NOT EXISTS (
             SELECT 1
             FROM unnest(generated_ranked.candidate_ids) AS recovered_candidate(candidate_id)
             WHERE NOT EXISTS (
               SELECT 1
               FROM private.banking_pay_workbench_candidate_scope_registry AS recovered_registry
               JOIN private.banking_pay_workbench_economic_builds AS recovered_build
                 ON recovered_build.candidate_id = recovered_registry.candidate_id
                AND recovered_build.session_id = p_session_id
                AND recovered_build.session_version = v_session.version
                AND recovered_build.captured_candidate_generation = recovered_registry.evaluated_generation
                AND recovered_build.source_change_seq = recovered_registry.current_source_change_seq
                AND recovered_build.status = 'COMPLETE'
                AND recovered_build.private_stage = 'COMPLETE'
                AND recovered_build.completed_at_utc IS NOT NULL
                AND recovered_build.completed_at_utc >= generated_ranked.created_at_utc
               WHERE recovered_registry.candidate_id = recovered_candidate.candidate_id
                 AND recovered_registry.initialisation_status = 'READY'
                 AND recovered_registry.current_build_id IS NULL
                 AND recovered_registry.dirty_generation = recovered_registry.evaluated_generation
                 AND recovered_registry.evaluated_generation >= generated_ranked.scope_change_generation
                 AND COALESCE(recovered_registry.failure_json, '{}'::jsonb) = '{}'::jsonb
             )
           ) THEN 'SUCCEEDED'
          -- Backward compatibility for cancellation jobs written before
          -- supersessions became successful terminal work. Do not trust the flag
          -- alone: require the exact legacy code and the replacement full-candidate
          -- job for this session/batch. The replacement's own active/error state is
          -- evaluated independently with the session pipeline below.
          WHEN generated_ranked.status IN ('FAILED', 'DEAD')
           AND generated_ranked.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
           AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'superseded_by_cancel_full_candidate_refresh', 'false'))) = 'true'
           AND UPPER(BTRIM(COALESCE(generated_ranked.last_error_json->>'code', '')))
                 = 'WORKBENCH_FINANCE_DIRTY_SUPERSEDED_BY_CANCEL_FULL_CANDIDATE_REFRESH'
           AND generated_ranked.payload_json->>'superseding_session_id' = p_session_id::text
           AND COALESCE(generated_ranked.payload_json->>'superseding_pay_batch_id', '')
                 ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND EXISTS (
             SELECT 1
             FROM public.banking_pay_workbench_jobs AS replacement_job
             WHERE replacement_job.session_id = p_session_id
               AND replacement_job.job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND replacement_job.created_at_utc >= generated_ranked.created_at_utc
               AND COALESCE(
                     replacement_job.payload_json->>'pay_batch_id',
                     replacement_job.payload_json#>>'{source_build,pay_batch_id}',
                     ''
                   ) = generated_ranked.payload_json->>'superseding_pay_batch_id'
               AND UPPER(BTRIM(COALESCE(
                     replacement_job.payload_json->>'refresh_scope_kind',
                     replacement_job.payload_json#>>'{source_build,refresh_scope_kind}',
                     ''
                   ))) = 'CANDIDATE_FULL_LIVE'
               AND LOWER(BTRIM(COALESCE(
                     replacement_job.payload_json->>'full_candidate_recovery_reallocation_required',
                     'false'
                   ))) = 'true'
               AND (
                 COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) = 0
                 OR replacement_job.candidate_id = ANY(generated_ranked.candidate_ids)
               )
           ) THEN 'SUCCEEDED'
          ELSE generated_ranked.status
        END AS effective_status
      FROM generated_ranked
      WHERE authority_ordinal = 1
    )
    SELECT
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('QUEUED', 'RUNNING')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective
        WHERE job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
          AND effective_status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')),
      (SELECT COUNT(*)::integer FROM generated_effective WHERE relevance_decision = 'UNKNOWN'),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('QUEUED', 'RUNNING')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb),
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'job_id', limited_job.id::text,
          'job_type', limited_job.job_type,
          'status', limited_job.effective_status,
          'scope_change_generation', limited_job.scope_change_generation,
          'dedupe_key', limited_job.work_identity,
          'relevance', limited_job.relevance_decision
        ) ORDER BY limited_job.scope_change_generation, limited_job.id)
        FROM (
          SELECT * FROM generated_effective
          WHERE effective_status IN ('FAILED', 'DEAD')
          ORDER BY scope_change_generation, id
          LIMIT 25
        ) AS limited_job
      ), '[]'::jsonb)
    INTO
      v_upstream_active,
      v_upstream_failed,
      v_broad_pending,
      v_unknown_relevance,
      v_active_sample,
      v_failure_sample;
  END IF;

  -- Session job rows are immutable execution history. Their raw FAILED/DEAD
  -- status is not durable readiness authority because a later current-state
  -- rebuild may have recovered the candidate under a different dedupe key.
  -- Active work remains a blocker. Terminal failure authority is held by the
  -- session's recomputed scope/line failure counters, which the worker updates
  -- from current candidate state and clears after a successful recovery.
  WITH session_active AS MATERIALIZED (
    SELECT
      session_job.*,
      COALESCE(NULLIF(BTRIM(session_job.dedupe_key), ''), 'JOB:' || session_job.id::text) AS work_identity
    FROM public.banking_pay_workbench_jobs AS session_job
    WHERE session_job.session_id = p_session_id
      AND session_job.job_type IN (
        'WORKBENCH_SESSION_SCOPE_SEED',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'WORKBENCH_SESSION_CLONE_REBASE',
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
        'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      )
      AND session_job.status IN ('QUEUED', 'RUNNING')
  )
  SELECT
    (SELECT COUNT(*)::integer FROM session_active),
    0::integer,
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', limited_job.id::text,
        'job_type', limited_job.job_type,
        'status', limited_job.status,
        'dedupe_key', limited_job.work_identity
      ) ORDER BY limited_job.created_at_utc, limited_job.id)
      FROM (
        SELECT * FROM session_active
        ORDER BY created_at_utc, id
        LIMIT 25
      ) AS limited_job
    ), '[]'::jsonb),
    '[]'::jsonb
  INTO
    v_session_active,
    v_session_failed,
    v_session_active_sample,
    v_session_failure_sample;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_active_sample
  FROM jsonb_array_elements(COALESCE(v_active_sample, '[]'::jsonb) || COALESCE(v_session_active_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_failure_sample
  FROM jsonb_array_elements(COALESCE(v_failure_sample, '[]'::jsonb) || COALESCE(v_session_failure_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'target_generation', p_target_generation,
    'upstream_active_count', COALESCE(v_upstream_active, 0),
    'upstream_unresolved_failure_count', COALESCE(v_upstream_failed, 0),
    'session_active_count', COALESCE(v_session_active, 0),
    'session_unresolved_failure_count', COALESCE(v_session_failed, 0),
    'session_scope_failed_count', COALESCE(v_session.scope_failed_count, 0),
    'session_line_failed_count', COALESCE(v_session.line_units_failed, 0),
    'broad_root_pending_count', COALESCE(v_broad_pending, 0),
    'unknown_relevance_count', COALESCE(v_unknown_relevance, 0),
    'active_sample', COALESCE(v_active_sample, '[]'::jsonb),
    'failure_sample', COALESCE(v_failure_sample, '[]'::jsonb),
    'all_clear',
      COALESCE(v_upstream_active, 0) = 0
      AND COALESCE(v_upstream_failed, 0) = 0
      AND COALESCE(v_session_active, 0) = 0
      AND COALESCE(v_session_failed, 0) = 0
      AND COALESCE(v_session.scope_failed_count, 0) = 0
      AND COALESCE(v_session.line_units_failed, 0) = 0
  );
END;
$function$;

-- [REPLACES] public.pay_workbench_scope_reconcile_drain_one_v1(p_candidate_limit integer, p_worker_id text)  winner piece A23
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_reconcile_drain_one_v1(p_candidate_limit integer DEFAULT 25, p_worker_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_limit integer := LEAST(GREATEST(COALESCE(p_candidate_limit, 25), 1), 50);
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_enabled boolean := true;
  v_config_shadow boolean := false;
  v_mode text := 'AUTHORITATIVE';
  v_target bigint := 0;
  v_current_generation bigint := 0;
  v_base_generation bigint := 0;
  v_cursor_generation bigint := 0;
  v_cursor_entity_key text := '';
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_last_generation bigint := 0;
  v_last_entity_key text := '';
  v_shortlist jsonb := '[]'::jsonb;
  v_admission jsonb := '{}'::jsonb;
  v_eligible jsonb := '[]'::jsonb;
  v_inserted jsonb := '[]'::jsonb;
  v_inserted_count integer := 0;
  v_enqueue jsonb := '{}'::jsonb;
  v_blocker jsonb := '{}'::jsonb;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_more_sessions boolean := false;
  v_already_in_scope integer := 0;
  v_would_admit integer := 0;
  v_would_reject integer := 0;
  v_shadow_summary jsonb := '{}'::jsonb;
  v_shadow_previous jsonb := '{}'::jsonb;
  v_shadow_sample jsonb := '[]'::jsonb;
  v_error_message text;
  v_error_detail text;
  v_error_state text;
BEGIN
  SELECT queued_job.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS queued_job
  WHERE UPPER(BTRIM(COALESCE(queued_job.job_type, ''))) = 'WORKBENCH_SCOPE_RECONCILE'
    AND queued_job.status = 'QUEUED'
    AND queued_job.run_at_utc <= v_now
  ORDER BY queued_job.priority, queued_job.run_at_utc, queued_job.created_at_utc, queued_job.id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'processed', false, 'reason', 'NO_DUE_COORDINATOR');
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS claimed_job
  SET status = 'RUNNING',
      started_at_utc = v_now,
      updated_at_utc = v_now,
      payload_json = COALESCE(claimed_job.payload_json, '{}'::jsonb)
        || jsonb_build_object('worker_id', COALESCE(NULLIF(BTRIM(p_worker_id), ''), 'SCOPE_RECONCILE'))
  WHERE claimed_job.id = v_job.id
  RETURNING claimed_job.* INTO v_job;

  BEGIN
    SELECT
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_enabled, true),
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
    INTO v_enabled, v_config_shadow
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    IF NOT COALESCE(v_enabled, true) THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completion_reason', 'SCOPE_RECONCILIATION_DISABLED'),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'SUCCEEDED', 'reason', 'SCOPE_RECONCILIATION_DISABLED');
    END IF;

    v_mode := UPPER(BTRIM(COALESCE(
      v_job.payload_json->>'reconcile_mode',
      CASE WHEN v_config_shadow THEN 'SHADOW' ELSE 'AUTHORITATIVE' END
    )));
    IF v_mode NOT IN ('SHADOW', 'AUTHORITATIVE') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILE_MODE_INVALID'
        USING ERRCODE = '22023';
    END IF;

    IF v_config_shadow AND v_mode = 'AUTHORITATIVE' THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('reconcile_mode', 'SHADOW', 'shadow_mode', true),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'CONVERTED_TO_SHADOW');
    END IF;

    v_current_generation := public.pay_workbench_scope_current_generation_v1();
    v_target := CASE
      WHEN COALESCE(v_job.payload_json->>'target_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'target_generation')::bigint
      ELSE 0
    END;
    v_target := GREATEST(v_target, v_current_generation);

    UPDATE public.banking_pay_workbench_jobs AS coordinator_job
    SET scope_change_generation = v_target,
        payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('target_generation', v_target, 'reconcile_mode', v_mode),
        updated_at_utc = v_now
    WHERE coordinator_job.id = v_job.id;

    IF COALESCE(v_job.payload_json->>'active_session_id', '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = (v_job.payload_json->>'active_session_id')::uuid
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      FOR UPDATE;
    END IF;

    IF v_session.id IS NULL THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      ORDER BY session_row.session_signature, session_row.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1;
    END IF;
    IF v_session.id IS NULL THEN
      SELECT generation_counter.seq
      INTO v_current_generation
      FROM public.app_change_counters AS generation_counter
      WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
      FOR UPDATE;

      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS lagging_session
        WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
          AND lagging_session.discarded_at_utc IS NULL
          AND lagging_session.replacement_session_id IS NULL
          AND COALESCE(lagging_session.scope_seed_complete, false)
          AND (
            (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
            OR
            (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
          )
      ) INTO v_more_sessions;

      IF v_current_generation > v_target OR v_more_sessions THEN
        UPDATE public.banking_pay_workbench_jobs AS coordinator_job
        SET status = 'QUEUED',
            run_at_utc = v_now,
            started_at_utc = NULL::timestamptz,
            failed_at_utc = NULL::timestamptz,
            last_error_json = NULL::jsonb,
            payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
              - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
              || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
            scope_change_generation = v_current_generation,
            updated_at_utc = v_now
        WHERE coordinator_job.id = v_job.id;
        RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'NEW_GENERATION_OR_SESSION_LAG');
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'SUCCEEDED',
        'target_generation', v_target, 'reconcile_mode', v_mode
      );
    END IF;

    v_base_generation := CASE
      WHEN v_mode = 'SHADOW' THEN COALESCE(v_session.scope_change_generation_shadow_checked, 0)
      ELSE COALESCE(v_session.scope_change_generation_applied, 0)
    END;
    v_cursor_generation := CASE
      WHEN COALESCE(v_job.payload_json->>'cursor_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'cursor_generation')::bigint
      ELSE v_base_generation
    END;
    v_cursor_entity_key := COALESCE(v_job.payload_json->>'cursor_entity_key', '');

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET scope_change_generation_target = CASE
          WHEN v_mode = 'AUTHORITATIVE' THEN v_target
          ELSE session_update.scope_change_generation_target
        END,
        progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_reconcile_status', CASE WHEN v_mode = 'SHADOW' THEN 'SHADOW_RUNNING' ELSE 'RUNNING' END,
            'scope_reconcile_mode', v_mode,
            'scope_change_generation_target', v_target,
            'scope_change_generation_applied', COALESCE(session_update.scope_change_generation_applied, 0),
            'scope_change_generation_shadow_checked', COALESCE(session_update.scope_change_generation_shadow_checked, 0)
          ),
        updated_at_utc = v_now
    WHERE session_update.id = v_session.id;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '30 seconds',
          started_at_utc = NULL::timestamptz,
          last_error_json = jsonb_build_object(
            'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
            'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
            'target_generation', v_target
          ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', false, 'processed', true, 'status', 'QUEUED',
        'reason', 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED',
        'target_generation', v_target,
        'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb)
      );
    END IF;

    -- A previously observed blocker may have recovered under the promoted
    -- generation target. Clear stale coordinator error evidence before waiting
    -- for active work or processing the next bounded page.
    UPDATE public.banking_pay_workbench_jobs AS recovered_coordinator
    SET failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE recovered_coordinator.id = v_job.id;

    IF v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '1 second',
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'upstream_wait_count', v_upstream_active
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'QUEUED',
        'reason', 'WAITING_FOR_UPSTREAM', 'upstream_count', v_upstream_active
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp._bpay_scope_reconcile_page;
    CREATE TEMP TABLE _bpay_scope_reconcile_page ON COMMIT DROP AS
    SELECT candidate_change.entity_key,
           candidate_change.scope_change_generation,
           SUBSTRING(candidate_change.entity_key FROM 15)::uuid AS candidate_id,
           ROW_NUMBER() OVER (
             ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
           ) AS page_ordinal
    FROM public.app_change_counters AS candidate_change
    WHERE candidate_change.entity_key LIKE 'pay_candidate:%'
      AND candidate_change.entity_key
            ~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND candidate_change.scope_change_generation > v_base_generation
      AND candidate_change.scope_change_generation <= v_target
      AND (
        candidate_change.scope_change_generation > v_cursor_generation
        OR (
          candidate_change.scope_change_generation = v_cursor_generation
          AND candidate_change.entity_key > v_cursor_entity_key
        )
      )
    ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
    LIMIT (v_limit + 1);

    SELECT COUNT(*)::integer,
           EXISTS (SELECT 1 FROM pg_temp._bpay_scope_reconcile_page WHERE page_ordinal > v_limit)
    INTO v_page_count, v_has_more
    FROM pg_temp._bpay_scope_reconcile_page
    WHERE page_ordinal <= v_limit;

    SELECT COUNT(*)::integer
    INTO v_already_in_scope
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    SELECT COALESCE(
             jsonb_agg(to_jsonb(page_row.candidate_id::text) ORDER BY page_row.page_ordinal),
             '[]'::jsonb
           )
    INTO v_shortlist
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    IF jsonb_array_length(v_shortlist) > 0 THEN
      v_admission := public.pay_workbench_scope_admission_candidates_v1(
        v_session.id,
        v_shortlist,
        v_target
      );
      v_eligible := CASE
        WHEN jsonb_typeof(v_admission->'candidate_ids') = 'array' THEN v_admission->'candidate_ids'
        ELSE '[]'::jsonb
      END;
    ELSE
      v_eligible := '[]'::jsonb;
    END IF;

    v_would_admit := jsonb_array_length(v_eligible);
    v_would_reject := GREATEST(jsonb_array_length(v_shortlist) - v_would_admit, 0);
    IF v_mode = 'AUTHORITATIVE' AND v_would_admit > 0 THEN
      WITH input_candidates AS (
        SELECT DISTINCT candidate_value.value::uuid AS candidate_id
        FROM jsonb_array_elements_text(v_eligible) AS candidate_value(value)
      ), base_ordinal AS (
        SELECT COALESCE(MAX(scope_row.scope_ordinal), 0)::bigint AS value
        FROM public.banking_pay_workbench_session_scope AS scope_row
        WHERE scope_row.session_id = v_session.id
      ), inserted_scope AS (
        INSERT INTO public.banking_pay_workbench_session_scope(
          session_id, candidate_id, scope_ordinal, status, pending_job_id,
          seeded, dirty, error_json, created_at_utc, updated_at_utc
        )
        SELECT v_session.id,
               input_candidates.candidate_id,
               base_ordinal.value + ROW_NUMBER() OVER (ORDER BY input_candidates.candidate_id),
               'PENDING', NULL::uuid, true, false, NULL::jsonb, v_now, v_now
        FROM input_candidates
        CROSS JOIN base_ordinal
        ON CONFLICT (session_id, candidate_id) DO NOTHING
        RETURNING candidate_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(
               jsonb_agg(to_jsonb(inserted_scope.candidate_id::text) ORDER BY inserted_scope.candidate_id),
               '[]'::jsonb
             )
      INTO v_inserted_count, v_inserted
      FROM inserted_scope;

      IF v_inserted_count > 0 THEN
        v_enqueue := public.pay_workbench_enqueue_candidate_refresh_many(
          p_session_id => v_session.id,
          p_candidate_ids => v_inserted,
          p_reason => 'CONTINUOUS_SCOPE_RECONCILE_ADMISSION',
          p_actor_user_id => v_session.actor_user_id
        );
      END IF;
    END IF;

    SELECT page_row.scope_change_generation, page_row.entity_key
    INTO v_last_generation, v_last_entity_key
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
    ORDER BY page_row.page_ordinal DESC
    LIMIT 1;

    v_shadow_previous := CASE
      WHEN jsonb_typeof(v_job.payload_json->'shadow_accumulator') = 'object'
        THEN v_job.payload_json->'shadow_accumulator'
      ELSE '{}'::jsonb
    END;

    SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
    INTO v_shadow_sample
    FROM jsonb_array_elements(
      COALESCE(v_shadow_previous->'candidate_sample', '[]'::jsonb)
      || COALESCE((
        SELECT jsonb_agg(to_jsonb(sample_candidate.value) ORDER BY sample_candidate.ordinality)
        FROM jsonb_array_elements_text(v_shortlist)
             WITH ORDINALITY AS sample_candidate(value, ordinality)
        WHERE sample_candidate.ordinality <= 25
      ), '[]'::jsonb)
    ) WITH ORDINALITY AS sample_row(value, ordinality)
    WHERE sample_row.ordinality <= 25;

    v_shadow_summary := jsonb_build_object(
      'target_generation', v_target,
      'candidates_considered', COALESCE((v_shadow_previous->>'candidates_considered')::integer, 0) + v_page_count,
      'already_in_scope', COALESCE((v_shadow_previous->>'already_in_scope')::integer, 0) + v_already_in_scope,
      'would_admit', COALESCE((v_shadow_previous->>'would_admit')::integer, 0) + v_would_admit,
      'would_reject', COALESCE((v_shadow_previous->>'would_reject')::integer, 0) + v_would_reject,
      'would_enqueue_refresh', COALESCE((v_shadow_previous->>'would_enqueue_refresh')::integer, 0) + v_would_admit,
      'candidate_sample', v_shadow_sample,
      'decision_hash', encode(
        extensions.digest(
          convert_to(v_shortlist::text || '|' || v_eligible::text || '|' || v_target::text, 'UTF8'),
          'sha256'
        ),
        'hex'
      )
    );

    IF v_has_more THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'cursor_generation', v_last_generation,
              'cursor_entity_key', v_last_entity_key,
              'candidate_limit', v_limit,
              'reconcile_mode', v_mode,
              'shadow_accumulator', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END,
              'last_shadow_page', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;

      RETURN jsonb_build_object(
        'ok', true,
        'processed', true,
        'status', 'QUEUED',
        'reconcile_mode', v_mode,
        'session_id', v_session.id::text,
        'target_generation', v_target,
        'page_count', v_page_count,
        'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
        'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
        'has_more', true
      );
    END IF;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 OR v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + CASE
            WHEN v_upstream_failed > 0 THEN interval '30 seconds'
            ELSE interval '1 second'
          END,
          started_at_utc = NULL::timestamptz,
          last_error_json = CASE
            WHEN v_upstream_failed > 0 THEN jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
              'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
              'target_generation', v_target
            )
            ELSE coordinator_job.last_error_json
          END,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', v_upstream_failed = 0,
        'processed', true,
        'status', 'QUEUED',
        'reason', CASE
          WHEN v_upstream_failed > 0 THEN 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED'
          ELSE 'UPSTREAM_APPEARED_BEFORE_ADVANCE'
        END
      );
    END IF;

    IF v_mode = 'SHADOW' THEN
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_shadow_checked = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SHADOW_SUCCEEDED',
              'scope_reconcile_mode', 'SHADOW',
              'scope_change_generation_shadow_checked', v_target,
              'scope_shadow_summary', v_shadow_summary,
              'scope_shadow_checked_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    ELSE
      -- A23 (PRE-EXISTING SB02 fix, AA-B3): an AUTHORITATIVE completion has applied every candidate change up to
      -- v_target, which is strictly more than a SHADOW dry-run check of the same page range. Record it as checked
      -- too, so the settled certificate's target = applied = shadow_checked equality can hold in the default
      -- (AUTHORITATIVE) mode. SHADOW mode, the certificate, due_claim and the table CHECK are unchanged.
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_applied = v_target,
          scope_change_generation_target = v_target,
          scope_change_generation_shadow_checked = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SUCCEEDED',
              'scope_reconcile_mode', 'AUTHORITATIVE',
              'scope_change_generation_target', v_target,
              'scope_change_generation_applied', v_target,
              'scope_change_generation_shadow_checked', v_target,
              'scope_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    END IF;

    SELECT generation_counter.seq
    INTO v_current_generation
    FROM public.app_change_counters AS generation_counter
    WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
    FOR UPDATE;

    SELECT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_sessions AS lagging_session
      WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
        AND lagging_session.discarded_at_utc IS NULL
        AND lagging_session.replacement_session_id IS NULL
        AND COALESCE(lagging_session.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
        )
    ) INTO v_more_sessions;

    IF v_current_generation > v_target OR v_more_sessions THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
          scope_change_generation = v_current_generation,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'processed', true,
      'status', CASE
        WHEN v_current_generation > v_target OR v_more_sessions THEN 'QUEUED'
        ELSE 'SUCCEEDED'
      END,
      'reconcile_mode', v_mode,
      'session_id', v_session.id::text,
      'target_generation', v_target,
      'current_generation', v_current_generation,
      'page_count', v_page_count,
      'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
      'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
      'has_more', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_error_message = MESSAGE_TEXT,
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_state = RETURNED_SQLSTATE;

    UPDATE public.banking_pay_workbench_jobs AS failed_coordinator
    SET attempt_count = COALESCE(failed_coordinator.attempt_count, 0) + 1,
        status = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN 'FAILED'
          ELSE 'QUEUED'
        END,
        run_at_utc = v_now + make_interval(
          secs => LEAST(900, 30 * GREATEST(COALESCE(failed_coordinator.attempt_count, 0) + 1, 1))
        ),
        started_at_utc = NULL::timestamptz,
        failed_at_utc = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN v_now
          ELSE NULL::timestamptz
        END,
        last_error_json = jsonb_strip_nulls(jsonb_build_object(
          'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
          'message', v_error_message,
          'detail', v_error_detail,
          'failed_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE failed_coordinator.id = v_job.id;

    RETURN jsonb_build_object(
      'ok', false,
      'processed', true,
      'job_id', v_job.id::text,
      'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
      'message', v_error_message
    );
  END;
END;
$function$
;

-- [REPLACES] public.pay_workbench_settled_certificate_build_start_v8(p_workbench_session_id uuid, p_actor_user_id uuid, p_build_idempotency_key text)  winner piece A30
CREATE OR REPLACE FUNCTION public.pay_workbench_settled_certificate_build_start_v8(p_workbench_session_id uuid, p_actor_user_id uuid, p_build_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_existing private.banking_pay_workbench_settled_certificates_v8%ROWTYPE;
  v_certificate_uuid uuid := pg_catalog.gen_random_uuid();
  v_build_id uuid := pg_catalog.gen_random_uuid();
  v_selected_count integer;
  v_partition_count integer;
  v_selected_total numeric;
  v_invalid_selected_count integer;
  v_server_id_count integer;
  v_server_distinct_count integer;
  v_server_missing_count integer;
  v_selected_missing_count integer;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_filter_candidate_text text;
  v_filter_client_text text;
  v_filter_context jsonb;
  v_filter_digest text;
  v_gate jsonb;
  v_gate_digest text;
  v_empty_digest text;
  v_publication_count integer;
  v_invalid_publication_count integer;
  v_queued_jobs integer;
  v_running_jobs integer;
  v_invalid_pointer_count integer;
  v_last_receipt_sha256 text;
BEGIN
  PERFORM pg_catalog.set_config('statement_timeout', '15000', true);
  PERFORM pg_catalog.set_config('lock_timeout', '1500', true);
  IF p_workbench_session_id IS NULL OR p_actor_user_id IS NULL
     OR NULLIF(BTRIM(COALESCE(p_build_idempotency_key, '')), '') IS NULL
     OR pg_catalog.octet_length(p_build_idempotency_key) > 512 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_BUILD_REQUEST_INVALID' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_session
  FROM public.banking_pay_workbench_sessions
  WHERE id = p_workbench_session_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_session.actor_user_id IS DISTINCT FROM p_actor_user_id
     OR UPPER(v_session.status) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL
     OR v_session.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SESSION_INVALID' USING ERRCODE = '55000';
  END IF;
  IF v_session.version < 1 OR v_session.progress_counter_version < 1
     OR v_session.authority_fence_generation < 1
     OR UPPER(v_session.progress_state) <> 'READY'
     OR NOT v_session.scope_seed_complete
     OR v_session.scope_total_count <> v_session.scope_seeded_count
     OR v_session.scope_total_count <> v_session.scope_ready_count
     OR v_session.scope_pending_count <> 0 OR v_session.scope_failed_count <> 0
     OR v_session.line_units_total <> v_session.line_units_ready
     OR v_session.line_units_pending <> 0 OR v_session.line_units_failed <> 0
     OR v_session.scope_change_generation_target <> v_session.scope_change_generation_applied
     OR v_session.scope_change_generation_target <> v_session.scope_change_generation_shadow_checked THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SESSION_NOT_SETTLED' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_existing
  FROM private.banking_pay_workbench_settled_certificates_v8 certificate
  WHERE certificate.workbench_session_id = p_workbench_session_id
    AND certificate.session_version = v_session.version
    AND certificate.progress_counter_version = v_session.progress_counter_version
    AND certificate.authority_fence_generation = v_session.authority_fence_generation
    AND certificate.build_idempotency_key = BTRIM(p_build_idempotency_key)
  LIMIT 1;
  IF FOUND THEN
    SELECT receipt.page_digest_sha256
    INTO v_last_receipt_sha256
    FROM private.banking_pay_workbench_settled_certificate_page_receipts_v8 receipt
    WHERE receipt.certificate_uuid=v_existing.certificate_uuid
      AND receipt.request_scope_key='CERTIFICATE_BUILD'
      AND receipt.page_kind='BUILD_APPEND'
      AND receipt.pay_channel_scope='ALL'
    ORDER BY receipt.page_sequence DESC
    LIMIT 1;
    RETURN pg_catalog.jsonb_build_object(
      'ok', v_existing.lifecycle IN ('BUILDING','SEALED_CURRENT'),
      'replayed', true,
      'certificate_uuid', v_existing.certificate_uuid,
      'build_id', v_existing.build_id,
      'certification_id', v_existing.certification_id,
      'overall_digest_sha256', v_existing.overall_digest_sha256,
      'lifecycle', v_existing.lifecycle,
      'selected_constituent_count', v_existing.selected_constituent_count,
      'next_after_ordinal',v_existing.build_after_ordinal,
      'last_page_receipt_sha256',v_last_receipt_sha256,
      'append_complete',v_existing.selected_constituents_digest_sha256 IS NOT NULL,
      'build_failure_code',v_existing.build_failure_code,
      'build_failure_message',v_existing.build_failure_message,
      'lease_owner',v_existing.lease_owner,
      'maximum_page_size',256,
      'maximum_requested_page_size',256,
      'maximum_build_emission_rows',64
    );
  END IF;

  -- A settled authority has one producer at a time. Different caller keys may
  -- not manufacture parallel certificates for the same immutable session
  -- generation; the exact current certificate is the canonical replay result.
  SELECT * INTO v_existing
  FROM private.banking_pay_workbench_settled_certificates_v8 certificate
  WHERE certificate.workbench_session_id=p_workbench_session_id
    AND certificate.session_version=v_session.version
    AND certificate.progress_counter_version=v_session.progress_counter_version
    AND certificate.authority_fence_generation=v_session.authority_fence_generation
    AND certificate.lifecycle IN ('BUILDING','SEALED_CURRENT')
  ORDER BY CASE certificate.lifecycle WHEN 'SEALED_CURRENT' THEN 0 ELSE 1 END,
           certificate.created_at_utc
  LIMIT 1;
  IF FOUND THEN
    IF v_existing.lifecycle='SEALED_CURRENT' THEN
      SELECT receipt.page_digest_sha256
      INTO v_last_receipt_sha256
      FROM private.banking_pay_workbench_settled_certificate_page_receipts_v8 receipt
      WHERE receipt.certificate_uuid=v_existing.certificate_uuid
        AND receipt.request_scope_key='CERTIFICATE_BUILD'
        AND receipt.page_kind='BUILD_APPEND'
        AND receipt.pay_channel_scope='ALL'
      ORDER BY receipt.page_sequence DESC
      LIMIT 1;
      RETURN pg_catalog.jsonb_build_object(
        'ok',true,'replayed',true,'certificate_uuid',v_existing.certificate_uuid,
        'build_id',v_existing.build_id,'certification_id',v_existing.certification_id,
        'overall_digest_sha256',v_existing.overall_digest_sha256,
        'lifecycle',v_existing.lifecycle,
        'selected_constituent_count',v_existing.selected_constituent_count,
        'next_after_ordinal',v_existing.build_after_ordinal,
        'last_page_receipt_sha256',v_last_receipt_sha256,
        'append_complete',true,
        'lease_owner',v_existing.lease_owner,
        'maximum_page_size',256,
        'maximum_requested_page_size',256,
        'maximum_build_emission_rows',64
      );
    END IF;
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_BUILD_ALREADY_IN_PROGRESS'
      USING ERRCODE='55000',DETAIL=pg_catalog.jsonb_build_object(
        'certificate_uuid',v_existing.certificate_uuid,'build_id',v_existing.build_id)::text;
  END IF;

  -- Admission counts at most the supported set plus one sentinel.  Exact row
  -- eligibility, economics, source identity and digests are deliberately
  -- checked by bounded append pages; doing that work here made a legitimate
  -- 50,000-row session exceed the fixed 15-second budget.
  SELECT COUNT(*)::integer
  INTO v_selected_count
  FROM (
    SELECT preview.id
    FROM public.banking_pay_workbench_preview_rows preview
    WHERE preview.session_id = p_workbench_session_id
      AND preview.session_version = v_session.version
      AND preview.selected
      AND UPPER(preview.selection_state) = 'SELECTED'
    LIMIT 50001
  ) bounded_selected;
  IF v_selected_count < 1 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_NO_SELECTED_ROWS' USING ERRCODE = '22023';
  END IF;
  IF v_selected_count > 50000 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SELECTED_LIMIT_EXCEEDED' USING ERRCODE = '54000';
  END IF;
  IF v_session.selected_row_count IS DISTINCT FROM v_selected_count THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SELECTED_COUNTER_MISMATCH' USING ERRCODE = '55000';
  END IF;

  -- A26 (PRE-EXISTING SB02 fix, AC-B4): the modal-v2 selection owner (the route the Office UI uses) and the
  -- ordinary row-patch owner deliberately record IMPLICIT_ALL selection intent: provided = false, with the
  -- selection authority held on the preview rows themselves (their committed runtime tests require exactly
  -- that). The certificate previously accepted only the legacy explicit form (provided = true), so no session
  -- selected through the real UI, and no untouched default session, could ever certify. Accept the implicit
  -- form only when the recorded intent is IMPLICIT_ALL (or absent, the session-open default). Any NON-EMPTY
  -- server id list (explicit, or the one the certified publisher maintains) must still equal the materialised
  -- selection exactly (unchanged MISMATCH check below). In the implicit form the certificate's own
  -- source_members, inserted below from the same locked session version, are the server-selected id list, so
  -- the header's provided/equal attestations hold by construction. No amount, selection or row change.
  IF (v_session.server_selected_preview_row_ids_provided IS NOT TRUE
      AND COALESCE(v_session.progress_json #>> '{selection_intent_v1,canonical_preview_lines,mode}', 'IMPLICIT_ALL')
          IS DISTINCT FROM 'IMPLICIT_ALL')
     OR pg_catalog.jsonb_typeof(v_session.server_selected_preview_row_ids) IS DISTINCT FROM 'array'
     OR EXISTS (
       SELECT 1 FROM pg_catalog.jsonb_array_elements(v_session.server_selected_preview_row_ids) element(value)
       WHERE pg_catalog.jsonb_typeof(element.value) <> 'string'
          OR BTRIM(element.value #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     ) THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SERVER_SELECTION_INVALID' USING ERRCODE = '22023';
  END IF;
  IF v_session.server_selected_preview_row_ids_provided IS TRUE
     OR pg_catalog.jsonb_array_length(v_session.server_selected_preview_row_ids) > 0 THEN
  WITH server_ids AS MATERIALIZED (
    SELECT value::uuid AS preview_row_id
    FROM pg_catalog.jsonb_array_elements_text(v_session.server_selected_preview_row_ids) element(value)
  ), selected_ids AS MATERIALIZED (
    SELECT preview.id AS preview_row_id
    FROM public.banking_pay_workbench_preview_rows preview
    WHERE preview.session_id = p_workbench_session_id
      AND preview.session_version = v_session.version
      AND preview.selected
      AND UPPER(preview.selection_state) = 'SELECTED'
  )
  SELECT (SELECT COUNT(*) FROM server_ids)::integer,
         (SELECT COUNT(DISTINCT preview_row_id) FROM server_ids)::integer,
         (SELECT COUNT(*) FROM server_ids s LEFT JOIN selected_ids e USING (preview_row_id) WHERE e.preview_row_id IS NULL)::integer,
         (SELECT COUNT(*) FROM selected_ids e LEFT JOIN server_ids s USING (preview_row_id) WHERE s.preview_row_id IS NULL)::integer
  INTO v_server_id_count, v_server_distinct_count, v_server_missing_count, v_selected_missing_count;
  IF v_server_id_count <> v_selected_count OR v_server_distinct_count <> v_selected_count
     OR v_server_missing_count <> 0 OR v_selected_missing_count <> 0 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_SERVER_SELECTION_MISMATCH' USING ERRCODE = '22023';
  END IF;
  END IF;  -- A26 AC-B4: explicit / non-empty server id list
  -- BUILDING headers use harmless non-null placeholders for totals and
  -- partitions.  The final append page atomically replaces them with the exact
  -- values proved from every bounded constituent page before seal can run.
  v_partition_count := 1;
  v_selected_total := 0;

  v_filter_candidate_text := NULLIF(BTRIM(COALESCE(
    v_session.filters_json->>'candidate_filter_id', v_session.filters_json->>'candidateFilterId',
    v_session.filters_json->>'filter_candidate_id', v_session.filters_json->>'candidate_id',
    v_session.filters_json->>'candidateId', ''
  )), '');
  v_filter_client_text := NULLIF(BTRIM(COALESCE(
    v_session.filters_json->>'client_filter_id', v_session.filters_json->>'clientFilterId',
    v_session.filters_json->>'filter_client_id', v_session.filters_json->>'client_id',
    v_session.filters_json->>'clientId', ''
  )), '');
  IF v_filter_candidate_text IS NOT NULL AND v_filter_candidate_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_FILTER_CONTEXT_INVALID' USING ERRCODE = '22023';
  END IF;
  IF v_filter_client_text IS NOT NULL AND v_filter_client_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_FILTER_CONTEXT_INVALID' USING ERRCODE = '22023';
  END IF;
  v_filter_candidate_id := v_filter_candidate_text::uuid;
  v_filter_client_id := v_filter_client_text::uuid;
  v_filter_context := pg_catalog.jsonb_build_object(
    'candidate_filter_id', v_filter_candidate_id,
    'client_filter_id', v_filter_client_id,
    'filter_binding_mode', 'EXACT_CERTIFIED_SELECTED_UNIVERSE'
  );
  v_filter_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(v_filter_context)
  );

  IF v_filter_candidate_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.banking_pay_workbench_preview_rows preview
    WHERE preview.session_id = p_workbench_session_id
      AND preview.session_version = v_session.version
      AND preview.selected
      AND UPPER(preview.selection_state) = 'SELECTED'
      AND preview.candidate_id <> v_filter_candidate_id
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_FILTER_CONTEXT_MISMATCH' USING ERRCODE = '22023';
  END IF;
  IF v_filter_client_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.banking_pay_workbench_preview_rows preview
    WHERE preview.session_id = p_workbench_session_id
      AND preview.session_version = v_session.version
      AND preview.selected
      AND UPPER(preview.selection_state) = 'SELECTED'
      AND COALESCE(preview.row_json->>'client_id', '') <> v_filter_client_id::text
      -- A30 (PRE-EXISTING fix, H6 M2): a repayment/recovery row is Candidate-level: the Workbench publishes it for a
      -- Candidate it scoped for this Client, and it carries no client_id. It belongs to the certified selected
      -- universe when its Candidate is in this session's scope, exactly as the Workbench scoped and capped it. A row
      -- naming a DIFFERENT Client, and every Timesheet row, is still refused.
      AND NOT (
        NULLIF(BTRIM(COALESCE(preview.row_json->>'client_id', '')), '') IS NULL
        AND UPPER(BTRIM(COALESCE(preview.row_json->>'line_type', ''))) IN (
          'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT')
        AND COALESCE(preview.row_json->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND EXISTS (
          SELECT 1 FROM public.banking_pay_workbench_session_scope a30_scope
          WHERE a30_scope.session_id = p_workbench_session_id
            AND a30_scope.candidate_id = preview.candidate_id)
      )
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_FILTER_CONTEXT_MISMATCH' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) FILTER (WHERE status = 'QUEUED')::integer,
         COUNT(*) FILTER (WHERE status = 'RUNNING')::integer
  INTO v_queued_jobs, v_running_jobs
  FROM public.banking_pay_workbench_jobs
  WHERE session_id = p_workbench_session_id
    AND status IN ('QUEUED','RUNNING');
  SELECT COUNT(*)::integer INTO v_invalid_pointer_count
  FROM public.banking_pay_workbench_session_scope scope
  LEFT JOIN public.banking_pay_workbench_jobs job ON job.id = scope.pending_job_id
  WHERE scope.session_id = p_workbench_session_id
    -- A28 (PRE-EXISTING SB02 fix, item 1): a Candidate whose certified publication is genuinely EMPTY
    -- (SOURCE_EMPTY: parity-attested for this session version with 0 source rows; no CURRENT source line and no
    -- selected or live preview row for it; no error) has nothing to pay. It is not unsettled work, so it no longer refuses the whole session; it simply
    -- contributes no constituent, partition or Draft item. Every other non-Ready status is still refused.
    AND (scope.pending_job_id IS NOT NULL OR (scope.status NOT IN ('READY', 'MATERIALISED') /* A26 AC-B5 */
           AND NOT (scope.status = 'SOURCE_EMPTY'
           AND COALESCE(scope.error_json, '{}'::jsonb) = '{}'::jsonb
           AND scope.certified_preview_publication_parity_ok IS TRUE
           AND scope.certified_preview_publication_session_version = v_session.version
           AND pg_catalog.jsonb_typeof(scope.certified_preview_publication_attestation_json) = 'object'
           AND COALESCE(scope.certified_preview_publication_attestation_json->>'source_row_count', '') = '0'
           AND NOT EXISTS (
             SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines empty_source
             WHERE empty_source.session_id = scope.session_id AND empty_source.candidate_id = scope.candidate_id
               AND empty_source.status = 'CURRENT')
           AND NOT EXISTS (
             SELECT 1 FROM public.banking_pay_workbench_preview_rows empty_preview
             WHERE empty_preview.session_id = scope.session_id AND empty_preview.candidate_id = scope.candidate_id
               AND (empty_preview.selected OR UPPER(COALESCE(empty_preview.status, '')) IN ('READY', 'DIRTY', 'PENDING')))))
      OR (scope.pending_job_id IS NOT NULL AND (job.id IS NULL OR job.status NOT IN ('QUEUED','RUNNING'))));
  IF COALESCE(v_queued_jobs, 0) <> 0 OR COALESCE(v_running_jobs, 0) <> 0 OR v_invalid_pointer_count <> 0 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_CURRENT_JOB_AUTHORITY_UNSETTLED' USING ERRCODE = '55000';
  END IF;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE (scope.status NOT IN ('READY', 'MATERIALISED') /* A26 AC-B5 */
             AND NOT empty_check.certified_empty) /* A28 item 1 */
           OR state.status <> 'READY'
           OR scope.certified_preview_publication_parity_ok IS NOT TRUE
           OR scope.certified_preview_publication_session_version IS DISTINCT FROM v_session.version
           OR scope.certified_preview_publication_source_change_seq IS DISTINCT FROM state.source_change_seq
           OR scope.certified_preview_publication_source_build_run_id IS NULL
           -- A28 item 1: an empty publication has no source row to carry a publication identity
           OR (scope.certified_preview_publication_source_publication_id IS NULL AND NOT empty_check.certified_empty)
           OR pg_catalog.jsonb_typeof(scope.certified_preview_publication_attestation_json) IS DISTINCT FROM 'object')::integer
  INTO v_publication_count, v_invalid_publication_count
  FROM public.banking_pay_workbench_session_scope scope
  LEFT JOIN public.banking_pay_workbench_session_candidate_state state
    ON state.session_id = scope.session_id AND state.candidate_id = scope.candidate_id
  CROSS JOIN LATERAL (SELECT (scope.status = 'SOURCE_EMPTY'
           AND COALESCE(scope.error_json, '{}'::jsonb) = '{}'::jsonb
           AND scope.certified_preview_publication_parity_ok IS TRUE
           AND scope.certified_preview_publication_session_version = v_session.version
           AND pg_catalog.jsonb_typeof(scope.certified_preview_publication_attestation_json) = 'object'
           AND COALESCE(scope.certified_preview_publication_attestation_json->>'source_row_count', '') = '0'
           AND NOT EXISTS (
             SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines empty_source
             WHERE empty_source.session_id = scope.session_id AND empty_source.candidate_id = scope.candidate_id
               AND empty_source.status = 'CURRENT')
           AND NOT EXISTS (
             SELECT 1 FROM public.banking_pay_workbench_preview_rows empty_preview
             WHERE empty_preview.session_id = scope.session_id AND empty_preview.candidate_id = scope.candidate_id
               AND (empty_preview.selected OR UPPER(COALESCE(empty_preview.status, '')) IN ('READY', 'DIRTY', 'PENDING')))) AS certified_empty) empty_check /* A28 item 1 */
  WHERE scope.session_id = p_workbench_session_id;
  IF v_publication_count <> v_session.scope_total_count OR v_invalid_publication_count <> 0 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_PUBLICATION_AUTHORITY_INVALID' USING ERRCODE = '55000';
  END IF;

  v_gate := private.pay_workbench_modal_draft_gate_v2(p_workbench_session_id, v_selected_count);
  IF v_gate->'can_create_draft' IS DISTINCT FROM 'true'::jsonb
     OR COALESCE(v_gate->>'session_selected_eligible_ready_row_count', '') !~ '^[0-9]+$'
     OR (v_gate->>'session_selected_eligible_ready_row_count')::integer <> v_selected_count
     OR pg_catalog.jsonb_array_length(v_gate->'blocker_codes') <> 0 THEN
    RAISE EXCEPTION 'WORKBENCH_CERTIFICATE_DRAFT_GATE_REJECTED'
      USING ERRCODE = '55000', DETAIL = v_gate::text;
  END IF;
  v_gate_digest := private.pay_workbench_settled_certificate_sha256_text_v8(
    private.pay_workbench_settled_certificate_stable_stringify_v8(v_gate)
  );
  v_empty_digest := private.pay_workbench_settled_certificate_sha256_text_v8('[]');

  INSERT INTO private.banking_pay_workbench_settled_certificates_v8(
    certificate_uuid, certificate_contract, workbench_session_id, session_version,
    progress_counter_version, progress_state, source_snapshot_run_id, session_signature,
    pay_date, week_ending_cutoff, filters_digest_sha256,
    scope_change_generation_target, scope_change_generation_applied,
    scope_change_generation_shadow_checked, authority_fence_generation,
    publication_count, publications_digest_sha256,
    scope_total_count, scope_seeded_count, scope_ready_count, scope_pending_count, scope_failed_count,
    line_units_total, line_units_ready, line_units_pending, line_units_failed,
    selected_row_count, selected_page_order, selected_page_size_max, selected_pages_fetched,
    selected_terminal_sentinel_seen, selected_sentinel_overflow, all_selected_rows_loaded,
    server_selected_preview_row_ids_provided, server_selected_ids_equal_materialised_selected_ids,
    ready_action_required_blocked_pairwise_disjoint, active_draft_rows_excluded,
    ineligible_rows_excluded, snoozed_rows_excluded, unloaded_selection_gap_count,
    queued_current_job_count, running_current_job_count, unresolved_current_job_count,
    invalid_current_job_pointer_count, historical_terminal_rows_retained,
    historical_terminal_rows_are_not_current_authority, can_create_draft,
    selected_eligible_ready_row_count, blocking_reason_count, gate_digest_sha256,
    selected_constituent_count, selected_canonical_amount_ex_vat_total,
    selected_partition_count, selected_partitions_ordering,
    policy_contract_version, before_policy_projection_digest_sha256,
    after_policy_projection_digest_sha256, policy_digests_equal,
    execution_recovery_delta_only, forbidden_policy_delta_count, no_payment_policy_change,
    lifecycle, build_id, build_idempotency_key, lease_owner, lease_expires_at_utc,
    created_by_user_id, candidate_filter_id, client_filter_id,
    filter_binding_mode, filter_context_digest_sha256
  ) VALUES (
    v_certificate_uuid, 'WORKBENCH_SETTLED_CERTIFICATION_V2', p_workbench_session_id, v_session.version,
    v_session.progress_counter_version, 'READY', v_session.source_snapshot_run_id, v_session.session_signature,
    v_session.pay_date, v_session.week_ending_cutoff, v_filter_digest,
    v_session.scope_change_generation_target, v_session.scope_change_generation_applied,
    v_session.scope_change_generation_shadow_checked, v_session.authority_fence_generation,
    v_publication_count, v_empty_digest,
    v_session.scope_total_count, v_session.scope_seeded_count, v_session.scope_ready_count, 0, 0,
    v_session.line_units_total, v_session.line_units_ready, 0, 0,
    v_selected_count, 'row_ordinal asc, preview_row_id asc', 256, 1,
    true, false, true, true, true,
    true, true, true, true, 0,
    0, 0, 0, 0, true, true, true,
    v_selected_count, 0, v_gate_digest,
    v_selected_count, private.pay_workbench_settled_certificate_money_v8(pg_catalog.to_jsonb(v_selected_total)),
    v_partition_count, 'minimum constituent ordinal asc, candidate_id asc, resolved_pay_channel asc',
    'WORKBENCH_PAYMENT_POLICY_PARITY_V2', v_filter_digest, v_filter_digest, true,
    true, 0, true,
    'BUILDING', v_build_id, BTRIM(p_build_idempotency_key), p_actor_user_id::text,
    clock_timestamp() + interval '30 seconds', p_actor_user_id,
    v_filter_candidate_id, v_filter_client_id,
    'EXACT_CERTIFIED_SELECTED_UNIVERSE', v_filter_digest
  );

  INSERT INTO private.banking_pay_workbench_settled_certificate_source_members_v8(
    certificate_uuid, constituent_ordinal, preview_row_id, source_row_ordinal, source_row_digest_sha256
  )
  SELECT v_certificate_uuid,
         (ROW_NUMBER() OVER (ORDER BY preview.row_ordinal, preview.id) - 1)::integer,
         preview.id, preview.row_ordinal, NULL
  FROM public.banking_pay_workbench_preview_rows preview
  WHERE preview.session_id = p_workbench_session_id
    AND preview.session_version = v_session.version
    AND preview.selected
    AND UPPER(preview.selection_state) = 'SELECTED'
  ORDER BY preview.row_ordinal, preview.id;

  INSERT INTO private.banking_pay_workbench_settled_certificate_digest_runs_v8(
    certificate_uuid,stream_kind,pay_channel_scope,hash_contract,status,next_ordinal,
    stream_phase,current_state_json
  )
  SELECT v_certificate_uuid,'SELECTED_CONSTITUENTS',scope,
         'V1_STABLE_STRINGIFY_CONSTITUENTS','BUILDING',0,'ROWS',
         private.pay_workbench_settled_certificate_sha256_update_v8(
           private.pay_workbench_settled_certificate_sha256_init_v8(),'['
         )
  FROM (VALUES ('ALL'),('PAYE'),('UMBRELLA')) scopes(scope);

  INSERT INTO private.banking_pay_workbench_settled_certificate_publications_v8(
    certificate_uuid, scope_ordinal, candidate_id, candidate_state_id, candidate_state_status,
    source_change_seq, source_build_run_id, source_publication_id,
    certified_publication_session_version, publication_attestation_version,
    publication_attestation_digest_sha256, publication_parity_ok, publication_attested_at_utc
  )
  SELECT v_certificate_uuid, scope.scope_ordinal::integer, scope.candidate_id, state.id, state.status,
         scope.certified_preview_publication_source_change_seq,
         scope.certified_preview_publication_source_build_run_id,
         -- A28 item 1: the certificate records an empty publication under the same deterministic identity the
         -- publisher derives for that session/Candidate/version/sequence/run (it stamps no row, so none is stored).
         COALESCE(scope.certified_preview_publication_source_publication_id,
           CASE WHEN scope.status = 'SOURCE_EMPTY' THEN private.pay_workbench_source_publication_identity_v1(
             scope.session_id, scope.candidate_id, scope.certified_preview_publication_session_version,
             scope.certified_preview_publication_source_change_seq, scope.certified_preview_publication_source_build_run_id) END),
         scope.certified_preview_publication_session_version,
         CASE WHEN COALESCE(scope.certified_preview_publication_attestation_json->>'contract_version', '') ~ '^[0-9]+$'
           THEN (scope.certified_preview_publication_attestation_json->>'contract_version')::integer ELSE 1 END,
         private.pay_workbench_settled_certificate_sha256_text_v8(
           private.pay_workbench_settled_certificate_stable_stringify_v8(scope.certified_preview_publication_attestation_json)
         ), true,
         COALESCE(scope.certified_preview_publication_attested_at_utc, clock_timestamp())
  FROM public.banking_pay_workbench_session_scope scope
  JOIN public.banking_pay_workbench_session_candidate_state state
    ON state.session_id = scope.session_id AND state.candidate_id = scope.candidate_id
  WHERE scope.session_id = p_workbench_session_id
  ORDER BY scope.scope_ordinal, scope.candidate_id;

  INSERT INTO private.banking_pay_workbench_settled_certificate_policy_owners_v8(
    certificate_uuid,owner_ordinal,logical_owner_identity
  ) VALUES
    (v_certificate_uuid,0,'WORKBENCH_SELECTION_OWNER'),
    (v_certificate_uuid,1,'DRAFT_FINANCIAL_OWNERS_UNCHANGED');
  INSERT INTO private.banking_pay_workbench_settled_certificate_policy_surfaces_v8(
    certificate_uuid,surface_ordinal,compared_surface
  ) VALUES
    (v_certificate_uuid,0,'eligibility and selected constituents'),
    (v_certificate_uuid,1,'amount, sign, tax, VAT and economic keys'),
    (v_certificate_uuid,2,'pay method, channel, grouping and routing'),
    (v_certificate_uuid,3,'approval, hold, resolution, prior-paid, supersession and recovery/headroom'),
    (v_certificate_uuid,4,'pre-Draft source reservations'),
    (v_certificate_uuid,5,'unchanged Draft financial owner identities without Draft-produced facts'),
    (v_certificate_uuid,6,'provider, settlement, remittance and ultimate payment boundaries');

  INSERT INTO private.banking_pay_workbench_settled_certificate_universes_v8(
    certificate_uuid, universe_kind, row_count, universe_digest_sha256
  )
  SELECT v_certificate_uuid, kind, 0, v_empty_digest
  FROM (VALUES ('READY'),('ACTION_REQUIRED'),('BLOCKED'),('ACTIVE_DRAFT'),('INELIGIBLE'),('SNOOZED')) kinds(kind);
  INSERT INTO private.banking_pay_workbench_settled_certificate_digest_runs_v8(
    certificate_uuid,stream_kind,pay_channel_scope,hash_contract,status,next_ordinal,
    stream_phase,current_state_json
  ) VALUES (
    v_certificate_uuid,'UNIVERSE_CAPTURE','ALL','V2_STABLE_STRINGIFY_OVERALL',
    'BUILDING',0,'ROWS',pg_catalog.jsonb_build_object(
      'after_row_ordinal',NULL,'after_preview_row_id',NULL
    )
  );

  INSERT INTO private.banking_pay_workbench_settled_certificate_lifecycle_events_v8(
    certificate_uuid, event_sequence, event_kind, reason_code, actor_user_id
  ) VALUES (v_certificate_uuid, 0, 'BUILD_STARTED', 'CURRENT_SETTLED_WORKBENCH_AUTHORITY', p_actor_user_id);

  RETURN pg_catalog.jsonb_build_object(
    'ok', true, 'replayed', false,
    'certificate_uuid', v_certificate_uuid,
    'build_id', v_build_id,
    'lifecycle', 'BUILDING',
    'selected_constituent_count', v_selected_count,
    'selected_partition_count', NULL,
    'selected_canonical_amount_ex_vat_total', NULL,
    'classification_pending', true,
    'authority_fence_generation', v_session.authority_fence_generation,
    'next_after_ordinal', NULL,
    'last_page_receipt_sha256',NULL,
    'append_complete',false,
    'lease_owner',p_actor_user_id::text,
    'maximum_page_size', 256,
    'maximum_requested_page_size', 256,
    'maximum_build_emission_rows', 64
  );
END;
$function$
;

-- [REPLACES] public.pay_workbench_source_build_attempt_claim_start_v1(p_worker_id text, p_lane_identity text, p_lease_seconds integer, p_now_utc timestamp with time zone, p_session_id uuid, p_candidate_id uuid)  winner piece A29
CREATE OR REPLACE FUNCTION public.pay_workbench_source_build_attempt_claim_start_v1(p_worker_id text, p_lane_identity text, p_lease_seconds integer DEFAULT NULL::integer, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_database_now timestamptz := clock_timestamp();
  v_now timestamptz := LEAST(COALESCE(p_now_utc,v_database_now),v_database_now);
  v_worker_id text := NULLIF(btrim(COALESCE(p_worker_id,'')),'');
  v_lane_identity text := NULLIF(btrim(COALESCE(p_lane_identity,'')),'');
  v_configured_lease integer := 25;
  v_effective_lease integer;
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_build_id uuid;
  v_claimed_job_id uuid;
  v_attempt_id uuid;
  v_attempt_nonce uuid;
  v_attempt_number integer;
  v_stage text;
  v_cursor_kind text;
  v_cursor_json jsonb;
  v_source_build_run_id uuid;
  v_source_change_seq bigint;
  v_captured_generation bigint;
  v_attempt_started_at timestamptz;
  v_lease_expires timestamptz;
  v_bootstrap_id uuid;
  v_is_bootstrap boolean:=false;
  v_recovery record;
  v_claim record;
  v_recovery_cursor_generation bigint;
  v_recovery_cursor_due_at timestamptz;
  v_recovery_cursor_object_id uuid;
  v_claim_cursor_generation bigint;
  v_claim_cursor_chain_rank smallint;
  v_claim_cursor_priority integer;
  v_claim_cursor_due_at timestamptz;
  v_claim_cursor_created_at timestamptz;
  v_claim_cursor_object_id uuid;
  v_scan_scope_key text;
  v_recovery_examined integer:=0;
  v_claim_examined integer:=0;
  v_claim_sweep_restarted boolean:=false;
  v_recovered_count integer:=0;
  v_scan_limit integer:=50;
  -- Four source-build lanes may collect and publish concurrently, but the
  -- reconciliation stage performs the expensive finance/effect comparison.
  -- Admit at most two such attempts at once so four Worker lanes cannot turn
  -- a healthy ~6 second attempt into a 25 second lease-expiry stampede.
  v_reconcile_attempt_limit integer:=2;
  v_execution_profile_version integer:=1;
  v_reconciliation_optimization_version integer:=0;
  v_settings_json jsonb:='{}'::jsonb;
  v_obsolete_repair_result jsonb:='{}'::jsonb;
  v_obsolete_successor_job_id uuid:=NULL::uuid;
  v_obsolete_active_successor_proven boolean:=false;
  v_obsolete_terminal_current_proven boolean:=false;
  v_obsolete_successor_wait_count integer:=0;
  v_obsolete_successor_wait_seconds integer:=2;
  v_obsolete_successor_retry_at_utc timestamptz:=NULL::timestamptz;
  v_draft_deferral_enabled boolean:=false;
  v_draft_operation_id uuid:=NULL::uuid;
  v_draft_operation public.banking_pay_operations%ROWTYPE;
  v_draft_deferral_count integer:=0;
  v_draft_deferral_seconds integer:=2;
  v_same_authority_election_enabled boolean:=false;
  v_authority_fingerprint_version smallint:=NULL::smallint;
  v_authority_fingerprint text:=NULL::text;
  v_required_physical_publication_contract_version smallint:=0;
  v_unique_constraint_name text:=NULL::text;
  v_winner_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_winner_active_job_id uuid:=NULL::uuid;
  v_winner_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_winner_complete_current_proven boolean:=false;
  v_terminal_repair_result jsonb:='{}'::jsonb;
  v_terminal_repair_row jsonb:='{}'::jsonb;
  v_terminal_action text:=NULL::text;
  v_terminal_successor_job_id uuid:=NULL::uuid;
  v_terminal_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_terminal_candidate_state public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_terminal_candidate_state_present boolean:=false;
  v_terminal_owner_valid boolean:=false;
  v_terminal_progress_json jsonb:='{}'::jsonb;
  v_terminal_progress_recompute_result jsonb:='{}'::jsonb;
  v_terminal_existing_successor_proven boolean:=false;
  v_terminal_live_change_seq bigint:=0;
  v_recovery_first_divergent_cause jsonb:=NULL::jsonb;
  v_recovery_first_divergent_attempt_number integer:=NULL::integer;
  v_recovery_latest_observed_failure jsonb:=NULL::jsonb;
  v_recovery_error_json jsonb:=NULL::jsonb;
BEGIN
  IF v_worker_id IS NULL OR v_lane_identity IS NULL
     OR char_length(v_worker_id)>200 OR char_length(v_lane_identity)>200 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_CALLER_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_ATTEMPT_CALLER_INVALID'
      )::text;
  END IF;
  IF p_now_utc IS NOT NULL AND abs(extract(epoch FROM p_now_utc-v_database_now))>300 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_CUTOFF_INVALID' USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_db_worker_lease_seconds,25),
         to_jsonb(settings_row)
  INTO v_configured_lease,v_settings_json
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  v_same_authority_election_enabled:=COALESCE(
    (v_settings_json->>'banking_pay_same_authority_build_election_v1_enabled')::boolean,
    false
  );
  v_configured_lease := LEAST(GREATEST(COALESCE(v_configured_lease,25),5),120);
  v_effective_lease := LEAST(
    v_configured_lease,
    LEAST(GREATEST(COALESCE(p_lease_seconds,v_configured_lease),5),120)
  );

  v_scan_scope_key:=COALESCE(p_session_id::text,'*')||':'||
    COALESCE(p_candidate_id::text,'*');

  INSERT INTO private.banking_pay_workbench_queue_scan_state(
    lane_identity,scan_kind,scan_scope_key)
  VALUES(v_lane_identity,'RECOVERY',v_scan_scope_key)
  ON CONFLICT(lane_identity,scan_kind,scan_scope_key) DO NOTHING;
  SELECT cursor_generation,cursor_due_at,cursor_object_id
  INTO v_recovery_cursor_generation,v_recovery_cursor_due_at,v_recovery_cursor_object_id
  FROM private.banking_pay_workbench_queue_scan_state
  WHERE lane_identity=v_lane_identity AND scan_kind='RECOVERY'
    AND scan_scope_key=v_scan_scope_key
  FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'claimed',false,'result_code','LANE_SCAN_BUSY');
  END IF;

  -- Small indexed lease-recovery page.  No financial source relation is read.
  FOR v_recovery IN
    SELECT attempt.id attempt_id,attempt.job_id,attempt.build_id,attempt.candidate_id,
           job.session_id,
           attempt.lease_expires_at_utc,
           job.attempt_count,job.max_attempts,
           CASE WHEN COALESCE(job.payload_json->>'recovery_scan_generation','') ~ '^\d+$'
             THEN LEAST((job.payload_json->>'recovery_scan_generation')::bigint,2147483647)
             ELSE 0 END AS scan_generation
    FROM private.banking_pay_workbench_stage_attempts attempt
    JOIN public.banking_pay_workbench_jobs job ON job.id=attempt.job_id
    WHERE attempt.attempt_status='STARTED'
      AND clock_timestamp()>=attempt.lease_expires_at_utc+interval '15 seconds'
      AND job.status='RUNNING' AND job.economic_build_id=attempt.build_id
      AND (p_session_id IS NULL OR job.session_id=p_session_id)
      AND (p_candidate_id IS NULL OR job.candidate_id=p_candidate_id)
      AND (COALESCE(job.payload_json->>'recovery_scan_deferred_epoch','') !~ '^\d+(\.\d+)?$'
        OR (job.payload_json->>'recovery_scan_deferred_epoch')::numeric
          <=extract(epoch FROM clock_timestamp()))
      AND (v_recovery_cursor_object_id IS NULL OR
        ROW(
          CASE WHEN COALESCE(job.payload_json->>'recovery_scan_generation','') ~ '^\d+$'
            THEN LEAST((job.payload_json->>'recovery_scan_generation')::bigint,2147483647)
            ELSE 0 END,
          attempt.lease_expires_at_utc,attempt.id
        ) > ROW(v_recovery_cursor_generation,
          v_recovery_cursor_due_at,v_recovery_cursor_object_id))
    ORDER BY scan_generation,attempt.lease_expires_at_utc,attempt.id LIMIT v_scan_limit
  LOOP
    v_recovery_examined:=v_recovery_examined+1;
    UPDATE private.banking_pay_workbench_queue_scan_state
    SET cursor_generation=v_recovery.scan_generation,cursor_chain_rank=NULL,
      cursor_priority=NULL,cursor_due_at=v_recovery.lease_expires_at_utc,
      cursor_created_at=NULL,cursor_object_id=v_recovery.attempt_id,
      updated_at_utc=clock_timestamp()
    WHERE lane_identity=v_lane_identity AND scan_kind='RECOVERY'
      AND scan_scope_key=v_scan_scope_key;
    IF pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_recovery.candidate_id),24062027)) THEN
      PERFORM 1 FROM private.banking_pay_workbench_candidate_scope_registry
      WHERE candidate_id=v_recovery.candidate_id FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      PERFORM 1 FROM private.banking_pay_workbench_economic_builds
      WHERE id=v_recovery.build_id FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      PERFORM 1 FROM public.banking_pay_workbench_jobs
      WHERE id=v_recovery.job_id FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      PERFORM 1 FROM private.banking_pay_workbench_stage_attempts
      WHERE id=v_recovery.attempt_id FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      UPDATE private.banking_pay_workbench_stage_attempts SET attempt_status='EXPIRED',
        expired_at_utc=clock_timestamp(),result_code='LEASE_EXPIRED_AFTER_CANCELLATION_GRACE',
        error_class='DELIVERED_ATTEMPT_EXPIRED',error_json=jsonb_build_object(
          'code','LEASE_EXPIRED_AFTER_CANCELLATION_GRACE'),updated_at_utc=clock_timestamp()
      WHERE id=v_recovery.attempt_id AND attempt_status='STARTED'
        AND clock_timestamp()>=lease_expires_at_utc+interval '15 seconds';
      IF FOUND THEN
        v_recovered_count:=v_recovered_count+1;

        -- The private attempt ledger is the existing ordered causal authority.
        -- Lease expiry and terminal exhaustion describe later recovery events;
        -- neither may replace an earlier concrete stage divergence.
        v_recovery_first_divergent_cause:=NULL::jsonb;
        v_recovery_first_divergent_attempt_number:=NULL::integer;
        SELECT attempt.error_json,attempt.attempt_number
        INTO v_recovery_first_divergent_cause,v_recovery_first_divergent_attempt_number
        FROM private.banking_pay_workbench_stage_attempts AS attempt
        WHERE attempt.job_id=v_recovery.job_id
          AND jsonb_typeof(attempt.error_json)='object'
          AND attempt.error_json<>'{}'::jsonb
          AND NULLIF(BTRIM(COALESCE(attempt.error_json->>'code','')),'') IS NOT NULL
        ORDER BY attempt.attempt_number,attempt.started_at_utc,attempt.id
        LIMIT 1;
        v_recovery_first_divergent_cause:=COALESCE(
          v_recovery_first_divergent_cause,
          jsonb_build_object('code','LEASE_EXPIRED_AFTER_CANCELLATION_GRACE')
        );
        v_recovery_first_divergent_attempt_number:=COALESCE(
          v_recovery_first_divergent_attempt_number,
          v_recovery.attempt_count
        );
        v_recovery_latest_observed_failure:=jsonb_build_object(
          'code','LEASE_EXPIRED_AFTER_CANCELLATION_GRACE'
        );

        IF v_recovery.attempt_count<v_recovery.max_attempts THEN
          v_recovery_error_json:=jsonb_build_object(
            'code','DELIVERED_ATTEMPT_EXPIRED',
            'causal_contract_version','WORKBENCH_FIRST_DIVERGENT_CAUSE_V1',
            'first_divergent_cause',v_recovery_first_divergent_cause,
            'first_divergent_attempt_number',v_recovery_first_divergent_attempt_number,
            'latest_observed_failure',v_recovery_latest_observed_failure,
            'latest_attempt_number',v_recovery.attempt_count
          );
          UPDATE public.banking_pay_workbench_jobs SET status='QUEUED',started_at_utc=NULL,
            run_at_utc=clock_timestamp()+make_interval(secs=>LEAST(300,
              GREATEST(1,power(2,LEAST(v_recovery.attempt_count,8))::integer))),
            payload_json=COALESCE(payload_json,'{}'::jsonb)
              -'recovery_scan_deferred_epoch'-'recovery_scan_deferral_count'-'recovery_scan_generation',
            last_error_json=v_recovery_error_json,
            updated_at_utc=clock_timestamp() WHERE id=v_recovery.job_id AND status='RUNNING';
        ELSE
          v_recovery_error_json:=jsonb_build_object(
            'code','DELIVERED_ATTEMPT_EXHAUSTED',
            'causal_contract_version','WORKBENCH_FIRST_DIVERGENT_CAUSE_V1',
            'first_divergent_cause',v_recovery_first_divergent_cause,
            'first_divergent_attempt_number',v_recovery_first_divergent_attempt_number,
            'latest_observed_failure',v_recovery_latest_observed_failure,
            'latest_attempt_number',v_recovery.attempt_count
          );
          UPDATE public.banking_pay_workbench_jobs SET status='FAILED',failed_at_utc=clock_timestamp(),
            payload_json=COALESCE(payload_json,'{}'::jsonb)
              -'recovery_scan_deferred_epoch'-'recovery_scan_deferral_count'-'recovery_scan_generation',
            last_error_json=v_recovery_error_json,
            updated_at_utc=clock_timestamp() WHERE id=v_recovery.job_id AND status='RUNNING';
          UPDATE private.banking_pay_workbench_economic_builds SET status='FAILED',
            failed_at_utc=clock_timestamp(),failure_json=v_recovery_error_json,
            updated_at_utc=clock_timestamp()
          WHERE id=v_recovery.build_id AND status NOT IN ('COMPLETE','OBSOLETE');

          /* A prior bounded repair may already have rebound the scope to a
             valid successor while the exhausted delivered attempt remains
             STARTED.  In that state the orphan repair correctly has no row to
             change.  Requiring repaired_count=1 makes this recovery transaction
             roll back forever before the already-owned successor can be
             claimed.  Prove that exact already-rebound state directly; only
             call the repair owner when no such successor exists. */
          v_terminal_existing_successor_proven:=false;
          v_terminal_successor_job_id:=NULL::uuid;
          SELECT COALESCE(change_counter.seq,0)
          INTO v_terminal_live_change_seq
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key='pay_candidate:'||v_recovery.candidate_id::text;
          v_terminal_live_change_seq:=COALESCE(v_terminal_live_change_seq,0);

          SELECT scope_row.* INTO v_terminal_scope
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id=v_recovery.session_id
            AND scope_row.candidate_id=v_recovery.candidate_id
            AND scope_row.pending_job_id IS NOT NULL
            AND scope_row.pending_job_id IS DISTINCT FROM v_recovery.job_id
            AND UPPER(BTRIM(COALESCE(scope_row.status,'')))='SOURCE_BUILD_PENDING'
            AND COALESCE(scope_row.dirty,false)=true
            AND scope_row.error_json IS NULL
          FOR UPDATE;

          IF FOUND THEN
            SELECT successor.id INTO v_terminal_successor_job_id
            FROM public.banking_pay_workbench_jobs AS successor
            JOIN public.banking_pay_workbench_sessions AS successor_session
              ON successor_session.id=successor.session_id
            WHERE successor.id=v_terminal_scope.pending_job_id
              AND successor.session_id=v_terminal_scope.session_id
              AND successor.candidate_id=v_terminal_scope.candidate_id
              AND UPPER(BTRIM(COALESCE(successor.status,''))) IN ('QUEUED','RUNNING')
              AND UPPER(BTRIM(COALESCE(successor.job_type,''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE')
              AND CASE
                WHEN COALESCE(successor.payload_json->>'session_version','') ~ '^[0-9]{1,18}$'
                  THEN (successor.payload_json->>'session_version')::bigint
                ELSE NULL::bigint END=successor_session.version
              AND CASE
                WHEN COALESCE(successor.payload_json->>'source_change_seq','') ~ '^[0-9]{1,18}$'
                  THEN (successor.payload_json->>'source_change_seq')::bigint
                ELSE NULL::bigint END>=v_terminal_live_change_seq
              AND COALESCE(successor.payload_json->>'source_build_run_id','')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            FOR UPDATE OF successor,successor_session;
            v_terminal_existing_successor_proven:=FOUND;
          END IF;

          IF v_terminal_existing_successor_proven THEN
            v_terminal_action:='REBOUND_ACTIVE_SUCCESSOR';
            v_terminal_progress_recompute_result:=
              public.pay_workbench_session_recompute_progress_counters(
                p_session_id=>v_recovery.session_id,
                p_apply=>true,
                p_reason=>'EXHAUSTED_ATTEMPT_EXISTING_SUCCESSOR_PROVEN',
                p_write_progress_json=>true);
            IF jsonb_typeof(v_terminal_progress_recompute_result)<>'object'
               OR COALESCE((v_terminal_progress_recompute_result->>'ok')::boolean,false)
                  IS NOT TRUE THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
                USING ERRCODE='40001',DETAIL='EXISTING_SUCCESSOR_PROGRESS_RECOMPUTE';
            END IF;
            v_terminal_repair_row:=jsonb_build_object(
              'session_id',v_recovery.session_id::text,
              'candidate_id',v_recovery.candidate_id::text,
              'old_pending_job_id',v_recovery.job_id::text,
              'action',v_terminal_action,
              'successor_job_id',v_terminal_successor_job_id::text,
              'state_transition_proven',true,
              'progress_recomputed',true,
              'already_rebound_successor_proven',true);
            v_terminal_repair_result:=jsonb_build_object(
              'ok',true,
              'already_rebound_successor_proven',true,
              'results',jsonb_build_array(v_terminal_repair_row));
          ELSE
            v_terminal_repair_result:=public.pay_workbench_repair_orphaned_pending_source_build(
              p_session_id=>v_recovery.session_id,
              p_candidate_id=>v_recovery.candidate_id,
              p_limit=>1,
              p_now_utc=>v_database_now,
              p_reason=>'EXHAUSTED_DELIVERED_ATTEMPT_ATOMIC_CONVERGENCE');
            v_terminal_repair_row:=COALESCE(v_terminal_repair_result->'results'->0,'{}'::jsonb);
            v_terminal_action:=NULLIF(BTRIM(v_terminal_repair_row->>'action'),'');
            v_terminal_successor_job_id:=CASE
              WHEN COALESCE(v_terminal_repair_row->>'successor_job_id','')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                THEN (v_terminal_repair_row->>'successor_job_id')::uuid END;

            IF COALESCE((v_terminal_repair_result->>'ok')::boolean,false) IS NOT TRUE
               OR COALESCE((v_terminal_repair_result->>'examined_count')::integer,-1)<>1
               OR COALESCE((v_terminal_repair_result->>'repaired_count')::integer,-1)<>1
               OR COALESCE((v_terminal_repair_result->>'skipped_count')::integer,-1)<>0
               OR COALESCE((v_terminal_repair_result->>'unresolved_count')::integer,-1)<>0
               OR COALESCE((v_terminal_repair_result->>'progress_recompute_failed_count')::integer,-1)<>0
               OR COALESCE((v_terminal_repair_result->>'all_state_transitions_proven')::boolean,false)
                  IS NOT TRUE
               OR COALESCE((v_terminal_repair_result->>'all_progress_recomputed')::boolean,false)
                  IS NOT TRUE
               OR jsonb_array_length(COALESCE(v_terminal_repair_result->'results','[]'::jsonb))<>1
               OR COALESCE(v_terminal_repair_row->>'candidate_id','')<>v_recovery.candidate_id::text
               OR COALESCE((v_terminal_repair_row->>'state_transition_proven')::boolean,false)
                  IS NOT TRUE
               OR COALESCE((v_terminal_repair_row->>'progress_recomputed')::boolean,false)
                  IS NOT TRUE
               OR v_terminal_action NOT IN ('FAILED_CLOSED_DETERMINISTIC_SOURCE',
                 'FAILED_CLOSED_MAX_ATTEMPTS','REBOUND_ACTIVE_SUCCESSOR',
                 'RECONCILED_SUCCESSFUL_BUILD') THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
                USING ERRCODE='40001',DETAIL=jsonb_build_object(
                  'candidate_id',v_recovery.candidate_id,
                  'job_id',v_recovery.job_id,
                  'repair_result',v_terminal_repair_result)::text;
            END IF;
          END IF;

          IF v_terminal_action IN (
            'FAILED_CLOSED_DETERMINISTIC_SOURCE','FAILED_CLOSED_MAX_ATTEMPTS'
          ) THEN
            UPDATE public.banking_pay_workbench_session_scope AS failed_scope
            SET error_json=COALESCE(failed_scope.error_json,'{}'::jsonb)
                  || (v_recovery_error_json-'code'-'message'-'sqlstate'),
                updated_at_utc=clock_timestamp()
            WHERE failed_scope.session_id=v_recovery.session_id
              AND failed_scope.candidate_id=v_recovery.candidate_id
              AND UPPER(BTRIM(COALESCE(failed_scope.status,'')))='SOURCE_BUILD_ERROR'
              AND failed_scope.pending_job_id IS NULL;
            UPDATE public.banking_pay_workbench_session_candidate_state AS failed_state
            SET last_error_json=COALESCE(failed_state.last_error_json,'{}'::jsonb)
                  || (v_recovery_error_json-'code'-'message'-'sqlstate'),
                updated_at_utc=clock_timestamp()
            WHERE failed_state.session_id=v_recovery.session_id
              AND failed_state.candidate_id=v_recovery.candidate_id
              AND UPPER(BTRIM(COALESCE(failed_state.status,'')))='FAILED'
              AND failed_state.pending_job_id IS NULL;
          END IF;

          SELECT scope_row.* INTO v_terminal_scope
          FROM public.banking_pay_workbench_session_scope scope_row
          WHERE scope_row.session_id=(v_terminal_repair_row->>'session_id')::uuid
            AND scope_row.candidate_id=v_recovery.candidate_id
          FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
              USING ERRCODE='40001',DETAIL='TERMINAL_SCOPE_MISSING';
          END IF;

          SELECT state_row.* INTO v_terminal_candidate_state
          FROM public.banking_pay_workbench_session_candidate_state state_row
          WHERE state_row.session_id=v_terminal_scope.session_id
            AND state_row.candidate_id=v_terminal_scope.candidate_id
          FOR UPDATE;
          v_terminal_candidate_state_present:=FOUND;

          SELECT COALESCE(session_row.progress_json,'{}'::jsonb)
          INTO v_terminal_progress_json
          FROM public.banking_pay_workbench_sessions session_row
          WHERE session_row.id=v_terminal_scope.session_id
          FOR UPDATE;

          IF v_terminal_action IN (
            'FAILED_CLOSED_DETERMINISTIC_SOURCE','FAILED_CLOSED_MAX_ATTEMPTS'
          ) THEN
            IF UPPER(BTRIM(COALESCE(v_terminal_scope.status,'')))<>'SOURCE_BUILD_ERROR'
               OR v_terminal_scope.pending_job_id IS NOT NULL
               OR NULLIF(BTRIM(COALESCE(v_terminal_scope.error_json->>'code','')),'') IS NULL
               OR (v_terminal_candidate_state_present AND (
                 UPPER(BTRIM(COALESCE(v_terminal_candidate_state.status,'')))<>'FAILED'
                 OR v_terminal_candidate_state.pending_job_id IS NOT NULL
                 OR v_terminal_scope.error_json->>'code' IS DISTINCT FROM
                      v_terminal_candidate_state.last_error_json->>'code')) THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
                USING ERRCODE='40001',DETAIL='FAILED_CLOSED_POSTCONDITION';
            END IF;
          ELSIF v_terminal_action='REBOUND_ACTIVE_SUCCESSOR' THEN
            SELECT EXISTS(SELECT 1
              FROM public.banking_pay_workbench_jobs successor
              WHERE successor.id=v_terminal_successor_job_id
                AND successor.session_id=v_terminal_scope.session_id
                AND successor.candidate_id=v_terminal_scope.candidate_id
                AND UPPER(BTRIM(COALESCE(successor.status,''))) IN ('QUEUED','RUNNING'))
            INTO v_terminal_owner_valid;
            IF UPPER(BTRIM(COALESCE(v_terminal_scope.status,'')))<>'SOURCE_BUILD_PENDING'
               OR v_terminal_successor_job_id IS NULL
               OR v_terminal_scope.pending_job_id IS DISTINCT FROM v_terminal_successor_job_id
               OR v_terminal_owner_valid IS NOT TRUE
               OR (v_terminal_candidate_state_present AND (
                 UPPER(BTRIM(COALESCE(v_terminal_candidate_state.status,'')))<>'PENDING'
                 OR v_terminal_candidate_state.pending_job_id IS DISTINCT FROM
                      v_terminal_successor_job_id
                 OR COALESCE(v_terminal_candidate_state.last_error_json,'{}'::jsonb)<>'{}'::jsonb)) THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
                USING ERRCODE='40001',DETAIL='REBOUND_POSTCONDITION';
            END IF;
          ELSE
            IF UPPER(BTRIM(COALESCE(v_terminal_scope.status,''))) NOT IN (
                 'SOURCE_READY','LINE_WORK_PENDING','MATERIALISED','MATERIALIZED','READY','SOURCE_EMPTY')
               OR COALESCE(v_terminal_scope.dirty,true)
               OR v_terminal_scope.pending_job_id IS NOT DISTINCT FROM v_recovery.job_id
               OR (v_terminal_candidate_state_present AND (
                 UPPER(BTRIM(COALESCE(v_terminal_candidate_state.status,'')))='FAILED'
                 OR v_terminal_candidate_state.pending_job_id IS NOT DISTINCT FROM v_recovery.job_id
                 OR v_terminal_candidate_state.session_version IS DISTINCT FROM
                      v_terminal_scope.session_version
                 OR v_terminal_candidate_state.source_change_seq IS DISTINCT FROM
                      v_terminal_scope.source_change_seq)) THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
                USING ERRCODE='40001',DETAIL='RECONCILED_POSTCONDITION';
            END IF;
          END IF;

          IF COALESCE((v_terminal_progress_json->>'recovery_required_count')::integer,0)<>0
             OR COALESCE((v_terminal_progress_json#>>'{blocker_counts,pending_scope_without_active_job}')::integer,0)<>0 THEN
            RAISE EXCEPTION 'PAY_WORKBENCH_EXHAUSTED_ATTEMPT_CONVERGENCE_UNPROVEN'
              USING ERRCODE='40001',DETAIL='SESSION_PROGRESS_POSTCONDITION';
          END IF;
        END IF;

        PERFORM public._audit_insert(
          'banking_pay_workbench_job',
          v_recovery.job_id::text,
          CASE
            WHEN v_recovery.attempt_count<v_recovery.max_attempts
              THEN 'DELIVERED_ATTEMPT_EXPIRED_REQUEUED'
            ELSE 'DELIVERED_ATTEMPT_EXHAUSTED'
          END,
          jsonb_build_object(
            'attempt_id',v_recovery.attempt_id::text,
            'attempt_number',v_recovery.attempt_count,
            'lease_expires_at_utc',v_recovery.lease_expires_at_utc::text,
            'cancellation_grace_seconds',15
          ),
          v_recovery_error_json,
          CASE
            WHEN v_recovery.attempt_count<v_recovery.max_attempts
              THEN 'DELIVERED_ATTEMPT_EXPIRED_REQUEUED'
            ELSE 'DELIVERED_ATTEMPT_EXHAUSTED'
          END,
          NULL
        );
        IF v_recovered_count>=5 THEN EXIT; END IF;
      END IF;
    ELSE
      -- The durable lane cursor already advanced past this attempt. Never wait
      -- behind the transaction that owns the candidate merely to annotate its
      -- public job; another bounded scan can revisit it after cursor wrap.
      CONTINUE;
    END IF;
  END LOOP;

  IF v_recovery_examined=0 AND v_recovery_cursor_object_id IS NOT NULL THEN
    UPDATE private.banking_pay_workbench_queue_scan_state
    SET cursor_generation=NULL,cursor_chain_rank=NULL,cursor_priority=NULL,
      cursor_due_at=NULL,cursor_created_at=NULL,cursor_object_id=NULL,
      sweep_generation=sweep_generation+1,updated_at_utc=clock_timestamp()
    WHERE lane_identity=v_lane_identity AND scan_kind='RECOVERY'
      AND scan_scope_key=v_scan_scope_key;
  END IF;

  INSERT INTO private.banking_pay_workbench_queue_scan_state(
    lane_identity,scan_kind,scan_scope_key)
  VALUES(v_lane_identity,'CLAIM',v_scan_scope_key)
  ON CONFLICT(lane_identity,scan_kind,scan_scope_key) DO NOTHING;
  SELECT cursor_generation,cursor_chain_rank,cursor_priority,cursor_due_at,
    cursor_created_at,cursor_object_id
  INTO v_claim_cursor_generation,v_claim_cursor_chain_rank,v_claim_cursor_priority,
    v_claim_cursor_due_at,v_claim_cursor_created_at,v_claim_cursor_object_id
  FROM private.banking_pay_workbench_queue_scan_state
  WHERE lane_identity=v_lane_identity AND scan_kind='CLAIM'
    AND scan_scope_key=v_scan_scope_key
  FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',true,'claimed',false,'result_code','LANE_SCAN_BUSY');
  END IF;

  -- Source-only form of the installed claim ordering and candidate-serial
  -- predicates.  The advisory lock is attempted only after the bounded final
  -- eligibility set, then the exact queue row is locked and rechecked.  RPC 1
  -- does not transition the job to RUNNING until its concrete build exists.
  -- A29: at most two sweeps per call.  When the durable cursor is past every
  -- remaining eligible row (a non-empty sweep has ended), the cursor is reset
  -- exactly as before and the scan restarts once from the new sweep's start in
  -- this same call, instead of returning an empty CLAIM_SCAN_CURSOR_WRAPPED
  -- result that only asks the Worker to call again.
  <<claim_sweep>>
  LOOP
  FOR v_claim IN
    WITH claim_source AS MATERIALIZED (
      SELECT job.id,job.priority,job.run_at_utc,job.created_at_utc,job.payload_json,
        job.private_stage,
        CASE WHEN COALESCE(job.payload_json->>'claim_scan_generation','') ~ '^\d+$'
          THEN LEAST((job.payload_json->>'claim_scan_generation')::bigint,2147483647)
          ELSE 0 END AS scan_generation,
        public._pay_workbench_candidate_serial_candidate_id(job.candidate_id,job.payload_json) AS serial_candidate_id,
        public._pay_workbench_candidate_serial_key(
          public._pay_workbench_candidate_serial_candidate_id(job.candidate_id,job.payload_json)) AS serial_key,
        CASE WHEN (lower(btrim(COALESCE(job.payload_json->>'continuation','false'))) IN ('true','t','1','yes','y','on')
          OR upper(btrim(COALESCE(job.payload_json->>'run_mode',''))) IN
            ('BOUNDED_CONTINUATION','CONTINUATION','STAGE_CONTINUATION')
          OR NULLIF(btrim(COALESCE(job.payload_json->>'source_job_id',
            job.payload_json->>'continuation_source_job_id',
            job.payload_json->>'bounded_continuation_source_job_id','')),'') IS NOT NULL)
          THEN 0 ELSE 1 END AS chain_rank
      FROM public.banking_pay_workbench_jobs job
      WHERE job.status='QUEUED'
        AND job.job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND job.run_at_utc<=v_now
        AND COALESCE(job.attempt_count,0)<COALESCE(job.max_attempts,8)
        AND job.candidate_id IS NOT NULL AND job.session_id IS NOT NULL
        AND (p_session_id IS NULL OR job.session_id=p_session_id)
        AND (p_candidate_id IS NULL OR job.candidate_id=p_candidate_id)
        AND NOT EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts active_attempt
          WHERE active_attempt.job_id=job.id AND active_attempt.attempt_status='STARTED')
        AND ((job.economic_build_id IS NULL AND ((job.private_stage='BUILD_INITIALISE'
            AND job.private_cursor_kind='BUILD_INITIALISE') OR (job.private_stage IS NULL
            AND job.private_cursor_kind IS NULL AND job.private_stage_version IS NULL)))
          OR (job.economic_build_id IS NOT NULL AND job.private_stage IS NOT NULL
            AND job.private_stage<>'BUILD_INITIALISE' AND job.private_cursor_kind IS NOT NULL
            AND job.private_stage_version IS NOT NULL))
        AND (v_claim_cursor_object_id IS NULL OR ROW(
          CASE WHEN COALESCE(job.payload_json->>'claim_scan_generation','') ~ '^\d+$'
            THEN LEAST((job.payload_json->>'claim_scan_generation')::bigint,2147483647)
            ELSE 0 END,
          CASE WHEN (lower(btrim(COALESCE(job.payload_json->>'continuation','false'))) IN ('true','t','1','yes','y','on')
            OR upper(btrim(COALESCE(job.payload_json->>'run_mode',''))) IN
              ('BOUNDED_CONTINUATION','CONTINUATION','STAGE_CONTINUATION')
            OR NULLIF(btrim(COALESCE(job.payload_json->>'source_job_id',
              job.payload_json->>'continuation_source_job_id',
              job.payload_json->>'bounded_continuation_source_job_id','')),'') IS NOT NULL)
            THEN 0 ELSE 1 END,
          job.priority,job.run_at_utc,job.created_at_utc,job.id
        ) > ROW(v_claim_cursor_generation,v_claim_cursor_chain_rank,
          v_claim_cursor_priority,v_claim_cursor_due_at,
          v_claim_cursor_created_at,v_claim_cursor_object_id))
      ORDER BY scan_generation,chain_rank,job.priority,job.run_at_utc,job.created_at_utc,job.id
      LIMIT v_scan_limit
    ), ranked AS MATERIALIZED (
      SELECT claim_source.*,row_number() OVER (
        PARTITION BY COALESCE(claim_source.serial_key,claim_source.id::text)
        ORDER BY claim_source.scan_generation,
          claim_source.chain_rank,
          claim_source.priority,claim_source.run_at_utc,claim_source.created_at_utc,claim_source.id) AS serial_rank
      FROM claim_source
    )
    SELECT ranked.*,
      lower(btrim(COALESCE(serial_state.state_json->>'blocked','false')))
        IN ('true','t','1','yes','y','on') AS serial_blocked
    FROM ranked
    CROSS JOIN LATERAL (SELECT public._pay_workbench_candidate_serial_active_state(
      ranked.id,ranked.serial_candidate_id,'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      ranked.payload_json,v_now) AS state_json) serial_state
    WHERE ranked.serial_rank=1
    ORDER BY ranked.scan_generation,ranked.chain_rank,
      ranked.priority,ranked.run_at_utc,ranked.created_at_utc,ranked.id
  LOOP
    v_claim_examined:=v_claim_examined+1;
    UPDATE private.banking_pay_workbench_queue_scan_state
    SET cursor_generation=v_claim.scan_generation,cursor_chain_rank=v_claim.chain_rank,
      cursor_priority=v_claim.priority,cursor_due_at=v_claim.run_at_utc,
      cursor_created_at=v_claim.created_at_utc,cursor_object_id=v_claim.id,
      updated_at_utc=clock_timestamp()
    WHERE lane_identity=v_lane_identity AND scan_kind='CLAIM'
      AND scan_scope_key=v_scan_scope_key;
    IF v_claim.serial_blocked THEN
      -- Cursor progress supplies fairness. Mutating a serial-blocked queue row
      -- here can wait behind its owner and turn a safe no-claim into an
      -- uncertain HTTP result.
      CONTINUE;
    END IF;
    IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
      COALESCE(v_claim.serial_key,v_claim.id::text),24062027)) THEN
      -- Losing lanes skip immediately. They must not update the row protected
      -- by the winning lane, because that update introduces an avoidable wait
      -- into the one-second claim transaction.
      CONTINUE;
    END IF;
    IF v_claim.private_stage='RECONCILE_EXECUTE' THEN
      -- Serialise the admission check itself.  The lock is transaction-scoped:
      -- once the first claim commits, the next lane observes its durable
      -- STARTED attempt before deciding whether another reconciliation fits.
      IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
        'BANKING_PAY_WORKBENCH:RECONCILE_EXECUTE:ADMISSION',24062027)) THEN
        CONTINUE;
      END IF;
      IF (
        SELECT count(*)
        FROM private.banking_pay_workbench_stage_attempts AS active_reconcile
        JOIN public.banking_pay_workbench_jobs AS active_reconcile_job
          ON active_reconcile_job.id=active_reconcile.job_id
        WHERE active_reconcile.attempt_status='STARTED'
          AND active_reconcile.private_stage='RECONCILE_EXECUTE'
          AND active_reconcile_job.status='RUNNING'
          AND clock_timestamp()
              < active_reconcile.lease_expires_at_utc+interval '15 seconds'
      )>=v_reconcile_attempt_limit THEN
        CONTINUE;
      END IF;
    END IF;
    v_job:=NULL;
    SELECT claimed_job.* INTO v_job
    FROM public.banking_pay_workbench_jobs claimed_job
    WHERE claimed_job.id=v_claim.id AND claimed_job.status='QUEUED'
      AND claimed_job.run_at_utc<=v_now
      AND COALESCE(claimed_job.attempt_count,0)<COALESCE(claimed_job.max_attempts,8)
      AND NOT EXISTS(SELECT 1 FROM private.banking_pay_workbench_stage_attempts active_attempt
        WHERE active_attempt.job_id=claimed_job.id AND active_attempt.attempt_status='STARTED')
    FOR UPDATE OF claimed_job SKIP LOCKED;
    EXIT WHEN v_job.id IS NOT NULL;
  END LOOP;

  EXIT claim_sweep WHEN v_job.id IS NOT NULL OR v_claim_examined>0
    OR v_claim_cursor_object_id IS NULL OR v_claim_sweep_restarted;
  -- The cursor is past every eligible row: end this sweep (same reset as the
  -- former wrapped return) and scan once more from the start of the next one.
  UPDATE private.banking_pay_workbench_queue_scan_state
  SET cursor_generation=NULL,cursor_chain_rank=NULL,cursor_priority=NULL,
    cursor_due_at=NULL,cursor_created_at=NULL,cursor_object_id=NULL,
    sweep_generation=sweep_generation+1,updated_at_utc=clock_timestamp()
  WHERE lane_identity=v_lane_identity AND scan_kind='CLAIM'
    AND scan_scope_key=v_scan_scope_key;
  v_claim_cursor_generation:=NULL;
  v_claim_cursor_chain_rank:=NULL;
  v_claim_cursor_priority:=NULL;
  v_claim_cursor_due_at:=NULL;
  v_claim_cursor_created_at:=NULL;
  v_claim_cursor_object_id:=NULL;
  v_claim_sweep_restarted:=true;
  END LOOP claim_sweep;

  IF v_claim_examined=0 AND v_claim_cursor_object_id IS NOT NULL THEN
    UPDATE private.banking_pay_workbench_queue_scan_state
    SET cursor_generation=NULL,cursor_chain_rank=NULL,cursor_priority=NULL,
      cursor_due_at=NULL,cursor_created_at=NULL,cursor_object_id=NULL,
      sweep_generation=sweep_generation+1,updated_at_utc=clock_timestamp()
    WHERE lane_identity=v_lane_identity AND scan_kind='CLAIM'
      AND scan_scope_key=v_scan_scope_key;
    -- Reaching the end of a non-empty durable claim sweep is progress, not an
    -- empty queue.  The next bounded RPC 1 call must start at the beginning of
    -- the new sweep.  Return an explicit result so the Worker can continue
    -- within its existing burst/runtime limits instead of waiting for cron or
    -- unrelated UI traffic.
    RETURN jsonb_build_object(
      'ok',true,
      'claimed',false,
      'result_code','CLAIM_SCAN_CURSOR_WRAPPED',
      'scan_progress',true,
      'claim_scan_wrapped',true,
      'claim_examined',0
    );
  END IF;

  IF v_job.id IS NULL THEN
    IF v_claim_examined>0 THEN
      -- The lane advanced past a candidate whose serial/advisory/job-row
      -- authority was temporarily unavailable.  Preserve that fairness
      -- progress and request another bounded pass; do not present it as an
      -- authoritative no-work result.
      RETURN jsonb_build_object(
        'ok',true,
        'claimed',false,
        'result_code','CLAIM_SCAN_PROGRESS',
        'scan_progress',true,
        'claim_scan_wrapped',false,
        'claim_examined',v_claim_examined
      );
    END IF;
    RETURN jsonb_build_object('ok',true,'claimed',false);
  END IF;

  PERFORM 1 FROM public.candidates AS candidate_row
  WHERE candidate_row.id=v_job.candidate_id FOR UPDATE;
  IF NOT FOUND THEN
    UPDATE public.banking_pay_workbench_jobs
    SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
        economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
        private_cursor_json='{}'::jsonb,private_stage_version=NULL,
        last_error_json=jsonb_build_object('code','CANDIDATE_DELETED_BEFORE_ATTEMPT')
    WHERE id=v_job.id AND status='QUEUED';
    RETURN jsonb_build_object('ok',true,'claimed',false,'result_code','CANDIDATE_DELETED');
  END IF;

  INSERT INTO private.banking_pay_workbench_candidate_scope_registry(
    candidate_id,last_dirtied_at_utc,created_at_utc,updated_at_utc
  )
  VALUES(v_job.candidate_id,v_database_now,v_database_now,v_database_now)
  ON CONFLICT(candidate_id) DO NOTHING;

  SELECT * INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id=v_job.candidate_id
  FOR UPDATE;

  SELECT * INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id=v_job.session_id;
  -- The session is validation input, not RPC-1 mutation authority. Taking a
  -- row lock here serialised otherwise independent candidate lanes behind a
  -- long-running RPC-2 attempt on the same session. The claimed build freezes
  -- the session version below and RPC 2/final publication revalidate it before
  -- any result can become authoritative.
  IF NOT FOUND OR v_session.status NOT IN ('OPEN','READY','REFRESHING') THEN
    IF v_job.economic_build_id IS NOT NULL THEN
      UPDATE private.banking_pay_workbench_economic_builds
      SET status='OBSOLETE',obsolete_at_utc=clock_timestamp(),
          failure_json=jsonb_build_object('code','SESSION_NO_LONGER_CURRENT'),
          updated_at_utc=clock_timestamp()
      WHERE id=v_job.economic_build_id AND status NOT IN ('COMPLETE','FAILED','OBSOLETE');
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET current_build_id=NULL,updated_at_utc=clock_timestamp()
      WHERE candidate_id=v_job.candidate_id AND current_build_id=v_job.economic_build_id;
    END IF;
    UPDATE public.banking_pay_workbench_jobs
    SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
        economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
        private_cursor_json='{}'::jsonb,private_stage_version=NULL,
        last_error_json=jsonb_build_object('code','SESSION_NO_LONGER_CURRENT')
    WHERE id=v_job.id AND status='QUEUED';
    RETURN jsonb_build_object('ok',true,'claimed',false,'result_code','SESSION_OBSOLETE');
  END IF;

  v_source_change_seq := GREATEST(
    v_registry.current_source_change_seq,
    COALESCE(CASE WHEN COALESCE(v_job.payload_json->>'source_change_seq','') ~ '^\d+$'
      THEN (v_job.payload_json->>'source_change_seq')::bigint END,0)
  );
  v_captured_generation := COALESCE(v_job.scope_change_generation,v_registry.dirty_generation,0);

  v_draft_deferral_enabled:=COALESCE(
    (v_settings_json->>'banking_pay_draft_self_invalidation_claim_deferral_v1_enabled')::boolean,
    false
  );
  IF v_draft_deferral_enabled
     AND v_job.economic_build_id IS NULL
     AND COALESCE(v_job.payload_json->>'draft_operation_id','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND NULLIF(pg_catalog.btrim(COALESCE(v_job.payload_json->>'draft_context_token','')),'') IS NOT NULL
     AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_job.payload_json->>'draft_phase',''))) IN (
       'INSERT_ITEMS','APPLY_FINANCE_ADJUSTMENTS','FINALISE_RESERVATIONS',
       'CREATE_TIMESHEET_SNAPSHOTS','BUILD_ITEM_BREAKDOWNS'
     ) THEN
    v_draft_operation_id:=(v_job.payload_json->>'draft_operation_id')::uuid;
    SELECT operation_row.* INTO v_draft_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id=v_draft_operation_id;

    IF FOUND
       AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_draft_operation.operation_type,'')))='DRAFT_CREATE'
       AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_draft_operation.status,''))) IN
         ('QUEUED','RUNNING','PROCESSING','CLAIMED','IN_PROGRESS')
       AND v_draft_operation.workbench_session_id=v_job.session_id
       AND pg_catalog.upper(pg_catalog.btrim(COALESCE(v_draft_operation.phase,''))) IN (
         'INSERT_ITEMS','APPLY_FINANCE_ADJUSTMENTS','FINALISE_RESERVATIONS',
         'POPULATE_CANDIDATE_SUMMARIES','CREATE_TIMESHEET_SNAPSHOTS','BUILD_ITEM_BREAKDOWNS',
         'ASSERT_INTEGRITY'
       )
       AND EXISTS(
         SELECT 1
         FROM public.banking_pay_operation_candidate_scope AS operation_scope
         WHERE operation_scope.operation_id=v_draft_operation_id
           AND operation_scope.workbench_session_id=v_job.session_id
           AND operation_scope.candidate_id=v_job.candidate_id
           AND operation_scope.pay_batch_id=v_draft_operation.pay_batch_id
           AND operation_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
       )
       AND v_source_change_seq<=v_registry.current_source_change_seq
       AND v_captured_generation<=v_registry.dirty_generation THEN
      v_draft_deferral_count:=CASE
        WHEN COALESCE(v_job.payload_json->>'draft_self_invalidation_deferral_count','') ~ '^\d+$'
          THEN LEAST((v_job.payload_json->>'draft_self_invalidation_deferral_count')::integer,12)
        ELSE 0
      END;
      IF v_draft_deferral_count<12 THEN
        v_draft_deferral_seconds:=CASE
          WHEN v_draft_deferral_count=0 THEN 2
          WHEN v_draft_deferral_count=1 THEN 3
          ELSE 5
        END;
        UPDATE public.banking_pay_workbench_jobs AS deferred_job
        SET run_at_utc=pg_catalog.clock_timestamp()+pg_catalog.make_interval(secs=>v_draft_deferral_seconds),
            payload_json=COALESCE(deferred_job.payload_json,'{}'::jsonb)
              || pg_catalog.jsonb_build_object(
                'draft_self_invalidation_deferral_count',v_draft_deferral_count+1,
                'draft_self_invalidation_deferred_at_utc',pg_catalog.clock_timestamp(),
                'draft_self_invalidation_result_code','DRAFT_CREATE_SELF_INVALIDATION_DEFERRED'
              ),
            updated_at_utc=pg_catalog.clock_timestamp()
        WHERE deferred_job.id=v_job.id AND deferred_job.status='QUEUED';
        RETURN pg_catalog.jsonb_build_object(
          'ok',true,'claimed',false,
          'result_code','DRAFT_CREATE_SELF_INVALIDATION_DEFERRED',
          'job_id',v_job.id,'candidate_id',v_job.candidate_id,
          'operation_id',v_draft_operation_id,
          'deferral_count',v_draft_deferral_count+1,
          'defer_seconds',v_draft_deferral_seconds
        );
      END IF;
    END IF;
  END IF;

  IF v_job.economic_build_id IS NULL THEN
    BEGIN
      v_execution_profile_version := COALESCE(
        NULLIF(v_settings_json->>'banking_pay_workbench_source_build_execution_profile_version','')::integer,
        1
      );
    EXCEPTION WHEN OTHERS THEN
      v_execution_profile_version := 1;
    END;
    IF v_execution_profile_version NOT IN (1,2) THEN
      v_execution_profile_version := 1;
    END IF;
    IF v_execution_profile_version=2 THEN
      BEGIN
        v_reconciliation_optimization_version:=COALESCE(
          NULLIF(v_settings_json->>'banking_pay_workbench_reconciliation_optimization_version','')::integer,0
        );
      EXCEPTION WHEN OTHERS THEN
        v_reconciliation_optimization_version:=0;
      END;
    END IF;
    v_reconciliation_optimization_version:=CASE WHEN v_reconciliation_optimization_version=1 THEN 1 ELSE 0 END;
    IF COALESCE(v_job.payload_json->>'source_build_run_id','')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED'
        USING ERRCODE='22023', DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED','job_id',v_job.id
        )::text;
    END IF;
    v_source_build_run_id := (v_job.payload_json->>'source_build_run_id')::uuid;
    IF v_same_authority_election_enabled THEN
      IF COALESCE(v_job.payload_json->>'authority_fingerprint_version','') NOT IN ('2','3')
         OR COALESCE(v_job.payload_json->>'authority_fingerprint','') !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_BUILD_AUTHORITY_FINGERPRINT_REQUIRED'
          USING ERRCODE='22023',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAY_WORKBENCH_SOURCE_BUILD_AUTHORITY_FINGERPRINT_REQUIRED',
            'job_id',v_job.id,
            'candidate_id',v_job.candidate_id
          )::text;
      END IF;
      v_authority_fingerprint_version:=(v_job.payload_json->>'authority_fingerprint_version')::smallint;
      v_authority_fingerprint:=v_job.payload_json->>'authority_fingerprint';
      v_required_physical_publication_contract_version:=CASE
        WHEN v_authority_fingerprint_version=3 THEN COALESCE(
          NULLIF(v_job.payload_json->>'required_physical_publication_contract_version','')::smallint,
          0
        ) ELSE 0 END;
      IF v_authority_fingerprint_version=3
         AND v_required_physical_publication_contract_version NOT IN (0,1) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_BUILD_PHYSICAL_PUBLICATION_CONTRACT_REQUIRED'
          USING ERRCODE='22023',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAY_WORKBENCH_SOURCE_BUILD_PHYSICAL_PUBLICATION_CONTRACT_REQUIRED',
            'job_id',v_job.id,'candidate_id',v_job.candidate_id
          )::text;
      END IF;
    END IF;
    v_is_bootstrap := COALESCE(v_job.payload_json->>'bootstrap_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND v_registry.initialisation_status<>'READY';
    IF v_is_bootstrap THEN
      v_bootstrap_id := (v_job.payload_json->>'bootstrap_id')::uuid;
    END IF;
    -- A26 (PRE-EXISTING SB02 fix, F-DRAFT-09): the partial unique index bpay_wb_economic_builds_candidate_active_uq
    -- allows one active build per Candidate and counts BLOCKED_UNVALIDATED_RECONCILIATION_SCALE as active. A build
    -- that no QUEUED/RUNNING job owns can never progress (the scale block ends its job SUCCEEDED), yet it kept the
    -- slot for ever, so every later claim for this Candidate raised 23505 here and the Candidate stayed wedged.
    -- Release only such dead holders (OBSOLETE, reason recorded) under the claim's existing Candidate locks. A
    -- build that still has a live job is untouched, exactly as before. Pre-Draft orchestration only; no amount.
    WITH released_holder AS (
      UPDATE private.banking_pay_workbench_economic_builds AS dead_holder
      SET status='OBSOLETE',obsolete_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
          failure_json=COALESCE(dead_holder.failure_json,'{}'::jsonb)||jsonb_build_object(
            'active_slot_release',jsonb_build_object('code','ACTIVE_BUILD_SLOT_RELEASED_FOR_RETRY',
              'previous_status',dead_holder.status,'released_by_job_id',v_job.id,
              'released_at_utc',clock_timestamp()::text))
      WHERE dead_holder.candidate_id=v_job.candidate_id
        AND dead_holder.status IN ('COLLECTING','READY_FOR_RECONCILIATION','RECONCILING','RECONCILED',
          'PUBLISHING','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE')
        AND NOT EXISTS (
          SELECT 1 FROM public.banking_pay_workbench_jobs AS live_job
          WHERE live_job.economic_build_id=dead_holder.id
            AND live_job.status IN ('QUEUED','RUNNING'))
      RETURNING dead_holder.id
    )
    UPDATE private.banking_pay_workbench_candidate_scope_registry AS released_registry
    SET current_build_id=NULL,updated_at_utc=clock_timestamp()
    WHERE released_registry.candidate_id=v_job.candidate_id
      AND released_registry.current_build_id IN (SELECT released_holder.id FROM released_holder);
    v_build_id := gen_random_uuid();
    BEGIN
    INSERT INTO private.banking_pay_workbench_economic_builds(
      id,candidate_id,session_id,session_version,source_snapshot_run_id,
      source_build_run_id,source_job_id,captured_candidate_generation,
      source_change_seq,status,private_stage,scope_cursor_json,attestation_json,
      authority_fingerprint_version,authority_fingerprint
    ) VALUES (
      v_build_id,v_job.candidate_id,v_job.session_id,v_session.version,v_session.source_snapshot_run_id,
      v_source_build_run_id,v_job.id,v_captured_generation,v_source_change_seq,
      'COLLECTING',CASE WHEN v_is_bootstrap THEN 'BOOTSTRAP_DISCOVERY' ELSE 'PREPARE_SCOPE' END,
      CASE WHEN v_is_bootstrap THEN jsonb_build_object(
        'cursor_kind','BOOTSTRAP_DISCOVERY','cursor_version',1,
        'bootstrap_id',v_bootstrap_id,'bootstrap_stream','TIMESHEETS_TSFIN',
        'last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',v_job.candidate_id,'captured_candidate_generation',v_captured_generation,
        'captured_source_change_seq',v_source_change_seq,'processed_source_rows',0
      ) ELSE jsonb_build_object(
        'cursor_kind','SCOPE_SELECT','cursor_version',1,
        'seed_family','ACTIVE_STATE','last_source_key',NULL,'build_id',v_build_id,
        'candidate_id',v_job.candidate_id,'captured_candidate_generation',v_captured_generation,
        'captured_source_change_seq',v_source_change_seq,'processed_source_rows',0
      ) END,
      jsonb_build_object(
        'execution_profile_version',v_execution_profile_version,
        'execution_profile_frozen_at_utc',clock_timestamp(),
        'execution_profile_authority','BUILD_CREATION_SETTINGS',
        'reconciliation_optimization_version',v_reconciliation_optimization_version,
        'reconciliation_optimization_frozen_at_utc',clock_timestamp(),
        'reconciliation_optimization_authority','BUILD_CREATION_SETTINGS',
        'authority_fingerprint_version',v_authority_fingerprint_version,
        'authority_fingerprint',v_authority_fingerprint,
        'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
        'source_publication_baseline_required',v_required_physical_publication_contract_version>=1
      ),
      v_authority_fingerprint_version,v_authority_fingerprint
    ) RETURNING id,scope_cursor_json INTO v_build_id,v_cursor_json;
    EXCEPTION WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_unique_constraint_name=CONSTRAINT_NAME;
      IF v_same_authority_election_enabled IS NOT TRUE
         OR v_unique_constraint_name IS DISTINCT FROM 'uq_bpay_wb_economic_build_authority_v1'
         OR v_authority_fingerprint_version IS NULL
         OR v_authority_fingerprint IS NULL THEN
        RAISE;
      END IF;

      SELECT winner.* INTO v_winner_build
      FROM private.banking_pay_workbench_economic_builds AS winner
      WHERE winner.candidate_id=v_job.candidate_id
        AND winner.authority_fingerprint_version=v_authority_fingerprint_version
        AND winner.authority_fingerprint=v_authority_fingerprint
        AND winner.status NOT IN ('FAILED','OBSOLETE','CLEANING')
      ORDER BY winner.created_at_utc,winner.id
      LIMIT 1
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_SAME_AUTHORITY_WINNER_NOT_PROVEN'
          USING ERRCODE='40001',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAY_WORKBENCH_SAME_AUTHORITY_WINNER_NOT_PROVEN',
            'job_id',v_job.id,'candidate_id',v_job.candidate_id,
            'authority_fingerprint_version',v_authority_fingerprint_version,
            'authority_fingerprint',v_authority_fingerprint
          )::text;
      END IF;

      IF v_winner_build.status='COMPLETE' THEN
        v_winner_scope:=NULL;
        SELECT current_scope.*
        INTO v_winner_scope
        FROM public.banking_pay_workbench_session_scope AS current_scope
        JOIN public.banking_pay_workbench_session_candidate_state AS current_state
          ON current_state.session_id=current_scope.session_id
         AND current_state.candidate_id=current_scope.candidate_id
        WHERE current_scope.session_id=v_job.session_id
          AND current_scope.candidate_id=v_job.candidate_id
          AND current_scope.pending_job_id=v_job.id
          AND current_scope.certified_preview_publication_required IS TRUE
          AND current_scope.certified_preview_publication_parity_ok IS TRUE
          AND current_scope.certified_preview_publication_session_version=v_winner_build.session_version
          AND current_scope.certified_preview_publication_source_change_seq=v_winner_build.source_change_seq
          AND current_scope.certified_preview_publication_source_build_run_id=v_winner_build.source_build_run_id
          AND (
            COALESCE(
              (v_settings_json->>'banking_pay_workbench_semantic_ready_publication_v3_enabled')::boolean,
              false
            ) IS NOT TRUE
            OR (
              current_scope.certified_preview_publication_attestation_json->>'attestation_version'
                    ='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
              AND current_scope.certified_preview_publication_attestation_json->>'contract_version'='3'
              AND current_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
                    ='READY_TO_PAY_SEMANTIC_V2'
              AND COALESCE(
                (current_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,
                false
              )
              AND COALESCE(
                (current_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean,
                false
              )
            )
          )
          AND (
            v_required_physical_publication_contract_version=0
            OR (
              current_scope.certified_preview_publication_source_publication_id IS NOT NULL
              AND current_scope.certified_preview_publication_attestation_json->>'source_publication_id'
                    =current_scope.certified_preview_publication_source_publication_id::text
            )
          )
          AND current_state.pending_job_id=v_job.id
          AND current_state.session_version=v_winner_build.session_version
          AND current_state.source_change_seq=v_winner_build.source_change_seq
        FOR UPDATE OF current_scope,current_state;
        v_winner_complete_current_proven:=FOUND;

        IF v_winner_complete_current_proven THEN
          UPDATE public.banking_pay_workbench_jobs AS loser_job
          SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
              economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
              private_cursor_json='{}'::jsonb,private_stage_version=NULL,
              last_error_json=pg_catalog.jsonb_build_object(
                'code','SAME_AUTHORITY_COMPLETE_WINNER_COALESCED',
                'winner_build_id',v_winner_build.id,
                'authority_fingerprint_version',v_authority_fingerprint_version,
                'authority_fingerprint',v_authority_fingerprint
              )
          WHERE loser_job.id=v_job.id AND loser_job.status='QUEUED';

          UPDATE public.banking_pay_workbench_session_scope AS scope_row
          SET status='MATERIALISED',dirty=false,pending_job_id=NULL,error_json=NULL,
              updated_at_utc=clock_timestamp()
          WHERE scope_row.session_id=v_job.session_id
            AND scope_row.candidate_id=v_job.candidate_id
            AND scope_row.pending_job_id=v_job.id;
          UPDATE public.banking_pay_workbench_session_candidate_state AS state_row
          SET status='READY',pending_job_id=NULL,updated_at_utc=clock_timestamp()
          WHERE state_row.session_id=v_job.session_id
            AND state_row.candidate_id=v_job.candidate_id
            AND state_row.pending_job_id=v_job.id;
          UPDATE private.banking_pay_workbench_candidate_scope_registry
          SET current_build_id=v_winner_build.id,updated_at_utc=clock_timestamp()
          WHERE candidate_id=v_job.candidate_id
            AND current_source_change_seq=v_winner_build.source_change_seq
            AND dirty_generation=v_winner_build.captured_candidate_generation;

          RETURN pg_catalog.jsonb_build_object(
            'ok',true,'claimed',false,
            'result_code','SAME_AUTHORITY_COMPLETE_WINNER_COALESCED',
            'job_id',v_job.id,'candidate_id',v_job.candidate_id,
            'winner_build_id',v_winner_build.id,
            'authority_fingerprint_version',v_authority_fingerprint_version,
            'authority_fingerprint',v_authority_fingerprint,
            'current_terminal_authority',true
          );
        END IF;

        -- A legacy V2 owner can be economically complete while lacking the
        -- newly required V3 semantic publication.  The losing V2 job must not
        -- spin forever on the uniqueness fence: terminate it, then let the
        -- canonical orphan-repair/enqueue owner elect the distinct V3
        -- successor in this same transaction.
        IF COALESCE(
             (v_settings_json->>'banking_pay_workbench_semantic_ready_publication_v3_enabled')::boolean,
             false
           )
           AND COALESCE(v_authority_fingerprint_version,0)<3 THEN
          UPDATE public.banking_pay_workbench_jobs AS loser_job
          SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
              economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
              private_cursor_json='{}'::jsonb,private_stage_version=NULL,
              last_error_json=pg_catalog.jsonb_build_object(
                'code','SAME_AUTHORITY_LEGACY_WINNER_V3_REELECTION_REQUIRED',
                'winner_build_id',v_winner_build.id,
                'authority_fingerprint_version',v_authority_fingerprint_version,
                'authority_fingerprint',v_authority_fingerprint
              )
          WHERE loser_job.id=v_job.id AND loser_job.status='QUEUED';

          v_obsolete_repair_result:=public.pay_workbench_repair_orphaned_pending_source_build(
            p_session_id=>v_job.session_id,
            p_candidate_id=>v_job.candidate_id,
            p_limit=>1,
            p_now_utc=>v_database_now,
            p_reason=>'SAME_AUTHORITY_LEGACY_WINNER_V3_REELECTION'
          );

          IF jsonb_typeof(v_obsolete_repair_result) IS DISTINCT FROM 'object'
             OR lower(BTRIM(COALESCE(v_obsolete_repair_result->>'ok','false'))) <> 'true'
             OR COALESCE((v_obsolete_repair_result->>'unresolved_count')::integer,0) <> 0
             OR lower(BTRIM(COALESCE(
                  v_obsolete_repair_result->>'all_state_transitions_proven','false'
                ))) <> 'true' THEN
            RAISE EXCEPTION 'SOURCE_BUILD_SAME_AUTHORITY_V3_SUCCESSOR_NOT_PROVEN'
              USING ERRCODE='40001',DETAIL=pg_catalog.jsonb_build_object(
                'code','SOURCE_BUILD_SAME_AUTHORITY_V3_SUCCESSOR_NOT_PROVEN',
                'job_id',v_job.id,
                'candidate_id',v_job.candidate_id,
                'winner_build_id',v_winner_build.id
              )::text;
          END IF;

          SELECT pending_scope.pending_job_id,
                 EXISTS (
                   SELECT 1
                   FROM public.banking_pay_workbench_jobs AS successor_job
                   JOIN public.banking_pay_workbench_session_candidate_state AS successor_state
                     ON successor_state.session_id=successor_job.session_id
                    AND successor_state.candidate_id=successor_job.candidate_id
                   WHERE successor_job.id=pending_scope.pending_job_id
                     AND successor_job.session_id=v_job.session_id
                     AND successor_job.candidate_id=v_job.candidate_id
                     AND successor_job.job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
                     AND successor_job.status IN ('QUEUED','RUNNING')
                     AND COALESCE(
                       NULLIF(successor_job.payload_json->>'authority_fingerprint_version','')::integer,
                       0
                     )>=3
                     AND successor_state.status='PENDING'
                     AND successor_state.pending_job_id=successor_job.id
                 )
          INTO v_obsolete_successor_job_id,
               v_obsolete_active_successor_proven
          FROM public.banking_pay_workbench_session_scope AS pending_scope
          WHERE pending_scope.session_id=v_job.session_id
            AND pending_scope.candidate_id=v_job.candidate_id;

          IF COALESCE(v_obsolete_active_successor_proven,false) IS NOT TRUE THEN
            RAISE EXCEPTION 'SOURCE_BUILD_SAME_AUTHORITY_V3_SUCCESSOR_NOT_PROVEN'
              USING ERRCODE='40001',DETAIL=pg_catalog.jsonb_build_object(
                'code','SOURCE_BUILD_SAME_AUTHORITY_V3_SUCCESSOR_NOT_PROVEN',
                'job_id',v_job.id,
                'candidate_id',v_job.candidate_id,
                'successor_job_id',v_obsolete_successor_job_id
              )::text;
          END IF;

          RETURN pg_catalog.jsonb_build_object(
            'ok',true,'claimed',false,
            'result_code','SAME_AUTHORITY_LEGACY_WINNER_V3_REELECTED',
            'job_id',v_job.id,'candidate_id',v_job.candidate_id,
            'winner_build_id',v_winner_build.id,
            'successor_resolution',pg_catalog.jsonb_build_object(
              'required',true,'proven',true,
              'successor_created_or_reused',true,
              'successor_job_id',v_obsolete_successor_job_id
            )
          );
        END IF;

        RAISE EXCEPTION 'PAY_WORKBENCH_SAME_AUTHORITY_COMPLETE_WINNER_NOT_CURRENT'
          USING ERRCODE='40001',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAY_WORKBENCH_SAME_AUTHORITY_COMPLETE_WINNER_NOT_CURRENT',
            'job_id',v_job.id,'winner_build_id',v_winner_build.id
          )::text;
      END IF;

      SELECT winner_job.id INTO v_winner_active_job_id
      FROM public.banking_pay_workbench_jobs AS winner_job
      WHERE winner_job.economic_build_id=v_winner_build.id
        AND winner_job.status IN ('QUEUED','RUNNING')
      ORDER BY CASE WHEN winner_job.status='RUNNING' THEN 0 ELSE 1 END,
               winner_job.run_at_utc,winner_job.created_at_utc,winner_job.id
      LIMIT 1
      FOR UPDATE;
      IF v_winner_active_job_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_SAME_AUTHORITY_ACTIVE_WINNER_NOT_PROVEN'
          USING ERRCODE='40001',DETAIL=pg_catalog.jsonb_build_object(
            'code','PAY_WORKBENCH_SAME_AUTHORITY_ACTIVE_WINNER_NOT_PROVEN',
            'job_id',v_job.id,'winner_build_id',v_winner_build.id
          )::text;
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS loser_job
      SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp(),
          economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
          private_cursor_json='{}'::jsonb,private_stage_version=NULL,
          last_error_json=pg_catalog.jsonb_build_object(
            'code','SAME_AUTHORITY_OWNER_COALESCED',
            'winner_build_id',v_winner_build.id,
            'winner_job_id',v_winner_active_job_id,
            'authority_fingerprint_version',v_authority_fingerprint_version,
            'authority_fingerprint',v_authority_fingerprint
          )
      WHERE loser_job.id=v_job.id AND loser_job.status='QUEUED';

      UPDATE public.banking_pay_workbench_session_scope AS scope_row
      SET pending_job_id=v_winner_active_job_id,updated_at_utc=clock_timestamp()
      WHERE scope_row.session_id=v_job.session_id
        AND scope_row.candidate_id=v_job.candidate_id
        AND scope_row.pending_job_id=v_job.id;
      UPDATE public.banking_pay_workbench_session_candidate_state AS state_row
      SET pending_job_id=v_winner_active_job_id,updated_at_utc=clock_timestamp()
      WHERE state_row.session_id=v_job.session_id
        AND state_row.candidate_id=v_job.candidate_id
        AND state_row.pending_job_id=v_job.id;
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET current_build_id=v_winner_build.id,updated_at_utc=clock_timestamp()
      WHERE candidate_id=v_job.candidate_id;

      RETURN pg_catalog.jsonb_build_object(
        'ok',true,'claimed',false,'result_code','SAME_AUTHORITY_OWNER_COALESCED',
        'job_id',v_job.id,'candidate_id',v_job.candidate_id,
        'winner_build_id',v_winner_build.id,'winner_job_id',v_winner_active_job_id,
        'authority_fingerprint_version',v_authority_fingerprint_version,
        'authority_fingerprint',v_authority_fingerprint
      );
    END;
    UPDATE private.banking_pay_workbench_candidate_scope_registry
    SET current_build_id=v_build_id,
        initialisation_status=CASE WHEN v_is_bootstrap THEN 'DISCOVERING' ELSE initialisation_status END,
        bootstrap_id=CASE WHEN v_is_bootstrap THEN v_bootstrap_id ELSE bootstrap_id END,
        bootstrap_stream=CASE WHEN v_is_bootstrap THEN 'TIMESHEETS_TSFIN' ELSE bootstrap_stream END,
        bootstrap_cursor_json=CASE WHEN v_is_bootstrap THEN v_cursor_json ELSE bootstrap_cursor_json END,
        bootstrap_rows_seen=CASE WHEN v_is_bootstrap THEN 0 ELSE bootstrap_rows_seen END,
        bootstrap_timesheets_registered=CASE WHEN v_is_bootstrap THEN 0 ELSE bootstrap_timesheets_registered END,
        bootstrap_captured_generation=CASE WHEN v_is_bootstrap THEN v_captured_generation ELSE bootstrap_captured_generation END,
        bootstrap_captured_source_change_seq=CASE WHEN v_is_bootstrap THEN v_source_change_seq ELSE bootstrap_captured_source_change_seq END,
        updated_at_utc=clock_timestamp()
    WHERE candidate_id=v_job.candidate_id;
    v_stage := CASE WHEN v_is_bootstrap THEN 'BOOTSTRAP_DISCOVERY' ELSE 'PREPARE_SCOPE' END;
    v_cursor_kind := CASE WHEN v_is_bootstrap THEN 'BOOTSTRAP_DISCOVERY' ELSE 'SCOPE_SELECT' END;
  ELSE
    v_build_id := v_job.economic_build_id;
    v_stage := v_job.private_stage;
    v_cursor_kind := v_job.private_cursor_kind;
    v_cursor_json := v_job.private_cursor_json;
    SELECT build_row.* INTO v_build
    FROM private.banking_pay_workbench_economic_builds AS build_row
    WHERE build_row.id=v_build_id AND build_row.candidate_id=v_job.candidate_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_BUILD_MISMATCH'
        USING ERRCODE='40001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_ATTEMPT_BUILD_MISMATCH','job_id',v_job.id,'build_id',v_build_id
        )::text;
    END IF;
    IF v_registry.current_build_id IS DISTINCT FROM v_build_id
       OR v_build.captured_candidate_generation IS DISTINCT FROM v_registry.dirty_generation
       OR v_build.source_change_seq IS DISTINCT FROM v_registry.current_source_change_seq THEN
      UPDATE private.banking_pay_workbench_economic_builds
      SET status='OBSOLETE',obsolete_at_utc=clock_timestamp(),
          failure_json=jsonb_build_object('code','ATTEMPT_GENERATION_OBSOLETE'),
          updated_at_utc=clock_timestamp()
      WHERE id=v_build_id AND status NOT IN ('COMPLETE','FAILED','OBSOLETE');
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET current_build_id=NULL,updated_at_utc=clock_timestamp()
      WHERE candidate_id=v_job.candidate_id AND current_build_id=v_build_id;
      v_obsolete_repair_result:=public.pay_workbench_repair_orphaned_pending_source_build(
        p_session_id=>v_job.session_id,
        p_candidate_id=>v_job.candidate_id,
        p_limit=>1,
        p_now_utc=>v_database_now,
        p_reason=>'ATTEMPT_GENERATION_OBSOLETE_SUCCESSOR'
      );

      IF jsonb_typeof(v_obsolete_repair_result) IS DISTINCT FROM 'object'
         OR lower(BTRIM(COALESCE(v_obsolete_repair_result->>'ok','false'))) <> 'true' THEN
        RAISE EXCEPTION 'SOURCE_BUILD_OBSOLETE_SUCCESSOR_NOT_PROVEN'
          USING ERRCODE='40001',DETAIL=jsonb_build_object(
            'code','SOURCE_BUILD_OBSOLETE_SUCCESSOR_NOT_PROVEN',
            'job_id',v_job.id,
            'candidate_id',v_job.candidate_id,
            'repair_result_code',v_obsolete_repair_result->>'repair_code'
          )::text;
      END IF;

      SELECT pending_scope.pending_job_id,
             EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_jobs AS successor_job
               JOIN public.banking_pay_workbench_session_candidate_state AS successor_state
                 ON successor_state.session_id=successor_job.session_id
                AND successor_state.candidate_id=successor_job.candidate_id
               WHERE successor_job.id=pending_scope.pending_job_id
                 AND successor_job.session_id=v_job.session_id
                 AND successor_job.candidate_id=v_job.candidate_id
                 AND successor_job.job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
                 AND successor_job.status IN ('QUEUED','RUNNING')
                 AND CASE
                       WHEN COALESCE(successor_job.payload_json->>'source_change_seq','') ~ '^\d+$'
                         THEN (successor_job.payload_json->>'source_change_seq')::bigint
                       ELSE NULL::bigint
                     END=successor_registry.current_source_change_seq
                 AND COALESCE(
                       successor_job.scope_change_generation,
                       CASE
                         WHEN COALESCE(successor_job.payload_json->>'scope_change_generation','') ~ '^\d+$'
                           THEN (successor_job.payload_json->>'scope_change_generation')::bigint
                         ELSE NULL::bigint
                       END,
                       successor_registry.dirty_generation
                     )=successor_registry.dirty_generation
                 AND successor_state.status='PENDING'
                 AND successor_state.pending_job_id=successor_job.id
                 AND successor_state.source_change_seq=successor_registry.current_source_change_seq
                 AND successor_state.session_version=v_session.version
             ),
             (
               pending_scope.status IN ('READY','MATERIALISED','MATERIALIZED','SOURCE_EMPTY')
               AND COALESCE(pending_scope.dirty,false) IS NOT TRUE
               AND pending_scope.pending_job_id IS NULL
               AND COALESCE(pending_scope.certified_preview_publication_required,false) IS TRUE
               AND COALESCE(pending_scope.certified_preview_publication_parity_ok,false) IS TRUE
               AND pending_scope.certified_preview_publication_session_version=v_session.version
               AND pending_scope.certified_preview_publication_source_change_seq=
                   successor_registry.current_source_change_seq
             )
      INTO v_obsolete_successor_job_id,
           v_obsolete_active_successor_proven,
           v_obsolete_terminal_current_proven
      FROM public.banking_pay_workbench_session_scope AS pending_scope
      JOIN private.banking_pay_workbench_candidate_scope_registry AS successor_registry
        ON successor_registry.candidate_id=pending_scope.candidate_id
      WHERE pending_scope.session_id=v_job.session_id
        AND pending_scope.candidate_id=v_job.candidate_id;

      IF COALESCE(v_obsolete_active_successor_proven,false) IS NOT TRUE
         AND COALESCE(v_obsolete_terminal_current_proven,false) IS NOT TRUE THEN
        v_obsolete_successor_wait_count:=CASE
          WHEN COALESCE(v_job.payload_json->>'obsolete_successor_wait_count','')~'^[0-9]{1,9}$'
            THEN LEAST((v_job.payload_json->>'obsolete_successor_wait_count')::integer,1000000)
          ELSE 0
        END;
        v_obsolete_successor_wait_seconds:=LEAST(30,GREATEST(2,
          power(2,LEAST(v_obsolete_successor_wait_count+1,5))::integer
        ));
        v_obsolete_successor_retry_at_utc:=pg_catalog.clock_timestamp()
          +pg_catalog.make_interval(secs=>v_obsolete_successor_wait_seconds);

        UPDATE public.banking_pay_workbench_jobs AS waiting_job
        SET run_at_utc=v_obsolete_successor_retry_at_utc,
            payload_json=(COALESCE(waiting_job.payload_json,'{}'::jsonb)
              -'obsolete_successor_retry_at_utc')||pg_catalog.jsonb_build_object(
                'obsolete_successor_wait_contract_version',
                  'SOURCE_BUILD_OBSOLETE_SUCCESSOR_WAIT_V1',
                'obsolete_successor_wait_count',v_obsolete_successor_wait_count+1,
                'obsolete_successor_wait_started_at_utc',COALESCE(
                  waiting_job.payload_json->>'obsolete_successor_wait_started_at_utc',
                  pg_catalog.clock_timestamp()::text
                ),
                'obsolete_successor_retry_at_utc',v_obsolete_successor_retry_at_utc,
                'obsolete_successor_expected_source_change_seq',
                  v_registry.current_source_change_seq,
                'obsolete_successor_expected_dirty_generation',v_registry.dirty_generation,
                'obsolete_successor_last_repair_code',
                  v_obsolete_repair_result->>'repair_code',
                'obsolete_successor_repair_unresolved_count',COALESCE(
                  CASE WHEN COALESCE(v_obsolete_repair_result->>'unresolved_count','')
                    ~'^[0-9]{1,9}$'
                    THEN (v_obsolete_repair_result->>'unresolved_count')::integer END,0
                ),
                'obsolete_successor_repair_transitions_proven',
                  pg_catalog.lower(pg_catalog.btrim(COALESCE(
                    v_obsolete_repair_result->>'all_state_transitions_proven','false'
                  ))) IN ('true','t','1','yes','y','on')
              ),
            updated_at_utc=pg_catalog.clock_timestamp()
        WHERE waiting_job.id=v_job.id AND waiting_job.status='QUEUED';

        RETURN pg_catalog.jsonb_build_object(
          'ok',true,'claimed',false,
          'result_code','SOURCE_BUILD_OBSOLETE_SUCCESSOR_PENDING',
          'job_id',v_job.id,'candidate_id',v_job.candidate_id,
          'retry_at_utc',v_obsolete_successor_retry_at_utc,
          'repair_result_code',v_obsolete_repair_result->>'repair_code',
          'expected_source_change_seq',v_registry.current_source_change_seq,
          'expected_generation',v_registry.dirty_generation
        );
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS obsolete_job
      SET status='SUCCEEDED',completed_at_utc=pg_catalog.clock_timestamp(),
          economic_build_id=NULL,private_stage=NULL,private_cursor_kind=NULL,
          private_cursor_json='{}'::jsonb,private_stage_version=NULL,
          payload_json=COALESCE(obsolete_job.payload_json,'{}'::jsonb)
            -'obsolete_successor_wait_contract_version'
            -'obsolete_successor_wait_count'
            -'obsolete_successor_wait_started_at_utc'
            -'obsolete_successor_retry_at_utc'
            -'obsolete_successor_expected_source_change_seq'
            -'obsolete_successor_expected_dirty_generation'
            -'obsolete_successor_last_repair_code'
            -'obsolete_successor_repair_unresolved_count'
            -'obsolete_successor_repair_transitions_proven',
          last_error_json=pg_catalog.jsonb_build_object('code','ATTEMPT_GENERATION_OBSOLETE'),
          updated_at_utc=pg_catalog.clock_timestamp()
      WHERE obsolete_job.id=v_job.id AND obsolete_job.status='QUEUED';

      RETURN jsonb_build_object('ok',true,'claimed',false,
        'result_code','ATTEMPT_GENERATION_OBSOLETE',
        'successor_resolution',jsonb_build_object(
          'required',true,
          'proven',true,
          'successor_created_or_reused',v_obsolete_active_successor_proven,
          'successor_job_id',v_obsolete_successor_job_id,
          'current_terminal_authority',v_obsolete_terminal_current_proven,
          'source_change_seq',v_registry.current_source_change_seq,
          'generation',v_registry.dirty_generation
        ));
    END IF;
    v_captured_generation:=v_build.captured_candidate_generation;
    v_source_change_seq:=v_build.source_change_seq;
    BEGIN
      v_execution_profile_version := COALESCE(
        NULLIF(v_build.attestation_json->>'execution_profile_version','')::integer,
        1
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_INVALID'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_EXECUTION_PROFILE_INVALID','build_id',v_build_id
        )::text;
    END;
    IF v_execution_profile_version NOT IN (1,2)
       OR EXISTS (
         SELECT 1
         FROM private.banking_pay_workbench_stage_attempts AS prior_attempt
         WHERE prior_attempt.build_id=v_build_id
           AND prior_attempt.execution_profile_version IS DISTINCT FROM v_execution_profile_version
       ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_EXECUTION_PROFILE_CONFLICT'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_EXECUTION_PROFILE_CONFLICT',
          'build_id',v_build_id,
          'execution_profile_version',v_execution_profile_version
        )::text;
    END IF;
    BEGIN
      v_reconciliation_optimization_version:=COALESCE(
        NULLIF(v_build.attestation_json->>'reconciliation_optimization_version','')::integer,0
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_INVALID'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_INVALID','build_id',v_build_id
        )::text;
    END;
    IF v_reconciliation_optimization_version NOT IN (0,1)
       OR (v_execution_profile_version=1 AND v_reconciliation_optimization_version<>0) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_OPTIMIZATION_CONFLICT'
        USING ERRCODE='P0001';
    END IF;
    UPDATE private.banking_pay_workbench_economic_builds
    SET source_job_id=v_job.id,updated_at_utc=clock_timestamp()
    WHERE id=v_build_id;
  END IF;

  v_attempt_number := COALESCE(v_job.attempt_count,0)+1;
  v_claimed_job_id:=v_job.id;
  UPDATE public.banking_pay_workbench_jobs claimed_job
  SET status='RUNNING',attempt_count=v_attempt_number,
      started_at_utc=COALESCE(claimed_job.started_at_utc,clock_timestamp()),
      updated_at_utc=clock_timestamp(),completed_at_utc=NULL,failed_at_utc=NULL,
      last_error_json=NULL,economic_build_id=v_build_id,private_stage=v_stage,
      private_cursor_kind=v_cursor_kind,private_cursor_json=v_cursor_json,
      private_stage_version=1,
      payload_json=jsonb_strip_nulls((COALESCE(claimed_job.payload_json,'{}'::jsonb)
          -'claim_scan_deferred_reason'-'claim_scan_deferral_count'-'claim_scan_generation'
          -'recovery_scan_deferred_epoch'-'recovery_scan_deferral_count'-'recovery_scan_generation')
        ||jsonb_build_object(
          'claimed_at_utc',clock_timestamp()::text,
          'candidate_serial_key',public._pay_workbench_candidate_serial_key(v_job.candidate_id),
          'candidate_serial_candidate_id',v_job.candidate_id::text,
          'candidate_serial_active_chain_id',COALESCE(
            NULLIF(btrim(COALESCE(claimed_job.payload_json->>'candidate_serial_active_chain_id','')),''),
            NULLIF(btrim(COALESCE(claimed_job.payload_json->>'source_job_id','')),''),
            claimed_job.id::text),
          'candidate_serial_source_job_id',NULLIF(btrim(COALESCE(
            claimed_job.payload_json->>'source_job_id','')),''),
          'candidate_serial_started_at_utc',clock_timestamp()::text,
          'candidate_serial_reason','CANDIDATE_SERIAL_CLAIM_GRANTED'))
  WHERE claimed_job.id=v_claimed_job_id AND claimed_job.status='QUEUED'
    AND claimed_job.run_at_utc<=v_now
    AND COALESCE(claimed_job.attempt_count,0)=v_attempt_number-1
    AND COALESCE(claimed_job.attempt_count,0)<COALESCE(claimed_job.max_attempts,8)
    AND NOT EXISTS (
      SELECT 1 FROM private.banking_pay_workbench_stage_attempts active_attempt
      WHERE active_attempt.job_id=claimed_job.id AND active_attempt.attempt_status='STARTED'
    )
  RETURNING claimed_job.* INTO v_job;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_CLAIM_ADOPTION_FAILED'
      USING ERRCODE='40001',DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_ATTEMPT_CLAIM_ADOPTION_FAILED','job_id',v_claimed_job_id
      )::text;
  END IF;

  v_attempt_started_at := clock_timestamp();
  v_lease_expires := v_attempt_started_at+make_interval(secs=>v_effective_lease);
  INSERT INTO private.banking_pay_workbench_stage_attempts(
    job_id,build_id,candidate_id,private_stage,attempt_number,worker_id,lane_identity,
    captured_candidate_generation,captured_source_change_seq,execution_profile_version,
    started_at_utc,lease_expires_at_utc,created_at_utc,updated_at_utc
  ) VALUES (
    v_job.id,v_build_id,v_job.candidate_id,v_stage,v_attempt_number,v_worker_id,v_lane_identity,
    v_captured_generation,v_source_change_seq,v_execution_profile_version,v_attempt_started_at,v_lease_expires,
    v_attempt_started_at,v_attempt_started_at
  ) RETURNING id,attempt_nonce INTO v_attempt_id,v_attempt_nonce;

  RETURN jsonb_build_object(
    'ok',true,'claimed',true,'job_id',v_job.id,'build_id',v_build_id,
    'candidate_id',v_job.candidate_id,'private_stage',v_stage,
    'attempt_id',v_attempt_id,'attempt_number',v_attempt_number,
    'attempt_nonce',v_attempt_nonce,'attempt_started_at_utc',v_attempt_started_at,
    'lease_expires_at_utc',v_lease_expires,'execution_profile_version',v_execution_profile_version,
    'reconciliation_optimization_version',v_reconciliation_optimization_version
  );
END;
$function$
;

-- ACL for functions NEW in this release: owner-only EXECUTE (repository convention, cf. 22092026_1645),
-- applied in the creating transaction. Replaced functions keep their existing owner and grants (CREATE OR
-- REPLACE preserves them). The authoritative closure for every new and changed object is the generated
-- grants repeatable supabase/repeatable/26092026_0209_banking_pay_stage2_grants_v1.sql (A25, regenerated after A26/A27), which installs last.
REVOKE ALL ON FUNCTION private.pay_batch_source_head_drift_v1(p_pay_batch_id uuid) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.pay_batch_v8_draft_preparation_unfinished_v1(p_pay_batch_id uuid) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION private.weekly_source_entitlement_head_ledger_mark_v1() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public._pay_batch_draft_stale_hint_on_view_v1(p_pay_batch_id uuid, p_page_timesheet_count integer, p_budget_ms integer) FROM PUBLIC, anon, authenticated, service_role;

commit;
